-- Default data
INSERT INTO public.settings (company_name) VALUES ('') ON CONFLICT DO NOTHING;
INSERT INTO public._credentials_key (encryption_key) VALUES (encode(extensions.gen_random_bytes(32), 'hex')) ON CONFLICT DO NOTHING;
INSERT INTO public._encryption_keys (key_name, key_value) VALUES ('credentials', encode(extensions.gen_random_bytes(32), 'hex')) ON CONFLICT DO NOTHING;
INSERT INTO public._internal_secrets (key, value) VALUES ('CRON_SECRET', encode(extensions.gen_random_bytes(32), 'hex')) ON CONFLICT DO NOTHING;
-- 1812: WEBAUTHN_VERIFY_URL is gone. Passkeys are checked in this database
-- (_webauthn_verify_assertion); nothing here names Pental's checker any more,
-- and a row left by an earlier version is removed.
DELETE FROM public._internal_secrets WHERE key = 'WEBAUTHN_VERIFY_URL';
-- 1825: PENTAL_VERIFY_URL is gone the same way. Pental's signatures are
-- checked in this database (_ed25519_verify); no service of Pental's is asked
-- whether a signed call counts, and a row left by an earlier version is removed.
DELETE FROM public._internal_secrets WHERE key = 'PENTAL_VERIFY_URL';
-- NOTE: PROVISION_SECRET is NOT seeded here - rpc_bulk_clean generates it on first connect (bootstrap mode).

-- ════════════════════════════════════════════════════════════
-- ALTER TABLE - safe for existing BYO databases
-- ════════════════════════════════════════════════════════════
-- Defensive: ensure both favicon column variants exist regardless of which
-- schema generation this BYO was first set up on. Older builds used
-- favicon_data (text/data-URL); newer builds favicon_url (storage URL).
-- Some databases were partially migrated and have one but not the other.
-- Adding both as nullable text columns is harmless: queries reading the
-- "wrong" column just see NULL, and GRANTs / functions referencing
-- either column won't error out.
-- Severity WORDING for generated reports: case, weight, text colour, and the
-- colour of a severity word drawn on a coloured chip. Separate from the
-- palette because a firm can want the colour without the shouting. A CREATE
-- TABLE default only reaches a NEW database, so existing ones need this.
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS severity_style jsonb
  DEFAULT '{"case":"upper","bold":true,"colour":"severity"}';

ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS favicon_data text;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS favicon_url text;
-- Light-mode logo variant. logo_url stays the primary/dark logo; this is used
-- only when the portal renders in light mode and falls back to logo_url when
-- empty, so existing tenants are unaffected until they upload one.
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS logo_url_light text;
-- Which logo each OUTPUT surface uses: 'primary' means logo_url, which is the
-- default and reproduces the behaviour these surfaces had before the light
-- variant existed; 'light' means logo_url_light, falling back to logo_url when
-- no light logo has been uploaded.
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS pdf_logo_variant text DEFAULT 'primary';
