ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS feedback_mode text DEFAULT 'portal';
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS google_review_url text;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS loa_visibility text DEFAULT 'internal';
-- Per-type filename patterns for generated documents (invoice, proposal, report, attestation).
-- JSON keyed by type_ext: {invoice_pdf:"{invoice_id} - {client} - Invoice", proposal_docx:"...", ...}
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS filename_templates jsonb;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS show_tester_teams boolean DEFAULT false;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS show_tester_slack boolean DEFAULT false;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS notify_test_started boolean DEFAULT true;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS notify_test_ended boolean DEFAULT true;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS notify_critical_finding boolean DEFAULT true;
