-- Drop any pre-existing policies to avoid conflicts on re-run
DO $drp$ DECLARE _tbl text; _pol record; BEGIN
  FOR _tbl IN SELECT unnest(ARRAY['settings','profiles','clients','assessments','findings','proposals','invoices','kb_entries','meetings','meeting_attendees','tickets','timeline_events','assessment_comments','assessment_files','feedback','contractor_payments','email_notifications','payment_events','qa_comments','login_codes','_credentials_key','_encryption_keys','_internal_secrets']) LOOP
    FOR _pol IN SELECT policyname FROM pg_policies WHERE tablename = _tbl LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', _pol.policyname, _tbl);
    END LOOP;
  END LOOP;
END $drp$;

-- SETTINGS
CREATE POLICY settings_anon_read ON public.settings FOR SELECT TO anon USING (true);
CREATE POLICY settings_auth_read ON public.settings FOR SELECT TO authenticated USING (true);
CREATE POLICY settings_admin_insert ON public.settings FOR INSERT TO authenticated WITH CHECK (public.current_user_role() = 'admin');
CREATE POLICY settings_admin_update ON public.settings FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin','senior')) WITH CHECK (true);
CREATE POLICY settings_admin_delete ON public.settings FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');

-- PROFILES
-- WHO YOU CAN SEE. This was USING (true): every authenticated user could read
-- every profile row in the tenant, so a client at one organisation could read
-- another organisation's users and the firm's entire staff list with emails.
--
-- NO `mfa_is_fresh()` HERE, DELIBERATELY. The sign-in flow reads profiles BY
-- EMAIL to work out which MFA methods to offer, which happens BEFORE MFA is
-- fresh by definition. Adding the freshness test to this policy locks
-- everybody out of their own login. This policy decides WHICH ROWS, not
-- whether the session is stepped up — the sensitive columns are withheld by
-- the column grant regardless.
CREATE POLICY profiles_auth_read ON public.profiles FOR SELECT TO authenticated
  USING (
    -- Yourself, always, or you cannot sign in or load your own settings.
    auth_user_id = auth.uid()
    -- Staff already see every client and every engagement; hiding colleagues
    -- from them would break the assignment pickers and gain nothing.
    OR public.is_staff()
    -- Your own organisation, and for a CONTRACTOR the clients they work with.
    -- One helper answers both, and it is the same one clients_read uses, so
    -- this cannot drift from what "can see that client" means elsewhere (1943:
    -- can_see_client, the clients they brought and those of their engagements).
    OR (client_id IS NOT NULL AND public.can_see_client(client_id))
    -- The people attached to an engagement you can reach: the lead tester and
    -- the QA reviewer. A client legitimately needs the name of the tester on
    -- their own work, and that is the read the portal actually makes.
    OR EXISTS (
      SELECT 1 FROM public.assessments a
       WHERE (a.lead_id = public.profiles.id OR a.qa_assignee = public.profiles.id)
         AND public.can_access_assessment(a.id))
    -- 1943: a contractor's own team, who share its engagements.
    OR (contractor_team_id IS NOT NULL AND contractor_team_id = public.current_contractor_team_id())
  );
CREATE POLICY profiles_manage_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (public.can_manage());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (public.can_manage() OR (auth_user_id = auth.uid() AND active = true)) WITH CHECK (true);
CREATE POLICY profiles_manage_delete ON public.profiles FOR DELETE TO authenticated USING (public.can_manage());
-- 1841: these four writes ask for the second factor too, set further down
-- (once mfa_is_fresh() exists): "THE SECOND FACTOR FOR PEOPLE AND SETTINGS".

-- CLIENTS
CREATE POLICY clients_read ON public.clients FOR SELECT TO authenticated USING (public.is_staff() OR (public.current_user_role() = 'contractor' AND (created_by = public.current_profile_id() OR id IN (SELECT client_id FROM public.assessments WHERE lead_id = public.current_profile_id()))) OR (public.current_user_role() = 'client' AND id = public.current_user_client_id()));
CREATE POLICY clients_insert ON public.clients FOR INSERT TO authenticated WITH CHECK (public.can_write());
CREATE POLICY clients_update ON public.clients FOR UPDATE TO authenticated USING (public.can_write()) WITH CHECK (true);
CREATE POLICY clients_delete ON public.clients FOR DELETE TO authenticated USING (public.can_manage());

-- ASSESSMENTS
CREATE POLICY assessments_read ON public.assessments FOR SELECT TO authenticated USING (public.is_staff() OR (public.current_user_role() = 'contractor' AND lead_id = public.current_profile_id()) OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id()));
CREATE POLICY assessments_insert ON public.assessments FOR INSERT TO authenticated WITH CHECK (public.can_write());
CREATE POLICY assessments_update ON public.assessments FOR UPDATE TO authenticated USING (public.is_staff() OR (public.current_user_role() = 'contractor' AND lead_id = public.current_profile_id())) WITH CHECK (true);
CREATE POLICY assessments_delete ON public.assessments FOR DELETE TO authenticated USING (public.can_manage());

-- FINDINGS
-- THE CLAUSE THAT MAKES A NULL ASSESSMENT SURVIVABLE (649). With
-- `assessment_id` NULL the existing client arm evaluates to NULL, so the row is
-- invisible — fail-closed, which is the right direction but means scan findings
-- would simply vanish for a customer once the NOT NULL goes.
--
-- The new arm matches on the finding's OWN client, and only for rows with no
-- assessment: it cannot widen anything that exists today, because every finding
-- currently has one. `client_visible` is still required — a null assessment is
-- not a way around the release rule.
CREATE POLICY findings_read ON public.findings FOR SELECT TO authenticated USING (public.is_staff() OR (public.current_user_role() = 'contractor' AND assessment_id IN (SELECT id FROM public.assessments WHERE lead_id = public.current_profile_id())) OR (public.current_user_role() = 'client' AND client_visible = true AND assessment_id IN (SELECT id FROM public.assessments WHERE client_id = public.current_user_client_id())) OR (public.current_user_role() = 'client' AND client_visible = true AND assessment_id IS NULL AND client_id IS NOT NULL AND client_id = public.current_user_client_id()));
CREATE POLICY findings_insert ON public.findings FOR INSERT TO authenticated WITH CHECK (public.can_write());
CREATE POLICY findings_update ON public.findings FOR UPDATE TO authenticated USING (public.is_staff() OR public.current_user_role() = 'contractor') WITH CHECK (true);
CREATE POLICY findings_delete ON public.findings FOR DELETE TO authenticated USING (public.can_manage());

-- PROPOSALS
CREATE POLICY proposals_read ON public.proposals FOR SELECT TO authenticated USING (public.current_user_role() IN ('admin','senior','sales','contractor') OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id()));
CREATE POLICY proposals_insert ON public.proposals FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin','senior','contractor'));
CREATE POLICY proposals_update ON public.proposals FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin','senior','contractor') OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id())) WITH CHECK (true);
CREATE POLICY proposals_delete ON public.proposals FOR DELETE TO authenticated USING (public.can_manage());

-- INVOICES
CREATE POLICY invoices_read ON public.invoices FOR SELECT TO authenticated USING (public.current_user_role() IN ('admin','senior','sales') OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id()));
CREATE POLICY invoices_insert ON public.invoices FOR INSERT TO authenticated WITH CHECK (public.can_manage());
CREATE POLICY invoices_update ON public.invoices FOR UPDATE TO authenticated USING (public.can_manage()) WITH CHECK (true);
CREATE POLICY invoices_delete ON public.invoices FOR DELETE TO authenticated USING (public.can_manage());

