CREATE POLICY kb_read ON public.kb_entries FOR SELECT TO authenticated USING (public.current_user_role() NOT IN ('client', 'none'));
CREATE POLICY kb_insert ON public.kb_entries FOR INSERT TO authenticated WITH CHECK (public.can_write());
CREATE POLICY kb_update ON public.kb_entries FOR UPDATE TO authenticated USING (public.can_write()) WITH CHECK (true);
CREATE POLICY kb_delete ON public.kb_entries FOR DELETE TO authenticated USING (public.can_manage());

-- MEETINGS + ATTENDEES
CREATE POLICY meetings_read ON public.meetings FOR SELECT TO authenticated USING (public.current_user_role() NOT IN ('client', 'none'));
CREATE POLICY meetings_insert ON public.meetings FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin','senior','sales','standard'));
CREATE POLICY meetings_update ON public.meetings FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin','senior','sales','standard')) WITH CHECK (true);
CREATE POLICY meetings_delete ON public.meetings FOR DELETE TO authenticated USING (public.can_manage());
