CREATE POLICY attendees_write ON public.meeting_attendees FOR ALL TO authenticated USING (public.current_user_role() IN ('admin','senior','sales','standard')) WITH CHECK (true);

-- TICKETS
CREATE POLICY tickets_read ON public.tickets FOR SELECT TO authenticated USING (true);
CREATE POLICY tickets_insert ON public.tickets FOR INSERT TO authenticated WITH CHECK (public.can_write());
CREATE POLICY tickets_update ON public.tickets FOR UPDATE TO authenticated USING (public.can_write()) WITH CHECK (true);
CREATE POLICY tickets_delete ON public.tickets FOR DELETE TO authenticated USING (public.can_manage());

-- TIMELINE_EVENTS
CREATE POLICY timeline_read ON public.timeline_events FOR SELECT TO authenticated USING (true);
CREATE POLICY timeline_insert ON public.timeline_events FOR INSERT TO authenticated WITH CHECK (public.current_user_role() != 'client');
CREATE POLICY timeline_update ON public.timeline_events FOR UPDATE TO authenticated USING (public.current_user_role() != 'client') WITH CHECK (true);
CREATE POLICY timeline_delete ON public.timeline_events FOR DELETE TO authenticated USING (public.can_manage());

-- ASSESSMENT_COMMENTS
CREATE POLICY comments_read ON public.assessment_comments FOR SELECT TO authenticated USING (true);
CREATE POLICY comments_insert ON public.assessment_comments FOR INSERT TO authenticated WITH CHECK (public.current_user_role() != 'client' OR assessment_id IN (SELECT id FROM public.assessments WHERE client_id = public.current_user_client_id()));
CREATE POLICY comments_update ON public.assessment_comments FOR UPDATE TO authenticated USING (public.can_manage() OR user_id = public.current_profile_id()) WITH CHECK (true);
CREATE POLICY comments_delete ON public.assessment_comments FOR DELETE TO authenticated USING (public.can_manage() OR user_id = public.current_profile_id());

-- ASSESSMENT_FILES
-- A CLIENT READS FILES ON THEIR OWN ENGAGEMENTS AND NO OTHERS (570). The rule
-- used to be "client_visible, from anyone", which let a portal user list the
-- name, size and uploader of every file any firm had ever shared with any
-- customer. Storage was never open — `can_access_assessment_file` has always
-- scoped the download by assessment — so this was a metadata leak rather than
-- a way to fetch somebody else's report, but the two layers now say the same
-- thing. The assessment test is the same subquery the comments policy uses.
CREATE POLICY files_read ON public.assessment_files FOR SELECT TO authenticated USING (
  public.current_user_role() != 'client'
  OR (
    (client_visible = true OR uploaded_by_client = true)
    AND EXISTS (
      SELECT 1 FROM public.assessments a
       WHERE a.id = assessment_files.assessment_id
         AND a.client_id = (SELECT p.client_id FROM public.profiles p
                             WHERE p.auth_user_id = auth.uid() AND p.active = true LIMIT 1)
    )
  )
);
CREATE POLICY files_insert ON public.assessment_files FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY files_update ON public.assessment_files FOR UPDATE TO authenticated USING (public.current_user_role() != 'client') WITH CHECK (true);
CREATE POLICY files_delete ON public.assessment_files FOR DELETE TO authenticated USING (public.can_manage() OR uploaded_by = public.current_profile_id());


-- FEEDBACK
CREATE POLICY feedback_read ON public.feedback FOR SELECT TO authenticated USING (public.is_staff() OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id()));
CREATE POLICY feedback_insert ON public.feedback FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY feedback_update ON public.feedback FOR UPDATE TO authenticated USING (public.can_manage()) WITH CHECK (true);
CREATE POLICY feedback_delete ON public.feedback FOR DELETE TO authenticated USING (public.can_manage());

