CREATE POLICY conpay_insert ON public.contractor_payments FOR INSERT TO authenticated WITH CHECK (public.can_manage());
CREATE POLICY conpay_update ON public.contractor_payments FOR UPDATE TO authenticated USING (public.can_manage()) WITH CHECK (true);
CREATE POLICY conpay_delete ON public.contractor_payments FOR DELETE TO authenticated USING (public.can_manage());

