CREATE POLICY email_notif_read ON public.email_notifications FOR SELECT TO authenticated USING (public.is_staff());
CREATE POLICY email_notif_write ON public.email_notifications FOR ALL TO authenticated USING (public.can_write()) WITH CHECK (true);

-- PAYMENT_EVENTS
CREATE POLICY payment_events_all ON public.payment_events FOR ALL TO authenticated USING (public.can_manage()) WITH CHECK (true);

-- QA_COMMENTS
CREATE POLICY qa_read ON public.qa_comments FOR SELECT TO authenticated USING (public.current_user_role() != 'client');
CREATE POLICY qa_insert ON public.qa_comments FOR INSERT TO authenticated WITH CHECK (public.can_write());
CREATE POLICY qa_update ON public.qa_comments FOR UPDATE TO authenticated USING (public.can_manage() OR user_id = public.current_profile_id()) WITH CHECK (true);
CREATE POLICY qa_delete ON public.qa_comments FOR DELETE TO authenticated USING (public.can_manage() OR user_id = public.current_profile_id());

-- Prevent role escalation via self-update
CREATE OR REPLACE FUNCTION public._protect_profile_columns() RETURNS trigger AS $$
DECLARE v_caller_role text;
BEGIN
  -- Allow SECURITY DEFINER RPCs that set this transaction-local flag
  IF current_setting('pental.bypass_protect', true) = 'true' THEN RETURN NEW; END IF;
  IF auth.uid() IS NULL THEN
    IF current_setting('role', true) = 'service_role' THEN RETURN NEW; END IF;
    IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'Cannot change role'; END IF;
    IF NEW.email IS DISTINCT FROM OLD.email THEN RAISE EXCEPTION 'Cannot change email'; END IF;
    IF NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN RAISE EXCEPTION 'Cannot change auth binding'; END IF;
    IF NEW.active IS DISTINCT FROM OLD.active THEN RAISE EXCEPTION 'Cannot change active status'; END IF;
    IF NEW.client_id IS DISTINCT FROM OLD.client_id THEN RAISE EXCEPTION 'Cannot change client assignment'; END IF;
    IF NEW.totp_secret IS DISTINCT FROM OLD.totp_secret THEN RAISE EXCEPTION 'Cannot change MFA config'; END IF;
    IF NEW.contractor_team_id IS DISTINCT FROM OLD.contractor_team_id THEN RAISE EXCEPTION 'Cannot change team'; END IF;   -- 1943
    RETURN NEW;
  END IF;
  IF current_setting('role', true) = 'service_role' THEN RETURN NEW; END IF;
  SELECT role INTO v_caller_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_caller_role IN ('admin', 'senior') THEN RETURN NEW; END IF;
  IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'Cannot change role'; END IF;
  IF NEW.email IS DISTINCT FROM OLD.email THEN RAISE EXCEPTION 'Cannot change email'; END IF;
  IF NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN RAISE EXCEPTION 'Cannot change auth binding'; END IF;
  IF NEW.active IS DISTINCT FROM OLD.active THEN RAISE EXCEPTION 'Cannot change active status'; END IF;
  IF NEW.client_id IS DISTINCT FROM OLD.client_id THEN RAISE EXCEPTION 'Cannot change client assignment'; END IF;
  IF NEW.totp_secret IS DISTINCT FROM OLD.totp_secret THEN RAISE EXCEPTION 'Cannot change MFA config'; END IF;
  -- 1943: a contractor's team is the firm's choice; joining another team would
  -- open that team's engagements.
  IF NEW.contractor_team_id IS DISTINCT FROM OLD.contractor_team_id THEN RAISE EXCEPTION 'Cannot change team'; END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

DROP TRIGGER IF EXISTS protect_profile_columns ON public.profiles;
CREATE TRIGGER protect_profile_columns BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public._protect_profile_columns();

-- 1798: WHAT A NOTICE PRINTS IS TEXT, SO IT IS ESCAPED. Names, addresses, a
-- device string and a typed reason were put into these HTML bodies as they
-- came, and now that the outbox sends them, a name like `<a href=...>Verify
-- here</a>` arrives as a working link in an email from the firm's own mailbox.
-- The same five replacements `_email_fill` makes, ampersand first.
CREATE OR REPLACE FUNCTION public._html_esc(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT replace(replace(replace(replace(replace(COALESCE(p, ''),
    '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;')
$$;
REVOKE EXECUTE ON FUNCTION public._html_esc(text) FROM PUBLIC, anon, authenticated;

-- Security notification trigger: notify admins when a profile is created or has
-- a sensitive column change (role, active). Runs AFTER the row is committed so
-- enqueue never blocks the original write. Toggle keys on the settings row
-- control whether the email actually goes out.
CREATE OR REPLACE FUNCTION public._notify_profile_change() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.active IS NOT FALSE THEN
      PERFORM public._queue_security_notif(
        'notify_user_created',
        'New user added to your portal',
        format(
          '<p>A new portal user has been added.</p>'
          '<table style="border-collapse:collapse;margin:12px 0">'
          '<tr><td style="padding:4px 12px;color:#666">Email</td><td style="padding:4px 12px"><strong>%s</strong></td></tr>'
          '<tr><td style="padding:4px 12px;color:#666">Name</td><td style="padding:4px 12px">%s</td></tr>'
          '<tr><td style="padding:4px 12px;color:#666">Role</td><td style="padding:4px 12px">%s</td></tr>'
          '</table>'
          '<p>If you did not expect this, review your user list in <strong>Settings &rarr; Users</strong>.</p>',
          public._html_esc(NEW.email), public._html_esc(NEW.name), public._html_esc(NEW.role)
        ),
        NEW.id
      );
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.role IS DISTINCT FROM OLD.role THEN
      PERFORM public._queue_security_notif(
        'notify_role_changed',
        format('Role changed for %s', COALESCE(NEW.email, 'a user')),
        format(
          '<p>A user''s role has been changed.</p>'
          '<table style="border-collapse:collapse;margin:12px 0">'
          '<tr><td style="padding:4px 12px;color:#666">User</td><td style="padding:4px 12px"><strong>%s</strong></td></tr>'
          '<tr><td style="padding:4px 12px;color:#666">Previous role</td><td style="padding:4px 12px">%s</td></tr>'
          '<tr><td style="padding:4px 12px;color:#666">New role</td><td style="padding:4px 12px"><strong>%s</strong></td></tr>'
          '</table>'
          '<p>If this change was not expected, review user permissions immediately.</p>',
          public._html_esc(NEW.email), public._html_esc(OLD.role), public._html_esc(NEW.role)
        ),
        NEW.id
      );
    END IF;
    IF OLD.totp_secret IS NOT NULL AND OLD.totp_secret != '' AND (NEW.totp_secret IS NULL OR NEW.totp_secret = '') THEN
      PERFORM public._queue_security_notif(
        'notify_mfa_changed',
        'MFA authenticator removed',
        format(
          '<p>The authenticator app for <strong>%s</strong> has been removed.</p>'
          '<p>Next sign-in will require setting up a new authenticator. If this was not requested, contact your administrator.</p>',
          public._html_esc(NEW.email)
        ),
        NEW.id,
        NEW.email
      );
    END IF;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Profile notification trigger error: %', SQLERRM;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

DROP TRIGGER IF EXISTS notify_profile_change ON public.profiles;
CREATE TRIGGER notify_profile_change AFTER INSERT OR UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public._notify_profile_change();

-- ════════════════════════════════════════════════════════════════
-- STORAGE BUCKETS + POLICIES
-- ════════════════════════════════════════════════════════════════
INSERT INTO storage.buckets (id, name, public) VALUES ('avatars', 'avatars', false) ON CONFLICT (id) DO NOTHING;
-- Avatars are staff/client photos, so the bucket is private: reads require a
-- signed-in user and the portal resolves signed URLs at load time.
UPDATE storage.buckets SET public = false WHERE id = 'avatars';
INSERT INTO storage.buckets (id, name, public) VALUES ('assessment-files', 'assessment-files', false) ON CONFLICT (id) DO NOTHING;
-- Branding bucket holds logos and favicons. Public-read so an unauthenticated
-- visitor (e.g. someone hitting the login page) can fetch them. Mutations
-- happen exclusively through service_role from the Vercel API route, so
-- no INSERT/UPDATE/DELETE policy for authenticated users is needed.
INSERT INTO storage.buckets (id, name, public) VALUES ('branding', 'branding', true) ON CONFLICT (id) DO NOTHING;

DROP POLICY IF EXISTS avatars_public_read ON storage.objects;
DROP POLICY IF EXISTS avatars_auth_insert ON storage.objects;
DROP POLICY IF EXISTS avatars_auth_update ON storage.objects;
DROP POLICY IF EXISTS avatars_auth_delete ON storage.objects;
DROP POLICY IF EXISTS assessment_files_auth_read ON storage.objects;
DROP POLICY IF EXISTS assessment_files_auth_insert ON storage.objects;
DROP POLICY IF EXISTS assessment_files_auth_update ON storage.objects;
DROP POLICY IF EXISTS assessment_files_auth_delete ON storage.objects;
DROP POLICY IF EXISTS storage_admin_migration_insert ON storage.objects;
DROP POLICY IF EXISTS storage_admin_migration_select ON storage.objects;

-- 1785: A FILE ASKS FOR A FRESH SIGN-IN CHECK, AS EVERY ROW DOES.
--
-- [stated] Arian, asked whether downloads should get the check the tables
-- have: "yes". Every table's rules ask `mfa_is_fresh()`, so a session past the
-- firm's MFA window is refused the rows; the storage rules did not, so the same
-- session could still list, download, replace and remove the files it reached
-- before. Every storage rule for a signed-in user asks it now, staff and
-- clients alike. The branding bucket's public read does not: the sign-in page
-- fetches the logo before anybody has signed in.
--
-- `mfa_is_fresh` is defined further down with the rest of the sign-in checks;
-- this asks for it when a rule runs rather than when it is written, so the
-- rules here can name it. Each rule asks it once per statement, `(SELECT ...)`,
-- not once for every file a listing returns.
CREATE OR REPLACE FUNCTION public._files_mfa_fresh() RETURNS boolean
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $fmfa$
BEGIN
  RETURN public.mfa_is_fresh();
END $fmfa$;
REVOKE ALL ON FUNCTION public._files_mfa_fresh() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public._files_mfa_fresh() TO authenticated, service_role;

CREATE POLICY avatars_public_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatars' AND (SELECT public._files_mfa_fresh()));
CREATE POLICY avatars_auth_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (SELECT public._files_mfa_fresh()) AND name LIKE 'avatars/' || auth.uid()::text || '%');
CREATE POLICY avatars_auth_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatars' AND (SELECT public._files_mfa_fresh()) AND name LIKE 'avatars/' || auth.uid()::text || '%');
CREATE POLICY avatars_auth_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatars' AND (SELECT public._files_mfa_fresh()) AND name LIKE 'avatars/' || auth.uid()::text || '%');

-- 1782: WHAT A CLIENT IS SHOWN OF AN ENGAGEMENT, ASKED THE WAY THE PORTAL ASKS.
--
-- [stated] Arian, asked whether to close it: "Tighten it (Recommended)".
-- Found while doing 1779: the rule for a file in an engagement's folder asked
-- only whose engagement it was, so a client could list and download every
-- object in it, whatever the portal showed them: the evidence and description
-- pictures of findings not shown to them (drafts among them), files not shared
-- with them, and pictures in the internal notes. The helpers below answer, for
-- the file rule further down, the same questions the portal's screens answer.
--
-- A section, as `isSectionVisible` has it: the internal notes only when the
-- engagement shows them (or the firm defaults them on); any other section once
-- the report is delivered and signed off; otherwise the engagement's own choice,
-- then the firm's default, then the section's own. The keys are the portal's
-- (`exec_summary`, `appendices`, `summary_<id>` for a custom section).
CREATE OR REPLACE FUNCTION public._client_sees_section(p_assessment uuid, p_key text) RETURNS boolean
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $csec$
DECLARE
  v_a record;
  v_vis jsonb;
  v_cfg jsonb;
  v_qa boolean;
  v_custom jsonb;
  v_def boolean;
  v_val jsonb;
BEGIN
  SELECT status, delivered_at, qa_status, client_section_visibility INTO v_a
    FROM public.assessments WHERE id = p_assessment;
  IF NOT FOUND OR p_key IS NULL THEN RETURN false; END IF;
  BEGIN v_vis := COALESCE(NULLIF(v_a.client_section_visibility, ''), '{}')::jsonb;
  EXCEPTION WHEN OTHERS THEN v_vis := '{}'::jsonb; END;
  IF jsonb_typeof(v_vis) IS DISTINCT FROM 'object' THEN v_vis := '{}'::jsonb; END IF;
  SELECT summary_fields, qa_enabled INTO v_cfg, v_qa FROM public.settings LIMIT 1;
  IF jsonb_typeof(v_cfg) IS DISTINCT FROM 'object' THEN v_cfg := '{}'::jsonb; END IF;
  -- The firm's default: a custom section's own, a built-in one set in Settings,
  -- else the section's own (the four text sections the portal shows by default).
  -- 1786: a custom section is asked for as the engagement names it,
  -- `summary_<id>`, and found by its own id, as `_smClientDefault` finds it.
  SELECT c INTO v_custom
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_cfg->'custom') = 'array' THEN v_cfg->'custom' ELSE '[]'::jsonb END) c
   WHERE c->>'id' = p_key
      OR (left(p_key, 8) = 'summary_' AND c->>'id' = substr(p_key, 9))
   ORDER BY (c->>'id' = p_key) DESC
   LIMIT 1;
  IF v_custom IS NOT NULL THEN
    v_def := CASE WHEN jsonb_typeof(v_custom->'client_default') = 'boolean' THEN (v_custom->>'client_default')::boolean ELSE false END;
  ELSIF jsonb_typeof(v_cfg->'fields'->p_key->'client_default') = 'boolean' THEN
    v_def := (v_cfg->'fields'->p_key->>'client_default')::boolean;
  ELSE
    v_def := p_key IN ('scope', 'caveats', 'retest_summary', 'executive_summary', 'findings', 'comments', 'documents');
  END IF;
  -- The engagement's own choice, read as the portal reads it (`!!value`).
  v_val := v_vis->p_key;
  IF p_key IN ('notes', 'scan_import', 'timeline', 'credentials') THEN
    IF v_vis ? p_key THEN
      RETURN CASE jsonb_typeof(v_val) WHEN 'boolean' THEN (v_val #>> '{}')::boolean WHEN 'number' THEN (v_val #>> '{}')::numeric <> 0
                  WHEN 'string' THEN (v_val #>> '{}') <> '' WHEN 'null' THEN false ELSE true END;
    END IF;
    RETURN v_def;
  END IF;
  IF (v_a.status = 'delivered' OR v_a.delivered_at IS NOT NULL)
     AND (v_qa IS FALSE OR v_a.qa_status = 'approved') THEN
    RETURN true;
  END IF;
  IF v_vis ? p_key THEN
    RETURN CASE jsonb_typeof(v_val) WHEN 'boolean' THEN (v_val #>> '{}')::boolean WHEN 'number' THEN (v_val #>> '{}')::numeric <> 0
                WHEN 'string' THEN (v_val #>> '{}') <> '' WHEN 'null' THEN false ELSE true END;
  END IF;
  RETURN v_def;
END $csec$;
REVOKE ALL ON FUNCTION public._client_sees_section(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._client_sees_section(uuid, text) TO service_role;

-- Whether a section of one engagement that its client can see refers to a
-- stored file.
CREATE OR REPLACE FUNCTION public._client_section_refers(p_assessment uuid, p_path text) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $csref$
  SELECT EXISTS (
    SELECT 1 FROM public.assessments a
     WHERE a.id = p_assessment AND COALESCE(p_path, '') <> ''
       AND strpos(concat_ws(' ', a.exec_summary, a.caveats, a.retest_summary, a.notes, a.scope,
                            a.appendices::text, a.summary_sections::text), p_path) > 0
       AND ((strpos(COALESCE(a.exec_summary, ''), p_path) > 0 AND public._client_sees_section(a.id, 'exec_summary'))
         OR (strpos(COALESCE(a.caveats, ''), p_path) > 0 AND public._client_sees_section(a.id, 'caveats'))
         OR (strpos(COALESCE(a.retest_summary, ''), p_path) > 0 AND public._client_sees_section(a.id, 'retest_summary'))
         OR (strpos(COALESCE(a.notes, ''), p_path) > 0 AND public._client_sees_section(a.id, 'notes'))
         OR (strpos(COALESCE(a.scope, ''), p_path) > 0 AND public._client_sees_section(a.id, 'scope'))
         OR (strpos(COALESCE(a.appendices::text, ''), p_path) > 0 AND public._client_sees_section(a.id, 'appendices'))
         OR EXISTS (SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(a.summary_sections) = 'object'
                                                       THEN a.summary_sections ELSE '{}'::jsonb END) sec
                     WHERE strpos(sec.value, p_path) > 0
                       AND public._client_sees_section(a.id, 'summary_' || sec.key))))
$csref$;
REVOKE ALL ON FUNCTION public._client_section_refers(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._client_section_refers(uuid, text) TO service_role;

-- Whether anything a client is shown refers to a stored file: a finding they
-- can see (on any of their engagements, or one of their own scans), or a
-- section of one of their engagements that they can see. A picture is filed
-- under a finding or section folder when it is added, but a document read back
-- from Word files its pictures under shared folders, and a copied finding keeps
-- pointing at its original's, so the reference is the one answer that holds for
-- every picture. The engagement the file is filed under is asked first, as
-- nearly every picture is used there; the rest of theirs only when it is not.
CREATE OR REPLACE FUNCTION public._client_sees_reference(p_client uuid, p_path text) RETURNS boolean
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $cref$
DECLARE
  v_home uuid;
BEGIN
  IF p_client IS NULL OR COALESCE(p_path, '') = '' THEN RETURN false; END IF;
  BEGIN v_home := split_part(p_path, '/', 1)::uuid; EXCEPTION WHEN OTHERS THEN v_home := NULL; END;
  IF v_home IS NOT NULL AND EXISTS (SELECT 1 FROM public.assessments WHERE id = v_home AND client_id = p_client) THEN
    IF EXISTS (SELECT 1 FROM public.findings f
                WHERE f.assessment_id = v_home AND f.client_visible = true
                  AND strpos(f::text, p_path) > 0)
       OR public._client_section_refers(v_home, p_path) THEN
      RETURN true;
    END IF;
  ELSE
    v_home := NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.findings f
              WHERE f.client_visible = true
                AND f.assessment_id IS DISTINCT FROM v_home
                AND (f.assessment_id IN (SELECT a.id FROM public.assessments a WHERE a.client_id = p_client)
                     OR (f.assessment_id IS NULL AND f.client_id = p_client))
                AND strpos(f::text, p_path) > 0) THEN
    RETURN true;
  END IF;
  RETURN EXISTS (SELECT 1 FROM public.assessments a
                  WHERE a.client_id = p_client AND a.id IS DISTINCT FROM v_home
                    AND public._client_section_refers(a.id, p_path));
END $cref$;
REVOKE ALL ON FUNCTION public._client_sees_reference(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._client_sees_reference(uuid, text) TO service_role;

CREATE OR REPLACE FUNCTION public.can_access_assessment_file(file_path text) RETURNS boolean
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
AS $$
DECLARE
  v_first_seg text;
  v_first_uuid uuid;
  v_second_seg text;
  v_third_seg text;
  v_role text;
  v_client_id uuid;
  v_doc_id uuid;
  v_doc_assess_id uuid;
  v_doc_client uuid;
  v_lead_id uuid;
  v_doc_delivered boolean;
BEGIN
  -- BYO is single-tenant, so caller resolution doesn't filter on tenant_id.
  SELECT role, client_id INTO v_role, v_client_id FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_role IS NULL THEN RETURN false; END IF;
  -- 1943: the role as every rule reads it, so a contractor while contractors
  -- are off is nobody here too.
  v_role := public.current_user_role();
  IF v_role = 'none' THEN RETURN false; END IF;

  v_first_seg := split_part(file_path, '/', 1);
  v_second_seg := split_part(file_path, '/', 2);
  v_third_seg := split_part(file_path, '/', 3);
  IF v_first_seg IS NULL OR v_first_seg = '' THEN RETURN false; END IF;
  BEGIN v_first_uuid := v_first_seg::uuid; EXCEPTION WHEN OTHERS THEN RETURN false; END;

  -- Layout 2: <tenant_id>/final-pdfs/<type>_<id>.pdf
  IF v_second_seg = 'final-pdfs' THEN
    DECLARE v_basename text; v_after_underscore text; v_before_dot text; v_type text;
    BEGIN
      v_basename := v_third_seg;
      IF v_basename IS NULL OR v_basename = '' THEN RETURN false; END IF;
      -- 1324: SPLIT FROM THE RIGHT, BECAUSE A TYPE MAY CONTAIN AN UNDERSCORE.
      --
      -- This read the type as everything before the FIRST underscore and the id
      -- as everything after it. That holds for `report`, `loa`, `proposal` and
      -- `invoice` and breaks on `vuln_report`: the type came out as `vuln` and
      -- the id as `report_<uuid>`, which fails the cast, so the policy returned
      -- false and every attempt to keep a scan's PDF was refused with a 403
      -- row-level-security error.
      --
      -- The id is a UUID and a UUID is 36 characters, so the boundary is the
      -- LAST underscore before the extension. No type can break that, whatever
      -- it is called.
      v_before_dot := split_part(v_basename, '.', 1);
      IF length(v_before_dot) < 38 THEN RETURN false; END IF;
      v_after_underscore := right(v_before_dot, 36);
      v_type := left(v_before_dot, length(v_before_dot) - 37);
      BEGIN v_doc_id := v_after_underscore::uuid; EXCEPTION WHEN OTHERS THEN RETURN false; END;
      IF v_type = 'proposal' THEN
        SELECT client_id INTO v_doc_client FROM public.proposals WHERE id = v_doc_id LIMIT 1;
        IF NOT FOUND THEN RETURN false; END IF;
      ELSIF v_type = 'invoice' THEN
        SELECT client_id INTO v_doc_client FROM public.invoices WHERE id = v_doc_id LIMIT 1;
        IF NOT FOUND THEN RETURN false; END IF;
      ELSIF v_type IN ('report', 'attestation', 'loa') THEN
        SELECT client_id, lead_id, (status = 'delivered' OR delivered_at IS NOT NULL)
          INTO v_doc_client, v_lead_id, v_doc_delivered FROM public.assessments WHERE id = v_doc_id LIMIT 1;
        IF NOT FOUND THEN RETURN false; END IF;
        v_doc_assess_id := v_doc_id;
      ELSIF v_type = 'vuln_report' THEN
        -- 1324: a scan report's slot is keyed by the RUN (1313), and a run
        -- carries its own `client_id` - the same column the file trigger
        -- already trusts to decide who a scan's evidence belongs to.
        SELECT client_id INTO v_doc_client FROM public.scan_runs WHERE id = v_doc_id LIMIT 1;
        IF NOT FOUND THEN RETURN false; END IF;
      ELSE
        IF v_role IN ('admin','senior','standard') THEN RETURN true; END IF;   -- 1970: not Sales or Marketing
        RETURN false;
      END IF;
      IF v_role IN ('admin','senior','standard') THEN RETURN true; END IF;
      -- 1970: SALES AND MARKETING HAVE THE COMMERCIAL DOCUMENTS ONLY: a proposal
      -- or an invoice. A report, the letter of attestation and a scan's report
      -- are the findings in another form, so they are the firm's working staff's,
      -- as the findings are (is_delivery_staff).
      IF v_role IN ('sales','marketing') THEN RETURN v_type IN ('proposal', 'invoice'); END IF;
      IF v_role = 'contractor' THEN
        -- 1943: an engagement of theirs, led by them or handed to their team.
        IF v_type IN ('report','attestation','loa') THEN RETURN public.can_access_assessment(v_doc_id); END IF;
        RETURN false;
      END IF;
      -- 1777: A REPORT IS THE CLIENT'S WHILE IT IS DELIVERED. The portal only
      -- ever offered it after delivery, and this read it at any status, so a
      -- report taken back, or one still in QA whose PDF was already made, was
      -- one request away from a client who knew where to ask. Proposals and
      -- invoices are the client's as they always were.
      IF v_role = 'client' THEN
        IF v_type IN ('report', 'attestation', 'loa') THEN RETURN v_doc_client = v_client_id AND COALESCE(v_doc_delivered, false); END IF;
        RETURN v_doc_client = v_client_id;
      END IF;
      RETURN false;
    END;
  END IF;

  -- Legacy <tenant_id>/<id>/<type>.pdf
  IF v_second_seg IS NOT NULL AND v_second_seg <> '' THEN
    DECLARE v_legacy_id uuid;
    BEGIN
      BEGIN v_legacy_id := v_second_seg::uuid; EXCEPTION WHEN OTHERS THEN v_legacy_id := NULL; END;
      IF v_legacy_id IS NOT NULL AND v_role IN ('admin','senior','standard') THEN
        IF EXISTS (SELECT 1 FROM public.proposals WHERE id = v_legacy_id)
           OR EXISTS (SELECT 1 FROM public.invoices WHERE id = v_legacy_id)
           OR EXISTS (SELECT 1 FROM public.assessments WHERE id = v_legacy_id)
        THEN RETURN true; END IF;
      END IF;
      -- 1970: and Sales and Marketing a proposal's or an invoice's, never an engagement's.
      IF v_legacy_id IS NOT NULL AND v_role IN ('sales','marketing') THEN
        IF EXISTS (SELECT 1 FROM public.proposals WHERE id = v_legacy_id)
           OR EXISTS (SELECT 1 FROM public.invoices WHERE id = v_legacy_id)
        THEN RETURN true; END IF;
      END IF;
    END;
  END IF;

  -- Layout 1: assessment-rooted (evidence)
  -- <assessment>/edited/<file>.docx is the firm's WORKING Word document, kept
  -- so the portal can hand back what was delivered and refresh it. A client is
  -- never given it: they receive the final PDF (421). The path is readable in
  -- the assessments row, so the door has to be shut here rather than only in
  -- the interface.
  IF v_role = 'client' AND v_second_seg = 'edited' THEN RETURN false; END IF;
  -- 1970: an engagement's evidence and working files are the firm's working
  -- staff's (is_delivery_staff): Sales and Marketing are given none of them.
  IF v_role IN ('admin','senior','standard') THEN RETURN EXISTS (SELECT 1 FROM public.assessments WHERE id = v_first_uuid); END IF;
  IF v_role IN ('sales','marketing') THEN RETURN false; END IF;
  IF v_role = 'contractor' THEN RETURN public.can_access_assessment(v_first_uuid); END IF;   -- 1943: theirs or their team's
  IF v_role = 'client' THEN
    -- 1782: WHAT THE PORTAL SHOWS THEM, NOT THE WHOLE FOLDER. It must be their
    -- engagement, as before, and then the file must be one they are shown.
    IF NOT EXISTS (SELECT 1 FROM public.assessments WHERE id = v_first_uuid AND client_id = v_client_id) THEN
      RETURN false;
    END IF;
    -- A file with a row (shared with them, uploaded by them, a scan's
    -- document): the row decides, exactly as it does for their list
    -- (`afile_read`), 1779's rule with it: one filed with the report or the
    -- letter waits for the report to be delivered.
    IF EXISTS (SELECT 1 FROM public.assessment_files f WHERE f.storage_path = file_path) THEN
      RETURN EXISTS (SELECT 1 FROM public.assessment_files f JOIN public.assessments a ON a.id = f.assessment_id
                      WHERE f.storage_path = file_path AND f.assessment_id = v_first_uuid AND f.client_visible = true
                        AND (COALESCE(f.doc_type, '') NOT IN ('report', 'attestation')
                             OR a.status = 'delivered' OR a.delivered_at IS NOT NULL));
    END IF;
    -- A picture: while something they are shown uses it. Nearly every one is
    -- filed under the finding that uses it (`<engagement>/<field>/<finding>/...`),
    -- so that finding is asked first; a section's picture, one read back from
    -- Word and a copied finding's are found by `_client_sees_reference`. A
    -- picture the finding no longer uses (replaced, or taken out) is not shown.
    IF v_third_seg ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
      IF EXISTS (SELECT 1 FROM public.findings fd
                  WHERE fd.id = v_third_seg::uuid AND fd.client_visible = true
                    AND (fd.assessment_id IN (SELECT a.id FROM public.assessments a WHERE a.client_id = v_client_id)
                         OR (fd.assessment_id IS NULL AND fd.client_id = v_client_id))
                    AND strpos(fd::text, file_path) > 0) THEN
        RETURN true;
      END IF;
    END IF;
    RETURN public._client_sees_reference(v_client_id, file_path);
  END IF;
  RETURN false;
END;
$$;

-- 1714: A CLIENT ADDS FILES, AND REMOVES ITS OWN. IT DOES NOT REWRITE THE
-- FIRM'S.
--
-- Every file a client can READ, it could also overwrite: the update policy
-- asked only whether the file could be reached, which for a client includes
-- their own delivered report, letter of authority and invoice PDFs, and every
-- file the firm shared with them. [stated] Arian: "yes, they should be able to
-- delete their uploaded files as well like all the edit stuff staff have for
-- files".
--
-- So, for a client only (staff are unchanged):
--   - a new file goes in the engagement's own folder, `<assessment>/<file>`,
--     which is where the portal's Upload button puts it, and nowhere else: not
--     the final-PDF slots, where planting a file first would make it theirs;
--   - a file already there is replaced or removed only if they uploaded it,
--     and only in that folder;
--   - the one write a client makes to the firm's paper: signing a proposal
--     adds the signature page to its PDF from the signer's browser. That is
--     allowed for a proposal of theirs signed in the last hour, and only while
--     the PDF has not been written since the signature, so it is one write.
CREATE OR REPLACE FUNCTION public._client_own_file_area(p_name text) RETURNS boolean
  LANGUAGE sql IMMUTABLE
  SET search_path = pg_catalog, pg_temp AS $$
  SELECT COALESCE(p_name, '') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/[^/]+$'
$$;

-- 1782: and the engagement the folder is named for is theirs. With 1782 a file
-- in the folder is readable only once it is shown to them, so a client's own
-- upload, which has no row until it is stored, is allowed on this and on
-- being theirs rather than on the read rule.
CREATE OR REPLACE FUNCTION public._client_engagement_folder(p_name text) RETURNS boolean
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $cfold$
DECLARE v_id uuid;
BEGIN
  IF public.current_user_role() IS DISTINCT FROM 'client' THEN RETURN false; END IF;
  BEGIN v_id := split_part(COALESCE(p_name, ''), '/', 1)::uuid; EXCEPTION WHEN OTHERS THEN RETURN false; END;
  RETURN EXISTS (SELECT 1 FROM public.assessments WHERE id = v_id AND client_id = public.current_user_client_id());
END $cfold$;
REVOKE ALL ON FUNCTION public._client_engagement_folder(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public._client_engagement_folder(text) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public._client_signing_proposal_pdf(p_name text, p_written timestamptz)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE v_file text := split_part(COALESCE(p_name, ''), '/', 3); v_id uuid;
BEGIN
  IF public.current_user_role() IS DISTINCT FROM 'client' THEN RETURN false; END IF;
  IF split_part(p_name, '/', 2) <> 'final-pdfs' OR split_part(p_name, '/', 4) <> ''
     OR v_file !~ '^proposal_[0-9a-fA-F-]{36}\.pdf$' THEN
    RETURN false;
  END IF;
  BEGIN v_id := substr(v_file, 10, 36)::uuid; EXCEPTION WHEN OTHERS THEN RETURN false; END;
  RETURN EXISTS (
    SELECT 1 FROM public.proposals p
     WHERE p.id = v_id
       AND p.client_id = public.current_user_client_id()
       AND p.status = 'signed'
       AND p.signed_at > now() - interval '1 hour'
       AND (p_written IS NULL OR p_written <= p.signed_at));
END $$;
REVOKE ALL ON FUNCTION public._client_signing_proposal_pdf(text, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public._client_signing_proposal_pdf(text, timestamptz) TO authenticated, service_role;

-- 1842: A PICTURE NOTHING USES ANY MORE. A standard tester may delete a
-- finding ([stated] "yes"), and its pictures should go with it; the delete
-- rule below let them remove only pictures they had uploaded themselves, so
-- another person's stayed in the firm's storage with nothing pointing at them
-- (as they did when a standard tester took a picture out of a finding). This
-- answers whether a file is a picture in one of a finding's own folders (its
-- evidence, description, impact, remediation, retest or one of the firm's own
-- fields, under an engagement) that no finding, library entry or review
-- comment names any more: such a file is the firm's own leftover, and a
-- standard tester may remove it. A picture still named anywhere is not, so a
-- copy of a finding (a re-signed engagement's, a duplicated proposal's) or a
-- library entry made from it keeps its pictures. It reads every finding, so it
-- is asked last, only for a standard tester's delete of somebody else's file.
CREATE OR REPLACE FUNCTION public._finding_picture_unused(p_name text) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $fpu$
  SELECT public.current_user_role() IN ('admin', 'senior', 'standard')
     AND p_name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/(evidence|description|impact|remediation|retest|custom[A-Za-z0-9_-]*)/[^/]+/[^/]+$'
     AND NOT EXISTS (SELECT 1 FROM public.findings f WHERE strpos(f::text, p_name) > 0)
     AND NOT EXISTS (SELECT 1 FROM public.kb_entries k WHERE strpos(k::text, p_name) > 0)
     AND NOT EXISTS (SELECT 1 FROM public.qa_comments q WHERE strpos(q::text, p_name) > 0);
$fpu$;
REVOKE ALL ON FUNCTION public._finding_picture_unused(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._finding_picture_unused(text) TO authenticated, service_role;

-- 1782: the firm's rules as they were. A client reads what they are shown
-- (`can_access_assessment_file`) and their own upload in their engagement's
-- folder, which is also the only place they add, replace or remove a file; the
-- signature page written onto a proposal they have just signed is the one other
-- write, as before.
-- 1785: and each asks for a fresh sign-in check first.
CREATE POLICY assessment_files_auth_read ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'assessment-files' AND (SELECT public._files_mfa_fresh()) AND (public.can_access_assessment_file(name)
    OR (owner = auth.uid() AND public._client_own_file_area(name) AND public._client_engagement_folder(name))));
CREATE POLICY assessment_files_auth_insert ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'assessment-files' AND (SELECT public._files_mfa_fresh()) AND (
    (public.current_user_role() IS DISTINCT FROM 'client' AND public.can_access_assessment_file(name))
    OR (public._client_own_file_area(name) AND public._client_engagement_folder(name))));
CREATE POLICY assessment_files_auth_update ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'assessment-files' AND (SELECT public._files_mfa_fresh()) AND (
    (public.current_user_role() IS DISTINCT FROM 'client' AND public.can_access_assessment_file(name))
    OR (owner = auth.uid() AND public._client_own_file_area(name) AND public._client_engagement_folder(name))
    OR (public._client_signing_proposal_pdf(name, updated_at) AND public.can_access_assessment_file(name))))
  WITH CHECK (bucket_id = 'assessment-files' AND (SELECT public._files_mfa_fresh()) AND (
    (public.current_user_role() IS DISTINCT FROM 'client' AND public.can_access_assessment_file(name))
    OR (owner = auth.uid() AND public._client_own_file_area(name) AND public._client_engagement_folder(name))
    OR (public._client_signing_proposal_pdf(name, NULL) AND public.can_access_assessment_file(name))));
CREATE POLICY assessment_files_auth_delete ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'assessment-files' AND (SELECT public._files_mfa_fresh()) AND (
    (public.current_user_role() IS DISTINCT FROM 'client' AND public.can_access_assessment_file(name)
      AND (public.can_manage() OR owner = auth.uid()))
    OR (owner = auth.uid() AND public._client_own_file_area(name) AND public._client_engagement_folder(name))
    OR (public.current_user_role() = 'standard' AND public.can_access_assessment_file(name)
      AND public._finding_picture_unused(name))));

CREATE POLICY storage_admin_migration_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK ((SELECT public._files_mfa_fresh()) AND EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = auth.uid() AND role = 'admin' AND active = true));
CREATE POLICY storage_admin_migration_select ON storage.objects FOR SELECT TO authenticated USING ((SELECT public._files_mfa_fresh()) AND EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = auth.uid() AND role = 'admin' AND active = true));

-- ════════════════════════════════════════════════════════════════
-- REALTIME
-- ════════════════════════════════════════════════════════════════
DO $rt$ DECLARE t text; BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN CREATE PUBLICATION supabase_realtime; END IF;
  FOR t IN SELECT unnest(ARRAY['settings','profiles','clients','assessments','findings','proposals','invoices','kb_entries','feedback','assessment_comments','qa_comments','assessment_files','contractor_payments','meetings','meeting_attendees','timeline_events','tickets','email_notifications','login_codes']) LOOP
    BEGIN EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE ' || quote_ident(t); EXCEPTION WHEN duplicate_object THEN NULL; END;
  END LOOP;
END $rt$;

-- ════════════════════════════════════════════════════════════════
-- HELPER FUNCTIONS
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public._get_cred_key() RETURNS text AS $$
  SELECT key_value FROM public._encryption_keys WHERE key_name = 'credentials';
$$ LANGUAGE sql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public._validate_cron_secret(p_secret text) RETURNS boolean AS $$
DECLARE v_stored text;
BEGIN
  SELECT value INTO v_stored FROM public._internal_secrets WHERE key = 'CRON_SECRET';
  IF v_stored IS NULL OR v_stored = 'CHANGE_ME_TO_YOUR_ACTUAL_CRON_SECRET' THEN RAISE EXCEPTION 'CRON_SECRET not configured'; END IF;
  RETURN p_secret = v_stored;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- Drop the old single-argument signature first: adding a defaulted parameter
-- creates an OVERLOAD rather than replacing, which would make every existing
-- one-argument call ambiguous.
DROP FUNCTION IF EXISTS public._validate_provision_secret(text);
CREATE OR REPLACE FUNCTION public._validate_provision_secret(p_secret text, p_op text DEFAULT NULL) RETURNS boolean AS $$
DECLARE v_stored text; v_hashed text; v_ok boolean;
BEGIN
  SELECT value INTO v_stored FROM public._internal_secrets WHERE key = 'PROVISION_SECRET';
  IF v_stored IS NULL OR v_stored = '' THEN
    -- Audit even the failures, so a firm can see attempted use.
    BEGIN
      INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
        VALUES (COALESCE(p_op, 'provision_secret_call'), 'provision_secret', 'rejected', 'no secret set');
    EXCEPTION WHEN others THEN NULL; END;
    RETURN false;
  END IF;
  v_hashed := encode(extensions.digest(p_secret, 'sha256'), 'hex');
  -- Stored value is the SHA-256 hash of the real provision secret (64 lowercase hex chars).
  -- This means the real secret is never present in the database at rest.
  -- Old deployments that stored plaintext still validate via the legacy branch until
  -- they next run rpc_bulk_clean (which re-stores as hash).
  IF v_stored ~ '^[0-9a-f]{64}$' THEN
    v_ok := (v_hashed = v_stored);
  ELSE
    -- Legacy plaintext path (pre-hash-storage deployments). Keep hashing the stored
    -- value so the comparison still happens on hashes, matching the old behaviour.
    v_ok := (v_hashed = encode(extensions.digest(v_stored, 'sha256'), 'hex'));
  END IF;
  -- Every use of Pental's provisioning credential is recorded in the firm's OWN
  -- database, readable by their admins, so Pental-side access is visible to them
  -- rather than invisible. Never blocks the call if logging fails.
  BEGIN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result)
      VALUES (COALESCE(p_op, 'provision_secret_call'), 'provision_secret', CASE WHEN v_ok THEN 'ok' ELSE 'rejected' END);
  EXCEPTION WHEN others THEN NULL; END;
  RETURN v_ok;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public._validate_provision_secret_or_bootstrap(p_secret text) RETURNS boolean AS $$
DECLARE v_stored text;
BEGIN
  SELECT value INTO v_stored FROM public._internal_secrets WHERE key = 'PROVISION_SECRET';
  IF v_stored IS NULL OR v_stored = '' THEN RETURN true; END IF;
  RETURN public._validate_provision_secret(p_secret);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- rpc_get_provision_secret has been removed to prevent anon exfiltration of the secret.
-- BYO tenants pay for isolation: the secret must not be retrievable from BYO at rest.
-- Master learns the secret once from rpc_bulk_clean's return value and stores it.
-- If master loses its copy, the tenant must re-run rpc_bulk_clean (which wipes BYO data).
DROP FUNCTION IF EXISTS public.rpc_get_provision_secret();


-- ════════════════════════════════════════════════════════════════
-- LOGIN CODE RPCs
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_login_code_create(p_email text, p_code text, p_expires_at timestamptz, p_secret text DEFAULT NULL) RETURNS boolean AS $$
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_login_code_create') THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  INSERT INTO public.login_codes (email, code, expires_at) VALUES (lower(p_email), p_code, p_expires_at); RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_login_code_verify(p_email text, p_code text, p_secret text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_login_code_verify') THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  UPDATE public.login_codes SET used = true WHERE id = (SELECT id FROM public.login_codes WHERE email = lower(p_email) AND code = p_code AND used = false AND expires_at >= now() ORDER BY created_at DESC LIMIT 1 FOR UPDATE SKIP LOCKED) RETURNING id INTO v_id;
  IF v_id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'id', v_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_login_code_invalidate(p_email text, p_secret text DEFAULT NULL) RETURNS boolean AS $$
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  UPDATE public.login_codes SET used = true WHERE email = lower(p_email) AND used = false; RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_login_code_count_recent(p_email text, p_since timestamptz, p_secret text DEFAULT NULL) RETURNS integer AS $$
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  RETURN (SELECT count(*) FROM public.login_codes WHERE email = lower(p_email) AND created_at >= p_since)::integer;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- These four GRANTs are wrapped in DO blocks because re-runs of the script
-- against a database that has already applied later patches (which DROP
-- and recreate these functions with new signatures) would otherwise halt
-- here. The later patch sections re-issue GRANTs against the new
-- signatures, so authoritative permissions are always set correctly by
-- script-end.
DO $g$ BEGIN
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_login_code_create(text, text, timestamptz, text) TO anon, authenticated, service_role';
EXCEPTION WHEN undefined_function THEN NULL; END $g$;
DO $g$ BEGIN
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_login_code_verify(text, text, text) TO anon, authenticated, service_role';
EXCEPTION WHEN undefined_function THEN NULL; END $g$;
DO $g$ BEGIN
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_login_code_invalidate(text, text) TO anon, authenticated, service_role';
EXCEPTION WHEN undefined_function THEN NULL; END $g$;
DO $g$ BEGIN
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_login_code_count_recent(text, timestamptz, text) TO anon, authenticated, service_role';
EXCEPTION WHEN undefined_function THEN NULL; END $g$;

-- ════════════════════════════════════════════════════════════════
-- AUTH + BRIDGE RPCs
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_bootstrap_admin(p_email text, p_name text) RETURNS jsonb AS $$
DECLARE v_count integer; v_uid uuid;
BEGIN
  SELECT count(*) INTO v_count FROM public.profiles;
  IF v_count > 0 THEN RETURN jsonb_build_object('error','Bootstrap not available - users already exist'); END IF;
  v_uid := gen_random_uuid();
  INSERT INTO auth.users (id,instance_id,email,encrypted_password,email_confirmed_at,aud,role,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token,phone_change,phone_change_token,reauthentication_token,is_sso_user,is_anonymous) VALUES (v_uid,'00000000-0000-0000-0000-000000000000',p_email,extensions.crypt(gen_random_uuid()::text,extensions.gen_salt('bf')),now(),'authenticated','authenticated',jsonb_build_object('provider','email','providers',ARRAY['email']),jsonb_build_object('name',p_name),now(),now(),encode(extensions.gen_random_bytes(32),'hex'),'','','','','','',false,false);
  INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at) VALUES (gen_random_uuid(),v_uid,p_email,jsonb_build_object('sub',v_uid::text,'email',p_email,'email_verified',true),'email',now(),now(),now());
  INSERT INTO public.profiles (id,auth_user_id,email,name,role) VALUES (v_uid,v_uid,p_email,p_name,'admin');
  RETURN jsonb_build_object('success',true,'user_id',v_uid,'message','Admin account created');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP FUNCTION IF EXISTS public.rpc_set_bridge_password(text, text);
DROP FUNCTION IF EXISTS public.rpc_set_bridge_password(text, text, text);
CREATE OR REPLACE FUNCTION public.rpc_set_bridge_password(p_email text, p_password text, p_secret text DEFAULT NULL) RETURNS boolean AS $$
DECLARE v_uid uuid; v_profile_id uuid; v_auth_id uuid; v_enc text;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_set_bridge_password') THEN RAISE EXCEPTION 'Invalid provision secret'; END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  v_enc := extensions.crypt(p_password, extensions.gen_salt('bf'));
  SELECT id INTO v_auth_id FROM auth.users WHERE email = lower(p_email);
  IF v_auth_id IS NOT NULL THEN
    UPDATE auth.users SET encrypted_password = v_enc, email_confirmed_at = COALESCE(email_confirmed_at, now()), updated_at = now() WHERE id = v_auth_id;
    SELECT id INTO v_profile_id FROM public.profiles WHERE lower(email) = lower(p_email) LIMIT 1;
    IF v_profile_id IS NOT NULL THEN
      -- Profile exists - just ensure auth_user_id points to the correct auth user
      UPDATE public.profiles SET auth_user_id = v_auth_id, active = true WHERE id = v_profile_id AND (auth_user_id IS NULL OR auth_user_id != v_auth_id);
    ELSE
      -- No profile - create one
      INSERT INTO public.profiles (id,auth_user_id,email,name,role,active) VALUES (v_auth_id,v_auth_id,lower(p_email),split_part(lower(p_email),'@',1),'admin',true) ON CONFLICT (id) DO UPDATE SET email=lower(p_email),auth_user_id=v_auth_id,active=true;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM auth.identities WHERE user_id::text = v_auth_id::text AND provider = 'email') THEN
      INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at) VALUES (gen_random_uuid(),v_auth_id,lower(p_email),jsonb_build_object('sub',v_auth_id::text,'email',lower(p_email),'email_verified',true),'email',now(),now(),now());
    END IF;
    RETURN true;
  END IF;
  SELECT id INTO v_profile_id FROM public.profiles WHERE lower(email) = lower(p_email) LIMIT 1;
  v_uid := COALESCE(v_profile_id, gen_random_uuid());
  INSERT INTO auth.users (id,instance_id,email,encrypted_password,email_confirmed_at,aud,role,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token,phone_change,phone_change_token,reauthentication_token,is_sso_user,is_anonymous) VALUES (v_uid,'00000000-0000-0000-0000-000000000000',lower(p_email),v_enc,now(),'authenticated','authenticated',jsonb_build_object('provider','email','providers',ARRAY['email']),jsonb_build_object('email',lower(p_email)),now(),now(),encode(extensions.gen_random_bytes(32),'hex'),'','','','','','',false,false);
  INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at) VALUES (gen_random_uuid(),v_uid,lower(p_email),jsonb_build_object('sub',v_uid::text,'email',lower(p_email),'email_verified',true),'email',now(),now(),now());
  IF v_profile_id IS NULL THEN INSERT INTO public.profiles (id,auth_user_id,email,name,role,active) VALUES (v_uid,v_uid,lower(p_email),split_part(lower(p_email),'@',1),'admin',true);
  ELSE UPDATE public.profiles SET auth_user_id = v_uid WHERE id = v_profile_id AND (auth_user_id IS NULL OR auth_user_id != v_uid); END IF;
  RETURN true;
EXCEPTION WHEN unique_violation THEN
  UPDATE auth.users SET encrypted_password=v_enc,email_confirmed_at=COALESCE(email_confirmed_at,now()),updated_at=now() WHERE email=lower(p_email); RETURN FOUND;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ════════════════════════════════════════════════════════════════
-- USER MANAGEMENT RPCs
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_create_auth_user(p_email text, p_name text, p_role text, p_client_id uuid DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_caller_role text; v_auth_id uuid; v_profile_id uuid; v_existing_profile uuid;
  -- 1707: the sign-in record is lower case, the identity every lookup
  -- compares against. 1715: the PROFILE keeps the address exactly as it was
  -- typed, because the profile is where every email to this person is sent.
  v_email text := lower(btrim(p_email));
  v_typed text := btrim(p_email);
  v_h jsonb := '{"admin":5,"senior":4,"standard":3,"sales":2,"marketing":1,"contractor":0,"client":0}'::jsonb;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  -- BYO is single-tenant; no tenant_id column. All profiles belong to this
  -- one tenant by definition, so duplicate-email checks are global.
  SELECT role INTO v_caller_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active=true LIMIT 1;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin','senior') THEN RETURN jsonb_build_object('error','Not authorized'); END IF;
  IF (v_h->>p_role)::int > (v_h->>v_caller_role)::int THEN RETURN jsonb_build_object('error','Cannot create user with higher privileges'); END IF;

  SELECT id INTO v_existing_profile FROM public.profiles WHERE lower(email) = v_email;
  IF v_existing_profile IS NOT NULL THEN RETURN jsonb_build_object('error','A user with this email already exists'); END IF;

  SELECT id INTO v_auth_id FROM auth.users WHERE email = v_email;
  IF v_auth_id IS NULL THEN
    v_auth_id := gen_random_uuid();
    INSERT INTO auth.users (id,instance_id,email,encrypted_password,email_confirmed_at,aud,role,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token,phone_change,phone_change_token,reauthentication_token,is_sso_user,is_anonymous) VALUES (v_auth_id,'00000000-0000-0000-0000-000000000000',v_email,extensions.crypt(gen_random_uuid()::text,extensions.gen_salt('bf')),now(),'authenticated','authenticated',jsonb_build_object('provider','email','providers',ARRAY['email']),jsonb_build_object('name',p_name),now(),now(),encode(extensions.gen_random_bytes(32),'hex'),'','','','','','',false,false);
    IF NOT EXISTS (SELECT 1 FROM auth.identities WHERE user_id = v_auth_id AND provider = 'email') THEN
      INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at) VALUES (gen_random_uuid(),v_auth_id,v_email,jsonb_build_object('sub',v_auth_id::text,'email',v_email,'email_verified',true),'email',now(),now(),now());
    END IF;
  END IF;
  v_profile_id := gen_random_uuid();
  INSERT INTO public.profiles (id, auth_user_id, email, name, role, client_id)
    VALUES (v_profile_id, v_auth_id, v_typed, p_name, p_role, p_client_id);

  RETURN jsonb_build_object('success',true,'user_id',v_profile_id,'auth_user_id',v_auth_id,'message','User created');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- rpc_restore_user: recreate a user from a backup export, PRESERVING the original
-- profile id (and auth user id where possible) so every created_by / assigned_to
-- reference in the imported data still resolves. Idempotent: if the profile id
-- already exists it is left untouched. Admin only.
CREATE OR REPLACE FUNCTION public.rpc_restore_user(
  p_profile_id uuid,
  p_email text,
  p_name text,
  p_role text,
  p_auth_user_id uuid DEFAULT NULL,
  p_client_id uuid DEFAULT NULL,
  p_active boolean DEFAULT true
) RETURNS jsonb AS $$
DECLARE v_caller_role text; v_auth_id uuid;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  SELECT role INTO v_caller_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_caller_role IS DISTINCT FROM 'admin' THEN RETURN jsonb_build_object('error','Not authorized'); END IF;
  IF p_profile_id IS NULL OR p_email IS NULL OR p_email = '' THEN RETURN jsonb_build_object('error','profile id and email required'); END IF;
  -- Never restore a role higher than the caller (no privilege escalation).
  IF (('{"admin":5,"senior":4,"standard":3,"sales":2,"marketing":1,"contractor":0,"client":0}'::jsonb)->>COALESCE(NULLIF(p_role,''),'standard'))::int
     > (('{"admin":5,"senior":4,"standard":3,"sales":2,"marketing":1,"contractor":0,"client":0}'::jsonb)->>v_caller_role)::int
  THEN RETURN jsonb_build_object('error','Cannot restore a user with a higher role'); END IF;

  -- Already restored? leave it alone.
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_profile_id) THEN
    RETURN jsonb_build_object('success',true,'skipped',true,'reason','profile exists');
  END IF;

  -- Resolve or create the auth user, keeping the original id when free.
  v_auth_id := NULL;
  IF p_auth_user_id IS NOT NULL THEN
    SELECT id INTO v_auth_id FROM auth.users WHERE id = p_auth_user_id;
  END IF;
  IF v_auth_id IS NULL THEN
    SELECT id INTO v_auth_id FROM auth.users WHERE lower(email) = lower(p_email);
  END IF;
  IF v_auth_id IS NULL THEN
    v_auth_id := COALESCE(p_auth_user_id, gen_random_uuid());
    -- 1715: the sign-in record in lower case, like every other account; the
    -- profile below keeps the address as it was saved.
    INSERT INTO auth.users (id,instance_id,email,encrypted_password,email_confirmed_at,aud,role,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token,phone_change,phone_change_token,reauthentication_token,is_sso_user,is_anonymous)
      VALUES (v_auth_id,'00000000-0000-0000-0000-000000000000',lower(btrim(p_email)),extensions.crypt(gen_random_uuid()::text,extensions.gen_salt('bf')),now(),'authenticated','authenticated',jsonb_build_object('provider','email','providers',ARRAY['email']),jsonb_build_object('name',p_name),now(),now(),encode(extensions.gen_random_bytes(32),'hex'),'','','','','','',false,false);
    IF NOT EXISTS (SELECT 1 FROM auth.identities WHERE user_id = v_auth_id AND provider = 'email') THEN
      INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at)
        VALUES (gen_random_uuid(),v_auth_id,lower(btrim(p_email)),jsonb_build_object('sub',v_auth_id::text,'email',lower(btrim(p_email)),'email_verified',true),'email',now(),now(),now());
    END IF;
  END IF;

  -- Recreate the profile with its ORIGINAL id.
  INSERT INTO public.profiles (id, auth_user_id, email, name, role, client_id, active)
    VALUES (p_profile_id, v_auth_id, p_email, p_name, COALESCE(NULLIF(p_role,''),'standard'), p_client_id, COALESCE(p_active, true))
    ON CONFLICT (id) DO NOTHING;

  RETURN jsonb_build_object('success',true,'user_id',p_profile_id,'auth_user_id',v_auth_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;
REVOKE EXECUTE ON FUNCTION public.rpc_restore_user(uuid,text,text,text,uuid,uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_restore_user(uuid,text,text,text,uuid,uuid,boolean) TO authenticated;

CREATE OR REPLACE FUNCTION public.rpc_delete_auth_user(p_user_id uuid) RETURNS jsonb AS $$
DECLARE v_cr text; v_tr text; v_auth_id uuid; v_remaining int;
  v_h jsonb := '{"admin":5,"senior":4,"standard":3,"sales":2,"marketing":1,"contractor":0,"client":0}'::jsonb;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  SELECT role INTO v_cr FROM public.profiles WHERE auth_user_id = auth.uid() AND active=true LIMIT 1;
  IF v_cr IS NULL OR v_cr NOT IN ('admin','senior') THEN RETURN jsonb_build_object('error','Not authorized'); END IF;
  SELECT role, auth_user_id INTO v_tr, v_auth_id FROM public.profiles WHERE id = p_user_id;
  IF v_tr IS NULL THEN RETURN jsonb_build_object('error','User not found'); END IF;
  IF (v_h->>v_tr)::int >= (v_h->>v_cr)::int THEN RETURN jsonb_build_object('error','Cannot delete users with equal or higher roles'); END IF;
  DELETE FROM public.profiles WHERE id = p_user_id;
  IF v_auth_id IS NOT NULL THEN
    SELECT count(*) INTO v_remaining FROM public.profiles WHERE auth_user_id = v_auth_id;
    IF v_remaining = 0 THEN
      DELETE FROM auth.identities WHERE user_id = v_auth_id; DELETE FROM auth.sessions WHERE user_id = v_auth_id;
      DELETE FROM auth.refresh_tokens WHERE user_id = v_auth_id::text; DELETE FROM auth.mfa_factors WHERE user_id = v_auth_id;
      DELETE FROM auth.users WHERE id = v_auth_id;
    END IF;
  END IF;
  RETURN jsonb_build_object('success',true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- 1810: an administrator's cleanup after rpc_admin_delete_profile, never
-- Pental's. It took the provisioning secret alone, which is Pental's, and
-- deleted any user's profile and sign-in account outright. Now it takes an
-- admin or senior session with a fresh factor, and only removes a sign-in
-- account that no profile refers to any more (the profile itself is deleted
-- by rpc_admin_delete_profile, with its hierarchy rules). p_secret is kept
-- for older callers and ignored.
CREATE OR REPLACE FUNCTION public.rpc_hard_delete_auth_user(p_auth_id uuid, p_secret text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh()
     OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true AND role IN ('admin', 'senior')) THEN
    RETURN jsonb_build_object('error', 'Admin session required');
  END IF;
  IF p_auth_id = auth.uid() THEN RETURN jsonb_build_object('error', 'Cannot delete your own sign-in'); END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = p_auth_id) THEN
    RETURN jsonb_build_object('error', 'A profile still uses this sign-in; delete the user first');
  END IF;
  BEGIN DELETE FROM auth.identities WHERE user_id = p_auth_id; EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN DELETE FROM auth.sessions WHERE user_id = p_auth_id; EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN DELETE FROM auth.refresh_tokens WHERE user_id = p_auth_id; EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN DELETE FROM auth.mfa_factors WHERE user_id = p_auth_id; EXCEPTION WHEN OTHERS THEN NULL; END;
  BEGIN DELETE FROM auth.users WHERE id = p_auth_id; EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.rpc_cleanup_orphan_auth(p_email text) RETURNS jsonb AS $$
DECLARE v_auth_id uuid; v_profile_exists boolean;
BEGIN
  IF p_email IS NULL OR p_email = '' THEN RETURN jsonb_build_object('error', 'Email required'); END IF;
  SELECT EXISTS(SELECT 1 FROM public.profiles WHERE lower(email) = lower(p_email)) INTO v_profile_exists;
  IF v_profile_exists THEN RETURN jsonb_build_object('skipped', true, 'reason', 'Profile still exists'); END IF;
  SELECT id INTO v_auth_id FROM auth.users WHERE email = lower(p_email);
  IF v_auth_id IS NULL THEN RETURN jsonb_build_object('skipped', true, 'reason', 'No auth user found'); END IF;
  DELETE FROM auth.identities WHERE user_id = v_auth_id; DELETE FROM auth.sessions WHERE user_id = v_auth_id;
  DELETE FROM auth.refresh_tokens WHERE user_id = v_auth_id; DELETE FROM auth.mfa_factors WHERE user_id = v_auth_id;
  DELETE FROM auth.users WHERE id = v_auth_id;
  RETURN jsonb_build_object('success', true, 'deleted_user_id', v_auth_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ════════════════════════════════════════════════════════════════
-- CLIENT / PROPOSAL RPCs
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_create_client(p_name text, p_industry text DEFAULT '', p_contact_name text DEFAULT '', p_contact_email text DEFAULT '', p_contact_phone text DEFAULT '', p_job_code text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE _role text; _row clients%ROWTYPE;
BEGIN
  -- 1943: the role every rule reads (a contractor while contractors are off is
  -- nobody), and the second factor fresh, as clients_insert asks.
  _role := public.current_user_role();
  IF _role IS NULL OR _role NOT IN ('admin','senior','contractor','standard') THEN RAISE EXCEPTION 'Not authorized'; END IF;
  PERFORM public._need_fresh_mfa();
  INSERT INTO clients (name,industry,contact_name,contact_email,contact_phone,job_code,created_by) VALUES (p_name,p_industry,p_contact_name,p_contact_email,p_contact_phone,p_job_code,public.current_profile_id()) RETURNING * INTO _row;
  RETURN to_jsonb(_row);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_create_client_profile(p_email text, p_name text, p_client_id uuid) RETURNS void AS $$
DECLARE _role text;
BEGIN
  -- 1943: A PORTAL LOGIN FOR A CLIENT IS MADE BY WHOEVER DOES THAT CLIENT'S
  -- BUSINESS. A contractor could make one for any client by its id, which is a
  -- sign-in to that client's reports for an address of the contractor's
  -- choosing; now only for a client they brought (can_access_client), with the
  -- second factor fresh, and never while contractors are off.
  _role := public.current_user_role();
  IF _role IS NULL OR _role NOT IN ('admin','senior','contractor') THEN RAISE EXCEPTION 'Not authorized'; END IF;
  PERFORM public._need_fresh_mfa();
  IF p_client_id IS NULL OR NOT public.can_access_client(p_client_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  INSERT INTO profiles (id,email,name,role,client_id) VALUES (gen_random_uuid(),lower(p_email),p_name,'client',p_client_id) ON CONFLICT (email) DO NOTHING;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_create_proposal(p_data jsonb) RETURNS jsonb AS $$
DECLARE _role text; _row proposals%ROWTYPE;
BEGIN
  -- 1943: the role every rule reads, the second factor fresh (proposals_insert
  -- asks both), a contractor's only for a client they brought, and whoever made
  -- it recorded (it was left empty, so a contractor could not read back the
  -- proposal they had just written).
  _role := public.current_user_role();
  IF _role IS NULL OR _role = 'none' THEN RAISE EXCEPTION 'No profile found'; END IF;
  IF _role NOT IN ('admin','senior','contractor') THEN RAISE EXCEPTION 'Role % not authorized', _role; END IF;
  PERFORM public._need_fresh_mfa();
  IF _role = 'contractor' AND NOT public.can_access_client(NULLIF(p_data->>'client_id', '')::uuid) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  INSERT INTO proposals (title,type,scope,cost,test_days,start_date,end_date,status,client_id,job_code,created_by) VALUES (p_data->>'title',p_data->>'type',p_data->>'scope',(p_data->>'cost')::numeric,(p_data->>'test_days')::integer,NULLIF(p_data->>'start_date','')::date,NULLIF(p_data->>'end_date','')::date,COALESCE(p_data->>'status','draft'),(p_data->>'client_id')::uuid,p_data->>'job_code',public.current_profile_id()) RETURNING * INTO _row;
  RETURN to_jsonb(_row);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

DROP FUNCTION IF EXISTS public.rpc_sign_proposal(uuid, text, text);
-- 1839: signed with the second factor fresh (as reading the proposal needs);
-- only a proposal waiting for a signature (the firm's own people may sign a
-- draft on the client's behalf), and one signed already is said, not signed
-- twice; the price, days and deal as signed are kept (signed_cost,
-- signed_test_days, signed_deal_structure); the rest of a multi-year or
-- subscription deal is made here, whoever signs (_proposal_deal_items: the
-- client's browser may not make it); and the timeline names the person by
-- their profile (its user_id is a profile; auth.uid() is not one, and the
-- line failed the engagement it was written for). The engagement it makes is
-- the one the firm's own signing made: the proposal's phases and notes, the
-- first year's or period's label on a deal, and as its lead the contractor
-- who signs, or who sent the proposal. Where the engagement already exists
-- (p_skip_assessment) it is the proposal's, or the one made from it.
-- 1841: THE ADDRESS A PROPOSAL WAS SIGNED FROM, AS THIS DATABASE'S OWN
-- SERVER SAW IT. A client signed through Pental's route (api/utils,
-- fn=sign-proposal) only so that the route could add the address the request
-- came from, which put the signature and the signer's details on Pental's
-- servers. The portal now asks rpc_sign_proposal itself, and the address is
-- read here: what the gateway saw (pental.client_ip, from 1.10.0, a setting
-- no caller can make), else what the platform in front of this database
-- adds (Supabase: Cloudflare's cf-connecting-ip, then x-real-ip, then the
-- first of x-forwarded-for). The caller's own p_sign_ip is kept only where
-- none says.
CREATE OR REPLACE FUNCTION public._request_ip() RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $reqip$
DECLARE h jsonb; v text;
BEGIN
  v := btrim(COALESCE(current_setting('pental.client_ip', true), ''));
  IF v = '' THEN
    BEGIN
      h := NULLIF(current_setting('request.headers', true), '')::jsonb;
    EXCEPTION WHEN OTHERS THEN h := NULL; END;
    IF h IS NOT NULL AND jsonb_typeof(h) = 'object' THEN
      v := btrim(COALESCE(NULLIF(h ->> 'cf-connecting-ip', ''), NULLIF(h ->> 'x-real-ip', ''),
                          split_part(COALESCE(h ->> 'x-forwarded-for', ''), ',', 1), ''));
    END IF;
  END IF;
  IF v IS NULL OR v = '' OR length(v) > 64 OR v !~ '^[0-9A-Fa-f:.]+$' THEN RETURN NULL; END IF;
  RETURN v;
END $reqip$;
REVOKE ALL ON FUNCTION public._request_ip() FROM PUBLIC, anon, authenticated;

-- 1846: WHAT WAS WRITTEN ON THE PROPOSAL GOES WITH IT. A section a firm shows
-- on a new proposal ("On new": the caveats, and its own sections) was written
-- there and left there: the engagement the signature made had the notes and
-- nothing else, so it was written again or lost. The engagement takes the
-- proposal's own sections and its client-visible switches, which the proposal
-- keeps beside them as `_cv_<key>` and an engagement keeps under the key it
-- shows each by (`client_section_visibility`: `summary_<id>` for a firm's own
-- section, as _smVisKey). { sections, vis }.
CREATE OR REPLACE FUNCTION public._proposal_engagement_sections(p_ss jsonb) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = public, pg_catalog, pg_temp AS $pes$
  WITH e AS (
    SELECT x.key, x.value FROM jsonb_each(CASE WHEN jsonb_typeof(p_ss) = 'object' THEN p_ss ELSE '{}'::jsonb END) x
  ), own AS (
    SELECT c ->> 'id' AS id FROM public.settings s, jsonb_array_elements(CASE WHEN jsonb_typeof(s.summary_fields -> 'custom') = 'array' THEN s.summary_fields -> 'custom' ELSE '[]'::jsonb END) c
  )
  SELECT jsonb_build_object(
    'sections', COALESCE((SELECT jsonb_object_agg(e.key, e.value) FROM e WHERE e.key NOT LIKE '\_cv\_%' AND jsonb_typeof(e.value) = 'string'), '{}'::jsonb),
    'vis', COALESCE((SELECT jsonb_object_agg(
              CASE WHEN substr(e.key, 5) = 'executive_summary' THEN 'exec_summary'
                   WHEN substr(e.key, 5) LIKE 'cs\_%' OR substr(e.key, 5) IN (SELECT id FROM own) THEN 'summary_' || substr(e.key, 5)
                   ELSE substr(e.key, 5) END, e.value)
            FROM e WHERE e.key LIKE '\_cv\_%' AND jsonb_typeof(e.value) = 'boolean'), '{}'::jsonb));
$pes$;
REVOKE ALL ON FUNCTION public._proposal_engagement_sections(jsonb) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_sign_proposal(p_proposal_id uuid, p_signed_by text, p_signature_data text, p_start_date date DEFAULT NULL, p_end_date date DEFAULT NULL, p_job_code text DEFAULT NULL, p_test_perspective text DEFAULT 'unauthenticated', p_source_assessment_id uuid DEFAULT NULL, p_skip_assessment boolean DEFAULT false, p_sign_ip text DEFAULT NULL, p_sign_user_agent text DEFAULT NULL, p_sign_email text DEFAULT NULL, p_sign_consent_text text DEFAULT NULL, p_sign_document_hash text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_cid uuid; v_role text; v_ccid uuid; v_p record; v_aid uuid; v_clone uuid; v_src record; v_cloned boolean := false; v_fc integer := 0; v_f record; v_tp text; v_n integer := 0;
  v_me uuid; v_deal jsonb; v_ds jsonb; v_label text := ''; v_lead uuid; v_years integer; v_secs jsonb;
BEGIN
  v_cid := auth.uid(); IF v_cid IS NULL THEN RETURN jsonb_build_object('error','Not authenticated'); END IF;
  SELECT id,role,client_id INTO v_me,v_role,v_ccid FROM public.profiles WHERE auth_user_id=v_cid AND active=true;
  -- 1798: an active profile is required. Without this a signed-in session with
  -- no profile (a public sign-up, a deactivated user) had v_role NULL, and the
  -- client check below is the only gate, so NULL sailed past it and signed any
  -- proposal. No profile, no signing.
  IF v_role IS NULL THEN RETURN jsonb_build_object('error','Not authorized'); END IF;
  -- 1839: the people who may change a proposal (proposals_update), and the
  -- client it is for. A tester or someone in sales or marketing may not
  -- sign one by its id.
  IF v_role NOT IN ('admin','senior','contractor','client') THEN RETURN jsonb_build_object('error','Not authorized'); END IF;
  IF NOT public.mfa_is_fresh() THEN RETURN jsonb_build_object('error','Confirm your sign-in again (your second factor), then sign.'); END IF;
  SELECT * INTO v_p FROM public.proposals WHERE id=p_proposal_id FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('error','Proposal not found'); END IF;
  IF v_role='client' AND v_ccid IS DISTINCT FROM v_p.client_id THEN RETURN jsonb_build_object('error','Not authorized'); END IF;
  IF v_p.status = 'signed' THEN RETURN jsonb_build_object('success',true,'already',true,'assessment_id',v_p.assessment_id,'cloned',false); END IF;
  IF v_p.status NOT IN ('pending_signature','draft') OR (v_role='client' AND v_p.status <> 'pending_signature') THEN
    RETURN jsonb_build_object('error','This proposal is not waiting for a signature.');
  END IF;
  -- 1943: the engagement a contractor's signature copies is one of theirs (the
  -- proposal's own is held by _contractor_guard_proposal; this is the one asked
  -- for at signing).
  IF v_role = 'contractor' AND p_source_assessment_id IS NOT NULL
     AND NOT public.can_access_assessment(p_source_assessment_id) THEN
    RETURN jsonb_build_object('error','You can copy only an engagement of yours.');
  END IF;
  UPDATE public.proposals SET status='signed',signed_by=p_signed_by,signature_data=p_signature_data,signed_at=now(),sign_ip=COALESCE(public._request_ip(), NULLIF(btrim(COALESCE(p_sign_ip, '')), '')),sign_user_agent=p_sign_user_agent,sign_email=p_sign_email,sign_user_id=v_cid,sign_consent_text=p_sign_consent_text,sign_document_hash=p_sign_document_hash,
         signed_cost=cost,signed_test_days=test_days,signed_deal_structure=deal_structure WHERE id=p_proposal_id;
  IF p_skip_assessment OR v_p.assessment_id IS NOT NULL THEN
    v_aid := COALESCE(v_p.assessment_id, (SELECT a.id FROM public.assessments a WHERE a.proposal_id = p_proposal_id
                                           ORDER BY a.created_at ASC NULLS LAST, a.id LIMIT 1));
    IF v_aid IS NOT NULL THEN
      IF v_p.assessment_id IS NULL THEN UPDATE public.proposals SET assessment_id = v_aid WHERE id = p_proposal_id; END IF;
      INSERT INTO public.timeline_events(assessment_id,event,user_id,title) VALUES(v_aid,'Contract signed by '||p_signed_by,v_me,'Contract signed');
    END IF;
    v_deal := public._proposal_deal_items(p_proposal_id, v_aid, p_start_date, p_end_date, p_job_code, v_me);
    RETURN jsonb_build_object('success',true,'assessment_id',v_aid,'cloned',false,'deal',v_deal);
  END IF;
  v_ds := COALESCE(v_p.signed_deal_structure, v_p.deal_structure);
  IF jsonb_typeof(v_ds) = 'object' AND v_ds ->> 'type' = 'multi_year' THEN
    v_years := LEAST(GREATEST(COALESCE(CASE WHEN COALESCE(v_ds ->> 'years', '') ~ '^[0-9]{1,2}$' THEN (v_ds ->> 'years')::integer END, 2), 1), 10);
    v_label := ' (Year 1/' || v_years || ')';
  ELSIF jsonb_typeof(v_ds) = 'object' AND v_ds ->> 'type' = 'subscription' THEN
    v_label := CASE WHEN v_ds ->> 'frequency' = 'quarterly' THEN ' (Q1)' ELSE ' (Period 1)' END;
  END IF;
  v_lead := CASE WHEN v_role = 'contractor' THEN v_me
                 ELSE (SELECT pr.id FROM public.profiles pr WHERE pr.id = v_p.sent_by AND pr.role = 'contractor' AND pr.active IS NOT FALSE) END;
  v_clone := COALESCE(p_source_assessment_id,v_p.source_assessment_id);
  v_tp := CASE WHEN p_test_perspective='authenticated' THEN 'authenticated' ELSE 'unauthenticated' END;
  -- 1846: the proposal's own sections and caveats go with it.
  v_secs := public._proposal_engagement_sections(v_p.summary_sections);
  IF v_clone IS NOT NULL THEN
    -- 1798: only an assessment of the same customer is copied. The id can come
    -- from the caller (p_source_assessment_id), and copying another customer's
    -- engagement would put its findings under this one.
    SELECT * INTO v_src FROM public.assessments WHERE id=v_clone AND client_id=v_p.client_id;
    IF FOUND THEN
      INSERT INTO public.assessments(client_id,name,type,status,start_date,end_date,job_code,test_perspective,credentials_status,lead_id,proposal_id,scanning_enabled,caveats,summary_sections,client_section_visibility) VALUES(v_p.client_id,COALESCE(v_p.title,v_src.name,'Security Assessment'),COALESCE(v_p.type,v_src.type,'Security Assessment'),'draft',COALESCE(p_start_date,v_p.start_date,v_src.start_date),COALESCE(p_end_date,v_p.end_date,v_src.end_date),p_job_code,COALESCE(v_tp,v_src.test_perspective,'unauthenticated'),CASE WHEN COALESCE(v_tp,v_src.test_perspective)='authenticated' THEN 'awaiting' ELSE 'none' END,v_src.lead_id,p_proposal_id,COALESCE(v_p.scanning_enabled,false),COALESCE(v_p.caveats,''),v_secs -> 'sections',(v_secs -> 'vis')::text) RETURNING id INTO v_aid; v_cloned := true;
      FOR v_f IN SELECT * FROM public.findings WHERE assessment_id=v_clone ORDER BY created_at LOOP
        -- 1841: with its CVSS vector (it was left behind, so every finding of a
        -- re-signed engagement printed a score with no vector), its impact and
        -- the firm's own fields.
        v_n:=v_n+1; INSERT INTO public.findings(assessment_id,title,severity,status,cvss,cvss_vector,cwe,category,description,impact,remediation,evidence,affected_hosts,client_visible,refs,custom_fields,created_by,finding_code) VALUES(v_aid,v_f.title,v_f.severity,COALESCE(v_f.status,'open'),v_f.cvss,v_f.cvss_vector,v_f.cwe,v_f.category,v_f.description,v_f.impact,v_f.remediation,v_f.evidence,v_f.affected_hosts,COALESCE(v_f.client_visible,true),v_f.refs,COALESCE(v_f.custom_fields,'{}'::jsonb),v_f.created_by,CASE WHEN p_job_code IS NOT NULL THEN p_job_code||'-'||LPAD(v_n::text,2,'0') ELSE NULL END); v_fc:=v_fc+1;
      END LOOP;
      UPDATE public.proposals SET assessment_id=v_aid WHERE id=p_proposal_id;
      INSERT INTO public.timeline_events(assessment_id,event,user_id,title) VALUES(v_aid,'Contract signed by '||p_signed_by||' (cloned, '||v_fc||' findings)',v_me,'Contract signed');
    END IF;
  END IF;
  IF v_aid IS NULL THEN
    INSERT INTO public.assessments(client_id,name,type,status,start_date,end_date,job_code,test_perspective,credentials_status,proposal_id,scanning_enabled,phases,notes,lead_id,caveats,summary_sections,client_section_visibility)
    VALUES(v_p.client_id,COALESCE(NULLIF(v_p.title,''),'Security Assessment')||v_label,COALESCE(v_p.type,'Security Assessment'),'draft',COALESCE(p_start_date,v_p.start_date),COALESCE(p_end_date,v_p.end_date),p_job_code,v_tp,CASE WHEN v_tp='authenticated' THEN 'awaiting' ELSE 'none' END,p_proposal_id,COALESCE(v_p.scanning_enabled,false),
           CASE WHEN jsonb_typeof(v_p.phases) = 'array' AND jsonb_array_length(v_p.phases) > 0 THEN v_p.phases END,COALESCE(v_p.notes,''),v_lead,COALESCE(v_p.caveats,''),v_secs -> 'sections',(v_secs -> 'vis')::text) RETURNING id INTO v_aid;
    UPDATE public.proposals SET assessment_id=v_aid WHERE id=p_proposal_id;
    INSERT INTO public.timeline_events(assessment_id,event,user_id,title) VALUES(v_aid,'Contract signed by '||p_signed_by,v_me,'Contract signed');
  END IF;
  v_deal := public._proposal_deal_items(p_proposal_id, v_aid, p_start_date, p_end_date, p_job_code, v_me);
  RETURN jsonb_build_object('success',true,'assessment_id',v_aid,'cloned',v_cloned,'findings_cloned',v_fc,'deal',v_deal);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- ════════════════════════════════════════════════════════════════
-- CREDENTIAL RPCs
-- ════════════════════════════════════════════════════════════════

-- 1709: an email template's placeholders, filled in the database. The same
-- rule as the email kit (pentalportal/api/_email-kit.js): {{name}} becomes the
-- value, escaped for HTML in a body and as it is in a subject; a placeholder
-- with no value goes, except the portal's address, which only the mail sender
-- knows and fills.
CREATE OR REPLACE FUNCTION public._email_fill(p_tpl text, p_vars jsonb, p_html boolean)
RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $ef$
DECLARE k text; v text; o text := COALESCE(p_tpl, '');
BEGIN
  FOR k, v IN SELECT key, value FROM jsonb_each_text(COALESCE(p_vars, '{}'::jsonb)) LOOP
    v := COALESCE(v, '');
    IF p_html THEN
      v := replace(replace(replace(replace(replace(v, '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;');
    END IF;
    o := replace(o, '{{' || k || '}}', v);
  END LOOP;
  o := regexp_replace(o, '\{\{\s*(?!action_url\s*\}\}|portal_url\s*\}\})[a-z0-9_]+\s*\}\}', '', 'gi');
  IF NOT p_html THEN o := btrim(regexp_replace(o, '\s+', ' ', 'g')); END IF;
  RETURN o;
END $ef$;
REVOKE ALL ON FUNCTION public._email_fill(text, jsonb, boolean) FROM PUBLIC, anon, authenticated;

-- 1798: the ownership tests in the four credential functions are NULL-safe.
-- `lead_id != me` is not true when the engagement has no lead, and
-- `client_id != mine` is not true when the caller has no organisation, so
-- both refusals were skipped. IS DISTINCT FROM, and no organisation, no access.
-- 1841: A CLIENT'S CREDENTIALS NEVER PASS THROUGH PENTAL'S SERVERS. [stated]
-- Arian: "if pental were breached, their data shouldnt be readable". The
-- portal asked Pental's route (api/utils, fn=credentials), which called these
-- functions with the person's session and handed the decrypted logins and
-- files back; the portal now asks these itself. What the route added is here:
-- the list a tester first opens names and sizes each file and carries none of
-- their contents (_cred_strip_files); one file is read on its own
-- (p_cred_index, p_file_index); and what a client sends is checked as it
-- arrives (_cred_clean, in rpc_credentials_submit).
CREATE OR REPLACE FUNCTION public._cred_strip_files(p_list jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $credstrip$
  SELECT CASE WHEN jsonb_typeof(p_list) IS DISTINCT FROM 'array' THEN p_list ELSE COALESCE((
    SELECT jsonb_agg(CASE WHEN jsonb_typeof(t.e) = 'object' AND jsonb_typeof(t.e -> 'files') = 'array'
        THEN t.e || jsonb_build_object('files', (
          SELECT COALESCE(jsonb_agg(jsonb_build_object('name', x.f -> 'name', 'type', x.f -> 'type', 'size', x.f -> 'size') ORDER BY x.o), '[]'::jsonb)
            FROM jsonb_array_elements(t.e -> 'files') WITH ORDINALITY x(f, o)))
        ELSE t.e END ORDER BY t.o)
      FROM jsonb_array_elements(p_list) WITH ORDINALITY t(e, o)), '[]'::jsonb) END
$credstrip$;
REVOKE ALL ON FUNCTION public._cred_strip_files(jsonb) FROM PUBLIC, anon, authenticated;

-- What a client sends, checked and kept as Pental's route kept it: up to 10
-- files and 3 MB of them, each named safely and typed, and up to 500 logins
-- of a role, user name, password, MFA and notes, each a string. A row with
-- neither a user name nor a password is dropped. 22023, said in words.
CREATE OR REPLACE FUNCTION public._cred_clean(p_credential jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $credclean$
DECLARE v_out jsonb; v_f jsonb; v_b64 text; v_total bigint := 0; v_bytes bigint; v_name text; v_type text;
  v_files jsonb := '[]'::jsonb; v_accs jsonb := '[]'::jsonb; v_a jsonb; v_row jsonb; v_k text;
BEGIN
  IF p_credential IS NULL OR jsonb_typeof(p_credential) <> 'object' THEN
    RAISE EXCEPTION 'Missing credential data' USING ERRCODE = '22023';
  END IF;
  v_out := p_credential;
  IF jsonb_typeof(p_credential -> 'files') IS NOT NULL AND jsonb_typeof(p_credential -> 'files') <> 'null' THEN
    IF jsonb_typeof(p_credential -> 'files') <> 'array' OR jsonb_array_length(p_credential -> 'files') > 10 THEN
      RAISE EXCEPTION 'Up to 10 files can be sent at once' USING ERRCODE = '22023';
    END IF;
    FOR v_f IN SELECT e FROM jsonb_array_elements(p_credential -> 'files') e LOOP
      IF jsonb_typeof(v_f) IS DISTINCT FROM 'object' OR jsonb_typeof(v_f -> 'b64') IS DISTINCT FROM 'string'
         OR (v_f ->> 'b64') !~ '^[A-Za-z0-9+/]*={0,2}$' THEN
        RAISE EXCEPTION 'A file could not be read' USING ERRCODE = '22023';
      END IF;
      v_b64 := v_f ->> 'b64';
      v_bytes := floor(length(v_b64) * 3 / 4.0)::bigint - CASE WHEN v_b64 LIKE '%==' THEN 2 WHEN v_b64 LIKE '%=' THEN 1 ELSE 0 END;
      v_total := v_total + v_bytes;
      -- The route's String(f.name || 'file'): text that is not empty, or a
      -- number that is not nought; anything else is 'file'.
      v_name := CASE WHEN jsonb_typeof(v_f -> 'name') = 'string' AND (v_f ->> 'name') <> '' THEN v_f ->> 'name'
                     WHEN jsonb_typeof(v_f -> 'name') = 'number' AND (v_f ->> 'name')::numeric <> 0 THEN v_f ->> 'name'
                     ELSE 'file' END;
      v_name := left(regexp_replace(v_name, '[\x01-\x1f\\/:*?"<>|]+', '_', 'g'), 200);
      IF v_name = '' THEN v_name := 'file'; END IF;
      v_type := CASE WHEN COALESCE(v_f ->> 'type', '') ~ '^[A-Za-z0-9_.+-]+/[A-Za-z0-9_.+-]+$' THEN v_f ->> 'type' ELSE 'application/octet-stream' END;
      v_files := v_files || jsonb_build_array(jsonb_build_object('name', v_name, 'type', v_type, 'size', v_bytes, 'b64', v_b64));
    END LOOP;
    IF v_total > 3 * 1024 * 1024 THEN
      RAISE EXCEPTION 'Files for credentials can be up to 3 MB in total' USING ERRCODE = '22023';
    END IF;
    v_out := v_out || jsonb_build_object('files', v_files);
  END IF;
  IF jsonb_typeof(p_credential -> 'accounts') IS NOT NULL AND jsonb_typeof(p_credential -> 'accounts') <> 'null' THEN
    IF jsonb_typeof(p_credential -> 'accounts') <> 'array' OR jsonb_array_length(p_credential -> 'accounts') > 500 THEN
      RAISE EXCEPTION 'Up to 500 accounts can be sent at once' USING ERRCODE = '22023';
    END IF;
    FOR v_a IN SELECT e FROM jsonb_array_elements(p_credential -> 'accounts') e LOOP
      IF jsonb_typeof(v_a) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'An account could not be read' USING ERRCODE = '22023';
      END IF;
      v_row := '{}'::jsonb;
      FOREACH v_k IN ARRAY ARRAY['role', 'username', 'password', 'mfa', 'notes'] LOOP
        IF jsonb_typeof(v_a -> v_k) IS NULL OR jsonb_typeof(v_a -> v_k) = 'null' OR (v_a -> v_k) = '""'::jsonb THEN CONTINUE; END IF;
        IF jsonb_typeof(v_a -> v_k) <> 'string' OR length(v_a ->> v_k) > 4000 THEN
          RAISE EXCEPTION 'An account could not be read' USING ERRCODE = '22023';
        END IF;
        v_row := v_row || jsonb_build_object(v_k, v_a ->> v_k);
      END LOOP;
      IF v_row ? 'username' OR v_row ? 'password' THEN v_accs := v_accs || jsonb_build_array(v_row); END IF;
    END LOOP;
    v_out := CASE WHEN jsonb_array_length(v_accs) > 0 THEN v_out || jsonb_build_object('accounts', v_accs) ELSE v_out - 'accounts' END;
  END IF;
  RETURN v_out;
END $credclean$;
REVOKE ALL ON FUNCTION public._cred_clean(jsonb) FROM PUBLIC, anon, authenticated;

DROP FUNCTION IF EXISTS public.rpc_credentials_read(uuid);
CREATE OR REPLACE FUNCTION public.rpc_credentials_read(p_assessment_id uuid, p_cred_index integer DEFAULT NULL, p_file_index integer DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_role text; v_ass record; v_key text; v_dec text; v_list jsonb; v_f jsonb;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  -- 1943: the role every rule reads; a contractor's engagement is one they lead
  -- or one handed to their team.
  v_role := public.current_user_role();
  IF v_role IS NULL OR v_role NOT IN ('admin','senior','standard','contractor') THEN RETURN jsonb_build_object('error','Access denied'); END IF;
  SELECT * INTO v_ass FROM public.assessments WHERE id=p_assessment_id; IF NOT FOUND THEN RETURN jsonb_build_object('error','Assessment not found'); END IF;
  IF v_role='contractor' AND NOT public.can_access_assessment(p_assessment_id) THEN RETURN jsonb_build_object('error','Not the assigned tester'); END IF;
  IF v_ass.credentials_data IS NULL OR (v_ass.credentials_data::jsonb)->>'enc' IS NULL THEN RETURN jsonb_build_object('error','No credentials available'); END IF;
  v_key := public._get_cred_key();
  BEGIN v_dec := extensions.pgp_sym_decrypt(decode((v_ass.credentials_data::jsonb)->>'enc','base64'),v_key); EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error','Could not decrypt'); END;
  v_list := v_dec::jsonb;
  -- 1841: one file, for the tester downloading it.
  IF p_cred_index IS NOT NULL OR p_file_index IS NOT NULL THEN
    IF p_cred_index IS NULL OR p_file_index IS NULL OR p_cred_index < 0 OR p_file_index < 0 THEN
      RETURN jsonb_build_object('error','Missing file');
    END IF;
    IF jsonb_typeof(v_list) <> 'array' THEN v_list := jsonb_build_array(v_list); END IF;
    v_f := v_list -> p_cred_index -> 'files' -> p_file_index;
    IF jsonb_typeof(v_f) IS DISTINCT FROM 'object' OR jsonb_typeof(v_f -> 'b64') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('error','That file is no longer there');
    END IF;
    RETURN jsonb_build_object('success', true, 'name', v_f -> 'name', 'type', v_f -> 'type', 'size', v_f -> 'size', 'b64', v_f -> 'b64');
  END IF;
  RETURN jsonb_build_object('success',true,'credentials',public._cred_strip_files(v_list));
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;
REVOKE ALL ON FUNCTION public.rpc_credentials_read(uuid, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_credentials_read(uuid, integer, integer) TO authenticated;

-- 1721: WHAT HAS BEEN RECEIVED STAYS ON THE RECORD. [stated] Arian: "for
-- credentials, after downloading and deleting it still says 1 received when 2
-- were uploaded and received for example".
--
-- The list a tester opens is deleted when they confirm, and `meta`, the only
-- record of what was sent, was rebuilt from whatever list is still encrypted. So
-- a client who sent one set, had it collected, and sent another was left with a
-- record of the second alone: two received, "1 received". And a submission of
-- two files was one entry, so it counted as one.
--
-- Each entry now says whether it has been received (`received`, stamped by the
-- acknowledgement) and how much it holds: `files`, and `items`, the files plus
-- one for the typed details when there are any. Collected entries are carried
-- into every later submission and removal, so the record only grows. A list
-- viewed before 1721 has no flags; with nothing waiting, all of it was received.
--
-- 1758: an entry can carry several logins (`accounts`, one row each), and each
-- is one item, as a file is; the entry's own URL and MFA go with them. The
-- record says how many (`accounts`) when there are any.
CREATE OR REPLACE FUNCTION public._cred_meta_of(p_list jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $credmeta$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'auth_type', t.e->>'auth_type', 'label', COALESCE(t.e->>'label', ''),
      'submitted_by', t.e->>'submitted_by', 'submitted_at', t.e->>'submitted_at',
      'files', f.n,
      'items', GREATEST(1, f.n + CASE WHEN f.a > 0 THEN f.a WHEN EXISTS (
          SELECT 1 FROM jsonb_each(CASE WHEN jsonb_typeof(t.e) = 'object' THEN t.e ELSE '{}'::jsonb END) kv
           WHERE kv.key NOT IN ('auth_type', 'label', 'files', 'accounts', 'notes', 'submitted_by', 'submitted_at')
             AND NULLIF(btrim(COALESCE(kv.value #>> '{}', '')), '') IS NOT NULL) THEN 1 ELSE 0 END)
    ) || CASE WHEN f.a > 0 THEN jsonb_build_object('accounts', f.a) ELSE '{}'::jsonb END ORDER BY t.o), '[]'::jsonb)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_list) = 'array' THEN p_list ELSE '[]'::jsonb END) WITH ORDINALITY t(e, o)
  CROSS JOIN LATERAL (SELECT CASE WHEN jsonb_typeof(t.e->'files') = 'array' THEN jsonb_array_length(t.e->'files') ELSE 0 END AS n,
                             CASE WHEN jsonb_typeof(t.e->'accounts') = 'array' THEN jsonb_array_length(t.e->'accounts') ELSE 0 END AS a) f
$credmeta$;
REVOKE ALL ON FUNCTION public._cred_meta_of(jsonb) FROM PUBLIC, anon, authenticated;

-- The entries of a record that have been received. `p_waiting` says whether an
-- encrypted list is still waiting to be collected; when none is, everything on
-- the record was received, flagged or not.
CREATE OR REPLACE FUNCTION public._cred_received(p_meta jsonb, p_waiting boolean) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $credrecv$
  SELECT COALESCE(jsonb_agg(CASE WHEN lower(COALESCE(t.e->>'received', '')) = 'true' THEN t.e
                                 ELSE t.e || '{"received": true}'::jsonb END ORDER BY t.o), '[]'::jsonb)
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_meta) = 'array' THEN p_meta ELSE '[]'::jsonb END) WITH ORDINALITY t(e, o)
   WHERE jsonb_typeof(t.e) = 'object'
     AND (lower(COALESCE(t.e->>'received', '')) = 'true' OR NOT COALESCE(p_waiting, false))
$credrecv$;
REVOKE ALL ON FUNCTION public._cred_received(jsonb, boolean) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_credentials_acknowledge(p_assessment_id uuid) RETURNS jsonb AS $$
DECLARE v_role text; v_ass record; v_meta jsonb;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  v_role := public.current_user_role();   -- 1943, as rpc_credentials_read
  IF v_role IS NULL OR v_role NOT IN ('admin','senior','standard','contractor') THEN RETURN jsonb_build_object('error','Access denied'); END IF;
  SELECT * INTO v_ass FROM public.assessments WHERE id=p_assessment_id; IF NOT FOUND THEN RETURN jsonb_build_object('error','Assessment not found'); END IF;
  IF v_role='contractor' AND NOT public.can_access_assessment(p_assessment_id) THEN RETURN jsonb_build_object('error','Access denied'); END IF;
  -- 1721: every entry on the record is received now, and says when.
  v_meta := COALESCE(v_ass.credentials_meta, (v_ass.credentials_data::jsonb)->'meta');
  SELECT COALESCE(jsonb_agg(CASE WHEN lower(COALESCE(t.e->>'received', '')) = 'true' THEN t.e
                                 ELSE t.e || jsonb_build_object('received', true, 'received_at', now()::text) END ORDER BY t.o), '[]'::jsonb)
    INTO v_meta
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_meta) = 'array' THEN v_meta ELSE '[]'::jsonb END) WITH ORDINALITY t(e, o)
   WHERE jsonb_typeof(t.e) = 'object';
  UPDATE public.assessments SET credentials_data=CASE WHEN jsonb_array_length(v_meta) > 0 THEN jsonb_build_object('meta',v_meta) ELSE NULL END, credentials_meta=NULLIF(v_meta, '[]'::jsonb), credentials_status='viewed', test_perspective='authenticated' WHERE id=p_assessment_id;
  RETURN jsonb_build_object('success',true,'meta',v_meta);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_credentials_submit(p_assessment_id uuid, p_credential jsonb) RETURNS jsonb AS $$
DECLARE v_role text; v_cid uuid; v_ass record; v_key text; v_list jsonb; v_enc text; v_meta jsonb; v_pid uuid; v_label text; v_company text; v_to text; v_notify boolean;
  v_tpls jsonb; v_vars jsonb; v_subject text; v_body text; v_custom text; v_what text; v_hist jsonb;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  SELECT id,role,client_id INTO v_pid,v_role,v_cid FROM public.profiles WHERE auth_user_id=auth.uid() AND active=true;
  IF v_role IS DISTINCT FROM 'client' THEN RETURN jsonb_build_object('error','Only clients can submit credentials'); END IF;
  SELECT * INTO v_ass FROM public.assessments WHERE id=p_assessment_id; IF NOT FOUND THEN RETURN jsonb_build_object('error','Assessment not found'); END IF;
  IF v_cid IS NULL OR v_ass.client_id IS DISTINCT FROM v_cid THEN RETURN jsonb_build_object('error','Access denied'); END IF;
  -- 1841: checked here, as it arrives (Pental's route did, and is retired).
  BEGIN
    p_credential := public._cred_clean(p_credential);
  EXCEPTION WHEN invalid_parameter_value THEN
    RETURN jsonb_build_object('error', SQLERRM);
  END;
  v_key := public._get_cred_key(); v_list := '[]'::jsonb;
  IF v_ass.credentials_data IS NOT NULL THEN BEGIN IF (v_ass.credentials_data::jsonb)->>'enc' IS NOT NULL THEN v_list := extensions.pgp_sym_decrypt(decode((v_ass.credentials_data::jsonb)->>'enc','base64'),v_key)::jsonb; END IF; EXCEPTION WHEN OTHERS THEN v_list := '[]'::jsonb; END; END IF;
  p_credential := p_credential || jsonb_build_object('submitted_by',(SELECT COALESCE(name,email) FROM public.profiles WHERE auth_user_id=auth.uid() AND active=true),'submitted_at',now()::text);
  v_list := v_list || jsonb_build_array(p_credential);
  v_enc := encode(extensions.pgp_sym_encrypt(v_list::text,v_key)::bytea,'base64');
  -- 1721: what was collected before stays on the record, ahead of what waits.
  v_hist := public._cred_received(COALESCE(v_ass.credentials_meta, (v_ass.credentials_data::jsonb)->'meta'),
                                  (v_ass.credentials_data::jsonb)->>'enc' IS NOT NULL);
  v_meta := v_hist || public._cred_meta_of(v_list);
  UPDATE public.assessments SET credentials_data=jsonb_build_object('enc',v_enc,'meta',v_meta), credentials_meta=v_meta, credentials_status='pending', test_perspective='authenticated' WHERE id=p_assessment_id;
  -- Add a timeline event server-side. Clients can't INSERT into
  -- timeline_events directly (RLS denies it), so the RPC does it under
  -- SECURITY DEFINER. Without this, the timeline showed nothing for
  -- client-submitted credentials.
  v_label := COALESCE(p_credential->>'label', p_credential->>'auth_type', 'credentials');
  BEGIN
    INSERT INTO public.timeline_events(assessment_id, event, user_id, title, user_name)
      VALUES (p_assessment_id, 'Client credentials submitted (' || v_label || ')', v_pid, 'Credentials submitted',
              (SELECT COALESCE(name, email) FROM public.profiles WHERE id = v_pid));
  EXCEPTION WHEN OTHERS THEN NULL; END;
  -- 1560: TELL THE TESTER. [stated] Arian: "there also needs to be notifications
  -- for the tester that credentials have been submitted etc".
  --
  -- A customer submitting credentials is the event the tester has been waiting
  -- on, and nothing said so: the portal's own note (queueEmail) records that a
  -- client CANNOT queue mail - the send route refuses a client role and RLS
  -- refuses the insert - so it has to be queued here, under SECURITY DEFINER,
  -- or it cannot be queued at all.
  --
  -- To the lead tester, and to the QA reviewer when there is one and it is
  -- somebody else. Never to the client who just typed them.
  BEGIN
    -- The switch for this already existed and nothing ever fired it: honour it
    -- rather than adding a second one. Default true, as the column declares.
    SELECT company_name, COALESCE(notify_credentials_submitted, true), email_templates
      INTO v_company, v_notify, v_tpls FROM public.settings LIMIT 1;
    -- 1709: THE FIRM'S OWN "CREDENTIALS RECEIVED" EMAIL. This wrote its own
    -- paragraphs whatever the firm had put in the credentials_submitted
    -- template, and put names into the HTML unescaped. The template and its
    -- subject are used now when the firm has edited them (a stored copy of the
    -- portal's old default counts as not edited, as it does in the portal), and
    -- the email kit's default otherwise. Values are escaped by _email_fill; the
    -- mail sender fills in the portal's address and puts the result in the
    -- firm's frame.
    -- What was shared, in words: "VPN access (Office VPN)", "files".
    v_what := CASE p_credential->>'auth_type'
        WHEN 'api_key' THEN 'an API key' WHEN 'vpn' THEN 'VPN access' WHEN 'ssh' THEN 'SSH access'
        WHEN 'certificate' THEN 'a client certificate' WHEN 'file' THEN 'files' ELSE 'credentials' END
      || CASE WHEN NULLIF(btrim(COALESCE(p_credential->>'label', '')), '') IS NOT NULL
              THEN ' (' || left(btrim(p_credential->>'label'), 120) || ')' ELSE '' END;
    v_vars := jsonb_build_object(
      'assessment_name', COALESCE(v_ass.name, 'an engagement'),
      'client_name', COALESCE((SELECT COALESCE(name, email) FROM public.profiles WHERE id = v_pid), 'The client'),
      'credential_label', v_what,
      'start_date', COALESCE(to_char(v_ass.start_date, 'FMDD Mon YYYY'), ''),
      'company_name', COALESCE(v_company, ''));
    v_custom := NULLIF(btrim(COALESCE(v_tpls->>'credentials_submitted', '')), '');
    IF v_custom IS NOT NULL AND md5(v_custom) = '19e438c9be61f2364b38bb71e6e41684' THEN v_custom := NULL; END IF;
    v_body := public._email_fill(COALESCE(v_custom,
        '<h1>Credentials received</h1>' || chr(10)
      || '<p><strong>{{client_name}}</strong> has shared {{credential_label}} for <strong>{{assessment_name}}</strong>.</p>' || chr(10)
      || '<table class="details"><tr><th>Testing starts</th><td>{{start_date}}</td></tr></table>' || chr(10)
      || '<p>They are encrypted and can be viewed once, in the Credentials and Authorisation section of the assessment. Copy or download them when you open them.</p>' || chr(10)
      || '<a class="button" href="{{action_url}}">View credentials</a>'), v_vars, true);
    v_subject := public._email_fill(COALESCE(NULLIF(btrim(COALESCE(v_tpls->'subjects'->>'credentials_submitted', '')), ''),
      'Credentials received for {{assessment_name}}'), v_vars, false);
    FOR v_to IN
      SELECT DISTINCT p.email
        FROM public.profiles p
       WHERE COALESCE(v_notify, true)
         AND p.active = true
         AND p.id IN (v_ass.lead_id, v_ass.qa_assignee)
         AND p.id IS DISTINCT FROM v_pid
         AND COALESCE(p.email, '') <> ''
    LOOP
      INSERT INTO public.email_notifications
        (to_email, subject, body, notification_type, related_id, status)
      VALUES (v_to, v_subject, v_body, 'credentials_submitted', p_assessment_id, 'pending');
    END LOOP;
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('success',true,'count',jsonb_array_length(v_list),'meta',v_meta);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_credentials_remove(p_assessment_id uuid, p_index integer) RETURNS jsonb AS $$
DECLARE v_role text; v_cid uuid; v_ass record; v_key text; v_list jsonb; v_new jsonb := '[]'::jsonb; v_enc text; v_meta jsonb; v_el jsonb; v_hist jsonb;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  SELECT role,client_id INTO v_role,v_cid FROM public.profiles WHERE auth_user_id=auth.uid() AND active=true;
  IF v_role IS DISTINCT FROM 'client' THEN RETURN jsonb_build_object('error','Only clients can remove credentials'); END IF;
  SELECT * INTO v_ass FROM public.assessments WHERE id=p_assessment_id; IF NOT FOUND THEN RETURN jsonb_build_object('error','Assessment not found'); END IF;
  IF v_cid IS NULL OR v_ass.client_id IS DISTINCT FROM v_cid THEN RETURN jsonb_build_object('error','Access denied'); END IF;
  IF v_ass.credentials_data IS NULL OR (v_ass.credentials_data::jsonb)->>'enc' IS NULL THEN RETURN jsonb_build_object('error','No credentials'); END IF;
  v_key := public._get_cred_key();
  BEGIN v_list := extensions.pgp_sym_decrypt(decode((v_ass.credentials_data::jsonb)->>'enc','base64'),v_key)::jsonb; EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error','Could not decrypt'); END;
  IF p_index < 0 OR p_index >= jsonb_array_length(v_list) THEN RETURN jsonb_build_object('error','Invalid index'); END IF;
  FOR v_el IN SELECT value FROM jsonb_array_elements(v_list) WITH ORDINALITY AS t(value,idx) WHERE t.idx-1 != p_index LOOP v_new := v_new || jsonb_build_array(v_el); END LOOP;
  -- 1721: p_index counts the entries still waiting (the encrypted list), and
  -- the entries already received are kept whatever is removed.
  v_hist := public._cred_received(COALESCE(v_ass.credentials_meta, (v_ass.credentials_data::jsonb)->'meta'), true);
  IF jsonb_array_length(v_new) > 0 THEN
    v_enc := encode(extensions.pgp_sym_encrypt(v_new::text,v_key)::bytea,'base64');
    v_meta := v_hist || public._cred_meta_of(v_new);
    UPDATE public.assessments SET credentials_data=jsonb_build_object('enc',v_enc,'meta',v_meta), credentials_meta=v_meta, credentials_status='pending', test_perspective='authenticated' WHERE id=p_assessment_id;
    RETURN jsonb_build_object('success',true,'count',jsonb_array_length(v_new),'meta',v_meta,'status','pending');
  ELSIF jsonb_array_length(v_hist) > 0 THEN
    -- Nothing waits any more, and what was collected earlier still stands.
    UPDATE public.assessments SET credentials_data=jsonb_build_object('meta',v_hist), credentials_meta=v_hist, credentials_status='viewed', test_perspective='authenticated' WHERE id=p_assessment_id;
    RETURN jsonb_build_object('success',true,'count',0,'meta',v_hist,'status','viewed');
  ELSE UPDATE public.assessments SET credentials_data=NULL, credentials_meta=NULL, credentials_status='none', test_perspective='unauthenticated' WHERE id=p_assessment_id; END IF;
  RETURN jsonb_build_object('success',true,'count',0,'meta',NULL,'status','none');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- 1718: CREDENTIALS SENT ANOTHER WAY. [stated] Arian: "Please add a credentials
-- submitted through other means to close the notification for the client in
-- case they did it through other means as well".
--
-- An engagement asking for credentials says so on the client's dashboard, in
-- their menu and on the engagement, and emails them reminders, until the
-- credentials arrive through the portal. Credentials handed over on a call or
-- by the firm's own secure transfer never did, so the client was chased for
-- something already done. This closes it: 'elsewhere' is received, as far as
-- the portal is concerned, and nothing counts it as owed.
--
-- The client says so for their own organisation's engagement, or somebody at
-- the firm who has them in hand does (a contractor only on work they lead).
-- Only from 'awaiting': a submission in the portal already closed it. The
-- tester is told when it is the client who says so, through the same switch
-- and to the same people as a submission.
CREATE OR REPLACE FUNCTION public.rpc_credentials_elsewhere(p_assessment_id uuid, p_note text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE v_pid uuid; v_role text; v_cid uuid; v_name text; v_ass record; v_note text;
  v_company text; v_notify boolean; v_vars jsonb; v_subject text; v_body text; v_to text;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  SELECT id, role, client_id, COALESCE(NULLIF(btrim(name), ''), email)
    INTO v_pid, v_role, v_cid, v_name
    FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  v_role := public.current_user_role();   -- 1943: a contractor while contractors are off is nobody
  SELECT * INTO v_ass FROM public.assessments WHERE id = p_assessment_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Assessment not found'); END IF;
  IF v_role = 'client' THEN
    IF v_ass.client_id IS DISTINCT FROM v_cid THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  ELSIF v_role = 'contractor' THEN
    -- 1943: led by them or handed to their team.
    IF NOT public.can_access_assessment(p_assessment_id) THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  ELSIF v_role NOT IN ('admin', 'senior', 'standard') THEN
    RETURN jsonb_build_object('error', 'Access denied');
  END IF;
  IF COALESCE(v_ass.credentials_status, 'none') <> 'awaiting' THEN
    RETURN jsonb_build_object('error', 'This engagement is not waiting on credentials');
  END IF;
  v_note := NULLIF(left(btrim(COALESCE(p_note, '')), 300), '');

  UPDATE public.assessments SET credentials_status = 'elsewhere', test_perspective = 'authenticated'
   WHERE id = p_assessment_id;

  BEGIN
    INSERT INTO public.timeline_events (assessment_id, event, user_id, title, user_name, details)
    VALUES (p_assessment_id,
            CASE WHEN v_role = 'client' THEN 'Client says credentials were provided another way'
                 ELSE 'Credentials received another way' END,
            v_pid, 'Credentials provided another way', v_name, v_note);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  IF v_role = 'client' THEN
    BEGIN
      SELECT company_name, COALESCE(notify_credentials_submitted, true)
        INTO v_company, v_notify FROM public.settings LIMIT 1;
      v_vars := jsonb_build_object(
        'assessment_name', COALESCE(v_ass.name, 'an engagement'),
        'client_name', COALESCE(v_name, 'The client'),
        'note', COALESCE(v_note, ''),
        'start_date', COALESCE(to_char(v_ass.start_date, 'FMDD Mon YYYY'), ''),
        'company_name', COALESCE(v_company, ''));
      v_body := public._email_fill(
           '<h1>Credentials sent another way</h1>' || chr(10)
        || '<p><strong>{{client_name}}</strong> says the credentials for <strong>{{assessment_name}}</strong> were given to you outside the portal, so it has stopped asking them for them.</p>' || chr(10)
        || CASE WHEN v_note IS NOT NULL THEN '<p>Their note: {{note}}</p>' || chr(10) ELSE '' END
        || CASE WHEN v_ass.start_date IS NOT NULL THEN '<table class="details"><tr><th>Testing starts</th><td>{{start_date}}</td></tr></table>' || chr(10) ELSE '' END
        || '<p>If nothing has reached you, contact them directly.</p>' || chr(10)
        || '<a class="button" href="{{action_url}}">Open the engagement</a>', v_vars, true);
      v_subject := public._email_fill('Credentials for {{assessment_name}} were sent another way', v_vars, false);
      FOR v_to IN
        SELECT DISTINCT p.email FROM public.profiles p
         WHERE COALESCE(v_notify, true) AND p.active = true
           AND p.id IN (v_ass.lead_id, v_ass.qa_assignee)
           AND p.id IS DISTINCT FROM v_pid
           AND COALESCE(p.email, '') <> ''
      LOOP
        INSERT INTO public.email_notifications (to_email, subject, body, notification_type, related_id, status)
        VALUES (v_to, v_subject, v_body, 'credentials_elsewhere', p_assessment_id, 'pending');
      END LOOP;
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  RETURN jsonb_build_object('success', true, 'status', 'elsewhere');
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_credentials_elsewhere(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_credentials_elsewhere(uuid, text) TO authenticated, service_role;

-- ════════════════════════════════════════════════════════════════
-- SETTINGS + PROFILE LOOKUP RPCs
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_get_smtp_config(p_secret text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_s RECORD;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_get_smtp_config') THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT smtp_host, smtp_port, smtp_user, smtp_pass, smtp_pass_enc, smtp_from_name, smtp_from_email, company_name, email_enabled, email_templates, accent_color, company_email, smtp_oauth_provider, smtp_oauth_user, smtp_oauth_refresh, smtp_oauth_refresh_enc INTO v_s FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  -- The encryption trigger moves smtp_pass into smtp_pass_enc and blanks the
  -- plaintext, so fall back to decrypting the ciphertext. Without this the
  -- verify-read returns a NULL password and every SMTP save looks like it failed.
  RETURN jsonb_build_object('smtp_host', v_s.smtp_host, 'smtp_port', v_s.smtp_port, 'smtp_user', v_s.smtp_user, 'smtp_pass', COALESCE(NULLIF(v_s.smtp_pass, ''), public._settings_decrypt(v_s.smtp_pass_enc)), 'smtp_from_name', v_s.smtp_from_name, 'smtp_from_email', v_s.smtp_from_email, 'company_name', v_s.company_name, 'email_enabled', v_s.email_enabled, 'email_templates', v_s.email_templates, 'accent_color', v_s.accent_color, 'company_email', v_s.company_email, 'smtp_oauth_provider', v_s.smtp_oauth_provider, 'smtp_oauth_user', v_s.smtp_oauth_user, 'smtp_oauth_refresh', COALESCE(NULLIF(v_s.smtp_oauth_refresh, ''), public._settings_decrypt(v_s.smtp_oauth_refresh_enc)), 'password_login_enabled', COALESCE(v_s.password_login_enabled, false));
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_update_settings(p_data jsonb, p_secret text DEFAULT NULL) RETURNS boolean AS $$
DECLARE v_key text; v_sql text := 'UPDATE public.settings SET ';
  v_allowed text[] := ARRAY['company_name','company_email','company_phone','company_address','company_number','company_ending','company_website','accent_color','theme_mode','logo_url','logo_url_light','pdf_logo_variant','email_logo_variant','password_login_enabled','font_display','font_body','font_mono','pdf_font_body','pdf_font_heading','email_font','favicon_data','portal_title','login_title','login_subtitle','login_support_email','login_button_text','login_custom_text','login_show_logo','login_show_company_name','login_show_title','testing_calendar_enabled','sso_google_enabled','sso_microsoft_enabled','sso_google_client_id','sso_ms_client_id','sso_ms_tenant','sso_google_client_secret','sso_ms_client_secret','smtp_host','smtp_port','smtp_user','smtp_pass','smtp_oauth_provider','smtp_oauth_user','smtp_oauth_refresh','smtp_from_name','smtp_from_email','email_enabled','severity_colors','severity_style','notification_color','toast_success_color','google_api_key','currency_code','currency_symbol','day_rate','vat_rate','vat_number','assessment_types','session_timeout_minutes','theme_dark','theme_light','stripe_enabled','stripe_publishable_key','stripe_secret_key','stripe_webhook_secret','stripe_success_url','ai_provider','ai_api_key','meeting_integration','contact_integration','updated_at','pdf_templates','ai_custom_url','ai_custom_model','ai_custom_format','ai_custom_headers','ai_custom_max_tokens','ai_ollama_num_ctx','logo_data','color_bg','color_border','color_card','color_muted','color_primary','color_secondary','color_text','color_hover','teams_tenant_id','teams_client_id','teams_client_secret','teams_user_email','email_templates','loa_signatory_name','loa_signatory_title','loa_signature_data','session_timeout_action','session_signout_minutes','session_refresh_buffer_minutes','show_tester_teams','show_tester_slack','google_review_url','feedback_mode','loa_visibility','sig_name','sig_title','sig_email','sig_phone','sig_teams','sig_slack','sig_html','email_signature_enabled','notify_test_started','notify_test_ended','notify_critical_finding','notify_proposal_sent','notify_invoice_sent','notify_tester_assigned','notify_credentials_submitted','notify_comment_reply','notify_report_delivered','notify_new_sign_in','notify_new_device_sign_in','notify_mfa_changed','notify_role_changed','notify_user_created','notify_session_revoked','exec_summary_prompt','finding_desc_prompt','finding_rem_prompt','retest_summary_prompt','proposals_enabled','invoices_enabled','feedback_enabled','meet_calendar_enabled','meetings_enabled','contacts_enabled','dashboard_enabled','qa_enabled','assessments_enabled','library_enabled','dashboard_layouts','proposal_multi_year_enabled','proposal_subscription_enabled','proposal_custom_titles','auto_start_enabled','auto_start_time','auto_complete_enabled','auto_complete_time','automation_timezone','automation_workdays_only','auto_credentials_enabled','auto_credentials_time','auto_credentials_days','self_scan_default_hour','mail_outbox_enabled','mail_outbox_started_at','invoice_automation','invoice_auto_send_days','filename_templates','standard_field_prompts','summary_fields','summary_sections','plan_max_users','plan_max_clients','notes_prompt','caveats_prompt','date_format',
    -- 1547: the Reply-To typed on the dashboard's mail screen. The route has
    -- sent it since 1410 and this list silently dropped it, so "Replies go to"
    -- never persisted and quietly fell back to the company address.
    'notify_reply_to_email'];
  v_first boolean := true;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_update_settings') THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  FOR v_key IN SELECT jsonb_object_keys(p_data) LOOP
    IF v_key = ANY(v_allowed) THEN IF NOT v_first THEN v_sql := v_sql || ', '; END IF; v_sql := v_sql || quote_ident(v_key) || ' = ' || quote_literal(p_data->>v_key); v_first := false; END IF;
  END LOOP;
  IF v_first THEN RETURN false; END IF;
  v_sql := v_sql || ' WHERE id = (SELECT id FROM public.settings LIMIT 1)'; EXECUTE v_sql; RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_profile_lookup(p_email text, p_secret text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_row RECORD;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT id, name, role, active, email INTO v_row FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'id', v_row.id, 'name', v_row.name, 'email', v_row.email);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_get_admin_email(p_secret text DEFAULT NULL) RETURNS text AS $$
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  RETURN (SELECT email FROM public.profiles WHERE role = 'admin' AND active = true LIMIT 1);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- ════════════════════════════════════════════════════════════════
-- MFA RPCs
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_check_mfa_status(p_email text) RETURNS jsonb AS $$
DECLARE v_role text; v_has boolean;
BEGIN
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true;
  IF v_role IS NULL THEN RETURN jsonb_build_object('error', 'Not authenticated'); END IF;
  IF v_role NOT IN ('admin', 'senior') THEN SELECT (totp_secret IS NOT NULL AND totp_secret != '') INTO v_has FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true;
  ELSE SELECT (totp_secret IS NOT NULL AND totp_secret != '') INTO v_has FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true; END IF;
  RETURN jsonb_build_object('has_totp', COALESCE(v_has, false));
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- ────────────────────────────────────────────────────────────────
-- Security notification helper. Enqueues a row in email_notifications for
-- the affected user or their tenant admins when a sensitive event happens.
-- Respects per-tenant toggles on the settings row.
--
-- IMPORTANT: on master (shared multi-tenant DB) the settings, profiles, and
-- email_notifications tables have a tenant_id column and hold rows for many
-- tenants. The caller MUST pass p_profile_id so the helper can derive the
-- tenant_id and scope every lookup to that tenant. On BYO tenant_id is
-- always NULL and the scoping is a no-op.
-- ────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public._queue_security_notif(
  p_toggle_key text, p_subject text, p_body text,
  p_profile_id uuid,
  p_to_email text DEFAULT NULL,
  p_notif_type text DEFAULT 'security_event'
) RETURNS void AS $$
DECLARE v_enabled boolean; v_email_on boolean; v_from_name text; v_from_email text;
        v_target text;
        v_settings_sql text;
BEGIN
  IF p_profile_id IS NULL THEN RETURN; END IF;

  -- Single-tenant BYO: one settings row, one admin pool. No tenant filter.
  v_settings_sql := format(
    'SELECT email_enabled, COALESCE(%I, false), smtp_from_name, smtp_from_email FROM public.settings LIMIT 1',
    p_toggle_key
  );
  EXECUTE v_settings_sql INTO v_email_on, v_enabled, v_from_name, v_from_email;

  IF v_email_on IS NOT TRUE OR v_enabled IS NOT TRUE THEN RETURN; END IF;

  IF NULLIF(p_to_email, '') IS NOT NULL THEN
    v_target := p_to_email;
  ELSE
    SELECT email INTO v_target FROM public.profiles
      WHERE role = 'admin' AND active = true ORDER BY created_at LIMIT 1;
  END IF;
  IF v_target IS NULL OR v_target = '' THEN RETURN; END IF;

  INSERT INTO public.email_notifications
    (to_email, subject, body, notification_type, from_name, from_email, status, attempts)
  VALUES
    (v_target, p_subject, p_body, COALESCE(p_notif_type, 'security_event'),
     COALESCE(v_from_name, 'Pental'), v_from_email, 'pending', 0);
EXCEPTION WHEN OTHERS THEN
  -- Never let notification enqueueing block the calling action
  RAISE WARNING 'Security notification enqueue failed: %', SQLERRM;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;
-- 1797: A HELPER, NOT AN ENDPOINT. It takes a recipient, a subject and a body
-- and queues them as pending mail, and it was executable by anyone holding the
-- publishable key: a way to have the firm's mailbox send anything to anyone
-- once the outbox runs, which it does now. Only the four functions that call
-- it (all SECURITY DEFINER, so they run as its owner) need it.
REVOKE ALL ON FUNCTION public._queue_security_notif(text, text, text, uuid, text, text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_save_totp_secret(p_email text, p_totp_secret text, p_secret text) RETURNS boolean AS $$
DECLARE v_role text; v_caller_email text; v_was_set boolean; v_target_id uuid;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_save_totp_secret') THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT role, email INTO v_role, v_caller_email FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true;
  IF lower(p_email) != lower(v_caller_email) AND v_role NOT IN ('admin', 'senior') THEN RAISE EXCEPTION 'Can only save own MFA secret'; END IF;
  SELECT id, (totp_secret IS NOT NULL AND totp_secret != '')
    INTO v_target_id, v_was_set
    FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true;
  -- Enrolling for the FIRST time is open: there is no authenticator to prove yet.
  -- REPLACING an existing authenticator, or setting one for another user, requires
  -- the caller to have already passed MFA in this session. This is what stops a
  -- session alone from being enough: anyone holding only a session (including
  -- Pental's back end, which sends the login email) cannot swap in an authenticator
  -- it controls, so it can never satisfy mfa_is_fresh() and every data-access
  -- policy keeps failing closed. A real user replacing a lost device goes through
  -- an admin reset, which requires a signed-in admin.
  IF (v_was_set OR lower(p_email) != lower(v_caller_email)) AND NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Current MFA verification required to change an authenticator';
  END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles SET totp_secret = p_totp_secret WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM set_config('pental.bypass_protect', 'false', true);
  -- Notify on any change: initial setup, reset, or re-enrollment
  PERFORM public._queue_security_notif(
    'notify_mfa_changed',
    CASE WHEN v_was_set THEN 'MFA authenticator updated' ELSE 'MFA authenticator enabled' END,
    format(
      '<p>The authenticator app for <strong>%s</strong> has been %s.</p>'
      '<p>If this was not you, revoke active sessions in your portal Security settings and contact your administrator.</p>',
      public._html_esc(lower(p_email)), CASE WHEN v_was_set THEN 'updated' ELSE 'enabled' END
    ),
    v_target_id,
    lower(p_email)
  );
  RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ────────────────────────────────────────────────────────────────
-- Server-side TOTP verification (RFC 6238 / RFC 4226).
-- The TOTP secret never leaves the database: previous implementations returned
-- it to the Node caller and relied on otplib, which meant anyone with the
-- provision secret could exfiltrate every user's MFA seed.
-- ────────────────────────────────────────────────────────────────

-- Base32 decode (RFC 4648). Accepts upper/lower case, ignores '=' padding and
-- whitespace. Returns raw bytes. Used only internally by _totp_check.
CREATE OR REPLACE FUNCTION public._base32_decode(p_input text) RETURNS bytea AS $$
DECLARE
  v_alphabet text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_clean text;
  v_bits text := '';
  v_c text;
  v_idx int;
  v_out bytea := ''::bytea;
  v_byte int;
  i int;
BEGIN
  v_clean := upper(regexp_replace(COALESCE(p_input, ''), '[=\s]', '', 'g'));
  IF v_clean = '' THEN RETURN ''::bytea; END IF;
  FOR i IN 1..length(v_clean) LOOP
    v_c := substr(v_clean, i, 1);
    v_idx := position(v_c in v_alphabet) - 1;
    IF v_idx < 0 THEN RETURN NULL; END IF;
    v_bits := v_bits || lpad(v_idx::bit(5)::text, 5, '0');
  END LOOP;
  i := 1;
  WHILE i + 7 <= length(v_bits) LOOP
    v_byte := ('B' || substr(v_bits, i, 8))::bit(8)::int;
    v_out := v_out || set_byte('\x00'::bytea, 0, v_byte);
    i := i + 8;
  END LOOP;
  RETURN v_out;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Compute the 6-digit TOTP for a given base32 secret and unix time.
-- Uses HMAC-SHA1 and RFC 4226 dynamic truncation. Returns the 6-digit code
-- as text (zero-padded).
CREATE OR REPLACE FUNCTION public._totp_code(p_secret_b32 text, p_unix_time bigint) RETURNS text AS $$
DECLARE
  v_key bytea;
  v_counter bigint;
  v_msg bytea := ''::bytea;
  v_hmac bytea;
  v_offset int;
  v_bin bigint;
BEGIN
  v_key := public._base32_decode(p_secret_b32);
  IF v_key IS NULL OR length(v_key) = 0 THEN RETURN NULL; END IF;
  v_counter := floor(p_unix_time / 30)::bigint;
  -- 8-byte big-endian counter
  FOR i IN 0..7 LOOP
    v_msg := v_msg || set_byte('\x00'::bytea, 0, ((v_counter >> ((7 - i) * 8)) & 255)::int);
  END LOOP;
  v_hmac := extensions.hmac(v_msg, v_key, 'sha1');
  v_offset := get_byte(v_hmac, length(v_hmac) - 1) & 15;
  v_bin := ((get_byte(v_hmac, v_offset) & 127)::bigint << 24)
         | ((get_byte(v_hmac, v_offset + 1) & 255)::bigint << 16)
         | ((get_byte(v_hmac, v_offset + 2) & 255)::bigint << 8)
         |  (get_byte(v_hmac, v_offset + 3) & 255)::bigint;
  RETURN lpad((v_bin % 1000000)::text, 6, '0');
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Server-side TOTP check with a ±1 step window (±30s tolerance).
CREATE OR REPLACE FUNCTION public._totp_check(p_secret_b32 text, p_code text) RETURNS boolean AS $$
DECLARE
  v_now bigint := extract(epoch FROM now())::bigint;
  v_input text;
BEGIN
  v_input := regexp_replace(COALESCE(p_code, ''), '\s', '', 'g');
  IF length(v_input) != 6 OR v_input !~ '^[0-9]{6}$' THEN RETURN false; END IF;
  IF public._totp_code(p_secret_b32, v_now) = v_input THEN RETURN true; END IF;
  IF public._totp_code(p_secret_b32, v_now - 30) = v_input THEN RETURN true; END IF;
  IF public._totp_code(p_secret_b32, v_now + 30) = v_input THEN RETURN true; END IF;
  RETURN false;
END;
$$ LANGUAGE plpgsql;

DROP FUNCTION IF EXISTS public.rpc_verify_totp(text, text);
-- Verify a TOTP code against the stored secret for p_email.
-- Performs the verification server-side: the secret never leaves the database.
-- Atomically updates totp_attempts / totp_locked_until.
-- Returns {success: true} or {error: "...", attempts_remaining?, locked_until?}.
CREATE OR REPLACE FUNCTION public.rpc_verify_totp(p_email text, p_code text, p_secret text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_prof RECORD; v_ok boolean; v_new_attempts int; v_lock_until timestamptz;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_verify_totp') THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT id, totp_secret, COALESCE(totp_attempts, 0) AS totp_attempts, totp_locked_until
    INTO v_prof
    FROM public.profiles
    WHERE lower(email) = lower(p_email) AND active = true
    FOR UPDATE;
  IF NOT FOUND OR v_prof.totp_secret IS NULL OR v_prof.totp_secret = '' THEN
    RETURN jsonb_build_object('error', 'MFA not configured');
  END IF;
  IF v_prof.totp_locked_until IS NOT NULL AND v_prof.totp_locked_until > now() THEN
    RETURN jsonb_build_object('error', 'Account locked', 'locked_until', v_prof.totp_locked_until);
  END IF;

  v_ok := public._totp_check(v_prof.totp_secret, p_code);

  IF v_ok THEN
    -- Reset counter + lock on success.
    UPDATE public.profiles
      SET totp_attempts = 0, totp_locked_until = NULL
      WHERE id = v_prof.id;
    RETURN jsonb_build_object('success', true);
  END IF;

  -- Invalid code: bump the counter atomically. 5 strikes → 15-minute lock.
  v_new_attempts := v_prof.totp_attempts + 1;
  IF v_new_attempts >= 5 THEN
    v_lock_until := now() + interval '15 minutes';
    UPDATE public.profiles
      SET totp_attempts = v_new_attempts, totp_locked_until = v_lock_until
      WHERE id = v_prof.id;
    RETURN jsonb_build_object('error', 'Account locked', 'locked_until', v_lock_until);
  END IF;
  UPDATE public.profiles SET totp_attempts = v_new_attempts WHERE id = v_prof.id;
  RETURN jsonb_build_object('error', 'Invalid code', 'attempts_remaining', 5 - v_new_attempts);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ════════════════════════════════════════════════════════════════
-- SESSION MANAGEMENT RPCs
-- ════════════════════════════════════════════════════════════════
-- Session rows are keyed on the Supabase JWT session_id claim so a single
-- browser stays as one row across refresh-token rotations. The portal calls
-- rpc_session_register on login (passing session_id + IP + user-agent) and
-- rpc_session_touch from its activity tracker (throttled to every 5 min).

CREATE OR REPLACE FUNCTION public.rpc_session_register(
  p_auth_session_id text, p_ip text DEFAULT NULL, p_user_agent text DEFAULT NULL,
  p_device_label text DEFAULT NULL, p_expires_at timestamptz DEFAULT NULL
) RETURNS jsonb AS $$
DECLARE v_profile_id uuid; v_existing_id uuid; v_was_new boolean := false;
        v_is_new_device boolean := false; v_ua_hash text;
        v_prior_count integer := 0;
BEGIN
  IF p_auth_session_id IS NULL OR length(p_auth_session_id) < 8 THEN
    RETURN jsonb_build_object('error', 'Invalid session id');
  END IF;
  SELECT id INTO v_profile_id FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN jsonb_build_object('error', 'No active profile'); END IF;

  SELECT id INTO v_existing_id FROM public.user_sessions
    WHERE auth_session_id = p_auth_session_id LIMIT 1;

  IF v_existing_id IS NULL THEN
    -- Count how many prior session rows this profile has. If zero, suppress
    -- the new-device notification - this is either a brand-new user or an
    -- existing user's first registration after the feature deployed, and
    -- either way should not trigger a "new device" alert.
    SELECT COUNT(*) INTO v_prior_count FROM public.user_sessions WHERE profile_id = v_profile_id;

    -- Determine if this is a new device: no prior non-revoked session for this
    -- profile with matching (ip, user_agent prefix). user_agent is long so we
    -- hash it for comparison stability.
    v_ua_hash := encode(extensions.digest(COALESCE(p_user_agent, ''), 'sha256'), 'hex');
    IF v_prior_count > 0 AND NOT EXISTS (
      SELECT 1 FROM public.user_sessions
      WHERE profile_id = v_profile_id
        -- Deliberately NOT filtered on revoked_at. This asks "have we ever
        -- seen this address and browser for this person", which is a question
        -- about history, not about currently-live sessions. Signing out
        -- revokes the row, so with that filter the same address and browser
        -- stopped counting as known the moment someone logged out, and the
        -- next sign-in was reported as a new device. That is why the alert
        -- fired on every single login from one new address instead of once.
        AND ip IS NOT DISTINCT FROM p_ip
        AND encode(extensions.digest(COALESCE(user_agent, ''), 'sha256'), 'hex') = v_ua_hash
    ) THEN
      v_is_new_device := true;
    END IF;

    INSERT INTO public.user_sessions
      (profile_id, auth_session_id, ip, user_agent, device_label, expires_at)
      VALUES (v_profile_id, p_auth_session_id, p_ip, p_user_agent, p_device_label, p_expires_at)
      RETURNING id INTO v_existing_id;
    v_was_new := true;

    -- Only send notifications if this is NOT the profile's very first session
    -- (suppresses deploy-day flood and brand-new-user signup noise)
    IF v_prior_count > 0 THEN
    -- Notify: new device for a known user, or plain new sign-in if configured
    IF v_is_new_device THEN
      PERFORM public._queue_security_notif(
        'notify_new_device_sign_in',
        'New sign-in to your portal from an unrecognised device',
        format(
          '<p>A new sign-in to your portal was detected.</p>'
          '<table style="border-collapse:collapse;margin:12px 0">'
          '<tr><td style="padding:4px 12px;color:#666">Device</td><td style="padding:4px 12px"><strong>%s</strong></td></tr>'
          '<tr><td style="padding:4px 12px;color:#666">IP address</td><td style="padding:4px 12px">%s</td></tr>'
          '<tr><td style="padding:4px 12px;color:#666">When</td><td style="padding:4px 12px">%s</td></tr>'
          '</table>'
          '<p>If this was you, no action is needed. If you do not recognise this sign-in, open <strong>Settings &rarr; Security</strong> in your portal and revoke the session.</p>',
          COALESCE(p_device_label, 'Unknown device'),
          COALESCE(p_ip, 'unknown'),
          to_char(now() AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI UTC')
        ),
        v_profile_id,
        (SELECT email FROM public.profiles WHERE id = v_profile_id)
      );
    ELSE
      PERFORM public._queue_security_notif(
        'notify_new_sign_in',
        'New sign-in to your portal',
        format(
          '<p>A new sign-in to your portal was detected at %s from %s.</p>'
          '<p>If this was not you, open Settings &rarr; Security and revoke the session.</p>',
          to_char(now() AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI UTC'),
          COALESCE(p_ip, 'an unknown address')
        ),
        v_profile_id,
        (SELECT email FROM public.profiles WHERE id = v_profile_id)
      );
    END IF;
    END IF; -- end v_prior_count > 0 notification suppression
  ELSE
    UPDATE public.user_sessions
      SET last_active_at = now(),
          ip = COALESCE(p_ip, ip),
          user_agent = COALESCE(p_user_agent, user_agent),
          expires_at = COALESCE(p_expires_at, expires_at),
          revoked_at = NULL, revoked_reason = NULL
      WHERE id = v_existing_id;
  END IF;

  RETURN jsonb_build_object(
    'session_id', v_existing_id,
    'is_new', v_was_new,
    'is_new_device', v_is_new_device
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.rpc_session_touch(p_auth_session_id text) RETURNS boolean AS $$
DECLARE v_profile_id uuid;
BEGIN
  SELECT id INTO v_profile_id FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN false; END IF;
  UPDATE public.user_sessions SET last_active_at = now()
    WHERE auth_session_id = p_auth_session_id
      AND profile_id = v_profile_id
      AND revoked_at IS NULL;
  RETURN FOUND;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_session_revoke(p_session_id uuid, p_reason text DEFAULT 'user') RETURNS boolean AS $$
DECLARE v_profile_id uuid; v_caller_role text;
        v_target_profile_id uuid;
        v_target_email text; v_device text; v_ip text;
BEGIN
  -- BYO is single-tenant; every profile is in the same tenant by definition,
  -- so no tenant comparison is needed. Caller must own the session, or be
  -- an admin/senior.
  SELECT id, role INTO v_profile_id, v_caller_role FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN false; END IF;

  SELECT us.profile_id, p.email, us.device_label, us.ip
    INTO v_target_profile_id, v_target_email, v_device, v_ip
    FROM public.user_sessions us
    LEFT JOIN public.profiles p ON p.id = us.profile_id
    WHERE us.id = p_session_id;
  IF v_target_profile_id IS NULL THEN RETURN false; END IF;

  IF v_target_profile_id != v_profile_id THEN
    IF v_caller_role NOT IN ('admin','senior') THEN RETURN false; END IF;
  END IF;

  UPDATE public.user_sessions
    SET revoked_at = now(), revoked_reason = COALESCE(p_reason, 'user')
    WHERE id = p_session_id AND revoked_at IS NULL;

  IF FOUND THEN
    PERFORM public._queue_security_notif(
      'notify_session_revoked',
      'A portal session was revoked',
      format(
        '<p>A session on your portal account was revoked.</p>'
        '<table style="border-collapse:collapse;margin:12px 0">'
        '<tr><td style="padding:4px 12px;color:#666">Device</td><td style="padding:4px 12px">%s</td></tr>'
        '<tr><td style="padding:4px 12px;color:#666">IP</td><td style="padding:4px 12px">%s</td></tr>'
        '<tr><td style="padding:4px 12px;color:#666">Reason</td><td style="padding:4px 12px">%s</td></tr>'
        '</table>',
        -- 1798: the device string is whatever the browser said it was.
        public._html_esc(COALESCE(v_device, 'Unknown')), public._html_esc(COALESCE(v_ip, 'unknown')),
        public._html_esc(COALESCE(p_reason, 'user'))
      ),
      v_target_profile_id,
      v_target_email
    );
    RETURN true;
  END IF;
  RETURN false;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_session_revoke_others(p_current_auth_session_id text) RETURNS integer AS $$
DECLARE v_profile_id uuid; v_count integer;
BEGIN
  SELECT id INTO v_profile_id FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN 0; END IF;
  WITH updated AS (
    UPDATE public.user_sessions
      SET revoked_at = now(), revoked_reason = 'user_revoke_others'
      WHERE profile_id = v_profile_id
        AND revoked_at IS NULL
        AND auth_session_id IS DISTINCT FROM p_current_auth_session_id
      RETURNING 1
  )
  SELECT count(*) INTO v_count FROM updated;
  RETURN v_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- RLS policies for user_sessions. Writes go through the SECURITY DEFINER
-- RPCs below which do their own authorisation. Reads:
--   user_sessions_select_own:   any user can see their own rows
--   user_sessions_select_admin: admin/senior see all rows in this BYO
--                               database. BYO is single-tenant so every
--                               profile belongs to the same tenant by
--                               definition; no tenant_id column exists
--                               here to compare against (unlike master).
DROP POLICY IF EXISTS user_sessions_select_own ON public.user_sessions;
DROP POLICY IF EXISTS user_sessions_select_admin ON public.user_sessions;
CREATE POLICY user_sessions_select_own ON public.user_sessions
  FOR SELECT TO authenticated
  USING (profile_id = public.current_profile_id());
CREATE POLICY user_sessions_select_admin ON public.user_sessions
  FOR SELECT TO authenticated
  USING (
    public.can_manage() AND EXISTS (
      SELECT 1 FROM public.profiles caller
      WHERE caller.auth_user_id = auth.uid() AND caller.active = true
    )
  );
-- No INSERT/UPDATE/DELETE policies: writes only through the SECURITY DEFINER
-- RPCs above, which do their own authorisation.

GRANT SELECT ON public.user_sessions TO authenticated;
GRANT ALL ON public.user_sessions TO service_role;
GRANT EXECUTE ON FUNCTION public.rpc_session_register(text, text, text, text, timestamptz) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_session_touch(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_session_revoke(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_session_revoke_others(text) TO authenticated;

CREATE OR REPLACE FUNCTION public.rpc_get_profile_bank_details(p_profile_id uuid) RETURNS jsonb AS $$
DECLARE v_role text; v_row RECORD;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'senior') THEN RETURN jsonb_build_object('error', 'Admin access required'); END IF;
  SELECT bank_name, bank_sort_code, bank_account, bank_institution, contractor_company INTO v_row FROM public.profiles WHERE id = p_profile_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profile not found'); END IF;
  RETURN jsonb_build_object('bank_name', v_row.bank_name, 'bank_sort_code', v_row.bank_sort_code, 'bank_account', v_row.bank_account, 'bank_institution', v_row.bank_institution, 'contractor_company', v_row.contractor_company);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- ════════════════════════════════════════════════════════════════
-- INVOICE + RETEST RPCs
-- ════════════════════════════════════════════════════════════════

-- 1839: THE PAGE A CARD PAYMENT RETURNS TO SAYS "PAYMENT TO CONFIRM", NEVER
-- "PAID". [stated] Arian: "make sure all those integrations work". Anyone
-- could open that page (or call this) for any invoice of theirs and have it
-- marked paid with nothing paid at all. It now marks the invoice as a payment
-- being confirmed (pending_payment_confirmation), keeps the Stripe session it
-- names, and asks Stripe from this database's own side where it can
-- (_card_payment_returned); Stripe's word (that answer, or its webhook,
-- rpc_stripe_event) or the firm's team's Confirm marks it paid.
DROP FUNCTION IF EXISTS public.rpc_mark_invoice_paid(uuid);
CREATE OR REPLACE FUNCTION public.rpc_mark_invoice_paid(p_invoice_id uuid, p_session_id text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_out jsonb;
BEGIN
  v_out := public._card_payment_returned(ARRAY[p_invoice_id], p_session_id);
  RETURN jsonb_build_object('success', COALESCE((v_out ->> 'ok')::boolean, false), 'pending', true) || v_out;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;
REVOKE ALL ON FUNCTION public.rpc_mark_invoice_paid(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_mark_invoice_paid(uuid, text) TO authenticated;

CREATE OR REPLACE FUNCTION public.rpc_confirm_bank_payment(p_invoice_id uuid) RETURNS jsonb AS $$
DECLARE v_uid uuid; v_role text; v_client_id uuid; v_inv record;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  v_uid := auth.uid(); IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  SELECT role, client_id INTO v_role, v_client_id FROM public.profiles WHERE auth_user_id = v_uid AND active = true LIMIT 1;
  IF v_role IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Profile not found'); END IF;
  SELECT id, client_id, status, assessment_id INTO v_inv FROM public.invoices WHERE id = p_invoice_id;
  IF v_inv.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Invoice not found'); END IF;
  IF v_role NOT IN ('admin', 'senior') THEN IF v_role != 'client' OR v_client_id IS NULL OR v_client_id != v_inv.client_id THEN RETURN jsonb_build_object('success', false, 'error', 'Not authorized'); END IF; END IF;
  IF v_inv.status NOT IN ('sent', 'overdue') THEN RETURN jsonb_build_object('success', false, 'error', 'Invoice not in payable state'); END IF;
  UPDATE public.invoices SET status = 'pending_bank_verification', updated_at = now() WHERE id = p_invoice_id;
  -- 1839: with its title (a timeline line must have one), or it was never written.
  BEGIN IF v_inv.assessment_id IS NOT NULL THEN INSERT INTO public.timeline_events (assessment_id, event, user_id, title) VALUES (v_inv.assessment_id, 'Client confirmed bank transfer payment - awaiting verification', v_uid, 'Bank transfer to verify'); END IF; EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('success', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_request_retest(p_finding_id uuid) RETURNS jsonb AS $$
DECLARE v_uid uuid; v_role text; v_client_id uuid; v_f record;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  v_uid := auth.uid(); IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  SELECT role, client_id INTO v_role, v_client_id FROM public.profiles WHERE auth_user_id = v_uid AND active = true LIMIT 1;
  IF v_role IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Profile not found'); END IF;
  v_role := public.current_user_role();   -- 1943: a contractor while contractors are off is nobody
  -- 1924: held while it is decided, so two people asking at once ask once.
  SELECT f.id, f.assessment_id, f.retest_requested, f.retest_status, a.client_id AS a_client_id INTO v_f FROM public.findings f JOIN public.assessments a ON a.id = f.assessment_id WHERE f.id = p_finding_id FOR UPDATE OF f;
  IF v_f.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Finding not found'); END IF;
  IF v_role NOT IN ('admin','senior','standard','contractor') THEN IF v_role != 'client' OR v_client_id IS NULL OR v_client_id != v_f.a_client_id THEN RETURN jsonb_build_object('success', false, 'error', 'Not authorized'); END IF; END IF;
  -- 1841: a contractor, for an engagement they lead (as findings_read says).
  -- 1943: or one handed to their team.
  IF v_role = 'contractor' AND NOT public.can_access_assessment(v_f.assessment_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  IF v_f.retest_requested AND v_f.retest_status = 'requested' THEN RETURN jsonb_build_object('success', true, 'message', 'Already requested'); END IF;
  UPDATE public.findings SET retest_requested = true, retest_status = 'requested', retest_requested_at = now(), updated_at = now() WHERE id = p_finding_id;
  -- 1839: with its title (a timeline line must have one), or it was never written.
  BEGIN INSERT INTO public.timeline_events (assessment_id, event, user_id, title) VALUES (v_f.assessment_id, 'Retest requested for finding', v_uid, 'Retest requested'); EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('success', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- ════════════════════════════════════════════════════════════════
-- BULK OPS (data transfer)
-- ════════════════════════════════════════════════════════════════

-- Introspection helper used by the setup wizard to probe for required
-- RPCs without invoking them. Previously the wizard POSTed {} to each
-- function as an existence probe, but rpc_bulk_clean actually executes
-- in bootstrap mode (when _internal_secrets has no PROVISION_SECRET row),
-- which would silently wipe the just-created BYO database.
--
-- Returns one row per requested name with {name, is_present}. Column is
-- is_present rather than exists because EXISTS is a reserved keyword.
DROP FUNCTION IF EXISTS public.rpc_functions_exist(text[]);
CREATE OR REPLACE FUNCTION public.rpc_functions_exist(p_names text[])
  RETURNS TABLE(name text, is_present boolean)
  LANGUAGE sql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp STABLE
AS $$
  SELECT
    n.name,
    EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace ns ON ns.oid = p.pronamespace
      WHERE ns.nspname = 'public' AND p.proname = n.name
    ) AS is_present
  FROM unnest(p_names) AS n(name);
$$;
GRANT EXECUTE ON FUNCTION public.rpc_functions_exist(text[]) TO anon, authenticated, service_role;

DROP FUNCTION IF EXISTS public.rpc_bulk_clean(text);
DROP FUNCTION IF EXISTS public.rpc_bulk_clean();
CREATE OR REPLACE FUNCTION public.rpc_bulk_clean(p_secret text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_new_secret text;
BEGIN
  IF NOT public._validate_provision_secret_or_bootstrap(COALESCE(p_secret, '')) THEN RETURN jsonb_build_object('success', false, 'error', 'Invalid provision secret'); END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  DELETE FROM payment_events WHERE true; DELETE FROM qa_comments WHERE true; DELETE FROM assessment_files WHERE true; DELETE FROM assessment_comments WHERE true; DELETE FROM timeline_events WHERE true; DELETE FROM tickets WHERE true; DELETE FROM feedback WHERE true; DELETE FROM email_notifications WHERE true; DELETE FROM contractor_payments WHERE true; DELETE FROM meeting_attendees WHERE true; DELETE FROM meetings WHERE true; DELETE FROM kb_entries WHERE true; PERFORM set_config('pental.wiping', 'on', true); DELETE FROM invoices WHERE true; DELETE FROM proposals WHERE true; DELETE FROM findings WHERE true; DELETE FROM assessments WHERE true; DELETE FROM login_codes WHERE true;
  DELETE FROM _internal_secrets WHERE key NOT IN ('PROVISION_SECRET', 'WEBAUTHN_VERIFY_URL', 'PENTAL_VERIFY_URL'); DELETE FROM _encryption_keys WHERE true; DELETE FROM _credentials_key WHERE true;
  UPDATE profiles SET client_id = NULL WHERE client_id IS NOT NULL;
  DELETE FROM auth.identities WHERE true; DELETE FROM auth.sessions WHERE true; DELETE FROM auth.refresh_tokens WHERE true; DELETE FROM auth.mfa_factors WHERE true; DELETE FROM auth.users WHERE true;
  DELETE FROM clients WHERE true; DELETE FROM profiles WHERE true; DELETE FROM settings WHERE true;
  DELETE FROM _internal_secrets WHERE key = 'PROVISION_SECRET';
  -- Generate a fresh 64-char hex secret, return the plaintext to master so it can
  -- be stored there exactly once, and persist only the SHA-256 hash locally.
  v_new_secret := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO _internal_secrets (key, value) VALUES ('PROVISION_SECRET', encode(extensions.digest(v_new_secret, 'sha256'), 'hex'));
  INSERT INTO _internal_secrets (key, value) VALUES ('CRON_SECRET', encode(extensions.gen_random_bytes(32), 'hex')) ON CONFLICT (key) DO NOTHING;
  RETURN jsonb_build_object('success', true, 'provision_secret', v_new_secret);
END;
$$;

DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb);
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text);
CREATE OR REPLACE FUNCTION public.rpc_bulk_import(p_table text, p_rows jsonb, p_secret text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r jsonb; v_inserted integer := 0; v_errors integer := 0; v_last_err text := ''; v_cols text[]; v_col_types text[]; v_sql text; v_key text; v_vals text[]; v_col_list text; v_col_type text; v_idx int;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Invalid provision secret'); END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  IF p_rows IS NULL OR jsonb_typeof(p_rows) != 'array' OR jsonb_array_length(p_rows) = 0 THEN RETURN jsonb_build_object('success', true, 'inserted', 0, 'errors', 0); END IF;
  -- Reject writes to internal / secret-bearing tables. These should never be
  -- repopulated via bulk_import (which is for master→BYO transfer of tenant data).
  -- Writing to _internal_secrets can lock Pental out of managing the tenant.
  IF p_table IN ('_internal_secrets','_credentials_key','_encryption_keys') THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Table is reserved and cannot be imported');
  END IF;
  IF p_table = 'profiles_client_restore' THEN
    FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP BEGIN UPDATE profiles SET client_id = (r->>'client_id')::uuid WHERE id = (r->>'id')::uuid; EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; v_last_err := SQLERRM; END; END LOOP;
    RETURN jsonb_build_object('success', v_errors = 0, 'inserted', jsonb_array_length(p_rows) - v_errors, 'errors', v_errors, 'last_error', v_last_err);
  END IF;
  SELECT array_agg(column_name::text ORDER BY ordinal_position), array_agg(data_type::text ORDER BY ordinal_position) INTO v_cols, v_col_types FROM information_schema.columns WHERE table_schema = 'public' AND table_name = p_table;
  IF v_cols IS NULL THEN RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Table not found: ' || p_table); END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    BEGIN v_vals := ARRAY[]::text[]; v_col_list := '';
      FOR v_key IN SELECT * FROM jsonb_object_keys(r) LOOP
        IF r->v_key IS NULL OR jsonb_typeof(r->v_key) = 'null' THEN CONTINUE; END IF;
        v_idx := array_position(v_cols, v_key);
        IF v_idx IS NOT NULL THEN
          v_col_type := v_col_types[v_idx]; v_col_list := v_col_list || CASE WHEN v_col_list = '' THEN '' ELSE ',' END || quote_ident(v_key);
          IF v_col_type = 'jsonb' OR v_col_type = 'json' THEN v_vals := v_vals || (quote_literal((r->v_key)::text) || '::jsonb');
          ELSIF v_col_type = 'bytea' THEN v_vals := v_vals || (quote_literal(r->>v_key) || '::bytea');
          ELSE v_vals := v_vals || quote_nullable(r ->> v_key); END IF;
        END IF;
      END LOOP;
      IF v_col_list != '' THEN v_sql := 'INSERT INTO ' || quote_ident(p_table) || ' (' || v_col_list || ') VALUES (' || array_to_string(v_vals, ',') || ')'; EXECUTE v_sql; END IF;
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; v_last_err := SQLERRM; END;
  END LOOP;
  RETURN jsonb_build_object('success', v_errors = 0, 'inserted', v_inserted, 'errors', v_errors, 'last_error', v_last_err);
END;
$$;

DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb);
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text);
CREATE OR REPLACE FUNCTION public.rpc_bulk_auth(p_profiles jsonb, p_secret text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r jsonb; v_created int := 0; v_errors int := 0; v_auth_id uuid;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RETURN jsonb_build_object('success', false, 'created', 0, 'errors', 1, 'error', 'Invalid provision secret'); END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  IF p_profiles IS NULL OR jsonb_typeof(p_profiles) != 'array' THEN RETURN jsonb_build_object('success',true,'created',0); END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(p_profiles) LOOP
    BEGIN
      -- Use auth_user_id if present (master DB has separate profile/auth IDs), fall back to id
      v_auth_id := COALESCE((r->>'auth_user_id')::uuid, (r->>'id')::uuid);
      IF EXISTS (SELECT 1 FROM auth.users WHERE id = v_auth_id) THEN CONTINUE; END IF;
      INSERT INTO auth.users (id,instance_id,email,encrypted_password,email_confirmed_at,aud,role,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,email_change_token_current,email_change_confirm_status,phone,phone_change,phone_change_token,reauthentication_token,is_sso_user,is_anonymous,recovery_token) VALUES (v_auth_id,'00000000-0000-0000-0000-000000000000',lower(r->>'email'),extensions.crypt(gen_random_uuid()::text,extensions.gen_salt('bf')),now(),'authenticated','authenticated',jsonb_build_object('provider','email','providers',ARRAY['email']),jsonb_build_object('name',COALESCE(r->>'name','')),now(),now(),'','','','',0,NULL,'','','',false,false,'');
      INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at) VALUES (gen_random_uuid(),v_auth_id,lower(r->>'email'),jsonb_build_object('sub',v_auth_id::text,'email',lower(r->>'email'),'email_verified',true),'email',now(),now(),now());
      -- Ensure profile.auth_user_id is set correctly
      UPDATE public.profiles SET auth_user_id = v_auth_id WHERE lower(email) = lower(r->>'email') AND (auth_user_id IS NULL OR auth_user_id != v_auth_id);
      v_created := v_created + 1;
    EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; END;
  END LOOP;
  RETURN jsonb_build_object('success',v_errors=0,'created',v_created,'errors',v_errors);
END;
$$;

-- ════════════════════════════════════════════════════════════════
-- rpc_bulk_import_keys
-- Mirrors rpc_bulk_import but ONLY for the encryption-key tables that
-- rpc_bulk_import deliberately refuses. Called during master→BYO migration
-- so assessment credentials and other encrypted payloads remain decryptable
-- after the move. Requires a valid provision_secret like the other bulk RPCs.
--
-- Hard constraints:
--   - Only accepts _credentials_key and _encryption_keys
--   - _internal_secrets is still refused (would let a leaked anon key overwrite
--     PROVISION_SECRET and lock Pental out of the tenant's BYO database)
--   - Wipes the target table before insert so stale keys can't linger
-- ════════════════════════════════════════════════════════════════
DROP FUNCTION IF EXISTS public.rpc_bulk_import_keys(text, jsonb, text);
CREATE OR REPLACE FUNCTION public.rpc_bulk_import_keys(p_table text, p_rows jsonb, p_secret text DEFAULT NULL)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r jsonb; v_inserted integer := 0; v_errors integer := 0; v_last_err text := '';
  v_cols text[]; v_col_types text[]; v_sql text; v_key text; v_vals text[];
  v_col_list text; v_col_type text; v_idx int;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Invalid provision secret');
  END IF;
  IF p_table NOT IN ('_credentials_key','_encryption_keys') THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Only _credentials_key and _encryption_keys accepted');
  END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  IF p_rows IS NULL OR jsonb_typeof(p_rows) != 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN jsonb_build_object('success', true, 'inserted', 0, 'errors', 0);
  END IF;

  -- Wipe target table so re-migration doesn't leave orphan keys from a previous tenant run.
  EXECUTE 'DELETE FROM ' || quote_ident(p_table) || ' WHERE true';

  SELECT array_agg(column_name::text ORDER BY ordinal_position),
         array_agg(data_type::text ORDER BY ordinal_position)
    INTO v_cols, v_col_types
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = p_table;
  IF v_cols IS NULL THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Table not found: ' || p_table);
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    BEGIN
      v_vals := ARRAY[]::text[]; v_col_list := '';
      FOR v_key IN SELECT * FROM jsonb_object_keys(r) LOOP
        IF r->v_key IS NULL OR jsonb_typeof(r->v_key) = 'null' THEN CONTINUE; END IF;
        -- tenant_id is meaningless in single-tenant BYO; skip it.
        IF v_key = 'tenant_id' THEN CONTINUE; END IF;
        v_idx := array_position(v_cols, v_key);
        IF v_idx IS NOT NULL THEN
          v_col_type := v_col_types[v_idx];
          v_col_list := v_col_list || CASE WHEN v_col_list = '' THEN '' ELSE ',' END || quote_ident(v_key);
          IF v_col_type = 'jsonb' OR v_col_type = 'json' THEN
            v_vals := v_vals || (quote_literal((r->v_key)::text) || '::jsonb');
          ELSIF v_col_type = 'bytea' THEN
            v_vals := v_vals || (quote_literal(r->>v_key) || '::bytea');
          ELSE
            v_vals := v_vals || quote_nullable(r ->> v_key);
          END IF;
        END IF;
      END LOOP;
      IF v_col_list != '' THEN
        v_sql := 'INSERT INTO ' || quote_ident(p_table) || ' (' || v_col_list || ') VALUES (' || array_to_string(v_vals, ',') || ')';
        EXECUTE v_sql;
      END IF;
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; v_last_err := SQLERRM; END;
  END LOOP;

  -- After importing into _encryption_keys, sync the credentials key into
  -- Vault. _get_cred_key() reads from Vault, not the table, so without
  -- this sync any encrypted data migrated from master can never be
  -- decrypted on BYO (Vault still holds whatever rpc_bulk_clean
  -- generated). Best-effort: failure to sync Vault doesn't fail the
  -- import, the table row is still present as a backup.
  IF p_table = '_encryption_keys' AND v_inserted > 0 THEN
    BEGIN
      DECLARE v_imported_key text; v_vault_slot uuid;
      BEGIN
        SELECT key_value INTO v_imported_key
          FROM public._encryption_keys
         WHERE key_name = 'credentials'
         LIMIT 1;
        IF v_imported_key IS NOT NULL AND v_imported_key <> '' THEN
          SELECT id INTO v_vault_slot
            FROM vault.decrypted_secrets
           WHERE name = 'credentials_aes_key';
          IF v_vault_slot IS NOT NULL THEN
            PERFORM vault.update_secret(v_vault_slot, v_imported_key);
          END IF;
        END IF;
      END;
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object('success', v_errors = 0, 'inserted', v_inserted, 'errors', v_errors, 'last_error', v_last_err);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_bulk_import_keys(text, jsonb, text) TO anon, authenticated;

DROP FUNCTION IF EXISTS public.rpc_export_all();
DROP FUNCTION IF EXISTS public.rpc_export_all(text);
CREATE OR REPLACE FUNCTION public.rpc_export_all(p_secret text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE result jsonb := '{}'::jsonb; v_role text;
BEGIN
  -- Only a signed-in ADMIN of THIS portal may export. This deliberately does NOT
  -- accept the provisioning secret: Pental holds that secret but is never an admin
  -- of a customer's portal, so Pental cannot call this and cannot read the data.
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_role IS DISTINCT FROM 'admin' THEN RETURN jsonb_build_object('error', 'Admin access required'); END IF;
  result := jsonb_build_object(
    'settings', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM settings) t), '[]'::jsonb),
    'profiles', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM profiles) t), '[]'::jsonb),
    'clients', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM clients) t), '[]'::jsonb),
    'assessments', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM assessments) t), '[]'::jsonb),
    'findings', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM findings) t), '[]'::jsonb),
    'proposals', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM proposals) t), '[]'::jsonb),
    'invoices', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM invoices) t), '[]'::jsonb),
    'kb_entries', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM kb_entries) t), '[]'::jsonb),
    'meetings', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM meetings) t), '[]'::jsonb),
    'meeting_attendees', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM meeting_attendees) t), '[]'::jsonb),
    'contractor_payments', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM contractor_payments) t), '[]'::jsonb),
    'email_notifications', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM email_notifications) t), '[]'::jsonb),
    'feedback', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM feedback) t), '[]'::jsonb),
    'tickets', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM tickets) t), '[]'::jsonb),
    'timeline_events', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM timeline_events) t), '[]'::jsonb),
    'assessment_comments', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM assessment_comments) t), '[]'::jsonb),
    'assessment_files', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM assessment_files) t), '[]'::jsonb),
    'qa_comments', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM qa_comments) t), '[]'::jsonb),
    'payment_events', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM payment_events) t), '[]'::jsonb),
    'login_codes', COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM login_codes) t), '[]'::jsonb)
  );
  -- Encryption keys and internal secrets are NEVER exported.
  RETURN result;
END;
$$;

-- 1798: THE SECRET COLUMNS OF `settings`, NAMED ONCE. Three grant blocks in
-- this file each carried their own copy of this list, and the last one (the one
-- that takes effect) had lost the two SSO client secrets and their ciphertext,
-- so every signed-in session, a customer's included, could read them. The grant
-- blocks and the signed-change notice's redaction all read this now.
CREATE OR REPLACE FUNCTION public._settings_secret_columns() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT ARRAY[
    'smtp_pass', 'smtp_oauth_refresh', 'stripe_secret_key', 'stripe_webhook_secret',
    'ai_api_key', 'teams_client_secret', 'zoom_client_secret', 'google_api_key',
    'slack_bot_token', 'sso_google_client_secret', 'sso_ms_client_secret',
    -- 1799: the headers a firm sends its own AI endpoint carry that endpoint's
    -- credential as often as not (an X-Api-Key, a bearer token), and every
    -- signed-in session could read them back. Write-only now, like the API
    -- key: this database adds them as a request to the endpoint leaves
    -- (_ai_endpoint, 1833; Pental's relay is given none from 1841), and the
    -- AI screen shows only whether any are set.
    'ai_custom_headers',
    -- 1851: not a secret, but for the firm's own people alone: the password
    -- managers revealed credentials may be sent to can name addresses inside
    -- the firm, and an administrator may write a fixed credential into an
    -- API's headers there. Withheld from every signed-in session, a client's
    -- included, and read by the firm's people through rpc_password_managers().
    'password_managers',
    -- The ciphertext companions: never read directly either. The definer
    -- functions that decrypt them are not bound by column grants.
    'smtp_pass_enc', 'smtp_oauth_refresh_enc', 'stripe_secret_key_enc',
    'stripe_webhook_secret_enc', 'ai_api_key_enc', 'teams_client_secret_enc',
    'zoom_client_secret_enc', 'google_api_key_enc', 'slack_bot_token_enc',
    'sso_google_client_secret_enc', 'sso_ms_client_secret_enc'
  ]::text[]
$$;
REVOKE EXECUTE ON FUNCTION public._settings_secret_columns() FROM PUBLIC, anon, authenticated;

-- ════════════════════════════════════════════════════════════════
-- COLUMN-LEVEL SELECT GRANTS (lock down secrets)
-- ════════════════════════════════════════════════════════════════
--
-- Settings: hide secret columns from authenticated. We previously listed
-- every non-secret column explicitly, but that approach is fragile across
-- schema generations: a column rename or a missing legacy column makes
-- the entire GRANT statement fail (PostgreSQL halts on the first column
-- that doesn't exist), leaving authenticated with NO read access at all
-- and 403s on every settings query.
--
-- New approach: dynamically build the grant from information_schema. We
-- read the actual columns of public.settings and grant SELECT on every
-- one EXCEPT the small known-secret list. This auto-adapts to any schema
-- variant, works whether the DB has favicon_data, favicon_url, or both.
DO $col_grants$
DECLARE
  v_cols text;
  v_secret_cols text[] := public._settings_secret_columns();
BEGIN
  SELECT string_agg(quote_ident(column_name), ', ')
    INTO v_cols
    FROM information_schema.columns
   WHERE table_schema = 'public'
     AND table_name = 'settings'
     AND column_name <> ALL(v_secret_cols);

  IF v_cols IS NOT NULL THEN
    EXECUTE 'REVOKE SELECT ON public.settings FROM authenticated';
    EXECUTE 'GRANT SELECT (' || v_cols || ') ON public.settings TO authenticated';
  END IF;
END
$col_grants$;
GRANT INSERT, UPDATE, DELETE ON public.settings TO authenticated;

-- Settings anon: branding columns only. Same dynamic-build approach as
-- authenticated above, list specifies what to EXCLUDE rather than
-- enumerate all included columns, so a missing column doesn't halt.
DO $col_grants$
DECLARE
  v_cols text;
  -- Anon gets a tighter set than authenticated: branding/cosmetic only.
  -- Anything not in this allowlist is excluded.
  v_allowed_cols text[] := ARRAY[
    'id','company_name','company_email','company_phone','company_website',
    'accent_color','theme_mode','severity_colors','severity_style','notification_color',
    'toast_success_color','logo_url','logo_url_light','pdf_logo_variant','email_logo_variant','password_login_enabled','font_display','font_body','font_mono','pdf_font_body','pdf_font_heading','email_font','favicon_data','favicon_url',
    'portal_title','login_title','login_subtitle','login_support_email',
    'login_button_text','login_custom_text','login_show_logo',
    'login_show_company_name','login_show_title','sso_google_enabled','sso_microsoft_enabled',
    -- 1522: white-label SSO. The IDs and the directory hint are ordinary
    -- settings; the two secrets are written through this same path and the
    -- encrypt trigger moves them out of the plaintext column on the way in.
    -- 1798: and so they are NOT on this list. "Moves them out" holds only when
    -- encryption succeeds; when it does not, the plaintext stays in the column,
    -- and this grant handed it to anybody holding the publishable key. The
    -- signed-in grants withhold both too (`_settings_secret_columns()`); the
    -- sign-in flow reads them through rpc_get_sso_config, which is signed.
    'sso_google_client_id','sso_ms_client_id','sso_ms_tenant',
    'theme_dark','theme_light','currency_code','currency_symbol',
    'day_rate','vat_rate','assessment_types','session_timeout_minutes',
    'session_timeout_action','email_enabled','feedback_mode',
    'proposals_enabled','invoices_enabled','feedback_enabled',
    'meet_calendar_enabled','meetings_enabled','contacts_enabled',
    'dashboard_enabled','qa_enabled','assessments_enabled','library_enabled','created_at','updated_at'
  ];
BEGIN
  SELECT string_agg(quote_ident(column_name), ', ')
    INTO v_cols
    FROM information_schema.columns
   WHERE table_schema = 'public'
     AND table_name = 'settings'
     AND column_name = ANY(v_allowed_cols);

  IF v_cols IS NOT NULL THEN
    EXECUTE 'REVOKE SELECT ON public.settings FROM anon';
    EXECUTE 'GRANT SELECT (' || v_cols || ') ON public.settings TO anon';
  END IF;
END
$col_grants$;
REVOKE INSERT, UPDATE, DELETE ON public.settings FROM anon;

-- Profiles: hide totp_secret, bank details from authenticated. Same
-- dynamic approach for resilience to schema variants.
DO $col_grants$
DECLARE
  v_cols text;
  v_secret_cols text[] := ARRAY[
    'totp_secret',
    -- A SIGNATURE IMAGE HAS NO CROSS-USER READER. profiles_auth_read is
    -- USING (true), so every authenticated user could read every profile row,
    -- and this column was in the granted set — meaning a client at one
    -- organisation could read the signature image of anybody in the tenant.
    -- The product only ever reads it for the CALLER'S OWN row, so nothing is
    -- lost by withholding it and serving that one row through an RPC.
    'signature_data',
    'bank_account_name',
    'bank_name',
    'bank_sort_code',
    'bank_account_number',
    'mfa_recovery_token',
    'mfa_recovery_expires_at',
    'mfa_verified_at',
    -- THE NAMES THIS TABLE ACTUALLY USES (1798). Three entries above are the
    -- settings table's names (bank_account_number) or were never columns here
    -- (mfa_recovery_token), so the real account number, the bank and the
    -- recovery code stayed readable to every signed-in user, a client
    -- included. Nothing in the portal selects them; the one reader is
    -- rpc_get_profile_bank_details, which runs as the definer.
    'bank_account',
    'bank_institution',
    'mfa_recovery_code'
  ];
BEGIN
  SELECT string_agg(quote_ident(column_name), ', ')
    INTO v_cols
    FROM information_schema.columns
   WHERE table_schema = 'public'
     AND table_name = 'profiles'
     AND column_name <> ALL(v_secret_cols);

  IF v_cols IS NOT NULL THEN
    EXECUTE 'REVOKE SELECT ON public.profiles FROM authenticated';
    EXECUTE 'GRANT SELECT (' || v_cols || ') ON public.profiles TO authenticated';
  END IF;
END
$col_grants$;
GRANT INSERT, UPDATE, DELETE ON public.profiles TO authenticated;

-- Profiles anon: no direct access (use rpc_profile_lookup)
REVOKE ALL ON public.profiles FROM anon;

-- Write grants for data tables
DO $wg$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['settings','profiles','clients','assessments','findings','proposals','invoices','kb_entries','meetings','meeting_attendees','tickets','timeline_events','assessment_comments','assessment_files','feedback','contractor_payments','email_notifications','payment_events','qa_comments'] LOOP
    EXECUTE format('GRANT INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
  END LOOP;
END $wg$;

-- Secret tables: service_role ONLY
REVOKE ALL ON public._credentials_key FROM anon, authenticated;
REVOKE ALL ON public._encryption_keys FROM anon, authenticated;
REVOKE ALL ON public._internal_secrets FROM anon, authenticated;
REVOKE ALL ON public.login_codes FROM anon, authenticated;
GRANT ALL ON public._credentials_key TO service_role;
GRANT ALL ON public._encryption_keys TO service_role;
GRANT ALL ON public._internal_secrets TO service_role;
GRANT ALL ON public.login_codes TO service_role;

-- ════════════════════════════════════════════════════════════════
-- FUNCTION GRANTS
-- ════════════════════════════════════════════════════════════════
-- Several function signatures change in later patch sections of this
-- file (e.g. rpc_update_settings goes from 2-arg to 3-arg to 4-arg
-- across hardening passes). On a fresh install all original signatures
-- exist at this point, so all GRANTs succeed. On a re-run after a
-- partial earlier execution, some signatures may already have been
-- swapped, wrapping the whole block in a DO that catches
-- undefined_function lets the script continue rather than halting on a
-- stale signature reference. The later patch sections re-issue GRANTs
-- on the new signatures, so authoritative permissions are always set
-- correctly by script-end.
DO $grants$
BEGIN
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_login_code_create(text, text, timestamptz, text) TO anon, authenticated, service_role';
EXCEPTION WHEN undefined_function THEN NULL; END $grants$;
