-- ════════════════════════════════════════════════════════════════
-- PROPOSAL COUNTER-SIGNATURE RPCs
-- Portal calls these with user JWT; role checks enforce who can read/write.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.get_proposals_auth(p_ids uuid[]) RETURNS TABLE (
  id uuid, authorised_by text, authorised_title text, authorised_email text,
  authorised_signature text, authorised_at timestamptz
) AS $$
DECLARE v_role text; v_cid uuid;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  -- 1943: the role the rules read, so a contractor while contractors are off
  -- reads nothing here either.
  v_role := public.current_user_role(); v_cid := public.current_user_client_id();
  IF v_role IS NULL THEN RETURN; END IF;
  -- 1841: a contractor, the proposals they made, sent or are working with
  -- the client of (as proposals_read).
  IF v_role IN ('admin','senior','sales','standard') THEN
    RETURN QUERY SELECT p.id, p.authorised_by, p.authorised_title, p.authorised_email, p.authorised_signature, p.authorised_at
      FROM public.proposals p WHERE p.id = ANY(p_ids);
  ELSIF v_role = 'contractor' THEN
    RETURN QUERY SELECT p.id, p.authorised_by, p.authorised_title, p.authorised_email, p.authorised_signature, p.authorised_at
      FROM public.proposals p WHERE p.id = ANY(p_ids)
       AND (p.created_by = public.current_profile_id() OR p.sent_by = public.current_profile_id() OR public.can_access_client(p.client_id));
  ELSIF v_role = 'client' THEN
    RETURN QUERY SELECT p.id, p.authorised_by, p.authorised_title, p.authorised_email, p.authorised_signature, p.authorised_at
      FROM public.proposals p WHERE p.id = ANY(p_ids) AND p.client_id = v_cid;
  END IF;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.save_proposal_auth(p_id uuid, p_by text, p_title text, p_email text, p_sig text, p_at timestamptz) RETURNS boolean AS $$
DECLARE v_role text;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  v_role := public.current_user_role();   -- 1943: as get_proposals_auth
  IF v_role IS NULL OR v_role NOT IN ('admin','senior','sales','contractor') THEN RETURN false; END IF;
  -- 1841: a contractor, on a proposal of a client they work with (as
  -- proposals_update).
  UPDATE public.proposals SET authorised_by = p_by, authorised_title = p_title, authorised_email = p_email,
    authorised_signature = p_sig, authorised_at = COALESCE(p_at, now()), updated_at = now()
    WHERE id = p_id
      AND (v_role <> 'contractor' OR public.can_access_client(client_id));
  RETURN FOUND;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.sync_profile_auth_id() RETURNS boolean AS $$
DECLARE v_email text; v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
  IF v_email IS NULL THEN RETURN false; END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles SET auth_user_id = v_uid, updated_at = now()
    WHERE lower(email) = lower(v_email) AND (auth_user_id IS NULL OR auth_user_id != v_uid);
  RETURN FOUND;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

GRANT EXECUTE ON FUNCTION public.get_proposals_auth(uuid[]) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.save_proposal_auth(uuid, text, text, text, text, timestamptz) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.sync_profile_auth_id() TO authenticated, service_role;

-- ════════════════════════════════════════════════════════════════
-- SELF-SERVICE PROFILE AND SETTINGS RPCs
-- Used by the portal to update a user's own profile and to patch a single
-- PDF template's config block without re-uploading megabytes of image data.
-- The app has direct-UPDATE fallbacks if these RPCs are missing, but having
-- them is faster (especially for pdf_templates) and removes a confusing
-- error path.
-- ════════════════════════════════════════════════════════════════

-- save_own_profile: update the CURRENT user's profile row only. Allowlists
-- which columns may be edited so users can't elevate role or flip active/is_test.
DROP FUNCTION IF EXISTS public.save_own_profile(jsonb);
CREATE OR REPLACE FUNCTION public.save_own_profile(updates jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_pid uuid; v_allowed text[]; v_set text := ''; v_key text; v_val text;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  v_pid := public.current_profile_id();
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF updates IS NULL OR jsonb_typeof(updates) != 'object' THEN RETURN jsonb_build_object('success', false, 'error', 'Invalid updates'); END IF;

  v_allowed := ARRAY['name','phone','job_title','contractor_company','teams_link','slack_link',
                     'avatar_url','signature_data','bank_name','bank_sort_code','bank_account',
                     'bank_institution','viewed_findings','findings_viewed_at','onboarding_completed_at'];

  PERFORM set_config('pental.bypass_protect', 'true', true);
  FOR v_key IN SELECT * FROM jsonb_object_keys(updates) LOOP
    IF v_key = ANY(v_allowed) THEN
      v_set := v_set || CASE WHEN v_set = '' THEN '' ELSE ', ' END || quote_ident(v_key) || ' = ';
      IF updates->v_key IS NULL OR jsonb_typeof(updates->v_key) = 'null' THEN
        v_set := v_set || 'NULL';
      ELSIF jsonb_typeof(updates->v_key) = 'object' OR jsonb_typeof(updates->v_key) = 'array' THEN
        v_set := v_set || quote_literal((updates->v_key)::text) || '::jsonb';
      ELSE
        v_set := v_set || quote_nullable(updates->>v_key);
      END IF;
    END IF;
  END LOOP;

  IF v_set = '' THEN RETURN jsonb_build_object('success', false, 'error', 'No allowed fields'); END IF;
  EXECUTE 'UPDATE public.profiles SET ' || v_set || ', updated_at = now() WHERE id = ' || quote_literal(v_pid::text) || '::uuid';
  RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;
GRANT EXECUTE ON FUNCTION public.save_own_profile(jsonb) TO authenticated, service_role;

-- update_pdf_template_config: patch settings.pdf_templates[<template_key>] with
-- a new config JSON object, without rewriting the image fields already stored
-- under that key. The app strips image data client-side before calling this so
-- we only need to merge the new non-image fields back in. Without this RPC,
-- the app falls back to a full settings UPDATE which re-sends all images.
DROP FUNCTION IF EXISTS public.update_pdf_template_config(uuid, text, text);
CREATE OR REPLACE FUNCTION public.update_pdf_template_config(settings_id uuid, template_key text, config_json text)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_existing jsonb; v_prev jsonb; v_new jsonb; v_merged jsonb;
  v_img_fields text[] := ARRAY['logoData','headerImageData','footerImageData','watermarkData','coverImageData','backgroundImageData'];
  v_f text;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  IF NOT public.is_staff() THEN RETURN jsonb_build_object('success', false, 'error', 'Forbidden'); END IF;

  -- 1924: the row is held while it is read and written, so two saves of
  -- different templates at the same moment cannot each write back the other's
  -- copy of the rest.
  SELECT pdf_templates INTO v_existing FROM public.settings WHERE id = settings_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Settings row not found'); END IF;

  BEGIN v_new := config_json::jsonb; EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success', false, 'error', 'Invalid config_json'); END;
  v_existing := COALESCE(v_existing, '{}'::jsonb);
  v_prev := COALESCE(v_existing->template_key, '{}'::jsonb);

  -- Preserve image fields from the previous config block so clients don't need to resend them.
  v_merged := v_new;
  FOREACH v_f IN ARRAY v_img_fields LOOP
    IF v_prev ? v_f AND NOT (v_merged ? v_f) THEN
      v_merged := v_merged || jsonb_build_object(v_f, v_prev->v_f);
    END IF;
  END LOOP;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.settings
    SET pdf_templates = jsonb_set(v_existing, ARRAY[template_key], v_merged, true),
        updated_at = now()
    WHERE id = settings_id;
  RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;
GRANT EXECUTE ON FUNCTION public.update_pdf_template_config(uuid, text, text) TO authenticated, service_role;

-- 1924: ONLY WHAT WAS CHANGED, AND ONLY OVER WHAT IT WAS CHANGED FROM. The
-- function above replaces a template's whole block of settings with the one the
-- editor sends, so two people setting up one report template at once each put
-- back the other's settings as they had first seen them. This takes the
-- settings that were changed (`changed_json`) with the values they were changed
-- from (`expected_json`), writes them into the block as it is now, and writes
-- nothing when one of them has been changed by somebody else since: it answers
-- `changed` with those settings and the block as it is, for the person to
-- choose. A setting nobody else touched is never in question.
CREATE OR REPLACE FUNCTION public.update_pdf_template_config_merge(settings_id uuid, template_key text, changed_json text, expected_json text DEFAULT NULL)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_existing jsonb; v_prev jsonb; v_changed jsonb; v_expected jsonb; v_k text; v_clash text[] := ARRAY[]::text[];
BEGIN
  PERFORM public._need_fresh_mfa();
  IF NOT public.is_staff() THEN RETURN jsonb_build_object('success', false, 'error', 'Forbidden'); END IF;
  BEGIN
    v_changed := changed_json::jsonb;
    v_expected := COALESCE(NULLIF(expected_json, '')::jsonb, '{}'::jsonb);
  EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('success', false, 'error', 'Invalid config_json'); END;
  IF jsonb_typeof(v_changed) <> 'object' OR jsonb_typeof(v_expected) <> 'object' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid config_json');
  END IF;
  SELECT pdf_templates INTO v_existing FROM public.settings WHERE id = settings_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Settings row not found'); END IF;
  v_existing := COALESCE(v_existing, '{}'::jsonb);
  v_prev := COALESCE(v_existing->template_key, '{}'::jsonb);
  -- A setting that is not there and one that is empty (JSON null) are the same
  -- setting, so a first save is not taken for a clash with nothing.
  FOR v_k IN SELECT jsonb_object_keys(v_changed) LOOP
    IF v_expected ? v_k
       AND COALESCE(v_prev->v_k, 'null'::jsonb) IS DISTINCT FROM COALESCE(v_expected->v_k, 'null'::jsonb)
       AND COALESCE(v_prev->v_k, 'null'::jsonb) IS DISTINCT FROM COALESCE(v_changed->v_k, 'null'::jsonb) THEN
      v_clash := v_clash || v_k;
    END IF;
  END LOOP;
  IF array_length(v_clash, 1) > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'changed', 'fields', to_jsonb(v_clash), 'current', v_prev);
  END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.settings
    SET pdf_templates = jsonb_set(v_existing, ARRAY[template_key], v_prev || v_changed, true),
        updated_at = now()
    WHERE id = settings_id;
  RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;
REVOKE ALL ON FUNCTION public.update_pdf_template_config_merge(uuid, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_pdf_template_config_merge(uuid, text, text, text) TO authenticated, service_role;

-- update_pdf_templates_full: full overwrite of settings.pdf_templates jsonb
-- in one call. Used by the multi-template save path which rewrites the
-- templates array, default pointer, and possibly migrates legacy singular
-- templates all in one go, the per-key RPC above can't do that atomically.
DROP FUNCTION IF EXISTS public.update_pdf_templates_full(uuid, jsonb);
-- 1924: `p_expected_version`, the settings row's version the templates were
-- read at. Given, the write is made only if the row is still that version, and
-- otherwise answers `changed` with the version it is now, so the portal reads
-- the templates again and puts the two people's changes together rather than
-- writing back a copy from before somebody else's. Left out (an older portal),
-- it writes as it always did.
DROP FUNCTION IF EXISTS public.update_pdf_templates_full(uuid, jsonb, bigint);
CREATE OR REPLACE FUNCTION public.update_pdf_templates_full(p_settings_id uuid, p_pdf_templates jsonb, p_expected_version bigint DEFAULT NULL)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
  SET statement_timeout = '120s'
AS $$
DECLARE v_ver bigint;
BEGIN
  PERFORM public._need_fresh_mfa();   -- 1841
  -- BYO is single-tenant: just verify the caller is an active staff member.
  -- There's no tenant_id to cross-check against.
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE auth_user_id = auth.uid()
       AND role IN ('admin','senior')
       AND active = true
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Forbidden - admin/senior role required');
  END IF;
  -- Confirm the settings row exists (BYO has one row, but guard anyway)
  SELECT row_version INTO v_ver FROM public.settings WHERE id = p_settings_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Settings row not found');
  END IF;
  IF p_expected_version IS NOT NULL AND v_ver IS DISTINCT FROM p_expected_version THEN
    RETURN jsonb_build_object('success', false, 'error', 'changed', 'row_version', v_ver);
  END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.settings
     SET pdf_templates = COALESCE(p_pdf_templates, '{}'::jsonb),
         updated_at = now()
   WHERE id = p_settings_id
   RETURNING row_version INTO v_ver;
  RETURN jsonb_build_object('success', true, 'row_version', v_ver);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;
GRANT EXECUTE ON FUNCTION public.update_pdf_templates_full(uuid, jsonb, bigint) TO authenticated, service_role;

-- ════════════════════════════════════════════════════════════════
-- CRON RPCs (BYO single-tenant version)
-- Called by pentalportal/api/cron-assessment-status.js with service_role key.
-- On master, the same RPCs exist but accept p_tenant_id; BYO versions ignore it
-- because the whole database represents one tenant. We accept p_tenant_id for
-- signature parity (cron handler sends it) but do not filter by it.
-- ════════════════════════════════════════════════════════════════

-- 1500: THE FIRM'S OWN CLOCK, AND THE FIRM'S OWN REMINDER SCHEDULE.
--
-- `v_today` was Europe/London for everybody. It is now whatever the tenant set,
-- because "today" is what decides whether an assessment dated the 5th is due,
-- and a firm five hours behind London had that roll over on the evening of the
-- 4th.
--
-- The credential leg took a hardcoded seven-day window. It now takes the widest
-- offset the firm configured, and the handler picks the exact days out of the
-- list -- so a firm that wants one reminder the day before is not selecting a
-- week of assessments and discarding six days of them.
CREATE OR REPLACE FUNCTION public.rpc_cron_get_pending(p_action text, p_tenant_id uuid DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_tz text := 'Europe/London';
  v_today date;
  v_assessments jsonb := '[]'::jsonb;
  v_settings jsonb;
  v_row record;
  v_cred_days int := 7;
BEGIN
  -- Gather settings (SMTP + branding + email toggles + the automation clock).
  -- Every automation field the handler needs travels with this, so a cron pass
  -- does not need a second round trip per tenant per action.
  SELECT to_jsonb(s) INTO v_settings FROM (
    SELECT email_enabled, smtp_from_name, smtp_from_email, company_name,
           -- 1709: the automatic start sends the firm's "testing started"
           -- email, so it answers to that email's switch too.
           COALESCE(notify_test_started, true) AS notify_test_started,
           COALESCE(NULLIF(automation_timezone, ''), 'Europe/London') AS automation_timezone,
           COALESCE(automation_workdays_only, false) AS automation_workdays_only,
           COALESCE(auto_credentials_enabled, true) AS auto_credentials_enabled,
           COALESCE(NULLIF(auto_credentials_time, ''), '09:00') AS auto_credentials_time,
           COALESCE(NULLIF(auto_credentials_days, ''), '7,3,1') AS auto_credentials_days
      FROM public.settings LIMIT 1
  ) s;

  -- A TIMEZONE NOBODY VALIDATED MUST NOT TAKE THE CRON DOWN FOR EVERY TENANT.
  -- An unknown name raises on the cast, so it is tried here and falls back
  -- rather than aborting the pass.
  BEGIN
    v_tz := COALESCE(NULLIF(v_settings->>'automation_timezone', ''), 'Europe/London');
    v_today := (now() AT TIME ZONE v_tz)::date;
  EXCEPTION WHEN OTHERS THEN
    v_tz := 'Europe/London';
    v_today := (now() AT TIME ZONE v_tz)::date;
  END;

  -- The widest offset in the list decides how far ahead to look. Anything
  -- unparseable leaves the historic seven.
  BEGIN
    SELECT GREATEST(1, LEAST(90, MAX(trim(x)::int)))
      INTO v_cred_days
      FROM unnest(string_to_array(COALESCE(v_settings->>'auto_credentials_days', '7'), ',')) AS x
     WHERE trim(x) ~ '^[0-9]+$';
  EXCEPTION WHEN OTHERS THEN v_cred_days := 7; END;
  IF v_cred_days IS NULL THEN v_cred_days := 7; END IF;

  IF p_action = 'start' THEN
    -- Draft/pending assessments whose start_date has arrived, not yet active
    FOR v_row IN
      SELECT a.id, a.name, a.start_date, a.end_date, c.contact_email
      FROM public.assessments a LEFT JOIN public.clients c ON c.id = a.client_id
      WHERE a.status = 'draft' AND a.start_date IS NOT NULL AND a.start_date <= v_today AND a.archived_at IS NULL
    LOOP
      v_assessments := v_assessments || jsonb_build_array(jsonb_build_object(
        'id', v_row.id, 'name', v_row.name, 'start_date', v_row.start_date,
        'end_date', v_row.end_date, 'contact_email', v_row.contact_email
      ));
    END LOOP;
  ELSIF p_action = 'complete' THEN
    FOR v_row IN
      SELECT a.id, a.name, a.start_date, a.end_date, c.contact_email
      FROM public.assessments a LEFT JOIN public.clients c ON c.id = a.client_id
      WHERE a.status = 'active' AND a.end_date IS NOT NULL AND a.end_date <= v_today AND a.archived_at IS NULL
    LOOP
      v_assessments := v_assessments || jsonb_build_array(jsonb_build_object(
        'id', v_row.id, 'name', v_row.name, 'start_date', v_row.start_date,
        'end_date', v_row.end_date, 'contact_email', v_row.contact_email
      ));
    END LOOP;
  ELSIF p_action = 'credentials' AND COALESCE((v_settings->>'auto_credentials_enabled')::boolean, true) THEN
    -- Upcoming authenticated assessments still awaiting credentials, out to the
    -- widest reminder offset the firm configured. The handler decides which of
    -- those days actually gets a mail.
    FOR v_row IN
      SELECT a.id, a.name, a.start_date, a.end_date, c.contact_email
      FROM public.assessments a LEFT JOIN public.clients c ON c.id = a.client_id
      WHERE a.test_perspective = 'authenticated'
        AND a.credentials_status IN ('none','awaiting')
        AND a.start_date IS NOT NULL
        AND a.start_date > v_today
        AND a.start_date <= v_today + make_interval(days => v_cred_days)
        AND a.archived_at IS NULL
    LOOP
      v_assessments := v_assessments || jsonb_build_array(jsonb_build_object(
        'id', v_row.id, 'name', v_row.name, 'start_date', v_row.start_date,
        'end_date', v_row.end_date, 'contact_email', v_row.contact_email
      ));
    END LOOP;
  END IF;

  -- `today` and `tz` travel back with the rows. The handler gates on the same
  -- date this query selected on, rather than recomputing it from its own idea
  -- of the timezone and disagreeing across the midnight boundary.
  RETURN jsonb_build_object('assessments', v_assessments,
                            'settings', COALESCE(v_settings, '{}'::jsonb),
                            'today', v_today, 'tz', v_tz);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_cron_process(p_assessment_id uuid, p_new_status text, p_qa_status text, p_timeline_title text, p_timeline_event text, p_tenant_id uuid DEFAULT NULL) RETURNS boolean AS $$
BEGIN
  UPDATE public.assessments SET status = p_new_status, qa_status = COALESCE(p_qa_status, qa_status), updated_at = now()
    WHERE id = p_assessment_id;
  IF NOT FOUND THEN RETURN false; END IF;
  BEGIN
    INSERT INTO public.timeline_events (assessment_id, type, title, event, details)
    VALUES (p_assessment_id, 'cron', p_timeline_title, p_timeline_event, 'Automated by Pental');
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

CREATE OR REPLACE FUNCTION public.rpc_cron_queue_email(p_to text, p_subject text, p_body text, p_type text DEFAULT 'general', p_related_id uuid DEFAULT NULL, p_from_name text DEFAULT NULL, p_from_email text DEFAULT NULL, p_tenant_id uuid DEFAULT NULL) RETURNS uuid AS $$
DECLARE v_id uuid;
BEGIN
  INSERT INTO public.email_notifications (to_email, subject, body, notification_type, related_id, from_name, from_email, status, attempts)
  VALUES (lower(p_to), p_subject, p_body, p_type, p_related_id, p_from_name, p_from_email, 'pending', 0)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- ═══════════════════════════════════════════════════════════════════════════
-- THE SCHEDULE RUNS ON ITS OWN (1796, 2025092801).
--
-- [stated] Arian: "assessments seem to still be starting when admin signs in
-- and it should be automated with the cron."
--
-- The three functions above were never reachable by the cron. They are granted
-- to service_role alone, Pental holds no firm's service-role key, and the cron
-- called them with the publishable one, so every pass was refused and the only
-- thing that ever started an assessment was the portal itself, once somebody
-- who could edit signed in. They stay for the tests that exercise them; nothing
-- in the product calls them now.
--
-- This is the one call the cron makes instead. SIGNED, so it answers to Pental's
-- key pair and its cosigner and to nothing a breach of the portal's host could
-- produce: not the provisioning secret, and not a signed-in user. NARROW, so the
-- most anybody can do with it is what the firm's own schedule already says
-- should happen: it takes no ids and no statuses, decides everything here in
-- the firm's own timezone, and hands back what the portal needs to write the
-- emails.
--
-- A moment falls due at the assessment's date and its own time, or the firm's
-- default time when it has none. With working days only, a date on a weekend
-- moves to the Monday at the same time, and nothing moves on a Saturday or
-- Sunday. A moment that has passed is due at the next pass.
--
-- Rows are taken FOR UPDATE SKIP LOCKED and changed only from the state they
-- were read in, so two passes arriving together start an assessment once and
-- email about it once. A hundred of each per pass; the next pass takes the rest.
--
-- 1797: AND THE TWO THINGS THE PORTAL STILL DID ON SOMEBODY'S SIGN-IN.
-- [stated] Arian: "yes the two others fix them all". An invoice set to go
-- after a delay went only when somebody who could edit opened the portal after
-- the delay had passed, and a meeting that had ended was marked completed (and
-- a scoping call became a client) only when a member of staff signed in. Both
-- are legs here now, `invoices` and `meetings`, and the portal does neither.
CREATE OR REPLACE FUNCTION public._automation_day(p_day date, p_workdays boolean)
RETURNS date LANGUAGE sql IMMUTABLE AS $autoday$
  SELECT CASE WHEN p_workdays AND EXTRACT(ISODOW FROM p_day) = 6 THEN p_day + 2
              WHEN p_workdays AND EXTRACT(ISODOW FROM p_day) = 7 THEN p_day + 1
              ELSE p_day END
$autoday$;
REVOKE ALL ON FUNCTION public._automation_day(date, boolean) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_automation_due(
  p_action text DEFAULT 'due',
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $autodue$
DECLARE
  v_mode text;
  v_s record;
  v_r record;
  v_tz text;
  v_now timestamp;
  v_today date;
  v_workdays boolean;
  v_start_def time;
  v_end_def time;
  v_cred_time time;
  v_cred_days int[];
  v_started uuid[] := ARRAY[]::uuid[];
  v_completed uuid[] := ARRAY[]::uuid[];
  v_reminded uuid[] := ARRAY[]::uuid[];
  v_skipped jsonb := '{}'::jsonb;
  v_rows jsonb;
  v_started_rows jsonb;
  v_completed_rows jsonb;
  v_reminder_rows jsonb;
  -- 1797
  v_inv_days int;
  v_inv_docx boolean;
  v_invoiced uuid[] := ARRAY[]::uuid[];
  v_invoice_rows jsonb := '[]'::jsonb;
  v_meet_at timestamp;
  v_met int := 0;
  v_clients_made int := 0;
  v_client_name text;
  -- 1800
  v_overdue uuid[] := ARRAY[]::uuid[];
BEGIN
  -- 1800: 'now' is the whole due pass, asked for by the firm's own team (a
  -- change that can make something due at once, or "Run now") rather than by
  -- the clock. It is signed for its own operation, so the log of Pental's
  -- signed calls keeps the two apart: "The schedule last ran" on the
  -- Automation page reads the clock's passes only, and a schedule that has
  -- stopped cannot look alive because somebody saved an assessment.
  v_mode := public._pental_authorise(p_auth, p_secret,
    CASE WHEN p_action = 'now' THEN 'rpc_automation_now' ELSE 'rpc_automation_due' END, true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF COALESCE(p_action, '') NOT IN ('due', 'now', 'start', 'complete', 'credentials', 'invoices', 'overdue', 'meetings') THEN
    RAISE EXCEPTION 'Unknown action';
  END IF;
  IF p_action = 'now' THEN p_action := 'due'; END IF;

  SELECT * INTO v_s FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;

  -- A zone or a time nobody validated falls back rather than stopping the pass.
  BEGIN
    v_tz := COALESCE(NULLIF(trim(v_s.automation_timezone), ''), 'Europe/London');
    v_now := now() AT TIME ZONE v_tz;
  EXCEPTION WHEN OTHERS THEN
    v_tz := 'Europe/London';
    v_now := now() AT TIME ZONE v_tz;
  END;
  v_today := v_now::date;
  v_workdays := COALESCE(v_s.automation_workdays_only, false);
  BEGIN v_start_def := COALESCE(NULLIF(trim(v_s.auto_start_time), ''), '09:00')::time;
  EXCEPTION WHEN OTHERS THEN v_start_def := '09:00'; END;
  BEGIN v_end_def := COALESCE(NULLIF(trim(v_s.auto_complete_time), ''), '17:00')::time;
  EXCEPTION WHEN OTHERS THEN v_end_def := '17:00'; END;
  BEGIN v_cred_time := COALESCE(NULLIF(trim(v_s.auto_credentials_time), ''), '09:00')::time;
  EXCEPTION WHEN OTHERS THEN v_cred_time := '09:00'; END;
  BEGIN
    SELECT COALESCE(array_agg(DISTINCT trim(x)::int), ARRAY[]::int[]) INTO v_cred_days
      FROM unnest(string_to_array(COALESCE(v_s.auto_credentials_days, '7,3,1'), ',')) AS x
     WHERE trim(x) ~ '^[0-9]{1,2}$' AND trim(x)::int BETWEEN 1 AND 90;
  EXCEPTION WHEN OTHERS THEN v_cred_days := ARRAY[7, 3, 1]; END;

  -- ── Start: a draft with a lead, once its moment has come ──────────────────
  IF p_action IN ('due', 'start') THEN
    IF COALESCE(v_s.auto_start_enabled, true) IS FALSE THEN
      v_skipped := v_skipped || jsonb_build_object('start', 'off');
    ELSIF v_workdays AND EXTRACT(ISODOW FROM v_today) IN (6, 7) THEN
      v_skipped := v_skipped || jsonb_build_object('start', 'weekend');
    ELSE
      FOR v_r IN
        SELECT a.id, public._automation_day(a.start_date, v_workdays) + COALESCE(a.start_time, v_start_def) AS due_at
          FROM public.assessments a
         WHERE a.status = 'draft' AND a.archived_at IS NULL
           AND a.start_date IS NOT NULL AND a.lead_id IS NOT NULL
           AND public._automation_day(a.start_date, v_workdays) + COALESCE(a.start_time, v_start_def) <= v_now
         ORDER BY 2, a.id
         LIMIT 100
         FOR UPDATE OF a SKIP LOCKED
      LOOP
        UPDATE public.assessments SET status = 'active', updated_at = now()
         WHERE id = v_r.id AND status = 'draft';
        IF FOUND THEN
          -- Stamped at the moment it was scheduled for, like a start by hand,
          -- because the timeline reads its steps in that order.
          INSERT INTO public.timeline_events (assessment_id, type, title, event, user_name, created_at)
          VALUES (v_r.id, 'cron', 'Testing started', 'Testing started', 'System',
                  LEAST(v_r.due_at AT TIME ZONE v_tz, now()));
          v_started := v_started || v_r.id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ── Complete: an active assessment, once its end has come ─────────────────
  -- Completing does not send the report to QA; the tester does that (1413).
  IF p_action IN ('due', 'complete') THEN
    IF COALESCE(v_s.auto_complete_enabled, true) IS FALSE THEN
      v_skipped := v_skipped || jsonb_build_object('complete', 'off');
    ELSIF v_workdays AND EXTRACT(ISODOW FROM v_today) IN (6, 7) THEN
      v_skipped := v_skipped || jsonb_build_object('complete', 'weekend');
    ELSE
      FOR v_r IN
        SELECT a.id, public._automation_day(a.end_date, v_workdays) + COALESCE(a.end_time, v_end_def) AS due_at
          FROM public.assessments a
         WHERE a.status = 'active' AND a.archived_at IS NULL
           AND a.end_date IS NOT NULL
           AND public._automation_day(a.end_date, v_workdays) + COALESCE(a.end_time, v_end_def) <= v_now
           -- Started this pass: it ends on a later pass, not in the same breath.
           AND NOT (a.id = ANY (v_started))
         ORDER BY 2, a.id
         LIMIT 100
         FOR UPDATE OF a SKIP LOCKED
      LOOP
        UPDATE public.assessments SET status = 'completed', updated_at = now()
         WHERE id = v_r.id AND status = 'active';
        IF FOUND THEN
          INSERT INTO public.timeline_events (assessment_id, type, title, event, user_name, created_at)
          VALUES (v_r.id, 'cron', 'Testing completed', 'Testing completed', 'System',
                  LEAST(v_r.due_at AT TIME ZONE v_tz, now()));
          v_completed := v_completed || v_r.id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ── Credential reminders: once a day, on the days the firm named ──────────
  -- Not a weekday rule: a client can be reminded on a Saturday, as before. A
  -- cancelled engagement is not reminded about at all.
  IF p_action IN ('due', 'credentials') THEN
    IF COALESCE(v_s.auto_credentials_enabled, true) IS FALSE THEN
      v_skipped := v_skipped || jsonb_build_object('credentials', 'off');
    ELSIF COALESCE(array_length(v_cred_days, 1), 0) = 0 THEN
      v_skipped := v_skipped || jsonb_build_object('credentials', 'no days');
    ELSIF v_now::time < v_cred_time THEN
      v_skipped := v_skipped || jsonb_build_object('credentials', 'not yet');
    ELSE
      FOR v_r IN
        SELECT a.id
          FROM public.assessments a
         WHERE a.test_perspective = 'authenticated'
           AND a.credentials_status IN ('none', 'awaiting')
           AND a.status IN ('draft', 'active')
           AND a.archived_at IS NULL
           AND a.start_date IS NOT NULL
           AND (a.start_date - v_today) = ANY (v_cred_days)
           AND a.credentials_reminded_on IS DISTINCT FROM v_today
         ORDER BY a.start_date, a.id
         LIMIT 100
         FOR UPDATE OF a SKIP LOCKED
      LOOP
        UPDATE public.assessments SET credentials_reminded_on = v_today WHERE id = v_r.id;
        v_reminded := v_reminded || v_r.id;
      END LOOP;
    END IF;
  END IF;

  -- ── Invoices: a draft that was to go after a delay, once it has passed ────
  -- Settings, Invoices: "generate, then send after N days", counted from the
  -- report's delivery, as the portal counted it. The module off, or any other
  -- choice there, sends nothing. The email is the portal's "invoice_sent", with
  -- its own switch, written by the cron from the rows below.
  --
  -- Nor with a custom invoice template (a Word file under Templates), which
  -- Settings shows as switching automation off: that invoice is downloaded,
  -- made into a PDF and uploaded by hand, and sending the draft would send the
  -- client the default one instead. The portal's own sender did not check.
  IF p_action IN ('due', 'invoices') THEN
    v_inv_days := COALESCE(v_s.invoice_auto_send_days, 0);
    -- A template in the list the portal keeps, or the older single one.
    v_inv_docx := COALESCE(CASE
        WHEN jsonb_typeof(v_s.pdf_templates -> 'docx_templates_invoice') = 'array' THEN EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_s.pdf_templates -> 'docx_templates_invoice') t
           WHERE jsonb_typeof(t) = 'object'
             AND (COALESCE(t ->> 'data', '') <> '' OR COALESCE(t ->> 'storage_path', '') <> ''))
        ELSE jsonb_typeof(v_s.pdf_templates -> 'docx_template_invoice') = 'object'
             AND (COALESCE(v_s.pdf_templates -> 'docx_template_invoice' ->> 'data', '') <> ''
                  OR COALESCE(v_s.pdf_templates -> 'docx_template_invoice' ->> 'storage_path', '') <> '')
      END, false);
    IF COALESCE(v_s.invoices_enabled, false) IS FALSE THEN
      v_skipped := v_skipped || jsonb_build_object('invoices', 'off');
    ELSIF COALESCE(v_s.invoice_automation, 'manual') <> 'generate_send_delayed' OR v_inv_days <= 0 THEN
      v_skipped := v_skipped || jsonb_build_object('invoices', 'not on a delay');
    ELSIF v_inv_docx THEN
      v_skipped := v_skipped || jsonb_build_object('invoices', 'custom invoice template');
    ELSE
      FOR v_r IN
        SELECT i.id, i.assessment_id
          FROM public.invoices i
          JOIN public.assessments a ON a.id = i.assessment_id
         WHERE i.status = 'draft' AND i.archived_at IS NULL
           AND a.status = 'delivered' AND a.delivered_at IS NOT NULL
           AND a.delivered_at + make_interval(days => v_inv_days) <= now()
         ORDER BY a.delivered_at, i.id
         LIMIT 100
         FOR UPDATE OF i SKIP LOCKED
      LOOP
        UPDATE public.invoices SET status = 'sent', sent_at = now(), updated_at = now()
         WHERE id = v_r.id AND status = 'draft';
        IF FOUND THEN
          INSERT INTO public.timeline_events (assessment_id, type, title, event, user_name)
          VALUES (v_r.assessment_id, 'cron',
                  'Invoice auto-sent after ' || v_inv_days || ' day delay',
                  'Invoice auto-sent after ' || v_inv_days || ' day delay', 'System');
          v_invoiced := v_invoiced || v_r.id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ── Overdue: a sent invoice whose due date has gone (1800) ────────────────
  -- [stated] Arian: "automation seems broken as well, it didnt auto start the
  -- assessment for example i assume other areas broken as well". One of them:
  -- the setup wizard has always said unpaid invoices "transition to overdue
  -- automatically", and nothing ever moved one. The status was written by
  -- nobody, so an invoice a month late still read "sent" on every screen and to
  -- the client. The day after its due date, in the firm's timezone, it is
  -- overdue. Paying works from either status, as it always has. Not one this
  -- pass has only just sent, and nothing with the Invoices module off.
  IF p_action IN ('due', 'overdue') THEN
    IF COALESCE(v_s.invoices_enabled, false) IS FALSE THEN
      v_skipped := v_skipped || jsonb_build_object('overdue', 'off');
    ELSE
      FOR v_r IN
        SELECT i.id, i.assessment_id, i.invoice_number
          FROM public.invoices i
         WHERE i.status = 'sent' AND i.archived_at IS NULL
           AND i.due_date IS NOT NULL AND i.due_date < v_today
           AND NOT (i.id = ANY (v_invoiced))
         ORDER BY i.due_date, i.id
         LIMIT 200
         FOR UPDATE OF i SKIP LOCKED
      LOOP
        UPDATE public.invoices SET status = 'overdue', updated_at = now()
         WHERE id = v_r.id AND status = 'sent';
        IF FOUND THEN
          IF v_r.assessment_id IS NOT NULL THEN
            INSERT INTO public.timeline_events (assessment_id, type, title, event, user_name)
            VALUES (v_r.assessment_id, 'cron', 'Invoice overdue',
                    'Invoice ' || COALESCE(NULLIF(btrim(v_r.invoice_number), ''), 'for this engagement') || ' is overdue', 'System');
          END IF;
          v_overdue := v_overdue || v_r.id;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ── Meetings: one that has ended is completed ─────────────────────────────
  -- Its date and start time, in the firm's timezone, plus its length. A scoping
  -- call that has happened becomes a client unless one of that name or that
  -- address exists already, as the portal did it; a refusal (1975: no plan
  -- limits clients) leaves the meeting completed and says why.
  IF p_action IN ('due', 'meetings') THEN
    FOR v_r IN
      SELECT m.id, m.meeting_purpose, m.client_name, m.client_email, m.client_org,
             m.meeting_date, m.meeting_time, m.duration_minutes
        FROM public.meetings m
       WHERE m.status IN ('pending', 'confirmed')
         AND m.meeting_date IS NOT NULL
         AND m.meeting_date <= v_today
         AND COALESCE(m.meeting_time, '') ~ '^\s*([01]?[0-9]|2[0-3]):[0-5][0-9]'
       ORDER BY m.meeting_date, m.meeting_time, m.id
       LIMIT 200
       FOR UPDATE OF m SKIP LOCKED
    LOOP
      v_meet_at := v_r.meeting_date
        + make_time(split_part(btrim(v_r.meeting_time), ':', 1)::int,
                    substring(split_part(btrim(v_r.meeting_time), ':', 2) from 1 for 2)::int, 0)
        + make_interval(mins => GREATEST(COALESCE(v_r.duration_minutes, 30), 0));
      CONTINUE WHEN v_meet_at > v_now;
      UPDATE public.meetings SET status = 'completed', updated_at = now()
       WHERE id = v_r.id AND status IN ('pending', 'confirmed');
      CONTINUE WHEN NOT FOUND;
      v_met := v_met + 1;
      v_client_name := COALESCE(NULLIF(btrim(v_r.client_org), ''), NULLIF(btrim(v_r.client_name), ''));
      IF v_r.meeting_purpose = 'scoping' AND v_client_name IS NOT NULL
         AND NOT EXISTS (
           SELECT 1 FROM public.clients c
            WHERE lower(c.name) = lower(v_client_name)
               OR (NULLIF(btrim(v_r.client_email), '') IS NOT NULL
                   AND lower(btrim(c.contact_email)) = lower(btrim(v_r.client_email))))
      THEN
        BEGIN
          INSERT INTO public.clients (name, contact_name, contact_email)
          VALUES (v_client_name, NULLIF(btrim(v_r.client_name), ''), NULLIF(btrim(v_r.client_email), ''));
          v_clients_made := v_clients_made + 1;
        EXCEPTION WHEN OTHERS THEN
          v_skipped := v_skipped || jsonb_build_object('scoping_client', left(SQLERRM, 200));
        END;
      END IF;
    END LOOP;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', i.id, 'invoice_number', i.invoice_number, 'title', i.title,
           'amount', i.amount, 'description', i.description, 'due_date', i.due_date,
           -- 1839: what it comes to, as this database works it out (its own
           -- currency and VAT rate, VAT rounded once), for the email.
           'money', public._invoice_money(i.id),
           'contact_email', NULLIF(btrim(c.contact_email), ''), 'client_name', c.name)
         ORDER BY i.id), '[]'::jsonb)
    INTO v_invoice_rows
    FROM public.invoices i
    LEFT JOIN public.clients c ON c.id = i.client_id
   WHERE i.id = ANY (v_invoiced);

  -- What the emails need, for exactly the rows moved above. The proposal is
  -- read for the engagement's phases when the assessment has none of its own.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', a.id, 'name', a.name, 'type', a.type, 'phases', a.phases,
           'proposal_type', p.type, 'proposal_phases', p.phases,
           'start_date', a.start_date, 'end_date', a.end_date,
           'start_time', to_char(a.start_time, 'HH24:MI'), 'end_time', to_char(a.end_time, 'HH24:MI'),
           'days_until', a.start_date - v_today,
           'contact_email', NULLIF(trim(c.contact_email), ''),
           'lead', CASE WHEN l.id IS NULL THEN NULL ELSE jsonb_build_object(
             'name', l.name, 'email', l.email, 'phone', l.phone,
             'job_title', l.job_title, 'role', l.role) END,
           'moved', CASE WHEN a.id = ANY (v_started) THEN 'started'
                         WHEN a.id = ANY (v_completed) THEN 'completed'
                         ELSE 'reminded' END)
         ORDER BY a.start_date, a.id), '[]'::jsonb)
    INTO v_rows
    FROM public.assessments a
    LEFT JOIN public.clients c ON c.id = a.client_id
    LEFT JOIN public.profiles l ON l.id = a.lead_id
    LEFT JOIN LATERAL (
      SELECT pr.type, pr.phases FROM public.proposals pr
       WHERE pr.id = a.proposal_id OR pr.assessment_id = a.id
       ORDER BY (pr.id = a.proposal_id) DESC NULLS LAST, pr.created_at DESC NULLS LAST
       LIMIT 1) p ON true
   WHERE a.id = ANY (v_started || v_completed || v_reminded);

  SELECT COALESCE(jsonb_agg(x) FILTER (WHERE x->>'moved' = 'completed'), '[]'::jsonb),
         COALESCE(jsonb_agg(x) FILTER (WHERE x->>'moved' = 'reminded'), '[]'::jsonb),
         COALESCE(jsonb_agg(x) FILTER (WHERE x->>'moved' = 'started'), '[]'::jsonb)
    INTO v_completed_rows, v_reminder_rows, v_started_rows
    FROM jsonb_array_elements(v_rows) AS x;

  RETURN jsonb_build_object(
    'action', p_action, 'tz', v_tz, 'today', v_today, 'time', to_char(v_now, 'HH24:MI'),
    'started', v_started_rows, 'completed', v_completed_rows, 'reminders', v_reminder_rows,
    'invoices', v_invoice_rows, 'meetings_completed', v_met, 'clients_created', v_clients_made,
    'overdue', to_jsonb(v_overdue),
    'skipped', v_skipped,
    -- The switches and the look of the emails. Nothing secret: the mailer reads
    -- the sending account itself, behind its own signature.
    'settings', jsonb_build_object(
      'email_enabled', COALESCE(v_s.email_enabled, false),
      'notify_test_started', COALESCE(v_s.notify_test_started, true),
      'notify_test_ended', COALESCE(v_s.notify_test_ended, true),
      'date_format', v_s.date_format, 'currency_code', v_s.currency_code,
      'company_name', v_s.company_name, 'company_email', v_s.company_email,
      'company_phone', v_s.company_phone, 'company_website', v_s.company_website,
      'accent_color', v_s.accent_color,
      'email_signature_enabled', COALESCE(v_s.email_signature_enabled, false),
      'sig_html', v_s.sig_html, 'sig_name', v_s.sig_name, 'sig_title', v_s.sig_title,
      'sig_email', v_s.sig_email, 'sig_phone', v_s.sig_phone,
      'sig_teams', v_s.sig_teams, 'sig_slack', v_s.sig_slack,
      -- 1797: what an invoice email says and how it says to pay. The bank
      -- details go to every client in these emails already; of Stripe, only
      -- whether card payment is set up, which is all the email needs to know.
      'invoices_enabled', COALESCE(v_s.invoices_enabled, false),
      'notify_invoice_sent', COALESCE(v_s.notify_invoice_sent, true),
      'currency_symbol', v_s.currency_symbol, 'vat_rate', v_s.vat_rate,
      'bank_account_name', v_s.bank_account_name, 'bank_name', v_s.bank_name,
      'bank_sort_code', v_s.bank_sort_code, 'bank_account_number', v_s.bank_account_number,
      'bank_iban', v_s.bank_iban, 'bank_bic', v_s.bank_bic,
      'card_payments', COALESCE(v_s.stripe_enabled, false) AND COALESCE(v_s.stripe_publishable_key, '') <> ''));
END;
$autodue$;
REVOKE ALL ON FUNCTION public.rpc_automation_due(text, text, jsonb) FROM PUBLIC, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_automation_due(text, text, jsonb) TO anon, service_role;

-- GOOGLE REVIEWS, READ BACK INTO FEEDBACK (1797).
--
-- "Sync Google Reviews" has never written a review. The route inserted into
-- `feedback` with the publishable key, which is anon, and this table's
-- policies are for signed-in users; asked as the person instead, the insert
-- policy wants a client the person can see, and a Google review has none. It
-- also named a column this table does not have (communication_rating), so the
-- insert failed even where it was allowed.
--
-- 1843: this database reads the reviews from Google itself (TEAMS LINKS AND
-- GOOGLE REVIEWS FROM THE FIRM'S OWN SIDE, _places_details_answer), so the
-- import is its own and no longer anybody's to call: Pental's route, which
-- read them with the firm's key and called rpc_feedback_import_google as
-- the person, is retired with it. This writes the ones not already here,
-- and nothing else. At most fifty a call, which is more than Google hands
-- back at once.
CREATE OR REPLACE FUNCTION public._feedback_import_google(p_reviews jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $gimport$
DECLARE
  v_r jsonb;
  v_id text;
  v_rating int;
  v_at timestamptz;
  v_n int := 0;
BEGIN
  IF jsonb_typeof(p_reviews) IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('error', 'No reviews were sent');
  END IF;
  FOR v_r IN SELECT x FROM jsonb_array_elements(p_reviews) WITH ORDINALITY AS t(x, n) WHERE n <= 50 LOOP
    CONTINUE WHEN jsonb_typeof(v_r) IS DISTINCT FROM 'object';
    v_id := left(NULLIF(btrim(v_r->>'google_review_id'), ''), 300);
    CONTINUE WHEN v_id IS NULL OR left(v_id, 2) <> 'g_';
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.feedback f WHERE f.google_review_id = v_id);
    v_rating := CASE WHEN COALESCE(v_r->>'rating', '') ~ '^[0-9]{1,2}$'
                     THEN LEAST(5, GREATEST(0, (v_r->>'rating')::int)) ELSE 0 END;
    -- 1843: the same review, by the same named author with the same words and
    -- rating, is the same review however Google's API named its time (Google
    -- keeps one review a person for a place). A review with no author's name
    -- or no words is known by its name alone: two people's bare five stars are
    -- two reviews.
    CONTINUE WHEN btrim(COALESCE(v_r->>'author_name', '')) <> '' AND btrim(COALESCE(v_r->>'text', '')) <> ''
      AND EXISTS (SELECT 1 FROM public.feedback f WHERE f.google_review_id IS NOT NULL
      AND f.google_review_data ->> 'author' = left(COALESCE(v_r->>'author_name', ''), 200)
      AND f.testimonial = left(COALESCE(v_r->>'text', ''), 5000) AND f.rating = v_rating);
    v_at := CASE WHEN COALESCE(v_r->>'time', '') ~ '^[0-9]{1,12}$'
                 THEN to_timestamp((v_r->>'time')::bigint) ELSE now() END;
    INSERT INTO public.feedback (rating, testimonial, submitted_by_name, google_review_id, google_review_data, created_at)
    VALUES (v_rating,
            left(COALESCE(v_r->>'text', ''), 5000),
            left(COALESCE(NULLIF(btrim(v_r->>'author_name'), ''), 'Google Reviewer'), 200),
            v_id,
            jsonb_build_object(
              'author', left(COALESCE(v_r->>'author_name', ''), 200),
              'author_url', left(COALESCE(v_r->>'author_url', ''), 500),
              'profile_photo', left(COALESCE(v_r->>'profile_photo_url', ''), 500),
              'rating', v_rating,
              'relative_time', left(COALESCE(v_r->>'relative_time_description', ''), 100),
              'time', v_r->'time'),
            LEAST(v_at, now()));
    v_n := v_n + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'synced', v_n);
END;
$gimport$;
REVOKE ALL ON FUNCTION public._feedback_import_google(jsonb) FROM PUBLIC, anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- THE CONTACT FORM (1739). [stated] Arian: "continue" (to fixing /api/contact).
--
-- A firm's website posts its enquiries to the portal's /api/contact, and each
-- one lands here as a `contact_form` row: the Contacts page reads them, and
-- `pending` is unread. The route holds only the publishable key, which may not
-- add a row, so it calls this, behind Pental's signature or the provisioning
-- secret; a browser cannot call it at all. The form is public, and the route's
-- limit per address stands aside when the master database does not answer, so
-- this keeps a ceiling of its own: 100 in an hour.
CREATE OR REPLACE FUNCTION public.rpc_submit_contact_form(
  p_name text, p_email text, p_organisation text DEFAULT NULL, p_service text DEFAULT NULL,
  p_message text DEFAULT NULL, p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $contactform$
DECLARE
  v_mode text;
  v_email text;
  v_name text;
  v_org text;
  v_service text;
  v_message text;
  v_id uuid;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_submit_contact_form');
  IF v_mode IS NULL OR v_mode NOT IN ('signed', 'provision_secret') THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  v_email := lower(btrim(COALESCE(p_email, '')));
  IF v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(v_email) > 254 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_email');
  END IF;
  IF (SELECT count(*) FROM public.email_notifications
       WHERE notification_type = 'contact_form' AND created_at > now() - interval '1 hour') >= 100 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'busy');
  END IF;
  v_name := left(btrim(COALESCE(p_name, '')), 200);
  v_org := left(btrim(COALESCE(p_organisation, '')), 200);
  v_service := left(btrim(COALESCE(p_service, '')), 200);
  v_message := left(btrim(COALESCE(p_message, '')), 5000);
  -- The lines the Contacts page reads back (_parseContactBody).
  INSERT INTO public.email_notifications (to_email, from_name, from_email, subject, body, notification_type, status)
  VALUES (v_email, v_name, v_email, 'Contact Form: ' || COALESCE(NULLIF(v_name, ''), v_email),
          concat_ws(E'\n',
            CASE WHEN v_name <> '' THEN 'Name: ' || v_name END,
            'Email: ' || v_email,
            CASE WHEN v_org <> '' THEN 'Organisation: ' || v_org END,
            CASE WHEN v_service <> '' THEN 'Service: ' || v_service END,
            CASE WHEN v_message <> '' THEN 'Message: ' || v_message END),
          'contact_form', 'pending')
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$contactform$;
REVOKE ALL ON FUNCTION public.rpc_submit_contact_form(text, text, text, text, text, text, jsonb) FROM PUBLIC, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_submit_contact_form(text, text, text, text, text, text, jsonb) TO anon, service_role;

-- 1836: WHO SENDS A ROW. NULL is Pental's servers (the outbox drain below,
-- and the log it writes); 'local' is this database's own side, which the
-- portal hands the email it writes to (rpc_mail_submit, further down) and
-- which the drain leaves alone.
ALTER TABLE public.email_notifications ADD COLUMN IF NOT EXISTS sent_via text;
-- And the version of it Pental's servers may be given if this side cannot
-- send it after all (a finding's title and score and a comment's words left
-- out; NULL where the email itself may be): the row is then handed to the
-- drain with that version in place of its own, so no email is lost.
ALTER TABLE public.email_notifications ADD COLUMN IF NOT EXISTS fallback_subject text;
ALTER TABLE public.email_notifications ADD COLUMN IF NOT EXISTS fallback_body text;
-- 1844: AN INVITATION'S CALENDAR FILE, ATTACHED BY WHATEVER SENDS IT. The
-- portal wrote it into the body as an HTML comment for a sender to find, and
-- no sender ever looked: every invitation went out with no calendar file. It
-- is the email's own now, and every sender attaches it (_mail_request here,
-- the gateway's mail worker, Pental's drain). Only a calendar is let in: an
-- invitation, its update or its cancellation (METHOD REQUEST or CANCEL), as
-- RFC 5545 writes one, 64 KB at most (in bytes, as every sender counts it).
ALTER TABLE public.email_notifications ADD COLUMN IF NOT EXISTS calendar text;
-- (Written out in the check, not called: a check's function needs EXECUTE
-- from whoever writes the row, and the portal's people may write one.)
DO $enotif_calendar$ BEGIN
  ALTER TABLE public.email_notifications DROP CONSTRAINT IF EXISTS email_notifications_calendar;
  ALTER TABLE public.email_notifications ADD CONSTRAINT email_notifications_calendar CHECK (calendar IS NULL OR (
    octet_length(calendar) <= 65536 AND calendar ~ '^BEGIN:VCALENDAR\r\n' AND calendar ~ '\r\nEND:VCALENDAR(\r\n)?$'
    AND calendar ~ '\r\nMETHOD:(REQUEST|CANCEL)\r\n' AND position(E'\r\nBEGIN:VEVENT\r\n' IN calendar) > 0)) NOT VALID;
END $enotif_calendar$;
-- The same test, for rpc_mail_submit to answer with words.
CREATE OR REPLACE FUNCTION public._mail_calendar_ok(p text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $mlcalok$
  SELECT p IS NULL OR (octet_length(p) <= 65536 AND p ~ '^BEGIN:VCALENDAR\r\n' AND p ~ '\r\nEND:VCALENDAR(\r\n)?$'
    AND p ~ '\r\nMETHOD:(REQUEST|CANCEL)\r\n' AND position(E'\r\nBEGIN:VEVENT\r\n' IN p) > 0);
$mlcalok$;
REVOKE ALL ON FUNCTION public._mail_calendar_ok(text) FROM PUBLIC, anon, authenticated;
-- Its METHOD, for the content type it is sent with.
CREATE OR REPLACE FUNCTION public._mail_calendar_method(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $mlcalm$
  SELECT CASE WHEN p ~ '\r\nMETHOD:CANCEL\r\n' THEN 'CANCEL' ELSE 'REQUEST' END;
$mlcalm$;
REVOKE ALL ON FUNCTION public._mail_calendar_method(text) FROM PUBLIC, anon, authenticated;
-- Base64 in lines of 76, each ended CRLF, as a message's part is written.
-- (PostgreSQL ends a last line that is whole, a multiple of 57 bytes, with
-- a line break of its own, which nodemailer does not: it is taken off, so the
-- message is byte for byte the gateway's and Pental's for every length.)
CREATE OR REPLACE FUNCTION public._mail_b64_lines(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $mlb64$
  SELECT replace(rtrim(encode(convert_to(COALESCE(p, ''), 'UTF8'), 'base64'), E'\n'), E'\n', E'\r\n') || E'\r\n';
$mlb64$;
REVOKE ALL ON FUNCTION public._mail_b64_lines(text) FROM PUBLIC, anon, authenticated;
CREATE INDEX IF NOT EXISTS email_notifications_local_pending_idx ON public.email_notifications (created_at)
  WHERE sent_via = 'local' AND status = 'pending';
-- 1841: and what waits for the drain, which the firm's own side takes over
-- once it sends (_mail_adopt), asked every ten seconds.
CREATE INDEX IF NOT EXISTS email_notifications_drain_idx ON public.email_notifications (created_at)
  WHERE sent_via IS NULL AND status = 'pending';
-- Who sends a row, and its version for Pental, are this database's to set
-- (rpc_mail_submit and the functions after it), not a person's through the
-- API: a row written or revived as the firm's own would be sent from here
-- without rpc_mail_submit's checks. A row the firm's side sends is not put
-- back to waiting through the API either.
CREATE OR REPLACE FUNCTION public._email_notifications_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_catalog, pg_temp AS $engd$
BEGIN
  IF current_user IN ('anon', 'authenticated') THEN
    IF TG_OP = 'INSERT' AND (NEW.sent_via IS NOT NULL OR NEW.fallback_subject IS NOT NULL OR NEW.fallback_body IS NOT NULL) THEN
      RAISE EXCEPTION 'Who sends an email is set by this database alone' USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.sent_via IS DISTINCT FROM OLD.sent_via OR NEW.fallback_subject IS DISTINCT FROM OLD.fallback_subject
                             OR NEW.fallback_body IS DISTINCT FROM OLD.fallback_body
                             OR (OLD.sent_via = 'local' AND NEW.status = 'pending' AND OLD.status IS DISTINCT FROM 'pending')) THEN
      RAISE EXCEPTION 'Who sends an email is set by this database alone' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $engd$;
REVOKE ALL ON FUNCTION public._email_notifications_guard() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS email_notifications_guard ON public.email_notifications;
CREATE TRIGGER email_notifications_guard BEFORE INSERT OR UPDATE ON public.email_notifications
  FOR EACH ROW EXECUTE FUNCTION public._email_notifications_guard();

-- ═══════════════════════════════════════════════════════════════════════════
-- THE OUTBOX: CUTOFF, CLAIM AND RESULT (1502)
--
-- Read the long note beside `settings.mail_outbox_started_at` before changing
-- anything here.

-- WHICH TYPES ARE OUTBOUND MAIL AT ALL. An ALLOW list, not a block list, so a
-- notification type added later is silently NOT sent rather than silently sent.
--
-- Deliberately absent, each for its own reason:
--   contact_form           inbound. The contact inbox is a view over this table
--                          and `pending` is its unread state. Sending these
--                          would mail every enquiry to whoever is in to_email
--                          and mark the firm's whole inbox as read.
--   login_code             a time-limited secret that expired long ago, and
--                          auth-code.js has its own transport anyway. Posting a
--                          stale sign-in code is the worst thing in this table.
--   smtp_test              a connectivity test. Meaningless once the moment has
--                          passed, and confusing to receive.
--
-- 1797: and the portal's own notices, which were never on it. A notice the
-- sender could not send at the time (no mailbox and no Pental sender, or a
-- refusal the portal then queued itself) was written as pending and left
-- there. So was every credentials notice the database writes for a tester
-- (1560), and the schedule's own "Testing has started" since 1796 named it
-- test_started rather than assessment_start. Still an allow list: each of these
-- is a notice somebody would want late rather than never, inside the window
-- below.
CREATE OR REPLACE FUNCTION public._mail_outbox_sendable(p_type text)
  RETURNS boolean LANGUAGE sql IMMUTABLE
  SET search_path = public, pg_catalog, pg_temp AS $obst$
  SELECT COALESCE(p_type, 'general') = ANY (ARRAY[
    'general','welcome','assessment_start','credential_reminder',
    'scan_target_pending','scan_finished','meeting_invite',
    'security_event','account_email_changed',
    -- 1797
    'test_started','test_ended','critical_finding','report_delivered',
    'tester_assigned','comment_reply','comment_new',
    'proposal_signature','invoice_sent','invoice_reminder','invoice_paid',
    'credentials_submitted','credentials_elsewhere',
    -- 1844: a confirmed meeting moved or cancelled, to everyone invited
    'meeting_update','meeting_cancel'
  ]);
$obst$;

-- HOW STALE IS TOO STALE. A reminder about an assessment that started last
-- month is noise; a security alert that arrives three weeks late is alarming
-- about something long settled, so those get a much shorter window. Anything
-- past its window is cancelled with the reason on the row rather than sent.
CREATE OR REPLACE FUNCTION public._mail_outbox_max_age(p_type text)
  RETURNS interval LANGUAGE sql IMMUTABLE
  SET search_path = public, pg_catalog, pg_temp AS $obma$
  SELECT CASE WHEN COALESCE(p_type, 'general') IN ('security_event','account_email_changed')
              THEN interval '24 hours'
              ELSE interval '7 days'
         END;
$obma$;

-- 1797: THE DRAIN COULD NEVER REACH THESE. The three functions below were
-- granted to service_role alone, and Pental holds no firm's service-role key:
-- the drain called them with the publishable one, which is anon, and every
-- pass was refused. Nothing queued has ever been sent from a firm's own
-- database, meeting invitations included. Each now takes Pental's signature
-- and nothing else (not the provisioning secret, not a signed-in user), and is
-- executable by anon so the signed call can arrive at all. The old signatures
-- are dropped, or PostgREST would find two and choose neither.
DROP FUNCTION IF EXISTS public.rpc_mail_outbox_claim(integer);
DROP FUNCTION IF EXISTS public.rpc_mail_outbox_result(uuid, boolean, text);
DROP FUNCTION IF EXISTS public.rpc_mail_sender_ready();

-- CLAIM. Incrementing `attempts` IS the claim: there is no 'sending' status and
-- adding one would mean changing a CHECK constraint every tenant has. A pass
-- that dies mid-send leaves the row at attempts+1 and still pending, so it is
-- retried but cannot spin, and it is visible as attempts > 0.
--
-- SKIP LOCKED so two passes overlapping take different rows rather than both
-- sending the same one.
CREATE OR REPLACE FUNCTION public.rpc_mail_outbox_claim(
  p_limit integer DEFAULT 25,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $obclaim$
DECLARE
  v_mode text;
  v_since timestamptz;
  v_on boolean;
  v_rows jsonb := '[]'::jsonb;
  v_cancelled integer := 0;
  v_n integer;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_mail_outbox_claim', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Not authorised'; END IF;
  -- 1841: NOTHING, ONCE THIS PORTAL SENDS ITS OWN EMAIL (_mail_locked): its
  -- own side sends what waits here itself (_mail_adopt), and keeps the window
  -- below as this drain kept it.
  IF public._mail_locked() THEN
    RETURN jsonb_build_object('messages', '[]'::jsonb, 'locked', true);
  END IF;

  SELECT COALESCE(mail_outbox_enabled, true), mail_outbox_started_at
    INTO v_on, v_since
    FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;

  IF NOT COALESCE(v_on, true) THEN
    RETURN jsonb_build_object('messages', '[]'::jsonb, 'off', true);
  END IF;
  -- NO CUTOFF MEANS NO SENDING. A database that has not had the stamping pass
  -- applied has an unbounded backlog, and the safe answer to "how far back may
  -- I go" being unknown is "nowhere".
  IF v_since IS NULL THEN
    RETURN jsonb_build_object('messages', '[]'::jsonb, 'no_cutoff', true);
  END IF;

  -- Past its window: cancelled with the reason, never sent.
  UPDATE public.email_notifications e
     SET status = 'cancelled',
         error_message = left(COALESCE(e.error_message || ' ', '')
           || '[outbox] too old to send (' || e.notification_type || ')', 500)
   WHERE e.status = 'pending'
     AND e.created_at >= v_since
     AND public._mail_outbox_sendable(e.notification_type)
     AND e.sent_via IS NULL
     AND e.created_at < now() - public._mail_outbox_max_age(e.notification_type);
  GET DIAGNOSTICS v_cancelled = ROW_COUNT;

  -- Tried and tried: three goes, then it is a failure somebody can look at.
  UPDATE public.email_notifications e
     SET status = 'failed'
   WHERE e.status = 'pending'
     AND e.created_at >= v_since
     AND public._mail_outbox_sendable(e.notification_type)
     AND e.sent_via IS NULL
     AND COALESCE(e.attempts, 0) >= 3;

  WITH picked AS (
    SELECT e.id
      FROM public.email_notifications e
     WHERE e.status = 'pending'
       AND e.created_at >= v_since
       AND public._mail_outbox_sendable(e.notification_type)
       AND e.sent_via IS NULL
       AND COALESCE(e.attempts, 0) < 3
       AND e.created_at >= now() - public._mail_outbox_max_age(e.notification_type)
     ORDER BY e.created_at ASC
     LIMIT GREATEST(1, LEAST(100, COALESCE(p_limit, 25)))
     FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE public.email_notifications e
       SET attempts = COALESCE(e.attempts, 0) + 1
      FROM picked
     WHERE e.id = picked.id
    RETURNING e.id, e.to_email, e.subject, e.body, e.notification_type,
              e.related_id, e.from_name, e.attempts, e.calendar
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(c)), '[]'::jsonb) INTO v_rows FROM claimed c;

  SELECT jsonb_array_length(v_rows) INTO v_n;
  RETURN jsonb_build_object('messages', v_rows, 'claimed', v_n, 'cancelled_stale', v_cancelled);
END;
$obclaim$;

-- RESULT. Separate from the claim so a send that never came back leaves the row
-- retryable rather than marked sent.
CREATE OR REPLACE FUNCTION public.rpc_mail_outbox_result(
  p_id uuid,
  p_ok boolean,
  p_error text DEFAULT NULL,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
)
  RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $obres$
DECLARE v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_mail_outbox_result', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF p_ok THEN
    UPDATE public.email_notifications
       SET status = 'sent', sent_at = now(), error_message = NULL
     WHERE id = p_id AND status = 'pending' AND sent_via IS NULL;
  ELSE
    UPDATE public.email_notifications
       SET error_message = left(COALESCE(p_error, 'send failed'), 500),
           status = CASE WHEN COALESCE(attempts, 0) >= 3 THEN 'failed' ELSE status END
     WHERE id = p_id AND status = 'pending' AND sent_via IS NULL;
  END IF;
  RETURN FOUND;
END;
$obres$;

-- CAN THIS TENANT SEND AT ALL? The drain asks BEFORE it claims anything,
-- because `sendTenantEmail` answers a missing sender by writing ANOTHER pending
-- row. Draining into a deployment with no sender would grow the table on every
-- pass, forever, which is the one failure mode worse than not sending.
CREATE OR REPLACE FUNCTION public.rpc_mail_sender_ready(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
)
  RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $obrdy$
DECLARE v_s record; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_mail_sender_ready', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Not authorised'; END IF;
  -- 1841: Pental's servers send none of this portal's email once its own side
  -- does (_mail_locked).
  IF public._mail_locked() THEN RETURN false; END IF;
  SELECT * INTO v_s FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;
  IF v_s.id IS NULL THEN RETURN false; END IF;
  IF COALESCE(v_s.email_enabled, true) IS FALSE THEN RETURN false; END IF;
  -- A connected mailbox counts, exactly as it does in _mailer.js (1095).
  IF COALESCE(v_s.smtp_oauth_provider, '') <> ''
     AND (COALESCE(v_s.smtp_oauth_refresh, '') <> '' OR v_s.smtp_oauth_refresh_enc IS NOT NULL)
  THEN RETURN true; END IF;
  RETURN COALESCE(v_s.smtp_host, '') <> ''
     AND COALESCE(v_s.smtp_user, '') <> ''
     AND (COALESCE(v_s.smtp_pass, '') <> '' OR v_s.smtp_pass_enc IS NOT NULL);
END;
$obrdy$;

REVOKE ALL ON FUNCTION public.rpc_mail_outbox_claim(integer, text, jsonb) FROM PUBLIC, authenticated;
REVOKE ALL ON FUNCTION public.rpc_mail_outbox_result(uuid, boolean, text, text, jsonb) FROM PUBLIC, authenticated;
REVOKE ALL ON FUNCTION public.rpc_mail_sender_ready(text, jsonb) FROM PUBLIC, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_mail_outbox_claim(integer, text, jsonb) TO anon, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_mail_outbox_result(uuid, boolean, text, text, jsonb) TO anon, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_mail_sender_ready(text, jsonb) TO anon, service_role;

-- THE EMAIL LOG, WRITTEN BY THE PORTAL'S SENDER (1797).
--
-- [stated] Arian: "yes the two others fix them all" (the email log among them).
--
-- Every email the portal's server sends was to be recorded here, sent or
-- failed, and the no-sender case queued as pending for the drain above. Each
-- of those was a plain insert with the publishable key, which is anon, and
-- this table's policies are for signed-in users alone: every one was refused
-- without a word. The Email Log showed nothing the server had sent, and a
-- notice that could not be sent was not queued, so nothing retried it.
--
-- Pental's signature and nothing else. A sign-in code is never kept, whoever
-- writes the row: the log is readable by the firm's managers, and a code in it
-- is a way into somebody else's account.
CREATE OR REPLACE FUNCTION public.rpc_mail_log(
  p_to text,
  p_subject text,
  p_body text,
  p_type text DEFAULT 'general',
  p_related_id uuid DEFAULT NULL,
  p_status text DEFAULT 'sent',
  p_from_name text DEFAULT NULL,
  p_from_email text DEFAULT NULL,
  p_error text DEFAULT NULL,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp AS $maillog$
DECLARE
  v_mode text;
  v_id uuid;
  v_type text := COALESCE(NULLIF(btrim(p_type), ''), 'general');
  v_status text := lower(COALESCE(NULLIF(btrim(p_status), ''), 'sent'));
  v_body text := COALESCE(p_body, '');
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_mail_log', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF v_status NOT IN ('sent', 'failed', 'pending') THEN RAISE EXCEPTION 'Unknown status'; END IF;
  IF COALESCE(btrim(p_to), '') = '' THEN RAISE EXCEPTION 'No recipient'; END IF;
  IF v_type = 'login_code' THEN
    v_body := '<p>A sign-in email. Its code is not kept.</p>';
  END IF;
  -- Pending means the drain will send it. A kind of email the outbox never
  -- sends late (a sign-in code, a mailbox test) is recorded as not sent, and
  -- why, rather than left pending for ever.
  IF v_status = 'pending' AND NOT public._mail_outbox_sendable(v_type) THEN
    v_status := 'failed';
    p_error := COALESCE(NULLIF(p_error, '') || ' ', '') || '(this kind of email is not sent later)';
  END IF;
  INSERT INTO public.email_notifications
    (to_email, subject, body, notification_type, related_id, status,
     from_name, from_email, error_message, attempts, sent_at)
  VALUES
    (btrim(p_to), COALESCE(p_subject, ''), v_body, v_type, p_related_id, v_status,
     NULLIF(p_from_name, ''), NULLIF(p_from_email, ''), left(NULLIF(p_error, ''), 500),
     CASE WHEN v_status = 'pending' THEN 0 ELSE 1 END,
     CASE WHEN v_status = 'sent' THEN now() END)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$maillog$;
REVOKE ALL ON FUNCTION public.rpc_mail_log(text, text, text, text, uuid, text, text, text, text, text, jsonb) FROM PUBLIC, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_mail_log(text, text, text, text, uuid, text, text, text, text, text, jsonb) TO anon, service_role;

-- STAMP THE CUTOFF AND CANCEL THE BACKLOG, EXACTLY ONCE.
--
-- Idempotent by construction: the stamp is only written where it is NULL, and
-- the cancel only touches rows older than it. Re-running this file on a tenant
-- that already has an outbox cancels nothing.
--
-- `contact_form` IS EXCLUDED FROM THE CANCEL as well as from the send. Those
-- rows are the firm's unread contact enquiries; cancelling them would empty the
-- inbox just as thoroughly as sending them would.
DO $outbox_cutoff$
DECLARE v_since timestamptz; v_n integer;
BEGIN
  UPDATE public.settings SET mail_outbox_started_at = now() WHERE mail_outbox_started_at IS NULL;
  SELECT mail_outbox_started_at INTO v_since
    FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;
  IF v_since IS NULL THEN RETURN; END IF;
  UPDATE public.email_notifications e
     SET status = 'cancelled',
         error_message = left(COALESCE(e.error_message || ' ', '')
           || '[outbox] never sent: queued before the outbox existed', 500)
   WHERE e.status = 'pending'
     AND COALESCE(e.notification_type, '') <> 'contact_form'
     AND e.created_at < v_since;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    RAISE NOTICE 'outbox: % backlog row(s) cancelled; nothing before % will ever be sent', v_n, v_since;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'outbox cutoff could not be stamped: %', SQLERRM;
END $outbox_cutoff$;

-- 1797: AND ONCE MORE, FOR THE DRAIN THAT NOW WORKS. The cutoff above was
-- stamped when the outbox was added, and the drain could not reach a firm's
-- database from that day to this, so everything queued in between is exactly
-- the backlog the cutoff exists to stop: meeting invitations for meetings that
-- have happened, notices about things long settled. Coming from an earlier
-- version, the cutoff moves to now and those rows are cancelled with the
-- reason on them. A new database, or one already at 2025092802, is untouched.
-- contact_form rows are the contact inbox and are left alone, as above.
DO $outbox_cutoff_again$
DECLARE v_from bigint := 0; v_since timestamptz; v_n integer;
BEGIN
  IF to_regclass('public._pental_schema_version') IS NOT NULL THEN
    SELECT COALESCE((SELECT version FROM public._pental_schema_version WHERE id = 1), 0) INTO v_from;
  END IF;
  IF v_from = 0 OR v_from >= 2025092802 THEN RETURN; END IF;
  -- Forward only, and named rows: Supabase refuses an UPDATE with no WHERE.
  UPDATE public.settings SET mail_outbox_started_at = now()
   WHERE mail_outbox_started_at IS NULL OR mail_outbox_started_at < now();
  SELECT mail_outbox_started_at INTO v_since
    FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;
  IF v_since IS NULL THEN RETURN; END IF;
  UPDATE public.email_notifications e
     SET status = 'cancelled',
         error_message = left(COALESCE(e.error_message || ' ', '')
           || '[outbox] never sent: queued before the outbox could reach this database', 500)
   WHERE e.status = 'pending'
     AND COALESCE(e.notification_type, '') <> 'contact_form'
     AND e.created_at < v_since;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    RAISE NOTICE 'outbox: % queued row(s) from before this update cancelled; nothing before % will be sent', v_n, v_since;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'outbox cutoff could not be moved: %', SQLERRM;
END $outbox_cutoff_again$;

-- service_role only - cron runs with the BYO service key
REVOKE EXECUTE ON FUNCTION public.rpc_cron_get_pending(text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.rpc_cron_process(uuid, text, text, text, text, uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.rpc_cron_queue_email(text, text, text, text, uuid, text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_cron_get_pending(text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.rpc_cron_process(uuid, text, text, text, text, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.rpc_cron_queue_email(text, text, text, text, uuid, text, text, uuid) TO service_role;

-- Sign proposal needs anon for unsigned proposal signing via token
DO $sp$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid WHERE n.nspname='public' AND p.proname='rpc_sign_proposal') THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_sign_proposal(uuid, text, text, date, date, text, text, uuid, boolean, text, text, text, text, text) TO anon';
  END IF;
END $sp$;

-- Revoke dangerous functions from anon/public
DO $rv$ DECLARE fn text; BEGIN
  FOR fn IN SELECT p.oid::regprocedure::text FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid WHERE n.nspname='public' AND p.proname IN ('_validate_provision_secret','_validate_provision_secret_or_bootstrap','_validate_cron_secret','_get_cred_key') LOOP
    BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || fn || ' FROM PUBLIC'; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || fn || ' FROM authenticated'; EXCEPTION WHEN OTHERS THEN NULL; END;
    BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || fn || ' FROM anon'; EXCEPTION WHEN OTHERS THEN NULL; END;
  END LOOP;
END $rv$;

-- ═══════════════════════════════════════════════════════════════════════════
-- SCANNING IS PUBLISHED FOR REALTIME (829)
--
-- [stated] Arian: "some realtime features dont work sometimes, make sure
-- everything is realtime."
--
-- No scan table was in the publication, so nothing about scanning ever arrived
-- over the socket. What looked like realtime was a 30-second poller that only
-- ran while the page ALREADY knew a run was live - so a scan starting elsewhere
-- never appeared, and an asset approved by a colleague sat there until somebody
-- reloaded. That is why it worked "sometimes".
--
-- SEPARATE FROM THE PUBLICATION BLOCK AT THE TOP, because that one runs before
-- these tables are created. Adding them there published exactly one of five and
-- silently skipped the rest - the `EXCEPTION WHEN duplicate_object` swallows a
-- missing table just as quietly as a duplicate.
--
-- `scan_findings` is NOT here: there is no such table. Findings from a scan live
-- in `findings`, which is already published.
DO $rtscan$ DECLARE t text; BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    CREATE PUBLICATION supabase_realtime;
  END IF;
  FOR t IN SELECT unnest(ARRAY['scan_runs','client_scan_targets','scan_cadences',
                               'scan_providers','scan_schedules']) LOOP
    -- Only if it actually exists, and say so when it does not rather than
    -- swallowing it the way the block above does.
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = t) THEN
      BEGIN
        EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE public.' || quote_ident(t);
      EXCEPTION WHEN duplicate_object THEN NULL; END;
    ELSE
      RAISE NOTICE 'realtime: no table %, not published', t;
    END IF;
  END LOOP;
END $rtscan$;

NOTIFY pgrst, 'reload schema';
NOTIFY pgrst, 'reload config';

-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-mfa-enforcement.sql ━━
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- PENTAL BYO, SERVER-SIDE MFA ENFORCEMENT (OPTION A)
-- ═══════════════════════════════════════════════════════════════════════════
-- Run on each Enterprise BYO Supabase project AFTER byo-database.sql.
-- Safe to re-run: every statement is idempotent.
--
-- WHAT THIS DOES
--   Closes the bridge-password backdoor: an attacker holding the provision
--   secret can still mint a JWT via rpc_set_bridge_password, but that JWT no
--   longer grants read access to sensitive tables unless the holder has
--   independently passed a TOTP check within the configured window. MFA stops
--   being a UI-only gate and becomes a database-enforced authorisation factor.
--
-- HOW IT WORKS
--   1. rpc_verify_totp and rpc_save_totp_secret stamp auth.users.raw_app_meta_data
--      with mfa_verified_at = now() (unix seconds). Supabase re-reads
--      app_metadata on the next session refresh; the portal forces a refresh
--      right after TOTP success so the claim lands immediately.
--   2. A helper public.mfa_is_fresh() reads the JWT's app_metadata.mfa_verified_at
--      claim and returns true iff it's inside the tenant's configured
--      session_timeout_minutes (default 480).
--   3. Each sensitive RLS policy gains an AND clause that calls mfa_is_fresh().
--      Bootstrap-critical tables (profiles SELECT for the caller's own row,
--      settings SELECT) stay open so the portal can render the MFA prompt.
--   4. Clearing totp_secret (MFA reset) also clears mfa_verified_at so in-flight
--      tokens immediately stop working.
--
-- LIFECYCLE SAFETY
--   Fresh BYO setup: rpc_save_totp_secret stamps the claim implicitly; first
--     login proceeds without a re-prompt.
--   Existing BYO with MFA already set up: users see one MFA re-prompt on their
--     next session (because their current JWT has no mfa_verified_at claim);
--     after that, every login works as before.
--   Master → BYO upgrade migration: totp_secret is copied with profiles; users
--     re-login on the new DB and their first TOTP verify stamps the claim.
--   Admin invites a user: new user's first login lands on MFA setup →
--     rpc_save_totp_secret stamps the claim → full access.
--   Cron/webhook/provisioning paths: these call SECURITY DEFINER RPCs that
--     bypass RLS, so none of this affects them.
-- ═══════════════════════════════════════════════════════════════════════════

-- ────────────────────────────────────────────────────────────────
-- 1841: WHICH SESSIONS PASSED THE SECOND FACTOR (_mfa_fresh)
-- ────────────────────────────────────────────────────────────────
-- The stamp below is the PERSON's (auth.users), and every token GoTrue or the
-- gateway issues carries it. So a second factor passed on one device made
-- every session of that person fresh, a session signed in elsewhere with the
-- password alone included. A session that passes is now written down here by
-- its id (the token's session_id), and once a person has one, only a session
-- written here is fresh. A person with none (a second factor passed before
-- 1841, by a session the backfill below could not place) is read from the
-- stamp, as before, until they next pass it.
CREATE TABLE IF NOT EXISTS public._mfa_fresh (
  session_id   uuid PRIMARY KEY,
  auth_user_id uuid NOT NULL,
  verified_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS _mfa_fresh_user_idx ON public._mfa_fresh (auth_user_id);
-- 1911: and when its code was entered. verified_at is the moment the session
-- is fresh from, which a session in use moves on (rpc_mfa_keep_alive, below);
-- entered_at stays where the code was entered, for the day's limit. A row from
-- before 1911 has none and is read from verified_at, the same moment until now.
ALTER TABLE public._mfa_fresh ADD COLUMN IF NOT EXISTS entered_at timestamptz;
ALTER TABLE public._mfa_fresh ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._mfa_fresh FROM PUBLIC, anon, authenticated;
-- The sessions a person already had when they last passed are taken as the
-- ones that passed (one of them did); a session begun after that did not, and
-- is asked. Once, for a person with none written down yet.
DO $mfafill$
BEGIN
  INSERT INTO public._mfa_fresh (session_id, auth_user_id, verified_at)
  SELECT s.id, s.user_id, to_timestamp((u.raw_app_meta_data ->> 'mfa_verified_at')::bigint)
    FROM auth.sessions s JOIN auth.users u ON u.id = s.user_id
   WHERE COALESCE(u.raw_app_meta_data ->> 'mfa_verified_at', '') ~ '^[0-9]{1,12}$'
     AND to_timestamp((u.raw_app_meta_data ->> 'mfa_verified_at')::bigint) > now() - interval '31 days'
     AND s.created_at <= to_timestamp((u.raw_app_meta_data ->> 'mfa_verified_at')::bigint) + interval '5 seconds'
     AND NOT EXISTS (SELECT 1 FROM public._mfa_fresh f WHERE f.auth_user_id = s.user_id)
  ON CONFLICT (session_id) DO NOTHING;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE '_mfa_fresh: sessions not read (%), each is asked for its second factor', SQLERRM;
END $mfafill$;

-- ────────────────────────────────────────────────────────────────
-- mfa_is_fresh(), the RLS helper every sensitive policy will call
-- ────────────────────────────────────────────────────────────────
-- Reads two sources for the MFA timestamp:
--   1. auth.jwt() -> 'app_metadata' ->> 'mfa_verified_at' (fast path, set by
--      GoTrue at token issue time from auth.users.raw_app_meta_data)
--   2. auth.users.raw_app_meta_data ->> 'mfa_verified_at' (fallback for the
--      short window between stamp and next token refresh)
-- Returns true iff the freshest of those is within the configured window.
-- Falls back to 480 minutes if settings row is unreachable (conservative).
CREATE OR REPLACE FUNCTION public.mfa_is_fresh() RETURNS boolean AS $$
DECLARE
  v_window_min int;
  v_claim_ts bigint;
  v_db_ts bigint;
  v_user_id uuid;
  v_freshest bigint;
  v_sid text;
  v_at timestamptz;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RETURN false; END IF;

  -- Window comes from settings. We cap at 43200 (30 days) and floor at 5 min.
  BEGIN
    SELECT GREATEST(5, LEAST(43200, COALESCE(session_timeout_minutes, 480)))
      INTO v_window_min FROM public.settings LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_window_min := 480; END;
  IF v_window_min IS NULL THEN v_window_min := 480; END IF;

  -- 1841: this session, once the person has passed in a session written down
  -- (_mfa_fresh). A session that was ended (signed out, or signed out
  -- elsewhere) is not fresh, though its token has an hour left to run.
  IF EXISTS (SELECT 1 FROM public._mfa_fresh WHERE auth_user_id = v_user_id) THEN
    BEGIN
      v_sid := auth.jwt() ->> 'session_id';
    EXCEPTION WHEN OTHERS THEN v_sid := NULL; END;
    IF v_sid IS NULL OR v_sid !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
    SELECT verified_at INTO v_at FROM public._mfa_fresh
     WHERE session_id = v_sid::uuid AND auth_user_id = v_user_id;
    IF v_at IS NULL OR v_at <= now() - make_interval(mins => v_window_min) THEN RETURN false; END IF;
    BEGIN
      IF NOT EXISTS (SELECT 1 FROM auth.sessions WHERE id = v_sid::uuid) THEN RETURN false; END IF;
    EXCEPTION WHEN undefined_table OR insufficient_privilege THEN NULL; END;
    RETURN true;
  END IF;

  -- Claim-path (fast)
  BEGIN
    v_claim_ts := NULLIF(auth.jwt() -> 'app_metadata' ->> 'mfa_verified_at', '')::bigint;
  EXCEPTION WHEN OTHERS THEN v_claim_ts := NULL; END;

  -- DB-path (covers the gap between stamp and next refresh)
  BEGIN
    SELECT NULLIF(raw_app_meta_data ->> 'mfa_verified_at', '')::bigint
      INTO v_db_ts FROM auth.users WHERE id = v_user_id;
  EXCEPTION WHEN OTHERS THEN v_db_ts := NULL; END;

  v_freshest := GREATEST(COALESCE(v_claim_ts, 0), COALESCE(v_db_ts, 0));
  IF v_freshest = 0 THEN RETURN false; END IF;
  RETURN (extract(epoch FROM now())::bigint - v_freshest) < (v_window_min * 60);
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

GRANT EXECUTE ON FUNCTION public.mfa_is_fresh() TO authenticated, anon, service_role;

COMMENT ON FUNCTION public.mfa_is_fresh() IS
  'Returns true iff the calling session passed the second factor within the tenant-configured session_timeout_minutes: since 1841 by the session itself (_mfa_fresh, written by _stamp_mfa_verified for the person''s own session), read from the person''s stamp only for someone with no session written down; since 1911 counted from the session''s last activity (rpc_mfa_keep_alive), at most a day after its code. Used by RLS on sensitive tables and by _need_fresh_mfa().';


-- ────────────────────────────────────────────────────────────────
-- _stamp_mfa_verified(), internal helper that writes the claim
-- ────────────────────────────────────────────────────────────────
-- Centralises the app_metadata write so we can audit which RPCs set it.
-- ONLY callable from within SECURITY DEFINER RPCs defined below (it's
-- not granted to anon/authenticated at all).
CREATE OR REPLACE FUNCTION public._stamp_mfa_verified(p_auth_id uuid) RETURNS void AS $$
DECLARE v_current jsonb;
BEGIN
  IF p_auth_id IS NULL THEN RETURN; END IF;
  SELECT COALESCE(raw_app_meta_data, '{}'::jsonb) INTO v_current FROM auth.users WHERE id = p_auth_id;
  UPDATE auth.users
    SET raw_app_meta_data = v_current || jsonb_build_object('mfa_verified_at', extract(epoch FROM now())::bigint::text),
        updated_at = now()
    WHERE id = p_auth_id;
  -- 1841: and the session that passed, when it is the person's own.
  PERFORM public._mfa_fresh_note(p_auth_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

-- 1841: the session that passed the second factor, written down by its id.
-- Only the person's own session: an administrator setting up someone else's
-- authenticator, or a signed call with no session, writes nothing here.
CREATE OR REPLACE FUNCTION public._mfa_fresh_note(p_auth_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $mfanote$
DECLARE v_sid text;
BEGIN
  IF p_auth_id IS NULL OR auth.uid() IS DISTINCT FROM p_auth_id THEN RETURN; END IF;
  BEGIN
    v_sid := auth.jwt() ->> 'session_id';
  EXCEPTION WHEN OTHERS THEN v_sid := NULL; END;
  IF v_sid IS NULL OR v_sid !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN; END IF;
  INSERT INTO public._mfa_fresh (session_id, auth_user_id, verified_at, entered_at)
  VALUES (v_sid::uuid, p_auth_id, now(), now())
  ON CONFLICT (session_id) DO UPDATE SET verified_at = now(), entered_at = now()
   WHERE public._mfa_fresh.auth_user_id = EXCLUDED.auth_user_id;
END $mfanote$;
REVOKE ALL ON FUNCTION public._mfa_fresh_note(uuid) FROM PUBLIC, anon, authenticated;

-- 1841: one refusal, in one sentence, for every call that needs the second
-- factor and is not a table's (a table's policies ask mfa_is_fresh() already).
-- 42501, as a policy's refusal is, so the portal asks for the second factor.
CREATE OR REPLACE FUNCTION public._need_fresh_mfa() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $needmfa$
BEGIN
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Your second factor needs confirming again before this can be done.'
      USING ERRCODE = '42501';
  END IF;
END $needmfa$;
REVOKE ALL ON FUNCTION public._need_fresh_mfa() FROM PUBLIC, anon, authenticated;

-- 1911: A SESSION IN USE STAYS FRESH (rpc_mfa_keep_alive).
--
-- [stated] Arian: "if its a refresh token thing shouldnt it just work to keep
-- alive, my point was that when i clicked it, then refreshed, it still asked
-- for the authenticator".
--
-- A firm sets session_timeout_minutes as minutes of inactivity, and the
-- freshness above counted them from the moment the code was entered, whatever
-- was done since. Nothing but a code could move that moment, so the portal's
-- Stay signed in kept the page and not the session, and a refresh asked for
-- the code. Now the portal calls this while somebody is working (at most once
-- a minute) and when they press Stay signed in, and a session that is fresh
-- moves the moment it is fresh from on to now: the window is counted from the
-- last thing done, as the setting says. Only a fresh session can: one that has
-- run out, was signed out or was reset is asked for its code, as before. And
-- however busy, the code is asked for again a day after it was entered (or
-- after the firm's own window, where that is longer), so a session somebody
-- has taken cannot be kept fresh for ever.
--
-- Answers kept (this session's moment moved), fresh (as mfa_is_fresh() says:
-- a person read from the stamp, who passed before 1841, is fresh and not kept,
-- and is asked when the stamp's window ends, as before), left_s (the seconds
-- the session now has with nothing more done) and capped (the day's limit is
-- what ends it, so a later call cannot add to it).
CREATE OR REPLACE FUNCTION public.rpc_mfa_keep_alive() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $mfakeep$
DECLARE
  v_uid uuid;
  v_sid text;
  v_window int;
  v_cap interval;
  v_from timestamptz;
  v_entered timestamptz;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('kept', false, 'fresh', false);
  END IF;
  BEGIN
    SELECT GREATEST(5, LEAST(43200, COALESCE(session_timeout_minutes, 480)))
      INTO v_window FROM public.settings LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_window := 480; END;
  IF v_window IS NULL THEN v_window := 480; END IF;
  v_cap := make_interval(mins => GREATEST(v_window, 1440));
  BEGIN
    v_sid := auth.jwt() ->> 'session_id';
  EXCEPTION WHEN OTHERS THEN v_sid := NULL; END;
  IF v_sid IS NULL OR v_sid !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN jsonb_build_object('kept', false, 'fresh', true);
  END IF;
  -- The new moment: now, or the day's limit less the window where that comes
  -- first; never earlier than it was. SET reads the row as it was.
  UPDATE public._mfa_fresh
     SET entered_at = COALESCE(entered_at, verified_at),
         verified_at = GREATEST(verified_at,
           LEAST(now(), COALESCE(entered_at, verified_at) + v_cap - make_interval(mins => v_window)))
   WHERE session_id = v_sid::uuid AND auth_user_id = v_uid
  RETURNING verified_at, entered_at INTO v_from, v_entered;
  IF v_from IS NULL THEN
    RETURN jsonb_build_object('kept', false, 'fresh', true);
  END IF;
  RETURN jsonb_build_object(
    'kept', true,
    'fresh', true,
    'left_s', GREATEST(0, floor(extract(epoch FROM v_from + make_interval(mins => v_window) - now())))::int,
    'capped', v_from + make_interval(mins => v_window) >= v_entered + v_cap);
END $mfakeep$;
REVOKE ALL ON FUNCTION public.rpc_mfa_keep_alive() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_mfa_keep_alive() TO authenticated, service_role;
COMMENT ON FUNCTION public.rpc_mfa_keep_alive() IS
  'Keeps the calling session fresh while it is in use (1911): a session mfa_is_fresh() passes is fresh from now, at most a day (or the firm''s window, where longer) after its code was entered. The portal calls it on activity and from Stay signed in.';

REVOKE ALL ON FUNCTION public._stamp_mfa_verified(uuid) FROM PUBLIC, anon, authenticated;
-- Service role retains the ability for administrative reset if ever needed.


-- ────────────────────────────────────────────────────────────────
-- _clear_mfa_verified(), wipe the claim (MFA reset, session revoke)
-- ────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public._clear_mfa_verified(p_auth_id uuid) RETURNS void AS $$
DECLARE v_current jsonb;
BEGIN
  IF p_auth_id IS NULL THEN RETURN; END IF;
  SELECT COALESCE(raw_app_meta_data, '{}'::jsonb) INTO v_current FROM auth.users WHERE id = p_auth_id;
  UPDATE auth.users
    SET raw_app_meta_data = v_current - 'mfa_verified_at',
        updated_at = now()
    WHERE id = p_auth_id;
  -- 1841: and every session of theirs that passed. A row is kept that no
  -- session has (verified long ago), so they are read session by session from
  -- now on: read from the stamp instead, a token already out would still say
  -- fresh (its copy of the stamp is cleared only when it is renewed).
  UPDATE public._mfa_fresh SET verified_at = '-infinity' WHERE auth_user_id = p_auth_id;
  IF NOT FOUND THEN
    INSERT INTO public._mfa_fresh (session_id, auth_user_id, verified_at)
    VALUES (gen_random_uuid(), p_auth_id, '-infinity');
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

REVOKE ALL ON FUNCTION public._clear_mfa_verified(uuid) FROM PUBLIC, anon, authenticated;


-- ────────────────────────────────────────────────────────────────
-- Update rpc_verify_totp to stamp the claim on success
-- ────────────────────────────────────────────────────────────────
-- Logic preserved exactly from byo-database.sql; only the success branch
-- gains a call to _stamp_mfa_verified for the matched profile's auth_user_id.
DROP FUNCTION IF EXISTS public.rpc_verify_totp(text, text);
CREATE OR REPLACE FUNCTION public.rpc_verify_totp(p_email text, p_code text, p_secret text DEFAULT NULL) RETURNS jsonb AS $$
DECLARE v_prof RECORD; v_ok boolean; v_new_attempts int; v_lock_until timestamptz;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT id, auth_user_id, totp_secret, COALESCE(totp_attempts, 0) AS totp_attempts, totp_locked_until
    INTO v_prof
    FROM public.profiles
    WHERE lower(email) = lower(p_email) AND active = true
    FOR UPDATE;
  IF NOT FOUND OR v_prof.totp_secret IS NULL OR v_prof.totp_secret = '' THEN
    RETURN jsonb_build_object('error', 'MFA not configured');
  END IF;
  IF v_prof.totp_locked_until IS NOT NULL AND v_prof.totp_locked_until > now() THEN
    RETURN jsonb_build_object('error', 'Account locked', 'locked_until', v_prof.totp_locked_until);
  END IF;

  v_ok := public._totp_check(v_prof.totp_secret, p_code);

  IF v_ok THEN
    UPDATE public.profiles
      SET totp_attempts = 0, totp_locked_until = NULL
      WHERE id = v_prof.id;
    -- Stamp the MFA freshness claim so RLS unlocks on next token refresh.
    PERFORM public._stamp_mfa_verified(v_prof.auth_user_id);
    RETURN jsonb_build_object('success', true);
  END IF;

  v_new_attempts := v_prof.totp_attempts + 1;
  IF v_new_attempts >= 5 THEN
    v_lock_until := now() + interval '15 minutes';
    UPDATE public.profiles
      SET totp_attempts = v_new_attempts, totp_locked_until = v_lock_until
      WHERE id = v_prof.id;
    RETURN jsonb_build_object('error', 'Account locked', 'locked_until', v_lock_until);
  END IF;
  UPDATE public.profiles SET totp_attempts = v_new_attempts WHERE id = v_prof.id;
  RETURN jsonb_build_object('error', 'Invalid code', 'attempts_remaining', 5 - v_new_attempts);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.rpc_verify_totp(text, text, text) TO anon, authenticated, service_role;


-- ────────────────────────────────────────────────────────────────
-- Update rpc_save_totp_secret to stamp the claim implicitly
-- ────────────────────────────────────────────────────────────────
-- Rationale: the user literally just scanned a new QR and entered a valid
-- code from the authenticator they control. That's equivalent to passing
-- a TOTP check. Without this stamp, fresh setup would immediately face
-- "MFA not fresh" and re-prompt, creating an infinite loop.
-- Admins resetting someone else's MFA do NOT set it for themselves here;
-- the reset only clears the target user.
CREATE OR REPLACE FUNCTION public.rpc_save_totp_secret(p_email text, p_totp_secret text, p_secret text) RETURNS boolean AS $$
DECLARE v_role text; v_caller_email text; v_caller_auth_id uuid;
        v_target_id uuid; v_target_auth_id uuid; v_was_set boolean;
BEGIN
  IF NOT public._validate_provision_secret(COALESCE(p_secret, '')) THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT role, email, auth_user_id INTO v_role, v_caller_email, v_caller_auth_id
    FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true;
  IF lower(p_email) != lower(v_caller_email) AND v_role NOT IN ('admin', 'senior') THEN
    RAISE EXCEPTION 'Can only save own MFA secret';
  END IF;
  SELECT id, auth_user_id, (totp_secret IS NOT NULL AND totp_secret != '')
    INTO v_target_id, v_target_auth_id, v_was_set
    FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles SET totp_secret = p_totp_secret WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM set_config('pental.bypass_protect', 'false', true);

  -- Only stamp if the caller is saving their OWN secret, this prevents an admin
  -- from accidentally granting themselves fresh-MFA status by resetting someone else.
  IF lower(p_email) = lower(v_caller_email) THEN
    PERFORM public._stamp_mfa_verified(v_caller_auth_id);
  END IF;

  PERFORM public._queue_security_notif(
    'notify_mfa_changed',
    CASE WHEN v_was_set THEN 'MFA authenticator updated' ELSE 'MFA authenticator enabled' END,
    format(
      '<p>The authenticator app for <strong>%s</strong> has been %s.</p>'
      '<p>If this was not you, revoke active sessions in your portal Security settings and contact your administrator.</p>',
      public._html_esc(lower(p_email)), CASE WHEN v_was_set THEN 'updated' ELSE 'enabled' END
    ),
    v_target_id,
    lower(p_email)
  );
  RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp;

GRANT EXECUTE ON FUNCTION public.rpc_save_totp_secret(text, text, text) TO authenticated, service_role;


-- ────────────────────────────────────────────────────────────────
-- New RPC: clear_mfa_for_user, called by the admin MFA reset path
-- ────────────────────────────────────────────────────────────────
-- The settings-sync.js bridge path needs a way to also wipe the stamp. This
-- RPC is gated on provision secret (like every other sensitive BYO RPC) so
-- it's callable from the backend during admin MFA reset.
CREATE OR REPLACE FUNCTION public.rpc_clear_mfa(p_email text, p_secret text DEFAULT NULL) RETURNS boolean AS $$
DECLARE v_auth_id uuid;
BEGIN
  -- Clearing MFA is an authorisation action: a signed-in admin of this portal
  -- only. Pental's provisioning credential no longer grants it.
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE auth_user_id = auth.uid() AND role = 'admin' AND active = true
  ) THEN RAISE EXCEPTION 'Admin session required'; END IF;
  SELECT auth_user_id INTO v_auth_id FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true;
  IF v_auth_id IS NULL THEN RETURN false; END IF;
  -- Same column guard as rpc_save_totp_secret: it only lets admin/senior touch
  -- totp_secret, so this path failed with "Cannot change MFA config" for every
  -- other role. This function has already decided the caller is entitled to the
  -- change, so raise the guard's own flag and drop it straight after.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles SET totp_secret = NULL, totp_attempts = 0, totp_locked_until = NULL
    WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM set_config('pental.bypass_protect', 'false', true);
  PERFORM public._clear_mfa_verified(v_auth_id);
  RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.rpc_clear_mfa(text, text) TO anon, authenticated, service_role;


-- ────────────────────────────────────────────────────────────────
-- RLS TIGHTENING, sensitive tables now require mfa_is_fresh()
-- ────────────────────────────────────────────────────────────────
-- Bootstrap-safe tables NOT gated:
--   settings  , needed to render login page branding and to look up
--                session_timeout_minutes inside mfa_is_fresh() itself.
--   profiles  , the portal must load the caller's own profile to decide
--                whether to show the MFA prompt. Reading your own row is safe;
--                writes stay locked to can_manage() as before.
--   login_codes, _credentials_key, _encryption_keys, _internal_secrets -
--                already REVOKE'd from anon/authenticated in byo-database.sql;
--                only reachable via SECURITY DEFINER RPCs.
--
-- All other data-bearing tables get mfa_is_fresh() AND'd into their policies.

-- Drop existing policies we're about to tighten (safe: we recreate them).
DO $drp$ DECLARE _tbl text; _pol record; BEGIN
  FOR _tbl IN SELECT unnest(ARRAY[
    'clients','assessments','findings','proposals','invoices','kb_entries',
    'meetings','meeting_attendees','tickets','timeline_events',
    'assessment_comments','assessment_files','feedback',
    'contractor_payments','email_notifications','payment_events','qa_comments'
  ]) LOOP
    FOR _pol IN SELECT policyname FROM pg_policies WHERE tablename = _tbl AND schemaname = 'public' LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', _pol.policyname, _tbl);
    END LOOP;
  END LOOP;
END $drp$;

-- CLIENTS
-- 1943: a contractor sees the clients they brought and the client of each
-- engagement that is theirs, led by them or handed to their team (can_see_client).
CREATE POLICY clients_read ON public.clients FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_staff()
    OR (public.current_user_role() = 'contractor' AND (created_by = public.current_profile_id()
        OR id IN (SELECT a.client_id FROM public.assessments a
                   WHERE a.lead_id = public.current_profile_id()
                      OR (a.contractor_team_id IS NOT NULL AND a.contractor_team_id = public.current_contractor_team_id()))))
    OR (public.current_user_role() = 'client' AND id = public.current_user_client_id())));
CREATE POLICY clients_insert ON public.clients FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_write());
CREATE POLICY clients_update ON public.clients FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_write()) WITH CHECK (true);
CREATE POLICY clients_delete ON public.clients FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- ASSESSMENTS
-- 1943: A CONTRACTOR'S ENGAGEMENTS ARE THE ONES THEY LEAD AND THE ONES HANDED TO
-- THEIR TEAM, and only those, whichever way they are asked for. A contractor
-- could make an engagement for any client by its id (and so reach that client
-- through it), and move one of theirs to another client or another lead, since
-- what an update made was never checked (WITH CHECK (true)). They make one only
-- for a client they brought, leading it themselves, and what they change stays
-- theirs; what of it they may change is _contractor_guard_assessment's.
-- 1970: the firm's working staff (is_delivery_staff), not Sales or Marketing:
-- an engagement's record is its work too (the executive summary, the report's
-- sections, the scope, the review, the client's credentials). They read each
-- engagement's commercial record through rpc_engagements_commercial().
CREATE POLICY assessments_read ON public.assessments FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff()
    OR (public.current_user_role() = 'contractor' AND (lead_id = public.current_profile_id()
        OR (contractor_team_id IS NOT NULL AND contractor_team_id = public.current_contractor_team_id())))
    OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id())));
CREATE POLICY assessments_insert ON public.assessments FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND (public.current_user_role() IN ('admin', 'senior', 'standard')
    OR (public.current_user_role() = 'contractor' AND lead_id = public.current_profile_id()
        AND client_id IS NOT NULL AND public.can_access_client(client_id)
        AND (contractor_team_id IS NULL OR contractor_team_id = public.current_contractor_team_id()))));
CREATE POLICY assessments_update ON public.assessments FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff()
    OR (public.current_user_role() = 'contractor' AND (lead_id = public.current_profile_id()
        OR (contractor_team_id IS NOT NULL AND contractor_team_id = public.current_contractor_team_id())))))
  WITH CHECK (public.mfa_is_fresh() AND (public.is_delivery_staff()
    OR (public.current_user_role() = 'contractor' AND (lead_id = public.current_profile_id()
        OR (contractor_team_id IS NOT NULL AND contractor_team_id = public.current_contractor_team_id())))));
CREATE POLICY assessments_delete ON public.assessments FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- FINDINGS
-- AND THE ARM 649 ADDED, WHICH THIS BLOCK HAD DELETED (857).
--
-- The definition near the top of this file carries a fourth arm for a finding
-- with NO assessment, matched on the finding's own `client_id`. The MFA
-- tightening here DROPS every policy on these tables and recreates them, and it
-- recreated this one without that arm - so the arm existed in the file, was
-- never live on any database, and a scan finding imported since 779 (which
-- removed the assessment from an import) was unreachable by the customer it
-- belonged to however its visibility flag was set.
--
-- Found by a check asserting that EVERY definition of this policy carries the
-- branch, rather than reading whichever one came first.
--
-- `client_visible` is still required: a null assessment is not a way around the
-- release rule.
-- 1970: the firm's working staff, not Sales or Marketing (is_delivery_staff).
CREATE POLICY findings_read ON public.findings FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff()
    -- 1943: an engagement of theirs, led by them or handed to their team.
    OR (public.current_user_role() = 'contractor' AND assessment_id IN (SELECT a.id FROM public.assessments a
          WHERE a.lead_id = public.current_profile_id()
             OR (a.contractor_team_id IS NOT NULL AND a.contractor_team_id = public.current_contractor_team_id())))
    OR (public.current_user_role() = 'client' AND client_visible = true AND assessment_id IN (SELECT id FROM public.assessments WHERE client_id = public.current_user_client_id()))
    OR (public.current_user_role() = 'client' AND client_visible = true AND assessment_id IS NULL AND client_id IS NOT NULL AND client_id = public.current_user_client_id())));
CREATE POLICY findings_insert ON public.findings FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_write() AND public.can_access_assessment(assessment_id));
CREATE POLICY findings_update ON public.findings FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_staff() OR public.current_user_role() = 'contractor'))
  WITH CHECK (true);
-- 1842: AND A STANDARD TESTER. [stated] Arian, asked whether standard testers
-- should delete findings too: "yes". A finding's review comments go with it
-- (qa_comments' link cascades) and the pictures nothing else uses can be
-- removed by whoever deleted it (_finding_picture_unused). Contractors and
-- clients still delete none.
CREATE POLICY findings_delete ON public.findings FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','standard'));

-- PROPOSALS
CREATE POLICY proposals_read ON public.proposals FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.current_user_role() IN ('admin','senior','sales','contractor')
    OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id())));
CREATE POLICY proposals_insert ON public.proposals FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','contractor')
              AND public.can_access_client(client_id));
-- 1839: the firm's people only. A client signs through rpc_sign_proposal and
-- declines through rpc_decline_proposal; a client's own write could change
-- the price their invoices are made from, and mark it signed with no
-- signature (the accounting audit, finding 5).
CREATE POLICY proposals_update ON public.proposals FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','contractor'))
  WITH CHECK (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','contractor'));
CREATE POLICY proposals_delete ON public.proposals FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- INVOICES
CREATE POLICY invoices_read ON public.invoices FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.current_user_role() IN ('admin','senior','sales')
    OR (public.current_user_role() = 'client' AND client_id = public.current_user_client_id())));
CREATE POLICY invoices_insert ON public.invoices FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_manage());
CREATE POLICY invoices_update ON public.invoices FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage()) WITH CHECK (true);
CREATE POLICY invoices_delete ON public.invoices FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- KB_ENTRIES
-- 1798: 'not a client' also admitted 'none', the role a signed-in session
-- with no active profile has. These five internal reads now name both.
-- 1943: THE LIBRARY IS THE FIRM'S. A contractor reads it while the firm lets its
-- contractors use it (settings.contractors_library, on unless turned off), adds
-- to it then, and changes only what they added: any contractor could rewrite
-- any entry (can_write() admits contractors, and the change was never checked).
CREATE POLICY kb_read ON public.kb_entries FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND public.current_user_role() NOT IN ('client', 'none')
    AND (public.current_user_role() <> 'contractor' OR public._contractor_library_on()));
CREATE POLICY kb_insert ON public.kb_entries FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND (public.current_user_role() IN ('admin', 'senior', 'standard')
    OR (public.current_user_role() = 'contractor' AND public._contractor_library_on())));
CREATE POLICY kb_update ON public.kb_entries FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND (public.current_user_role() IN ('admin', 'senior', 'standard')
    OR (public.current_user_role() = 'contractor' AND public._contractor_library_on() AND created_by = public.current_profile_id())))
  WITH CHECK (public.mfa_is_fresh() AND (public.current_user_role() IN ('admin', 'senior', 'standard')
    OR (public.current_user_role() = 'contractor' AND public._contractor_library_on() AND created_by = public.current_profile_id())));
CREATE POLICY kb_delete ON public.kb_entries FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- MEETINGS + ATTENDEES
-- 1943: a contractor's meetings are the ones they made, were given, or are
-- attending; the firm's diary of sales calls and client meetings is not
-- theirs (_contractor_meeting).
CREATE POLICY meetings_read ON public.meetings FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.current_user_role() NOT IN ('client', 'none', 'contractor')
    OR public._contractor_meeting(id)));
CREATE POLICY meetings_insert ON public.meetings FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','sales','standard'));
CREATE POLICY meetings_update ON public.meetings FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','sales','standard'))
  WITH CHECK (true);
CREATE POLICY meetings_delete ON public.meetings FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());
CREATE POLICY attendees_read ON public.meeting_attendees FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.current_user_role() NOT IN ('client', 'none', 'contractor')
    OR public._contractor_meeting(meeting_id)));
CREATE POLICY attendees_write ON public.meeting_attendees FOR ALL TO authenticated
  USING (public.mfa_is_fresh() AND public.current_user_role() IN ('admin','senior','sales','standard'))
  WITH CHECK (true);

-- TICKETS
CREATE POLICY tickets_read ON public.tickets FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND public.can_access_client(client_id));
CREATE POLICY tickets_insert ON public.tickets FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_write() AND public.can_access_client(client_id));
CREATE POLICY tickets_update ON public.tickets FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_write()) WITH CHECK (true);
CREATE POLICY tickets_delete ON public.tickets FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());


-- timeline_read was mfa_is_fresh() and nothing else, so ANY signed-in user, a
-- client included, could read the activity log of EVERY engagement in the
-- database: titles, details, who did what and when. The portal happens to
-- filter by assessment in the query it sends, which is not a control.
CREATE POLICY timeline_read ON public.timeline_events FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND public.can_access_assessment(assessment_id));
CREATE POLICY timeline_insert ON public.timeline_events FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_write() AND public.can_access_assessment(assessment_id));
CREATE POLICY timeline_update ON public.timeline_events FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_write()) WITH CHECK (true);
CREATE POLICY timeline_delete ON public.timeline_events FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- ASSESSMENT_COMMENTS
-- Read: staff/contractor see everything. Clients see only client_visible
-- comments on their own assessments. The client_visible filter prevents
-- internal-only staff comments from leaking through PostgREST.
CREATE POLICY acom_read ON public.assessment_comments FOR SELECT TO authenticated
  USING (
    public.mfa_is_fresh() AND (
      public.current_user_role() IN ('admin','senior','standard','sales','marketing','contractor')
      OR (
        public.current_user_role() = 'client'
        AND client_visible = true
        AND assessment_id IN (
          SELECT id FROM public.assessments WHERE client_id = public.current_user_client_id()
        )
      )
    )
  );
-- Insert: staff/contractor can post anything. Clients can only post
-- client_visible=true on their own assessments, they can't sneak an
-- internal comment in by setting the flag false.
CREATE POLICY acom_insert ON public.assessment_comments FOR INSERT TO authenticated
  WITH CHECK (
    public.mfa_is_fresh()
    AND user_id IS NOT NULL
    -- The author is whoever is making the request, not whoever the client
    -- says. Without this a user could post as any other user.
    AND user_id = public.current_profile_id()
    AND (
      public.current_user_role() IN ('admin','senior','standard','sales','marketing','contractor')
      OR (
        public.current_user_role() = 'client'
        AND client_visible = true
        AND assessment_id IN (
          SELECT id FROM public.assessments WHERE client_id = public.current_user_client_id()
        )
      )
    )
  );
-- Update: only the author can edit. Clients can't flip a comment to
-- internal-only retroactively (their own comments must stay
-- client_visible=true).
CREATE POLICY acom_update ON public.assessment_comments FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND (user_id = public.current_profile_id() OR public.can_manage()))
  WITH CHECK (
    user_id = public.current_profile_id()
    AND (
      public.current_user_role() IN ('admin','senior','standard','sales','marketing','contractor')
      OR (public.current_user_role() = 'client' AND client_visible = true)
    )
  );
CREATE POLICY acom_delete ON public.assessment_comments FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND (user_id = public.current_profile_id() OR public.can_manage()));

-- ASSESSMENT_FILES
-- 1711: A CLIENT MAY ADD A FILE TO THEIR OWN ENGAGEMENT.
--
-- [stated] Arian: "for the upload areas when a client wants to upload something
-- it doesnt work Your session needs re-verifying before that can be saved."
--
-- The portal offers a client the Upload button on their engagement's files and
-- the storage policy lets the file itself in, but this insert policy asked for
-- `can_write()`, which is staff and contractors only. So the file landed in
-- storage, the row recording it was refused by row-level security, and the
-- portal read the refusal as a stale session (every RLS refusal reads that way,
-- because `mfa_is_fresh()` is in every write policy). It was never the session.
--
-- A client's row is held to what their upload actually is: their own
-- organisation's engagement (`can_access_assessment`), marked as theirs and
-- shared with them, in that engagement's own folder and nowhere under it, not a
-- scan's document or one of the firm's document slots, and at a path no other
-- row already records, so a client cannot put a name to a file somebody else
-- uploaded. The author trigger stamps `uploaded_by` with them.
CREATE OR REPLACE FUNCTION public._afile_client_insert_ok(
  p_assessment uuid, p_path text, p_by_client boolean, p_visible boolean, p_scan uuid, p_doc_type text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
  SELECT public.current_user_role() = 'client'
     AND p_by_client IS TRUE AND p_visible IS TRUE
     AND p_scan IS NULL AND COALESCE(p_doc_type, '') = ''
     AND p_path ~ ('^' || p_assessment::text || '/[^/]+$')
     AND NOT EXISTS (SELECT 1 FROM public.assessment_files f WHERE f.storage_path = p_path)
$$;
REVOKE ALL ON FUNCTION public._afile_client_insert_ok(uuid, text, boolean, boolean, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public._afile_client_insert_ok(uuid, text, boolean, boolean, uuid, text) TO authenticated, service_role;

-- 1970: the firm's working staff, not Sales or Marketing (is_delivery_staff):
-- evidence, reports and letters are the findings in another form.
CREATE POLICY afile_read ON public.assessment_files FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff()
    -- 1943: an engagement of theirs, led by them or handed to their team.
    OR (public.current_user_role() = 'contractor' AND assessment_id IN (SELECT a.id FROM public.assessments a
          WHERE a.lead_id = public.current_profile_id()
             OR (a.contractor_team_id IS NOT NULL AND a.contractor_team_id = public.current_contractor_team_id())))
    -- 1779: a PDF filed with the report or the letter is the client's once the
    -- report is delivered, as the report itself is (1777): not before, and not
    -- while it is taken back. Every other file is theirs as it was.
    OR (public.current_user_role() = 'client' AND client_visible = true AND assessment_id IN (
          SELECT a.id FROM public.assessments a
           WHERE a.client_id = public.current_user_client_id()
             AND (COALESCE(assessment_files.doc_type, '') NOT IN ('report', 'attestation')
                  OR a.status = 'delivered' OR a.delivered_at IS NOT NULL)))));
CREATE POLICY afile_insert ON public.assessment_files FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_access_assessment(assessment_id) AND (
    public.can_write()
    OR public._afile_client_insert_ok(assessment_id, storage_path, uploaded_by_client, client_visible, scan_run_id, doc_type)));
CREATE POLICY afile_update ON public.assessment_files FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_write()) WITH CHECK (true);
-- 1714: and a client removes a file THEY uploaded, from their own
-- organisation's engagement. The author trigger stamps `uploaded_by`, so it is
-- theirs and cannot be claimed.
CREATE POLICY afile_delete ON public.assessment_files FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND (public.can_write()
    OR (public.current_user_role() = 'client' AND uploaded_by_client IS TRUE
        AND uploaded_by = public.current_profile_id()
        AND public.can_access_assessment(assessment_id))));



-- feedback_read was mfa_is_fresh() alone, so any signed-in user could read every
-- rating, testimonial and comment left by every client of the firm.
-- 1943: a contractor reads what was said about their own engagements and their
-- own clients; the firm's other ratings and testimonials are not theirs.
CREATE POLICY feedback_read ON public.feedback FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (
    (public.current_user_role() NOT IN ('contractor', 'none') AND (client_id IS NULL OR public.can_access_client(client_id)))
    OR (public.current_user_role() = 'contractor' AND (
          (assessment_id IS NOT NULL AND public.can_access_assessment(assessment_id))
          OR (client_id IS NOT NULL AND public.can_access_client(client_id))))));
CREATE POLICY feedback_insert ON public.feedback FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_access_client(client_id)
              AND (assessment_id IS NULL OR public.can_access_assessment(assessment_id)));
CREATE POLICY feedback_update ON public.feedback FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage()) WITH CHECK (true);
CREATE POLICY feedback_delete ON public.feedback FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- CONTRACTOR_PAYMENTS
CREATE POLICY cpay_read ON public.contractor_payments FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.can_manage() OR contractor_id = public.current_profile_id()));
CREATE POLICY cpay_insert ON public.contractor_payments FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_manage());
CREATE POLICY cpay_update ON public.contractor_payments FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage()) WITH CHECK (true);
CREATE POLICY cpay_delete ON public.contractor_payments FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- EMAIL_NOTIFICATIONS (usually admin view only)
CREATE POLICY enotif_read ON public.email_notifications FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());
-- 1797: the firm's staff only. Anybody signed in could write a row here, a
-- client included, and a pending row is mail the outbox sends from the firm's
-- own mailbox to whatever address it names. While the outbox could not reach
-- this database that sent nothing; now it does, so only the people who may
-- send mail from the portal at all (the send route's own rule) may queue it.
CREATE POLICY enotif_insert ON public.email_notifications FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.is_staff());
CREATE POLICY enotif_update ON public.email_notifications FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage()) WITH CHECK (true);
CREATE POLICY enotif_delete ON public.email_notifications FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- PAYMENT_EVENTS
CREATE POLICY pe_read ON public.payment_events FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());
CREATE POLICY pe_insert ON public.payment_events FOR INSERT TO authenticated
  WITH CHECK (public.mfa_is_fresh() AND public.can_manage());

-- QA_COMMENTS
-- 1943: AND THE CONTRACTOR WHOSE REPORT IT IS. A report a contractor wrote came
-- back from QA with remarks they could not read (staff only), so "Changes to
-- make" listed changes nobody could see. They read, answer and resolve the
-- remarks on their own engagements (led by them or handed to their team); a
-- reviewer's words stay the reviewer's (_contractor_guard_qa_comment), and the
-- review itself, taking it on and signing it off, stays the firm's
-- (_contractor_guard_assessment).
-- 1970: a review is of findings: the firm's working staff's, not Sales' or
-- Marketing's (is_delivery_staff).
CREATE POLICY qa_read ON public.qa_comments FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff()
    OR (public.current_user_role() = 'contractor' AND public._qa_comment_contractor(assessment_id, finding_id))));
CREATE POLICY qa_insert ON public.qa_comments FOR INSERT TO authenticated
  WITH CHECK (
    public.mfa_is_fresh()
    AND (public.is_delivery_staff()
         OR (public.current_user_role() = 'contractor' AND public._qa_comment_contractor(assessment_id, finding_id)))
    -- The author is whoever is making the request. Without this, any staff
    -- member could post a comment carrying somebody else's user_id.
    AND user_id = public.current_profile_id()
  );
-- 1460: WITH CHECK IS EVALUATED AGAINST THE ROW AFTER THE UPDATE, NOT AGAINST
-- WHAT THE UPDATE TOUCHED.
--
-- [stated] Arian: "it says failed to resolve comments" - a 403 from PostgREST
-- on `qa_comments?or=(id.eq.<id>,parent_id.eq.<id>)`.
--
-- The comment above this policy said the intent exactly right: "Staff may still
-- resolve anybody's comment; they may not change whose it is." The condition
-- written underneath it did the opposite. `user_id = current_profile_id()` is
-- checked against the row as it will exist, and resolving somebody else's
-- comment leaves THEIR user_id on it - so the check failed and the whole
-- statement was refused. **Nobody could resolve a comment they had not written,
-- which is most of them: QA writes the remark, the tester resolves it.**
--
-- AND THE THING IT WAS GUARDING WAS ALREADY GUARDED, twenty lines below: the
-- BEFORE UPDATE trigger `_force_comment_author` does `NEW.user_id :=
-- OLD.user_id`, so the author of an existing comment cannot be changed by
-- anybody, by any route. A BEFORE trigger runs before WITH CHECK is evaluated,
-- so the check was comparing the ORIGINAL author against the person resolving
-- and refusing every time they differed. It protected nothing and broke the
-- one operation the table exists for.
CREATE POLICY qa_update ON public.qa_comments FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff()
    OR (public.current_user_role() = 'contractor' AND public._qa_comment_contractor(assessment_id, finding_id))))
  WITH CHECK (public.mfa_is_fresh() AND (public.is_delivery_staff()
    OR (public.current_user_role() = 'contractor' AND public._qa_comment_contractor(assessment_id, finding_id))));
CREATE POLICY qa_delete ON public.qa_comments FOR DELETE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage());

-- ── The comment author is DERIVED, never accepted ────────────────────────
-- RLS above stops a forged user_id, but user_name is a plain text column the
-- client also supplies, and it is what actually gets displayed. Left alone, a
-- user could post under somebody else's name while carrying their own id. This
-- sets both from the caller's own profile on every insert, and refuses to let
-- either change on update.
--
-- A NULL current_profile_id() means the writer is not an authenticated user
-- with a profile, which is the service role writing a system comment. Those
-- rows are left exactly as supplied.
CREATE OR REPLACE FUNCTION public._force_comment_author()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE
  v_id uuid := public.current_profile_id();
  v_name text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- The author of an existing comment is not editable by anybody.
    NEW.user_id := OLD.user_id;
    NEW.user_name := OLD.user_name;
    RETURN NEW;
  END IF;
  IF v_id IS NULL THEN
    RETURN NEW;              -- service role / system row, left as written
  END IF;
  SELECT name INTO v_name FROM public.profiles WHERE id = v_id;
  NEW.user_id := v_id;
  NEW.user_name := COALESCE(v_name, NEW.user_name);
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS tr_qa_comment_author ON public.qa_comments;
CREATE TRIGGER tr_qa_comment_author
  BEFORE INSERT OR UPDATE ON public.qa_comments
  FOR EACH ROW EXECUTE FUNCTION public._force_comment_author();

DROP TRIGGER IF EXISTS tr_acom_author ON public.assessment_comments;
CREATE TRIGGER tr_acom_author
  BEFORE INSERT OR UPDATE ON public.assessment_comments
  FOR EACH ROW EXECUTE FUNCTION public._force_comment_author();

-- ── Same hole, every other table that records WHO DID SOMETHING ──────────
-- Found by auditing every table carrying a client-supplied identity column.
-- In each case the column is written by the browser and no policy checked it
-- against the caller, so any authenticated user could attribute their action
-- to somebody else. timeline_events is the worst of them, because that is the
-- record of what happened on an engagement.
--
-- One generic trigger rather than nine: the column name is passed as a trigger
-- argument. Same rules as the comment one. On INSERT the value is DERIVED from
-- the caller's own profile. On UPDATE it is forced back to its previous value,
-- because who did a thing does not change afterwards. A null current_profile_id()
-- is the service role writing a system row and is left alone.
--
-- NOT covered, deliberately: assessments.lead_id and meeting_attendees.user_id
-- name OTHER people by design, and proposals.signed_by is the signature text a
-- signer types, not an author reference.
CREATE OR REPLACE FUNCTION public._force_row_author()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE
  v_col text := TG_ARGV[0];
  v_id uuid := public.current_profile_id();
  v_new jsonb := to_jsonb(NEW);
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RETURN jsonb_populate_record(NEW, jsonb_build_object(v_col, to_jsonb(OLD) -> v_col));
  END IF;
  IF v_id IS NULL THEN
    RETURN NEW;
  END IF;
  RETURN jsonb_populate_record(NEW, jsonb_build_object(v_col, to_jsonb(v_id)));
END $$;

-- the audit trail of what happened on an engagement
DROP TRIGGER IF EXISTS tr_timeline_events_author ON public.timeline_events;
CREATE TRIGGER tr_timeline_events_author
  BEFORE INSERT OR UPDATE ON public.timeline_events
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('user_id');

-- who raised a finding
DROP TRIGGER IF EXISTS tr_findings_author ON public.findings;
CREATE TRIGGER tr_findings_author
  BEFORE INSERT OR UPDATE ON public.findings
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

-- who uploaded evidence
DROP TRIGGER IF EXISTS tr_assessment_files_author ON public.assessment_files;
CREATE TRIGGER tr_assessment_files_author
  BEFORE INSERT OR UPDATE ON public.assessment_files
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('uploaded_by');

-- who wrote a knowledge base entry
DROP TRIGGER IF EXISTS tr_kb_entries_author ON public.kb_entries;
CREATE TRIGGER tr_kb_entries_author
  BEFORE INSERT OR UPDATE ON public.kb_entries
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

-- who added a client
DROP TRIGGER IF EXISTS tr_clients_author ON public.clients;
CREATE TRIGGER tr_clients_author
  BEFORE INSERT OR UPDATE ON public.clients
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

-- who raised a ticket
DROP TRIGGER IF EXISTS tr_tickets_author ON public.tickets;
CREATE TRIGGER tr_tickets_author
  BEFORE INSERT OR UPDATE ON public.tickets
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

-- who recorded a payment
DROP TRIGGER IF EXISTS tr_contractor_payments_author ON public.contractor_payments;
CREATE TRIGGER tr_contractor_payments_author
  BEFORE INSERT OR UPDATE ON public.contractor_payments
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

-- who booked a meeting
DROP TRIGGER IF EXISTS tr_meetings_author ON public.meetings;
CREATE TRIGGER tr_meetings_author
  BEFORE INSERT OR UPDATE ON public.meetings
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

-- ═══════════════════════════════════════════════════════════════════════════
-- 1943: A CONTRACTOR SEES THEIR OWN WORK AND NOTHING ELSE, ALONE OR IN A TEAM.
--
-- Asked for after contractors had been in beta: an audit of what a contractor
-- can read and change, so that they see only their own data; teams, for
-- several people from another consultancy taking a firm's overflow work, each
-- team seeing only its own; and contractors out of beta but OFF by default,
-- turned on by the firm (current_user_role(), near the top).
--
-- A contractor's work is the engagements they lead and the ones handed to their
-- team (can_access_assessment), with those engagements' findings, files,
-- comments, checklists, timeline, credentials and QA remarks; the client each
-- is for, to read (can_see_client); the clients they brought themselves and
-- that business (can_access_client: tickets, scanning, proposals, feedback);
-- their own meetings, payments, sessions and profile; their team and its
-- people; and the firm's library, to use, while the firm allows it. Nothing
-- else: the audit closed what reached further (see each rule, marked 1943).
-- These four guards hold what a contractor may change however it is reached,
-- through a rule or through a function that runs as the database.
-- ═══════════════════════════════════════════════════════════════════════════

-- The team. The firm's people read it; its own people read it; an administrator
-- or a senior makes, renames and removes it. Removing it leaves its people and
-- its engagements in no team (ON DELETE SET NULL), with the firm.
DROP POLICY IF EXISTS contractor_teams_read ON public.contractor_teams;
CREATE POLICY contractor_teams_read ON public.contractor_teams FOR SELECT TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_staff() OR id = public.current_contractor_team_id()));
DROP POLICY IF EXISTS contractor_teams_write ON public.contractor_teams;
CREATE POLICY contractor_teams_write ON public.contractor_teams FOR ALL TO authenticated
  USING (public.mfa_is_fresh() AND public.can_manage())
  WITH CHECK (public.mfa_is_fresh() AND public.can_manage());
REVOKE ALL ON public.contractor_teams FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.contractor_teams TO authenticated;
GRANT ALL ON public.contractor_teams TO service_role;
DROP TRIGGER IF EXISTS tr_contractor_teams_author ON public.contractor_teams;
CREATE TRIGGER tr_contractor_teams_author
  BEFORE INSERT OR UPDATE ON public.contractor_teams
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');
CREATE OR REPLACE FUNCTION public._contractor_team_touch()
RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_catalog, pg_temp AS $$
BEGIN
  NEW.name := btrim(COALESCE(NEW.name, ''));
  NEW.updated_at := now();
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tr_contractor_teams_touch ON public.contractor_teams;
CREATE TRIGGER tr_contractor_teams_touch
  BEFORE INSERT OR UPDATE ON public.contractor_teams
  FOR EACH ROW EXECUTE FUNCTION public._contractor_team_touch();

-- A team is a contractor's: anybody given another role leaves theirs.
CREATE OR REPLACE FUNCTION public._profile_team_role()
RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_catalog, pg_temp AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM 'contractor' AND NEW.contractor_team_id IS NOT NULL THEN
    NEW.contractor_team_id := NULL;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS tr_profile_team_role ON public.profiles;
CREATE TRIGGER tr_profile_team_role
  BEFORE INSERT OR UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public._profile_team_role();

-- Who is calling, as a contractor: their profile and team, or nothing when
-- they are not one. A contractor while contractors are off is refused outright.
CREATE OR REPLACE FUNCTION public._contractor_caller(OUT is_contractor boolean, OUT me uuid, OUT team uuid)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE v_raw text;
BEGIN
  is_contractor := false;
  IF COALESCE(current_setting('pental.bypass_protect', true), '') = 'true' OR auth.uid() IS NULL THEN RETURN; END IF;
  SELECT p.role, p.id, p.contractor_team_id INTO v_raw, me, team
    FROM public.profiles p WHERE p.auth_user_id = auth.uid() AND p.active = true LIMIT 1;
  IF v_raw IS DISTINCT FROM 'contractor' THEN me := NULL; team := NULL; RETURN; END IF;
  IF public.current_user_role() IS DISTINCT FROM 'contractor' THEN
    RAISE EXCEPTION 'Contractor access is switched off for this firm' USING ERRCODE = '42501';
  END IF;
  is_contractor := true;
END $$;
REVOKE ALL ON FUNCTION public._contractor_caller() FROM PUBLIC, anon, authenticated;

-- An engagement. A contractor makes one only for a client they brought, and
-- leads it (rpc_sign_proposal makes the one a signed proposal starts, so the
-- contractor who signed is its lead whatever it was copied from). On one of
-- theirs, its client and its team are the firm's to change; its lead moves
-- only within the team it was handed to; and the review is the firm's: who
-- reviews it, what they marked reviewed, taking it on and signing it off. With
-- QA on, it goes to the client once QA has signed it off.
CREATE OR REPLACE FUNCTION public._contractor_guard_assessment()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE c record; v_qa_on boolean;
BEGIN
  SELECT * INTO c FROM public._contractor_caller();
  IF NOT c.is_contractor THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.lead_id := c.me;
    IF NEW.client_id IS NULL OR NOT public.can_access_client(NEW.client_id) THEN
      RAISE EXCEPTION 'A contractor makes engagements only for clients they brought' USING ERRCODE = '42501';
    END IF;
    IF NEW.contractor_team_id IS NOT NULL AND NEW.contractor_team_id IS DISTINCT FROM c.team THEN
      RAISE EXCEPTION 'That team is not yours' USING ERRCODE = '42501';
    END IF;
    IF NEW.qa_assignee IS NOT NULL THEN NEW.qa_assignee := NULL; END IF;
    -- A new engagement starts before its review, as one made any other way
    -- does: with QA on it is not made already reviewed, signed off or sent.
    SELECT s.qa_enabled INTO v_qa_on FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1;
    IF COALESCE(v_qa_on, true) THEN
      IF NEW.qa_status IN ('in_review', 'approved') THEN NEW.qa_status := 'not_submitted'; END IF;
      NEW.qa_reviewed := '{}'::jsonb;
      NEW.qa_ticks := '{}'::jsonb;       -- 1956
      NEW.qa_ai_review := '{}'::jsonb;
      IF NEW.status = 'delivered' THEN NEW.status := 'completed'; END IF;
      NEW.delivered_at := NULL;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.client_id IS DISTINCT FROM OLD.client_id THEN
    RAISE EXCEPTION 'Which client an engagement is for is the firm''s to change' USING ERRCODE = '42501';
  END IF;
  IF NEW.contractor_team_id IS DISTINCT FROM OLD.contractor_team_id THEN
    RAISE EXCEPTION 'Which team an engagement is with is the firm''s to change' USING ERRCODE = '42501';
  END IF;
  IF NEW.lead_id IS DISTINCT FROM OLD.lead_id AND NOT (
       OLD.contractor_team_id IS NOT NULL AND OLD.contractor_team_id = c.team
       AND EXISTS (SELECT 1 FROM public.profiles p
                    WHERE p.id = NEW.lead_id AND p.active = true AND p.role = 'contractor'
                      AND p.contractor_team_id = c.team)) THEN
    RAISE EXCEPTION 'Who leads an engagement is the firm''s to change' USING ERRCODE = '42501';
  END IF;
  -- With QA off a firm has no review: a report its tester marks ready goes out
  -- (submitForQA marks it 'approved', which is all "ready" is then).
  SELECT s.qa_enabled INTO v_qa_on FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1;
  IF COALESCE(v_qa_on, true) THEN
    IF NEW.qa_assignee IS DISTINCT FROM OLD.qa_assignee THEN
      RAISE EXCEPTION 'Who reviews a report is the firm''s to decide' USING ERRCODE = '42501';
    END IF;
    IF NEW.qa_reviewed IS DISTINCT FROM OLD.qa_reviewed THEN
      RAISE EXCEPTION 'What the reviewer has marked reviewed is the reviewer''s' USING ERRCODE = '42501';
    END IF;
    -- 1956: the firm's QA checklist is ticked by its reviewer, and what its
    -- AI reviewer said is theirs too.
    IF NEW.qa_ticks IS DISTINCT FROM OLD.qa_ticks THEN
      RAISE EXCEPTION 'The QA checklist is ticked by the firm''s reviewer' USING ERRCODE = '42501';
    END IF;
    IF NEW.qa_ai_review IS DISTINCT FROM OLD.qa_ai_review THEN
      RAISE EXCEPTION 'What the AI reviewer said is the firm''s reviewer''s' USING ERRCODE = '42501';
    END IF;
    IF NEW.qa_status IS DISTINCT FROM OLD.qa_status AND NEW.qa_status IN ('in_review', 'approved') THEN
      RAISE EXCEPTION 'The firm''s QA reviews a report and signs it off' USING ERRCODE = '42501';
    END IF;
    IF ((NEW.status = 'delivered' AND OLD.status IS DISTINCT FROM 'delivered')
        OR (NEW.delivered_at IS NOT NULL AND OLD.delivered_at IS NULL))
       AND NEW.qa_status IS DISTINCT FROM 'approved' THEN
      RAISE EXCEPTION 'This report goes to the client once the firm''s QA has signed it off' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public._contractor_guard_assessment() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS tr_contractor_guard ON public.assessments;
CREATE TRIGGER tr_contractor_guard
  BEFORE INSERT OR UPDATE ON public.assessments
  FOR EACH ROW EXECUTE FUNCTION public._contractor_guard_assessment();

-- A proposal. A contractor's are the ones they made or sent and those of the
-- clients they brought, and they make one only for such a client. Signing and
-- declining by a proposal's id run as the database (rpc_sign_proposal,
-- rpc_decline_proposal, save_proposal_auth), so they are held here, where every
-- route meets: a contractor could sign the firm's proposal to any client and
-- so become the lead of the engagement the signature starts.
CREATE OR REPLACE FUNCTION public._contractor_guard_proposal()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE c record;
BEGIN
  SELECT * INTO c FROM public._contractor_caller();
  IF NOT c.is_contractor THEN RETURN NEW; END IF;
  -- The engagement a proposal is for, and the one signing it copies, are the
  -- contractor's own: pointing a proposal at the firm's other work would copy
  -- that work's findings into a new engagement of theirs when it is signed.
  IF NEW.assessment_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.assessment_id IS DISTINCT FROM OLD.assessment_id)
     AND NOT public.can_access_assessment(NEW.assessment_id) THEN
    RAISE EXCEPTION 'A contractor''s proposal is for an engagement of theirs' USING ERRCODE = '42501';
  END IF;
  IF NEW.source_assessment_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.source_assessment_id IS DISTINCT FROM OLD.source_assessment_id)
     AND NOT public.can_access_assessment(NEW.source_assessment_id) THEN
    RAISE EXCEPTION 'A contractor copies only an engagement of theirs' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.client_id IS NULL OR NOT public.can_access_client(NEW.client_id) THEN
      RAISE EXCEPTION 'A contractor makes proposals only for clients they brought' USING ERRCODE = '42501';
    END IF;
    NEW.created_by := c.me;
    RETURN NEW;
  END IF;
  IF NOT (OLD.created_by IS NOT DISTINCT FROM c.me OR OLD.sent_by IS NOT DISTINCT FROM c.me
          OR (OLD.client_id IS NOT NULL AND public.can_access_client(OLD.client_id))) THEN
    RAISE EXCEPTION 'That proposal is the firm''s' USING ERRCODE = '42501';
  END IF;
  IF NEW.client_id IS DISTINCT FROM OLD.client_id
     AND (NEW.client_id IS NULL OR NOT public.can_access_client(NEW.client_id)) THEN
    RAISE EXCEPTION 'A contractor''s proposals are for clients they brought' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public._contractor_guard_proposal() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS tr_contractor_guard ON public.proposals;
CREATE TRIGGER tr_contractor_guard
  BEFORE INSERT OR UPDATE ON public.proposals
  FOR EACH ROW EXECUTE FUNCTION public._contractor_guard_proposal();

-- A QA remark. On a contractor's engagement they answer the reviewer and mark
-- a remark resolved or not; somebody else's words are not theirs to change.
CREATE OR REPLACE FUNCTION public._contractor_guard_qa_comment()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE c record;
BEGIN
  SELECT * INTO c FROM public._contractor_caller();
  IF NOT c.is_contractor OR OLD.user_id IS NOT DISTINCT FROM c.me THEN RETURN NEW; END IF;
  IF (to_jsonb(NEW) - ARRAY['resolved', 'resolved_at', 'row_version', 'row_by'])
     IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['resolved', 'resolved_at', 'row_version', 'row_by']) THEN
    RAISE EXCEPTION 'A reviewer''s remark is theirs to change; you can mark it resolved' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public._contractor_guard_qa_comment() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS tr_qa_contractor_guard ON public.qa_comments;
CREATE TRIGGER tr_qa_contractor_guard
  BEFORE UPDATE ON public.qa_comments
  FOR EACH ROW EXECUTE FUNCTION public._contractor_guard_qa_comment();




