-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-database-security-patch.sql ━━
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- PENTAL BYO SECURITY PATCH
-- ═══════════════════════════════════════════════════════════════════════════
-- Apply AFTER byo-database.sql. Safe to re-run (idempotent).
--
-- What this patch does:
--   1. Enables pgsodium + Vault (if not already on)
--   2. Creates Vault slots for Pental's two Ed25519 public keys + the
--      credentials AES key used by rpc_credentials_*
--   3. Creates an install-token mechanism so rpc_bootstrap_admin and
--      rpc_install_pental_keys cannot be called by just any anon holder
--   4. Defines _verify_pental_auth(p_auth), dual Ed25519 signature check
--      using pgsodium.crypto_sign_verify_detached
--   5. Migrates existing _credentials_key / _encryption_keys rows into Vault
--   6. Replaces every provision-secret-gated RPC with a dual-auth version
--      that prefers signed JWT but falls back to the old secret during the
--      rollout window
--   7. Removes rpc_export_all and rpc_set_bridge_password (replaced)
--   8. Adds per-table export RPCs for the migration flow
--   9. Revokes anon grants on destructive RPCs
--  10. Adds an audit log for sensitive RPC invocations
--
-- Safety notes:
--   - Every CREATE OR REPLACE preserves the function name and grants used by
--     Pental's server. Existing calls with p_secret continue to work.
--   - Every DROP FUNCTION is of something that no longer has a caller after
--     master-side patches are deployed.
--   - Vault reads go through _pental_pubkey_a() / _pental_pubkey_b() helpers
--     so the vault names can be changed in one place if needed.
-- ═══════════════════════════════════════════════════════════════════════════


-- ── 1. Extensions ──────────────────────────────────────────────────────────
-- pgsodium is deprecated on Supabase (April 2025+ projects don't have the
-- schema/extension available). _verify_pental_auth does not depend on it: since
-- 1825 it checks both Ed25519 signatures itself, in SQL (_ed25519_verify), so
-- signed calls work on every BYO project and nothing outside it is asked.
--
-- We still try to enable pgsodium below for backwards-compat with any old
-- function bodies that might reference it; if it's not available we just
-- skip silently. Vault works either way (Supabase committed to keeping that
-- API stable).
DO $$
BEGIN
  CREATE SCHEMA IF NOT EXISTS pgsodium;
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

DO $$
BEGIN
  CREATE EXTENSION IF NOT EXISTS pgsodium WITH SCHEMA pgsodium CASCADE;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'pgsodium not available (deprecated on Apr 2025+ Supabase projects). This is fine, _verify_pental_auth checks signatures in SQL.';
END $$;

-- 1803: Supabase Vault where it exists; on a firm's own Postgres the Pental
-- gateway provides vault.create_secret, vault.update_secret and
-- vault.decrypted_secrets under the same names, sealed with pgcrypto under a
-- key only the gateway holds. Neither present is a setup that cannot work.
DO $vault$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'supabase_vault') THEN
    CREATE EXTENSION IF NOT EXISTS supabase_vault WITH SCHEMA vault CASCADE;
  ELSIF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'vault' AND p.proname = 'create_secret') THEN
    RAISE EXCEPTION 'No vault: neither the Supabase Vault extension nor the Pental gateway''s vault is present. On Supabase, enable the Vault; on your own database, apply this file through the Pental gateway.';
  END IF;
END $vault$;


-- ── 2. Create Vault slots (placeholder values until setup wizard runs) ─────
-- vault.create_secret(value, name, description) creates once; duplicate
-- names raise unique_violation which we catch so this is re-runnable.
DO $$
BEGIN
  BEGIN PERFORM vault.create_secret('', 'pental_pubkey_a', 'Pental Ed25519 public key A (Vercel-side). Used by _verify_pental_auth.'); EXCEPTION WHEN unique_violation THEN NULL; END;
  BEGIN PERFORM vault.create_secret('', 'pental_pubkey_b', 'Pental Ed25519 public key B (Edge Function cosigner). Used by _verify_pental_auth.'); EXCEPTION WHEN unique_violation THEN NULL; END;
  BEGIN PERFORM vault.create_secret('', 'credentials_aes_key', 'AES symmetric key for rpc_credentials_* encryption. Migrated from _encryption_keys.'); EXCEPTION WHEN unique_violation THEN NULL; END;
  BEGIN PERFORM vault.create_secret('', 'install_token_hash', 'SHA-256 of the current install token. Single-use; cleared after rpc_install_pental_keys.'); EXCEPTION WHEN unique_violation THEN NULL; END;
  -- 1798: the key-repair token lives in a slot of its own, so it can plant
  -- missing keys and do nothing else. See rpc_reissue_install_token.
  BEGIN PERFORM vault.create_secret('', 'key_repair_token_hash', 'SHA-256 of a key-repair token and when it was issued. Fills empty Pental key slots only; ten minutes, single use.'); EXCEPTION WHEN unique_violation THEN NULL; END;
END $$;


-- ── 3. Audit log table ─────────────────────────────────────────────────────
-- Every call to a privileged RPC that accepts p_auth gets a row here. Gives
-- customers visibility into what Pental is doing on their BYO. Cheap (one
-- INSERT per sensitive call, no selects on hot paths).
CREATE TABLE IF NOT EXISTS public._pental_rpc_audit_log (
  id bigserial PRIMARY KEY,
  at timestamptz NOT NULL DEFAULT now(),
  op text NOT NULL,
  tenant_id uuid,
  nonce_prefix text,         -- first 8 hex chars of nonce (for correlation, not replay)
  auth_mode text NOT NULL,   -- 'signed' | 'provision_secret' | 'bootstrap' | 'install_token'
  result text NOT NULL,      -- 'ok' | 'rejected' | 'error'
  error_short text
);
CREATE INDEX IF NOT EXISTS _pental_rpc_audit_at_idx ON public._pental_rpc_audit_log (at DESC);
REVOKE ALL ON public._pental_rpc_audit_log FROM anon, authenticated;
GRANT SELECT ON public._pental_rpc_audit_log TO authenticated;  -- customer admins can read via RLS
ALTER TABLE public._pental_rpc_audit_log ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS _pental_rpc_audit_log_admin_read ON public._pental_rpc_audit_log;
CREATE POLICY _pental_rpc_audit_log_admin_read ON public._pental_rpc_audit_log
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true AND role IN ('admin','senior')
  ));


-- ── 4. Nonce replay-protection table ──────────────────────────────────────
-- Every signed p_auth carries a 32-byte random nonce. _verify_pental_auth
-- INSERTs the nonce into this table; duplicate inserts raise unique_violation
-- which we surface as "replay detected". Old nonces are pruned via a cleanup
-- function called from rpc_session_touch-style heartbeats.
CREATE TABLE IF NOT EXISTS public._pental_used_nonces (
  nonce text PRIMARY KEY,
  used_at timestamptz NOT NULL DEFAULT now(),
  op text NOT NULL
);
CREATE INDEX IF NOT EXISTS _pental_used_nonces_used_at_idx ON public._pental_used_nonces (used_at);
REVOKE ALL ON public._pental_used_nonces FROM anon, authenticated;


-- ── 5. Vault accessors (wrapped so we can swap the backend later) ─────────
-- These are SECURITY DEFINER and REVOKEd from anon/authenticated, so only
-- callable from inside other SECURITY DEFINER functions (their owner
-- implicitly has execute privilege).

CREATE OR REPLACE FUNCTION public._pental_pubkey_a() RETURNS bytea
LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public, vault, pg_temp AS $$
  SELECT decode(decrypted_secret, 'base64')
  FROM vault.decrypted_secrets
  WHERE name = 'pental_pubkey_a'
$$;

-- 1803: THE GATEWAY'S WORD. On a firm's own Postgres there is no http
-- extension to reach a verifier with; the Pental gateway in front of the
-- database verifies Pental's signatures and WebAuthn assertions itself and
-- says so in one request header, x-pental-attest, an HMAC over the exact
-- inputs under a secret it shares with this database (sealed in the vault as
-- pental_gateway_attest, which the clean never touches). The gateway strips
-- that header from every request it receives, so only it can write one. On
-- Supabase the secret does not exist and the header, whatever it says, is
-- ignored.
CREATE OR REPLACE FUNCTION public._pental_attest_secret() RETURNS text
LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public, vault, pg_temp AS $$
  SELECT NULLIF(decrypted_secret, '') FROM vault.decrypted_secrets WHERE name = 'pental_gateway_attest'
$$;
REVOKE EXECUTE ON FUNCTION public._pental_attest_secret() FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public._pental_attestation() RETURNS text
LANGUAGE sql STABLE SET search_path = public, pg_temp AS $$
  SELECT NULLIF(NULLIF(current_setting('request.headers', true), '')::jsonb ->> 'x-pental-attest', '')
$$;
-- Does the header say the gateway verified exactly these inputs?
CREATE OR REPLACE FUNCTION public._pental_attested(p_inputs text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public, extensions, vault, pg_temp AS $$
DECLARE v_secret text; v_given text;
BEGIN
  v_secret := public._pental_attest_secret();
  v_given := public._pental_attestation();
  IF v_secret IS NULL OR v_given IS NULL THEN RETURN NULL; END IF;
  RETURN v_given = encode(extensions.hmac(convert_to(p_inputs, 'UTF8'), convert_to(v_secret, 'UTF8'), 'sha256'), 'hex');
END $$;
REVOKE EXECUTE ON FUNCTION public._pental_attested(text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._pental_pubkey_b() RETURNS bytea
LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public, vault, pg_temp AS $$
  SELECT decode(decrypted_secret, 'base64')
  FROM vault.decrypted_secrets
  WHERE name = 'pental_pubkey_b'
$$;

CREATE OR REPLACE FUNCTION public._pental_install_token_hash() RETURNS text
LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public, vault, pg_temp AS $$
  SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'install_token_hash'
$$;

REVOKE EXECUTE ON FUNCTION public._pental_pubkey_a() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public._pental_pubkey_b() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public._pental_install_token_hash() FROM PUBLIC, anon, authenticated;


-- ═══════════════════════════════════════════════════════════════════════════
-- 1825: PENTAL'S SIGNATURES ARE CHECKED HERE, IN THE FIRM'S OWN DATABASE.
--
-- [stated] Arian: "if pental were breached, their data shouldnt be readable.
-- pental employees shouldnt be able to read their data."
--
-- Until now a signed call on a Supabase-hosted database was checked by sending
-- the envelope to a verifier Pental hosted (PENTAL_VERIFY_URL) and trusting its
-- yes or no, so whoever ran that verifier could approve any call. 1812 took the
-- same step for passkeys. Ed25519 (RFC 8032) is done here with `numeric`,
-- which holds the 255-bit numbers exactly: the key decoded and checked to be
-- on the curve, SHA-512 (built into PostgreSQL), S below the group order, and
-- R required to be exactly the encoding of [S]B - [k]A. Both scalar
-- multiplications run at once in extended twisted Edwards coordinates with the
-- complete addition law, so there is no special case to get wrong. About
-- 15 ms a check. Nothing is fetched from anywhere.
--
-- The same function checks a schema bundle against Pental's release key for
-- this database's own updater (at the end of this file).
--
-- Pure functions of their arguments: no table access, no SECURITY DEFINER,
-- and revoked from the API roles.
-- ═══════════════════════════════════════════════════════════════════════════

-- Little-endian bytes as a number (Ed25519 writes numbers least significant
-- byte first).
CREATE OR REPLACE FUNCTION public._ed_le(p bytea) RETURNS numeric
  LANGUAGE plpgsql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp AS $el$
DECLARE v numeric := 0; i int;
BEGIN
  FOR i IN REVERSE length(p) - 1 .. 0 LOOP v := v * 256 + get_byte(p, i); END LOOP;
  RETURN v;
END $el$;

-- A number in [0, 2^(8n)) as n little-endian bytes.
CREATE OR REPLACE FUNCTION public._ed_le_bytes(v numeric, n int) RETURNS bytea
  LANGUAGE plpgsql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp AS $eb$
DECLARE o bytea := decode(repeat('00', n), 'hex'); k numeric := v; i int;
BEGIN
  IF k < 0 THEN RAISE EXCEPTION 'negative'; END IF;
  FOR i IN 0 .. n - 1 LOOP o := set_byte(o, i, (k % 256)::int); k := div(k, 256); END LOOP;
  IF k <> 0 THEN RAISE EXCEPTION 'too large'; END IF;
  RETURN o;
END $eb$;

-- b^e mod p, p = 2^255 - 19, by square and multiply.
CREATE OR REPLACE FUNCTION public._ed_pow(b numeric, e numeric) RETURNS numeric
  LANGUAGE plpgsql IMMUTABLE STRICT SET search_path = pg_catalog, pg_temp AS $ep$
DECLARE
  p CONSTANT numeric := 57896044618658097711785492504343953926634992332820282019728792003956564819949;
  r numeric := 1; x numeric := b % p; k numeric := e;
BEGIN
  IF x < 0 THEN x := x + p; END IF;
  WHILE k > 0 LOOP
    IF k % 2 = 1 THEN r := r * x % p; END IF;
    x := x * x % p;
    k := div(k, 2);
  END LOOP;
  RETURN r;
END $ep$;

-- Is p_sig a valid Ed25519 signature (RFC 8032) of p_msg under the 32-byte
-- public key p_pub? Strict where RFC 8032 is strict: S must be below the group
-- order, the key must decode to a point on the curve (y below p, x present,
-- no negative zero), and R must be exactly the encoding of [S]B - [k]A, which
-- also refuses an R written in a non-canonical form. Anything malformed is
-- false, never an error.
CREATE OR REPLACE FUNCTION public._ed25519_verify(p_pub bytea, p_msg bytea, p_sig bytea) RETURNS boolean
  LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $ev$
DECLARE
  p    CONSTANT numeric := 57896044618658097711785492504343953926634992332820282019728792003956564819949;
  l    CONSTANT numeric := 7237005577332262213973186563042994240857116359379907606001950938285454250989;
  d    CONSTANT numeric := 37095705934669439343138083508754565189542113879843219016388785533085940283555;
  d2   CONSTANT numeric := 16295367250680780974490674513165176452449235426866156013048779062215315747161;
  sqm1 CONSTANT numeric := 19681161376707505956807079304988542015446066515923890162744021073123829784752;
  gx   CONSTANT numeric := 15112221349535400772501151409588531511454012693041857206046113283949847762202;
  gy   CONSTANT numeric := 46316835694926478169428394003475163141307993866256225615783033603165251855960;
  e8   CONSTANT numeric := 7237005577332262213973186563042994240829374041602535252466099000494570602493; -- (p - 5) / 8
  hi   CONSTANT numeric := 57896044618658097711785492504343953926634992332820282019728792003956564819968; -- 2^255
  ax numeric; ay numeric; xs int; yy numeric; u numeric; v numeric; v3 numeric; vx2 numeric;
  s numeric; k numeric; kb bytea;
  -- the three addends, cached as (Y+X, Y-X, 2Z, 2dT)
  c_ypx numeric[] := ARRAY[0, 0, 0]; c_ymx numeric[] := ARRAY[0, 0, 0];
  c_z2  numeric[] := ARRAY[0, 0, 0]; c_t2d numeric[] := ARRAY[0, 0, 0];
  -- the running point, extended coordinates (X:Y:Z:T), starting at the identity
  rx numeric := 0; ry numeric := 1; rz numeric := 1; rt numeric := 0;
  ta numeric; tb numeric; tc numeric; td numeric; te numeric; tf numeric; tg numeric; th numeric;
  i int; sel int; zi numeric; x numeric; y numeric;
BEGIN
  IF p_pub IS NULL OR p_msg IS NULL OR p_sig IS NULL
     OR octet_length(p_pub) <> 32 OR octet_length(p_sig) <> 64 THEN
    RETURN false;
  END IF;

  -- S, the second half of the signature, below the group order.
  s := public._ed_le(substring(p_sig FROM 33 FOR 32));
  IF s >= l THEN RETURN false; END IF;

  -- A, the public key: y and the sign of x (RFC 8032 5.1.3).
  xs := get_byte(p_pub, 31) >> 7;
  ay := public._ed_le(set_byte(p_pub, 31, get_byte(p_pub, 31) & 127));
  IF ay >= p THEN RETURN false; END IF;
  yy := ay * ay % p;
  u := yy - 1;
  v := (d * yy + 1) % p;
  v3 := v * v % p * v % p;
  ax := u * v3 % p * public._ed_pow(u * (v3 * v3 % p * v % p) % p, e8) % p;
  vx2 := v * (ax * ax % p) % p;
  IF (vx2 - u) % p = 0 THEN
    NULL;
  ELSIF (vx2 + u) % p = 0 THEN
    ax := ax * sqm1 % p;
  ELSE
    RETURN false;  -- not on the curve
  END IF;
  IF ax < 0 THEN ax := ax + p; END IF;
  IF ax = 0 AND xs = 1 THEN RETURN false; END IF;
  IF ax % 2 <> xs THEN ax := p - ax; END IF;

  -- k = SHA-512(R || A || M) mod l, and its bits, least significant first.
  k := public._ed_le(sha512(substring(p_sig FROM 1 FOR 32) || p_pub || p_msg)) % l;
  kb := public._ed_le_bytes(k, 32);

  -- Addend 1: B. Addend 2: -A (x negated). Addend 3: B - A.
  c_ypx[1] := gy + gx; c_ymx[1] := gy - gx; c_z2[1] := 2; c_t2d[1] := gx * gy % p * d2 % p;
  c_ypx[2] := ay - ax; c_ymx[2] := ay + ax; c_z2[2] := 2; c_t2d[2] := (p - ax) * ay % p * d2 % p;
  -- B + (-A), with the same unified addition the loop uses.
  ta := (gy - gx) * c_ymx[2] % p; tb := (gy + gx) * c_ypx[2] % p;
  tc := (gx * gy % p) * c_t2d[2] % p; td := c_z2[2];
  te := tb - ta; tf := td - tc; tg := td + tc; th := tb + ta;
  rx := te * tf % p; ry := tg * th % p; rt := te * th % p; rz := tf * tg % p;
  c_ypx[3] := ry + rx; c_ymx[3] := ry - rx; c_z2[3] := 2 * rz % p; c_t2d[3] := rt * d2 % p;
  rx := 0; ry := 1; rz := 1; rt := 0;

  -- [S]B + [k](-A), both scalars at once (Shamir's trick), most significant
  -- bit first. Both are below l < 2^253.
  FOR i IN REVERSE 252 .. 0 LOOP
    -- R := 2R (dbl-2008-hwcd, a = -1)
    ta := rx * rx % p; tb := ry * ry % p; tc := 2 * (rz * rz % p);
    te := ((rx + ry) * (rx + ry) - ta - tb) % p;
    tg := tb - ta; tf := tg - tc; th := -ta - tb;
    rx := te * tf % p; ry := tg * th % p; rt := te * th % p; rz := tf * tg % p;
    sel := get_bit(p_sig, 256 + i) + 2 * get_bit(kb, i);
    IF sel > 0 THEN
      -- R := R + addend (add-2008-hwcd-3, a = -1; complete on this curve)
      ta := (ry - rx) * c_ymx[sel] % p; tb := (ry + rx) * c_ypx[sel] % p;
      tc := rt * c_t2d[sel] % p; td := rz * c_z2[sel] % p;
      te := tb - ta; tf := td - tc; tg := td + tc; th := tb + ta;
      rx := te * tf % p; ry := tg * th % p; rt := te * th % p; rz := tf * tg % p;
    END IF;
  END LOOP;

  IF rz % p = 0 THEN RETURN false; END IF;
  zi := public._ed_pow(rz, p - 2);
  x := rx * zi % p; IF x < 0 THEN x := x + p; END IF;
  y := ry * zi % p; IF y < 0 THEN y := y + p; END IF;
  RETURN public._ed_le_bytes(y + (x % 2) * hi, 32) = substring(p_sig FROM 1 FOR 32);
END $ev$;

-- Standard base64 (as Node writes a signature) to bytes; anything else is NULL.
CREATE OR REPLACE FUNCTION public._ed_b64(p text) RETURNS bytea
  LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $e64$
BEGIN
  IF p IS NULL OR p !~ '^[A-Za-z0-9+/]*={0,2}$' THEN RETURN NULL; END IF;
  RETURN decode(p, 'base64');
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $e64$;

REVOKE ALL ON FUNCTION public._ed_le(bytea) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._ed_le_bytes(numeric, int) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._ed_pow(numeric, numeric) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._ed25519_verify(bytea, bytea, bytea) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._ed_b64(text) FROM PUBLIC, anon, authenticated;


-- ═══════════════════════════════════════════════════════════════════════════
-- 1832: A SIGNED CALL IS MADE FOR ONE FIRM, AND THIS DATABASE KNOWS WHICH.
--
-- Every envelope Pental signs names the firm it was made for (tenant_id), and
-- until now nothing compared that name with this database. An envelope made
-- for one firm was accepted by another inside its minute, because a nonce is
-- only remembered by the database that saw it: a firm able to see the calls
-- reaching its own database (its own server, or statement logging on its own
-- project) could replay one at another firm's database and read whatever
-- that call reads there.
--
-- The database now holds its firm's id and refuses an envelope made for any
-- other (_verify_pental_auth, below). It learns the id with no step for the
-- firm, and only from proof that Pental's provisioning of THIS database holds
-- (_pental_verify_binding):
--   1. a verified envelope that arrives with this database's own provisioning
--      secret, which every call from the portal's servers carries (the
--      assessment schedule makes one every fifteen minutes), or
--   2. a verified envelope inside the provisioning window, which the setup's
--      own check (rpc_debug_verify_auth, with the install token) makes.
-- Nothing else teaches it: not, in particular, its own record of the signed
-- calls it accepted, because while it is unbound another firm's envelopes are
-- accepted and recorded there too (a firm that had never called it could
-- otherwise write that record and be given the database).
-- The same proof moves the binding, for a database Pental's directory has
-- given to another firm; an envelope without it never moves it, and one that
-- fails its check leaves it as it was. A wipe (rpc_bulk_clean) and Start
-- fresh clear it, and a move carries it with the provisioning secret it goes
-- with (both live in _internal_secrets). Until a database has learned its id
-- it accepts an envelope for any firm, exactly as before.
-- ═══════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public._pental_bound_tenant() RETURNS uuid
LANGUAGE sql SECURITY DEFINER VOLATILE SET search_path = public, pg_catalog, pg_temp AS $btn$
  SELECT CASE WHEN value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN value::uuid END
    FROM public._internal_secrets WHERE key = 'PENTAL_TENANT_ID'
$btn$;
REVOKE ALL ON FUNCTION public._pental_bound_tenant() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._pental_set_bound_tenant(p_tenant uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $sbt$
BEGIN
  IF p_tenant IS NULL THEN
    DELETE FROM public._internal_secrets WHERE key = 'PENTAL_TENANT_ID';
  ELSE
    INSERT INTO public._internal_secrets (key, value) VALUES ('PENTAL_TENANT_ID', p_tenant::text)
      ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
  END IF;
END $sbt$;
REVOKE ALL ON FUNCTION public._pental_set_bound_tenant(uuid) FROM PUBLIC, anon, authenticated;

-- This database's provisioning secret, compared without a word to the audit
-- log: it is asked only to decide whether an envelope may bind, and a binding
-- writes its own row. Same comparison as _validate_provision_secret.
CREATE OR REPLACE FUNCTION public._pental_provision_secret_ok(p_secret text) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path = public, extensions, pg_catalog, pg_temp AS $pso$
DECLARE v_stored text; v_hashed text;
BEGIN
  IF p_secret IS NULL OR p_secret = '' THEN RETURN false; END IF;
  SELECT value INTO v_stored FROM public._internal_secrets WHERE key = 'PROVISION_SECRET';
  IF v_stored IS NULL OR v_stored = '' THEN RETURN false; END IF;
  v_hashed := encode(extensions.digest(p_secret, 'sha256'), 'hex');
  IF v_stored ~ '^[0-9a-f]{64}$' THEN RETURN v_hashed = v_stored; END IF;
  RETURN v_hashed = encode(extensions.digest(v_stored, 'sha256'), 'hex');
END $pso$;
REVOKE ALL ON FUNCTION public._pental_provision_secret_ok(text) FROM PUBLIC, anon, authenticated;


-- ── 6. _verify_pental_auth, the core of the new auth path ────────────────
-- Input shape (jsonb):
--   {
--     "tenant_id": "uuid",
--     "op":        "rpc_update_settings",
--     "nonce":     "64-hex",
--     "exp":       1234567890,   -- unix seconds
--     "sig_a":     "base64",
--     "sig_b":     "base64"
--   }
--
-- Behaviour:
--   - Returns true if BOTH signatures verify over the canonical payload
--     AND the op matches p_expected_op AND exp is in the future AND the
--     nonce has not been used before.
--   - INSERTs the nonce atomically on success so the same p_auth cannot be
--     replayed.
--   - Returns false (NOT exception) so RPCs can gracefully fall back to
--     provision_secret during rollout. Each RPC raises its own exception
--     when neither auth mode succeeds.
--   - Logs result to _pental_rpc_audit_log.
CREATE OR REPLACE FUNCTION public._verify_pental_auth(p_auth jsonb, p_expected_op text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault, pg_temp AS $$
DECLARE
  v_tenant_id text;
  v_op text;
  v_nonce text;
  v_exp bigint;
  v_sig_a text;
  v_sig_b text;
  v_pubkey_a bytea;
  v_pubkey_b bytea;
  v_canonical text;
  v_ok_a boolean;
  v_ok_b boolean;
  v_attested boolean;
  v_bound uuid;
BEGIN
  -- ── Structural validation ────────────────────────────────────────────
  IF p_auth IS NULL OR jsonb_typeof(p_auth) != 'object' THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES (p_expected_op, 'signed', 'rejected', 'auth not object');
    RETURN false;
  END IF;

  v_tenant_id := p_auth->>'tenant_id';
  v_op        := p_auth->>'op';
  v_nonce     := p_auth->>'nonce';
  v_exp       := COALESCE((p_auth->>'exp')::bigint, 0);
  v_sig_a     := p_auth->>'sig_a';
  v_sig_b     := p_auth->>'sig_b';

  IF v_op IS DISTINCT FROM p_expected_op THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES (p_expected_op, 'signed', 'rejected', 'op mismatch');
    RETURN false;
  END IF;

  -- UUID shape check
  IF v_tenant_id IS NULL OR v_tenant_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES (p_expected_op, 'signed', 'rejected', 'tenant_id shape');
    RETURN false;
  END IF;

  -- Nonce length check (hex 32+ chars)
  IF v_nonce IS NULL OR length(v_nonce) < 32 OR length(v_nonce) > 128 OR v_nonce !~ '^[0-9a-fA-F]+$' THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, 'signed', 'rejected', 'nonce shape');
    RETURN false;
  END IF;

  -- Expiry (with a small clock-skew tolerance)
  IF v_exp < extract(epoch from now())::bigint - 5 THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'expired');
    RETURN false;
  END IF;

  IF v_exp > extract(epoch from now())::bigint + 600 THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'exp too far');
    RETURN false;
  END IF;

  -- ── 1832: made for this firm? ────────────────────────────────────────
  -- Once this database knows its firm (see _pental_bound_tenant above), an
  -- envelope made for any other is refused, before any arithmetic and behind
  -- a gateway as much as without one. A database that has not learned its
  -- firm yet carries on as before.
  v_bound := public._pental_bound_tenant();
  IF v_bound IS NOT NULL AND v_bound <> v_tenant_id::uuid THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'tenant mismatch');
    RETURN false;
  END IF;

  -- ── Signature shape: obvious garbage is refused before any arithmetic ──
  IF v_sig_a IS NULL OR length(v_sig_a) < 16 OR length(v_sig_a) > 256
     OR v_sig_b IS NULL OR length(v_sig_b) < 16 OR length(v_sig_b) > 256 THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'sig shape');
    RETURN false;
  END IF;

  -- ── Load public keys from Vault ──────────────────────────────────────
  v_pubkey_a := public._pental_pubkey_a();
  v_pubkey_b := public._pental_pubkey_b();

  IF v_pubkey_a IS NULL OR octet_length(v_pubkey_a) != 32 THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'pubkey_a missing');
    RETURN false;
  END IF;
  IF v_pubkey_b IS NULL OR octet_length(v_pubkey_b) != 32 THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'pubkey_b missing');
    RETURN false;
  END IF;

  -- ── Canonical payload ────────────────────────────────────────────────
  -- Byte-for-byte must match the form Vercel and the cosigner Edge Function sign.
  v_canonical := v_tenant_id || '|' || v_op || '|' || v_nonce || '|' || v_exp::text;

  -- ── 1803: the gateway verified both signatures already? ──────────────
  -- NULL when there is no gateway secret (Supabase) or no header; true or
  -- false when there is one. A header that does not match is a rejection,
  -- never a fall-through to the check below.
  v_attested := public._pental_attested(v_canonical || '|' || v_sig_a || '|' || v_sig_b);
  IF v_attested IS FALSE THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'attestation bad');
    RETURN false;
  END IF;
  -- Behind a gateway, a call it did not attest is refused: the gateway checks
  -- every signed call it passes on, so one it did not attest did not come
  -- through it.
  IF v_attested IS NULL AND public._pental_attest_secret() IS NOT NULL THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'sig not attested by gateway');
    RETURN false;
  END IF;
  IF v_attested IS TRUE THEN
    v_ok_a := true;
    v_ok_b := true;
  ELSE
    -- 1825: both signatures are checked here, against the keys in this
    -- database's vault. Nothing of Pental's is asked whether they are good.
    v_ok_a := public._ed25519_verify(v_pubkey_a, convert_to(v_canonical, 'UTF8'), public._ed_b64(v_sig_a));
    v_ok_b := public._ed25519_verify(v_pubkey_b, convert_to(v_canonical, 'UTF8'), public._ed_b64(v_sig_b));
  END IF;

  IF NOT (v_ok_a AND v_ok_b) THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected',
              CASE WHEN NOT v_ok_a AND NOT v_ok_b THEN 'both sigs bad'
                   WHEN NOT v_ok_a THEN 'sig_a bad'
                   ELSE 'sig_b bad' END);
    RETURN false;
  END IF;

  -- ── Replay check: atomically insert nonce ────────────────────────────
  -- Only after both signatures verify, so failed verifies don't burn nonces.
  INSERT INTO public._pental_used_nonces (nonce, op)
    VALUES (v_nonce, v_op)
    ON CONFLICT (nonce) DO NOTHING;
  IF NOT FOUND THEN
    INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
      VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'rejected', 'nonce replay');
    RETURN false;
  END IF;

  -- Opportunistic self-pruning. Tokens expire in ~10 minutes, so any nonce
  -- older than 24h can never be replayed and is pure bloat. There is no
  -- cross-database cron reaching BYO databases, so instead of relying on an
  -- external sweep we prune inline on ~1% of successful signed calls. The
  -- used_at index keeps this cheap, and 1% sampling keeps average latency
  -- negligible while guaranteeing the table stays bounded on any active DB.
  IF random() < 0.01 THEN
    DELETE FROM public._pental_used_nonces WHERE used_at < now() - interval '24 hours';
    -- Same rationale for the RPC audit log, but keep 90 days for forensic
    -- value (failed-auth patterns, Vercel-compromise detection) rather than
    -- pruning aggressively. Still self-bounding on any active database.
    DELETE FROM public._pental_rpc_audit_log WHERE at < now() - interval '90 days';
  END IF;

  -- ── Success ──────────────────────────────────────────────────────────
  INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result)
    VALUES (p_expected_op, v_tenant_id::uuid, substring(v_nonce, 1, 8), 'signed', 'ok');

  RETURN true;
END;
$$;

REVOKE EXECUTE ON FUNCTION public._verify_pental_auth(jsonb, text) FROM PUBLIC, anon, authenticated;

-- 1832: check an envelope, binding this database to the envelope's firm when
-- the caller holds the proof (this database's provisioning secret, or the
-- provisioning window, which the caller has checked and says so with
-- p_provisioning) and the binding is not already that firm. The binding is
-- put in place before the check so the check reads it, and put back as it was
-- when the check fails: an envelope that is refused never moves it. Without
-- the proof this is _verify_pental_auth and nothing more. Asked only when the
-- binding differs, so the usual call (bound, and to this firm) pays one read.
--
-- After review: two calls binding at once take turns (an advisory lock held to
-- the end of the call), and the one that waited reads the binding again, so a
-- refused envelope puts back what is there now and never undoes a binding
-- another call has just made. A binding the database will not write just now
-- (a guard on _internal_secrets) leaves the call checked without binding
-- rather than failing it.
CREATE OR REPLACE FUNCTION public._pental_verify_binding(
  p_auth jsonb, p_expected_op text, p_secret text, p_provisioning boolean DEFAULT false
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pvb$
DECLARE v_tenant uuid; v_prev uuid; v_ok boolean;
BEGIN
  IF p_auth IS NOT NULL AND jsonb_typeof(p_auth) = 'object'
     AND COALESCE(p_auth->>'tenant_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_tenant := (p_auth->>'tenant_id')::uuid;
    v_prev := public._pental_bound_tenant();
    IF v_prev IS DISTINCT FROM v_tenant
       AND (p_provisioning IS TRUE OR public._pental_provision_secret_ok(p_secret)) THEN
      PERFORM pg_advisory_xact_lock(hashtext('pental.tenant_binding'));
      v_prev := public._pental_bound_tenant();
      IF v_prev IS DISTINCT FROM v_tenant THEN
        BEGIN
          PERFORM public._pental_set_bound_tenant(v_tenant);
        EXCEPTION WHEN OTHERS THEN
          RETURN COALESCE(public._verify_pental_auth(p_auth, p_expected_op), false);
        END;
        v_ok := COALESCE(public._verify_pental_auth(p_auth, p_expected_op), false);
        IF v_ok THEN
          INSERT INTO public._pental_rpc_audit_log (op, tenant_id, nonce_prefix, auth_mode, result, error_short)
            VALUES ('tenant_binding', v_tenant, substring(p_auth->>'nonce', 1, 8), 'signed', 'ok',
                    CASE WHEN v_prev IS NULL THEN 'bound to this firm' ELSE 'bound again, was ' || v_prev::text END);
        ELSE
          -- Not guarded: if this could fail, the call fails, and the whole
          -- transaction (the tentative binding with it) is undone.
          PERFORM public._pental_set_bound_tenant(v_prev);
        END IF;
        RETURN v_ok;
      END IF;
    END IF;
  END IF;
  RETURN COALESCE(public._verify_pental_auth(p_auth, p_expected_op), false);
END $pvb$;
REVOKE ALL ON FUNCTION public._pental_verify_binding(jsonb, text, text, boolean) FROM PUBLIC, anon, authenticated;


-- ── 7. Helper: "authorise this op", tries signed, then secret ────────────
-- Returns 'signed' | 'provision_secret' | NULL. Every privileged RPC begins
-- with: SELECT public._pental_authorise(p_auth, p_secret, 'op_name') INTO v_mode;
-- IF v_mode IS NULL THEN RAISE EXCEPTION 'Unauthorised'; END IF;
--
-- IMPORTANT: this 3-arg signature is intentionally NOT created here. It used
-- to live at this location, but section 14 (later in this file) creates a
-- 4-arg variant `(jsonb, text, text, boolean)` with the 4th arg defaulted to
-- false. PostgreSQL cannot disambiguate a 3-arg call between a real 3-arg
-- signature and a 4-arg-with-default signature, so installing both makes
-- every privileged RPC fail with `function ... is not unique`. The 4-arg
-- form alone serves both call patterns: existing 3-arg call sites resolve
-- to it via the default, and stricter call sites that need user_jwt
-- enforcement pass true explicitly.
DROP FUNCTION IF EXISTS public._pental_authorise(jsonb, text, text);


-- ── 8. Nonce cleanup (daily) ──────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public._pental_cleanup_nonces() RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
  DELETE FROM public._pental_used_nonces WHERE used_at < now() - interval '24 hours';
$$;
REVOKE EXECUTE ON FUNCTION public._pental_cleanup_nonces() FROM PUBLIC, anon, authenticated;


-- ═══════════════════════════════════════════════════════════════════════════
-- 9. INSTALL TOKEN FLOW
-- ═══════════════════════════════════════════════════════════════════════════
-- rpc_bulk_clean already emits a provision_secret to master. We now ALSO
-- emit a single-use install_token that master presents once to
-- rpc_install_pental_keys() together with the two Ed25519 public keys.
-- After that, the install_token is consumed (hash cleared from Vault) and
-- the provision_secret becomes the backward-compat fallback only.
--
-- Flow:
--   1. Customer runs byo-database.sql + this patch in their Supabase SQL Editor
--   2. Customer pastes URL + publishable key into Pental wizard
--   3. Pental calls rpc_bulk_clean() → gets provision_secret + install_token
--   4. Pental calls rpc_install_pental_keys(install_token, pubkey_a, pubkey_b)
--      → install_token is single-use, future calls with it fail
--   5. From then on, Pental signs every privileged RPC

CREATE OR REPLACE FUNCTION public.rpc_install_pental_keys(
  p_install_token text,
  p_pubkey_a_b64  text,
  p_pubkey_b_b64  text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault AS $$
DECLARE
  v_expected_hash text;
  v_provided_hash text;
  v_pubkey_a_slot uuid;
  v_pubkey_b_slot uuid;
  v_install_slot  uuid;
BEGIN
  -- ── Single-use gate ──────────────────────────────────────────────────
  v_expected_hash := public._pental_install_token_hash();
  IF v_expected_hash IS NULL OR v_expected_hash = '' THEN
    RETURN jsonb_build_object('error', 'Install token already consumed or not provisioned. Re-run rpc_bulk_clean to reset.');
  END IF;

  IF p_install_token IS NULL OR length(p_install_token) < 32 THEN
    RETURN jsonb_build_object('error', 'Invalid install token');
  END IF;
  v_provided_hash := encode(extensions.digest(p_install_token, 'sha256'), 'hex');
  IF v_provided_hash IS DISTINCT FROM v_expected_hash THEN
    RETURN jsonb_build_object('error', 'Invalid install token');
  END IF;

  -- ── Validate public key shapes (Ed25519 raw pubkey is 32 bytes) ──────
  BEGIN
    IF octet_length(decode(p_pubkey_a_b64, 'base64')) != 32 THEN
      RETURN jsonb_build_object('error', 'pubkey_a must be 32-byte Ed25519 public key');
    END IF;
    IF octet_length(decode(p_pubkey_b_b64, 'base64')) != 32 THEN
      RETURN jsonb_build_object('error', 'pubkey_b must be 32-byte Ed25519 public key');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', 'pubkey decode failed');
  END;

  -- ── Update Vault slots ───────────────────────────────────────────────
  SELECT id INTO v_pubkey_a_slot FROM vault.decrypted_secrets WHERE name = 'pental_pubkey_a';
  SELECT id INTO v_pubkey_b_slot FROM vault.decrypted_secrets WHERE name = 'pental_pubkey_b';
  SELECT id INTO v_install_slot  FROM vault.decrypted_secrets WHERE name = 'install_token_hash';

  IF v_pubkey_a_slot IS NULL OR v_pubkey_b_slot IS NULL OR v_install_slot IS NULL THEN
    RETURN jsonb_build_object('error', 'Vault slots missing, patch not fully applied');
  END IF;

  PERFORM vault.update_secret(v_pubkey_a_slot, p_pubkey_a_b64);
  PERFORM vault.update_secret(v_pubkey_b_slot, p_pubkey_b_b64);

  -- Consume the install token. Future calls fail until next rpc_bulk_clean.
  PERFORM vault.update_secret(v_install_slot, '');

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Install token path: anon is fine because the token itself is the secret.
-- After consumption, subsequent anon calls fail with "already consumed".
GRANT EXECUTE ON FUNCTION public.rpc_install_pental_keys(text, text, text) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 10. REPLACE rpc_bulk_clean TO EMIT install_token AND USE ADVISORY LOCK
-- ═══════════════════════════════════════════════════════════════════════════
-- Changes from original:
--   - pg_advisory_xact_lock prevents concurrent wipes
--   - Generates a fresh install_token in addition to provision_secret
--   - install_token hash goes to Vault (single-use)
--   - Returns both values; Pental stores provision_secret on master, uses
--     install_token once to call rpc_install_pental_keys

DROP FUNCTION IF EXISTS public.rpc_bulk_clean(text);
DROP FUNCTION IF EXISTS public.rpc_bulk_clean();
DROP FUNCTION IF EXISTS public.rpc_bulk_clean(jsonb);
DROP FUNCTION IF EXISTS public.rpc_bulk_clean(text, jsonb);

CREATE OR REPLACE FUNCTION public.rpc_bulk_clean(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault AS $$
DECLARE
  v_new_secret text;
  v_install_token text;
  v_install_slot uuid;
  v_mode text;
BEGIN
  -- Serialise concurrent clean attempts. A double-click on the setup wizard
  -- previously could wipe the DB twice, creating two provision_secrets and
  -- leaving master out of sync. Advisory lock scoped to this operation.
  PERFORM pg_advisory_xact_lock(hashtext('rpc_bulk_clean'));

  -- Bootstrap path: if no PROVISION_SECRET exists yet, permit empty auth.
  -- This is the ONE window where anon can call us without gating; it's gated
  -- by the fact that a freshly-run byo-database.sql has no data to protect.
  IF NOT public._validate_provision_secret_or_bootstrap(COALESCE(p_secret, '')) THEN
    -- Non-bootstrap path: try signed auth first, then provision_secret
    v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_bulk_clean');
    IF v_mode IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Invalid provision secret');
    END IF;
  END IF;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  DELETE FROM payment_events WHERE true; DELETE FROM qa_comments WHERE true;
  DELETE FROM assessment_files WHERE true; DELETE FROM assessment_comments WHERE true;
  DELETE FROM timeline_events WHERE true; DELETE FROM tickets WHERE true;
  DELETE FROM feedback WHERE true; DELETE FROM email_notifications WHERE true;
  DELETE FROM contractor_payments WHERE true; DELETE FROM meeting_attendees WHERE true;
  DELETE FROM meetings WHERE true;
  DELETE FROM kb_entries WHERE true; PERFORM set_config('pental.wiping', 'on', true); DELETE FROM invoices WHERE true;
  DELETE FROM proposals WHERE true; DELETE FROM findings WHERE true;
  DELETE FROM assessments WHERE true; DELETE FROM login_codes WHERE true;
  DELETE FROM _internal_secrets WHERE key NOT IN ('PROVISION_SECRET', 'WEBAUTHN_VERIFY_URL', 'PENTAL_VERIFY_URL');
  DELETE FROM _encryption_keys WHERE true;
  DELETE FROM _credentials_key WHERE true;
  UPDATE profiles SET client_id = NULL WHERE client_id IS NOT NULL;
  DELETE FROM auth.identities WHERE true; DELETE FROM auth.sessions WHERE true;
  DELETE FROM auth.refresh_tokens WHERE true; DELETE FROM auth.mfa_factors WHERE true;
  DELETE FROM auth.users WHERE true;
  DELETE FROM clients WHERE true; DELETE FROM profiles WHERE true; DELETE FROM settings WHERE true;
  DELETE FROM _internal_secrets WHERE key = 'PROVISION_SECRET';
  DELETE FROM _pental_used_nonces WHERE true;

  -- Generate fresh secrets
  v_new_secret    := encode(extensions.gen_random_bytes(32), 'hex');
  v_install_token := encode(extensions.gen_random_bytes(32), 'hex');

  INSERT INTO _internal_secrets (key, value) VALUES (
    'PROVISION_SECRET',
    encode(extensions.digest(v_new_secret, 'sha256'), 'hex')
  );
  INSERT INTO _internal_secrets (key, value) VALUES (
    'CRON_SECRET',
    encode(extensions.gen_random_bytes(32), 'hex')
  ) ON CONFLICT (key) DO NOTHING;

  -- Store install_token hash in Vault (single-use, consumed by rpc_install_pental_keys)
  SELECT id INTO v_install_slot FROM vault.decrypted_secrets WHERE name = 'install_token_hash';
  IF v_install_slot IS NULL THEN
    PERFORM vault.create_secret(
      encode(extensions.digest(v_install_token, 'sha256'), 'hex'),
      'install_token_hash',
      'SHA-256 of the current install token. Single-use; cleared after rpc_install_pental_keys.'
    );
  ELSE
    PERFORM vault.update_secret(v_install_slot, encode(extensions.digest(v_install_token, 'sha256'), 'hex'));
  END IF;

  -- Also reset the pubkey slots so a re-install is required after a clean.
  DECLARE v_reset_id uuid; BEGIN FOR v_reset_id IN SELECT id FROM vault.decrypted_secrets WHERE name IN ('pental_pubkey_a', 'pental_pubkey_b') LOOP PERFORM vault.update_secret(v_reset_id, ''); END LOOP; END;

  INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result)
    VALUES ('rpc_bulk_clean', 'provision_secret', 'ok');

  RETURN jsonb_build_object(
    'success', true,
    'provision_secret', v_new_secret,
    'install_token',    v_install_token
  );
END;
$$;

-- Keep anon grant during bootstrap; bootstrap-mode is self-gating (no data to wipe).
-- Post-bootstrap, the secret/auth gate does the work.
GRANT EXECUTE ON FUNCTION public.rpc_bulk_clean(text, jsonb) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 11. CONVERT EACH PROVISION-SECRET-GATED RPC TO DUAL-AUTH
-- ═══════════════════════════════════════════════════════════════════════════
-- Pattern: replace IF NOT _validate_provision_secret THEN RAISE with
-- IF _pental_authorise(p_auth, p_secret, 'op_name') IS NULL THEN RAISE.
-- New signature is (..., p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL).

-- ── rpc_get_smtp_config ──
DROP FUNCTION IF EXISTS public.rpc_get_smtp_config(text);
DROP FUNCTION IF EXISTS public.rpc_get_smtp_config(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_get_smtp_config(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_s RECORD; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_get_smtp_config');
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from_name, smtp_from_email,
         company_name, email_enabled, email_templates, accent_color, company_email,
         -- 1363: the connection travels with the rest. Five definitions of
         -- this function live in this file and Postgres keeps the last; making
         -- them agree means re-running the setup cannot change whether a
         -- connected mailbox is visible to the mailer.
         smtp_oauth_provider, smtp_oauth_user, smtp_oauth_refresh, smtp_oauth_refresh_enc
         password_login_enabled
    INTO v_s FROM public.settings LIMIT 1;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  RETURN jsonb_build_object(
    'smtp_host', v_s.smtp_host, 'smtp_port', v_s.smtp_port, 'smtp_user', v_s.smtp_user,
    'smtp_pass', v_s.smtp_pass, 'smtp_from_name', v_s.smtp_from_name,
    'smtp_from_email', v_s.smtp_from_email, 'company_name', v_s.company_name,
    'email_enabled', v_s.email_enabled, 'email_templates', v_s.email_templates,
    'accent_color', v_s.accent_color, 'company_email', v_s.company_email,
    'smtp_oauth_provider', v_s.smtp_oauth_provider,
    'smtp_oauth_user', v_s.smtp_oauth_user,
    'smtp_oauth_refresh', COALESCE(NULLIF(v_s.smtp_oauth_refresh, ''), public._settings_decrypt(v_s.smtp_oauth_refresh_enc)),
    -- The new-user invite path reads this to choose between a sign-in code
    -- and a create-password link. Omitting it made that check silently false.
    'password_login_enabled', COALESCE(v_s.password_login_enabled, false)
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_get_smtp_config(text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_update_settings (also fixes dynamic SQL smell with jsonb_populate_record) ──
-- Dropping dynamic SQL entirely: jsonb_populate_record safely coerces fields
-- against the table's column types, and we build an UPDATE that only touches
-- allowed columns. No EXECUTE, no quote_literal games.
DROP FUNCTION IF EXISTS public.rpc_update_settings(jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_update_settings(jsonb, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_update_settings(
  p_data jsonb,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_mode text;
  v_id uuid;
  v_filtered jsonb := '{}'::jsonb;
  v_key text;
  v_allowed text[] := ARRAY[
    'company_name','company_email','company_phone','company_address','company_number',
    'company_ending','company_website','accent_color','theme_mode','logo_url','logo_url_light','pdf_logo_variant','email_logo_variant','password_login_enabled','font_display','font_body','font_mono','pdf_font_body','pdf_font_heading','email_font','favicon_data',
    'portal_title','login_title','login_subtitle','login_support_email','login_button_text',
    'login_custom_text','login_show_logo','login_show_company_name','login_show_title','sso_google_enabled','sso_microsoft_enabled',
    'smtp_host','smtp_port','smtp_user','smtp_pass','smtp_oauth_provider','smtp_oauth_user','smtp_oauth_refresh','smtp_from_name','smtp_from_email',
    'email_enabled','severity_colors','severity_style','notification_color','toast_success_color',
    'google_api_key','currency_code','currency_symbol','day_rate','vat_rate','vat_number',
    'assessment_types','session_timeout_minutes','theme_dark','theme_light',
    'stripe_enabled','stripe_publishable_key','stripe_secret_key','stripe_webhook_secret',
    'stripe_success_url','ai_provider','ai_api_key','meeting_integration','contact_integration',
    'updated_at','pdf_templates','ai_custom_url','ai_custom_model','ai_custom_format',
    'ai_custom_headers','ai_custom_max_tokens','ai_ollama_num_ctx','logo_data','color_bg','color_border',
    'color_card','color_muted','color_primary','color_secondary','color_text','color_hover',
    'teams_tenant_id','teams_client_id','teams_client_secret','teams_user_email',
    'email_templates','loa_signatory_name','loa_signatory_title','loa_signature_data',
    'session_timeout_action','session_signout_minutes','session_refresh_buffer_minutes',
    'show_tester_teams','show_tester_slack','google_review_url','feedback_mode',
    'loa_visibility','sig_name','sig_title','sig_email','sig_phone','sig_teams','sig_slack',
    'sig_html','email_signature_enabled','notify_test_started','notify_test_ended','notify_critical_finding',
    'notify_proposal_sent','notify_invoice_sent','notify_tester_assigned',
    'notify_credentials_submitted','notify_comment_reply','notify_report_delivered',
    'notify_new_sign_in','notify_new_device_sign_in','notify_mfa_changed',
    'notify_role_changed','notify_user_created','notify_session_revoked',
    'exec_summary_prompt','finding_desc_prompt','finding_rem_prompt',
    'retest_summary_prompt','proposals_enabled','invoices_enabled','feedback_enabled',
    'meet_calendar_enabled','meetings_enabled','contacts_enabled','dashboard_enabled',
    'dashboard_layouts','proposal_multi_year_enabled','proposal_subscription_enabled',
    'proposal_custom_titles','auto_start_enabled','auto_start_time','auto_complete_enabled',
    'auto_complete_time','automation_timezone','automation_workdays_only',
    'auto_credentials_enabled','auto_credentials_time','auto_credentials_days',
    'self_scan_default_hour','mail_outbox_enabled',
    'invoice_automation','invoice_auto_send_days','filename_templates'
  ];
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_update_settings');
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret'; END IF;

  -- Filter to allowed keys only
  FOR v_key IN SELECT jsonb_object_keys(p_data) LOOP
    IF v_key = ANY(v_allowed) THEN
      v_filtered := v_filtered || jsonb_build_object(v_key, p_data->v_key);
    END IF;
  END LOOP;

  IF v_filtered = '{}'::jsonb THEN RETURN false; END IF;

  SELECT id INTO v_id FROM public.settings LIMIT 1;
  IF v_id IS NULL THEN RETURN false; END IF;

  -- Single UPDATE using jsonb_populate_record for type coercion. This replaces
  -- the previous dynamic-SQL approach entirely. The table's own column types
  -- do the validation; missing keys leave those columns unchanged via COALESCE.
  --
  -- Technique: update to (merged record).* selected out of the existing row,
  -- where merged = jsonb_populate_record(existing_row, v_filtered).
  UPDATE public.settings AS s SET
    company_name = COALESCE((v_filtered->>'company_name')::text, s.company_name),
    company_email = COALESCE((v_filtered->>'company_email')::text, s.company_email),
    company_phone = COALESCE((v_filtered->>'company_phone')::text, s.company_phone),
    company_address = COALESCE((v_filtered->>'company_address')::text, s.company_address),
    company_number = COALESCE((v_filtered->>'company_number')::text, s.company_number),
    company_ending = COALESCE((v_filtered->>'company_ending')::text, s.company_ending),
    company_website = COALESCE((v_filtered->>'company_website')::text, s.company_website),
    accent_color = COALESCE((v_filtered->>'accent_color')::text, s.accent_color),
    theme_mode = COALESCE((v_filtered->>'theme_mode')::text, s.theme_mode),
    logo_url = COALESCE((v_filtered->>'logo_url')::text, s.logo_url),
    logo_url_light = COALESCE((v_filtered->>'logo_url_light')::text, s.logo_url_light),
    password_login_enabled = COALESCE((v_filtered->>'password_login_enabled')::boolean, s.password_login_enabled),
    font_display = COALESCE((v_filtered->>'font_display')::text, s.font_display),
    font_body = COALESCE((v_filtered->>'font_body')::text, s.font_body),
    font_mono = COALESCE((v_filtered->>'font_mono')::text, s.font_mono),
    pdf_font_body = COALESCE((v_filtered->>'pdf_font_body')::text, s.pdf_font_body),
    pdf_font_heading = COALESCE((v_filtered->>'pdf_font_heading')::text, s.pdf_font_heading),
    email_font = COALESCE((v_filtered->>'email_font')::text, s.email_font),
    pdf_logo_variant = COALESCE((v_filtered->>'pdf_logo_variant')::text, s.pdf_logo_variant),
    email_logo_variant = COALESCE((v_filtered->>'email_logo_variant')::text, s.email_logo_variant),
    favicon_data = COALESCE((v_filtered->>'favicon_data')::text, s.favicon_data),
    portal_title = COALESCE((v_filtered->>'portal_title')::text, s.portal_title),
    login_title = COALESCE((v_filtered->>'login_title')::text, s.login_title),
    login_subtitle = COALESCE((v_filtered->>'login_subtitle')::text, s.login_subtitle),
    login_support_email = COALESCE((v_filtered->>'login_support_email')::text, s.login_support_email),
    login_button_text = COALESCE((v_filtered->>'login_button_text')::text, s.login_button_text),
    login_custom_text = COALESCE((v_filtered->>'login_custom_text')::text, s.login_custom_text),
    login_show_logo = COALESCE((v_filtered->>'login_show_logo')::boolean, s.login_show_logo),
    login_show_company_name = COALESCE((v_filtered->>'login_show_company_name')::boolean, s.login_show_company_name),
    login_show_title = COALESCE((v_filtered->>'login_show_title')::boolean, s.login_show_title),
    sso_google_enabled = COALESCE((v_filtered->>'sso_google_enabled')::boolean, s.sso_google_enabled),
    sso_microsoft_enabled = COALESCE((v_filtered->>'sso_microsoft_enabled')::boolean, s.sso_microsoft_enabled),
    -- 1522: white-label SSO. The IDs and the directory hint are ordinary
    -- settings. The two SECRETS are written here too and the encrypt trigger
    -- moves each one into its _enc column on the way in, so the plaintext
    -- column is empty by the time the row is committed. An empty string means
    -- "clear it", which is how a firm turns white-label SSO back off; COALESCE
    -- alone would make that impossible.
    sso_google_client_id = COALESCE((v_filtered->>'sso_google_client_id')::text, s.sso_google_client_id),
    sso_ms_client_id = COALESCE((v_filtered->>'sso_ms_client_id')::text, s.sso_ms_client_id),
    sso_ms_tenant = COALESCE((v_filtered->>'sso_ms_tenant')::text, s.sso_ms_tenant),
    sso_google_client_secret = CASE WHEN v_filtered ? 'sso_google_client_secret'
      THEN NULLIF(v_filtered->>'sso_google_client_secret', '') ELSE s.sso_google_client_secret END,
    sso_google_client_secret_enc = CASE WHEN v_filtered ? 'sso_google_client_secret' AND NULLIF(v_filtered->>'sso_google_client_secret', '') IS NULL
      THEN NULL ELSE s.sso_google_client_secret_enc END,
    sso_ms_client_secret = CASE WHEN v_filtered ? 'sso_ms_client_secret'
      THEN NULLIF(v_filtered->>'sso_ms_client_secret', '') ELSE s.sso_ms_client_secret END,
    sso_ms_client_secret_enc = CASE WHEN v_filtered ? 'sso_ms_client_secret' AND NULLIF(v_filtered->>'sso_ms_client_secret', '') IS NULL
      THEN NULL ELSE s.sso_ms_client_secret_enc END,
    smtp_host = COALESCE((v_filtered->>'smtp_host')::text, s.smtp_host),
    smtp_port = COALESCE((v_filtered->>'smtp_port')::integer, s.smtp_port),
    smtp_user = COALESCE((v_filtered->>'smtp_user')::text, s.smtp_user),
    smtp_pass = COALESCE((v_filtered->>'smtp_pass')::text, s.smtp_pass),
    smtp_from_name = COALESCE((v_filtered->>'smtp_from_name')::text, s.smtp_from_name),
    smtp_from_email = COALESCE((v_filtered->>'smtp_from_email')::text, s.smtp_from_email),
    email_enabled = COALESCE((v_filtered->>'email_enabled')::boolean, s.email_enabled),
    severity_colors = COALESCE((v_filtered->'severity_colors')::jsonb, s.severity_colors),
    severity_style  = COALESCE((v_filtered->'severity_style')::jsonb, s.severity_style),
    notification_color = COALESCE((v_filtered->>'notification_color')::text, s.notification_color),
    toast_success_color = COALESCE((v_filtered->>'toast_success_color')::text, s.toast_success_color),
    google_api_key = COALESCE((v_filtered->>'google_api_key')::text, s.google_api_key),
    currency_code = COALESCE((v_filtered->>'currency_code')::text, s.currency_code),
    currency_symbol = COALESCE((v_filtered->>'currency_symbol')::text, s.currency_symbol),
    day_rate = COALESCE((v_filtered->>'day_rate')::integer, s.day_rate),
    vat_rate = COALESCE((v_filtered->>'vat_rate')::numeric, s.vat_rate),
    vat_number = COALESCE((v_filtered->>'vat_number')::text, s.vat_number),
    assessment_types = COALESCE((v_filtered->'assessment_types')::jsonb, s.assessment_types),
    session_timeout_minutes = COALESCE((v_filtered->>'session_timeout_minutes')::integer, s.session_timeout_minutes),
    theme_dark = COALESCE((v_filtered->'theme_dark')::jsonb, s.theme_dark),
    theme_light = COALESCE((v_filtered->'theme_light')::jsonb, s.theme_light),
    stripe_enabled = COALESCE((v_filtered->>'stripe_enabled')::boolean, s.stripe_enabled),
    stripe_publishable_key = COALESCE((v_filtered->>'stripe_publishable_key')::text, s.stripe_publishable_key),
    stripe_secret_key = COALESCE((v_filtered->>'stripe_secret_key')::text, s.stripe_secret_key),
    stripe_webhook_secret = COALESCE((v_filtered->>'stripe_webhook_secret')::text, s.stripe_webhook_secret),
    stripe_success_url = COALESCE((v_filtered->>'stripe_success_url')::text, s.stripe_success_url),
    ai_provider = COALESCE((v_filtered->>'ai_provider')::text, s.ai_provider),
    ai_api_key = COALESCE((v_filtered->>'ai_api_key')::text, s.ai_api_key),
    meeting_integration = COALESCE((v_filtered->>'meeting_integration')::text, s.meeting_integration),
    contact_integration = COALESCE((v_filtered->>'contact_integration')::text, s.contact_integration),
    pdf_templates = COALESCE((v_filtered->'pdf_templates')::jsonb, s.pdf_templates),
    ai_custom_url = COALESCE((v_filtered->>'ai_custom_url')::text, s.ai_custom_url),
    ai_custom_model = COALESCE((v_filtered->>'ai_custom_model')::text, s.ai_custom_model),
    ai_custom_format = COALESCE((v_filtered->>'ai_custom_format')::text, s.ai_custom_format),
    -- 1832: a text column, read as text (jsonb beside text is refused by COALESCE).
    ai_custom_headers = COALESCE((v_filtered->>'ai_custom_headers')::text, s.ai_custom_headers),
    ai_custom_max_tokens = COALESCE((v_filtered->>'ai_custom_max_tokens')::integer, s.ai_custom_max_tokens),
    ai_ollama_num_ctx = COALESCE((v_filtered->>'ai_ollama_num_ctx')::integer, s.ai_ollama_num_ctx),
    logo_data = COALESCE((v_filtered->>'logo_data')::text, s.logo_data),
    color_bg = COALESCE((v_filtered->>'color_bg')::varchar, s.color_bg),
    color_border = COALESCE((v_filtered->>'color_border')::varchar, s.color_border),
    color_card = COALESCE((v_filtered->>'color_card')::varchar, s.color_card),
    color_muted = COALESCE((v_filtered->>'color_muted')::varchar, s.color_muted),
    color_primary = COALESCE((v_filtered->>'color_primary')::varchar, s.color_primary),
    color_secondary = COALESCE((v_filtered->>'color_secondary')::varchar, s.color_secondary),
    color_text = COALESCE((v_filtered->>'color_text')::varchar, s.color_text),
    color_hover = COALESCE((v_filtered->>'color_hover')::text, s.color_hover),
    teams_tenant_id = COALESCE((v_filtered->>'teams_tenant_id')::text, s.teams_tenant_id),
