-- ── rpc_profile_lookup ──
DROP FUNCTION IF EXISTS public.rpc_profile_lookup(text, text);
DROP FUNCTION IF EXISTS public.rpc_profile_lookup(text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_profile_lookup(p_email text, p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_row RECORD; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_profile_lookup');
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT id, name, role, active, email INTO v_row FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'id', v_row.id, 'name', v_row.name, 'email', v_row.email);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_profile_lookup(text, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_get_admin_email ──
DROP FUNCTION IF EXISTS public.rpc_get_admin_email(text);
DROP FUNCTION IF EXISTS public.rpc_get_admin_email(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_get_admin_email(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_email text; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_get_admin_email');
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT email INTO v_email FROM public.profiles WHERE role = 'admin' AND active = true ORDER BY created_at ASC LIMIT 1;
  RETURN v_email;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_get_admin_email(text, jsonb) TO anon, authenticated, service_role;


-- ── Login code RPCs ──
-- These are called frequently (every login email). Keep dual-auth for rollout.
DROP FUNCTION IF EXISTS public.rpc_login_code_create(text, text, timestamptz, text);
DROP FUNCTION IF EXISTS public.rpc_login_code_create(text, text, timestamptz, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_login_code_create(
  p_email text, p_code text, p_expires_at timestamptz,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_login_code_create');
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  IF public._signin_refuse_pental('rpc_login_code_create') THEN RETURN false; END IF;  -- 1839
  INSERT INTO public.login_codes (email, code, expires_at) VALUES (lower(p_email), p_code, p_expires_at);
  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_login_code_create(text, text, timestamptz, text, jsonb) TO anon, authenticated, service_role;

DROP FUNCTION IF EXISTS public.rpc_login_code_verify(text, text, text);
DROP FUNCTION IF EXISTS public.rpc_login_code_verify(text, text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_login_code_verify(
  p_email text, p_code text,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_id uuid; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_login_code_verify');
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  IF public._signin_refuse_pental('rpc_login_code_verify') THEN RETURN jsonb_build_object('found', false, 'refused', 'signin_local'); END IF;  -- 1839
  UPDATE public.login_codes SET used = true
    WHERE id = (
      SELECT id FROM public.login_codes
      WHERE email = lower(p_email) AND code = p_code AND used = false AND expires_at >= now()
      ORDER BY created_at DESC LIMIT 1 FOR UPDATE SKIP LOCKED
    ) RETURNING id INTO v_id;
  IF v_id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'id', v_id);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_login_code_verify(text, text, text, jsonb) TO anon, authenticated, service_role;

DROP FUNCTION IF EXISTS public.rpc_login_code_invalidate(text, text);
DROP FUNCTION IF EXISTS public.rpc_login_code_invalidate(text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_login_code_invalidate(
  p_email text,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_login_code_invalidate');
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  IF public._signin_refuse_pental('rpc_login_code_invalidate') THEN RETURN false; END IF;  -- 1839
  UPDATE public.login_codes SET used = true WHERE email = lower(p_email) AND used = false;
  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_login_code_invalidate(text, text, jsonb) TO anon, authenticated, service_role;

DROP FUNCTION IF EXISTS public.rpc_login_code_count_recent(text, timestamptz, text);
DROP FUNCTION IF EXISTS public.rpc_login_code_count_recent(text, timestamptz, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_login_code_count_recent(
  p_email text, p_since timestamptz,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_login_code_count_recent');
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  IF public._signin_refuse_pental('rpc_login_code_count_recent') THEN RETURN 0; END IF;  -- 1839
  RETURN (SELECT count(*) FROM public.login_codes WHERE email = lower(p_email) AND created_at >= p_since)::integer;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_login_code_count_recent(text, timestamptz, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_verify_totp (from byo-mfa-enforcement.sql) ──
DROP FUNCTION IF EXISTS public.rpc_verify_totp(text, text, text);
DROP FUNCTION IF EXISTS public.rpc_verify_totp(text, text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_verify_totp(
  p_email text, p_code text,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_prof RECORD; v_ok boolean; v_new_attempts int; v_lock_until timestamptz; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_verify_totp');
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT id, auth_user_id, totp_secret, COALESCE(totp_attempts, 0) AS totp_attempts, totp_locked_until
    INTO v_prof FROM public.profiles
    WHERE lower(email) = lower(p_email) AND active = true FOR UPDATE;
  IF NOT FOUND OR v_prof.totp_secret IS NULL OR v_prof.totp_secret = '' THEN
    RETURN jsonb_build_object('error', 'MFA not configured');
  END IF;
  -- 1810: the code proves the person holding the session, so the session
  -- must be that person's. A signed call with no session, or another
  -- person's session, could otherwise stamp anybody fresh by naming them
  -- (the code alone is not a session, and Pental's server relays codes).
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM v_prof.auth_user_id THEN
    RAISE EXCEPTION 'Session required' USING ERRCODE = '42501';
  END IF;
  IF v_prof.totp_locked_until IS NOT NULL AND v_prof.totp_locked_until > now() THEN
    RETURN jsonb_build_object('error', 'Account locked', 'locked_until', v_prof.totp_locked_until);
  END IF;
  v_ok := public._totp_check(v_prof.totp_secret, p_code);
  IF v_ok THEN
    UPDATE public.profiles SET totp_attempts = 0, totp_locked_until = NULL WHERE id = v_prof.id;
    PERFORM public._stamp_mfa_verified(v_prof.auth_user_id);
    RETURN jsonb_build_object('success', true);
  END IF;
  v_new_attempts := v_prof.totp_attempts + 1;
  IF v_new_attempts >= 5 THEN
    v_lock_until := now() + interval '15 minutes';
    UPDATE public.profiles SET totp_attempts = v_new_attempts, totp_locked_until = v_lock_until WHERE id = v_prof.id;
    RETURN jsonb_build_object('error', 'Account locked', 'locked_until', v_lock_until);
  END IF;
  UPDATE public.profiles SET totp_attempts = v_new_attempts WHERE id = v_prof.id;
  RETURN jsonb_build_object('error', 'Invalid code', 'attempts_remaining', 5 - v_new_attempts);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_verify_totp(text, text, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_clear_mfa (renamed rpc_admin_reset_mfa for clarity) ──
-- Kept rpc_clear_mfa as a wrapper for backward compat during rollout.
DROP FUNCTION IF EXISTS public.rpc_clear_mfa(text, text);
DROP FUNCTION IF EXISTS public.rpc_clear_mfa(text, text, jsonb);
DROP FUNCTION IF EXISTS public.rpc_admin_reset_mfa(text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_admin_reset_mfa(
  p_email text,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_auth_id uuid; v_mode text;
BEGIN
  -- Resetting another user's MFA is an authorisation action and now requires a
  -- signed-in ADMIN of this portal. Pental's provisioning credential no longer
  -- grants it, so Pental cannot clear MFA and impersonate a user. A firm that
  -- loses every admin recovers through their own Supabase project.
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE auth_user_id = auth.uid() AND role = 'admin' AND active = true
  ) THEN
    RAISE EXCEPTION 'Admin session required';
  END IF;
  SELECT auth_user_id INTO v_auth_id FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true;
  IF v_auth_id IS NULL THEN RETURN false; END IF;
  UPDATE public.profiles SET totp_secret = NULL, totp_attempts = 0, totp_locked_until = NULL
    WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM public._clear_mfa_verified(v_auth_id);
  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_admin_reset_mfa(text, text, jsonb) TO anon, authenticated, service_role;

-- ── rpc_admin_reset_all_portal_mfa ────────────────────────────────────────
-- Wipes TOTP + WebAuthn for EVERY portal user in this BYO database.
-- 1810: a firm administrator's action, signed in with a fresh factor, and
-- nothing else; p_secret and p_auth are ignored. Nothing on pental.io calls
-- it any more (the operator dashboard's portal reset is gone).
--
-- Returns the number of profiles touched and webauthn rows deleted so
-- the caller can confirm the wipe actually did something.
DROP FUNCTION IF EXISTS public.rpc_admin_reset_all_portal_mfa(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_admin_reset_all_portal_mfa(
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp
AS $$
DECLARE
  v_mode text;
  v_profiles_touched int := 0;
  v_webauthn_deleted int := 0;
  v_auth_id uuid;
BEGIN
  -- Portal-wide MFA wipe is the strongest authorisation action in this database,
  -- so it requires a signed-in ADMIN of this portal. Pental's provisioning
  -- credential no longer grants it: without this, Pental could clear everyone's
  -- MFA and then enrol a factor of its own, which would defeat the whole point of
  -- MFA being the control that protects your data.
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE auth_user_id = auth.uid() AND role = 'admin' AND active = true
  ) THEN
    RAISE EXCEPTION 'Admin session required';
  END IF;
  -- And the admin must have presented a factor this session: a portal-wide MFA
  -- wipe is the strongest reset there is, so a password-step-only session must
  -- not be able to trigger it and then enrol into the cleared accounts.
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Re-verify MFA before resetting portal MFA' USING ERRCODE = '42501';
  END IF;
  -- 1816: and it is the account owner's. It resets every administrator's MFA,
  -- the owner's included, and only the owner acts on the other administrators
  -- (_pental_manage_refusal); any administrator could run it until now.
  IF public._pental_account_owner() IS DISTINCT FROM public.current_profile_id() THEN
    RAISE EXCEPTION 'Only the account owner can reset MFA for the whole portal' USING ERRCODE = '42501';
  END IF;
  v_mode := 'admin_session';

  PERFORM set_config('pental.bypass_protect', 'true', true);

  -- Clear TOTP secrets on every active profile, plus reset attempt
  -- counters and any lockout windows so users can re-enrol immediately
  -- without inheriting stale lockout state.
  WITH cleared AS (
    UPDATE public.profiles
       SET totp_secret = NULL,
           totp_attempts = 0,
           totp_locked_until = NULL,
           updated_at = now()
     WHERE totp_secret IS NOT NULL OR totp_attempts > 0 OR totp_locked_until IS NOT NULL
     RETURNING auth_user_id
  )
  SELECT count(*) INTO v_profiles_touched FROM cleared;

  -- Drop the mfa_verified_at claim on auth.users for every active profile
  -- so the next login forces a fresh MFA flow rather than inheriting a
  -- pre-reset verified state.
  FOR v_auth_id IN
    SELECT auth_user_id FROM public.profiles WHERE auth_user_id IS NOT NULL
  LOOP
    PERFORM public._clear_mfa_verified(v_auth_id);
  END LOOP;

  -- Delete every WebAuthn credential. BYO is single-tenant so a blanket
  -- DELETE clears the table. webauthn_mfa_challenges is transient (5 min
  -- expiry) and will self-clean, we don't need to touch it.
  -- 1816: WITH a WHERE, because Supabase refuses a DELETE without one
  -- (pg-safeupdate, loaded for every API session), so on Supabase this whole
  -- reset failed at this line and nothing was reset.
  IF EXISTS (SELECT 1 FROM information_schema.tables
             WHERE table_schema = 'public' AND table_name = 'webauthn_credentials') THEN
    EXECUTE 'WITH d AS (DELETE FROM public.webauthn_credentials WHERE true RETURNING 1) SELECT count(*) FROM d'
      INTO v_webauthn_deleted;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'profiles_touched', v_profiles_touched,
    'webauthn_deleted', COALESCE(v_webauthn_deleted, 0),
    'mode', v_mode
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_admin_reset_all_portal_mfa(text, jsonb) TO anon, authenticated, service_role;
COMMENT ON FUNCTION public.rpc_admin_reset_all_portal_mfa(text, jsonb) IS
  'Portal-wide MFA reset (TOTP + WebAuthn for every user) by an administrator of this portal signed in with a fresh factor. 1810: nothing on pental.io calls it; Pental cannot reset a firm''s MFA.';

-- Backward-compat alias. Two-phase auth pattern:
--   1. Authorise under op='rpc_clear_mfa' so callers can sign for the name
--      they're actually invoking.
--   2. Run the exact same body as rpc_admin_reset_mfa (including
--      _clear_mfa_verified and active=true filter) to keep behaviour
--      identical.
DROP FUNCTION IF EXISTS public.rpc_clear_mfa(text, text);
CREATE OR REPLACE FUNCTION public.rpc_clear_mfa(
  p_email text, p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_mode text; v_auth_id uuid;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_clear_mfa');
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret'; END IF;
  SELECT auth_user_id INTO v_auth_id FROM public.profiles
    WHERE lower(email) = lower(p_email) AND active = true;
  IF v_auth_id IS NULL THEN RETURN false; END IF;
  -- Same column guard as rpc_save_totp_secret: it only lets admin/senior touch
  -- totp_secret, so this path failed with "Cannot change MFA config" for every
  -- other role. This function has already decided the caller is entitled to the
  -- change, so raise the guard's own flag and drop it straight after.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles
    SET totp_secret = NULL, totp_attempts = 0, totp_locked_until = NULL
    WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM set_config('pental.bypass_protect', 'false', true);
  PERFORM public._clear_mfa_verified(v_auth_id);
  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_clear_mfa(text, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_bulk_import (replace with dual-auth + advisory lock) ──
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_bulk_import(
  p_table text, p_rows jsonb,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  r jsonb; v_inserted integer := 0; v_errors integer := 0; v_last_err text := '';
  v_cols text[]; v_col_types text[]; v_sql text; v_key text; v_vals text[];
  v_col_list text; v_col_type text; v_idx int; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_bulk_import');
  IF v_mode IS NULL THEN RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Invalid provision secret'); END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  IF p_rows IS NULL OR jsonb_typeof(p_rows) != 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN jsonb_build_object('success', true, 'inserted', 0, 'errors', 0);
  END IF;
  IF p_table IN ('_internal_secrets','_credentials_key','_encryption_keys') THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Table is reserved and cannot be imported');
  END IF;
  IF p_table = 'profiles_client_restore' THEN
    FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
      BEGIN UPDATE profiles SET client_id = (r->>'client_id')::uuid WHERE id = (r->>'id')::uuid;
      EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; v_last_err := SQLERRM; END;
    END LOOP;
    RETURN jsonb_build_object('success', v_errors = 0, 'inserted', jsonb_array_length(p_rows) - v_errors, 'errors', v_errors, 'last_error', v_last_err);
  END IF;
  SELECT array_agg(column_name::text ORDER BY ordinal_position),
         array_agg(data_type::text ORDER BY ordinal_position)
    INTO v_cols, v_col_types
    FROM information_schema.columns WHERE table_schema = 'public' AND table_name = p_table;
  IF v_cols IS NULL THEN RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1, 'last_error', 'Table not found: ' || p_table); END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    BEGIN
      v_vals := ARRAY[]::text[]; v_col_list := '';
      FOR v_key IN SELECT * FROM jsonb_object_keys(r) LOOP
        IF r->v_key IS NULL OR jsonb_typeof(r->v_key) = 'null' THEN CONTINUE; END IF;
        v_idx := array_position(v_cols, v_key);
        IF v_idx IS NOT NULL THEN
          v_col_type := v_col_types[v_idx];
          v_col_list := v_col_list || CASE WHEN v_col_list = '' THEN '' ELSE ',' END || quote_ident(v_key);
          IF v_col_type = 'jsonb' OR v_col_type = 'json' THEN
            v_vals := v_vals || (quote_literal((r->v_key)::text) || '::jsonb');
          ELSIF v_col_type = 'bytea' THEN
            v_vals := v_vals || (quote_literal(r->>v_key) || '::bytea');
          ELSE
            v_vals := v_vals || quote_nullable(r ->> v_key);
          END IF;
        END IF;
      END LOOP;
      IF v_col_list != '' THEN
        v_sql := 'INSERT INTO ' || quote_ident(p_table) || ' (' || v_col_list || ') VALUES (' || array_to_string(v_vals, ',') || ')';
        EXECUTE v_sql;
      END IF;
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; v_last_err := SQLERRM; END;
  END LOOP;
  RETURN jsonb_build_object('success', v_errors = 0, 'inserted', v_inserted, 'errors', v_errors, 'last_error', v_last_err);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_bulk_import(text, jsonb, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_bulk_auth ──
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_bulk_auth(
  p_profiles jsonb,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r jsonb; v_created int := 0; v_errors int := 0; v_auth_id uuid; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_bulk_auth');
  IF v_mode IS NULL THEN
    RETURN jsonb_build_object('success', false, 'created', 0, 'errors', 1, 'error', 'Invalid provision secret');
  END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  IF p_profiles IS NULL OR jsonb_typeof(p_profiles) != 'array' THEN
    RETURN jsonb_build_object('success', true, 'created', 0);
  END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(p_profiles) LOOP
    BEGIN
      v_auth_id := COALESCE((r->>'auth_user_id')::uuid, (r->>'id')::uuid);
      IF EXISTS (SELECT 1 FROM auth.users WHERE id = v_auth_id) THEN CONTINUE; END IF;
      INSERT INTO auth.users (
        id, instance_id, email, encrypted_password, email_confirmed_at, aud, role,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, email_change_token_current,
        email_change_confirm_status, phone, phone_change, phone_change_token,
        reauthentication_token, is_sso_user, is_anonymous, recovery_token
      ) VALUES (
        v_auth_id, '00000000-0000-0000-0000-000000000000', lower(r->>'email'),
        extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')),
        now(), 'authenticated', 'authenticated',
        jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
        jsonb_build_object('name', COALESCE(r->>'name', '')),
        now(), now(), '', '', '', '', 0, NULL, '', '', '', false, false, ''
      );
      INSERT INTO auth.identities (
        id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at
      ) VALUES (
        gen_random_uuid(), v_auth_id, lower(r->>'email'),
        jsonb_build_object('sub', v_auth_id::text, 'email', lower(r->>'email'), 'email_verified', true),
        'email', now(), now(), now()
      );
      UPDATE public.profiles SET auth_user_id = v_auth_id
        WHERE lower(email) = lower(r->>'email') AND (auth_user_id IS NULL OR auth_user_id != v_auth_id);
      v_created := v_created + 1;
    EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; END;
  END LOOP;
  RETURN jsonb_build_object('success', v_errors = 0, 'created', v_created, 'errors', v_errors);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_bulk_auth(jsonb, text, jsonb) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 12. rpc_set_bridge_password: DUAL-AUTH (signed JWT preferred, provision_secret fallback)
-- ═══════════════════════════════════════════════════════════════════════════
-- Legitimate use case: master→BYO migration needs to authenticate as the
-- tenant admin briefly to upload to BYO Storage buckets (RLS requires an
-- authenticated session). After upload, the temporary password is
-- discarded; the admin uses email login codes to access the portal.
--
-- 1810: this bridge sets a sign-in password for a person who ALREADY IS a
-- portal user, and nothing else. It used to create an auth user AND an admin
-- profile for an address it had never seen, which let anything holding
-- Pental's signing keys add an administrator to a firm's database (a first
-- enrolment is open, so that administrator could then enrol a factor and
-- read everything). Now an address with no active profile is refused. The
-- one creation left is the auth.users row for a person the firm invited who
-- has never signed in, linked to their existing profile.
DROP FUNCTION IF EXISTS public.rpc_set_bridge_password(text, text);
DROP FUNCTION IF EXISTS public.rpc_set_bridge_password(text, text, text);
DROP FUNCTION IF EXISTS public.rpc_set_bridge_password(text, text, text, jsonb);

CREATE OR REPLACE FUNCTION public.rpc_set_bridge_password(
  p_email text,
  p_password text,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_uid uuid; v_profile_id uuid; v_auth_id uuid; v_enc text; v_mode text;
BEGIN
  -- Auth gate: signed envelope only.
  --
  -- We deliberately do NOT accept provision_secret here. The threat model
  -- says "Master-Supabase-compromise alone: BYO data protected", but if
  -- this RPC accepted provision_secret, master-compromise would gain:
  --   1. read provision_secret from tenants table
  --   2. call rpc_set_bridge_password with it, set any user's password
  --   3. password-grant signin → user_jwt
  --   4. call any data-read RPC (which gates on user_jwt) → exfiltrate.
  --
  -- That re-opens the entire trust boundary the architecture exists to
  -- enforce. Sibling write RPCs (rpc_bulk_clean, rpc_bulk_import,
  -- rpc_admin_reset_mfa) all gate on something stronger than
  -- provision_secret, bridge_password must too.
  --
  -- Legitimate callers (portal auth-code lambda, master→BYO migration)
  -- both pass a signed envelope p_auth via pentalAuthFields/pentalSign.
  -- p_secret is preserved as an arg for ABI compatibility with older
  -- callers that pass it; if both are passed and the signed envelope
  -- verifies, that wins via _pental_authorise's signed-first check.
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_set_bridge_password');
  -- 1798: signed-envelope ONLY. _pental_authorise also returns 'user_jwt' for
  -- any signed-in caller, so without this a self-signed-up session with no
  -- profile could set ANY user's bridge password and then sign in as them.
  -- provision_secret is rejected explicitly just below; a bare session is
  -- rejected here.
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN RAISE EXCEPTION 'Unauthorised'; END IF;
  IF v_mode = 'provision_secret' THEN
    -- Explicitly reject: a signed-envelope path was not taken. We log
    -- this in the audit table for forensics, a provision_secret-only
    -- call to bridge_password indicates either an outdated client
    -- (which we want to surface as a 4xx, not silently accept) or an
    -- attacker holding a leaked provision_secret.
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES ('rpc_set_bridge_password', 'provision_secret', 'rejected',
              'provision_secret-only auth is not accepted; signed envelope required');
    RAISE EXCEPTION 'rpc_set_bridge_password requires signed-envelope authorisation' USING ERRCODE = '42501';
  END IF;

  -- 1839: refused once this database signs people in itself (false: no
  -- password set).
  IF public._signin_refuse_pental('rpc_set_bridge_password') THEN RETURN false; END IF;

  -- 1810: a portal user, or nothing. The sign-in only issues a code to an
  -- active profile, so this refusal is never met by a real sign-in.
  SELECT id INTO v_profile_id FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES ('rpc_set_bridge_password', v_mode, 'rejected', 'no active profile for the address');
    RAISE EXCEPTION 'Unauthorised' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  v_enc := extensions.crypt(p_password, extensions.gen_salt('bf'));
  SELECT id INTO v_auth_id FROM auth.users WHERE email = lower(p_email);
  IF v_auth_id IS NOT NULL THEN
    UPDATE auth.users SET encrypted_password = v_enc,
      email_confirmed_at = COALESCE(email_confirmed_at, now()),
      updated_at = now()
      WHERE id = v_auth_id;
    UPDATE public.profiles SET auth_user_id = v_auth_id
      WHERE id = v_profile_id AND (auth_user_id IS NULL OR auth_user_id != v_auth_id);
    IF NOT EXISTS (SELECT 1 FROM auth.identities WHERE user_id::text = v_auth_id::text AND provider = 'email') THEN
      INSERT INTO auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
        VALUES (gen_random_uuid(), v_auth_id, lower(p_email),
          jsonb_build_object('sub', v_auth_id::text, 'email', lower(p_email), 'email_verified', true),
          'email', now(), now(), now());
    END IF;
    RETURN true;
  END IF;
  -- The person the firm invited, signing in for the first time: their
  -- auth.users row is made here and linked to the profile the firm created.
  v_uid := v_profile_id;
  INSERT INTO auth.users (id, instance_id, email, encrypted_password, email_confirmed_at, aud, role,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token,
    email_change, email_change_token_new, recovery_token, phone_change, phone_change_token,
    reauthentication_token, is_sso_user, is_anonymous)
    VALUES (v_uid, '00000000-0000-0000-0000-000000000000', lower(p_email), v_enc, now(),
      'authenticated', 'authenticated',
      jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
      jsonb_build_object('email', lower(p_email)), now(), now(),
      encode(extensions.gen_random_bytes(32), 'hex'), '', '', '', '', '', '', false, false);
  INSERT INTO auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    VALUES (gen_random_uuid(), v_uid, lower(p_email),
      jsonb_build_object('sub', v_uid::text, 'email', lower(p_email), 'email_verified', true),
      'email', now(), now(), now());
  UPDATE public.profiles SET auth_user_id = v_uid
    WHERE id = v_profile_id AND (auth_user_id IS NULL OR auth_user_id != v_uid);
  RETURN true;
EXCEPTION WHEN unique_violation THEN
  UPDATE auth.users SET encrypted_password = v_enc,
    email_confirmed_at = COALESCE(email_confirmed_at, now()), updated_at = now()
    WHERE email = lower(p_email);
  RETURN FOUND;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_set_bridge_password(text, text, text, jsonb) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 12b. REMOVE rpc_export_all (replaced by per-table below)
-- ═══════════════════════════════════════════════════════════════════════════
DROP FUNCTION IF EXISTS public.rpc_export_all();
DROP FUNCTION IF EXISTS public.rpc_export_all(text);
DROP FUNCTION IF EXISTS public.rpc_export_all(text, jsonb);


-- ═══════════════════════════════════════════════════════════════════════════
-- 13. PER-TABLE EXPORT RPCs (used by master→BYO migration)
-- ═══════════════════════════════════════════════════════════════════════════
-- Replacement for rpc_export_all. Each function returns rows from ONE table.
-- Advantages:
--   - No _credentials_key / _encryption_keys / _internal_secrets leak via a
--     single call
--   - Signed JWT required per op (op = rpc_export_<table>)
--   - Pental requests them one at a time, so an attacker can't grab
--     everything atomically even with a single forged token (they'd need
--     one per table)

CREATE OR REPLACE FUNCTION public._pental_require_auth(p_auth jsonb, p_secret text, p_op text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
BEGIN
  -- 1798: signed only. Every rpc_export_* reads a whole table past row-level
  -- security; a signed-in session (any role) or the provisioning secret alone
  -- is not enough for that. Nothing calls them today.
  IF public._pental_authorise(p_auth, p_secret, p_op) IS DISTINCT FROM 'signed' THEN
    RAISE EXCEPTION 'Unauthorised';
  END IF;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._pental_require_auth(jsonb, text, text) FROM PUBLIC, anon, authenticated;

-- Generator macro: one function per table.
-- Intentionally not one generic rpc_export_table(), that would let an
-- attacker with a valid JWT for any op enumerate every table. Named RPCs
-- let the op allowlist distinguish them.

DO $gen$
DECLARE
  v_tbls text[] := ARRAY[
    'settings', 'profiles', 'clients', 'assessments', 'findings', 'proposals',
    'invoices', 'kb_entries', 'meetings', 'meeting_attendees',
    'contractor_payments', 'email_notifications', 'feedback', 'tickets',
    'timeline_events', 'assessment_comments', 'assessment_files', 'qa_comments',
    'payment_events', 'login_codes'
  ];
  v_tbl text;
  v_sql text;
BEGIN
  FOREACH v_tbl IN ARRAY v_tbls LOOP
    v_sql := format($f$
      DROP FUNCTION IF EXISTS public.rpc_export_%1$I(text);
      DROP FUNCTION IF EXISTS public.rpc_export_%1$I(text, jsonb);
      CREATE OR REPLACE FUNCTION public.rpc_export_%1$I(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
      RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $body$
      BEGIN
        PERFORM public._pental_require_auth(p_auth, p_secret, 'rpc_export_%1$s');
        RETURN COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM public.%1$I) t), '[]'::jsonb);
      END;
      $body$;
      GRANT EXECUTE ON FUNCTION public.rpc_export_%1$I(text, jsonb) TO anon, authenticated, service_role;
    $f$, v_tbl);
    EXECUTE v_sql;
  END LOOP;
END $gen$;


-- ═══════════════════════════════════════════════════════════════════════════
-- 14. rpc_cleanup_orphan_auth ROLE-GATE
-- ═══════════════════════════════════════════════════════════════════════════
-- Previously: anyone authenticated could call. Now admin-only or signed.
DROP FUNCTION IF EXISTS public.rpc_cleanup_orphan_auth(text);
DROP FUNCTION IF EXISTS public.rpc_cleanup_orphan_auth(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_cleanup_orphan_auth(
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_caller_role text; v_deleted int := 0; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_cleanup_orphan_auth');
  -- 1798: a session ('user_jwt') goes through the admin check too. It used to
  -- skip it, because only a NULL mode reached the check below.
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN
    -- Not signed/secret-authorised. Allow authenticated admins as a last resort.
    SELECT role INTO v_caller_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
      RAISE EXCEPTION 'Unauthorised';
    END IF;
  END IF;
  DELETE FROM auth.users
    WHERE id NOT IN (SELECT auth_user_id FROM public.profiles WHERE auth_user_id IS NOT NULL)
      AND created_at < now() - interval '24 hours';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'deleted', v_deleted);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_cleanup_orphan_auth(text, jsonb) TO authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 15. MIGRATE _credentials_key + _encryption_keys TO VAULT
-- ═══════════════════════════════════════════════════════════════════════════
-- One-time migration: copy current key value into Vault slot, keep the
-- old tables present but empty (for rollback window). _get_cred_key() now
-- reads from Vault.
DO $$
DECLARE v_existing_key text; v_slot uuid;
BEGIN
  -- Take existing key from _credentials_key or _encryption_keys, whichever is populated
  SELECT encryption_key INTO v_existing_key FROM public._credentials_key LIMIT 1;
  IF v_existing_key IS NULL OR v_existing_key = '' THEN
    SELECT key_value INTO v_existing_key FROM public._encryption_keys WHERE key_name = 'credentials' LIMIT 1;
  END IF;

  -- Write to Vault if not already set
  SELECT id INTO v_slot FROM vault.decrypted_secrets WHERE name = 'credentials_aes_key';
  IF v_slot IS NOT NULL THEN
    IF v_existing_key IS NOT NULL AND v_existing_key != '' THEN
      PERFORM vault.update_secret(v_slot, v_existing_key);
    ELSE
      -- Fresh install: generate and store
      PERFORM vault.update_secret(v_slot, encode(extensions.gen_random_bytes(32), 'hex'));
    END IF;
  END IF;
END $$;

-- Redirect _get_cred_key to Vault
CREATE OR REPLACE FUNCTION public._get_cred_key() RETURNS text
LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public, vault, pg_temp AS $$
  SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'credentials_aes_key'
$$;
REVOKE EXECUTE ON FUNCTION public._get_cred_key() FROM PUBLIC, anon, authenticated;


-- ═══════════════════════════════════════════════════════════════════════════
-- 16. REVOKE ANON GRANTS ON DESTRUCTIVE RPCs POST-MIGRATION
-- ═══════════════════════════════════════════════════════════════════════════
-- With dual-auth in place, Pental uses signed JWTs exclusively going forward.
-- But during rollout anon still needs EXECUTE so authenticated portal clients
-- calling via provision_secret during transition don't break. Once all code
-- has migrated (run the post-rollout patch), these revokes should happen.
--
-- FOR NOW: DO NOT REVOKE. The flip happens in a future patch
-- (byo-security-finalise.sql) after Arian confirms all callsites signed.
-- Keeping this section as a commented plan so we don't forget.

-- -- Uncomment when ready to cut over fully:
-- REVOKE EXECUTE ON FUNCTION public.rpc_bulk_clean(text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_bulk_import(text, jsonb, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_bulk_auth(jsonb, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_bulk_import_keys(text, jsonb, text) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_get_smtp_config(text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_update_settings(jsonb, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_read_settings_server(text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_profile_lookup(text, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_get_admin_email(text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_verify_totp(text, text, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_admin_reset_mfa(text, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_clear_mfa(text, text) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_login_code_create(text, text, timestamptz, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_login_code_verify(text, text, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_login_code_invalidate(text, text, jsonb) FROM anon;
-- REVOKE EXECUTE ON FUNCTION public.rpc_login_code_count_recent(text, timestamptz, text, jsonb) FROM anon;


-- ═══════════════════════════════════════════════════════════════════════════
-- 17. BOOTSTRAP ADMIN TIGHTENING
-- ═══════════════════════════════════════════════════════════════════════════
-- Previously: anyone with anon+publishable key could call rpc_bootstrap_admin
-- when profiles was empty. With install_token now in Vault, require it here.
DROP FUNCTION IF EXISTS public.rpc_bootstrap_admin(text, text);
DROP FUNCTION IF EXISTS public.rpc_bootstrap_admin(text, text, text);
CREATE OR REPLACE FUNCTION public.rpc_bootstrap_admin(
  p_email text, p_name text, p_install_token text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_count integer;
  v_uid uuid;
  v_expected_hash text;
  v_provided_hash text;
BEGIN
  SELECT count(*) INTO v_count FROM public.profiles;
  IF v_count > 0 THEN
    RETURN jsonb_build_object('error', 'Bootstrap not available - users already exist');
  END IF;

  -- Install-token gate: mandatory if token exists in Vault.
  v_expected_hash := public._pental_install_token_hash();
  IF v_expected_hash IS NOT NULL AND v_expected_hash != '' THEN
    IF p_install_token IS NULL OR length(p_install_token) < 32 THEN
      RETURN jsonb_build_object('error', 'Install token required');
    END IF;
    v_provided_hash := encode(extensions.digest(p_install_token, 'sha256'), 'hex');
    IF v_provided_hash IS DISTINCT FROM v_expected_hash THEN
      RETURN jsonb_build_object('error', 'Invalid install token');
    END IF;
  END IF;
  -- If no hash in Vault (very first boot before rpc_bulk_clean ran), permit.
  -- This is the classic bootstrap-mode window.

  v_uid := gen_random_uuid();
  INSERT INTO auth.users (
    id, instance_id, email, encrypted_password, email_confirmed_at, aud, role,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token,
    phone_change, phone_change_token, reauthentication_token, is_sso_user, is_anonymous
  ) VALUES (
    -- 1715: the sign-in record in lower case, like every other account.
    v_uid, '00000000-0000-0000-0000-000000000000', lower(btrim(p_email)),
    extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')),
    now(), 'authenticated', 'authenticated',
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('name', p_name),
    now(), now(), encode(extensions.gen_random_bytes(32), 'hex'),
    '', '', '', '', '', '', false, false
  );
  INSERT INTO auth.identities (
    id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at
  ) VALUES (
    gen_random_uuid(), v_uid, lower(btrim(p_email)),
    jsonb_build_object('sub', v_uid::text, 'email', lower(btrim(p_email)), 'email_verified', true),
    'email', now(), now(), now()
  );
  INSERT INTO public.profiles (id, auth_user_id, email, name, role)
    VALUES (v_uid, v_uid, p_email, p_name, 'admin');

  INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result)
    VALUES ('rpc_bootstrap_admin', 'install_token', 'ok');

  RETURN jsonb_build_object('success', true, 'user_id', v_uid, 'message', 'Admin account created');
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_bootstrap_admin(text, text, text) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 17b. DUAL-AUTH OVERLOADS FOR LEGACY RPCs
-- ═══════════════════════════════════════════════════════════════════════════
-- These two RPCs exist in byo-database.sql (rpc_bulk_import_keys) and
-- byo-mfa-enforcement.sql (rpc_save_totp_secret) with p_secret-only
-- signatures. They're still used by Pental's code with signed auth, so we
-- add a 4-arg overload that checks p_auth first and delegates back to the
-- 3-arg version for the actual work. PostgREST routes based on parameter
-- names, so callers sending {..., p_auth, p_secret} will hit this overload;
-- callers sending only {..., p_secret} hit the pre-existing function.

-- rpc_bulk_import_keys: signed overload
DROP FUNCTION IF EXISTS public.rpc_bulk_import_keys(text, jsonb, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_bulk_import_keys(
  p_table text, p_rows jsonb,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_mode text;
  r jsonb; v_inserted integer := 0; v_errors integer := 0; v_last_err text := '';
  v_cols text[]; v_col_types text[]; v_sql text; v_key text; v_vals text[];
  v_col_list text; v_col_type text; v_idx int;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_bulk_import_keys');
  IF v_mode IS NULL THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1,
      'last_error', 'Unauthorised');
  END IF;
  IF p_table NOT IN ('_credentials_key','_encryption_keys') THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1,
      'last_error', 'Only _credentials_key and _encryption_keys accepted');
  END IF;
  PERFORM set_config('pental.bypass_protect', 'true', true);
  IF p_rows IS NULL OR jsonb_typeof(p_rows) != 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN jsonb_build_object('success', true, 'inserted', 0, 'errors', 0);
  END IF;
  EXECUTE 'DELETE FROM ' || quote_ident(p_table) || ' WHERE true';
  SELECT array_agg(column_name::text ORDER BY ordinal_position),
         array_agg(data_type::text ORDER BY ordinal_position)
    INTO v_cols, v_col_types
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = p_table;
  IF v_cols IS NULL THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1,
      'last_error', 'Table not found: ' || p_table);
  END IF;
  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    BEGIN
      v_vals := ARRAY[]::text[];
      v_col_list := '';
      FOR v_idx IN 1..array_length(v_cols, 1) LOOP
        v_key := v_cols[v_idx];
        v_col_type := v_col_types[v_idx];
        IF r ? v_key THEN
          IF v_col_list = '' THEN v_col_list := quote_ident(v_key);
          ELSE v_col_list := v_col_list || ',' || quote_ident(v_key); END IF;
          IF r->>v_key IS NULL THEN
            v_vals := array_append(v_vals, 'NULL');
          ELSE
            v_vals := array_append(v_vals,
              quote_literal(r->>v_key) || '::' || v_col_type);
          END IF;
        END IF;
      END LOOP;
      IF v_col_list != '' THEN
        v_sql := format('INSERT INTO %I (%s) VALUES (%s) ON CONFLICT DO NOTHING',
                        p_table, v_col_list, array_to_string(v_vals, ','));
        EXECUTE v_sql;
        v_inserted := v_inserted + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_last_err := SQLERRM;
    END;
  END LOOP;
  RETURN jsonb_build_object('success', v_errors = 0, 'inserted', v_inserted,
    'errors', v_errors, 'last_error', v_last_err);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_bulk_import_keys(text, jsonb, text, jsonb)
  TO anon, authenticated, service_role;


-- rpc_save_totp_secret: signed overload
-- Original signature: (p_email text, p_totp_secret text, p_secret text)
-- New overload adds p_auth jsonb for signed-first auth.
DROP FUNCTION IF EXISTS public.rpc_save_totp_secret(text, text, text, jsonb);
-- rpc_save_totp_secret: signed overload, hardened.
--
-- Earlier overload accepted any signed-or-secret auth and blindly
-- overwrote profiles.totp_secret + stamped mfa_verified_at. That was
-- the complete-bypass path for Vercel-compromise:
--   1. Vercel produces a signed envelope (it has privkey_a + HMAC).
--   2. Calls bridge_password to mint a session for the victim.
--   3. Calls this RPC to overwrite victim's TOTP secret with one Vercel
--      knows AND stamp mfa_verified_at.
--   4. Now Vercel's session passes mfa_is_fresh() and reads everything.
--
-- That defeated the documented threat model ("Vercel-compromise alone
-- cannot read BYO data because RLS gates on mfa_is_fresh()"). The
-- hardening below restores it by requiring proof-of-secret-possession
-- on every call: the caller must also supply a currently-valid 6-digit
-- TOTP code computed from the new secret. A Vercel attacker can compute
-- a code from a secret they've chosen, but the call would still need
-- the user_jwt of the target user (rejected if the auth.uid()
-- mismatches the email), and bridge_password is now also gated on
-- signed envelope only (v18), so the attacker would need to chain two
-- separately-protected primitives. More importantly, when an attacker
-- ROTATES a victim's secret to one they control, the freshness stamp
-- only fires when caller is saving their OWN secret AND the code
-- matches, so an admin/attacker rotating someone else's secret
-- doesn't get the stamp on the victim's session.
DROP FUNCTION IF EXISTS public.rpc_save_totp_secret(text, text, text, jsonb);
DROP FUNCTION IF EXISTS public.rpc_save_totp_secret(text, text, text, text, jsonb);
-- 1798: and the three-argument form, which took the provisioning secret alone
-- and wrote any user's authenticator secret with no code and no signature.
-- Nothing calls it (the portal saves through the five-argument form below,
-- from api/admin.js, signed and with a code), so it goes.
DROP FUNCTION IF EXISTS public.rpc_save_totp_secret(text, text, text);
CREATE OR REPLACE FUNCTION public.rpc_save_totp_secret(
  p_email text,
  p_totp_secret text,
  p_verification_code text,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_mode text;
  v_caller_role text;
  v_caller_email text;
  v_caller_auth_id uuid;
  v_target_id uuid;
  v_target_auth_id uuid;
  v_was_set boolean;
  v_self_save boolean;
  v_code_ok boolean;
  v_has_webauthn boolean;
BEGIN
  -- Auth gate. p_require_user_jwt = true means provision_secret-only is
  -- rejected. The signed envelope still works (legitimate ops always
  -- pair it with a real session JWT in the Authorization header), but
  -- a Vercel-compromise that lacks a real user_jwt cannot proceed.
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_save_totp_secret', true);
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;

  -- Look up the caller from auth.uid().
  SELECT role, email, auth_user_id
    INTO v_caller_role, v_caller_email, v_caller_auth_id
    FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true;
  IF v_caller_email IS NULL THEN
    RAISE EXCEPTION 'Caller profile not found';
  END IF;

  v_self_save := (lower(p_email) = lower(v_caller_email));

  -- Authorisation: self-save is always allowed; admin/senior may save
  -- on behalf of another user (e.g. operator-assisted recovery). No
  -- other roles may write someone else's secret.
  IF NOT v_self_save AND v_caller_role NOT IN ('admin', 'senior') THEN
    RAISE EXCEPTION 'Can only save your own MFA secret';
  END IF;

  -- Proof-of-possession check: the verification code must be valid for
  -- the secret being saved. This stops an attacker who has stolen a
  -- session JWT from rotating the victim's TOTP to one the attacker
  -- controls without also possessing the new secret on their device.
  -- The check uses the same _totp_check that rpc_verify_totp uses.
  IF p_verification_code IS NULL OR length(p_verification_code) < 6 THEN
    RAISE EXCEPTION 'Verification code required';
  END IF;
  v_code_ok := public._totp_check(p_totp_secret, p_verification_code);
  IF NOT v_code_ok THEN
    RAISE EXCEPTION 'Invalid verification code';
  END IF;

  -- Look up target. Must exist and be active.
  SELECT id, auth_user_id, (totp_secret IS NOT NULL AND totp_secret != '')
    INTO v_target_id, v_target_auth_id, v_was_set
    FROM public.profiles
    WHERE lower(email) = lower(p_email) AND active = true;
  IF v_target_id IS NULL THEN
    RAISE EXCEPTION 'Target profile not found';
  END IF;

  -- Freshness gate. The earlier version of this function refused to change an
  -- authenticator unless the caller had already passed MFA in this session, and
  -- that guard was lost when the function was rewritten with a verification
  -- code. The code alone is not equivalent: it proves possession of the NEW
  -- secret, which an attacker holding a stolen session also has, so without
  -- this a session on its own was enough to swap in an authenticator the
  -- attacker controls.
  --
  -- FIRST-EVER enrolment stays open, because there is nothing to prove yet.
  -- Once the target has ANY method (authenticator OR passkey), or the caller is
  -- acting on someone else's behalf, a fresh verification is required. Adding a
  -- backup authenticator right after enrolling a passkey still works: the
  -- tr_mfa_stamp_on_webauthn trigger stamps mfa_verified_at when the credential
  -- is registered, so that session is already fresh.
  IF v_target_auth_id IS NOT NULL THEN
    SELECT count(*) > 0 INTO v_has_webauthn
      FROM public.webauthn_credentials WHERE auth_user_id = v_target_auth_id;
  ELSE
    v_has_webauthn := false;
  END IF;
  IF (v_was_set OR v_has_webauthn OR NOT v_self_save) AND NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Current MFA verification required to change an authenticator';
  END IF;

  -- Apply the new secret and reset attempt counters.
  -- The column guard on profiles rejects any change to totp_secret unless the
  -- caller is admin/senior. This function is SECURITY DEFINER but auth.uid() is
  -- still the CALLER's, so that branch never applied and enrolling an
  -- authenticator failed with "Cannot change MFA config" for every other role,
  -- clients included. Authorisation is already settled above (own email, or
  -- admin/senior, plus the verification code and the freshness gate when
  -- REPLACING one), so raise the flag the guard provides for exactly this case
  -- and drop it immediately after so nothing else inherits it.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles
    SET totp_secret = p_totp_secret,
        totp_attempts = 0,
        totp_locked_until = NULL,
        updated_at = now()
    WHERE id = v_target_id;
  PERFORM set_config('pental.bypass_protect', 'false', true);

  -- Stamp mfa_verified_at ONLY when the caller is saving their own
  -- secret. Admin-on-behalf save sets up the secret but does NOT grant
  -- the target a fresh-MFA session, the target must verify on their
  -- next sign-in. Without this guard, an admin (or anyone with the
  -- admin's session) could pre-stamp arbitrary users.
  IF v_self_save THEN
    -- The stamp is a freshness optimisation; if it cannot write (for example
    -- auth schema privileges differ on this project), the enrolment itself
    -- must still succeed. The user simply verifies on next sign-in.
    BEGIN
      PERFORM public._stamp_mfa_verified(v_caller_auth_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'rpc_save_totp_secret: mfa freshness stamp failed (%), continuing', SQLERRM;
    END;
  END IF;

  -- Notification, same content as the older non-signed version. Also
  -- non-fatal: a queue failure must never undo a successful enrolment.
  BEGIN
  PERFORM public._queue_security_notif(
    'notify_mfa_changed',
    CASE WHEN v_was_set THEN 'MFA authenticator updated' ELSE 'MFA authenticator enabled' END,
    format(
      '<p>The authenticator app for <strong>%s</strong> has been %s.</p>'
      '<p>If this was not you, revoke active sessions in your portal Security settings and contact your administrator.</p>',
      public._html_esc(lower(p_email)), CASE WHEN v_was_set THEN 'updated' ELSE 'enabled' END
    ),
    v_target_id,
    lower(p_email)
  );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'rpc_save_totp_secret: security notification failed (%), continuing', SQLERRM;
  END;

  RETURN true;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_save_totp_secret(text, text, text, text, jsonb)
  TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 18. SHOW USER THE INSTALL TOKEN AFTER SQL RUN
-- ═══════════════════════════════════════════════════════════════════════════
-- NOTE: this is purely a helper message. The wizard will call rpc_bulk_clean
-- as part of setup anyway; the install_token the customer sees here is only
-- useful if they're doing CLI-based install (rare). Most customers never see
-- this because the wizard handles everything.
DO $$
BEGIN
  RAISE NOTICE '';
  RAISE NOTICE '════════════════════════════════════════════════════════════';
  RAISE NOTICE 'PENTAL BYO SECURITY PATCH APPLIED SUCCESSFULLY';
  RAISE NOTICE '════════════════════════════════════════════════════════════';
  RAISE NOTICE 'Next steps:';
  RAISE NOTICE '  1. Return to the Pental setup wizard';
  RAISE NOTICE '  2. Paste your Supabase project URL + publishable key';
  RAISE NOTICE '  3. Pental will handle the rest automatically';
  RAISE NOTICE '';
END $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-bulk-ops-install-token-gate.sql ━━
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- byo-bulk-ops-install-token-gate.sql
--
-- Applies on top of byo-database.sql + byo-database-security-patch.sql.
--
-- PURPOSE
-- Closes the Vercel-compromise → full tenant takeover path that exists via
-- rpc_bulk_import / rpc_bulk_auth / rpc_bulk_import_keys. These ops currently
-- accept provision_secret, which Pental's Vercel holds for every BYO (stored
-- on master.tenants). A Vercel-compromise attacker can therefore:
--
--   1. Call rpc_bulk_auth to create an auth.users row with their chosen
--      password, for an email they inject
--   2. Call rpc_bulk_import with a 'profiles' payload setting role='admin',
--      active=true, totp_secret=<known>, auth_user_id=<matching>
--   3. Sign into the BYO's Supabase via password grant, gets a session
--   4. Call rpc_verify_totp with a TOTP code derived from the secret they
--      just planted, stamps mfa_verified_at on the JWT
--   5. Refresh the JWT, RLS now passes mfa_is_fresh(), read everything
--
-- The bulk ops were designed for one-time master→BYO migration. They should
-- never be callable after migration completes. This patch enforces that.
--
-- APPROACH
-- The install_token generated by rpc_bulk_clean already exists. It's
-- currently consumed by rpc_install_pental_keys, then discarded. This patch:
--
--   1. Decouples key installation from install_token consumption. After
--      this patch, rpc_install_pental_keys installs keys but does NOT clear
--      the token.
--   2. Gates rpc_bulk_import / rpc_bulk_auth / rpc_bulk_import_keys on
--      install_token being present-and-valid, not on provision_secret.
--   3. Introduces rpc_provisioning_complete(install_token) as the explicit
--      terminator that clears the token. Pental's migration calls this at
--      the end of migration, OR after first-install + keys planted.
--
-- Flow after patch:
--   rpc_bulk_clean()                   → returns provision_secret + install_token
--   rpc_install_pental_keys(tok, ...)  → installs keys, token REMAINS valid
--   rpc_bulk_import(tok, table, rows)  → accepts tok, writes data
--   rpc_bulk_auth(tok, profiles)       → accepts tok, creates auth.users
--   rpc_bulk_import_keys(tok, ...)     → accepts tok, writes encryption keys
--   rpc_provisioning_complete(tok)     → consumes tok, future bulk calls fail
--
-- After rpc_provisioning_complete, bulk ops return 'Install token required'
-- until the BYO operator runs rpc_bulk_clean again (which only works with the
-- current provision_secret, i.e. from master, so an attacker with just a
-- previously-valid provision_secret can't use it without master cooperation).
--
-- Vercel-compromise impact AFTER this patch:
--   - Cannot inject admin profile (no install_token)
--   - Cannot create auth.users (no install_token)
--   - Cannot replace encryption keys (no install_token)
--   - Can still call rpc_bulk_clean, but that wipes the database, making
--     it destructive rather than exfiltrative, and it's audit-logged and
--     single-use (advisory lock). Destructive catastrophe is real but
--     NOT the silent data theft we're preventing here.
--
-- CALLER MIGRATION
-- Callers must pass p_install_token. The Pental migration code
-- (website/src/lib/master-to-byo-migration.js and
-- website/src/app/api/tenant-setup/route.js) needs to:
--   1. Receive install_token from rpc_bulk_clean (already does)
--   2. Hold onto it through the entire migration
--   3. Pass it as p_install_token to every bulk_* call
--   4. Call rpc_provisioning_complete at the end
--
-- BACKWARD COMPATIBILITY
-- This patch does NOT preserve the old signatures that accept only
-- provision_secret. After applying, any call without a valid install_token
-- fails. If the migration code hasn't been updated to pass install_token,
-- migrations break. This is deliberate, the whole point is to make these
-- RPCs callable only during the provisioning window.
-- ═══════════════════════════════════════════════════════════════════════════


-- ── rpc_install_pental_keys: remove the install_token consumption ──────────
-- Keys can be (re-)installed as many times as needed during provisioning.
-- The token is only consumed by the explicit rpc_provisioning_complete.
--
-- 1798: A PLANTED KEY IS NEVER REPLACED BY A TOKEN. The two keys are what
-- every signed call is checked against, so whoever replaces them can sign
-- anything this database accepts. A slot may be written only while it is
-- empty (a wipe empties both, so provisioning is unchanged) or with the key it
-- already holds (a retry). Two tokens open this function and nothing else:
-- the one a wipe issues, which opens the whole provisioning window, and a
-- key-repair token from rpc_reissue_install_token, which is spent here.
--
-- A repair token is checked here and nowhere else. It is stored as
-- "<sha256 hex>|<epoch issued>" and lives ten minutes.
CREATE OR REPLACE FUNCTION public._pental_repair_token_ok(p_token text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, vault, extensions, pg_catalog, pg_temp AS $$
DECLARE v_stored text; v_issued bigint;
BEGIN
  IF p_token IS NULL OR length(p_token) < 32 THEN RETURN false; END IF;
  SELECT decrypted_secret INTO v_stored FROM vault.decrypted_secrets
   WHERE name = 'key_repair_token_hash' LIMIT 1;
  IF v_stored IS NULL OR v_stored !~ '^[0-9a-f]{32,128}\|[0-9]{1,12}$' THEN RETURN false; END IF;
  v_issued := split_part(v_stored, '|', 2)::bigint;
  IF extract(epoch FROM now())::bigint - v_issued > 600 THEN RETURN false; END IF;
  RETURN split_part(v_stored, '|', 1) = encode(extensions.digest(p_token, 'sha256'), 'hex');
END;
$$;
REVOKE EXECUTE ON FUNCTION public._pental_repair_token_ok(text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_install_pental_keys(
  p_install_token text,
  p_pubkey_a_b64  text,
  p_pubkey_b_b64  text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_expected_hash text;
  v_via text;
  v_new_a bytea;
  v_new_b bytea;
  v_cur_a bytea;
  v_cur_b bytea;
  v_pubkey_a_slot uuid;
  v_pubkey_b_slot uuid;
  v_repair_slot uuid;
BEGIN
  IF p_install_token IS NULL OR length(p_install_token) < 32 THEN
    RETURN jsonb_build_object('error', 'Invalid install token');
  END IF;
  v_expected_hash := public._pental_install_token_hash();
  IF COALESCE(v_expected_hash, '') <> ''
     AND encode(extensions.digest(p_install_token, 'sha256'), 'hex') = v_expected_hash THEN
    v_via := 'install_token';
  ELSIF public._pental_repair_token_ok(p_install_token) THEN
    v_via := 'key_repair';
  ELSIF COALESCE(v_expected_hash, '') = '' THEN
    RETURN jsonb_build_object('error', 'Install token already consumed or not provisioned. Re-run rpc_bulk_clean to reset.');
  ELSE
    RETURN jsonb_build_object('error', 'Invalid install token');
  END IF;

  -- Validate Ed25519 pubkey shapes
  BEGIN
    v_new_a := decode(p_pubkey_a_b64, 'base64');
    v_new_b := decode(p_pubkey_b_b64, 'base64');
    IF octet_length(v_new_a) != 32 THEN
      RETURN jsonb_build_object('error', 'pubkey_a must be 32-byte Ed25519 public key');
    END IF;
    IF octet_length(v_new_b) != 32 THEN
      RETURN jsonb_build_object('error', 'pubkey_b must be 32-byte Ed25519 public key');
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('error', 'pubkey decode failed');
  END;

  -- A slot holding anything that is not a 32-byte key is broken, and the
  -- verifier already treats it as missing, so it may be filled.
  BEGIN v_cur_a := public._pental_pubkey_a(); EXCEPTION WHEN OTHERS THEN v_cur_a := NULL; END;
  BEGIN v_cur_b := public._pental_pubkey_b(); EXCEPTION WHEN OTHERS THEN v_cur_b := NULL; END;
  IF (COALESCE(octet_length(v_cur_a), 0) = 32 AND v_cur_a IS DISTINCT FROM v_new_a)
     OR (COALESCE(octet_length(v_cur_b), 0) = 32 AND v_cur_b IS DISTINCT FROM v_new_b) THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES ('rpc_install_pental_keys', v_via, 'rejected', 'keys already planted');
    RETURN jsonb_build_object('error',
      'Pental''s signing keys are already installed on this database, and an install token does not replace them.',
      'keys_planted', true);
  END IF;

  SELECT id INTO v_pubkey_a_slot FROM vault.decrypted_secrets WHERE name = 'pental_pubkey_a';
  SELECT id INTO v_pubkey_b_slot FROM vault.decrypted_secrets WHERE name = 'pental_pubkey_b';
  IF v_pubkey_a_slot IS NULL OR v_pubkey_b_slot IS NULL THEN
    RETURN jsonb_build_object('error', 'Vault slots missing, patch not fully applied');
  END IF;

  PERFORM vault.update_secret(v_pubkey_a_slot, p_pubkey_a_b64);
  PERFORM vault.update_secret(v_pubkey_b_slot, p_pubkey_b_b64);

  -- NOTE: the install_token is NOT consumed here. It's consumed explicitly
  -- by rpc_provisioning_complete at the end of migration. A repair token has
  -- done its one job, so it is spent.
  IF v_via = 'key_repair' THEN
    SELECT id INTO v_repair_slot FROM vault.decrypted_secrets WHERE name = 'key_repair_token_hash';
    IF v_repair_slot IS NOT NULL THEN PERFORM vault.update_secret(v_repair_slot, ''); END IF;
  END IF;

  INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result)
    VALUES ('rpc_install_pental_keys', v_via, 'ok');

  -- Read back in the same call, so a repair needs no second token.
  RETURN jsonb_build_object('success', true,
    'both_planted', COALESCE(octet_length(public._pental_pubkey_a()), 0) = 32
                AND COALESCE(octet_length(public._pental_pubkey_b()), 0) = 32);
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_install_pental_keys(text, text, text) TO anon, authenticated, service_role;


-- ── Helper: verify install_token, raise if missing/invalid ─────────────────
CREATE OR REPLACE FUNCTION public._verify_install_token(p_install_token text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_expected_hash text;
  v_provided_hash text;
BEGIN
  v_expected_hash := public._pental_install_token_hash();
  IF v_expected_hash IS NULL OR v_expected_hash = '' THEN
    RAISE EXCEPTION 'Provisioning window closed. Install token consumed or not issued. Call rpc_bulk_clean to reopen.' USING ERRCODE = '42501';
  END IF;
  IF p_install_token IS NULL OR length(p_install_token) < 32 THEN
    RAISE EXCEPTION 'Invalid install token' USING ERRCODE = '42501';
  END IF;
  v_provided_hash := encode(extensions.digest(p_install_token, 'sha256'), 'hex');
  IF v_provided_hash IS DISTINCT FROM v_expected_hash THEN
    RAISE EXCEPTION 'Invalid install token' USING ERRCODE = '42501';
  END IF;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._verify_install_token(text) FROM PUBLIC, anon, authenticated;


-- ── rpc_bulk_import: now requires p_install_token ─────────────────────────
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text, jsonb);

CREATE OR REPLACE FUNCTION public.rpc_bulk_import(
  p_install_token text,
  p_table         text,
  p_rows          jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  r jsonb;
  v_inserted integer := 0;
  v_errors   integer := 0;
  v_last_err text := '';
  v_cols     text[];
  v_col_types text[];
  v_sql      text;
  v_key      text;
  v_vals     text[];
  v_col_list text;
  v_col_type text;
  v_idx      int;
BEGIN
  PERFORM public._verify_install_token(p_install_token);
  PERFORM set_config('pental.bypass_protect', 'true', true);

  IF p_rows IS NULL OR jsonb_typeof(p_rows) != 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN jsonb_build_object('success', true, 'inserted', 0, 'errors', 0);
  END IF;

  -- Reject internal/secret-bearing tables
  IF p_table IN ('_internal_secrets', '_credentials_key', '_encryption_keys') THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1,
                              'last_error', 'Table is reserved and cannot be imported');
  END IF;

  -- Special profiles_client_restore path (legacy, preserved)
  IF p_table = 'profiles_client_restore' THEN
    FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
      BEGIN
        UPDATE profiles SET client_id = (r->>'client_id')::uuid WHERE id = (r->>'id')::uuid;
      EXCEPTION WHEN OTHERS THEN v_errors := v_errors + 1; v_last_err := SQLERRM;
      END;
    END LOOP;
    RETURN jsonb_build_object('success', v_errors = 0,
                              'inserted', jsonb_array_length(p_rows) - v_errors,
                              'errors', v_errors, 'last_error', v_last_err);
  END IF;

  -- Discover columns and types for the target table
  SELECT array_agg(column_name ORDER BY ordinal_position),
         array_agg(udt_name    ORDER BY ordinal_position)
    INTO v_cols, v_col_types
  FROM information_schema.columns
  WHERE table_schema = 'public' AND table_name = p_table;

  IF v_cols IS NULL OR array_length(v_cols, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1,
                              'last_error', 'Unknown table: ' || p_table);
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    BEGIN
      v_vals := ARRAY[]::text[];
      v_col_list := NULL;
      FOR v_idx IN 1 .. array_length(v_cols, 1) LOOP
        v_key := v_cols[v_idx];
        v_col_type := v_col_types[v_idx];
        IF r ? v_key THEN
          IF v_col_list IS NULL THEN v_col_list := quote_ident(v_key);
          ELSE v_col_list := v_col_list || ',' || quote_ident(v_key); END IF;
          IF r->>v_key IS NULL OR r->v_key = 'null'::jsonb THEN
            v_vals := array_append(v_vals, 'NULL');
          ELSIF v_col_type IN ('jsonb', 'json') THEN
            v_vals := array_append(v_vals, quote_literal(r->v_key::text) || '::' || v_col_type);
          ELSE
            v_vals := array_append(v_vals, quote_literal(r->>v_key) || '::' || v_col_type);
          END IF;
        END IF;
      END LOOP;
      IF v_col_list IS NOT NULL THEN
        v_sql := format('INSERT INTO public.%I (%s) VALUES (%s) ON CONFLICT DO NOTHING',
                        p_table, v_col_list, array_to_string(v_vals, ','));
        EXECUTE v_sql;
        v_inserted := v_inserted + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_last_err := SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', v_errors = 0,
                            'inserted', v_inserted, 'errors', v_errors,
                            'last_error', v_last_err);
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_bulk_import(text, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_bulk_auth: now requires p_install_token ───────────────────────────
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text, jsonb);

CREATE OR REPLACE FUNCTION public.rpc_bulk_auth(
  p_install_token text,
  p_profiles      jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth, extensions, pg_temp AS $$
DECLARE
  r jsonb;
  v_created int := 0;
  v_errors  int := 0;
  v_auth_id uuid;
  v_email   text;
  v_password text;
BEGIN
  PERFORM public._verify_install_token(p_install_token);
  PERFORM set_config('pental.bypass_protect', 'true', true);

  IF p_profiles IS NULL OR jsonb_typeof(p_profiles) != 'array' THEN
    RETURN jsonb_build_object('success', true, 'created', 0, 'errors', 0);
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_profiles) LOOP
    BEGIN
      v_email := lower(trim(r->>'email'));
      v_password := r->>'password';
      IF v_email IS NULL OR v_email = '' THEN CONTINUE; END IF;

      SELECT id INTO v_auth_id FROM auth.users WHERE email = v_email;
      IF v_auth_id IS NOT NULL THEN CONTINUE; END IF;  -- already exists, skip

      -- Create auth.users row. Password left NULL so the user can't sign in
      -- via password grant until they complete a proper login code flow.
      INSERT INTO auth.users (
        id, instance_id, email, encrypted_password, email_confirmed_at, aud, role,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, recovery_token,
        phone_change, phone_change_token, reauthentication_token, is_sso_user, is_anonymous
      ) VALUES (
        (r->>'id')::uuid, '00000000-0000-0000-0000-000000000000', v_email,
        CASE WHEN v_password IS NOT NULL AND v_password != ''
             THEN extensions.crypt(v_password, extensions.gen_salt('bf')) ELSE NULL END,
        now(), 'authenticated', 'authenticated',
        jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
        jsonb_build_object('email', v_email),
        now(), now(),
        encode(extensions.gen_random_bytes(32), 'hex'),
        '', '', '', '', '', '', false, false
      );
      v_created := v_created + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', v_errors = 0, 'created', v_created, 'errors', v_errors);
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_bulk_auth(text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_bulk_import_keys: now requires p_install_token ────────────────────
DROP FUNCTION IF EXISTS public.rpc_bulk_import_keys(text, jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_bulk_import_keys(text, jsonb, text, jsonb);

CREATE OR REPLACE FUNCTION public.rpc_bulk_import_keys(
  p_install_token text,
  p_table         text,
  p_rows          jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  r jsonb;
  v_inserted integer := 0;
  v_errors   integer := 0;
  v_last_err text := '';
BEGIN
  PERFORM public._verify_install_token(p_install_token);
  PERFORM set_config('pental.bypass_protect', 'true', true);

  IF p_table NOT IN ('_internal_secrets', '_credentials_key', '_encryption_keys') THEN
    RETURN jsonb_build_object('success', false, 'inserted', 0, 'errors', 1,
                              'last_error', 'Only key tables allowed: _internal_secrets, _credentials_key, _encryption_keys');
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) != 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN jsonb_build_object('success', true, 'inserted', 0, 'errors', 0);
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    BEGIN
      IF p_table = '_internal_secrets' THEN
        INSERT INTO public._internal_secrets (key, value)
          VALUES (r->>'key', r->>'value')
          ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
      ELSIF p_table = '_credentials_key' THEN
        INSERT INTO public._credentials_key (id, key, created_at)
          VALUES ((r->>'id')::uuid, r->>'key', COALESCE((r->>'created_at')::timestamptz, now()))
          ON CONFLICT (id) DO NOTHING;
      ELSIF p_table = '_encryption_keys' THEN
        INSERT INTO public._encryption_keys (id, key, created_at)
          VALUES ((r->>'id')::uuid, r->>'key', COALESCE((r->>'created_at')::timestamptz, now()))
          ON CONFLICT (id) DO NOTHING;
      END IF;
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_last_err := SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', v_errors = 0,
                            'inserted', v_inserted, 'errors', v_errors,
                            'last_error', v_last_err);
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_bulk_import_keys(text, text, jsonb) TO anon, authenticated, service_role;


-- ── rpc_provisioning_complete: terminator ─────────────────────────────────
-- Consumes the install_token explicitly. After this call, bulk ops fail
-- with 'Provisioning window closed' until rpc_bulk_clean is called again.
CREATE OR REPLACE FUNCTION public.rpc_provisioning_complete(p_install_token text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault, pg_temp AS $$
DECLARE
  v_install_slot uuid;
BEGIN
  PERFORM public._verify_install_token(p_install_token);

  SELECT id INTO v_install_slot FROM vault.decrypted_secrets WHERE name = 'install_token_hash';
  IF v_install_slot IS NULL THEN
    RETURN jsonb_build_object('error', 'Install slot missing');
  END IF;

  PERFORM vault.update_secret(v_install_slot, '');
  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_provisioning_complete(text) TO anon, authenticated, service_role;


-- ── Audit trail: record token-gated calls ─────────────────────────────────
-- Uses the existing _pental_rpc_audit_log (no schema change needed).
-- Every bulk op triggers an audit row with auth_mode='install_token'.
-- Already handled implicitly because the RPCs write to the audit log via
-- the existing _validate_provision_secret path. We'll add an explicit
-- insert for clarity:
--
--   (This is optional; if the audit log isn't being written, these lines
--    can be added to each RPC body. Omitted here to keep the patch minimal.)


-- ── Sanity check ──────────────────────────────────────────────────────────
DO $rep$
DECLARE
  v_fn_count int;
BEGIN
  SELECT count(*) INTO v_fn_count
    FROM pg_proc p JOIN pg_namespace n ON p.pronamespace = n.oid
    WHERE n.nspname = 'public'
      AND p.proname IN ('rpc_bulk_import', 'rpc_bulk_auth',
                        'rpc_bulk_import_keys', 'rpc_provisioning_complete',
                        '_verify_install_token');
  IF v_fn_count < 5 THEN
    RAISE WARNING 'Bulk-ops-install-token patch did not install completely (% of 5 functions found)', v_fn_count;
  ELSE
    RAISE NOTICE 'Bulk-ops-install-token patch installed OK. Update your migration code to pass p_install_token to all bulk calls and to invoke rpc_provisioning_complete at the end.';
  END IF;
END $rep$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-close-vercel-exfil.sql ━━
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- byo-close-vercel-exfil.sql
--
-- Closes the Vercel-compromise → BYO data exfiltration hole while preserving
-- the narrow operational flows Pental actually needs:
--   - Branding sync from pental.io → portal (cosmetic fields only)
--   - Pental-staff MFA reset for locked-out customers (audited, detectable)
--   - Provisioning-time settings writes (install_token gated)
--
-- Apply AFTER:
--   website/byo-database.sql
--   website/byo-mfa-enforcement.sql
--   website/sql/byo-database-security-patch.sql
--   website/sql/byo-bulk-ops-install-token-gate.sql
--   website/sql/byo-management-token.sql
--
-- ═══════════════════════════════════════════════════════════════════════════
-- WHAT'S CHANGED
-- ═══════════════════════════════════════════════════════════════════════════
--
-- 1. DROP rpc_export_all. Full-database dump is gone. Downgrade migrations
--    use per-table exports already listed in pentalSign KNOWN_OPS.
--
-- 2. _pental_authorise gets a new signature taking p_require_user_jwt.
--    When true, auth.uid() MUST be set AND provision_secret is REJECTED.
--    Old 3-arg callers keep working (backward compatible).
--
-- 3. rpc_update_settings requires user_jwt. Writes ALL fields including SMTP.
--    Accepts p_install_token parameter for provisioning-time writes.
--
-- 4. rpc_update_settings_branding (NEW) accepts provision_secret. Writes
--    ONLY cosmetic fields (company_name, accent_color, theme_mode, logo_url,
--    favicon_data). This is the narrow server-to-server branding sync path.
--    No SMTP, no session policy, no financial settings, nothing sensitive.
--
-- 5. rpc_admin_reset_mfa_operator (NEW) accepts provision_secret. Clears MFA
--    for ONE specified email. Logs to _pental_ops_audit. Triggers a
--    security notification email via email_notifications queue. Narrow,
--    audited, detectable. Replaces the rpc_clear_mfa server-to-server path.
--
-- 6. rpc_clear_mfa and rpc_admin_reset_mfa require user_jwt. Used when an
--    admin resets MFA from within their portal (admin's own JWT authz).
--
-- 7. rpc_get_smtp_config, rpc_read_settings_server, rpc_get_admin_email
--    require user_jwt. No provision_secret path.
--
-- ═══════════════════════════════════════════════════════════════════════════
-- THREAT MODEL POST-PATCH
-- ═══════════════════════════════════════════════════════════════════════════
--
-- The architectural defence rests on three layers, each independently
-- protected:
--
--   Layer 1, auth-key separation:
--     - privkey_a (Ed25519) lives only in Vercel env
--     - privkey_b (Ed25519) lives only in cosigner Edge Function env
--     - HMAC secret is shared between Vercel and cosigner Edge Function
--   Layer 2, provision_secret gating:
--     - Sibling write RPCs (bulk_clean, bulk_import, admin_reset_mfa,
--       set_bridge_password) reject provision_secret-only auth
--   Layer 3, MFA-fresh RLS:
--     - 82 sensitive-table policies AND-gate on mfa_is_fresh()
--     - mfa_verified_at claim only set by:
--         * rpc_verify_totp, requires TOTP code from user's app
--         * rpc_save_totp_secret, requires proof-of-possession
--           verification code from the secret being saved
--
-- Master-Supabase-compromise alone: BYO data IS protected.
--   Master holds publishable keys + provision_secret. Cannot:
--     - mint signed envelopes (lacks privkey_a + HMAC)
--     - bridge passwords (sibling RPCs reject provision_secret only)
--     - set TOTP secrets without proof-of-possession code
--
-- Vercel-compromise alone: BYO data IS protected.
--   Vercel can mint signed envelopes (has privkey_a + HMAC + reaches
--   cosigner). Vercel can therefore call bridge_password, get a JWT,
--   sign in. But:
--     - The JWT has NO mfa_verified_at claim (set only on real TOTP
--       proof). So all 82 RLS policies still reject the session.
--     - To stamp mfa_verified_at, attacker must call rpc_save_totp_secret
--       with a verification code valid for a TOTP secret. They can
--       compute one for a secret THEY generate, but the function
--       requires user_jwt of the target user (matched via auth.uid()
--       == profiles.auth_user_id). Since they got the JWT via
--       bridge_password they DO have user_jwt for the victim. So they
--       could rotate the victim's TOTP secret to one they control AND
--       compute a code AND get the stamp.
--     - HOWEVER, that rotation is logged (notify_mfa_changed email
--       fires from BYO directly), the customer sees "MFA authenticator
--       updated" in their inbox, and the previous secret is wiped from
--       the user's authenticator app on next sign-in. The bypass is
--       detectable. To make it stealthy the attacker would need to
--       suppress the notification email, which originates from BYO's
--       SMTP and is triggered by a SECURITY DEFINER queue insert that
--       Vercel cannot suppress.
--     - In practice a defender sees the notification and rotates the
--       provision keys / forces re-provision. The window for data
--       exfiltration is bounded by mail-delivery latency.
--
--   Net: Vercel-compromise provides DETECTABLE temporary access, not
--   silent data exfiltration. Combined with Layer 2 hardening this is
--   the documented goal.
--
-- BYO-compromise: outside threat model (that IS the customer).
-- Joint compromise of any two layers: outside threat model.
--
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── 1. DROP rpc_export_all ──────────────────────────────────────────────
DROP FUNCTION IF EXISTS public.rpc_export_all();
DROP FUNCTION IF EXISTS public.rpc_export_all(text);


-- ─── 2. _pental_authorise: 4-arg version with user_jwt requirement ───────
DROP FUNCTION IF EXISTS public._pental_authorise(jsonb, text, text, boolean);

CREATE OR REPLACE FUNCTION public._pental_authorise(
  p_auth jsonb,
  p_secret text,
  p_expected_op text,
  p_require_user_jwt boolean DEFAULT false
) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_uid uuid;
  v_sig_ok boolean;
BEGIN
  v_uid := auth.uid();

  -- Signed auth path, checked FIRST. A valid signed-JWT proves Pental's
  -- HMAC keys are intact (separately administered from Vercel via the
  -- cosigner Edge Function). It satisfies p_require_user_jwt because it
  -- represents Pental-as-an-admin in the trust model.
  IF p_auth IS NOT NULL AND jsonb_typeof(p_auth) = 'object' THEN
    -- 1832: through the binding check. An envelope that arrives with this
    -- database's own provisioning secret (every call from the portal's servers
    -- carries it) binds the database to the firm it was made for; see
    -- _pental_bound_tenant.
    v_sig_ok := public._pental_verify_binding(p_auth, p_expected_op, p_secret);
    IF v_sig_ok THEN
      RETURN 'signed';
    END IF;
  END IF;

  -- User-JWT requirement gate. Set true for data-read and admin-mutation
  -- RPCs to block Vercel-compromise from calling them with just
  -- provision_secret. Vercel-compromise leaks provision_secret AND HMAC
  -- material on the Vercel side, but NOT the cosigner's sig_b key (separate
  -- Supabase project, separate admin). So a Vercel breach cannot produce a
  -- valid signed-JWT. provision_secret must therefore be rejected here.
  IF p_require_user_jwt AND v_uid IS NULL THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
      VALUES (p_expected_op, 'user_jwt', 'rejected', 'no user session');
    RETURN NULL;
  END IF;

  -- Provision-secret fallback. ONLY accepted when p_require_user_jwt is
  -- false (e.g. provisioning-time ops where install_token isn't available
  -- yet, or non-mutating utility RPCs).
  IF NOT p_require_user_jwt
     AND p_secret IS NOT NULL AND p_secret != ''
     AND public._validate_provision_secret(p_secret)
  THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result)
      VALUES (p_expected_op, 'provision_secret', 'ok');
    RETURN 'provision_secret';
  END IF;

  -- Authenticated user with no signed-auth payload: accept the user_jwt itself,
  -- but ONLY for a caller who has an active profile in this database. 1798:
  -- auth.uid() being set means only that SOMEBODY signed in. Supabase leaves
  -- public sign-up on unless the dashboard turns it off, so a stranger can mint
  -- a GoTrue session that has no profile here, and a deactivated user keeps a
  -- valid token until it expires. Neither is an authorised caller, and without
  -- this check 'user_jwt' was handed to both, which every caller that trusts a
  -- non-NULL result then believed.
  IF v_uid IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = v_uid AND active = true)
  THEN
    INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result)
      VALUES (p_expected_op, 'user_jwt', 'ok');
    RETURN 'user_jwt';
  END IF;

  INSERT INTO public._pental_rpc_audit_log (op, auth_mode, result, error_short)
    VALUES (p_expected_op, 'provision_secret', 'rejected', 'no valid auth');
  RETURN NULL;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._pental_authorise(jsonb, text, text, boolean) FROM PUBLIC, anon, authenticated;


-- ─── 3. Operator audit log ───────────────────────────────────────────────
-- Separate from the generic _pental_rpc_audit_log. Records every invocation
-- of the narrow "operator" RPCs (branding sync, operator MFA reset) so
-- Vercel-compromise activity is visible to the customer.
CREATE TABLE IF NOT EXISTS public._pental_ops_audit (
  id bigserial PRIMARY KEY,
  op text NOT NULL,
  target_email text,
  fields_changed jsonb,
  called_at timestamptz DEFAULT now(),
  caller_ip text
);
ALTER TABLE public._pental_ops_audit ENABLE ROW LEVEL SECURITY;
-- Admins can read this table via direct PostgREST (for ops transparency)
DROP POLICY IF EXISTS ops_audit_admin_read ON public._pental_ops_audit;
CREATE POLICY ops_audit_admin_read ON public._pental_ops_audit
  FOR SELECT TO authenticated
  USING (public.current_user_role() IN ('admin', 'senior'));
-- Nobody writes directly; only SECURITY DEFINER functions write
REVOKE INSERT, UPDATE, DELETE ON public._pental_ops_audit FROM PUBLIC, anon, authenticated;


-- ─── 4-5. Operator RPCs (DROPPED) ───────────────────────────────────────
-- Previously this file defined three narrow operator RPCs:
--   rpc_update_settings_branding (cosmetic-only writes)
--   rpc_update_smtp_operator     (SMTP writes)
--   rpc_admin_reset_mfa_operator (MFA reset on customer request)
--
-- All three accepted provision_secret. With WebAuthn-bound apply now in
-- place (byo-webauthn.sql + master-pending-settings.sql), pental.io NEVER
-- writes to BYO server-to-server. All settings changes are staged on
-- master and authorized by the admin's WebAuthn assertion in their portal.
-- MFA reset is a firm admin's action on the portal's Users screen (email
-- recovery is disabled); a firm with no admin able to sign in uses
-- public.owner_reset_mfa from its own database console. Pental cannot reset a
-- firm's MFA (1810).
--
-- Therefore: these three RPCs are NOT defined. Any caller still trying
-- to invoke them gets PostgREST 404, which is the right answer.

DROP FUNCTION IF EXISTS public.rpc_update_settings_branding(jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_update_settings_branding(jsonb, text, jsonb);
DROP FUNCTION IF EXISTS public.rpc_update_settings_branding(jsonb, jsonb);
DROP FUNCTION IF EXISTS public.rpc_update_smtp_operator(jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_admin_reset_mfa_operator(text, text);

-- ─── 1841: A WRITE FROM PENTAL'S SERVERS, ONCE THIS PORTAL SENDS ITS OWN EMAIL
-- Pental's servers still save the mail connection a firm sets up on
-- pental.io/manage (the mailbox it connects, the SMTP server it gives), which
-- nothing else can yet. Once the firm's own side sends (_mail_locked) they
-- cannot read the password or the refresh token kept here, and a write of
-- theirs may not be used to reach either: a stored password is never left
-- for a server or a username it was not given for (it is cleared, unless the
-- write brings one), and a write that would leave this portal nothing to send
-- with is refused, since Pental's servers no longer send in its place
-- (owner_mail_release is the way back). A firm administrator's own session is
-- not held to this. p_oauth: whether the caller writes the connection's own
-- columns. Answers the data to write, or { _refused: why }.
CREATE OR REPLACE FUNCTION public._mail_guard_signed(p_data jsonb, p_oauth boolean DEFAULT true) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $mlguard$
DECLARE s record; v jsonb := p_data; v_host text; v_user text; v_pass_after boolean; v_oauth_after boolean; v_smtp_after boolean;
  v_oauth_before boolean; v_smtp_before boolean;
BEGIN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT public._mail_locked() THEN RETURN v; END IF;
  SELECT smtp_host, smtp_user, smtp_pass, smtp_pass_enc, smtp_oauth_provider, smtp_oauth_refresh, smtp_oauth_refresh_enc
    INTO s FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;
  IF NOT FOUND THEN RETURN v; END IF;
  v_oauth_before := COALESCE(s.smtp_oauth_provider, '') <> '' AND (COALESCE(s.smtp_oauth_refresh, '') <> '' OR s.smtp_oauth_refresh_enc IS NOT NULL);
  v_smtp_before := COALESCE(s.smtp_host, '') <> '' AND COALESCE(s.smtp_user, '') <> '' AND (COALESCE(s.smtp_pass, '') <> '' OR s.smtp_pass_enc IS NOT NULL);
  v_host := COALESCE(v ->> 'smtp_host', s.smtp_host, '');
  v_user := COALESCE(v ->> 'smtp_user', s.smtp_user, '');
  IF COALESCE(v ->> 'smtp_pass', '') = '' AND (COALESCE(s.smtp_pass, '') <> '' OR s.smtp_pass_enc IS NOT NULL)
     AND (lower(btrim(v_host)) <> lower(btrim(COALESCE(s.smtp_host, ''))) OR btrim(v_user) <> btrim(COALESCE(s.smtp_user, ''))) THEN
    v := v || jsonb_build_object('smtp_pass', '');
  END IF;
  v_pass_after := CASE WHEN v ? 'smtp_pass' THEN COALESCE(v ->> 'smtp_pass', '') <> ''
                       ELSE COALESCE(s.smtp_pass, '') <> '' OR s.smtp_pass_enc IS NOT NULL END;
  v_smtp_after := btrim(v_host) <> '' AND btrim(v_user) <> '' AND v_pass_after;
  v_oauth_after := CASE WHEN NOT COALESCE(p_oauth, true) THEN v_oauth_before
    ELSE COALESCE(v ->> 'smtp_oauth_provider', s.smtp_oauth_provider, '') <> ''
         AND CASE WHEN v ? 'smtp_oauth_refresh' THEN COALESCE(v ->> 'smtp_oauth_refresh', '') <> ''
                  ELSE COALESCE(s.smtp_oauth_refresh, '') <> '' OR s.smtp_oauth_refresh_enc IS NOT NULL END END;
  IF (v_oauth_before OR v_smtp_before) AND NOT (v_oauth_after OR v_smtp_after) THEN
    RETURN jsonb_build_object('_refused', 'This portal sends its own email, and Pental''s servers no longer send it in its place, '
      || 'so its mailbox or mail server is not removed from here: connect another to replace it. Your database''s owner can '
      || 'hand email back to Pental from its SQL console (SELECT public.owner_mail_release();).');
  END IF;
  RETURN v;
END $mlguard$;
REVOKE ALL ON FUNCTION public._mail_guard_signed(jsonb, boolean) FROM PUBLIC, anon, authenticated;

-- ─── rpc_update_settings_branding, narrow cosmetic+SMTP push, cosigner-gated
-- Used by /api/complete-setup's post-provisioning branding push, where no
-- user JWT exists yet. Strict field whitelist (cosmetic + SMTP + currency).
CREATE OR REPLACE FUNCTION public.rpc_update_settings_branding(
  p_data jsonb,
  p_auth jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp
AS $$
DECLARE
  v_sig_ok boolean;
  v_key text;
  v_filtered jsonb := '{}'::jsonb;
  v_allowed text[] := ARRAY[
    'company_name','accent_color','theme_mode','logo_url','logo_url_light',
    'favicon_url','favicon_data',  -- accept both input keys; write to the column that exists on this DB (favicon_data on BYO)
    'company_email','login_support_email','portal_title',
    'smtp_host','smtp_port','smtp_user','smtp_pass','smtp_oauth_provider','smtp_oauth_user','smtp_oauth_refresh','smtp_oauth_verified_at','smtp_from_name','smtp_from_email','notify_reply_to_email',
    'email_enabled','theme_dark','theme_light',
    'currency_code','currency_symbol','automation_timezone',
    'login_title','login_subtitle','login_button_text','login_custom_text',
    'login_show_logo','login_show_company_name','login_show_title',
    'plan_max_users','plan_max_clients','notes_prompt','caveats_prompt'
  ];
BEGIN
  IF p_auth IS NULL OR jsonb_typeof(p_auth) != 'object' THEN
    RAISE EXCEPTION 'Signed envelope required';
  END IF;
  v_sig_ok := public._verify_pental_auth(p_auth, 'rpc_update_settings_branding');
  IF NOT v_sig_ok THEN RAISE EXCEPTION 'Invalid signed envelope'; END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_data) LOOP
    IF v_key = ANY(v_allowed) THEN
      v_filtered := v_filtered || jsonb_build_object(v_key, p_data->v_key);
    END IF;
  END LOOP;
  IF v_filtered = '{}'::jsonb THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No allowed fields');
  END IF;
  -- 1841: within _mail_guard_signed, once this portal sends its own email.
  v_filtered := public._mail_guard_signed(v_filtered, true);
  IF v_filtered ? '_refused' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'mail_locked', 'error', v_filtered ->> '_refused');
  END IF;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  -- Self-heal: if the seed row is missing for any reason, create it so this
  -- write lands somewhere instead of updating zero rows and silently doing
  -- nothing (which is exactly how branding/SMTP appears to save but shows
  -- defaults on reload).
  IF NOT EXISTS (SELECT 1 FROM public.settings) THEN
    INSERT INTO public.settings (company_name) VALUES ('');
  END IF;
  -- 804: the signed path announces itself so `tr_guard_plan_limits` lets the
  -- cap columns through. Set LOCAL, so it lasts one statement and cannot be
  -- left switched on for anything that runs afterwards.
  PERFORM set_config('pental.signed_update', '1', true);
  UPDATE public.settings SET
    company_name = COALESCE((v_filtered->>'company_name'), company_name),
    accent_color = COALESCE((v_filtered->>'accent_color'), accent_color),
    theme_mode = COALESCE((v_filtered->>'theme_mode'), theme_mode),
    logo_url = COALESCE((v_filtered->>'logo_url'), logo_url),
    logo_url_light = COALESCE((v_filtered->>'logo_url_light'), logo_url_light),
    password_login_enabled = COALESCE((v_filtered->>'password_login_enabled')::boolean, password_login_enabled),
    font_display = COALESCE((v_filtered->>'font_display')::text, font_display),
    font_body = COALESCE((v_filtered->>'font_body')::text, font_body),
    font_mono = COALESCE((v_filtered->>'font_mono')::text, font_mono),
    pdf_font_body = COALESCE((v_filtered->>'pdf_font_body')::text, pdf_font_body),
    pdf_font_heading = COALESCE((v_filtered->>'pdf_font_heading')::text, pdf_font_heading),
    email_font = COALESCE((v_filtered->>'email_font')::text, email_font),
    pdf_logo_variant = COALESCE((v_filtered->>'pdf_logo_variant'), pdf_logo_variant),
    email_logo_variant = COALESCE((v_filtered->>'email_logo_variant'), email_logo_variant),
    -- Both favicon columns exist (the schema migration above ensured this).
    -- Write to both so older portal builds reading favicon_data and newer
    -- builds reading favicon_url see the same value.
    favicon_data = COALESCE((v_filtered->>'favicon_data'), (v_filtered->>'favicon_url'), favicon_data),
    favicon_url = COALESCE((v_filtered->>'favicon_url'), (v_filtered->>'favicon_data'), favicon_url),
    company_email = COALESCE((v_filtered->>'company_email'), company_email),
    login_support_email = COALESCE((v_filtered->>'login_support_email'), login_support_email),
    portal_title = COALESCE((v_filtered->>'portal_title'), portal_title),
    smtp_host = COALESCE((v_filtered->>'smtp_host'), smtp_host),
    smtp_port = COALESCE((v_filtered->>'smtp_port')::int, smtp_port),
    smtp_user = COALESCE((v_filtered->>'smtp_user'), smtp_user),
    smtp_pass = COALESCE((v_filtered->>'smtp_pass'), smtp_pass),
    -- 1397 (2025090501): THE THREE CONNECTION COLUMNS WERE ALLOW-LISTED AND
    -- NEVER SET. Every key passed the filter above, the UPDATE ran, and none
    -- of these columns was in it, so a connected mailbox saved with "ok" and
    -- stored nothing. 1363's harness wrote the columns with a raw UPDATE and
    -- proved only the read side. A cleared secret ('') also clears its
    -- ciphertext: the encrypting trigger only clears the old ciphertext when a
    -- NEW value arrives, so writing '' alone left the previous token readable.
    smtp_oauth_provider = COALESCE((v_filtered->>'smtp_oauth_provider'), smtp_oauth_provider),
    smtp_oauth_user = COALESCE((v_filtered->>'smtp_oauth_user'), smtp_oauth_user),
    smtp_oauth_refresh = COALESCE((v_filtered->>'smtp_oauth_refresh'), smtp_oauth_refresh),
    -- 1402: '' clears it, an ISO timestamp sets it. A new connection always
    -- arrives unverified, because storing it clears the three columns first.
    smtp_oauth_verified_at = CASE WHEN v_filtered ? 'smtp_oauth_verified_at'
      THEN NULLIF(v_filtered->>'smtp_oauth_verified_at','')::timestamptz ELSE smtp_oauth_verified_at END,
    smtp_oauth_refresh_enc = CASE WHEN (v_filtered ? 'smtp_oauth_refresh') AND COALESCE(v_filtered->>'smtp_oauth_refresh', '') = ''
      THEN NULL ELSE smtp_oauth_refresh_enc END,
    smtp_pass_enc = CASE WHEN (v_filtered ? 'smtp_pass') AND COALESCE(v_filtered->>'smtp_pass', '') = ''
      THEN NULL ELSE smtp_pass_enc END,
    smtp_from_name = COALESCE((v_filtered->>'smtp_from_name'), smtp_from_name),
    smtp_from_email = COALESCE((v_filtered->>'smtp_from_email'), smtp_from_email),
    -- 1410 (2025090503): the Reply-To, settable where the sender is set. It
    -- reached the mailer all along but there was nowhere to enter it, so a
    -- firm's replies fell back to company_email or to nothing. '' clears it.
    notify_reply_to_email = CASE WHEN v_filtered ? 'notify_reply_to_email'
      THEN NULLIF(v_filtered->>'notify_reply_to_email','') ELSE notify_reply_to_email END,
    email_enabled = COALESCE((v_filtered->>'email_enabled')::boolean, email_enabled),
    theme_dark = COALESCE((v_filtered->'theme_dark'), theme_dark),
    theme_light = COALESCE((v_filtered->'theme_light'), theme_light),
    currency_code = COALESCE((v_filtered->>'currency_code'), currency_code),
    currency_symbol = COALESCE((v_filtered->>'currency_symbol'), currency_symbol),
    -- 1824 (2025100201): the zone a new portal's automations run in, set at
    -- provisioning from the person setting it up (complete-setup). Only a zone
    -- Postgres knows is written, so a name the cron could not read never lands;
    -- anything else leaves the column as it was (the Europe/London default).
    automation_timezone = CASE WHEN (v_filtered ? 'automation_timezone')
        AND EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_filtered->>'automation_timezone')
      THEN v_filtered->>'automation_timezone' ELSE automation_timezone END,
    login_title = COALESCE((v_filtered->>'login_title'), login_title),
    login_subtitle = COALESCE((v_filtered->>'login_subtitle'), login_subtitle),
    login_button_text = COALESCE((v_filtered->>'login_button_text'), login_button_text),
    login_custom_text = COALESCE((v_filtered->>'login_custom_text'), login_custom_text),
    login_show_logo = COALESCE((v_filtered->>'login_show_logo')::boolean, login_show_logo),
    login_show_company_name = COALESCE((v_filtered->>'login_show_company_name')::boolean, login_show_company_name),
    login_show_title = COALESCE((v_filtered->>'login_show_title')::boolean, login_show_title),
    sso_google_enabled = COALESCE((v_filtered->>'sso_google_enabled')::boolean, sso_google_enabled),
    sso_microsoft_enabled = COALESCE((v_filtered->>'sso_microsoft_enabled')::boolean, sso_microsoft_enabled),
    plan_max_users = CASE WHEN v_filtered ? 'plan_max_users' THEN NULLIF(v_filtered->>'plan_max_users','')::integer ELSE plan_max_users END,
    plan_max_clients = CASE WHEN v_filtered ? 'plan_max_clients' THEN NULLIF(v_filtered->>'plan_max_clients','')::integer ELSE plan_max_clients END,
    updated_at = now()
  WHERE id IS NOT NULL;
  PERFORM set_config('pental.bypass_protect', 'false', true);

  RETURN jsonb_build_object('ok', true);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_update_settings_branding(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_update_settings_branding(jsonb, jsonb) TO anon, authenticated, service_role;


-- ─── 6. rpc_update_settings, require user_jwt, add p_install_token escape
DROP FUNCTION IF EXISTS public.rpc_update_settings(jsonb, text);
DROP FUNCTION IF EXISTS public.rpc_update_settings(jsonb, text, jsonb);
DROP FUNCTION IF EXISTS public.rpc_update_settings(jsonb, text, jsonb, text);
CREATE OR REPLACE FUNCTION public.rpc_update_settings(
  p_data jsonb,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL,
  p_install_token text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_mode text;
  v_key text;
  v_filtered jsonb := '{}'::jsonb;
  v_allowed text[] := ARRAY[
    -- Full settings surface, only accessible with user_jwt or install_token
    'company_name','accent_color','theme_mode','logo_url','logo_url_light','pdf_logo_variant','email_logo_variant','password_login_enabled','font_display','font_body','font_mono','pdf_font_body','pdf_font_heading','email_font','favicon_data',
    'company_email','login_support_email','portal_title',
    'smtp_host','smtp_port','smtp_user','smtp_pass','smtp_oauth_provider','smtp_oauth_user','smtp_oauth_refresh','smtp_from_name','smtp_from_email',
    'email_enabled','email_templates',
    'severity_colors','severity_style','notification_color','toast_success_color',
    'theme_dark','theme_light','google_api_key',
    'session_timeout_minutes','session_timeout_action','session_signout_minutes','session_refresh_buffer_minutes',
    'day_rate','currency_code','currency_symbol','vat_rate','vat_number',
    'stripe_enabled','stripe_publishable_key','stripe_success_url',
    'bank_account_name','bank_name','bank_sort_code','bank_account_number',
    'pdf_templates','filename_templates','assessment_types',
    'show_tester_teams','show_tester_slack','feedback_mode','google_review_url','loa_visibility',
    'sig_name','sig_title','sig_email','sig_phone','sig_teams','sig_slack','sig_html','email_signature_enabled',
    'loa_signatory_name','loa_signatory_title','loa_signature_data',
    'notify_test_started','notify_test_ended','notify_critical_finding','notify_proposal_sent',
    'notify_invoice_sent','notify_tester_assigned','notify_credentials_submitted','notify_comment_reply',
    'notify_report_delivered','notify_new_sign_in','notify_new_device_sign_in','notify_mfa_changed',
    'notify_role_changed','notify_user_created','notify_session_revoked',
    'proposals_enabled','invoices_enabled','feedback_enabled',
    'meet_calendar_enabled','meetings_enabled','contacts_enabled','dashboard_enabled',
    'dashboard_layouts','login_title','login_subtitle','login_button_text',
    'login_custom_text','login_show_logo','login_show_company_name','login_show_title','sso_google_enabled','sso_microsoft_enabled',
    'contact_integration','meeting_integration','teams_tenant_id','teams_client_id',
    'teams_client_secret','teams_user_email'
  ];
BEGIN
  -- Install-token escape for provisioning-time writes (pre-user-exists on BYO).
  -- Token is consumed by rpc_provisioning_complete; after that this branch
  -- is dead and every caller must present a user_jwt.
  IF p_install_token IS NOT NULL AND p_install_token != '' THEN
    IF NOT public._check_install_token(p_install_token) THEN
      RAISE EXCEPTION 'Invalid install token';
    END IF;
  ELSE
    v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_update_settings', true);
    IF v_mode IS NULL THEN RAISE EXCEPTION 'Invalid secret or session required'; END IF;
    -- 1798: a session is enough only for the firm's administrators. Any active
    -- profile reaches 'user_jwt', a client's included, and this writes the
    -- mail server, sign-in switches and payment keys.
    IF v_mode = 'user_jwt' AND public.current_user_role() NOT IN ('admin', 'senior') THEN
      RAISE EXCEPTION 'Not authorised';
    END IF;
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_data) LOOP
    IF v_key = ANY(v_allowed) THEN
      v_filtered := v_filtered || jsonb_build_object(v_key, p_data->v_key);
    END IF;
  END LOOP;
  -- 1841: a signed write, within _mail_guard_signed once this portal sends
  -- its own email (this one does not write the connection's own columns).
  IF v_mode = 'signed' THEN
    v_filtered := public._mail_guard_signed(v_filtered, false);
    IF v_filtered ? '_refused' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'mail_locked', 'error', v_filtered ->> '_refused');
    END IF;
  END IF;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  -- 804: the signed path announces itself so `tr_guard_plan_limits` lets the
  -- cap columns through. Set LOCAL, so it lasts one statement and cannot be
  -- left switched on for anything that runs afterwards.
  PERFORM set_config('pental.signed_update', '1', true);
  UPDATE public.settings SET
    company_name = COALESCE((v_filtered->>'company_name'), company_name),
    accent_color = COALESCE((v_filtered->>'accent_color'), accent_color),
    theme_mode = COALESCE((v_filtered->>'theme_mode'), theme_mode),
    logo_url = COALESCE((v_filtered->>'logo_url'), logo_url),
    logo_url_light = COALESCE((v_filtered->>'logo_url_light'), logo_url_light),
    password_login_enabled = COALESCE((v_filtered->>'password_login_enabled')::boolean, password_login_enabled),
    font_display = COALESCE((v_filtered->>'font_display')::text, font_display),
    font_body = COALESCE((v_filtered->>'font_body')::text, font_body),
    font_mono = COALESCE((v_filtered->>'font_mono')::text, font_mono),
    pdf_font_body = COALESCE((v_filtered->>'pdf_font_body')::text, pdf_font_body),
    pdf_font_heading = COALESCE((v_filtered->>'pdf_font_heading')::text, pdf_font_heading),
    email_font = COALESCE((v_filtered->>'email_font')::text, email_font),
    pdf_logo_variant = COALESCE((v_filtered->>'pdf_logo_variant'), pdf_logo_variant),
    email_logo_variant = COALESCE((v_filtered->>'email_logo_variant'), email_logo_variant),
    favicon_data = COALESCE((v_filtered->>'favicon_data'), favicon_data),
    company_email = COALESCE((v_filtered->>'company_email'), company_email),
    login_support_email = COALESCE((v_filtered->>'login_support_email'), login_support_email),
    portal_title = COALESCE((v_filtered->>'portal_title'), portal_title),
    smtp_host = COALESCE((v_filtered->>'smtp_host'), smtp_host),
    smtp_port = COALESCE((v_filtered->>'smtp_port')::int, smtp_port),
    smtp_user = COALESCE((v_filtered->>'smtp_user'), smtp_user),
    smtp_pass = COALESCE((v_filtered->>'smtp_pass'), smtp_pass),
    -- 1841: a cleared password clears its ciphertext too, as the branding
    -- write's does (1397): the trigger only replaces it when a new one comes.
    smtp_pass_enc = CASE WHEN (v_filtered ? 'smtp_pass') AND COALESCE(v_filtered->>'smtp_pass', '') = ''
      THEN NULL ELSE smtp_pass_enc END,
    smtp_from_name = COALESCE((v_filtered->>'smtp_from_name'), smtp_from_name),
    smtp_from_email = COALESCE((v_filtered->>'smtp_from_email'), smtp_from_email),
    email_enabled = COALESCE((v_filtered->>'email_enabled')::boolean, email_enabled),
    email_templates = COALESCE(v_filtered->'email_templates', email_templates),
    updated_at = now()
  WHERE id IS NOT NULL;
  RETURN jsonb_build_object('ok', true, 'applied', v_filtered);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_update_settings(jsonb, text, jsonb, text) FROM PUBLIC;
-- anon kept for install_token escape during provisioning; non-install_token
-- paths still require user_jwt inside the function.
GRANT EXECUTE ON FUNCTION public.rpc_update_settings(jsonb, text, jsonb, text) TO anon, authenticated, service_role;


-- Helper: non-consuming install-token check (token is consumed separately by
-- rpc_provisioning_complete, allowing multiple provisioning-time RPC calls
-- within one install window).
CREATE OR REPLACE FUNCTION public._check_install_token(p_token text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_stored text;
BEGIN
  SELECT value INTO v_stored FROM public._internal_secrets WHERE key = 'INSTALL_TOKEN' LIMIT 1;
  IF v_stored IS NULL OR v_stored = '' THEN RETURN false; END IF;
  RETURN v_stored = p_token;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._check_install_token(text) FROM PUBLIC, anon, authenticated;


-- ─── 7. rpc_get_smtp_config, require user_jwt ───────────────────────────
DROP FUNCTION IF EXISTS public.rpc_get_smtp_config(text);
DROP FUNCTION IF EXISTS public.rpc_get_smtp_config(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_get_smtp_config(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_s RECORD; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_get_smtp_config', true);
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;
  SELECT smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from_name, smtp_from_email,
         company_name, email_enabled, email_templates, accent_color, company_email,
         -- 1363: the connection travels with the rest. Five definitions of
         -- this function live in this file and Postgres keeps the last; making
         -- them agree means re-running the setup cannot change whether a
         -- connected mailbox is visible to the mailer.
         smtp_oauth_provider, smtp_oauth_user, smtp_oauth_refresh, smtp_oauth_refresh_enc
    INTO v_s FROM public.settings LIMIT 1;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  RETURN jsonb_build_object(
    'smtp_host', v_s.smtp_host, 'smtp_port', v_s.smtp_port, 'smtp_user', v_s.smtp_user,
    'smtp_pass', v_s.smtp_pass, 'smtp_from_name', v_s.smtp_from_name,
    'smtp_from_email', v_s.smtp_from_email, 'company_name', v_s.company_name,
    'email_enabled', v_s.email_enabled, 'email_templates', v_s.email_templates,
    'accent_color', v_s.accent_color, 'company_email', v_s.company_email,
    'smtp_oauth_provider', v_s.smtp_oauth_provider,
    'smtp_oauth_user', v_s.smtp_oauth_user,
    'smtp_oauth_refresh', COALESCE(NULLIF(v_s.smtp_oauth_refresh, ''), public._settings_decrypt(v_s.smtp_oauth_refresh_enc))
  );
END;
$$;
-- Grant anon EXECUTE: the cosigner-signed envelope inside the function
-- body is the security gate. Revoking the PostgREST ACL would make
-- every portal login route to Pental SMTP fallback because the portal
-- calls with the publishable key (anon role) and PostgREST 404s the
-- call before the function body runs. The function still rejects
-- unsigned calls via _pental_authorise; the grant just lets the call
-- reach the body where the real check happens.
REVOKE ALL ON FUNCTION public.rpc_get_smtp_config(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_get_smtp_config(text, jsonb) TO anon, authenticated, service_role;


-- ─── 8. rpc_admin_reset_mfa, require user_jwt + admin role ──────────────
-- For in-portal MFA reset (admin resets another user's MFA). Caller must be
-- authenticated AND have admin role. 1810: a firm admin's action only, never
-- Pental's: a Pental-signed envelope is no longer accepted, alone or beside a
-- session, and the admin must always have presented a factor this session.
DROP FUNCTION IF EXISTS public.rpc_admin_reset_mfa(text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_admin_reset_mfa(
  p_email text,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_auth_id uuid; v_caller_role text; v_pid uuid; v_why text;
BEGIN
  -- 1810: a signed-in session only. p_secret and p_auth are kept so older
  -- callers still resolve to this function; neither is read.
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;

  SELECT role INTO v_caller_role
    FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true
    LIMIT 1;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin', 'senior') THEN
    RAISE EXCEPTION 'Admin role required';
  END IF;

  -- The admin doing the reset must have presented a factor this session. An
  -- admin session that reached the portal on the password step alone would
  -- otherwise be able to reset any user's factor (its own included) and enrol
  -- a replacement, bypassing MFA.
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Re-verify MFA before resetting a user''s MFA' USING ERRCODE = '42501';
  END IF;

  SELECT id, auth_user_id INTO v_pid, v_auth_id
    FROM public.profiles
    WHERE lower(email) = lower(p_email) AND active = true;
  IF v_auth_id IS NULL THEN RETURN false; END IF;

  -- 1816: whose it is matters here as in the uuid form: somebody below you,
  -- or another administrator when you are the account owner, and nobody else.
  v_why := public._pental_manage_refusal(v_pid);
  IF v_why IS NOT NULL THEN
    RAISE EXCEPTION '%', CASE v_why
        WHEN 'self' THEN 'Your own MFA is changed from your own account, not reset here'
        WHEN 'owner' THEN 'Nobody else can reset the account owner''s MFA'
        WHEN 'owner_only' THEN 'Only the account owner can reset another administrator''s MFA'
        WHEN 'rank' THEN 'You cannot reset MFA for someone with an equal or higher role'
        ELSE 'Admin role required' END
      USING ERRCODE = '42501';
  END IF;

  -- 1810: the same reset as the Users screen's uuid form: the last-method
  -- triggers stand aside for an admin's reset (a person whose only method is
  -- the authenticator is exactly who needs it), and the passkeys go too, so
  -- the person starts again with nothing an attacker could have enrolled.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  PERFORM set_config('pental.bypass_mfa_protection', 'true', true);
  UPDATE public.profiles
    SET totp_secret = NULL, totp_attempts = 0, totp_locked_until = NULL, updated_at = now()
    WHERE lower(email) = lower(p_email) AND active = true;
  DELETE FROM public.webauthn_credentials WHERE auth_user_id = v_auth_id;
  PERFORM set_config('pental.bypass_protect', 'false', true);
  PERFORM set_config('pental.bypass_mfa_protection', 'false', true);
  PERFORM public._clear_mfa_verified(v_auth_id);

  RETURN true;
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_admin_reset_mfa(text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_admin_reset_mfa(text, text, jsonb) TO anon, authenticated, service_role;


-- ─── 9. rpc_clear_mfa, require user_jwt (user clears own MFA) ───────────
DROP FUNCTION IF EXISTS public.rpc_clear_mfa(text, text);
DROP FUNCTION IF EXISTS public.rpc_clear_mfa(text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_clear_mfa(
  p_email text,
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_auth_id uuid; v_caller_email text;
BEGIN
  -- 1810: the person's own action, never Pental's. A signed-in session only;
  -- p_secret and p_auth are kept so older callers still resolve to this
  -- function, and neither is read.
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;

  -- A session may not clear its own factor unless it has presented one this
  -- session. Without this, a session that reached the portal on the password
  -- (email code) step alone could clear its factor and enrol a new one it
  -- controls, which stamps it fresh, and read data without ever presenting the
  -- factor already on the account. rpc_clear_own_totp already gates this way;
  -- this is its sibling.
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Re-verify MFA before changing security settings' USING ERRCODE = '42501';
  END IF;

  -- A user may only clear their own MFA via this function. Admins wanting
  -- to clear another user's MFA use rpc_admin_reset_mfa.
  SELECT email INTO v_caller_email
    FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true
    LIMIT 1;
  IF v_caller_email IS NULL OR lower(v_caller_email) <> lower(p_email) THEN
    RAISE EXCEPTION 'Can only clear your own MFA';
  END IF;

  SELECT auth_user_id INTO v_auth_id FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true;
  IF v_auth_id IS NULL THEN RETURN false; END IF;

  -- Same column guard as rpc_save_totp_secret: it only lets admin/senior touch
  -- totp_secret, so this path failed with "Cannot change MFA config" for every
  -- other role. This function has already decided the caller is entitled to the
  -- change, so raise the guard's own flag and drop it straight after.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles
    SET totp_secret = NULL, totp_attempts = 0, totp_locked_until = NULL, updated_at = now()
    WHERE lower(email) = lower(p_email) AND active = true;
  PERFORM set_config('pental.bypass_protect', 'false', true);
  PERFORM public._clear_mfa_verified(v_auth_id);

  RETURN true;
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_clear_mfa(text, text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_clear_mfa(text, text, jsonb) TO anon, authenticated, service_role;


-- ─── 11. rpc_get_admin_email, require user_jwt ──────────────────────────
DROP FUNCTION IF EXISTS public.rpc_get_admin_email(text);
DROP FUNCTION IF EXISTS public.rpc_get_admin_email(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_get_admin_email(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_email text; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_get_admin_email', true);
  IF v_mode IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;
  SELECT email INTO v_email FROM public.profiles WHERE role = 'admin' AND active = true LIMIT 1;
  RETURN v_email;
END;
$$;
-- Grant anon EXECUTE: same rationale as rpc_get_smtp_config above. The
-- portal's auth-code lambda calls this with the publishable key during
-- login flows. Revoking PostgREST ACL would silently break those calls.
REVOKE ALL ON FUNCTION public.rpc_get_admin_email(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_get_admin_email(text, jsonb) TO anon, authenticated, service_role;


-- ─── 12. Update _pental_rpc_audit_log RLS so admins can inspect ops ──────
DROP POLICY IF EXISTS rpc_audit_admin_read ON public._pental_rpc_audit_log;
CREATE POLICY rpc_audit_admin_read ON public._pental_rpc_audit_log
  FOR SELECT TO authenticated
  USING (public.current_user_role() IN ('admin', 'senior'));


-- ═══════════════════════════════════════════════════════════════════════════
-- RESIDUAL FIXES
-- ═══════════════════════════════════════════════════════════════════════════


-- ─── 14. MFA self-recovery: locked-out users regain access without an operator
-- Eliminates the common case that required rpc_admin_reset_mfa_operator.
-- Flow:
--   1. User signs in with email OTP (gets a real user JWT, MFA-not-verified).
--   2. Portal shows "Lost authenticator?" → calls rpc_request_mfa_recovery()
--      with their user JWT. RPC creates a one-time 8-digit recovery code,
--      stores a hash in mfa_recovery_requests, queues an email to the user's
--      profile email. Rate limit: max 3 per hour per user.
--   3. User reads email, enters code.
--   4. Portal calls rpc_clear_own_mfa_via_recovery(code) with their user JWT.
--      RPC hashes the code, looks up a non-expired unused request for this
--      user, marks consumed, clears totp_secret + mfa_verified_at.
--   5. Portal redirects to MFA enrol (fresh TOTP setup).
--
-- Attacker path: Vercel-compromise attacker cannot do step 1 (no way to
-- produce a user JWT, email OTP goes to user's real mailbox). Even if the
-- attacker had a user JWT, they'd need to intercept the recovery email at
-- the user's mailbox to get the code. Detection: audit row.

CREATE TABLE IF NOT EXISTS public.mfa_recovery_requests (
  id bigserial PRIMARY KEY,
  auth_user_id uuid NOT NULL,
  code_hash text NOT NULL,
  expires_at timestamptz NOT NULL,
  used boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mfa_recovery_user ON public.mfa_recovery_requests(auth_user_id, used, expires_at);
ALTER TABLE public.mfa_recovery_requests ENABLE ROW LEVEL SECURITY;
REVOKE INSERT, UPDATE, DELETE, SELECT ON public.mfa_recovery_requests FROM PUBLIC, anon, authenticated;


-- rpc_request_mfa_recovery: create a recovery code, email it to the user's
-- own profile email. Requires valid user JWT.
DROP FUNCTION IF EXISTS public.rpc_request_mfa_recovery();
CREATE OR REPLACE FUNCTION public.rpc_request_mfa_recovery()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_uid uuid;
  v_email text;
  v_company text;
  v_code text;
  v_recent_count int;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;

  -- Rate limit: max 3 requests per hour per user
  SELECT count(*) INTO v_recent_count
    FROM public.mfa_recovery_requests
    WHERE auth_user_id = v_uid
      AND created_at > now() - interval '1 hour';
  IF v_recent_count >= 3 THEN
    RAISE EXCEPTION 'Too many recovery requests. Wait up to an hour.';
  END IF;

  -- Find the user's profile email
  SELECT email INTO v_email
    FROM public.profiles
    WHERE auth_user_id = v_uid AND active = true
    LIMIT 1;
  IF v_email IS NULL THEN RAISE EXCEPTION 'Profile not found'; END IF;

  -- Generate 8-digit recovery code
  v_code := lpad(((random() * 99999999)::bigint)::text, 8, '0');

  -- Store hash + expiry
  INSERT INTO public.mfa_recovery_requests (auth_user_id, code_hash, expires_at)
    VALUES (v_uid, encode(extensions.digest(v_code, 'sha256'), 'hex'), now() + interval '15 minutes');

  -- Queue email
  SELECT company_name INTO v_company FROM public.settings LIMIT 1;
  BEGIN
    INSERT INTO public.email_notifications
      (to_email, subject, body, notification_type, status)
    VALUES (
      v_email,
      'Your authenticator recovery code',
      '<p>You requested to reset your authenticator on ' || COALESCE(v_company, 'your portal') || '.</p>' ||
      '<p>Your recovery code is:</p>' ||
      '<p style="font-size:1.8em;font-weight:700;letter-spacing:0.2em;background:#f6f6f6;padding:14px 20px;border-radius:8px;display:inline-block;">' || v_code || '</p>' ||
      '<p>It expires in 15 minutes. Enter it on the authenticator verification screen to reset your authenticator.</p>' ||
      '<p>If you did not request this, ignore this email.</p>',
      'mfa_recovery_code', 'pending'
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- Audit
  INSERT INTO public._pental_ops_audit (op, target_email)
    VALUES ('rpc_request_mfa_recovery', v_email);

  RETURN jsonb_build_object('ok', true, 'emailed', true);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_request_mfa_recovery() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_request_mfa_recovery() TO anon, authenticated, service_role;


-- rpc_clear_own_mfa_via_recovery: consume a recovery code, clear the
-- caller's own MFA. Requires user JWT AND valid recovery code that was
-- delivered to the user's email.
DROP FUNCTION IF EXISTS public.rpc_clear_own_mfa_via_recovery(text);
CREATE OR REPLACE FUNCTION public.rpc_clear_own_mfa_via_recovery(p_code text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_uid uuid;
  v_code_hash text;
  v_request_id bigint;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;

  IF p_code IS NULL OR length(trim(p_code)) != 8 THEN
    RAISE EXCEPTION 'Invalid code format';
  END IF;

  v_code_hash := encode(extensions.digest(trim(p_code), 'sha256'), 'hex');

  SELECT id INTO v_request_id
    FROM public.mfa_recovery_requests
    WHERE auth_user_id = v_uid
      AND code_hash = v_code_hash
      AND used = false
      AND expires_at > now()
    ORDER BY created_at DESC
    LIMIT 1;
  IF v_request_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired recovery code';
  END IF;

  -- Consume the code
  UPDATE public.mfa_recovery_requests SET used = true WHERE id = v_request_id;
  -- Also invalidate any other outstanding codes for this user
  UPDATE public.mfa_recovery_requests SET used = true
    WHERE auth_user_id = v_uid AND used = false;

  -- Clear MFA
  UPDATE public.profiles
    SET totp_secret = NULL, totp_attempts = 0, totp_locked_until = NULL, updated_at = now()
    WHERE auth_user_id = v_uid;
  PERFORM public._clear_mfa_verified(v_uid);

  INSERT INTO public._pental_ops_audit (op)
    VALUES ('rpc_clear_own_mfa_via_recovery');

  RETURN true;
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_clear_own_mfa_via_recovery(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_clear_own_mfa_via_recovery(text) TO anon, authenticated, service_role;


-- ─── 15. rpc_bulk_clean, notification on call ───────────────────────────
-- rpc_bulk_clean is destructively callable from Vercel-compromise. We can't
-- require a user JWT (it runs at re-provision time when no user session
-- exists). The mitigation here is that destructive activity is loud:
-- every call produces a notification email to the active admin so any
-- unauthorised wipe is visible immediately.
--
-- The rpc_bulk_clean definition lives in byo-database-security-patch.sql.
-- Here we just add a notification trigger so any call produces an email.
CREATE OR REPLACE FUNCTION public._notify_bulk_clean_called() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_email text; v_company text;
BEGIN
  SELECT email INTO v_email FROM public.profiles
    WHERE role = 'admin' AND active = true LIMIT 1;
  SELECT company_name INTO v_company FROM public.settings LIMIT 1;

  IF v_email IS NULL THEN RETURN; END IF;

  BEGIN
    INSERT INTO public.email_notifications
      (to_email, subject, body, notification_type, status)
    VALUES (
      v_email,
      'CRITICAL: Your portal data is being wiped',
      '<p>Pental has just issued a bulk_clean call against your Supabase project at ' || now()::text || ' UTC.</p>' ||
      '<p>This operation deletes all portal data in your database. It is used during ' ||
      'disaster recovery and re-provisioning. <strong>If you did not authorise this, ' ||
      'restore immediately from your Supabase Point-in-Time Recovery backup ' ||
      '(available for 7 days) and contact Pental support.</strong></p>',
      'security_bulk_clean', 'pending'
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._notify_bulk_clean_called() FROM PUBLIC, anon, authenticated;


-- Add the notification call to the existing rpc_bulk_clean by wrapping it.
-- We DROP the existing fn and recreate identical body + notification call.
-- (Alternative: add a trigger on a sentinel table, but calling the helper
-- from rpc_bulk_clean is cleaner.)
--
-- We skip this wrapper if rpc_bulk_clean hasn't been installed yet
-- (e.g. fresh install running the security patch file first).
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'rpc_bulk_clean'
  ) THEN
    -- The RPC exists. We need to add the notification call. Easiest and
    -- safest: add a BEFORE-style trigger via PERFORM injection. Since we
    -- can't modify the function body here without duplicating its logic,
    -- we create a secondary RPC that wraps and call the original via
    -- internal name. For simplicity and safety we DO NOT modify bulk_clean
    -- here, instead we rely on the documented detection-by-damage
    -- property (customer sees wiped DB, restores from Supabase PITR).
    --
    -- Future work: re-define rpc_bulk_clean with PERFORM public._notify_bulk_clean_called()
    -- at the top. Requires copying the full body from byo-database-security-patch.sql.
    NULL;
  END IF;
END $$;


-- ─── 16. Revoke unused anon grants for tightened surface ─────────────────
-- After this release, anon should only be able to reach provisioning-only
-- RPCs (those that accept install_token OR have their own gates).
-- Authenticated users (real portal sessions) get everything via user_jwt
-- requirements.
--
-- Already REVOKEd above: get_smtp_config, get_admin_email, read_settings_server,
-- clear_mfa, admin_reset_mfa, get_management_token.
--
-- Still anon for legitimate provisioning / recovery reasons:
--   - rpc_bulk_clean, rpc_install_pental_keys, rpc_provisioning_complete,
--     rpc_bootstrap_admin, rpc_bulk_import{,_keys}, rpc_bulk_auth
--     (install_token gated)
--   - rpc_functions_exist (read-only booleans)
--   - rpc_update_settings (install_token OR user_jwt)
--   - rpc_update_settings_branding, rpc_update_smtp_operator,
--     rpc_admin_reset_mfa_operator, rpc_set_migration_password
--     (narrow operator RPCs, provision_secret gated, all audit+notify)
--   - rpc_resolve_tenant (master-side only, public lookup)
--   - rpc_verify_totp, rpc_save_totp_secret (user_jwt gated internally)
--   - rpc_sign_proposal (has its own signature verification)


-- ─── rpc_get_login_branding ──────────────────────────────────────────────
-- Public branding lookup for the portal login screen on BYO tenants.
-- The portal calls this BEFORE the user authenticates, so it must be
-- callable with the publishable (anon) key. Returns the safe subset of
-- settings columns needed to render the pre-login page (logo, favicon,
-- accent, theme, login text). Excludes SMTP credentials, AI keys, financial
-- data, and any other sensitive columns.
--
-- BYO has a singleton settings row, so no tenant_id filter is needed. The
-- p_tenant_id argument is accepted for signature compatibility with the
-- master-side function (the portal passes the same argument to either side
-- depending on whether the tenant is BYO or not), but is not used.
CREATE OR REPLACE FUNCTION public.rpc_get_login_branding(p_tenant_id uuid)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE
  SET search_path = public, pg_catalog, pg_temp
AS $fn$
#variable_conflict use_variable
DECLARE v_settings RECORD;
BEGIN
  SELECT * INTO v_settings FROM public.settings LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Settings not found');
  END IF;
  RETURN jsonb_build_object(
    'company_name',            COALESCE(NULLIF(v_settings.company_name, ''), ''),
    'company_email',           COALESCE(v_settings.company_email, ''),
    'accent_color',            COALESCE(NULLIF(v_settings.accent_color, ''), '#991b1b'),
    'theme_mode',              COALESCE(NULLIF(v_settings.theme_mode, ''), 'both'),
    'severity_colors',       v_settings.severity_colors,
    'severity_style',        v_settings.severity_style,
    'logo_url',                NULLIF(v_settings.logo_url, ''),
    'password_login_enabled',  COALESCE(v_settings.password_login_enabled, false),
    'font_display',            v_settings.font_display,
    'font_body',               v_settings.font_body,
    'font_mono',               v_settings.font_mono,
    'logo_url_light',          NULLIF(v_settings.logo_url_light, ''),
    'favicon_data',            NULLIF(v_settings.favicon_data, ''),
    'login_title',             COALESCE(v_settings.login_title, ''),
    'login_subtitle',          COALESCE(v_settings.login_subtitle, ''),
    'login_support_email',     COALESCE(v_settings.login_support_email, ''),
    'login_show_logo',         COALESCE(v_settings.login_show_logo, true),
    'login_show_company_name', COALESCE(v_settings.login_show_company_name, true),
    'login_show_title',        COALESCE(v_settings.login_show_title, true),
    'sso_google_enabled',      COALESCE(v_settings.sso_google_enabled, true),
    'sso_microsoft_enabled',   COALESCE(v_settings.sso_microsoft_enabled, true),
    'login_button_text',       COALESCE(v_settings.login_button_text, ''),
    'login_custom_text',       COALESCE(v_settings.login_custom_text, ''),
    'portal_title',            COALESCE(v_settings.portal_title, ''),
    'theme_dark',              v_settings.theme_dark,
    'theme_light',             v_settings.theme_light
  );
END;
$fn$;

REVOKE EXECUTE ON FUNCTION public.rpc_get_login_branding(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_get_login_branding(uuid) TO anon, authenticated, service_role;


COMMENT ON FUNCTION public._pental_authorise(jsonb, text, text, boolean) IS
'4-arg version. When p_require_user_jwt=true, auth.uid() MUST be set AND provision_secret is REJECTED. Data-read and admin RPCs pass true.';

-- (Removed: COMMENT ON FUNCTION rpc_update_settings_branding, function was
-- dropped earlier in this file as part of the operator-RPC deprecation. Was
-- causing setup to fail with "function does not exist" errors. The comment
-- existed only as documentation of the historical signature.)

-- (Removed: COMMENT ON FUNCTION rpc_admin_reset_mfa_operator, same reason.)

-- (Removed: COMMENT ON FUNCTION rpc_get_management_token, function deleted.)

COMMENT ON FUNCTION public.rpc_request_mfa_recovery() IS
'User-initiated MFA recovery. Emails an 8-digit code to the user''s profile email. Rate-limited 3/hour. User redeems via rpc_clear_own_mfa_via_recovery.';

COMMENT ON FUNCTION public.rpc_clear_own_mfa_via_recovery(text) IS
'User-initiated MFA reset. Consumes a recovery code. Requires user JWT + valid unexpired code. Replaces the need for rpc_admin_reset_mfa_operator in the common case.';

-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-webauthn.sql ━━
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- byo-webauthn.sql
--
-- WebAuthn credential registration and assertion-gated settings application.
-- Apply AFTER byo-close-vercel-exfil.sql.
--
-- Companion to the webauthn-verify Edge Function (deployed separately via
-- Supabase Management API at install time).
--
-- ARCHITECTURE
-- The portal frontend (admin's browser, signed in to BYO) handles the full
-- WebAuthn flow:
--   1. Enrollment: navigator.credentials.create() with the BYO domain as
--      RP ID. Public key sent to BYO via rpc_register_webauthn() with
--      admin's user_jwt.
--   2. Signing: when applying a pental.io-staged change, portal computes
--      sha256(canonical_payload), calls navigator.credentials.get(challenge),
--      sends the assertion to BYO via rpc_apply_signed_settings().
--      No user_jwt required for the apply call, the assertion IS the auth.
--   3. BYO RPC calls out to the webauthn-verify Edge Function via the
--      `http` extension, which verifies the signature against the stored
--      public key and returns boolean.
--
-- THREAT MODEL
--   - Vercel-compromise of pental.io: cannot forge signatures (no private
--     key access). Can stage fake pending changes on master, but the user
--     reviews them in the portal before tapping their authenticator.
--   - Vercel-compromise of portal Vercel: serves malicious JS that could
--     ask the user to sign a different change than displayed. Mitigation:
--     every signed apply is logged to _pental_signed_changes_audit with
--     the canonical payload (visible to customer for review).
--   - Master-Supabase-compromise: BYO data still protected. Master holds
--     pending change descriptions but no signing keys, no BYO credentials.
-- ═══════════════════════════════════════════════════════════════════════════

-- 1825: the http extension is no longer enabled here. It was for the WebAuthn
-- verifier (gone in 1812) and the signature verifier (gone now): passkeys and
-- Pental's signatures are checked in this database, and nothing in this file
-- calls out. An http extension the firm has for its own use is left exactly
-- as it is (this block used to move one installed elsewhere, with CASCADE).


-- ─── 1. webauthn_credentials table ───────────────────────────────────────
-- One row per credential. Users can register multiple authenticators for
-- redundancy (laptop Touch ID + hardware key + phone).
CREATE TABLE IF NOT EXISTS public.webauthn_credentials (
  id bigserial PRIMARY KEY,
  auth_user_id uuid NOT NULL,
  credential_id text NOT NULL,             -- base64url, unique per credential
  public_key text NOT NULL,                -- base64url, COSE-encoded
  rp_id text NOT NULL,                     -- the RP ID this credential was registered for
  label text,                              -- user-supplied "MacBook Touch ID" etc.
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  UNIQUE (credential_id)
);

CREATE INDEX IF NOT EXISTS idx_webauthn_user ON public.webauthn_credentials(auth_user_id);
ALTER TABLE public.webauthn_credentials ENABLE ROW LEVEL SECURITY;

-- Users can read their own credentials (to list them in settings, see
-- which are registered, label them, delete them).
DROP POLICY IF EXISTS webauthn_own_read ON public.webauthn_credentials;
CREATE POLICY webauthn_own_read ON public.webauthn_credentials
  FOR SELECT TO authenticated
  USING (auth_user_id = auth.uid());

-- Inserts and deletes go through SECURITY DEFINER RPCs only.
REVOKE INSERT, UPDATE, DELETE ON public.webauthn_credentials FROM PUBLIC, anon, authenticated;


-- ─── 2. _pental_signed_changes_audit, every signed apply lives here ────
-- Customer can review every settings change ever applied via the WebAuthn
-- flow. Includes the full canonical payload so they can see exactly what
-- was applied, when, and which credential authorized it.
CREATE TABLE IF NOT EXISTS public._pental_signed_changes_audit (
  id bigserial PRIMARY KEY,
  credential_id text NOT NULL,
  auth_user_id uuid,
  operation text NOT NULL,
  payload jsonb NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now(),
  source_origin text                       -- the origin claimed in clientDataJSON
);

ALTER TABLE public._pental_signed_changes_audit ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS signed_changes_admin_read ON public._pental_signed_changes_audit;
CREATE POLICY signed_changes_admin_read ON public._pental_signed_changes_audit
  FOR SELECT TO authenticated
  USING (public.current_user_role() IN ('admin', 'senior'));
REVOKE INSERT, UPDATE, DELETE ON public._pental_signed_changes_audit FROM PUBLIC, anon, authenticated;


-- ─── 3. _pental_used_nonces, replay protection ──────────────────────────
-- Reuse the existing table (created in byo-database-security-patch.sql for
-- the signed-auth nonce check). Daily cleanup job already drops old nonces.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                 WHERE table_schema = 'public' AND table_name = '_pental_used_nonces')
  THEN
    CREATE TABLE public._pental_used_nonces (
      nonce text PRIMARY KEY,
      used_at timestamptz NOT NULL DEFAULT now()
    );
    ALTER TABLE public._pental_used_nonces ENABLE ROW LEVEL SECURITY;
    REVOKE ALL ON public._pental_used_nonces FROM PUBLIC, anon, authenticated;
  END IF;
END $$;


-- ─── 4. Edge Function URL config ─────────────────────────────────────────
-- The verifier Edge Function lives in Pental's separately-administered
-- Edge Functions project (independent of master and BYO; stateless;
-- holds no signing keys). Already seeded at line 279 with ON CONFLICT
-- DO NOTHING; this UPSERT covers the legacy case where an early
-- byo-setup.sql ran a different ordering and ended up with an empty
-- string (which would cause _verify_pental_auth and rpc_apply_signed_settings
-- to raise "WebAuthn verifier URL not configured" at runtime).
-- 1812: no WEBAUTHN_VERIFY_URL is seeded; passkeys are checked in this database.

-- 1825: no signature verifier URL is seeded either; _verify_pental_auth checks
-- Pental's signatures in this database.


-- ─── 5. rpc_register_webauthn, store a new credential ──────────────────
-- Caller provides credential_id + COSE public key from navigator.credentials.create().
-- Requires user_jwt: the calling user is the owner of this credential.
DROP FUNCTION IF EXISTS public.rpc_register_webauthn(text, text, text, text);
CREATE OR REPLACE FUNCTION public.rpc_register_webauthn(
  p_credential_id text,
  p_public_key text,
  p_rp_id text,
  p_label text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_uid uuid; v_id bigint;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;
  -- 1798: only a person with an active profile here enrols a key. A new key
  -- stamps the session as second-factor fresh, and a session with no profile
  -- (public sign-up, or a deactivated user) must never be made fresh.
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = v_uid AND active = true) THEN
    RAISE EXCEPTION 'Session required';
  END IF;

  IF p_credential_id IS NULL OR length(p_credential_id) < 16
     OR p_public_key IS NULL OR length(p_public_key) < 16
     OR p_rp_id IS NULL OR length(p_rp_id) < 1
  THEN
    RAISE EXCEPTION 'Invalid credential data';
  END IF;

  -- Cap per-user credentials at 10. Protects against a compromised user JWT
  -- registering thousands of credentials. 10 is more than any human needs
  -- (laptop Touch ID + phone + 2 hardware keys is typical).
  IF (SELECT count(*) FROM public.webauthn_credentials WHERE auth_user_id = v_uid) >= 10 THEN
    RAISE EXCEPTION 'Too many security keys registered. Remove an existing one before adding more.';
  END IF;

  -- Refuse if this credential_id is already registered (could be replay)
  IF EXISTS (SELECT 1 FROM public.webauthn_credentials WHERE credential_id = p_credential_id) THEN
    RAISE EXCEPTION 'Credential already registered';
  END IF;

  -- Adding a factor to an account that already has MFA requires current MFA (same
  -- rule as the 5-argument overload and as the authenticator app). Both overloads
  -- exist as separate functions, so the guard has to be on both or the older
  -- signature would be an open route to the same bypass.
  IF NOT public.mfa_is_fresh() AND (
       EXISTS (SELECT 1 FROM public.webauthn_credentials WHERE auth_user_id = v_uid)
       OR EXISTS (SELECT 1 FROM public.profiles
                  WHERE auth_user_id = v_uid AND totp_secret IS NOT NULL AND totp_secret != '')
     ) THEN
    RAISE EXCEPTION 'Current MFA verification required to add another factor';
  END IF;

  INSERT INTO public.webauthn_credentials
    (auth_user_id, credential_id, public_key, rp_id, label)
  VALUES (v_uid, p_credential_id, p_public_key, p_rp_id,
          COALESCE(NULLIF(trim(p_label), ''), 'Unnamed device'))
  RETURNING id INTO v_id;

  -- Audit
  INSERT INTO public._pental_ops_audit (op, target_email, fields_changed)
  VALUES ('rpc_register_webauthn',
          (SELECT email FROM public.profiles WHERE auth_user_id = v_uid LIMIT 1),
          jsonb_build_object('credential_id_prefix', left(p_credential_id, 16),
                             'rp_id', p_rp_id,
                             'label', p_label));

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_register_webauthn(text, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_register_webauthn(text, text, text, text) TO authenticated, service_role;


-- ─── 6. rpc_remove_webauthn, user removes one of their own credentials ──
DROP FUNCTION IF EXISTS public.rpc_remove_webauthn(text);
CREATE OR REPLACE FUNCTION public.rpc_remove_webauthn(p_credential_id text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_uid uuid; v_count int;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;
  -- 1810: removing a passkey is a factor change, so it takes what every other
  -- one takes: a factor presented this session. The row policy on direct
  -- deletes already required it; this function, which bypasses that policy,
  -- did not.
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Re-verify MFA before changing security settings' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.webauthn_credentials
  WHERE credential_id = p_credential_id AND auth_user_id = v_uid;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN RETURN false; END IF;

  INSERT INTO public._pental_ops_audit (op, target_email, fields_changed)
  VALUES ('rpc_remove_webauthn',
          (SELECT email FROM public.profiles WHERE auth_user_id = v_uid LIMIT 1),
          jsonb_build_object('credential_id_prefix', left(p_credential_id, 16)));

  RETURN true;
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_remove_webauthn(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_remove_webauthn(text) TO authenticated, service_role;


-- ─── 7. rpc_apply_signed_settings, the main verification + apply entrypoint
--
-- Inputs:
--   p_payload jsonb , canonical payload that was hashed to produce the
--     challenge. Must contain: tenant_id, op, fields, nonce, exp.
--   p_assertion jsonb, {credential_id, client_data_json, authenticator_data,
--     signature, expected_origin, expected_rp_id} all base64url-encoded
--     where applicable.
--
-- This RPC does NOT require user_jwt, the assertion proves user intent.
-- It IS however gated on:
--   1. The credential_id existing in webauthn_credentials.
--   2. The Edge Function returning ok: true.
--   3. The nonce not being previously used.
--   4. The exp not being in the past.
--   5. The op being on a known list.
--
-- After verification, it dispatches to the appropriate operation. Currently
-- supports op = 'rpc_update_settings'.
DROP FUNCTION IF EXISTS public.rpc_apply_signed_settings(jsonb, jsonb);
DROP FUNCTION IF EXISTS public.rpc_apply_signed_settings(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_apply_signed_settings(
  p_payload_canonical text,
  p_assertion jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_payload jsonb;
  v_op text;
  v_nonce text;
  v_exp bigint;
  v_credential_id text;
  v_public_key text;
  v_owner_uid uuid;
  v_challenge_b64u text;
  v_http_response jsonb;
  v_rp_id text;
  v_origin text;
  v_owner_email text;
  v_attested boolean;
BEGIN
  -- ── Parse and validate payload ────────────────────────────────────────
  -- The portal sends the canonical payload as the EXACT BYTE STRING it
  -- hashed for the WebAuthn challenge. We parse it for structure but use
  -- the raw bytes for the hash. This avoids JSON serialization mismatches
  -- between JS JSON.stringify and Postgres jsonb::text.
  BEGIN
    v_payload := p_payload_canonical::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Invalid canonical payload: not valid JSON';
  END;

  v_op := v_payload->>'op';
  v_nonce := v_payload->>'nonce';
  v_exp := (v_payload->>'exp')::bigint;

  IF v_op IS NULL OR v_nonce IS NULL OR v_exp IS NULL THEN
    RAISE EXCEPTION 'Payload missing required fields (op, nonce, exp)';
  END IF;

  IF v_exp < extract(epoch from now()) THEN
    RAISE EXCEPTION 'Payload expired';
  END IF;

  -- Replay protection
  BEGIN
    INSERT INTO public._pental_used_nonces(nonce, op) VALUES (v_nonce, v_op);
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Nonce already used';
  END;

  -- Allowlist of operations
  -- 1810: no MFA reset through this path (the later definition is the live one).
  IF v_op NOT IN ('rpc_update_settings') THEN
    RAISE EXCEPTION 'Operation not allowed via signed apply: %', v_op;
  END IF;

  -- ── Look up the credential ────────────────────────────────────────────
  v_credential_id := p_assertion->>'credential_id';
  IF v_credential_id IS NULL THEN
    RAISE EXCEPTION 'Assertion missing credential_id';
  END IF;

  SELECT public_key, auth_user_id, rp_id
    INTO v_public_key, v_owner_uid, v_rp_id
    FROM public.webauthn_credentials
    WHERE credential_id = v_credential_id;

  IF v_public_key IS NULL THEN
    RAISE EXCEPTION 'Unknown credential';
  END IF;

  -- The credential's owner must be a real, active admin or senior
  SELECT email INTO v_owner_email
    FROM public.profiles
    WHERE auth_user_id = v_owner_uid AND active = true
      AND role IN ('admin', 'senior')
    LIMIT 1;
  IF v_owner_email IS NULL THEN
    RAISE EXCEPTION 'Credential owner is not an active admin';
  END IF;

  -- ── Compute the challenge: sha256(canonical payload bytes) ─────────────
  -- Use the EXACT bytes the portal hashed. base64url-encoded for the verifier.
  v_challenge_b64u := encode(extensions.digest(p_payload_canonical, 'sha256'), 'base64');
  -- pgcrypto's encode wraps long base64 with newlines; strip them
  v_challenge_b64u := replace(v_challenge_b64u, E'\n', '');
  -- Strip '=' padding then convert to base64url alphabet
  v_challenge_b64u := rtrim(v_challenge_b64u, '=');
  v_challenge_b64u := translate(v_challenge_b64u, '+/', '-_');

  v_origin := p_assertion->>'expected_origin';
  IF v_origin IS NULL THEN
    RAISE EXCEPTION 'Assertion missing expected_origin';
  END IF;

  -- ── 1803: the gateway verified this assertion already? ────────────────
  -- Its header covers the credential and the exact bytes that were signed
  -- over; a header that does not match is a refusal, not a fall-through.
  v_attested := public._pental_attested('webauthn|' || v_credential_id || '|' || encode(extensions.digest(p_payload_canonical, 'sha256'), 'hex'));
  IF v_attested IS FALSE THEN
    RAISE EXCEPTION 'WebAuthn signature invalid: gateway attestation did not match';
  END IF;
  -- 1812: the check below runs for every caller; a mismatched header is still a refusal.
  -- 1812: checked here, in this database, with no call to anything.
  v_http_response := public._webauthn_verify_assertion(
    v_public_key, v_challenge_b64u,
    p_assertion->>'client_data_json', p_assertion->>'authenticator_data', p_assertion->>'signature',
    v_origin, v_rp_id
  );
  IF v_http_response IS NULL OR (v_http_response->>'ok')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'WebAuthn signature invalid: %', COALESCE(v_http_response->>'reason', 'unknown');
  END IF;

  -- ── Update last_used_at on the credential ─────────────────────────────
  UPDATE public.webauthn_credentials
    SET last_used_at = now()
    WHERE credential_id = v_credential_id;

  -- ── Audit BEFORE applying ─────────────────────────────────────────────
  -- 1798: the record says a secret changed, never what it became. It is read
  -- by the firm's admins and seniors, and a column grant withholds these same
  -- values from them everywhere else.
  INSERT INTO public._pental_signed_changes_audit
    (credential_id, auth_user_id, operation, payload, source_origin)
  VALUES (v_credential_id, v_owner_uid, v_op,
          CASE WHEN jsonb_typeof(v_payload->'fields') = 'object'
               THEN jsonb_set(v_payload, '{fields}', public._redact_setting_fields(v_payload->'fields'))
               ELSE v_payload END,
          v_origin);

  -- ── Dispatch to the actual operation ──────────────────────────────────
  IF v_op = 'rpc_update_settings' THEN
    PERFORM _apply_signed_settings_update(v_owner_uid, v_payload->'fields');
  END IF;

  RETURN jsonb_build_object('ok', true, 'op', v_op);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_apply_signed_settings(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_apply_signed_settings(text, jsonb) TO anon, authenticated, service_role;


-- ─── 8. Internal apply helpers ───────────────────────────────────────────
-- Called only by rpc_apply_signed_settings after assertion verification.
-- These helpers do NOT re-check authorization, that was done above.

CREATE OR REPLACE FUNCTION public._apply_signed_settings_update(
  p_caller_uid uuid,
  p_fields jsonb
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_key text;
  v_filtered jsonb := '{}'::jsonb;
  v_allowed text[] := ARRAY[
    'company_name','accent_color','theme_mode','logo_url','logo_url_light','pdf_logo_variant','email_logo_variant','password_login_enabled','font_display','font_body','font_mono','pdf_font_body','pdf_font_heading','email_font','favicon_data',
    'company_email','login_support_email','portal_title',
    'smtp_host','smtp_port','smtp_user','smtp_pass','smtp_oauth_provider','smtp_oauth_user','smtp_oauth_refresh','smtp_from_name','smtp_from_email',
    'email_enabled','email_templates',
    'severity_colors','severity_style','notification_color','toast_success_color',
    'theme_dark','theme_light',
    'session_timeout_minutes','session_timeout_action','session_signout_minutes','session_refresh_buffer_minutes',
    'day_rate','currency_code','currency_symbol','vat_rate','vat_number',
    'bank_account_name','bank_name','bank_sort_code','bank_account_number',
    'login_title','login_subtitle','login_button_text','login_custom_text',
    'login_show_logo','login_show_company_name','login_show_title',
    'plan_max_users','plan_max_clients','notes_prompt','caveats_prompt'
  ];
BEGIN
  FOR v_key IN SELECT jsonb_object_keys(p_fields) LOOP
    IF v_key = ANY(v_allowed) THEN
      v_filtered := v_filtered || jsonb_build_object(v_key, p_fields->v_key);
    END IF;
  END LOOP;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.settings SET
    company_name = COALESCE((v_filtered->>'company_name'), company_name),
    accent_color = COALESCE((v_filtered->>'accent_color'), accent_color),
    theme_mode = COALESCE((v_filtered->>'theme_mode'), theme_mode),
    logo_url = COALESCE((v_filtered->>'logo_url'), logo_url),
    logo_url_light = COALESCE((v_filtered->>'logo_url_light'), logo_url_light),
    password_login_enabled = COALESCE((v_filtered->>'password_login_enabled')::boolean, password_login_enabled),
    font_display = COALESCE((v_filtered->>'font_display')::text, font_display),
    font_body = COALESCE((v_filtered->>'font_body')::text, font_body),
    font_mono = COALESCE((v_filtered->>'font_mono')::text, font_mono),
    pdf_font_body = COALESCE((v_filtered->>'pdf_font_body')::text, pdf_font_body),
    pdf_font_heading = COALESCE((v_filtered->>'pdf_font_heading')::text, pdf_font_heading),
    email_font = COALESCE((v_filtered->>'email_font')::text, email_font),
    pdf_logo_variant = COALESCE((v_filtered->>'pdf_logo_variant'), pdf_logo_variant),
    email_logo_variant = COALESCE((v_filtered->>'email_logo_variant'), email_logo_variant),
    favicon_data = COALESCE((v_filtered->>'favicon_data'), favicon_data),
    company_email = COALESCE((v_filtered->>'company_email'), company_email),
    login_support_email = COALESCE((v_filtered->>'login_support_email'), login_support_email),
    portal_title = COALESCE((v_filtered->>'portal_title'), portal_title),
    smtp_host = COALESCE((v_filtered->>'smtp_host'), smtp_host),
    smtp_port = COALESCE((v_filtered->>'smtp_port')::int, smtp_port),
    smtp_user = COALESCE((v_filtered->>'smtp_user'), smtp_user),
    smtp_pass = COALESCE((v_filtered->>'smtp_pass'), smtp_pass),
    smtp_from_name = COALESCE((v_filtered->>'smtp_from_name'), smtp_from_name),
    smtp_from_email = COALESCE((v_filtered->>'smtp_from_email'), smtp_from_email),
    email_enabled = COALESCE((v_filtered->>'email_enabled')::boolean, email_enabled),
    email_templates = COALESCE(v_filtered->'email_templates', email_templates),
    updated_at = now()
  WHERE id IS NOT NULL;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._apply_signed_settings_update(uuid, jsonb) FROM PUBLIC, anon, authenticated;


-- 1810: the signed-apply MFA reset helpers are removed with the two operations
-- they served (see rpc_apply_signed_settings below). Dropped on every run.
DROP FUNCTION IF EXISTS public._apply_signed_admin_reset_mfa(uuid, text);
DROP FUNCTION IF EXISTS public._apply_signed_clear_mfa(uuid);


-- ─── 9. rpc_set_webauthn_verify_url, ops helper ─────────────────────────
-- Pental's installer sets this once per BYO during provisioning.
-- Install_token-gated to prevent post-install tampering.
-- 1812: rpc_set_webauthn_verify_url is gone with the URL it set. Nothing reads
-- a verifier URL; passkeys are checked in this database.
DROP FUNCTION IF EXISTS public.rpc_set_webauthn_verify_url(text, text);


-- 1825: rpc_set_pental_verify_url is gone with the URL it set. Nothing reads a
-- signature verifier URL; Pental's signatures are checked in this database.
DROP FUNCTION IF EXISTS public.rpc_set_pental_verify_url(text, text);


-- ─── 10. Remove deprecated narrow-operator RPCs ──────────────────────────
-- After WebAuthn ships fully (sessions 1-5), these are obsolete:
--   - rpc_update_settings_branding
--   - rpc_update_smtp_operator
--   - rpc_admin_reset_mfa_operator
-- The user-driven, WebAuthn-bound flow replaces them. We DON'T drop them
-- here yet, that happens in session 5 once the portal flow is ready.
-- Leaving the comment for future reference.


COMMENT ON TABLE public.webauthn_credentials IS
'WebAuthn credentials registered by users. Each row is one authenticator (Touch ID, hardware key, etc). User can register multiple for redundancy.';

COMMENT ON FUNCTION public.rpc_apply_signed_settings(text, jsonb) IS
'Apply a settings change authorized by a WebAuthn assertion. The assertion must be over sha256(canonical_payload). Verified in this database (1812). Replay-protected via _pental_used_nonces.';

COMMENT ON TABLE public._pental_signed_changes_audit IS
'Every WebAuthn-signed change ever applied. Customer can review to detect malicious or unexpected changes. Indexed by credential_id and applied_at.';


-- ─── Confirmation email on every signed change ──────────────────────────
-- Closes the "portal-Vercel-compromise can lie about displayed diff" residual.
-- After every signed apply, the audited canonical payload is summarised in
-- an email to the credential owner. If the portal lied (showed "rename
-- company" while signing "change SMTP"), the email arrives within minutes
-- with the actual change content. User notices, reverts, alerts.
--
-- Distinct from the operator-RPC notification spam pattern: this fires only
-- on changes the user authorized (no false positives), reports what
-- ACTUALLY happened (so it confirms what the user intended), and is a
-- detection-not-prevention layer (doesn't block the legitimate flow).
-- 1798: NO SECRET IS PRINTED, IN PART OR WHOLE. Only `smtp_pass` was masked,
-- and even that kept its last four characters, while every other value in the
-- change went into the body as sent: a mailbox refresh token, a Stripe or AI
-- key. The body sits in the email log, which the firm's managers read, whether
-- or not it is ever sent. A secret field now says only that it changed (or was
-- cleared). The list is the one the signed-in grant on `settings` withholds;
-- `test_security_1798.py` holds the two together.
CREATE OR REPLACE FUNCTION public._redact_setting_fields(p_fields jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT CASE WHEN p_fields IS NULL OR jsonb_typeof(p_fields) <> 'object' THEN p_fields ELSE
    COALESCE((
      SELECT jsonb_object_agg(e.k,
        CASE WHEN e.k = ANY (public._settings_secret_columns())
                  OR e.k LIKE '%\_enc' ESCAPE '\'
             THEN CASE WHEN e.v IN ('"changed (value hidden)"'::jsonb, '"cleared (now empty)"'::jsonb)
                       THEN e.v  -- already redacted: the audit row is, and the notice redacts it again
                       WHEN e.v IS NULL OR e.v = 'null'::jsonb OR e.v = '""'::jsonb
                       THEN to_jsonb('cleared (now empty)'::text)
                       ELSE to_jsonb('changed (value hidden)'::text) END
             ELSE e.v END)
        FROM jsonb_each(p_fields) AS e(k, v)), '{}'::jsonb)
  END
$$;
REVOKE EXECUTE ON FUNCTION public._redact_setting_fields(jsonb) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._notify_signed_change_applied() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_email text;
  v_company text;
  v_summary text;
  v_field_count int;
  v_safe_payload jsonb;
BEGIN
  SELECT email INTO v_email FROM public.profiles
    WHERE auth_user_id = NEW.auth_user_id AND active = true LIMIT 1;
  IF v_email IS NULL THEN RETURN NEW; END IF;

  SELECT company_name INTO v_company FROM public.settings LIMIT 1;

  -- Build a redacted payload for the email body: a secret field says it
  -- changed and nothing more, so the email and the log hold no part of it.
  v_safe_payload := NEW.payload;
  IF jsonb_typeof(v_safe_payload->'fields') = 'object' THEN
    v_safe_payload := jsonb_set(v_safe_payload, '{fields}', public._redact_setting_fields(v_safe_payload->'fields'));
  END IF;

  v_field_count := COALESCE(jsonb_object_keys_count(v_safe_payload->'fields'), 0);

  IF NEW.operation = 'rpc_bulk_clean' THEN
    v_summary := '<strong style="color:#c62828">ALL DATA WIPED</strong>. Your portal database has been reset. If you initiated this, you are now in the re-provisioning flow on pental.io. If you did not, your account has been compromised. Restore from Supabase Point-in-Time Recovery immediately and contact support.';
  ELSIF NEW.operation = 'rpc_update_settings' THEN
    v_summary := 'Settings updated: <pre style="background:#f6f6f6;padding:0.6rem;border-radius:6px;font-size:0.8rem;overflow-x:auto">' ||
      public._html_esc((v_safe_payload->'fields')::text) ||
      '</pre>';
  ELSE
    v_summary := 'Operation: <code>' || public._html_esc(NEW.operation) || '</code>';
  END IF;

  BEGIN
    INSERT INTO public.email_notifications
      (to_email, subject, body, notification_type, status)
    VALUES (
      v_email,
      'Settings change applied to ' || COALESCE(v_company, 'your portal'),
      '<p>The following change was just applied to your portal at ' || now()::text || ' UTC, authorized via your security key.</p>' ||
      '<p>' || v_summary || '</p>' ||
      '<p style="font-size:0.85rem;color:#666">If this matches what you authorized on pental.io, no action needed. If not, your portal''s code may have been compromised: revert via Supabase dashboard, sign out all sessions, and contact support immediately.</p>',
      'signed_change_applied', 'pending'
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN NEW;
END;
$$;
REVOKE EXECUTE ON FUNCTION public._notify_signed_change_applied() FROM PUBLIC, anon, authenticated;

-- Helper: count keys in a jsonb object (Postgres has no built-in)
CREATE OR REPLACE FUNCTION public.jsonb_object_keys_count(j jsonb) RETURNS int
LANGUAGE sql IMMUTABLE AS $$
  SELECT count(*)::int FROM jsonb_object_keys(COALESCE(j, '{}'::jsonb));
$$;

DROP TRIGGER IF EXISTS notify_on_signed_change ON public._pental_signed_changes_audit;
CREATE TRIGGER notify_on_signed_change
  AFTER INSERT ON public._pental_signed_changes_audit
  FOR EACH ROW
  EXECUTE FUNCTION public._notify_signed_change_applied();

-- 1798: AND WHAT IS ALREADY STORED IS SCRUBBED. Every signed change before this
-- version kept its secrets in the audit row, and its notice kept them in the
-- email log. Both are rewritten on every run of this file, which changes
-- nothing once they are clean: the audit row keeps every field and says only
-- that a secret changed; a notice that printed one keeps its subject and date
-- and loses its body, since the rest of it was the same printout.
DO $scrub_signed_secrets$
DECLARE v_a integer := 0; v_n integer := 0;
BEGIN
  UPDATE public._pental_signed_changes_audit a
     SET payload = jsonb_set(a.payload, '{fields}', public._redact_setting_fields(a.payload->'fields'))
   WHERE jsonb_typeof(a.payload->'fields') = 'object'
     AND a.payload->'fields' IS DISTINCT FROM public._redact_setting_fields(a.payload->'fields');
  GET DIAGNOSTICS v_a = ROW_COUNT;
  UPDATE public.email_notifications e
     SET body = '<p>A settings change was applied to your portal through your security key. '
             || 'This record printed secret values, so its details were removed. The change '
             || 'itself is listed under Settings, Security.</p>'
   WHERE e.notification_type = 'signed_change_applied'
     AND e.body ~ '&quot;(smtp_pass|smtp_oauth_refresh|stripe_secret_key|stripe_webhook_secret|ai_api_key|teams_client_secret|zoom_client_secret|google_api_key|slack_bot_token|sso_google_client_secret|sso_ms_client_secret)&quot;|"(smtp_pass|smtp_oauth_refresh|stripe_secret_key|stripe_webhook_secret|ai_api_key|teams_client_secret|zoom_client_secret|google_api_key|slack_bot_token|sso_google_client_secret|sso_ms_client_secret)"'
     AND e.body !~ 'changed \(value hidden\)|cleared \(now empty\)';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_a + v_n > 0 THEN
    RAISE NOTICE 'signed changes: % audit row(s) and % notice(s) had secrets removed', v_a, v_n;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'signed-change secrets could not be scrubbed: %', SQLERRM;
END $scrub_signed_secrets$;


-- ─── 11. Extend MFA recovery to also clear WebAuthn credentials ──────────
-- When a user recovers MFA access via email code (rpc_clear_own_mfa_via_recovery
-- in byo-close-vercel-exfil.sql), we also want their WebAuthn credentials
-- cleared so they can re-enrol on the new device. Wrap the existing RPC
-- with a trigger that mirrors deletes.
--
-- We do this via a SECURITY DEFINER trigger on _pental_ops_audit: when an
-- 'rpc_clear_own_mfa_via_recovery' row is inserted, the trigger deletes
-- the user's webauthn_credentials.
CREATE OR REPLACE FUNCTION public._on_mfa_recovery_clear_webauthn() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_uid uuid;
BEGIN
  IF NEW.op <> 'rpc_clear_own_mfa_via_recovery' THEN RETURN NEW; END IF;

  -- The recovery RPC writes the audit row from auth.uid() context. We can
  -- read auth.uid() here because the trigger runs in the same transaction.
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RETURN NEW; END IF;

  DELETE FROM public.webauthn_credentials WHERE auth_user_id = v_uid;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS clear_webauthn_on_mfa_recovery ON public._pental_ops_audit;
CREATE TRIGGER clear_webauthn_on_mfa_recovery
  AFTER INSERT ON public._pental_ops_audit
  FOR EACH ROW
  EXECUTE FUNCTION public._on_mfa_recovery_clear_webauthn();

COMMENT ON FUNCTION public._on_mfa_recovery_clear_webauthn() IS
'When a user uses email-OTP MFA recovery, their WebAuthn credentials are deleted so they can re-enrol fresh on whatever device they recover on.';

-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-bulk-clean-webauthn-gate.sql ━━
-- ═══════════════════════════════════════════════════════════════════════════

-- ═══════════════════════════════════════════════════════════════════════════
-- byo-bulk-clean-webauthn-gate.sql
--
-- Apply to BYO projects AFTER:
--   byo-database.sql, byo-mfa-enforcement.sql, byo-database-security-patch.sql,
--   byo-bulk-ops-install-token-gate.sql, byo-management-token.sql,
--   byo-close-vercel-exfil.sql, byo-webauthn.sql
--
-- AND BEFORE byo-drop-operator-rpcs.sql (this patch coexists with that one).
--
-- PURPOSE
-- Closes the rpc_bulk_clean residual: previously a Vercel-compromise
-- attacker could wipe any BYO with the stored provision_secret. Now,
-- bulk_clean is allowed in three cases:
--
--   (a) BOOTSTRAP: BYO has no PROVISION_SECRET stored AND no admin profiles.
--       True only at fresh-install time, before any data exists.
--
--   (b) WEBAUTHN-AUTHORIZED: caller provides a valid WebAuthn assertion
--       signed by a registered admin authenticating "wipe and re-provision."
--       Verified by the existing webauthn-verify Edge Function.
--
--   (c) LEGACY FALLBACK: provision_secret valid AND no admin has yet enrolled
--       a WebAuthn credential. This bridges the rollout window, once at
--       least one admin enrols, the legacy path locks shut. Documented
--       residual until enrolment is complete.
--
-- After at least one WebAuthn credential is registered, only paths (a) and
-- (b) work. Path (a) requires a wiped DB to begin with, so a Vercel-
-- compromise attacker who wants to wipe a populated BYO has only path (b),
-- which they cannot satisfy without the user's authenticator.
--
-- Re-provisioning UX: customer clicks "wipe and re-provision" on pental.io,
-- pental.io stages a pending row with operation='rpc_bulk_clean', user is
-- redirected to portal /apply, taps Touch ID, BYO wipes itself. Same flow
-- as settings changes.
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── 1. Helper: detect "BYO has admins" ────────────────────────────────
CREATE OR REPLACE FUNCTION public._has_admin_profile() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE active = true AND role IN ('admin', 'senior')
  );
$$;
REVOKE EXECUTE ON FUNCTION public._has_admin_profile() FROM PUBLIC, anon, authenticated;


-- ─── 3. Replace rpc_bulk_clean with the gated version ────────────────────
-- Same body as before; new gate at the top.
CREATE OR REPLACE FUNCTION public.rpc_bulk_clean(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault, pg_temp AS $$
DECLARE
  v_new_secret text;
  v_install_token text;
  v_install_slot uuid;
  v_mode text;
  v_secret_stored text;
  v_has_admin boolean;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('rpc_bulk_clean'));

  -- ── Gate: who is allowed to wipe this BYO? ────────────────────────────
  SELECT value INTO v_secret_stored FROM public._internal_secrets WHERE key = 'PROVISION_SECRET';
  v_has_admin := public._has_admin_profile();

  -- Path (a), bootstrap. No secret stored AND no admins. Fresh install
  -- only. This is the legitimate first-time provisioning case where Pental
  -- needs to set up the database before any admin exists.
  IF (v_secret_stored IS NULL OR v_secret_stored = '') AND NOT v_has_admin THEN
    NULL; -- Allow. Continue to wipe.
  -- Path (b), re-provisioning of a populated BYO. ALWAYS requires
  -- WebAuthn-bound apply via rpc_apply_signed_bulk_clean. Direct calls
  -- with provision_secret are REJECTED.
  ELSE
    RAISE EXCEPTION 'rpc_bulk_clean requires WebAuthn-bound authorization on populated databases. Use the wipe-and-re-provision flow on pental.io which routes through your portal for security-key authorization.';
  END IF;

  -- ── End new gate. Original wipe body follows ──────────────────────────
  PERFORM set_config('pental.bypass_protect', 'true', true);
  DELETE FROM payment_events WHERE true; DELETE FROM qa_comments WHERE true;
  DELETE FROM assessment_files WHERE true; DELETE FROM assessment_comments WHERE true;
  DELETE FROM timeline_events WHERE true; DELETE FROM tickets WHERE true;
  DELETE FROM feedback WHERE true; DELETE FROM email_notifications WHERE true;
  DELETE FROM contractor_payments WHERE true; DELETE FROM meeting_attendees WHERE true;
  DELETE FROM meetings WHERE true;
  DELETE FROM kb_entries WHERE true; PERFORM set_config('pental.wiping', 'on', true); DELETE FROM invoices WHERE true;
  DELETE FROM proposals WHERE true; DELETE FROM findings WHERE true;
  DELETE FROM assessments WHERE true; DELETE FROM login_codes WHERE true;
  DELETE FROM _internal_secrets WHERE key NOT IN ('PROVISION_SECRET', 'PENTAL_VERIFY_URL');
  DELETE FROM _encryption_keys WHERE true;
  DELETE FROM _credentials_key WHERE true;
  UPDATE profiles SET client_id = NULL WHERE client_id IS NOT NULL;
  DELETE FROM auth.identities WHERE true; DELETE FROM auth.sessions WHERE true;
  DELETE FROM auth.refresh_tokens WHERE true; DELETE FROM auth.mfa_factors WHERE true;
  DELETE FROM auth.users WHERE true;
  DELETE FROM clients WHERE true; DELETE FROM profiles WHERE true; DELETE FROM settings WHERE true;
  DELETE FROM _internal_secrets WHERE key = 'PROVISION_SECRET';
  DELETE FROM _pental_used_nonces WHERE true;
  DELETE FROM webauthn_credentials WHERE true;
  DELETE FROM _pental_signed_changes_audit WHERE true;
  DELETE FROM _pental_ops_audit WHERE true;
  -- (Removed: DELETE FROM _pental_used_install_tokens, install token state
  -- now lives in Vault, not in a dedicated table. Cleared below by writing a
  -- fresh hash to the install_token_hash Vault slot.)

  -- Generate new provision_secret + install_token
  v_new_secret := encode(extensions.gen_random_bytes(32), 'hex');
  v_install_token := encode(extensions.gen_random_bytes(32), 'hex');

  -- Store provision_secret as SHA-256 hash (matches _validate_provision_secret).
  -- The legacy bcrypt path was crypt() but _validate_provision_secret only
  -- recognises 64-char lowercase hex (sha256), so write that.
  INSERT INTO public._internal_secrets(key, value)
    VALUES ('PROVISION_SECRET', encode(extensions.digest(v_new_secret, 'sha256'), 'hex'));

  -- Store install_token hash in Vault (single-use, consumed by rpc_install_pental_keys)
  SELECT id INTO v_install_slot FROM vault.decrypted_secrets WHERE name = 'install_token_hash';
  IF v_install_slot IS NULL THEN
    PERFORM vault.create_secret(
      encode(extensions.digest(v_install_token, 'sha256'), 'hex'),
      'install_token_hash',
      'SHA-256 of the current install token. Single-use; cleared after rpc_install_pental_keys.'
    );
  ELSE
    PERFORM vault.update_secret(v_install_slot, encode(extensions.digest(v_install_token, 'sha256'), 'hex'));
  END IF;

  -- Reset pubkey slots so a re-install is required after a clean.
  DECLARE v_reset_id uuid; BEGIN FOR v_reset_id IN SELECT id FROM vault.decrypted_secrets WHERE name IN ('pental_pubkey_a', 'pental_pubkey_b') LOOP PERFORM vault.update_secret(v_reset_id, ''); END LOOP; END;

  RETURN jsonb_build_object(
    'success', true,
    'provision_secret', v_new_secret,
    'install_token', v_install_token
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_bulk_clean(text, jsonb) TO anon, authenticated, service_role;


-- ─── 4. rpc_apply_signed_bulk_clean, WebAuthn-authorized wipe ──────────
-- Called by the portal after a customer authorizes wipe-and-re-provision
-- via WebAuthn. Verifies the assertion exactly like rpc_apply_signed_settings,
-- then performs the bulk_clean.
DROP FUNCTION IF EXISTS public.rpc_apply_signed_bulk_clean(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_apply_signed_bulk_clean(
  p_payload_canonical text,
  p_assertion jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, vault, pg_temp AS $$
DECLARE
  v_payload jsonb;
  v_op text;
  v_nonce text;
  v_exp bigint;
  v_credential_id text;
  v_public_key text;
  v_owner_uid uuid;
  v_owner_email text;
  v_challenge_b64u text;
  v_http_response jsonb;
  v_rp_id text;
  v_origin text;
  v_clean_result jsonb;
  v_new_secret text;
  v_install_token text;
  v_install_slot uuid;
BEGIN
  -- Parse payload
  BEGIN
    v_payload := p_payload_canonical::jsonb;
  EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'Invalid canonical payload'; END;

  v_op := v_payload->>'op';
  v_nonce := v_payload->>'nonce';
  v_exp := (v_payload->>'exp')::bigint;
  IF v_op IS NULL OR v_nonce IS NULL OR v_exp IS NULL THEN
    RAISE EXCEPTION 'Payload missing required fields';
  END IF;
  IF v_op <> 'rpc_bulk_clean' THEN
    RAISE EXCEPTION 'This RPC only handles rpc_bulk_clean operations';
  END IF;
  IF v_exp < extract(epoch from now()) THEN RAISE EXCEPTION 'Payload expired'; END IF;

  -- Replay protection
  BEGIN
    INSERT INTO public._pental_used_nonces(nonce, op) VALUES (v_nonce, v_op);
  EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'Nonce already used'; END;

  -- Look up credential
  v_credential_id := p_assertion->>'credential_id';
  IF v_credential_id IS NULL THEN RAISE EXCEPTION 'Assertion missing credential_id'; END IF;

  SELECT public_key, auth_user_id, rp_id
    INTO v_public_key, v_owner_uid, v_rp_id
    FROM public.webauthn_credentials
    WHERE credential_id = v_credential_id;
  IF v_public_key IS NULL THEN RAISE EXCEPTION 'Unknown credential'; END IF;

  -- Owner must be admin/senior
  SELECT email INTO v_owner_email FROM public.profiles
    WHERE auth_user_id = v_owner_uid AND active = true
      AND role IN ('admin', 'senior')
    LIMIT 1;
  IF v_owner_email IS NULL THEN RAISE EXCEPTION 'Credential owner is not an active admin'; END IF;

  -- Compute challenge
  v_challenge_b64u := encode(extensions.digest(p_payload_canonical, 'sha256'), 'base64');
  v_challenge_b64u := replace(v_challenge_b64u, E'\n', '');
  v_challenge_b64u := rtrim(v_challenge_b64u, '=');
  v_challenge_b64u := translate(v_challenge_b64u, '+/', '-_');

  v_origin := p_assertion->>'expected_origin';
  IF v_origin IS NULL THEN RAISE EXCEPTION 'Assertion missing expected_origin'; END IF;

  -- 1812: checked here, in this database, with no call to anything. The
  -- reasons are the gateway's (lib/attest.js), which did the same for
  -- gateway-hosted firms already.
  v_http_response := public._webauthn_verify_assertion(
    v_public_key, v_challenge_b64u,
    p_assertion->>'client_data_json', p_assertion->>'authenticator_data', p_assertion->>'signature',
    v_origin, v_rp_id
  );
  IF v_http_response IS NULL OR (v_http_response->>'ok')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'WebAuthn signature invalid: %', COALESCE(v_http_response->>'reason', 'unknown');
  END IF;

  -- Audit BEFORE wiping. This row gets deleted in the wipe alongside any
  -- email queued on BYO. The portal will instead call master's
  -- rpc_mark_apply_consumed after this RPC returns success, and master
  -- queues the bulk_clean confirmation email there (which survives because
  -- master is unaffected by the BYO wipe).
  INSERT INTO public._pental_signed_changes_audit
    (credential_id, auth_user_id, operation, payload, source_origin)
  VALUES (v_credential_id, v_owner_uid, 'rpc_bulk_clean', v_payload, v_origin);

  -- Now actually wipe. We can't easily call rpc_bulk_clean recursively
  -- (it would re-check the gate and reject because admins exist). Inline
  -- the wipe body. After this returns, ALL data including the audit row
  -- we just inserted is gone, but the row also doesn't matter anymore
  -- because there's nothing left.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  DELETE FROM payment_events WHERE true; DELETE FROM qa_comments WHERE true;
  DELETE FROM assessment_files WHERE true; DELETE FROM assessment_comments WHERE true;
  DELETE FROM timeline_events WHERE true; DELETE FROM tickets WHERE true;
  DELETE FROM feedback WHERE true; DELETE FROM email_notifications WHERE true;
  DELETE FROM contractor_payments WHERE true; DELETE FROM meeting_attendees WHERE true;
  DELETE FROM meetings WHERE true;
  DELETE FROM kb_entries WHERE true; PERFORM set_config('pental.wiping', 'on', true); DELETE FROM invoices WHERE true;
  DELETE FROM proposals WHERE true; DELETE FROM findings WHERE true;
  DELETE FROM assessments WHERE true; DELETE FROM login_codes WHERE true;
  DELETE FROM _internal_secrets WHERE key NOT IN ('PROVISION_SECRET', 'PENTAL_VERIFY_URL');
  DELETE FROM _encryption_keys WHERE true;
  DELETE FROM _credentials_key WHERE true;
  UPDATE profiles SET client_id = NULL WHERE client_id IS NOT NULL;
  DELETE FROM auth.identities WHERE true; DELETE FROM auth.sessions WHERE true;
  DELETE FROM auth.refresh_tokens WHERE true; DELETE FROM auth.mfa_factors WHERE true;
  DELETE FROM auth.users WHERE true;
  DELETE FROM clients WHERE true; DELETE FROM profiles WHERE true; DELETE FROM settings WHERE true;
  DELETE FROM _internal_secrets WHERE key = 'PROVISION_SECRET';
  DELETE FROM _pental_used_nonces WHERE true;
  DELETE FROM webauthn_credentials WHERE true;
  DELETE FROM _pental_signed_changes_audit WHERE true;
  DELETE FROM _pental_ops_audit WHERE true;
  -- (Removed: DELETE FROM _pental_used_install_tokens, install token state
  -- now lives in Vault, not in a dedicated table.)

  -- Issue new provision_secret + install_token same as rpc_bulk_clean
  v_new_secret := encode(extensions.gen_random_bytes(32), 'hex');
  v_install_token := encode(extensions.gen_random_bytes(32), 'hex');

  -- Store provision_secret as SHA-256 hash (matches _validate_provision_secret).
  INSERT INTO public._internal_secrets(key, value)
    VALUES ('PROVISION_SECRET', encode(extensions.digest(v_new_secret, 'sha256'), 'hex'));

  -- Defensive re-seed of verifier URLs. The earlier DELETE preserves them
  -- via NOT IN, but if a BYO ever ended up with NULL/empty values from a
  -- prior install ordering (the historical bug that caused intermittent
  -- "WebAuthn verifier URL not configured" errors), bulk_clean is the
  -- right place to repair them, every Pro→Enterprise upgrade goes
  -- through it. Conditional UPSERT preserves any deliberate operator
  -- override (non-empty non-canonical value).
  -- 1812: no passkey verifier URL is seeded; passkeys are checked in this database.
  -- 1825: nor a signature verifier URL; signatures are checked here too.

  -- Store install_token hash in Vault (single-use, consumed by rpc_install_pental_keys)
  SELECT id INTO v_install_slot FROM vault.decrypted_secrets WHERE name = 'install_token_hash';
  IF v_install_slot IS NULL THEN
    PERFORM vault.create_secret(
      encode(extensions.digest(v_install_token, 'sha256'), 'hex'),
      'install_token_hash',
      'SHA-256 of the current install token. Single-use; cleared after rpc_install_pental_keys.'
    );
  ELSE
    PERFORM vault.update_secret(v_install_slot, encode(extensions.digest(v_install_token, 'sha256'), 'hex'));
  END IF;

  -- Reset pubkey slots so a re-install is required after a clean.
  DECLARE v_reset_id uuid; BEGIN FOR v_reset_id IN SELECT id FROM vault.decrypted_secrets WHERE name IN ('pental_pubkey_a', 'pental_pubkey_b') LOOP PERFORM vault.update_secret(v_reset_id, ''); END LOOP; END;

  v_clean_result := jsonb_build_object(
    'success', true,
    'provision_secret', v_new_secret,
    'install_token', v_install_token
  );

  RETURN v_clean_result;
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_apply_signed_bulk_clean(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_apply_signed_bulk_clean(text, jsonb) TO anon, authenticated, service_role;


COMMENT ON FUNCTION public.rpc_bulk_clean(text, jsonb) IS
'Wipe BYO data. Allowed in three cases: (a) bootstrap on fresh install, (b) WebAuthn-authorized via rpc_apply_signed_bulk_clean only (this fn rejects direct calls when admins+webauthn exist), (c) legacy provision_secret while no admin has enrolled WebAuthn (rollout fallback).';

COMMENT ON FUNCTION public.rpc_apply_signed_bulk_clean(text, jsonb) IS
'WebAuthn-authorized BYO wipe. Caller is pental.io after the user redirected to portal /apply, reviewed the wipe warning, and tapped their authenticator. Vercel-compromise alone cannot forge.';


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-mfa-self-management ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-mfa-self-management.sql
--
-- Brings BYO Supabase up to parity with master for the MFA self-management
-- and WebAuthn-as-MFA features added in session 109. Designed to layer on
-- top of byo-setup.sql; idempotent.
--
-- What this adds:
--   1. settings.mfa_methods_allowed jsonb (admin choice of allowed methods)
--   2. rpc_clear_own_totp(), user clears their own TOTP, fresh-MFA gated
--   3. webauthn_credentials own-delete RLS + last-method protection trigger
--   4. profiles totp_secret last-method protection trigger
--   5. webauthn_credentials stamp trigger (insert / last_used_at update)
--   6. rpc_mfa_methods_for_user(p_email), returns allowed + enrolled
--   7. WebAuthn-as-MFA infra: webauthn_mfa_challenges + rpc_mfa_webauthn_challenge
--   8. Extension of rpc_apply_signed_settings to allow op='mfa_assert', so
--      MFA-WebAuthn assertions are verified by the customer's existing Edge
--      Function (preserves Vercel-compromise resistance on BYO)
--
-- Trust model on BYO vs master:
--   On master, MFA-WebAuthn assertions are verified server-side in Vercel
--   using @simplewebauthn/server with master service_role. That's fine on
--   master because Vercel already has master service_role.
--
--   On BYO, Vercel does NOT have BYO service_role, that's the point of BYO.
--   So we route MFA-WebAuthn assertions through the same customer-controlled
--   Edge Function that already verifies settings-apply assertions. Same
--   trust boundary, additional op type.
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── 1. settings.mfa_methods_allowed ─────────────────────────────────────
ALTER TABLE public.settings
  ADD COLUMN IF NOT EXISTS mfa_methods_allowed jsonb
    NOT NULL DEFAULT '{"totp":true,"webauthn":true}'::jsonb;

UPDATE public.settings
   SET mfa_methods_allowed = '{"totp":true,"webauthn":true}'::jsonb
 WHERE mfa_methods_allowed IS NULL;


-- ─── 2. rpc_clear_own_totp ──────────────────────────────────────────────
DROP FUNCTION IF EXISTS public.rpc_clear_own_totp();
CREATE OR REPLACE FUNCTION public.rpc_clear_own_totp()
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE v_profile_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Re-verify MFA before changing security settings' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_profile_id FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  -- Same column guard as rpc_save_totp_secret: it only lets admin/senior touch
  -- totp_secret, so this path failed with "Cannot change MFA config" for every
  -- other role. This function has already decided the caller is entitled to the
  -- change, so raise the guard's own flag and drop it straight after.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles
     SET totp_secret = NULL,
         totp_attempts = 0,
         totp_locked_until = NULL
   WHERE id = v_profile_id;
  PERFORM set_config('pental.bypass_protect', 'false', true);

  RETURN FOUND;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_clear_own_totp() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_clear_own_totp() TO authenticated;


-- ─── 3. webauthn_credentials own-delete RLS ─────────────────────────────
DROP POLICY IF EXISTS webauthn_own_delete ON public.webauthn_credentials;
CREATE POLICY webauthn_own_delete ON public.webauthn_credentials
  FOR DELETE TO authenticated
  USING (
    auth_user_id = auth.uid()
    AND public.mfa_is_fresh()
  );

GRANT DELETE ON public.webauthn_credentials TO authenticated;


-- ─── 4. Last-method protection triggers ────────────────────────────────
DROP FUNCTION IF EXISTS public._tr_prevent_last_mfa_removal_totp() CASCADE;
CREATE OR REPLACE FUNCTION public._tr_prevent_last_mfa_removal_totp()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE v_webauthn_count int;
BEGIN
  -- Operator escape hatch: rpc_admin_reset_all_portal_mfa sets this for
  -- the duration of its transaction so a sequential TOTP+WebAuthn wipe
  -- doesn't trip whichever trigger fires second (clearing one leaves the
  -- other as the "last method" which would otherwise be refused).
  IF current_setting('pental.bypass_protect', true) = 'true' THEN RETURN NEW; END IF;
  IF (NEW.totp_secret IS NULL OR length(NEW.totp_secret) = 0)
     AND OLD.totp_secret IS NOT NULL AND length(OLD.totp_secret) > 0
     AND NEW.auth_user_id IS NOT NULL THEN
    SELECT count(*) INTO v_webauthn_count
      FROM public.webauthn_credentials
      WHERE auth_user_id = NEW.auth_user_id;
    IF v_webauthn_count = 0 THEN
      RAISE EXCEPTION 'Cannot remove your only MFA method. Add another method first.'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_prevent_last_mfa_removal_totp ON public.profiles;
CREATE TRIGGER tr_prevent_last_mfa_removal_totp
BEFORE UPDATE OF totp_secret ON public.profiles
FOR EACH ROW EXECUTE FUNCTION public._tr_prevent_last_mfa_removal_totp();


DROP FUNCTION IF EXISTS public._tr_prevent_last_mfa_removal_webauthn() CASCADE;
CREATE OR REPLACE FUNCTION public._tr_prevent_last_mfa_removal_webauthn()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_other_webauthn int;
  v_has_totp boolean;
BEGIN
  IF current_setting('pental.bypass_protect', true) = 'true' THEN RETURN OLD; END IF;
  SELECT count(*) INTO v_other_webauthn
    FROM public.webauthn_credentials
    WHERE auth_user_id = OLD.auth_user_id
      AND id != OLD.id;
  IF v_other_webauthn > 0 THEN
    RETURN OLD;
  END IF;
  SELECT (totp_secret IS NOT NULL AND length(totp_secret) > 0)
    INTO v_has_totp
    FROM public.profiles
    WHERE auth_user_id = OLD.auth_user_id AND active = true
    LIMIT 1;
  IF NOT COALESCE(v_has_totp, false) THEN
    RAISE EXCEPTION 'Cannot remove your only MFA method. Add another method first.'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS tr_prevent_last_mfa_removal_webauthn ON public.webauthn_credentials;
CREATE TRIGGER tr_prevent_last_mfa_removal_webauthn
BEFORE DELETE ON public.webauthn_credentials
FOR EACH ROW EXECUTE FUNCTION public._tr_prevent_last_mfa_removal_webauthn();


-- ─── 5. Stamp trigger on webauthn_credentials ──────────────────────────
-- Stamps mfa_verified_at on registration (INSERT) AND on each successful
-- assertion (last_used_at touch). The registration ceremony itself
-- (navigator.credentials.create) requires on-device user verification,
-- so the insert IS proof-of-possession for any legitimate flow. The
-- earlier v20 hardening (insert branch removed) defended against an
-- attacker with a stolen session JWT registering a public key they
-- don't control, but such an attacker already has session access, and
-- the alternative was every legitimate first-time enrolment failing to
-- stamp because the post-register assertion is flaky on platform
-- authenticators (Touch ID / Windows Hello sometimes return null
-- immediately after a registration ceremony, and any failure of the
-- Edge Function HTTP call leaves the trigger un-fired).
DROP FUNCTION IF EXISTS public._tr_mfa_stamp_on_webauthn() CASCADE;
CREATE OR REPLACE FUNCTION public._tr_mfa_stamp_on_webauthn()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public._stamp_mfa_verified(NEW.auth_user_id);
  ELSIF TG_OP = 'UPDATE' AND NEW.last_used_at IS DISTINCT FROM OLD.last_used_at THEN
    PERFORM public._stamp_mfa_verified(NEW.auth_user_id);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_mfa_stamp_on_webauthn ON public.webauthn_credentials;
CREATE TRIGGER tr_mfa_stamp_on_webauthn
AFTER INSERT OR UPDATE OF last_used_at ON public.webauthn_credentials
FOR EACH ROW EXECUTE FUNCTION public._tr_mfa_stamp_on_webauthn();


-- ─── 5b. Self-heal RPC: ensures WebAuthn MFA stamp trigger is installed ──
-- BYO databases provisioned from older byo-setup.sql versions that
-- predated the webauthn-as-mfa stamp trigger won't have it. Without it,
-- WebAuthn enrolment/verification doesn't stamp mfa_verified_at,
-- mfa_is_fresh() returns false, RLS reads return 0 rows, and the user
-- sees an empty portal + repeating MFA prompt after Pro→Enterprise
-- upgrade.
--
-- This RPC re-installs the trigger function and trigger idempotently.
-- Migration code (migrateMasterToBYO) calls it during upgrade so any
-- BYO that doesn't have it self-heals on the spot, no operator action
-- needed.
--
-- Service-role only, DDL on public schema must not be exposed broadly.
-- But unlike most BYO RPCs, this one does NOT take p_secret/p_auth, it's
-- called via service_role JWT only, which the migration code uses anyway.
CREATE OR REPLACE FUNCTION public.rpc_ensure_mfa_stamp_trigger(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_existed_before boolean;
  v_authed boolean := false;
BEGIN
  -- Auth: provision_secret OR signed envelope (same pattern as rpc_export_*).
  -- Both are held only by Pental's server. Without this check, any anon
  -- holder of the publishable key could trigger DDL, though the DDL is
  -- idempotent re-installation of a known-good trigger, this still falls
  -- foul of the "no public DDL" principle.
  IF p_secret IS NOT NULL AND public._validate_provision_secret(p_secret) THEN
    v_authed := true;
  ELSIF p_auth IS NOT NULL THEN
    BEGIN
      v_authed := public._verify_pental_auth(p_auth, 'rpc_ensure_mfa_stamp_trigger');
    EXCEPTION WHEN OTHERS THEN
      v_authed := false;
    END;
  END IF;

  IF NOT v_authed THEN
    RAISE EXCEPTION 'Invalid secret or session required';
  END IF;

  v_existed_before := EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'tr_mfa_stamp_on_webauthn'
      AND tgrelid = 'public.webauthn_credentials'::regclass
  );

  CREATE OR REPLACE FUNCTION public._tr_mfa_stamp_on_webauthn()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp
  AS $fn$
  BEGIN
    IF TG_OP = 'INSERT' THEN
      PERFORM public._stamp_mfa_verified(NEW.auth_user_id);
    ELSIF TG_OP = 'UPDATE' AND NEW.last_used_at IS DISTINCT FROM OLD.last_used_at THEN
      PERFORM public._stamp_mfa_verified(NEW.auth_user_id);
    END IF;
    RETURN NEW;
  END;
  $fn$;

  DROP TRIGGER IF EXISTS tr_mfa_stamp_on_webauthn ON public.webauthn_credentials;
  CREATE TRIGGER tr_mfa_stamp_on_webauthn
    AFTER INSERT OR UPDATE OF last_used_at ON public.webauthn_credentials
    FOR EACH ROW EXECUTE FUNCTION public._tr_mfa_stamp_on_webauthn();

  RETURN jsonb_build_object(
    'success', true,
    'existed_before', v_existed_before,
    'reinstalled', NOT v_existed_before
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_ensure_mfa_stamp_trigger(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_ensure_mfa_stamp_trigger(text, jsonb) TO anon, authenticated, service_role;


-- ─── 6. rpc_mfa_methods_for_user ───────────────────────────────────────
DROP FUNCTION IF EXISTS public.rpc_mfa_methods_for_user(text);
CREATE OR REPLACE FUNCTION public.rpc_mfa_methods_for_user(p_email text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_caller_email text;
  v_caller_role text;
  v_target_auth_id uuid;
  v_has_totp boolean;
  v_webauthn_count int;
  v_methods_allowed jsonb;
  v_email_l text := lower(trim(p_email));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT email, role INTO v_caller_email, v_caller_role
    FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_caller_email IS NULL THEN RAISE EXCEPTION 'Profile not found'; END IF;

  IF lower(v_caller_email) = v_email_l THEN
    SELECT
      (totp_secret IS NOT NULL AND length(totp_secret) > 0),
      auth_user_id
      INTO v_has_totp, v_target_auth_id
      FROM public.profiles WHERE lower(email) = v_email_l LIMIT 1;
  ELSIF v_caller_role = 'admin' THEN
    SELECT
      (totp_secret IS NOT NULL AND length(totp_secret) > 0),
      auth_user_id
      INTO v_has_totp, v_target_auth_id
      FROM public.profiles WHERE lower(email) = v_email_l LIMIT 1;
  ELSE
    RAISE EXCEPTION 'Cannot check MFA for other users';
  END IF;

  SELECT count(*) INTO v_webauthn_count
    FROM public.webauthn_credentials
    WHERE auth_user_id = v_target_auth_id;

  SELECT mfa_methods_allowed INTO v_methods_allowed
    FROM public.settings LIMIT 1;
  IF v_methods_allowed IS NULL THEN
    v_methods_allowed := '{"totp":true,"webauthn":true}'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_methods_allowed,
    'enrolled', jsonb_build_object(
      'totp', COALESCE(v_has_totp, false),
      'webauthn', v_webauthn_count > 0
    ),
    'webauthn_count', v_webauthn_count
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_mfa_methods_for_user(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_mfa_methods_for_user(text) TO authenticated;


-- ─── 7. webauthn_mfa_challenges + challenge RPC ───────────────────────
CREATE TABLE IF NOT EXISTS public.webauthn_mfa_challenges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  auth_user_id uuid NOT NULL,
  nonce text NOT NULL UNIQUE,
  purpose text NOT NULL DEFAULT 'authenticate' CHECK (purpose IN ('register','authenticate')),
  expires_at timestamptz NOT NULL DEFAULT (now() + interval '5 minutes'),
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_webauthn_mfa_chal_user
  ON public.webauthn_mfa_challenges(auth_user_id, expires_at);

ALTER TABLE public.webauthn_mfa_challenges ENABLE ROW LEVEL SECURITY;
-- No authenticated policies, only RPCs (SECURITY DEFINER) touch this table.


DROP FUNCTION IF EXISTS public.rpc_mfa_webauthn_challenge();
CREATE OR REPLACE FUNCTION public.rpc_mfa_webauthn_challenge()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_uid uuid;
  v_nonce text;
  v_credentials jsonb;
  v_rp_id text;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  v_nonce := encode(extensions.gen_random_bytes(32), 'hex');

  DELETE FROM public.webauthn_mfa_challenges
   WHERE auth_user_id = v_uid
     AND (expires_at < now() OR consumed_at IS NOT NULL);

  INSERT INTO public.webauthn_mfa_challenges (auth_user_id, nonce, purpose)
    VALUES (v_uid, v_nonce, 'authenticate');

  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', credential_id, 'type', 'public-key')), '[]'::jsonb)
    INTO v_credentials
    FROM public.webauthn_credentials
    WHERE auth_user_id = v_uid;

  SELECT rp_id INTO v_rp_id
    FROM public.webauthn_credentials
    WHERE auth_user_id = v_uid
    ORDER BY COALESCE(last_used_at, created_at) DESC NULLS LAST
    LIMIT 1;

  RETURN jsonb_build_object(
    'nonce', v_nonce,
    'credentials', v_credentials,
    'rp_id', v_rp_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_mfa_webauthn_challenge() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_mfa_webauthn_challenge() TO authenticated;


-- ─── 8. rpc_apply_signed_settings, extend with mfa_assert op ──────────
-- Rewrites the function preserving all existing behaviour. Only changes:
--   1. Allowlist now includes 'mfa_assert'
--   2. Owner role check is relaxed for mfa_assert (any active profile can
--      assert their own MFA, but settings ops still require admin/senior)
--   3. New ELSIF branch for 'mfa_assert' enforces caller-owns-credential
--
-- The last_used_at touch (already in the original) fires the stamp trigger,
-- which writes mfa_verified_at via _stamp_mfa_verified. The user must
-- refresh their JWT to pick up the new claim.
DROP FUNCTION IF EXISTS public.rpc_apply_signed_settings(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_apply_signed_settings(
  p_payload_canonical text,
  p_assertion jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_payload jsonb;
  v_op text;
  v_nonce text;
  v_exp bigint;
  v_credential_id text;
  v_public_key text;
  v_owner_uid uuid;
  v_challenge_b64u text;
  v_http_response jsonb;
  v_rp_id text;
  v_origin text;
  v_owner_email text;
  v_attested boolean;
BEGIN
  -- ── Parse and validate payload ────────────────────────────────────────
  BEGIN
    v_payload := p_payload_canonical::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Invalid canonical payload: not valid JSON';
  END;

  v_op := v_payload->>'op';
  v_nonce := v_payload->>'nonce';
  v_exp := (v_payload->>'exp')::bigint;

  IF v_op IS NULL OR v_nonce IS NULL OR v_exp IS NULL THEN
    RAISE EXCEPTION 'Payload missing required fields (op, nonce, exp)';
  END IF;

  IF v_exp < extract(epoch from now()) THEN
    RAISE EXCEPTION 'Payload expired';
  END IF;

  -- Replay protection
  BEGIN
    INSERT INTO public._pental_used_nonces(nonce, op) VALUES (v_nonce, v_op);
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Nonce already used';
  END;

  -- Allowlist (extended with mfa_assert). 1810: no MFA reset. 'rpc_admin_reset_mfa'
  -- and 'rpc_clear_mfa' were accepted here with no session at all, approved by
  -- the passkey verifier alone, and that verifier is Pental's. A firm's admin
  -- resets MFA on the portal's Users screen, signed in with fresh MFA.
  IF v_op NOT IN ('rpc_update_settings', 'mfa_assert') THEN
    RAISE EXCEPTION 'Operation not allowed via signed apply: %', v_op;
  END IF;

  -- ── Look up the credential ────────────────────────────────────────────
  v_credential_id := p_assertion->>'credential_id';
  IF v_credential_id IS NULL THEN
    RAISE EXCEPTION 'Assertion missing credential_id';
  END IF;

  SELECT public_key, auth_user_id, rp_id
    INTO v_public_key, v_owner_uid, v_rp_id
    FROM public.webauthn_credentials
    WHERE credential_id = v_credential_id;

  IF v_public_key IS NULL THEN
    RAISE EXCEPTION 'Unknown credential';
  END IF;

  -- Settings-apply ops require admin/senior owner; mfa_assert just requires
  -- an active profile (the user is asserting their own MFA).
  IF v_op = 'rpc_update_settings' THEN
    SELECT email INTO v_owner_email
      FROM public.profiles
      WHERE auth_user_id = v_owner_uid AND active = true
        AND role IN ('admin', 'senior')
      LIMIT 1;
    IF v_owner_email IS NULL THEN
      RAISE EXCEPTION 'Credential owner is not an active admin';
    END IF;
  ELSE
    SELECT email INTO v_owner_email
      FROM public.profiles
      WHERE auth_user_id = v_owner_uid AND active = true
      LIMIT 1;
    IF v_owner_email IS NULL THEN
      RAISE EXCEPTION 'Credential owner is not an active user';
    END IF;
  END IF;

  -- ── Compute the challenge: sha256(canonical payload bytes) ─────────────
  v_challenge_b64u := encode(extensions.digest(p_payload_canonical, 'sha256'), 'base64');
  v_challenge_b64u := replace(v_challenge_b64u, E'\n', '');
  v_challenge_b64u := rtrim(v_challenge_b64u, '=');
  v_challenge_b64u := translate(v_challenge_b64u, '+/', '-_');

  v_origin := p_assertion->>'expected_origin';
  IF v_origin IS NULL THEN
    RAISE EXCEPTION 'Assertion missing expected_origin';
  END IF;

  -- ── 1803: the gateway verified this assertion already? ────────────────
  -- Its header covers the credential and the exact bytes that were signed
  -- over; a header that does not match is a refusal, not a fall-through.
  -- 1810: this branch was in the earlier definition of this function and
  -- not in this one, the one Postgres keeps, so a passkey on a gateway
  -- database (which has no http extension) failed at the verifier call.
  v_attested := public._pental_attested('webauthn|' || v_credential_id || '|' || encode(extensions.digest(p_payload_canonical, 'sha256'), 'hex'));
  IF v_attested IS FALSE THEN
    RAISE EXCEPTION 'WebAuthn signature invalid: gateway attestation did not match';
  END IF;
  -- 1812: the gateway's verdict is no longer relied on; the check below runs
  -- for every caller, gateway or not. A header that does not match is still
  -- a refusal (nobody but the gateway can write one).
  -- 1812: checked here, in this database, with no call to anything. The
  -- reasons are the gateway's (lib/attest.js), which did the same for
  -- gateway-hosted firms already.
  v_http_response := public._webauthn_verify_assertion(
    v_public_key, v_challenge_b64u,
    p_assertion->>'client_data_json', p_assertion->>'authenticator_data', p_assertion->>'signature',
    v_origin, v_rp_id
  );
  IF v_http_response IS NULL OR (v_http_response->>'ok')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'WebAuthn signature invalid: %', COALESCE(v_http_response->>'reason', 'unknown');
  END IF;

  -- ── Update last_used_at on the credential ─────────────────────────────
  -- For mfa_assert this is the critical step: it fires the stamp trigger
  -- which writes mfa_verified_at via _stamp_mfa_verified. 1810: only when
  -- the session is the credential owner's. The verifier's word alone used
  -- to stamp the owner fresh with no session at all, and the verifier is
  -- Pental's, so a settings change could have made an administrator's
  -- next session fresh on Pental's say-so. A settings change from another
  -- session still applies; it just proves nothing about freshness.
  IF auth.uid() IS NOT NULL AND auth.uid() = v_owner_uid THEN
    UPDATE public.webauthn_credentials
      SET last_used_at = now()
      WHERE credential_id = v_credential_id;
  END IF;

  -- ── Audit BEFORE applying ─────────────────────────────────────────────
  -- 1798: the record says a secret changed, never what it became. It is read
  -- by the firm's admins and seniors, and a column grant withholds these same
  -- values from them everywhere else.
  INSERT INTO public._pental_signed_changes_audit
    (credential_id, auth_user_id, operation, payload, source_origin)
  VALUES (v_credential_id, v_owner_uid, v_op,
          CASE WHEN jsonb_typeof(v_payload->'fields') = 'object'
               THEN jsonb_set(v_payload, '{fields}', public._redact_setting_fields(v_payload->'fields'))
               ELSE v_payload END,
          v_origin);

  -- ── Dispatch ──────────────────────────────────────────────────────────
  IF v_op = 'rpc_update_settings' THEN
    PERFORM _apply_signed_settings_update(v_owner_uid, v_payload->'fields');
  ELSIF v_op = 'mfa_assert' THEN
    -- Asserting user MUST be the credential owner. Settings-apply ops are
    -- admin-driven and don't enforce this, but for personal MFA this is
    -- critical. The stamp trigger has already fired via the last_used_at
    -- touch. Caller refreshes their JWT to see the new mfa_verified_at.
    IF auth.uid() IS DISTINCT FROM v_owner_uid THEN
      RAISE EXCEPTION 'Credential not owned by calling user';
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'op', v_op);
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_apply_signed_settings(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_apply_signed_settings(text, jsonb) TO anon, authenticated, service_role;


DO $rep$
BEGIN
  RAISE NOTICE 'BYO MFA self-management installed: settings.mfa_methods_allowed, rpc_clear_own_totp, last-method triggers, webauthn stamp trigger, rpc_mfa_methods_for_user, webauthn_mfa_challenges + rpc_mfa_webauthn_challenge, rpc_apply_signed_settings extended with mfa_assert op';
END $rep$;

-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-mfa-policy-and-verify-delete ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-mfa-policy-and-verify-delete.sql
--
-- Mirrors master-mfa-policy-and-verify-delete.sql for BYO. Adds:
--   1. settings.mfa_methods_required ('any' | 'all')
--   2. Updated last-method triggers that enforce the policy
--   3. rpc_clear_own_totp_with_code(p_totp_code), verify then clear
--
-- BYO already has rpc_verify_totp(p_email, p_code) for full TOTP
-- verification (used during sign-in). The new clear-with-code RPC piggybacks
-- on it: verify first, then clear. WebAuthn key removal continues to use
-- rpc_apply_signed_settings with mfa_assert (added in earlier turn), the
-- portal will now sign a payload with the SPECIFIC key to be removed, then
-- delete the row only on successful verification.
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── 1. settings.mfa_methods_required ──────────────────────────────────
ALTER TABLE public.settings
  ADD COLUMN IF NOT EXISTS mfa_methods_required text
    NOT NULL DEFAULT 'any'
    CHECK (mfa_methods_required IN ('any','all'));


-- ─── 2. Updated last-method triggers ───────────────────────────────────
CREATE OR REPLACE FUNCTION public._tr_prevent_last_mfa_removal_totp()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_webauthn_count int;
  v_required text;
BEGIN
  IF (NEW.totp_secret IS NULL OR length(NEW.totp_secret) = 0)
     AND OLD.totp_secret IS NOT NULL AND length(OLD.totp_secret) > 0
     AND NEW.auth_user_id IS NOT NULL THEN

    SELECT COALESCE(mfa_methods_required, 'any') INTO v_required
      FROM public.settings LIMIT 1;

    IF v_required = 'all' THEN
      RAISE EXCEPTION 'Your administrator requires both an authenticator app and a security key. Cannot remove the authenticator.'
        USING ERRCODE = 'P0001';
    END IF;

    SELECT count(*) INTO v_webauthn_count
      FROM public.webauthn_credentials
      WHERE auth_user_id = NEW.auth_user_id;
    IF v_webauthn_count = 0 THEN
      RAISE EXCEPTION 'Cannot remove your only MFA method. Add another method first.'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


CREATE OR REPLACE FUNCTION public._tr_prevent_last_mfa_removal_webauthn()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_other_webauthn int;
  v_has_totp boolean;
  v_required text;
BEGIN
  SELECT count(*) INTO v_other_webauthn
    FROM public.webauthn_credentials
    WHERE auth_user_id = OLD.auth_user_id
      AND id != OLD.id;

  SELECT COALESCE(mfa_methods_required, 'any') INTO v_required
    FROM public.settings LIMIT 1;

  IF v_required = 'all' AND v_other_webauthn = 0 THEN
    RAISE EXCEPTION 'Your administrator requires both an authenticator app and a security key. Cannot remove your only security key.'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_other_webauthn > 0 THEN
    RETURN OLD;
  END IF;

  SELECT (totp_secret IS NOT NULL AND length(totp_secret) > 0)
    INTO v_has_totp
    FROM public.profiles
    WHERE auth_user_id = OLD.auth_user_id AND active = true
    LIMIT 1;
  IF NOT COALESCE(v_has_totp, false) THEN
    RAISE EXCEPTION 'Cannot remove your only MFA method. Add another method first.'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;


-- ─── 3. rpc_clear_own_totp_with_code ───────────────────────────────────
-- BYO does the verify itself by calling _totp_check inline. The secret
-- never leaves Postgres. Records failed attempts and lock state same as
-- the sign-in TOTP path.
DROP FUNCTION IF EXISTS public.rpc_clear_own_totp_with_code(text);
CREATE OR REPLACE FUNCTION public.rpc_clear_own_totp_with_code(p_totp_code text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_profile_id uuid;
  v_secret text;
  v_attempts int;
  v_locked_until timestamptz;
  v_ok boolean;
  v_new_attempts int;
  v_lock_until timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_totp_code IS NULL OR length(p_totp_code) != 6 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Code required');
  END IF;

  SELECT id, totp_secret, COALESCE(totp_attempts, 0), totp_locked_until
    INTO v_profile_id, v_secret, v_attempts, v_locked_until
    FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true
    FOR UPDATE;
  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;
  IF v_secret IS NULL OR length(v_secret) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No authenticator configured');
  END IF;

  -- Lock check
  IF v_locked_until IS NOT NULL AND v_locked_until > now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Account locked', 'locked_until', v_locked_until);
  END IF;

  v_ok := public._totp_check(v_secret, p_totp_code);

  IF NOT v_ok THEN
    -- Same attempts/lock semantics as rpc_verify_totp on BYO
    v_new_attempts := v_attempts + 1;
    IF v_new_attempts >= 5 THEN
      v_lock_until := now() + interval '15 minutes';
      UPDATE public.profiles
         SET totp_attempts = v_new_attempts, totp_locked_until = v_lock_until
       WHERE id = v_profile_id;
      RETURN jsonb_build_object('success', false, 'error', 'Account locked', 'locked_until', v_lock_until);
    END IF;
    UPDATE public.profiles SET totp_attempts = v_new_attempts WHERE id = v_profile_id;
    RETURN jsonb_build_object('success', false, 'error', 'Invalid code', 'attempts_remaining', 5 - v_new_attempts);
  END IF;

  -- Verified. Clear secret atomically. Last-method trigger may reject this.
  -- Same column guard as rpc_save_totp_secret: it only lets admin/senior touch
  -- totp_secret, so this path failed with "Cannot change MFA config" for every
  -- other role. This function has already decided the caller is entitled to the
  -- change, so raise the guard's own flag and drop it straight after.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE public.profiles
     SET totp_secret = NULL,
         totp_attempts = 0,
         totp_locked_until = NULL
   WHERE id = v_profile_id;
  PERFORM set_config('pental.bypass_protect', 'false', true);

  RETURN jsonb_build_object('success', true);
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_clear_own_totp_with_code(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_clear_own_totp_with_code(text) TO authenticated;


DO $rep$
BEGIN
  RAISE NOTICE 'BYO MFA policy + verify-delete installed: settings.mfa_methods_required, updated last-method triggers, rpc_clear_own_totp_with_code';
END $rep$;

-- ━━ byo-webauthn-transports ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-webauthn-transports.sql
--
-- BYO parity for master-webauthn-transports.sql. Adds the transports column
-- to webauthn_credentials so MFA verify and key-removal flows can hint the
-- browser which authenticator method is expected, Windows Hello / Touch ID
-- (internal) vs USB key / NFC / BLE (cross-platform), instead of showing
-- the full picker every time.
-- ═══════════════════════════════════════════════════════════════════════════

ALTER TABLE public.webauthn_credentials
  ADD COLUMN IF NOT EXISTS transports text[];


-- ── Update rpc_register_webauthn to accept transports ────────────────────
DROP FUNCTION IF EXISTS public.rpc_register_webauthn(text, text, text, text);
DROP FUNCTION IF EXISTS public.rpc_register_webauthn(text, text, text, text, text[]);
CREATE OR REPLACE FUNCTION public.rpc_register_webauthn(
  p_credential_id text,
  p_public_key text,
  p_rp_id text,
  p_label text DEFAULT NULL,
  p_transports text[] DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Session required'; END IF;
  -- 1798: only a person with an active profile here enrols a key. A new key
  -- stamps the session as second-factor fresh, and a session with no profile
  -- (public sign-up, or a deactivated user) must never be made fresh.
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = v_uid AND active = true) THEN
    RAISE EXCEPTION 'Session required';
  END IF;

  IF p_credential_id IS NULL OR length(p_credential_id) < 16
     OR p_public_key IS NULL OR length(p_public_key) < 16
     OR p_rp_id IS NULL OR length(p_rp_id) < 1
  THEN
    RAISE EXCEPTION 'Invalid credential data';
  END IF;

  IF (SELECT count(*) FROM public.webauthn_credentials WHERE auth_user_id = v_uid) >= 10 THEN
    RAISE EXCEPTION 'Maximum 10 credentials per user';
  END IF;

  -- Same rule as the authenticator app: adding a passkey to an account that ALREADY
  -- has MFA enrolled requires the caller to have passed MFA in this session. First
  -- enrolment stays open. Without this, a session on its own could add a new factor
  -- and then satisfy mfa_is_fresh(), which would make MFA no barrier to anyone
  -- holding only a session.
  IF NOT public.mfa_is_fresh() AND (
       EXISTS (SELECT 1 FROM public.webauthn_credentials WHERE auth_user_id = v_uid)
       OR EXISTS (SELECT 1 FROM public.profiles
                  WHERE auth_user_id = v_uid AND totp_secret IS NOT NULL AND totp_secret != '')
     ) THEN
    RAISE EXCEPTION 'Current MFA verification required to add another factor';
  END IF;

  INSERT INTO public.webauthn_credentials
    (auth_user_id, credential_id, public_key, rp_id, label, transports)
  VALUES
    (v_uid, p_credential_id, p_public_key, p_rp_id, COALESCE(p_label, 'Security key'), p_transports)
  ON CONFLICT (credential_id) DO NOTHING;

  RETURN jsonb_build_object('success', true);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_register_webauthn(text, text, text, text, text[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_register_webauthn(text, text, text, text, text[]) TO authenticated, service_role;


DO $rep$
BEGIN
  RAISE NOTICE 'BYO WebAuthn transports column installed + rpc_register_webauthn updated';
END $rep$;

-- ━━ byo-disable-mfa-email-recovery ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-disable-mfa-email-recovery.sql
--
-- BYO parity for master-disable-mfa-email-recovery.sql, see that file's
-- header for the full rationale. Bottom line: emailing yourself a recovery
-- code defeats MFA. The model is admin-reset in the portal; a firm with no
-- admin able to sign in uses public.owner_reset_mfa from its own database
-- console (1810: Pental cannot reset a firm's MFA).
-- ═══════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.rpc_request_mfa_recovery()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
BEGIN
  RAISE EXCEPTION 'Email-based MFA recovery is disabled. Ask another administrator to reset your MFA on the Users screen. If no administrator can sign in, whoever runs your firm''s database can reset it there with public.owner_reset_mfa; Pental cannot reset it.'
    USING ERRCODE = '42501';
END;
$$;

CREATE OR REPLACE FUNCTION public.rpc_clear_own_mfa_via_recovery(p_code text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
BEGIN
  RAISE EXCEPTION 'Email-based MFA recovery is disabled. Ask another administrator to reset your MFA on the Users screen. If no administrator can sign in, whoever runs your firm''s database can reset it there with public.owner_reset_mfa; Pental cannot reset it.'
    USING ERRCODE = '42501';
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_request_mfa_recovery() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.rpc_clear_own_mfa_via_recovery(text) FROM PUBLIC, anon, authenticated;

DO $rep$
BEGIN
  RAISE NOTICE 'BYO: MFA email-recovery RPCs disabled';
END $rep$;

-- ━━ byo-webauthn-transports-backfill ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-webauthn-transports-backfill.sql
--
-- BYO parity for master-webauthn-transports-backfill.sql. See that file's
-- header for the full rationale.
-- ═══════════════════════════════════════════════════════════════════════════

UPDATE public.webauthn_credentials
   SET transports = ARRAY['internal']::text[]
 WHERE transports IS NULL;

DO $rep$
DECLARE v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM public.webauthn_credentials WHERE transports = ARRAY['internal']::text[];
  RAISE NOTICE 'BYO WebAuthn transports backfilled: % credentials now flagged as internal', v_n;
END $rep$;

-- ━━ byo-stale-session-sweep ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-stale-session-sweep.sql
--
-- Active Sessions has been showing duplicate rows after logout-then-login.
-- Reason: when a session ends without explicit logout (tab close, browser
-- crash, network drop), the user_sessions row stays with revoked_at = NULL
-- forever. Next login adds a new row; the user sees both.
--
-- Fix: at register time, sweep this user's other sessions whose
-- last_active_at is older than 24 hours and mark them revoked. The 24h
-- window is comfortably longer than the JWT lifetime (1h) and the
-- keepalive cadence, so legitimately-active sessions never get caught.
--
-- Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_session_register(text, text, text, text, timestamptz);
CREATE OR REPLACE FUNCTION public.rpc_session_register(
  p_auth_session_id text,
  p_ip text DEFAULT NULL,
  p_user_agent text DEFAULT NULL,
  p_device_label text DEFAULT NULL,
  p_expires_at timestamptz DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_profile_id uuid;
  v_existing_id uuid;
  v_was_new boolean := false;
  v_is_new_device boolean := false;
  v_ua_hash text;
  v_prior_count integer := 0;
BEGIN
  IF p_auth_session_id IS NULL OR length(p_auth_session_id) < 8 THEN
    RETURN jsonb_build_object('error', 'Invalid session id');
  END IF;

  SELECT id INTO v_profile_id FROM public.profiles
    WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_profile_id IS NULL THEN
    RETURN jsonb_build_object('error', 'No active profile');
  END IF;

  -- Stale sweep: revoke any of THIS user's sessions that haven't been
  -- touched in 24h. Excludes the row we're about to register/touch so we
  -- don't accidentally revoke the in-flight one.
  UPDATE public.user_sessions
     SET revoked_at = now(),
         revoked_reason = 'stale'
   WHERE profile_id = v_profile_id
     AND revoked_at IS NULL
     AND auth_session_id <> p_auth_session_id
     AND last_active_at < (now() - interval '24 hours');

  SELECT id INTO v_existing_id FROM public.user_sessions
    WHERE auth_session_id = p_auth_session_id LIMIT 1;

  IF v_existing_id IS NULL THEN
    SELECT COUNT(*) INTO v_prior_count FROM public.user_sessions WHERE profile_id = v_profile_id;
    v_ua_hash := encode(extensions.digest(COALESCE(p_user_agent, ''), 'sha256'), 'hex');
    IF v_prior_count > 0 AND NOT EXISTS (
      SELECT 1 FROM public.user_sessions
      WHERE profile_id = v_profile_id
        -- Deliberately NOT filtered on revoked_at. This asks "have we ever
        -- seen this address and browser for this person", which is a question
        -- about history, not about currently-live sessions. Signing out
        -- revokes the row, so with that filter the same address and browser
        -- stopped counting as known the moment someone logged out, and the
        -- next sign-in was reported as a new device. That is why the alert
        -- fired on every single login from one new address instead of once.
        AND ip IS NOT DISTINCT FROM p_ip
        AND encode(extensions.digest(COALESCE(user_agent, ''), 'sha256'), 'hex') = v_ua_hash
    ) THEN
      v_is_new_device := true;
    END IF;

    INSERT INTO public.user_sessions
      (profile_id, auth_session_id, ip, user_agent, device_label, expires_at)
      VALUES (v_profile_id, p_auth_session_id, p_ip, p_user_agent, p_device_label, p_expires_at)
      RETURNING id INTO v_existing_id;
    v_was_new := true;
  ELSE
    UPDATE public.user_sessions
       SET last_active_at = now(),
           ip = COALESCE(p_ip, ip),
           user_agent = COALESCE(p_user_agent, user_agent),
           device_label = COALESCE(p_device_label, device_label),
           expires_at = COALESCE(p_expires_at, expires_at)
     WHERE id = v_existing_id;
  END IF;

  RETURN jsonb_build_object(
    'session_id', v_existing_id,
    'is_new', v_was_new,
    'is_new_device', v_is_new_device
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_session_register(text, text, text, text, timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_session_register(text, text, text, text, timestamptz) TO authenticated;

-- ━━ byo-rpc-get-mfa-policy ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-rpc-get-mfa-policy.sql
--
-- Read-only access to settings.mfa_methods_allowed and mfa_methods_required
-- for the post-credentials, pre-MFA sign-in step. The first-time MFA setup
-- screen needs to know which methods are allowed (so it can offer TOTP /
-- WebAuthn / both as setup choices) and what's required ('any' vs 'all').
--
-- SECURITY: only returns the two columns. Caller must be `authenticated`
-- (i.e. has a valid Supabase JWT). They've already proven the email-code
-- step at this point, adding MFA hardens the same identity, not a
-- different one. Returning the policy doesn't grant any privilege; it just
-- tells the client what UI to show.
--
-- Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_get_mfa_policy();
CREATE OR REPLACE FUNCTION public.rpc_get_mfa_policy()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_allowed jsonb;
  v_required text;
BEGIN
  SELECT mfa_methods_allowed, mfa_methods_required
    INTO v_allowed, v_required
    FROM public.settings
   LIMIT 1;
  RETURN jsonb_build_object(
    'methods_allowed', COALESCE(v_allowed, '{"totp":true,"webauthn":true}'::jsonb),
    'methods_required', COALESCE(v_required, 'any')
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_get_mfa_policy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_get_mfa_policy() TO authenticated;

-- ━━ byo-rpc-admin-reset-mfa-webauthn ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-rpc-admin-reset-mfa-webauthn.sql
--
-- The original rpc_admin_reset_mfa cleared totp_secret only. WebAuthn
-- credentials registered against webauthn_credentials_master were left
-- intact, meaning a "reset MFA" wasn't really a full reset, the user
-- could still sign in with their security key.
--
-- Updated version also deletes all WebAuthn credentials for the target
-- user, fully clearing every authentication factor. After this RPC, the
-- user must re-enrol everything from scratch on next sign-in.
--
-- Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_admin_reset_mfa(uuid);
CREATE OR REPLACE FUNCTION public.rpc_admin_reset_mfa(p_target_profile_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_role text;
  v_target_auth_uid uuid;
BEGIN
  v_role := public.current_user_role();
  IF v_role NOT IN ('admin','senior') THEN RAISE EXCEPTION 'Not authorized'; END IF;

  -- BYO single-tenant: profiles has no tenant_id column, so no cross-tenant
  -- check. Role gate above is the authorisation boundary.
  SELECT auth_user_id
    INTO v_target_auth_uid
    FROM public.profiles WHERE id = p_target_profile_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  PERFORM set_config('pental.bypass_mfa_protection', 'true', true);

  -- Wipe TOTP
  UPDATE public.profiles
     SET totp_secret = NULL,
         totp_attempts = 0,
         totp_locked_until = NULL
   WHERE id = p_target_profile_id;

  -- Wipe WebAuthn credentials (BYO table).
  IF v_target_auth_uid IS NOT NULL THEN
    DELETE FROM public.webauthn_credentials WHERE auth_user_id = v_target_auth_uid;
  END IF;

  PERFORM set_config('pental.bypass_protect', 'false', true);
  PERFORM set_config('pental.bypass_mfa_protection', 'false', true);

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_admin_reset_mfa(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_admin_reset_mfa(uuid) TO authenticated;

DO $$ BEGIN RAISE NOTICE 'rpc_admin_reset_mfa updated to also wipe WebAuthn credentials'; END $$;

-- ━━ byo-rpc-admin-reset-mfa-trigger-fix ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-rpc-admin-reset-mfa-trigger-fix.sql
--
-- BYO parity for master-rpc-admin-reset-mfa-trigger-fix.sql. See that
-- file's header for the rationale. BYO uses webauthn_credentials (no
-- _master suffix).
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public._tr_prevent_last_mfa_removal_totp() CASCADE;
CREATE OR REPLACE FUNCTION public._tr_prevent_last_mfa_removal_totp()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE v_webauthn_count int; v_bypass text;
BEGIN
  IF current_setting('pental.bypass_mfa_protection', true) = 'true'
     OR current_setting('pental.bypass_protect', true) = 'true' THEN
    RETURN NEW;
  END IF;

  IF (NEW.totp_secret IS NULL OR length(NEW.totp_secret) = 0)
     AND OLD.totp_secret IS NOT NULL AND length(OLD.totp_secret) > 0
     AND NEW.auth_user_id IS NOT NULL THEN
    SELECT count(*) INTO v_webauthn_count
      FROM public.webauthn_credentials
      WHERE auth_user_id = NEW.auth_user_id;
    IF v_webauthn_count = 0 THEN
      RAISE EXCEPTION 'Cannot remove your only MFA method. Add another method first.'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_prevent_last_mfa_removal_totp ON public.profiles;
CREATE TRIGGER tr_prevent_last_mfa_removal_totp
BEFORE UPDATE OF totp_secret ON public.profiles
FOR EACH ROW EXECUTE FUNCTION public._tr_prevent_last_mfa_removal_totp();


DROP FUNCTION IF EXISTS public._tr_prevent_last_mfa_removal_webauthn() CASCADE;
CREATE OR REPLACE FUNCTION public._tr_prevent_last_mfa_removal_webauthn()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_other_webauthn int;
  v_has_totp boolean;
  v_bypass text;
BEGIN
  IF current_setting('pental.bypass_mfa_protection', true) = 'true'
     OR current_setting('pental.bypass_protect', true) = 'true' THEN
    RETURN OLD;
  END IF;

  SELECT count(*) INTO v_other_webauthn
    FROM public.webauthn_credentials
    WHERE auth_user_id = OLD.auth_user_id
      AND id != OLD.id;
  IF v_other_webauthn > 0 THEN
    RETURN OLD;
  END IF;
  SELECT (totp_secret IS NOT NULL AND length(totp_secret) > 0)
    INTO v_has_totp
    FROM public.profiles
    WHERE auth_user_id = OLD.auth_user_id AND active = true
    LIMIT 1;
  IF NOT COALESCE(v_has_totp, false) THEN
    RAISE EXCEPTION 'Cannot remove your only MFA method. Add another method first.'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS tr_prevent_last_mfa_removal_webauthn ON public.webauthn_credentials;
CREATE TRIGGER tr_prevent_last_mfa_removal_webauthn
BEFORE DELETE ON public.webauthn_credentials
FOR EACH ROW EXECUTE FUNCTION public._tr_prevent_last_mfa_removal_webauthn();


DROP FUNCTION IF EXISTS public.rpc_admin_reset_mfa(uuid);
CREATE OR REPLACE FUNCTION public.rpc_admin_reset_mfa(p_target_profile_id uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $$
DECLARE
  v_role text;
  v_target_auth_uid uuid;
  v_why text;
BEGIN
  -- BYO single-tenant: this database belongs to exactly one tenant, so there
  -- is no cross-tenant check to make (profiles has no tenant_id column). The
  -- caller only reaches this DB with a JWT this DB's GoTrue issued, and the
  -- role gate below restricts the action to admins/seniors of this tenant.
  v_role := public.current_user_role();
  IF v_role NOT IN ('admin','senior') THEN RAISE EXCEPTION 'Not authorized'; END IF;

  -- The admin must have presented a factor this session, so that a session
  -- which reached the portal on the password step alone cannot reset a factor
  -- (its own included) and enrol a replacement to bypass MFA.
  IF NOT public.mfa_is_fresh() THEN
    RAISE EXCEPTION 'Re-verify MFA before resetting a user''s MFA' USING ERRCODE = '42501';
  END IF;

  SELECT auth_user_id INTO v_target_auth_uid
    FROM public.profiles WHERE id = p_target_profile_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'User not found'; END IF;

  -- 1816: AND ONLY SOMEBODY YOU MAY MANAGE: below you, or another
  -- administrator when you are the account owner. Never yourself (your own
  -- factors are yours to change, from your own account) and never the owner
  -- (who has recovery codes, and the database console's owner_reset_mfa).
  -- This asked only whether the caller was an admin or senior, so any of them
  -- could wipe a colleague's MFA, the owner's included.
  v_why := public._pental_manage_refusal(p_target_profile_id);
  IF v_why IS NOT NULL THEN
    RAISE EXCEPTION '%', CASE v_why
        WHEN 'self' THEN 'Your own MFA is changed from your own account, not reset here'
        WHEN 'owner' THEN 'Nobody else can reset the account owner''s MFA'
        WHEN 'owner_only' THEN 'Only the account owner can reset another administrator''s MFA'
        WHEN 'rank' THEN 'You cannot reset MFA for someone with an equal or higher role'
        WHEN 'not_found' THEN 'User not found'
        ELSE 'Not authorized' END
      USING ERRCODE = '42501';
  END IF;

  -- Bypass the last-MFA-removal protection triggers for this admin reset.
  -- The triggers read pental.bypass_protect (transaction-local), so set that
  -- exact name. Setting bypass_mfa_protection too keeps any trigger that
  -- checks either name satisfied. Both auto-clear on function return.
  PERFORM set_config('pental.bypass_protect', 'true', true);
  PERFORM set_config('pental.bypass_mfa_protection', 'true', true);

  UPDATE public.profiles
     SET totp_secret = NULL,
         totp_attempts = 0,
         totp_locked_until = NULL
   WHERE id = p_target_profile_id;

  IF v_target_auth_uid IS NOT NULL THEN
    DELETE FROM public.webauthn_credentials WHERE auth_user_id = v_target_auth_uid;
    -- 1810: and the person's current freshness, so a session of theirs that
    -- is still open cannot enrol a replacement from it.
    PERFORM public._clear_mfa_verified(v_target_auth_uid);
  END IF;

  PERFORM set_config('pental.bypass_protect', 'false', true);
  PERFORM set_config('pental.bypass_mfa_protection', 'false', true);

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_admin_reset_mfa(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_admin_reset_mfa(uuid) TO authenticated;

DO $$ BEGIN RAISE NOTICE 'BYO admin reset MFA: bypass-flag added, both triggers updated'; END $$;

-- ━━ byo-realtime-publication ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-realtime-publication.sql
--
-- Adds tables to the supabase_realtime publication so the portal's
-- postgres_changes subscriptions actually fire. Without this, .channel()
-- subscribes successfully but no events ever arrive.
--
-- This was previously configured via the Supabase dashboard (Database →
-- Replication → supabase_realtime) and never captured in SQL. After the DB
-- recreation, that config was lost.
--
-- Each table also needs REPLICA IDENTITY FULL so DELETE/UPDATE payloads
-- carry the OLD row data (otherwise client-side tenant filtering can't
-- inspect tenant_id on deletes).
--
-- Idempotent: ALTER PUBLICATION ADD TABLE will error if the table is
-- already a member, so we check pg_publication_tables first per table.
-- ═══════════════════════════════════════════════════════════════════════════

-- Ensure the publication exists (Supabase creates this by default but
-- guard in case a fresh project somehow doesn't have it)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    CREATE PUBLICATION supabase_realtime;
  END IF;
END $$;

-- Add each table to the publication, idempotently.
DO $$
DECLARE
  v_table text;
  v_tables text[] := ARRAY[
    'clients',
    'assessments',
    'findings',
    'proposals',
    'invoices',
    'kb_entries',
    'feedback',
    'settings',
    'assessment_comments',
    'qa_comments',
    'assessment_files',
    'contractor_payments',
    'meetings',
    'meeting_attendees',
    'profiles',
    'timeline_events'
  ];
BEGIN
  FOREACH v_table IN ARRAY v_tables
  LOOP
    -- Skip if table doesn't exist (defensive)
    IF NOT EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE c.relname = v_table AND n.nspname = 'public'
    ) THEN
      RAISE NOTICE 'Skipping % (table does not exist)', v_table;
      CONTINUE;
    END IF;

    -- Add to publication if not already there
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = v_table
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_table);
      RAISE NOTICE 'Added % to supabase_realtime', v_table;
    END IF;

    -- REPLICA IDENTITY FULL so DELETE/UPDATE payloads carry the OLD row
    -- data (needed for tenant filtering on delete events).
    EXECUTE format('ALTER TABLE public.%I REPLICA IDENTITY FULL', v_table);
  END LOOP;
END $$;

DO $$ BEGIN RAISE NOTICE 'Realtime publication updated. Restart the realtime service or wait ~30s for changes to propagate.'; END $$;

-- ━━ byo-add-reply-to-setting ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-add-reply-to-setting.sql
--
-- Adds settings.notify_reply_to_email, the address used as Reply-To on
-- outgoing notification emails. Matters most when the tenant uses Pental's
-- shared SMTP (the From: address is Pental's, so without Reply-To replies
-- come back to Pental). Fallback chain: this setting > company_email >
-- first active admin email.
--
-- Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

ALTER TABLE public.settings
  ADD COLUMN IF NOT EXISTS notify_reply_to_email text;

-- Allow the column to be read and written via the standard authenticated
-- grants on settings. The existing column-level GRANT block in master-setup
-- doesn't include this new column, so add SELECT/UPDATE for it.
DO $$
BEGIN
  EXECUTE 'GRANT SELECT (notify_reply_to_email) ON public.settings TO authenticated';
  EXECUTE 'GRANT UPDATE (notify_reply_to_email) ON public.settings TO authenticated';
EXCEPTION WHEN OTHERS THEN
  -- If column-level grants aren't in use on this DB, the table-level grant
  -- already covers it. Either way the column is now usable.
  NULL;
END $$;

DO $$ BEGIN RAISE NOTICE 'settings.notify_reply_to_email added'; END $$;

-- ━━ byo-add-webauthn-export ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-add-webauthn-export.sql
--
-- Adds rpc_export_webauthn_credentials so master-side migration code can
-- pull WebAuthn credentials off BYO during downgrade. Mirrors the existing
-- per-table export RPCs (rpc_export_profiles, rpc_export_settings, etc.).
--
-- Pair with the master-side change that adds 'webauthn_credentials' to the
-- exportTables array in src/lib/byo-migration.js.
--
-- Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_export_webauthn_credentials(text);
DROP FUNCTION IF EXISTS public.rpc_export_webauthn_credentials(text, jsonb);

CREATE OR REPLACE FUNCTION public.rpc_export_webauthn_credentials(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  PERFORM public._pental_require_auth(p_auth, p_secret, 'rpc_export_webauthn_credentials');
  -- Defensive: if the table doesn't exist on this BYO (older deploy), return
  -- an empty array so the migration script can keep going without crashing.
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'webauthn_credentials'
  ) THEN
    RETURN '[]'::jsonb;
  END IF;
  RETURN COALESCE(
    (SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM public.webauthn_credentials) t),
    '[]'::jsonb
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_export_webauthn_credentials(text, jsonb) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-grant-late-added-settings-cols ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- byo-grant-late-added-settings-cols.sql
--
-- Three columns were added to public.settings via incremental migrations
-- (mfa_methods_allowed, mfa_methods_required, notify_reply_to_email) but
-- the column-level GRANT block above wasn't updated to include them.
-- Without these grants, signed-in users get a 403 on the portal's main
-- settings SELECT (which lists all of these in _settingsCols_staff),
-- breaking branding/theme/notifications post-login. Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  -- Each column may not exist yet on an older install; guard with IF EXISTS.
  -- These grants are also no-ops if already present.
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_schema='public' AND table_name='settings'
             AND column_name='mfa_methods_allowed') THEN
    EXECUTE 'GRANT SELECT (mfa_methods_allowed) ON public.settings TO authenticated';
    EXECUTE 'GRANT UPDATE (mfa_methods_allowed) ON public.settings TO authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_schema='public' AND table_name='settings'
             AND column_name='mfa_methods_required') THEN
    EXECUTE 'GRANT SELECT (mfa_methods_required) ON public.settings TO authenticated';
    EXECUTE 'GRANT UPDATE (mfa_methods_required) ON public.settings TO authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_schema='public' AND table_name='settings'
             AND column_name='notify_reply_to_email') THEN
    EXECUTE 'GRANT SELECT (notify_reply_to_email) ON public.settings TO authenticated';
    EXECUTE 'GRANT UPDATE (notify_reply_to_email) ON public.settings TO authenticated';
  END IF;
END $$;

DO $$ BEGIN RAISE NOTICE 'BYO late-added settings columns granted to authenticated'; END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-realtime-add-user-sessions ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- Same as master-realtime-add-user-sessions but for BYO. Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    CREATE PUBLICATION supabase_realtime;
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = 'user_sessions' AND n.nspname = 'public'
  ) AND NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'user_sessions'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.user_sessions;
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = 'user_sessions' AND n.nspname = 'public'
  ) THEN
    ALTER TABLE public.user_sessions REPLICA IDENTITY FULL;
  END IF;
END $$;

DO $$ BEGIN RAISE NOTICE 'BYO user_sessions added to supabase_realtime'; END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-rpc-verify-pental-keys-planted ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- rpc_verify_pental_keys_planted, Pental tenant-setup readback after
-- rpc_install_pental_keys to confirm the pubkeys actually persisted in
-- Vault. Without this readback, install can return success while the
-- vault.update_secret silently no-ops (e.g. if a slot wasn't pre-created),
-- leaving the BYO with empty pubkey slots and every later signed RPC
-- failing with "Invalid secret or session required".
--
-- Auth: install_token (the same single-use token used to gate
-- rpc_install_pental_keys). Returning the byte length of pubkey material
-- is not sensitive, knowing whether keys are 32 bytes vs 0 bytes does
-- not help an attacker (they cannot read the keys, and the keys are
-- public anyway). Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_verify_pental_keys_planted(text);
CREATE OR REPLACE FUNCTION public.rpc_verify_pental_keys_planted(
  p_install_token text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, vault, pg_catalog, pg_temp
AS $$
DECLARE
  v_pubkey_a bytea;
  v_pubkey_b bytea;
  v_a_len int;
  v_b_len int;
BEGIN
  -- Re-validate install token. Keep this function admin-gated even though
  -- the keys themselves are public, we don't want anon callers introspecting
  -- the vault state for unrelated reasons.
  PERFORM public._verify_install_token(p_install_token);

  v_pubkey_a := public._pental_pubkey_a();
  v_pubkey_b := public._pental_pubkey_b();
  v_a_len := COALESCE(octet_length(v_pubkey_a), 0);
  v_b_len := COALESCE(octet_length(v_pubkey_b), 0);

  RETURN jsonb_build_object(
    'pubkey_a_bytes', v_a_len,
    'pubkey_b_bytes', v_b_len,
    'both_planted', (v_a_len = 32 AND v_b_len = 32)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_verify_pental_keys_planted(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_verify_pental_keys_planted(text) TO anon, authenticated, service_role;

DO $$ BEGIN RAISE NOTICE 'rpc_verify_pental_keys_planted installed'; END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-rpc-reissue-install-token ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- rpc_reissue_install_token, non-destructive recovery RPC. Issues a
-- KEY-REPAIR token without touching any application data. Used by the
-- website's `repair_byo_keys` action (/api/tenant-setup): when a BYO ends up
-- with empty pental_pubkey_a/_b because the original install path failed
-- silently (e.g. PENTAL_SIGN_PUBKEY_A/B env wasn't set on Vercel at install
-- time), the next signed RPC fails with "Invalid secret or session required".
-- rpc_bulk_clean would wipe all data to get there. This RPC fills that gap.
--
-- 1798: IT WAS ANYBODY'S, AND IT OPENED EVERYTHING. It answered the publishable
-- key, which is in every portal page, and wrote its token into the SAME slot
-- the provisioning window reads. With that token anybody could replace the two
-- keys every signed call is checked against (and then sign anything this
-- database accepts: settings secrets, SMTP, scanner and tracker credentials,
-- mail), create a sign-in with rpc_bulk_auth and an admin profile with
-- rpc_bulk_import, overwrite _internal_secrets (the provisioning secret and
-- both verifier addresses) with rpc_bulk_import_keys, and repoint the
-- signature verifier. The old comment here called the worst case a denial of
-- service. It was a takeover.
--
-- Now:
--   1. Pental's provisioning secret is required, and nothing weaker.
--   2. It answers only a database with a key missing. With both keys planted
--      there is nothing to repair and it says so; replacing a planted key is
--      refused by rpc_install_pental_keys whatever token is shown.
--   3. The token goes into its own slot (key_repair_token_hash), which only
--      rpc_install_pental_keys reads. The bulk operations, the verifier
--      setters and rpc_bootstrap_admin read install_token_hash, which only a
--      wipe writes, so a repair token opens none of them.
--   4. Ten minutes, single use, one a minute. A refusal is recorded in
--      _pental_rpc_audit_log (the secret check writes it), and answered as a
--      result rather than an exception so that record is not rolled back.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_reissue_install_token();
DROP FUNCTION IF EXISTS public.rpc_reissue_install_token(text);
CREATE OR REPLACE FUNCTION public.rpc_reissue_install_token(p_secret text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, vault, extensions, pg_catalog, pg_temp
AS $$
DECLARE
  v_token text;
  v_slot uuid;
  v_cur text;
  v_now bigint;
  v_a bytea;
  v_b bytea;
BEGIN
  -- Advisory lock to prevent concurrent rotations from racing
  PERFORM pg_advisory_xact_lock(hashtext('pental_reissue_install_token'));

  IF NOT public._validate_provision_secret(COALESCE(p_secret, ''), 'rpc_reissue_install_token') THEN
    RETURN jsonb_build_object('error', 'Not authorised');
  END IF;

  BEGIN v_a := public._pental_pubkey_a(); EXCEPTION WHEN OTHERS THEN v_a := NULL; END;
  BEGIN v_b := public._pental_pubkey_b(); EXCEPTION WHEN OTHERS THEN v_b := NULL; END;
  -- Both planted: nothing to repair here, and they are never replaced by a
  -- token. The keys are public, so they are handed back for the caller to
  -- compare with its own: keys that are planted and WRONG (Pental rotated, or
  -- somebody replaced them through the old hole) are a different answer from
  -- keys that are right, and the firm clears them itself (see the website's
  -- repair) rather than anybody being able to overwrite them.
  IF COALESCE(octet_length(v_a), 0) = 32 AND COALESCE(octet_length(v_b), 0) = 32 THEN
    RETURN jsonb_build_object('error',
      'Pental''s signing keys are already installed on this database, so there is nothing to repair.',
      'keys_planted', true,
      'planted_a', encode(v_a, 'base64'),
      'planted_b', encode(v_b, 'base64'));
  END IF;

  v_now := extract(epoch FROM now())::bigint;
  SELECT id, decrypted_secret INTO v_slot, v_cur FROM vault.decrypted_secrets
   WHERE name = 'key_repair_token_hash' LIMIT 1;
  -- Rate limit: max one token per 60s
  IF v_cur ~ '\|[0-9]{1,12}$' AND v_now - split_part(v_cur, '|', 2)::bigint < 60 THEN
    RETURN jsonb_build_object('error', 'A repair token was issued in the last minute. Wait a moment and try again.');
  END IF;

  -- Generate 32-byte random token, hex-encoded (64 chars)
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  IF v_slot IS NULL THEN
    PERFORM vault.create_secret(
      encode(extensions.digest(v_token, 'sha256'), 'hex') || '|' || v_now,
      'key_repair_token_hash',
      'SHA-256 of a key-repair token and when it was issued. Fills empty Pental key slots only; ten minutes, single use.');
  ELSE
    PERFORM vault.update_secret(v_slot, encode(extensions.digest(v_token, 'sha256'), 'hex') || '|' || v_now);
  END IF;

  RETURN jsonb_build_object('repair_token', v_token, 'expires_in', 600);
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_reissue_install_token(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_reissue_install_token(text) TO anon, authenticated, service_role;

-- 1798: AND A WINDOW ALREADY OPEN IS SHUT. Every token the old version handed
-- out sits in install_token_hash, where the bulk operations read it, and the
-- website's own repair never spent the one it was given. A database that has an
-- administrator is past provisioning (a wipe removes every profile before it
-- opens a window, and the first administrator is created after the window is
-- closed), so that slot and the legacy INSTALL_TOKEN are cleared on every run.
-- A new database and one mid-way through being provisioned (no administrator
-- yet) are untouched.
--
-- NOT KEYED ON THE SCHEMA VERSION, deliberately. Until 1806 a signed-in
-- session could write `_pental_schema_version` (the grant on every table
-- reached it), so somebody holding an old token could set it to the current
-- number, or delete it, and skip a version-keyed close. The writes are now
-- revoked (end of the move block), and this stays unkeyed all the same.
DO $close_install_window$
DECLARE v_slot uuid; v_n integer := 0;
BEGIN
  IF NOT public._has_admin_profile() THEN RETURN; END IF;
  SELECT id INTO v_slot FROM vault.decrypted_secrets
   WHERE name = 'install_token_hash' AND COALESCE(decrypted_secret, '') <> '' LIMIT 1;
  IF v_slot IS NOT NULL THEN PERFORM vault.update_secret(v_slot, ''); v_n := v_n + 1; END IF;
  DELETE FROM public._internal_secrets WHERE key = 'INSTALL_TOKEN';
  IF FOUND THEN v_n := v_n + 1; END IF;
  IF v_n > 0 THEN
    RAISE NOTICE 'install window: an open provisioning token was cleared on this populated database';
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'install window could not be closed: %', SQLERRM;
END $close_install_window$;

DO $$ BEGIN RAISE NOTICE 'rpc_reissue_install_token installed'; END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-debug-verify-auth ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- Debug helper to surface exactly why _verify_pental_auth is rejecting a
-- signed envelope. The audit log entries from a failing rpc_update_settings
-- get rolled back when the outer function raises, so we never see them.
-- This RPC runs the verification in its OWN call (no rollback) and returns
-- the audit log row directly. Install_token gated.
-- ═══════════════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.rpc_debug_verify_auth(jsonb, text, text);
CREATE OR REPLACE FUNCTION public.rpc_debug_verify_auth(
  p_auth jsonb,
  p_expected_op text,
  p_install_token text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, vault, pg_catalog, pg_temp
AS $$
DECLARE
  v_result boolean;
  v_log_row record;
  v_pubkey_a bytea;
  v_pubkey_b bytea;
BEGIN
  PERFORM public._verify_install_token(p_install_token);

  -- Snapshot vault state
  v_pubkey_a := public._pental_pubkey_a();
  v_pubkey_b := public._pental_pubkey_b();

  -- Run verification (this writes to audit log). 1832: inside the
  -- provisioning window (the install token was checked just above), a
  -- verified envelope also binds this database to the firm it was made for:
  -- the setup's own check, the first signed call a new database sees.
  v_result := public._pental_verify_binding(p_auth, p_expected_op, NULL, true);

  -- Read back the most recent audit row
  SELECT * INTO v_log_row FROM public._pental_rpc_audit_log
    WHERE op = p_expected_op
    ORDER BY id DESC LIMIT 1;

  RETURN jsonb_build_object(
    'verify_returned', v_result,
    'pubkey_a_bytes', COALESCE(octet_length(v_pubkey_a), 0),
    'pubkey_b_bytes', COALESCE(octet_length(v_pubkey_b), 0),
    -- 1825: checked in this database; there is no verifier URL to report.
    'verifier', 'in_database',
    'audit_row', CASE WHEN v_log_row IS NULL THEN NULL ELSE jsonb_build_object(
      'op', v_log_row.op,
      'auth_mode', v_log_row.auth_mode,
      'result', v_log_row.result,
      'error_short', v_log_row.error_short,
      'at', v_log_row.at
    ) END,
    'auth_received', jsonb_build_object(
      'op', p_auth->>'op',
      'tenant_id', p_auth->>'tenant_id',
      'nonce_len', length(COALESCE(p_auth->>'nonce', '')),
      'exp', p_auth->>'exp',
      'sig_a_len', length(COALESCE(p_auth->>'sig_a', '')),
      'sig_b_len', length(COALESCE(p_auth->>'sig_b', ''))
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_debug_verify_auth(jsonb, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_debug_verify_auth(jsonb, text, text) TO anon, authenticated, service_role;

DO $$ BEGIN RAISE NOTICE 'rpc_debug_verify_auth installed'; END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-management-token-removal ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- The Supabase Management API PAT is no longer used by Pental. Login emails
-- are sent by Pental directly via /api/auth-code, reading SMTP from BYO
-- settings via cosigner-signed RPC, so the PAT-related RPCs and the
-- _internal_secrets row that stored the PAT are dead weight. Drop them.
DROP FUNCTION IF EXISTS public.rpc_set_management_token(text, text);
DROP FUNCTION IF EXISTS public.rpc_set_management_token(text);
DROP FUNCTION IF EXISTS public.rpc_get_management_token(text, jsonb);
DROP FUNCTION IF EXISTS public.rpc_get_management_token(text);
DROP FUNCTION IF EXISTS public.rpc_get_management_token();
DROP FUNCTION IF EXISTS public.rpc_management_token_status();
DELETE FROM public._internal_secrets WHERE key = 'SUPABASE_MANAGEMENT_TOKEN';
DO $$ BEGIN RAISE NOTICE 'Legacy PAT RPCs and stored secret removed'; END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ byo-custom-access-token-hook ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- Custom Access Token Hook, bakes auth.users.raw_app_meta_data.mfa_verified_at
-- into every JWT issued or refreshed by GoTrue.
--
-- Why this matters:
--   _stamp_mfa_verified() updates auth.users.raw_app_meta_data when MFA is
--   verified. But GoTrue's refreshSession() doesn't always re-read that
--   column when rotating the access_token, so the JWT can carry a stale
--   (or missing) mfa_verified_at claim even though the database has the
--   fresh value. This breaks RLS policies that gate on mfa_is_fresh()
--   (which reads the JWT claim directly) and forces the portal to
--   reprompt for MFA on every refresh as a safety measure.
--
--   Custom access token hooks ARE called on every token issuance AND
--   every refresh. Reading raw_app_meta_data inside the hook ensures the
--   JWT app_metadata.mfa_verified_at always reflects the latest stamp.
--
-- BYO is single-tenant so we don't need master's tenant_id/profile_id
-- injection, just the MFA stamp.
--
-- IMPORTANT: After running this script, the customer MUST register the
-- hook in their Supabase dashboard:
--   Authentication → Hooks → Custom Access Token → public.custom_access_token_hook
-- Without the dashboard registration, the hook is defined but never
-- invoked. We can't register it from SQL, Supabase exposes that via
-- the Management API only.
-- ═══════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
  RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
AS $fn$
#variable_conflict use_variable
DECLARE
  _claims jsonb;
  _mfa_stamp text;
BEGIN
  _claims := event -> 'claims';

  -- Pull mfa_verified_at directly from auth.users.raw_app_meta_data and
  -- copy it into the JWT app_metadata so mfa_is_fresh() (used by RLS on
  -- sensitive tables) and the portal's freshness check both see the
  -- current value without needing a full re-login.
  SELECT raw_app_meta_data ->> 'mfa_verified_at' INTO _mfa_stamp
    FROM auth.users WHERE id = (event ->> 'user_id')::uuid;

  IF _mfa_stamp IS NOT NULL THEN
    _claims := jsonb_set(_claims, '{app_metadata}',
      COALESCE(_claims -> 'app_metadata', '{}'::jsonb) ||
      jsonb_build_object('mfa_verified_at', _mfa_stamp));
  END IF;

  RETURN jsonb_set(event, '{claims}', _claims);
END;
$fn$;

-- GoTrue assumes the supabase_auth_admin role when running access-token
-- hooks. Without these grants the hook is silently skipped and the JWT
-- carries no mfa_verified_at, exactly the bug we're trying to fix.
-- USAGE on schema public is needed to even resolve the function name.
GRANT USAGE ON SCHEMA public TO supabase_auth_admin;
GRANT EXECUTE ON FUNCTION public.custom_access_token_hook(jsonb) TO supabase_auth_admin;

-- Lock the hook down from anon/authenticated, only supabase_auth_admin
-- (the GoTrue runner) should call it. SECURITY DEFINER means it runs as
-- the function owner regardless, so this is belt-and-braces.
REVOKE EXECUTE ON FUNCTION public.custom_access_token_hook(jsonb) FROM PUBLIC, anon, authenticated;

DO $$ BEGIN
  RAISE NOTICE 'custom_access_token_hook installed. ACTION REQUIRED: register the hook in Supabase Dashboard → Authentication → Hooks → Custom Access Token → public.custom_access_token_hook';
END $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ encryption-at-rest for sensitive settings columns ━━
-- ═══════════════════════════════════════════════════════════════════════════
-- See migration_v9_encrypt_settings_secrets.sql for the full rationale.
-- This block reproduces the schema + helper functions on fresh BYO installs.
-- The companion encryption helper functions live next to the existing
-- _credentials_key / _encryption_keys infrastructure already established
-- earlier in this file.
--
-- Columns in this block: smtp_pass_enc, stripe_secret_key_enc,
-- stripe_webhook_secret_enc, ai_api_key_enc, teams_client_secret_enc,
-- zoom_client_secret_enc, slack_bot_token_enc.
--
-- For fresh installs there's nothing to backfill (all _enc cols start NULL,
-- all plaintext cols start NULL too). The SECURITY DEFINER read/write RPCs
-- handle encrypt/decrypt transparently from this point on.

ALTER TABLE public.settings
  ADD COLUMN IF NOT EXISTS smtp_oauth_provider text,
  ADD COLUMN IF NOT EXISTS smtp_oauth_user text,
  -- 1402 (2025090502): WHEN SOMEBODY CONFIRMED A MESSAGE FROM THIS MAILBOX
  -- ACTUALLY ARRIVED. A 250 from Exchange is acceptance, not delivery, and
  -- sign-in codes must not move to a mailbox that accepts and swallows.
  ADD COLUMN IF NOT EXISTS smtp_oauth_verified_at timestamptz,
  ADD COLUMN IF NOT EXISTS smtp_oauth_refresh text,
  ADD COLUMN IF NOT EXISTS smtp_oauth_refresh_enc bytea,
  ADD COLUMN IF NOT EXISTS smtp_pass_enc bytea,
  ADD COLUMN IF NOT EXISTS stripe_secret_key_enc bytea,
  ADD COLUMN IF NOT EXISTS stripe_webhook_secret_enc bytea,
  ADD COLUMN IF NOT EXISTS ai_api_key_enc bytea,
  ADD COLUMN IF NOT EXISTS teams_client_secret_enc bytea,
  ADD COLUMN IF NOT EXISTS zoom_client_secret_enc bytea,
  ADD COLUMN IF NOT EXISTS slack_bot_token_enc bytea,
  ADD COLUMN IF NOT EXISTS google_api_key_enc bytea,
  -- 1522: white-label SSO credentials, plus their encrypted companions.
  ADD COLUMN IF NOT EXISTS sso_google_client_id text,
  ADD COLUMN IF NOT EXISTS sso_google_client_secret text,
  ADD COLUMN IF NOT EXISTS sso_google_client_secret_enc bytea,
  ADD COLUMN IF NOT EXISTS sso_ms_client_id text,
  ADD COLUMN IF NOT EXISTS sso_ms_client_secret text,
  ADD COLUMN IF NOT EXISTS sso_ms_client_secret_enc bytea,
  ADD COLUMN IF NOT EXISTS sso_ms_tenant text DEFAULT 'common';

CREATE OR REPLACE FUNCTION public._settings_encrypt(p_plain text)
  RETURNS bytea LANGUAGE plpgsql VOLATILE SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
AS $fn$
DECLARE v_key text;
BEGIN
  IF p_plain IS NULL THEN RETURN NULL; END IF;
  IF p_plain = '' THEN RETURN NULL; END IF;
  SELECT key_value INTO v_key FROM public._encryption_keys
    WHERE key_name = 'credentials' LIMIT 1;
  -- Self-heal: a database provisioned from an older byo-setup.sql (or one whose
  -- key was wiped) may not have the 'credentials' key yet. Rather than raise and
  -- block the whole settings write, create the key now. This matches the
  -- pentest-credential path, which uses the same key_name.
  -- 1844: AND ONE THAT IS THERE BUT EMPTY. Kept as it was (DO NOTHING), every
  -- secret written stayed in plain text for good, and re-running the setup
  -- could not encrypt it ("Stored without encryption" that would not go). An
  -- empty key never encrypted anything (this refuses one, and so does
  -- _settings_decrypt), so giving it a value loses nothing.
  IF v_key IS NULL OR v_key = '' THEN
    INSERT INTO public._encryption_keys (key_name, key_value)
      VALUES ('credentials', encode(extensions.gen_random_bytes(32), 'hex'))
      ON CONFLICT (key_name) DO UPDATE SET key_value = EXCLUDED.key_value
        WHERE public._encryption_keys.key_value IS NULL OR public._encryption_keys.key_value = '';
    SELECT key_value INTO v_key FROM public._encryption_keys
      WHERE key_name = 'credentials' LIMIT 1;
  END IF;
  IF v_key IS NULL OR v_key = '' THEN
    -- Still nothing (should be impossible): leave the plaintext write to proceed
    -- rather than blocking the save. The value stays in the plaintext column and
    -- gets encrypted on the next write once the key exists.
    RETURN NULL;
  END IF;
  RETURN extensions.pgp_sym_encrypt(p_plain, v_key);
END;
$fn$;
REVOKE ALL ON FUNCTION public._settings_encrypt(text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._settings_decrypt(p_cipher bytea)
  RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
AS $fn$
DECLARE v_key text;
BEGIN
  IF p_cipher IS NULL THEN RETURN NULL; END IF;
  SELECT key_value INTO v_key FROM public._encryption_keys
    WHERE key_name = 'credentials' LIMIT 1;
  IF v_key IS NULL OR v_key = '' THEN RETURN NULL; END IF;
  BEGIN
    RETURN extensions.pgp_sym_decrypt(p_cipher, v_key);
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
END;
$fn$;
REVOKE ALL ON FUNCTION public._settings_decrypt(bytea) FROM PUBLIC, anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════
-- CHECKLISTS & RUNBOOKS (optional feature, off by default)
-- ═══════════════════════════════════════════════════════════════════════
-- Tenant-defined checklists and runbooks attachable to assessment phases.
-- Toggled per-tenant via settings.enable_checklists_runbooks; when off
-- the UI hides every related surface. Idempotent.

CREATE TABLE IF NOT EXISTS public.checklists_runbooks (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  kind           TEXT NOT NULL CHECK (kind IN ('checklist', 'runbook')),
  name           TEXT NOT NULL,
  description    TEXT,
  phase_hint     TEXT,
  source         TEXT NOT NULL DEFAULT 'custom',
  source_url     TEXT,
  client_visible BOOLEAN NOT NULL DEFAULT false,
  audit_ticks    BOOLEAN NOT NULL DEFAULT false,
  items          JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by     UUID REFERENCES public.profiles(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS checklists_runbooks_kind_idx
  ON public.checklists_runbooks (kind);

-- who wrote a checklist
-- MOVED HERE 2026-08-04. This sat ~6,200 lines ABOVE the CREATE TABLE it
-- targets. DROP TRIGGER IF EXISTS tolerates a missing table, but CREATE
-- TRIGGER does not, so on a genuinely FRESH tenant database byo-setup.sql
-- stopped dead here with 'relation "public.checklists_runbooks" does not
-- exist'. It went unnoticed because an existing database already had the
-- table by the time the file was re-run.
DROP TRIGGER IF EXISTS tr_checklists_runbooks_author ON public.checklists_runbooks;
CREATE TRIGGER tr_checklists_runbooks_author
  BEFORE INSERT OR UPDATE ON public.checklists_runbooks
  FOR EACH ROW EXECUTE FUNCTION public._force_row_author('created_by');

CREATE TABLE IF NOT EXISTS public.assessment_phase_checklist_state (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  assessment_id        UUID NOT NULL REFERENCES public.assessments(id) ON DELETE CASCADE,
  phase_index          INT  NOT NULL,
  phase_id             UUID,
  checklist_runbook_id UUID NOT NULL REFERENCES public.checklists_runbooks(id) ON DELETE CASCADE,
  ticks                JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Migrate-friendly: if the table existed without phase_id, add it.
ALTER TABLE public.assessment_phase_checklist_state
  ADD COLUMN IF NOT EXISTS phase_id UUID;

CREATE INDEX IF NOT EXISTS idx_apcs_assessment
  ON public.assessment_phase_checklist_state (assessment_id);
CREATE INDEX IF NOT EXISTS idx_apcs_phase_id
  ON public.assessment_phase_checklist_state (assessment_id, phase_id);

ALTER TABLE public.assessment_phase_checklist_state
  DROP CONSTRAINT IF EXISTS assessment_phase_checklist_state_assessment_id_phase_index_chec_key;

CREATE UNIQUE INDEX IF NOT EXISTS uq_apcs_by_phase_id
  ON public.assessment_phase_checklist_state (assessment_id, phase_id, checklist_runbook_id)
  WHERE phase_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_apcs_by_phase_index
  ON public.assessment_phase_checklist_state (assessment_id, phase_index, checklist_runbook_id)
  WHERE phase_id IS NULL;

ALTER TABLE public.checklists_runbooks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assessment_phase_checklist_state ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS crb_read ON public.checklists_runbooks;
CREATE POLICY crb_read ON public.checklists_runbooks
  FOR SELECT TO authenticated
  USING (public.current_user_role() NOT IN ('client', 'none') OR client_visible = true);

DROP POLICY IF EXISTS crb_insert ON public.checklists_runbooks;
CREATE POLICY crb_insert ON public.checklists_runbooks
  FOR INSERT TO authenticated WITH CHECK (public.can_write());

DROP POLICY IF EXISTS crb_update ON public.checklists_runbooks;
CREATE POLICY crb_update ON public.checklists_runbooks
  FOR UPDATE TO authenticated USING (public.can_write()) WITH CHECK (true);

DROP POLICY IF EXISTS crb_delete ON public.checklists_runbooks;
CREATE POLICY crb_delete ON public.checklists_runbooks
  FOR DELETE TO authenticated USING (public.can_write());

DROP POLICY IF EXISTS apcs_read ON public.assessment_phase_checklist_state;
CREATE POLICY apcs_read ON public.assessment_phase_checklist_state
  FOR SELECT TO authenticated
  USING (
    public.current_user_role() NOT IN ('client', 'none')
    OR EXISTS (
      SELECT 1 FROM public.assessments a
      JOIN public.checklists_runbooks crb
        ON crb.id = assessment_phase_checklist_state.checklist_runbook_id
      WHERE a.id = assessment_phase_checklist_state.assessment_id
        AND a.client_id = public.current_user_client_id()
        AND crb.client_visible = true
    )
  );

DROP POLICY IF EXISTS apcs_write ON public.assessment_phase_checklist_state;
CREATE POLICY apcs_write ON public.assessment_phase_checklist_state
  FOR ALL TO authenticated
  USING (public.can_write())
  WITH CHECK (public.can_write());

ALTER TABLE public.settings
  -- ON FROM THE START (674). [stated] Arian: "make checklists and runbooks
  -- enabled from the start." The curated OWASP/PTES/NIST templates ship with
  -- the product, so a firm that never finds the toggle never sees what it
  -- already has.
  --
  -- The DEFAULT only reaches new rows, so an existing tenant keeps whatever it
  -- has — and one that has never touched the setting sits at the old `false`.
  -- Flipped for those too, and ONLY those: a firm that deliberately switched it
  -- off has a row saying so, and the wizard writes the value explicitly.
  ADD COLUMN IF NOT EXISTS enable_checklists_runbooks BOOLEAN NOT NULL DEFAULT true;

-- The base column-grant block ran earlier in setup, before this column was
-- added. Without an explicit grant here, SELECT on this column returns 403.
DO $$
BEGIN
  EXECUTE 'GRANT SELECT (enable_checklists_runbooks) ON public.settings TO authenticated';
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE public.checklists_runbooks;
    EXCEPTION WHEN duplicate_object THEN NULL; END;
    BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE public.assessment_phase_checklist_state;
    EXCEPTION WHEN duplicate_object THEN NULL; END;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public._tg_touch_updated_at_crb()
RETURNS TRIGGER LANGUAGE plpgsql AS $fn$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END $fn$;

DROP TRIGGER IF EXISTS tg_crb_touch ON public.checklists_runbooks;
CREATE TRIGGER tg_crb_touch BEFORE UPDATE ON public.checklists_runbooks
  FOR EACH ROW EXECUTE FUNCTION public._tg_touch_updated_at_crb();

DROP TRIGGER IF EXISTS tg_apcs_touch ON public.assessment_phase_checklist_state;
CREATE TRIGGER tg_apcs_touch BEFORE UPDATE ON public.assessment_phase_checklist_state
  FOR EACH ROW EXECUTE FUNCTION public._tg_touch_updated_at_crb();

-- ─── Export RPCs for BYO→master downgrade migration ─────────────────────
-- Mirrors rpc_export_kb_entries / rpc_export_profiles / etc. so master's
-- migrateBYOToMaster() can pull these tables when an Enterprise tenant
-- downgrades to Starter/Pro.
DROP FUNCTION IF EXISTS public.rpc_export_checklists_runbooks(text);
DROP FUNCTION IF EXISTS public.rpc_export_checklists_runbooks(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_export_checklists_runbooks(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $fn$
BEGIN
  PERFORM public._pental_require_auth(p_auth, p_secret, 'rpc_export_checklists_runbooks');
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'checklists_runbooks'
  ) THEN RETURN '[]'::jsonb; END IF;
  RETURN COALESCE(
    (SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM public.checklists_runbooks) t),
    '[]'::jsonb
  );
END;
$fn$;
GRANT EXECUTE ON FUNCTION public.rpc_export_checklists_runbooks(text, jsonb) TO anon, authenticated, service_role;

DROP FUNCTION IF EXISTS public.rpc_export_assessment_phase_checklist_state(text);
DROP FUNCTION IF EXISTS public.rpc_export_assessment_phase_checklist_state(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_export_assessment_phase_checklist_state(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $fn$
BEGIN
  PERFORM public._pental_require_auth(p_auth, p_secret, 'rpc_export_assessment_phase_checklist_state');
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'assessment_phase_checklist_state'
  ) THEN RETURN '[]'::jsonb; END IF;
  RETURN COALESCE(
    (SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM public.assessment_phase_checklist_state) t),
    '[]'::jsonb
  );
END;
$fn$;
GRANT EXECUTE ON FUNCTION public.rpc_export_assessment_phase_checklist_state(text, jsonb) TO anon, authenticated, service_role;
-- Patch BYO bulk_clean to include checklists_runbooks in wipe
--
-- The two wipe functions (rpc_bulk_clean and rpc_apply_signed_bulk_clean)
-- delete most tenant data when re-provisioning, but the new checklists
-- tables were added later and never made it into the wipe list. Without
-- this, after a wipe-and-re-provision the new BYO has orphan
-- checklists_runbooks rows from the previous install.
--
-- assessment_phase_checklist_state CASCADEs from assessments, so it's
-- cleaned automatically. checklists_runbooks does not, add explicitly.
--
-- Idempotent. Safe to re-run.

-- Add DELETE FROM checklists_runbooks to both wipe paths. We do this by
-- a small wrapper RPC that the existing wipe functions don't actually
-- need to know about, easiest is to just add a trigger that wipes
-- checklists_runbooks whenever assessments is wiped on a re-provision.
-- But triggers fire per-row; cleaner to just update both functions.

-- ─── 1. Update rpc_apply_signed_bulk_clean ──────────────────────────────
-- Replace just the wipe-body portion. Since DROP FUNCTION + CREATE
-- requires rewriting the whole function and that's huge, we instead
-- create a tiny helper that adds the missing DELETEs and call it.

CREATE OR REPLACE FUNCTION public._wipe_extra_tables()
  RETURNS void LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp
AS $fn$
BEGIN
  PERFORM set_config('pental.bypass_protect', 'true', true);
  -- assessment_phase_checklist_state is CASCADE-deleted via assessments,
  -- but explicit DELETE here is harmless and defensive.
  IF EXISTS (SELECT 1 FROM information_schema.tables
             WHERE table_schema='public' AND table_name='assessment_phase_checklist_state') THEN
    EXECUTE 'DELETE FROM public.assessment_phase_checklist_state WHERE true';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables
             WHERE table_schema='public' AND table_name='checklists_runbooks') THEN
    EXECUTE 'DELETE FROM public.checklists_runbooks WHERE true';
  END IF;
END;
$fn$;

REVOKE ALL ON FUNCTION public._wipe_extra_tables() FROM PUBLIC, anon, authenticated;

-- ─── 2. Trigger on settings deletion: also wipes the new tables ─────────
-- Both wipe RPCs end with `DELETE FROM settings WHERE true` after all
-- the other tenant data is gone. Hook a BEFORE DELETE trigger to that
-- so the extra tables get cleaned at the same point.
CREATE OR REPLACE FUNCTION public._wipe_extras_on_settings_delete()
  RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp
AS $fn$
BEGIN
  -- Only fire during a bulk-clean style operation (pental.bypass_protect set).
  IF current_setting('pental.bypass_protect', true) = 'true' THEN
    PERFORM public._wipe_extra_tables();
  END IF;
  RETURN OLD;
END;
$fn$;

DROP TRIGGER IF EXISTS tg_settings_wipe_extras ON public.settings;
CREATE TRIGGER tg_settings_wipe_extras
  BEFORE DELETE ON public.settings
  FOR EACH ROW EXECUTE FUNCTION public._wipe_extras_on_settings_delete();

COMMENT ON TRIGGER tg_settings_wipe_extras ON public.settings IS
  'Cleans checklists_runbooks (and apcs defensively) during a bulk-clean. Fires only when pental.bypass_protect is set, which is exclusively done by the bulk_clean / signed_bulk_clean RPCs.';
-- BYO branding bucket: allow admin/senior to upload, update, delete
--
-- Inline EXISTS subqueries against public.profiles in storage RLS policies
-- run as the storage role (supabase_storage_admin) which does NOT have
-- SELECT on public.profiles. The fix: wrap the profile check in a
-- SECURITY DEFINER function so it runs as postgres with full access.
-- Same pattern as can_access_assessment_file().
--
-- Idempotent.

CREATE OR REPLACE FUNCTION public.can_manage_branding() RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_catalog, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE auth_user_id = auth.uid()
      AND active = true
      AND role IN ('admin', 'senior')
  );
$$;

GRANT EXECUTE ON FUNCTION public.can_manage_branding() TO authenticated, anon;

DROP POLICY IF EXISTS branding_admin_insert ON storage.objects;
DROP POLICY IF EXISTS branding_admin_update ON storage.objects;
DROP POLICY IF EXISTS branding_admin_delete ON storage.objects;
DROP POLICY IF EXISTS branding_public_read ON storage.objects;

CREATE POLICY branding_public_read ON storage.objects
  FOR SELECT
  USING (bucket_id = 'branding');

-- 1785: the public read stays public (the sign-in page shows the logo before
-- anybody signs in); a change to the branding asks for a fresh sign-in check.
CREATE POLICY branding_admin_insert ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'branding' AND (SELECT public._files_mfa_fresh()) AND public.can_manage_branding());

CREATE POLICY branding_admin_update ON storage.objects
  FOR UPDATE TO authenticated
  USING (bucket_id = 'branding' AND (SELECT public._files_mfa_fresh()) AND public.can_manage_branding());

CREATE POLICY branding_admin_delete ON storage.objects
  FOR DELETE TO authenticated
  USING (bucket_id = 'branding' AND (SELECT public._files_mfa_fresh()) AND public.can_manage_branding());

-- ─── templates bucket: DOCX template files (private, staff-only) ────────────
-- Stores .docx template binaries that previously lived in settings.pdf_templates
-- JSONB. Multi-MB docs in JSONB caused statement_timeout on UPDATE; moved here.
-- Path convention: <type>/<template_id>.docx (e.g. report/tpl_abc123.docx).
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('templates', 'templates', false, 10485760,
        ARRAY['application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
ON CONFLICT (id) DO UPDATE
  SET file_size_limit = EXCLUDED.file_size_limit,
      allowed_mime_types = EXCLUDED.allowed_mime_types;

DROP POLICY IF EXISTS templates_staff_read ON storage.objects;
DROP POLICY IF EXISTS templates_staff_insert ON storage.objects;
DROP POLICY IF EXISTS templates_staff_update ON storage.objects;
DROP POLICY IF EXISTS templates_staff_delete ON storage.objects;

-- Read access: any active user in the tenant. Templates are needed by the
-- portal to generate per-assessment .docx renders, including for regular
-- users who hit Download Report. Restricting reads to admin/senior would
-- break that flow.
-- 1785: every one asks for a fresh sign-in check.
CREATE POLICY templates_staff_read ON storage.objects
  FOR SELECT TO authenticated
  USING (
    bucket_id = 'templates' AND (SELECT public._files_mfa_fresh()) AND
    EXISTS (SELECT 1 FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true)
    -- 1943: not a contractor while contractors are off.
    AND (SELECT public.current_user_role()) <> 'none'
  );

CREATE POLICY templates_staff_insert ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'templates' AND (SELECT public._files_mfa_fresh()) AND public.can_manage());

CREATE POLICY templates_staff_update ON storage.objects
  FOR UPDATE TO authenticated
  USING (bucket_id = 'templates' AND (SELECT public._files_mfa_fresh()) AND public.can_manage());

CREATE POLICY templates_staff_delete ON storage.objects
  FOR DELETE TO authenticated
  USING (bucket_id = 'templates' AND (SELECT public._files_mfa_fresh()) AND public.can_manage());

-- ═══════════════════════════════════════════════════════════════════════════
-- Per-table export RPCs for downgrade (BYO → master).
--
-- master-side byo-migration.js calls rpc_export_<table> for each table.
-- These RPCs gate access via _pental_require_auth (signed JWT or secret) and
-- return all rows as a jsonb array. SECURITY DEFINER bypasses RLS so the
-- migration can read EVERYTHING regardless of who's calling.
--
-- Mirrors the pattern of rpc_export_webauthn_credentials etc. Idempotent.
-- ═══════════════════════════════════════════════════════════════════════════


DROP FUNCTION IF EXISTS public.rpc_export_settings(text);
DROP FUNCTION IF EXISTS public.rpc_export_settings(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_export_settings(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $fn$
BEGIN
  PERFORM public._pental_require_auth(p_auth, p_secret, 'rpc_export_settings');
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'settings'
  ) THEN
    RETURN '[]'::jsonb;
  END IF;
  RETURN COALESCE(
    (SELECT jsonb_agg(row_to_json(r)) FROM (SELECT * FROM public.settings) r),
    '[]'::jsonb
  );
END;
$fn$;
GRANT EXECUTE ON FUNCTION public.rpc_export_settings(text, jsonb) TO anon, authenticated, service_role;


