-- ═══════════════════════════════════════════════════════════════════════════
-- rpc_check_settings_secrets, returns has-flags for sensitive settings cols.
-- Portal calls this on bootstrap to drive "✓ Configured" UI without
-- transferring secret values over the wire.
-- ═══════════════════════════════════════════════════════════════════════════

-- 1844: WHY A SECRET IS IN PLAIN TEXT, so the portal says the cause rather
-- than only that one exists: the settings' encryption key empty (or not
-- there), its trigger switched off or missing, or pgcrypto not where this
-- file uses it. NULL when none of those is so.
CREATE OR REPLACE FUNCTION public._settings_secrets_fault() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $ssf$
DECLARE v_key text; v_found boolean; v_trig "char";
BEGIN
  SELECT key_value, true INTO v_key, v_found FROM public._encryption_keys WHERE key_name = 'credentials';
  IF NOT COALESCE(v_found, false) THEN RETURN 'key_missing'; END IF;
  IF COALESCE(v_key, '') = '' THEN RETURN 'key_empty'; END IF;
  IF to_regprocedure('extensions.pgp_sym_encrypt(text,text)') IS NULL THEN RETURN 'no_pgcrypto'; END IF;
  SELECT tgenabled INTO v_trig FROM pg_trigger WHERE tgrelid = 'public.settings'::regclass AND tgname = 'zzz_tr_settings_encrypt_secrets';
  IF NOT FOUND THEN RETURN 'trigger_missing'; END IF;
  IF v_trig = 'D' THEN RETURN 'trigger_off'; END IF;
  RETURN NULL;
END $ssf$;
REVOKE ALL ON FUNCTION public._settings_secrets_fault() FROM PUBLIC, anon, authenticated;

DROP FUNCTION IF EXISTS public.rpc_check_settings_secrets();
CREATE OR REPLACE FUNCTION public.rpc_check_settings_secrets()
  RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
AS $fn$
DECLARE
  v_role text;
  v_result jsonb;
BEGIN
  v_role := public.current_user_role();
  IF v_role = 'client' THEN RETURN '{}'::jsonb; END IF;

  IF v_role IN ('admin', 'senior') THEN
    SELECT jsonb_build_object(
      -- Check BOTH the plaintext column and its encrypted counterpart. These
      -- secrets are encrypted at rest by zzz_tr_settings_encrypt_secrets, which
      -- moves the value into <col>_enc and blanks the plaintext, so testing only
      -- the plaintext reported a saved secret as missing after the next reload.
      'has_ai_key',          ((ai_api_key IS NOT NULL AND ai_api_key <> '') OR ai_api_key_enc IS NOT NULL),
      -- 1799: write-only like the key; the screen says "set" and no more.
      'has_ai_custom_headers', (ai_custom_headers IS NOT NULL AND btrim(ai_custom_headers) <> ''),
      'has_smtp_pass',       ((smtp_pass IS NOT NULL AND smtp_pass <> '') OR smtp_pass_enc IS NOT NULL),
      'has_stripe_secret',   ((stripe_secret_key IS NOT NULL AND stripe_secret_key <> '') OR stripe_secret_key_enc IS NOT NULL),
      'has_stripe_whsec',    ((stripe_webhook_secret IS NOT NULL AND stripe_webhook_secret <> '') OR stripe_webhook_secret_enc IS NOT NULL),
      'has_teams_secret',    ((teams_client_secret IS NOT NULL AND teams_client_secret <> '') OR teams_client_secret_enc IS NOT NULL),
      'has_zoom_secret',     ((zoom_client_secret IS NOT NULL AND zoom_client_secret <> '') OR zoom_client_secret_enc IS NOT NULL),
      'has_slack_token',     ((slack_bot_token IS NOT NULL AND slack_bot_token <> '') OR slack_bot_token_enc IS NOT NULL),
      'has_google_api_key',  ((google_api_key IS NOT NULL AND google_api_key <> '') OR google_api_key_enc IS NOT NULL),
      'has_sso_google_secret', ((sso_google_client_secret IS NOT NULL AND sso_google_client_secret <> '') OR sso_google_client_secret_enc IS NOT NULL),
      'has_sso_ms_secret',     ((sso_ms_client_secret IS NOT NULL AND sso_ms_client_secret <> '') OR sso_ms_client_secret_enc IS NOT NULL),
      -- Distinguish "no secret stored" from "secret stored but no longer
      -- decryptable". The latter happens if the credentials key in
      -- _encryption_keys was regenerated after the value was encrypted, which
      -- otherwise looks identical to a missing key and is impossible to diagnose.
      'ai_key_undecryptable',    (ai_api_key_enc IS NOT NULL AND public._settings_decrypt(ai_api_key_enc) IS NULL),
      'smtp_pass_undecryptable', (smtp_pass_enc IS NOT NULL AND public._settings_decrypt(smtp_pass_enc) IS NULL),
      'stripe_undecryptable',    (stripe_secret_key_enc IS NOT NULL AND public._settings_decrypt(stripe_secret_key_enc) IS NULL),
      -- Which secrets are sitting UNENCRYPTED right now. A plaintext column is
      -- only ever non-empty when the encrypt step failed on the last write, so
      -- this is not a normal state and the admin has no other way to see it.
      -- Silence is what let a plaintext AI key and a stale ciphertext coexist
      -- for as long as they did.
      'secrets_plaintext', (
        CASE WHEN smtp_pass IS NOT NULL AND smtp_pass <> '' THEN '["smtp_pass"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN smtp_oauth_refresh IS NOT NULL AND smtp_oauth_refresh <> '' THEN '["smtp_oauth_refresh"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN stripe_secret_key IS NOT NULL AND stripe_secret_key <> '' THEN '["stripe_secret_key"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN stripe_webhook_secret IS NOT NULL AND stripe_webhook_secret <> '' THEN '["stripe_webhook_secret"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN ai_api_key IS NOT NULL AND ai_api_key <> '' THEN '["ai_api_key"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN teams_client_secret IS NOT NULL AND teams_client_secret <> '' THEN '["teams_client_secret"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN zoom_client_secret IS NOT NULL AND zoom_client_secret <> '' THEN '["zoom_client_secret"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN slack_bot_token IS NOT NULL AND slack_bot_token <> '' THEN '["slack_bot_token"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN google_api_key IS NOT NULL AND google_api_key <> '' THEN '["google_api_key"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN sso_google_client_secret IS NOT NULL AND sso_google_client_secret <> '' THEN '["sso_google_client_secret"]'::jsonb ELSE '[]'::jsonb END
        ||         CASE WHEN sso_ms_client_secret IS NOT NULL AND sso_ms_client_secret <> '' THEN '["sso_ms_client_secret"]'::jsonb ELSE '[]'::jsonb END
      )
    )
    INTO v_result
    FROM public.settings
    LIMIT 1;
    -- 1844: and why, when one is.
    IF jsonb_array_length(COALESCE(v_result -> 'secrets_plaintext', '[]'::jsonb)) > 0 THEN
      v_result := v_result || jsonb_build_object('secrets_fault', public._settings_secrets_fault());
    END IF;
  ELSE
    SELECT jsonb_build_object(
      'has_ai_key', ((ai_api_key IS NOT NULL AND ai_api_key <> '') OR ai_api_key_enc IS NOT NULL)
    )
    INTO v_result
    FROM public.settings
    LIMIT 1;
  END IF;

  RETURN COALESCE(v_result, '{}'::jsonb);
END
$fn$;

REVOKE ALL ON FUNCTION public.rpc_check_settings_secrets() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_check_settings_secrets() TO authenticated;


-- ═══════════════════════════════════════════════════════════════════════════
-- ━━ ACCOUNTING INTEGRATION (folded in from migrations so fresh BYO setups
-- ━━ are complete; previously only available as upgrade migrations) ━━
-- Apply order: base integrations → chunk3 additions → export RPCs.
-- All idempotent (CREATE ... IF NOT EXISTS / CREATE OR REPLACE). Depends on
-- current_user_role() and _pental_require_auth(), both defined earlier above.
-- ═══════════════════════════════════════════════════════════════════════════

-- ━━ byo-add-accounting-integrations.sql ━━
-- ─────────────────────────────────────────────────────────────────────
-- Xero / accounting integration tables for per-tenant BYO database
-- ─────────────────────────────────────────────────────────────────────
-- Adds the foundation for accounting integrations (Phase 1 = Xero).
-- Architecture (1838: see "XERO FROM THE FIRM'S OWN SIDE" further down,
-- which does the work now; Pental's website no longer does any of it):
--   - One Pental app registered at developer.xero.com, a public one (PKCE,
--     no secret). Each tenant connects their own Xero org through it, and
--     this database turns the sign-in into access itself.
--   - Per-tenant tokens (access/refresh) stored in this DB, sealed with
--     this database's own key (_get_cred_key), as a tracker's credentials
--     are.
--   - Designed to be provider-agnostic so adding QuickBooks / FreshBooks
--     later is just a new value for the 'provider' column.
--
-- Tables:
--   accounting_connections, one row per (provider, tenant) connection.
--     Stores encrypted tokens, the Xero org ID/name they connected, and
--     expiry tracking. We only allow ONE active connection per provider
--     per tenant (UNIQUE constraint).
--   accounting_sync_log, append-only event journal for debugging.
--     "Pushed invoice X to Xero", "Token refresh failed", etc.
--   invoice_external_links, Pental invoice id ↔ external (Xero) id.
--     Lets the manual "Push to Xero" button detect already-pushed
--     invoices and lets the UI render a status badge per invoice.
--   client_external_links, same idea for clients ↔ Xero contacts.
--     Created on first invoice push.
--
-- Idempotent. Safe to run multiple times.
-- ─────────────────────────────────────────────────────────────────────

-- Make sure pgcrypto is available (it usually is on Supabase, but be safe)
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

-- ── Connections ─────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.accounting_connections (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  provider text NOT NULL CHECK (provider IN ('xero', 'quickbooks', 'freshbooks', 'sage', 'wave')),
  -- The Xero "tenant" / org these tokens authorise access to. Xero calls
  -- this xero_tenant_id; we name it org_id to stay provider-agnostic.
  org_id text NOT NULL,
  org_name text,
  -- Encrypted token blob: JSON with access_token, refresh_token,
  -- id_token, token_type, scope. Encrypted with the tenant's
  -- credentials key from _encryption_keys (key_name='credentials').
  -- Stored base64 of the pgp_sym_encrypt bytea output.
  encrypted_tokens text NOT NULL,
  -- When the current access_token expires (refresh BEFORE this, not after)
  expires_at timestamptz NOT NULL,
  -- Updated each time we refresh the token successfully
  last_refreshed_at timestamptz,
  -- Set to false when the user clicks Disconnect or when we can't refresh
  is_active boolean NOT NULL DEFAULT true,
  -- Who connected it (audit trail). NULL means "we don't know" but the
  -- column being NULL is rare; the OAuth callback should always know.
  connected_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  connected_by_name text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- Only one ACTIVE connection per provider per tenant. The partial
  -- unique index lets us keep historical/disconnected rows for audit
  -- without preventing a fresh reconnect.
  UNIQUE (provider, org_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS accounting_connections_one_active_per_provider
  ON public.accounting_connections (provider)
  WHERE is_active = true;

CREATE INDEX IF NOT EXISTS accounting_connections_expires_at_idx
  ON public.accounting_connections (expires_at)
  WHERE is_active = true;

-- ── Sync log (debugging / audit trail) ──────────────────────────────
CREATE TABLE IF NOT EXISTS public.accounting_sync_log (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  provider text NOT NULL,
  -- Free-form event type: 'connected', 'disconnected', 'token_refreshed',
  -- 'token_refresh_failed', 'invoice_pushed', 'invoice_push_failed',
  -- 'contact_pushed', 'webhook_received', 'webhook_signature_failed', etc.
  event_type text NOT NULL,
  -- Which Pental record this is about (one of these will be set)
  invoice_id uuid REFERENCES public.invoices(id) ON DELETE SET NULL,
  client_id uuid REFERENCES public.clients(id) ON DELETE SET NULL,
  -- Free-form payload: API response, error message, anything useful
  -- for diagnosing what happened. Truncated to ~10KB in app code.
  details jsonb DEFAULT '{}'::jsonb,
  -- Was this a success? (NULL = informational, true/false = outcome)
  success boolean,
  -- Who triggered it (NULL = automatic/webhook)
  triggered_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS accounting_sync_log_created_at_idx
  ON public.accounting_sync_log (created_at DESC);

CREATE INDEX IF NOT EXISTS accounting_sync_log_provider_event_idx
  ON public.accounting_sync_log (provider, event_type, created_at DESC);

CREATE INDEX IF NOT EXISTS accounting_sync_log_invoice_idx
  ON public.accounting_sync_log (invoice_id)
  WHERE invoice_id IS NOT NULL;

-- ── Invoice ↔ external invoice mapping ──────────────────────────────
CREATE TABLE IF NOT EXISTS public.invoice_external_links (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  invoice_id uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  provider text NOT NULL,
  -- The provider's identifier for the corresponding invoice. For Xero
  -- this is the InvoiceID UUID. Length-permissive to support future
  -- providers with longer ids.
  external_id text NOT NULL,
  -- The provider's invoice number / reference (Xero "InvoiceNumber").
  -- Useful for the UI badge so we can show "Xero INV-001" without
  -- having to round-trip the API.
  external_number text,
  -- Mirrored from the provider: 'draft', 'submitted', 'authorised',
  -- 'paid', 'voided' etc. Provider-specific strings, we don't try
  -- to normalise them across providers.
  external_status text,
  -- Latest known total + currency from the provider. Lets the UI
  -- detect divergence ("amount in Xero differs from amount in Pental").
  external_amount_due numeric,
  external_amount_paid numeric,
  external_currency text,
  -- Last successful push (Pental → provider)
  last_pushed_at timestamptz NOT NULL DEFAULT now(),
  -- Last successful pull (provider → Pental, via webhook or scheduled sync)
  last_pulled_at timestamptz,
  -- Last error (if any) when pushing or pulling
  last_error text,
  last_error_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- A Pental invoice can only have ONE external id per provider. If we
  -- need to re-push after a void, we update the existing row.
  UNIQUE (invoice_id, provider)
);

CREATE INDEX IF NOT EXISTS invoice_external_links_provider_external_id_idx
  ON public.invoice_external_links (provider, external_id);

-- ── Client ↔ external contact mapping ───────────────────────────────
CREATE TABLE IF NOT EXISTS public.client_external_links (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,
  provider text NOT NULL,
  -- Xero ContactID
  external_id text NOT NULL,
  -- ContactName from Xero so we can show it in the UI without an API call
  external_name text,
  last_pushed_at timestamptz NOT NULL DEFAULT now(),
  last_pulled_at timestamptz,
  last_error text,
  last_error_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (client_id, provider)
);

CREATE INDEX IF NOT EXISTS client_external_links_provider_external_id_idx
  ON public.client_external_links (provider, external_id);

-- ── Outbound sync queue (for retries / scheduled pushes) ────────────
-- The "Push to Xero" button enqueues a row here, and a cron worker
-- processes them. Auto-push on invoice 'sent' also enqueues. Lets us
-- retry transient failures without blocking the user's request.
CREATE TABLE IF NOT EXISTS public.accounting_sync_queue (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  provider text NOT NULL,
  -- What kind of sync: 'push_invoice', 'push_contact', 'pull_invoice_status'
  task_type text NOT NULL,
  -- Subject id (invoice id for push_invoice, client id for push_contact)
  subject_id uuid NOT NULL,
  -- 'pending', 'in_progress', 'done', 'failed'
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'in_progress', 'done', 'failed')),
  -- Retry tracking, exponential backoff in app code
  attempts integer NOT NULL DEFAULT 0,
  max_attempts integer NOT NULL DEFAULT 5,
  last_error text,
  -- Don't attempt before this time (for backoff)
  scheduled_for timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  completed_at timestamptz,
  triggered_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS accounting_sync_queue_pending_idx
  ON public.accounting_sync_queue (scheduled_for, provider)
  WHERE status = 'pending';

CREATE INDEX IF NOT EXISTS accounting_sync_queue_subject_idx
  ON public.accounting_sync_queue (subject_id, task_type, status);

-- ── RLS ─────────────────────────────────────────────────────────────
ALTER TABLE public.accounting_connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.accounting_sync_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_external_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.client_external_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.accounting_sync_queue ENABLE ROW LEVEL SECURITY;

-- Tokens are sensitive, only the service_role can read accounting_connections.
-- The portal app uses the OAuth flow + RPC for connect/disconnect, never
-- reads tokens directly. The sync worker uses service_role.
REVOKE ALL ON public.accounting_connections FROM authenticated, anon;
GRANT ALL ON public.accounting_connections TO service_role;

-- Sync log: authenticated admin can read for the Integrations debug panel
-- 1838: by the caller's role (current_user_role), with a fresh second
-- factor. These compared profiles.id with auth.uid(), which are not the same
-- (777), so they matched nobody and the Integrations page showed nothing.
DROP POLICY IF EXISTS sync_log_admin_select ON public.accounting_sync_log;
CREATE POLICY sync_log_admin_select ON public.accounting_sync_log FOR SELECT
  TO authenticated USING (public.mfa_is_fresh() AND public.current_user_role() = 'admin');
GRANT SELECT ON public.accounting_sync_log TO authenticated;
GRANT ALL ON public.accounting_sync_log TO service_role;

-- External links: authenticated admin can read; service_role does the writes
-- Whoever reads the invoices (invoices_read, the firm's side of it).
DROP POLICY IF EXISTS invoice_links_admin_select ON public.invoice_external_links;
CREATE POLICY invoice_links_admin_select ON public.invoice_external_links FOR SELECT
  TO authenticated USING (public.mfa_is_fresh() AND public.current_user_role() IN ('admin', 'senior', 'sales'));
GRANT SELECT ON public.invoice_external_links TO authenticated;
GRANT ALL ON public.invoice_external_links TO service_role;

DROP POLICY IF EXISTS client_links_admin_select ON public.client_external_links;
CREATE POLICY client_links_admin_select ON public.client_external_links FOR SELECT
  TO authenticated USING (public.mfa_is_fresh() AND public.current_user_role() IN ('admin', 'senior', 'sales'));
GRANT SELECT ON public.client_external_links TO authenticated;
GRANT ALL ON public.client_external_links TO service_role;

-- Sync queue: admin can read for visibility, manual enqueue via RPC
DROP POLICY IF EXISTS sync_queue_admin_select ON public.accounting_sync_queue;
CREATE POLICY sync_queue_admin_select ON public.accounting_sync_queue FOR SELECT
  TO authenticated USING (public.mfa_is_fresh() AND public.current_user_role() = 'admin');
GRANT SELECT ON public.accounting_sync_queue TO authenticated;
GRANT ALL ON public.accounting_sync_queue TO service_role;

-- ── RPCs (server-side helpers, all SECURITY DEFINER) ────────────────

-- 1838: rpc_accounting_encrypt and rpc_accounting_decrypt are gone. Only
-- Pental's website called them, to store and read a firm's Xero tokens from
-- its own servers, and they read a key (_encryption_keys) that moved to the
-- vault long ago. This database seals and opens them itself now
-- (_xero_seal, _xero_unseal).
DROP FUNCTION IF EXISTS public.rpc_accounting_encrypt(text, uuid);
DROP FUNCTION IF EXISTS public.rpc_accounting_decrypt(text, uuid);

-- Read-only status view for the Integrations Settings page. Returns
-- enough info for the UI to render "Connected to <org>" / "Not connected"
-- WITHOUT exposing tokens. Callable by authenticated admin.
CREATE OR REPLACE FUNCTION public.rpc_accounting_status(p_provider text DEFAULT NULL)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $fn$
DECLARE v_results jsonb := '[]'::jsonb;
BEGIN
  -- Caller must be authenticated admin
  -- 777: `profiles.id` IS NOT `auth.uid()` - the row carries its own id and an
  -- `auth_user_id`. This matched nothing, so it refused EVERY admin.
  IF NOT EXISTS (SELECT 1 FROM public.profiles
                  WHERE id = public.current_profile_id() AND role = 'admin') THEN
    RETURN jsonb_build_object('error', 'admin only');
  END IF;
  -- 1838: with the second factor fresh, as everything else of the connection.
  IF NOT public.mfa_is_fresh() THEN RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501'; END IF;
  SELECT jsonb_agg(jsonb_build_object(
    'provider',          provider,
    'org_id',            org_id,
    'org_name',          org_name,
    'is_active',         is_active,
    'expires_at',        expires_at,
    'last_refreshed_at', last_refreshed_at,
    'connected_by_name', connected_by_name,
    'connected_at',      created_at
  )) INTO v_results
  FROM public.accounting_connections
  WHERE is_active = true
    AND (p_provider IS NULL OR provider = p_provider);
  RETURN COALESCE(v_results, '[]'::jsonb);
END;
$fn$;
REVOKE ALL ON FUNCTION public.rpc_accounting_status(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_accounting_status(text) TO authenticated;

-- Disconnect: rpc_accounting_disconnect, in "XERO FROM THE FIRM'S OWN SIDE"
-- below (1838), where it also removes the connection in Xero.

-- ━━ byo-accounting-chunk3-additions.sql ━━
-- ─────────────────────────────────────────────────────────────────────
-- Accounting integrations: chunk 3 schema additions
-- ─────────────────────────────────────────────────────────────────────
-- Adds:
--   - accounting_sync_queue.external_subject_id: stores Xero (or other
--     provider) external IDs for pull tasks where there's no local
--     Pental UUID yet. Used by the webhook receiver.
--   - accounting_sync_queue.subject_id: relax NOT NULL (pulls reference
--     external IDs only)
--   - accounting_settings: per-tenant config for the integration
--     (payment account code, VAT mapping, default line text)
--
-- PREREQUISITE: Run byo-add-accounting-integrations.sql FIRST. That
-- migration creates accounting_sync_queue and the other tables this
-- file alters. If you see ERROR 42P01 ("relation does not exist"), the
-- prerequisite hasn't been applied yet.
--
-- Idempotent. Safe to run multiple times.

-- Prerequisite guard: fail early with a friendly message if chunk 1
-- hasn't been applied. Without this guard, the next ALTER would fail
-- with a postgres-internal error that doesn't explain what to do.
DO $check$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'accounting_sync_queue'
  ) THEN
    RAISE EXCEPTION 'Prerequisite missing: run byo-add-accounting-integrations.sql first. That migration creates accounting_sync_queue and the other base tables this script alters.';
  END IF;
END
$check$;

-- 1. Relax subject_id and add external_subject_id
ALTER TABLE public.accounting_sync_queue
  ALTER COLUMN subject_id DROP NOT NULL;

ALTER TABLE public.accounting_sync_queue
  ADD COLUMN IF NOT EXISTS external_subject_id text;

-- Index for the worker's lookup of pull tasks
CREATE INDEX IF NOT EXISTS accounting_sync_queue_external_subject_idx
  ON public.accounting_sync_queue (provider, task_type, external_subject_id);

-- 2. Allow new task_types (pull_invoice_status, pull_contact). The
-- original CHECK constraint allowed any text; if you added one later,
-- update it here. We rely on the app layer for validation.

-- 3. Per-tenant accounting settings
CREATE TABLE IF NOT EXISTS public.accounting_settings (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  provider text NOT NULL UNIQUE CHECK (provider IN ('xero','quickbooks','freshbooks','sage','wave')),
  -- Xero "account code" for receiving payments. Defaults to '090'
  -- (Xero's standard Business Bank Account). Tenants with a different
  -- chart of accounts can override.
  payment_account_code text DEFAULT '090',
  -- Xero TaxType to apply to invoice lines. Examples:
  --   'NONE'   , outside scope of VAT (default; firm sets VAT in Xero)
  --   'OUTPUT2', UK 20% Output VAT
  --   'EXEMPTOUTPUT', Exempt Income
  -- Tenants who want Pental to mark VAT on each line set this.
  line_tax_type text DEFAULT 'AUTO',
  -- Sales account code (where the income hits). Default '200' is
  -- Xero's standard Sales account.
  sales_account_code text DEFAULT '200',
  -- Default line description if invoice.description is null/empty
  default_line_description text DEFAULT 'Security Assessment Services',
  -- Currency code for invoices. NULL = use the invoice's own currency
  -- when present, else GBP. Tenants who always invoice in one currency
  -- can set this.
  currency_code text,
  -- Per-status auto-push toggle. Default: push on sent + paid.
  auto_push_on_sent boolean NOT NULL DEFAULT true,
  auto_push_on_paid boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- 1839: 'AUTO' (the default): no tax type is named on the line, so Xero uses
-- the sales account's own tax rate, and the total Xero works out is checked
-- against what the client was asked for before the invoice is authorised
-- (_xero_total_differs). 'NONE' was the default and the portal called it
-- recommended: a VAT-registered firm's Xero then had every invoice short of
-- its VAT.
ALTER TABLE public.accounting_settings ALTER COLUMN line_tax_type SET DEFAULT 'AUTO';
-- And a firm that charges VAT, with 'NONE' saved (the card's old default,
-- called recommended), is moved to 'AUTO' once, on the update: with 'NONE'
-- every invoice would now fail the total check. Said in the sync log.
DO $xero_tax_auto$
BEGIN
  IF to_regclass('public._pental_schema_version') IS NOT NULL THEN
    IF COALESCE((SELECT version FROM public._pental_schema_version WHERE id = 1), 0) < 2025100501
       AND COALESCE((SELECT vat_rate FROM public.settings ORDER BY created_at ASC NULLS LAST, id LIMIT 1), 0) > 0 THEN
      UPDATE public.accounting_settings SET line_tax_type = 'AUTO', updated_at = now()
       WHERE provider = 'xero' AND upper(btrim(COALESCE(line_tax_type, ''))) = 'NONE';
      IF FOUND THEN
        INSERT INTO public.accounting_sync_log (provider, event_type, details, success)
        VALUES ('xero', 'tax_type_changed', jsonb_build_object('from', 'NONE', 'to', 'AUTO', 'note',
          'You charge VAT, and NONE sent every invoice to Xero without it. Invoices now go with the sales account''s own tax rate, and Xero''s total is checked against what the client was asked for. Choose another in Settings, Integrations, Xero if your sales account has no tax rate.'), NULL);
      END IF;
    END IF;
  END IF;
END $xero_tax_auto$;
-- And the account card payments go to (Stripe pays out in batches, net of its
-- fees, so firms often keep a clearing account for it); the payments account
-- where none is named.
ALTER TABLE public.accounting_settings ADD COLUMN IF NOT EXISTS card_payment_account_code text;

-- Tenant admin can read; service_role writes
ALTER TABLE public.accounting_settings ENABLE ROW LEVEL SECURITY;
-- 1838: by role with a fresh second factor (these matched nobody, as above).
DROP POLICY IF EXISTS accounting_settings_admin_read ON public.accounting_settings;
CREATE POLICY accounting_settings_admin_read ON public.accounting_settings FOR SELECT
  TO authenticated USING (public.mfa_is_fresh() AND public.current_user_role() = 'admin');
DROP POLICY IF EXISTS accounting_settings_admin_write ON public.accounting_settings;
CREATE POLICY accounting_settings_admin_write ON public.accounting_settings FOR ALL
  TO authenticated USING (public.mfa_is_fresh() AND public.current_user_role() = 'admin')
  WITH CHECK (public.mfa_is_fresh() AND public.current_user_role() = 'admin');
GRANT SELECT, INSERT, UPDATE ON public.accounting_settings TO authenticated;
GRANT ALL ON public.accounting_settings TO service_role;

-- Helper RPC to upsert settings idempotently
-- 1839: and the account card payments go to (p_card_payment_account_code;
-- '' for the payments account), and a tax type checked for its shape.
DROP FUNCTION IF EXISTS public.rpc_accounting_settings_save(text, text, text, text, text, text, boolean, boolean);
CREATE OR REPLACE FUNCTION public.rpc_accounting_settings_save(
  p_provider text,
  p_payment_account_code text DEFAULT NULL,
  p_line_tax_type text DEFAULT NULL,
  p_sales_account_code text DEFAULT NULL,
  p_default_line_description text DEFAULT NULL,
  p_currency_code text DEFAULT NULL,
  p_auto_push_on_sent boolean DEFAULT NULL,
  p_auto_push_on_paid boolean DEFAULT NULL,
  p_card_payment_account_code text DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp
AS $fn$
BEGIN
  -- 777: `profiles.id` IS NOT `auth.uid()` - the row carries its own id and an
  -- `auth_user_id`. This matched nothing, so it refused EVERY admin.
  IF NOT EXISTS (SELECT 1 FROM public.profiles
                  WHERE id = public.current_profile_id() AND role = 'admin') THEN
    RETURN jsonb_build_object('error', 'admin only');
  END IF;
  -- 1838: as every other change to the firm's settings, with a fresh second
  -- factor (the table's own policies ask the same).
  IF NOT public.mfa_is_fresh() THEN RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501'; END IF;
  IF p_line_tax_type IS NOT NULL AND upper(btrim(p_line_tax_type)) !~ '^[A-Z0-9_]{2,40}$' THEN
    RETURN jsonb_build_object('error', 'That is not a Xero tax type.');
  END IF;
  INSERT INTO public.accounting_settings (
    provider, payment_account_code, line_tax_type, sales_account_code,
    default_line_description, currency_code, auto_push_on_sent, auto_push_on_paid, card_payment_account_code
  ) VALUES (
    p_provider,
    COALESCE(p_payment_account_code, '090'),
    upper(btrim(COALESCE(p_line_tax_type, 'AUTO'))),
    COALESCE(p_sales_account_code, '200'),
    COALESCE(p_default_line_description, 'Security Assessment Services'),
    p_currency_code,
    COALESCE(p_auto_push_on_sent, true),
    COALESCE(p_auto_push_on_paid, true),
    NULLIF(btrim(COALESCE(p_card_payment_account_code, '')), '')
  ) ON CONFLICT (provider) DO UPDATE SET
    payment_account_code     = COALESCE(p_payment_account_code,     accounting_settings.payment_account_code),
    line_tax_type            = COALESCE(upper(btrim(p_line_tax_type)), accounting_settings.line_tax_type),
    card_payment_account_code = CASE WHEN p_card_payment_account_code IS NULL THEN accounting_settings.card_payment_account_code
                                     ELSE NULLIF(btrim(p_card_payment_account_code), '') END,
    sales_account_code       = COALESCE(p_sales_account_code,       accounting_settings.sales_account_code),
    default_line_description = COALESCE(p_default_line_description, accounting_settings.default_line_description),
    currency_code            = COALESCE(p_currency_code,            accounting_settings.currency_code),
    auto_push_on_sent        = COALESCE(p_auto_push_on_sent,        accounting_settings.auto_push_on_sent),
    auto_push_on_paid        = COALESCE(p_auto_push_on_paid,        accounting_settings.auto_push_on_paid),
    updated_at = now();
  RETURN jsonb_build_object('success', true);
END;
$fn$;
REVOKE ALL ON FUNCTION public.rpc_accounting_settings_save(text, text, text, text, text, text, boolean, boolean, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_accounting_settings_save(text, text, text, text, text, text, boolean, boolean, text) TO authenticated;

-- ━━ byo-accounting-export-rpcs.sql ━━
-- ─────────────────────────────────────────────────────────────────────
-- Accounting integrations: BYO export RPCs (chunk 4 / downgrade support)
-- ─────────────────────────────────────────────────────────────────────
-- Generates rpc_export_<table> functions for the accounting tables so
-- they're included in the BYO→master downgrade flow (byo-migration.js
-- → exportTables → callByoExport).
--
-- Follows the same pattern as byo-database-security-patch.sql which
-- generates per-table export RPCs (signed-JWT auth, op-scoped tokens).
--
-- PREREQUISITES:
--   1. byo-add-accounting-integrations.sql (creates the tables)
--   2. byo-database-security-patch.sql (defines _pental_require_auth)
--
-- Idempotent. Safe to run multiple times.

DO $check$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'accounting_connections'
  ) THEN
    RAISE EXCEPTION 'Prerequisite missing: run byo-add-accounting-integrations.sql first.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = '_pental_require_auth'
  ) THEN
    RAISE EXCEPTION 'Prerequisite missing: _pental_require_auth not found. Run byo-database-security-patch.sql first.';
  END IF;
END
$check$;

DO $gen$
DECLARE
  -- ONLY the tables that should be exported during downgrade. Notes:
  --   - invoice_external_links and client_external_links: yes, so the
  --     Xero ID mappings survive the move and future pushes update
  --     instead of duplicating
  --   - accounting_settings: yes, config follows the tenant
  --   - accounting_sync_log: yes, audit history
  --   - accounting_connections: NO, refresh tokens rotate per use; the
  --     user must reconnect after the move
  --   - accounting_sync_queue: NO, transient state
  v_tbls text[] := ARRAY[
    'invoice_external_links', 'client_external_links',
    'accounting_settings', 'accounting_sync_log'
  ];
  v_tbl text;
  v_sql text;
BEGIN
  FOREACH v_tbl IN ARRAY v_tbls LOOP
    v_sql := format($f$
      DROP FUNCTION IF EXISTS public.rpc_export_%1$I(text);
      DROP FUNCTION IF EXISTS public.rpc_export_%1$I(text, jsonb);
      CREATE OR REPLACE FUNCTION public.rpc_export_%1$I(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
      RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $body$
      BEGIN
        PERFORM public._pental_require_auth(p_auth, p_secret, 'rpc_export_%1$s');
        RETURN COALESCE((SELECT jsonb_agg(row_to_json(t)) FROM (SELECT * FROM public.%1$I) t), '[]'::jsonb);
      END;
      $body$;
      GRANT EXECUTE ON FUNCTION public.rpc_export_%1$I(text, jsonb) TO anon, authenticated, service_role;
    $f$, v_tbl);
    EXECUTE v_sql;
  END LOOP;
END $gen$;

NOTIFY pgrst, 'reload schema';

-- ═══════════════════════════════════════════════════════════════════════════
-- SECURITY HARDENING, single-mode BYO (final block; overrides everything above)
--
-- WHY THIS BLOCK EXISTS
--   Pental is now single-mode BYO: every tenant, on every plan, runs the
--   portal on their own database. There is NO Pental-hosted multi-tenant
--   database and therefore NO master↔BYO data transfer. The family of
--   "migration" RPCs (bulk import/auth/key-move and the per-table exports)
--   existed only to move data between the two databases. They are now dead
--   code AND an attack surface, so they are dropped below. (rpc_set_bridge_-
--   password is NOT in that set, despite historical migration use it is the
--   live login bridge and is already hardened to signed-envelope-only; it
--   stays. See its note in the drop section.) Each dropped RPC authenticated
--   with provision_secret, which the Pental application (Vercel) holds, a
--   provision_secret-gated read/write door into the tenant's data, exactly
--   what a Vercel compromise must NOT have.
--
--   This block runs LAST in byo-setup.sql, so a freshly-provisioned tenant
--   database is born hardened: the migration RPCs never exist, and the few
--   sensitive-read RPCs that remain require signed auth (a cosigner-signed
--   JWT whose second key lives in a separate Supabase project Vercel cannot
--   reach) or a real user session, never provision_secret alone.
--
-- WHAT THE THREAT MODEL BECOMES
--   A Vercel compromise (provision_secret + HMAC/sig_a) can still:
--     • tweak branding via the narrow cosmetic RPC (visible to the customer)
--     • reset ONE customer's MFA via the operator RPC (audited + email-notified)
--     • destroy the database via rpc_bulk_clean (destructive, detectable)
--   …but it can NO LONGER read a single client, finding, report, credential,
--   or SMTP password. There is no RPC that returns tenant data or secrets to
--   a provision_secret-only caller.
--
-- NOTE ON ENCRYPTION-AT-REST
--   Secret settings (smtp_pass, stripe/ai/teams/zoom/slack keys) and
--   assessment credentials are pgp_sym_encrypt'd in *_enc columns. That
--   protects raw disk/backup theft, but the symmetric key lives in
--   _encryption_keys in the SAME database, so it is NOT a defence against an
--   actor who can execute a decrypting RPC. Bulk portal data (clients,
--   findings, reports) is plaintext by necessity. So the real control is
--   AUTH, "not readable without a session or signed auth", which is what
--   this block enforces.
--
-- provision_secret survives ONLY for genuine first-connect provisioning
-- (rpc_bulk_clean / rpc_install_pental_keys / rpc_bootstrap_admin), which is
-- unavoidable: no user session exists yet when a database is first set up.
--
-- Idempotent. Safe to re-run.
-- ═══════════════════════════════════════════════════════════════════════════

-- 2025092909: this block used to open its own transaction (BEGIN) and close
-- it (COMMIT) further down. It no longer does: every way this file is applied
-- (Supabase's SQL editor, the Pental gateway, the self-hosted kit's updater,
-- pental-apply-schema.sh) runs the WHOLE file as one transaction, and a COMMIT
-- in the middle made everything above it stick even when a later statement
-- failed.

-- ── 1. Harden the sensitive-read RPCs: signed-auth / user-session ONLY ─────
-- _pental_authorise(..., p_require_user_jwt => true) rejects the
-- provision_secret fallback. The signed-JWT path is checked FIRST inside
-- _pental_authorise, so legitimate signed server callers (auth-code.js,
-- ai.js, create-meeting.js, all send a cosigner-signed p_auth) are
-- unaffected. Only a provision_secret-only caller (i.e. a Vercel breach) is
-- refused.

-- rpc_get_smtp_config, returns smtp_pass in plaintext
DROP FUNCTION IF EXISTS public.rpc_get_smtp_config(text);
DROP FUNCTION IF EXISTS public.rpc_get_smtp_config(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_get_smtp_config(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_s RECORD;
BEGIN
  IF public._pental_authorise(p_auth, p_secret, 'rpc_get_smtp_config', true) IS NULL THEN
    RAISE EXCEPTION 'Unauthorised: signed auth required';
  END IF;
  SELECT smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from_name, smtp_from_email,
         company_name, email_enabled, email_templates, accent_color, company_email,
         -- 1363: the connection travels with the rest. Five definitions of
         -- this function live in this file and Postgres keeps the last; making
         -- them agree means re-running the setup cannot change whether a
         -- connected mailbox is visible to the mailer.
         smtp_oauth_provider, smtp_oauth_user, smtp_oauth_refresh, smtp_oauth_refresh_enc
    INTO v_s FROM public.settings LIMIT 1;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  RETURN jsonb_build_object(
    'smtp_host', v_s.smtp_host, 'smtp_port', v_s.smtp_port, 'smtp_user', v_s.smtp_user,
    'smtp_pass', v_s.smtp_pass, 'smtp_from_name', v_s.smtp_from_name,
    'smtp_from_email', v_s.smtp_from_email, 'company_name', v_s.company_name,
    'email_enabled', v_s.email_enabled, 'email_templates', v_s.email_templates,
    'accent_color', v_s.accent_color, 'company_email', v_s.company_email,
    'smtp_oauth_provider', v_s.smtp_oauth_provider,
    'smtp_oauth_user', v_s.smtp_oauth_user,
    'smtp_oauth_refresh', COALESCE(NULLIF(v_s.smtp_oauth_refresh, ''), public._settings_decrypt(v_s.smtp_oauth_refresh_enc))
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_get_smtp_config(text, jsonb) TO anon, authenticated, service_role;

-- rpc_profile_lookup, profile PII
DROP FUNCTION IF EXISTS public.rpc_profile_lookup(text, text);
DROP FUNCTION IF EXISTS public.rpc_profile_lookup(text, text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_profile_lookup(p_email text, p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_row RECORD;
BEGIN
  IF public._pental_authorise(p_auth, p_secret, 'rpc_profile_lookup', true) IS DISTINCT FROM 'signed' THEN
    RAISE EXCEPTION 'Unauthorised: signed auth required';
  END IF;
  -- 1839: only Pental's sign-in routes ask who has an account; refused once
  -- this database signs people in itself.
  IF public._signin_refuse_pental('rpc_profile_lookup') THEN RETURN jsonb_build_object('found', false, 'refused', 'signin_local'); END IF;
  SELECT id, name, role, active, email INTO v_row FROM public.profiles WHERE lower(email) = lower(p_email) AND active = true LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'id', v_row.id, 'name', v_row.name, 'email', v_row.email);
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_profile_lookup(text, text, jsonb) TO anon, authenticated, service_role;

-- rpc_get_admin_email, admin PII
DROP FUNCTION IF EXISTS public.rpc_get_admin_email(text);
DROP FUNCTION IF EXISTS public.rpc_get_admin_email(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_get_admin_email(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_email text;
BEGIN
  IF public._pental_authorise(p_auth, p_secret, 'rpc_get_admin_email', true) IS DISTINCT FROM 'signed' THEN
    RAISE EXCEPTION 'Unauthorised: signed auth required';
  END IF;
  SELECT email INTO v_email FROM public.profiles WHERE role = 'admin' AND active = true ORDER BY created_at ASC LIMIT 1;
  RETURN v_email;
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_get_admin_email(text, jsonb) TO anon, authenticated, service_role;

-- ── 2. Drop the entire migration RPC surface ───────────────────────────────
-- Bulk write / auth / key-move (master→BYO transfer only, no longer exists).
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text) CASCADE;
DROP FUNCTION IF EXISTS public.rpc_bulk_import(text, jsonb, text, jsonb) CASCADE;
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text) CASCADE;
DROP FUNCTION IF EXISTS public.rpc_bulk_auth(jsonb, text, jsonb) CASCADE;
DROP FUNCTION IF EXISTS public.rpc_bulk_import_keys(text, jsonb, text) CASCADE;
DROP FUNCTION IF EXISTS public.rpc_bulk_import_keys(text, jsonb, text, jsonb) CASCADE;
-- NOTE: rpc_set_bridge_password is deliberately NOT dropped. Despite its
-- historical use during master→BYO migration, it is the LIVE login bridge:
-- after a login code is verified, the portal calls it (with a cosigner-signed
-- envelope, it already rejects provision_secret) to set the GoTrue password,
-- then does a password grant to mint the user's session. Dropping it breaks
-- all login-code sign-ins. It is correctly hardened (signed-envelope only),
-- so it stays.

-- Full-table export RPCs (portal-data + accounting tables). Provision_secret-
-- or signed-gated full-table reads have no place once migration is gone: the
-- portal renders data through the ordinary RLS-scoped user session, and the
-- "export my data" path can be reintroduced later behind a user session if
-- required. Drop every generated variant.
DO $drop_exports$
DECLARE
  v_tbls text[] := ARRAY[
    'settings', 'profiles', 'clients', 'assessments', 'findings', 'proposals',
    'invoices', 'kb_entries', 'meetings', 'meeting_attendees',
    'contractor_payments', 'email_notifications', 'feedback', 'tickets',
    'timeline_events', 'assessment_comments', 'assessment_files', 'qa_comments',
    'payment_events', 'login_codes', 'webauthn_credentials',
    -- accounting export tables (generated by the accounting block above)
    'accounting_connections', 'accounting_settings', 'accounting_sync_log',
    'accounting_sync_queue', 'invoice_external_links', 'client_external_links'
  ];
  v_tbl text;
BEGIN
  FOREACH v_tbl IN ARRAY v_tbls LOOP
    EXECUTE format('DROP FUNCTION IF EXISTS public.rpc_export_%I(text) CASCADE', v_tbl);
    EXECUTE format('DROP FUNCTION IF EXISTS public.rpc_export_%I(text, jsonb) CASCADE', v_tbl);
  END LOOP;
END $drop_exports$;

-- Legacy single-shot export, if any residue remains.
DROP FUNCTION IF EXISTS public.rpc_export_all() CASCADE;
DROP FUNCTION IF EXISTS public.rpc_export_all(text) CASCADE;
DROP FUNCTION IF EXISTS public.rpc_export_all(text, jsonb) CASCADE;

-- (end of the hardening block; see the 2025092909 note at its start)

NOTIFY pgrst, 'reload schema';

-- ── Verification (optional; run manually) ──────────────────────────────────
-- With ONLY a provision_secret (no signed p_auth, no user session), where
-- <SECRET> is the tenant's provision secret, each of these must RAISE:
--   SELECT public.rpc_get_smtp_config('<SECRET>');       -- expect: ERROR
--   SELECT public.rpc_read_settings_server('<SECRET>');  -- expect: ERROR
-- And the migration RPCs must no longer exist:
--   SELECT to_regprocedure('public.rpc_bulk_import(text,jsonb,text,jsonb)');   -- NULL
--   SELECT to_regprocedure('public.rpc_export_findings(text,jsonb)');          -- NULL
-- While genuine provisioning RPCs remain:
--   SELECT to_regprocedure('public.rpc_bulk_clean(text,jsonb)');               -- not NULL
--   SELECT to_regprocedure('public.rpc_bootstrap_admin(text,text,jsonb)');     -- not NULL

-- ═══════════════════════════════════════════════════════════════════════════
-- ADMIN SUPPORT RPC, BYO session revoke
--
-- 1810: the passkey wipe that sat here is gone (below): Pental cannot reset or
-- wipe a firm's portal MFA. What remains is the session revoke, which signs
-- everybody out and grants nothing. It authenticates with a cosigner-signed
-- envelope (p_auth), NOT provision_secret.
-- ═══════════════════════════════════════════════════════════════════════════

-- rpc_wipe_byo_webauthn: REMOVED (1810). It let a Pental-signed call delete
-- every passkey in this database, admins' included: Pental resetting a firm's
-- MFA. A firm's own admin resets a person's MFA on the portal's Users screen
-- (rpc_admin_reset_mfa, signed in with fresh MFA); a firm with no admin able to
-- sign in uses public.owner_reset_mfa from its own database console. Dropped
-- on every run, so a database that has it loses it.
DROP FUNCTION IF EXISTS public.rpc_wipe_byo_webauthn(text);
DROP FUNCTION IF EXISTS public.rpc_wipe_byo_webauthn(text, jsonb);

-- rpc_revoke_all_byo_sessions(p_secret, p_auth)
--   → jsonb { tracking_revoked, gotrue_sessions_deleted, gotrue_tokens_deleted }
-- Marks every active user_sessions row revoked (app-level tracking) AND
-- deletes the underlying GoTrue auth.sessions / auth.refresh_tokens so the
-- JWTs actually stop working. Scoped to active portal profiles in this DB.
DROP FUNCTION IF EXISTS public.rpc_revoke_all_byo_sessions(text);
DROP FUNCTION IF EXISTS public.rpc_revoke_all_byo_sessions(text, jsonb);
CREATE OR REPLACE FUNCTION public.rpc_revoke_all_byo_sessions(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_tracking integer := 0;
  v_gt_sessions integer := 0;
  v_gt_tokens integer := 0;
BEGIN
  IF public._pental_authorise(p_auth, p_secret, 'rpc_revoke_all_byo_sessions', true) IS DISTINCT FROM 'signed' THEN
    RAISE EXCEPTION 'Unauthorised: signed auth required';
  END IF;

  -- App-level tracking rows (best-effort; table always present in BYO).
  WITH r AS (
    UPDATE public.user_sessions
       SET revoked_at = now()
     WHERE revoked_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_tracking FROM r;

  -- GoTrue sessions + refresh tokens for every active portal user in this DB.
  -- auth.sessions.user_id is uuid; auth.refresh_tokens.user_id is text.
  BEGIN
    WITH s AS (
      DELETE FROM auth.sessions
       WHERE user_id IN (SELECT auth_user_id FROM public.profiles WHERE auth_user_id IS NOT NULL)
      RETURNING 1
    )
    SELECT count(*) INTO v_gt_sessions FROM s;
  EXCEPTION WHEN OTHERS THEN v_gt_sessions := 0;
  END;

  BEGIN
    WITH t AS (
      DELETE FROM auth.refresh_tokens
       WHERE user_id IN (SELECT auth_user_id::text FROM public.profiles WHERE auth_user_id IS NOT NULL)
      RETURNING 1
    )
    SELECT count(*) INTO v_gt_tokens FROM t;
  EXCEPTION WHEN OTHERS THEN v_gt_tokens := 0;
  END;

  RETURN jsonb_build_object(
    'tracking_revoked', COALESCE(v_tracking, 0),
    'gotrue_sessions_deleted', COALESCE(v_gt_sessions, 0),
    'gotrue_tokens_deleted', COALESCE(v_gt_tokens, 0)
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.rpc_revoke_all_byo_sessions(text, jsonb) TO anon, authenticated, service_role;

NOTIFY pgrst, 'reload schema';

-- ═══════════════════════════════════════════════════════════════════════════
-- PLAN LIMIT GUARD (defence in depth for BYO)
--
-- Because each tenant owns their database, the app-side plan limit checks can
-- be bypassed by inserting rows directly (SQL editor, PostgREST, service-role
-- key). This guard adds a DB-side backstop: BEFORE INSERT triggers on the two
-- limited tables that count existing rows and reject inserts over the plan
-- limit. Master pushes the plan's limits into settings on setup and on every
-- plan change (rpc_update_settings_branding allowlist includes these keys).
--
-- Honest scope: a determined tenant with the service-role key can still ALTER
-- the settings limits or DROP these triggers, because they are root on their
-- own database. This is not fully preventable in a BYO model. What this DOES
-- stop is casual bypass through the normal app path, the API, or the Supabase
-- table editor, and it keeps honest tenants honest. It also makes tampering
-- visible: if the triggers are gone when master audits, that is a signal.
--
-- Fails OPEN: when the limit columns are NULL (not yet pushed, or unlimited /
-- Enterprise), the triggers allow everything. So this can never wrongly block
-- a tenant whose limits master hasn't populated.
-- ═══════════════════════════════════════════════════════════════════════════

ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS plan_max_users integer;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS plan_max_clients integer;

-- THE CAPS ARE NOT THE TENANT'S TO EDIT (804). [stated] Arian: "if it is the
-- case of one change in the database and unlimited limits and they can use it
-- as normal then no something has to be done."
--
-- It was exactly that case, and WORSE than he feared: `settings_admin_update`
-- lets an admin update ANY column on `settings`, so raising your own limit did
-- not need database access at all. One authenticated request with
-- `plan_max_users = null` and the seat cap was gone.
--
-- This trigger refuses any change to the two cap columns unless the caller
-- holds the provisioning secret - which is what the platform signs its pushes
-- with and what a customer does not have. So the caps can still be written by
-- `pushByoSettings` on a plan change and by the backfill, and by nothing else
-- reachable from a browser.
--
-- **THIS IS NOT UNBREAKABLE AND CANNOT BE.** A tenant with the service key can
-- `ALTER TABLE ... DISABLE TRIGGER`, or drop it. What it removes is the
-- one-request bypass: going over now takes a deliberate act against your own
-- database, with the trigger definition sitting there saying what it is for.
CREATE OR REPLACE FUNCTION public._guard_plan_limits()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $planguard$
BEGIN
  IF NEW.plan_max_users IS DISTINCT FROM OLD.plan_max_users
     OR NEW.plan_max_clients IS DISTINCT FROM OLD.plan_max_clients THEN
    -- `_pental_in_signed_update` is set by the signed-settings path for the
    -- duration of its own statement. Anything else - the portal, PostgREST, a
    -- psql session as `authenticated` - has it unset and is refused.
    IF COALESCE(current_setting('pental.signed_update', true), '') <> '1' THEN
      RAISE EXCEPTION 'Plan limits are set by your subscription and cannot be changed here'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN NEW;
END;
$planguard$;

DROP TRIGGER IF EXISTS tr_guard_plan_limits ON public.settings;
CREATE TRIGGER tr_guard_plan_limits
  BEFORE UPDATE ON public.settings
  FOR EACH ROW EXECUTE FUNCTION public._guard_plan_limits();

-- WHO PAYS, RECORDED IN THE TENANT (570). Written only by the API, and only
-- after the master database has confirmed that the caller's email owns THIS
-- tenant, which is the same check the subscription screen already makes. It
-- is deliberately in `settings` beside the other values pushed down from
-- master rather than a flag on `profiles`: a profile column would be one an
-- admin could set on themselves, and this is the value that decides who may
-- remove an admin. See `_pental_account_owner()`.
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS account_owner_id uuid;

-- Internal-user cap. Counts profiles whose role is not 'client' (matches the
-- app: admin/senior/standard/sales/marketing/contractor all consume a seat).
-- 1975: the cap is the testers the firm pays for, and the refusal says so in
-- testers, as the portal says it. [stated] Arian, of its "Plan user limit
-- reached": "fix all". `pentalportal/api/admin.js` passes the sentence on.
CREATE OR REPLACE FUNCTION public._enforce_user_limit()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE
  v_max integer;
  v_count integer;
BEGIN
  IF NEW.role = 'client' THEN RETURN NEW; END IF;      -- clients are not seats
  SELECT plan_max_users INTO v_max FROM public.settings LIMIT 1;
  IF v_max IS NULL THEN RETURN NEW; END IF;            -- unlimited / not set
  SELECT count(*) INTO v_count FROM public.profiles WHERE role <> 'client';
  IF v_count >= v_max THEN
    RAISE EXCEPTION '%', CASE WHEN v_max = 1 THEN 'Your subscription is for 1 tester, already in use.'
                              ELSE 'Your subscription is for ' || v_max || ' testers, all in use.' END
                         || ' Add a tester at pental.io/manage first.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_enforce_user_limit ON public.profiles;
CREATE TRIGGER tr_enforce_user_limit
  BEFORE INSERT ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public._enforce_user_limit();

-- A CLIENT LOGIN MADE STAFF TAKES A SEAT TOO (1753). [stated] Arian: "do these,
-- both" (this, raised in 1752). The cap above runs on INSERT only, and an admin
-- can change a profile's role (`update_user_role` on the admin route, or a
-- PATCH on profiles), so turning a client login into staff added a seat past the
-- plan without one new row. Only that change adds a seat: staff to staff and
-- staff to client add none, and are never refused. Its own function, so an older
-- update file that redefines `_enforce_user_limit` cannot take this with it.
CREATE OR REPLACE FUNCTION public._enforce_user_limit_on_role()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $$
DECLARE
  v_max integer;
  v_count integer;
BEGIN
  IF OLD.role IS DISTINCT FROM 'client' OR NEW.role = 'client' THEN RETURN NEW; END IF;
  SELECT plan_max_users INTO v_max FROM public.settings LIMIT 1;
  IF v_max IS NULL THEN RETURN NEW; END IF;            -- unlimited / not set
  -- This row is still a client here, so it is not in the count.
  SELECT count(*) INTO v_count FROM public.profiles WHERE role <> 'client';
  IF v_count >= v_max THEN
    -- 1975: the same sentence as the cap above.
    RAISE EXCEPTION '%', CASE WHEN v_max = 1 THEN 'Your subscription is for 1 tester, already in use.'
                              ELSE 'Your subscription is for ' || v_max || ' testers, all in use.' END
                         || ' Add a tester at pental.io/manage first.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_enforce_user_limit_on_role ON public.profiles;
CREATE TRIGGER tr_enforce_user_limit_on_role
  BEFORE UPDATE OF role ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public._enforce_user_limit_on_role();

-- NO CLIENT CAP (1975). [stated] Arian: "remove client restriction paywalls",
-- then, of the database's own "Plan client limit reached": "fix all". No plan
-- limits a firm's clients, so the database refuses none. `plan_max_clients`
-- stays a column Pental writes (empty now); the trigger that enforced it, and
-- its function, are dropped on every run, so a database that had them loses
-- them.
DROP TRIGGER IF EXISTS tr_enforce_client_limit ON public.clients;
DROP FUNCTION IF EXISTS public._enforce_client_limit();

-- ═══════════════════════════════════════════════════════════════════════════
-- Settings secret encryption at rest (smtp_pass, stripe_secret_key,
-- stripe_webhook_secret, ai_api_key, teams_client_secret)
-- ═══════════════════════════════════════════════════════════════════════════
-- These integration secrets were stored as plaintext in public.settings. They
-- are now encrypted at rest into the matching *_enc bytea columns using the
-- per-database key in _encryption_keys (the same key the pentest-credential
-- encryption already uses; it never leaves the tenant's own database and Pental
-- never holds it).
--
-- The settings table is written by several paths (SECURITY DEFINER RPCs AND
-- direct PostgREST updates from the app, which holds a table-level UPDATE
-- grant). To make encryption transparent regardless of the write path, a
-- BEFORE INSERT OR UPDATE trigger does the work: whenever a plaintext secret
-- column is set to a real value, it encrypts that value into the *_enc column
-- and blanks the plaintext column, so the plaintext is never persisted to
-- disk. Reads go through SECURITY DEFINER RPCs (rpc_get_smtp_config and,
-- from 1832, a read for each feature; the full read is retired in 1841)
-- which decrypt on the way out, so the application API is unchanged.
-- Idempotent.

-- 1839: as the database's owner (SECURITY DEFINER). An administrator saves
-- these from the portal by writing the row as themselves, and as themselves
-- they may not run _settings_encrypt (revoked from authenticated): the
-- encryption failed, the failure was swallowed, and a Stripe key or a mailbox
-- password saved from Settings sat in plain text until setup next ran.
CREATE OR REPLACE FUNCTION public._settings_encrypt_secrets()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public, extensions, pg_catalog, pg_temp
AS $enc$
DECLARE v_enc bytea;
BEGIN
  -- Encryption is best-effort housekeeping and must NEVER block a settings write.
  -- The whole body is wrapped so that a missing *_enc column on an out-of-date
  -- database, an unavailable key, or any other error can never abort the INSERT
  -- or UPDATE (which previously killed the seed row and made every branding/SMTP
  -- save silently fall back to defaults). On any error we simply leave the
  -- plaintext in place; the read side falls back to plaintext, and the value is
  -- encrypted on the next write once the schema and key are consistent.
  BEGIN
    IF NEW.smtp_pass IS NOT NULL AND NEW.smtp_pass <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `smtp_pass` could be ignored in favour of an older value.
      NEW.smtp_pass_enc := NULL;
      v_enc := public._settings_encrypt(NEW.smtp_pass);
      IF v_enc IS NOT NULL THEN NEW.smtp_pass_enc := v_enc; NEW.smtp_pass := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.smtp_pass_enc := NULL; END;
  BEGIN
    IF NEW.smtp_oauth_refresh IS NOT NULL AND NEW.smtp_oauth_refresh <> '' THEN
      -- Clear the old ciphertext FIRST, see the note on smtp_pass above.
      NEW.smtp_oauth_refresh_enc := NULL;
      v_enc := public._settings_encrypt(NEW.smtp_oauth_refresh);
      IF v_enc IS NOT NULL THEN NEW.smtp_oauth_refresh_enc := v_enc; NEW.smtp_oauth_refresh := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.smtp_oauth_refresh_enc := NULL; END;
  BEGIN
    IF NEW.stripe_secret_key IS NOT NULL AND NEW.stripe_secret_key <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `stripe_secret_key` could be ignored in favour of an older value.
      NEW.stripe_secret_key_enc := NULL;
      v_enc := public._settings_encrypt(NEW.stripe_secret_key);
      IF v_enc IS NOT NULL THEN NEW.stripe_secret_key_enc := v_enc; NEW.stripe_secret_key := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.stripe_secret_key_enc := NULL; END;
  BEGIN
    IF NEW.stripe_webhook_secret IS NOT NULL AND NEW.stripe_webhook_secret <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `stripe_webhook_secret` could be ignored in favour of an older value.
      NEW.stripe_webhook_secret_enc := NULL;
      v_enc := public._settings_encrypt(NEW.stripe_webhook_secret);
      IF v_enc IS NOT NULL THEN NEW.stripe_webhook_secret_enc := v_enc; NEW.stripe_webhook_secret := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.stripe_webhook_secret_enc := NULL; END;
  BEGIN
    IF NEW.ai_api_key IS NOT NULL AND NEW.ai_api_key <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `ai_api_key` could be ignored in favour of an older value.
      NEW.ai_api_key_enc := NULL;
      v_enc := public._settings_encrypt(NEW.ai_api_key);
      IF v_enc IS NOT NULL THEN NEW.ai_api_key_enc := v_enc; NEW.ai_api_key := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.ai_api_key_enc := NULL; END;
  BEGIN
    IF NEW.teams_client_secret IS NOT NULL AND NEW.teams_client_secret <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `teams_client_secret` could be ignored in favour of an older value.
      NEW.teams_client_secret_enc := NULL;
      v_enc := public._settings_encrypt(NEW.teams_client_secret);
      IF v_enc IS NOT NULL THEN NEW.teams_client_secret_enc := v_enc; NEW.teams_client_secret := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.teams_client_secret_enc := NULL; END;
  BEGIN
    IF NEW.zoom_client_secret IS NOT NULL AND NEW.zoom_client_secret <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `zoom_client_secret` could be ignored in favour of an older value.
      NEW.zoom_client_secret_enc := NULL;
      v_enc := public._settings_encrypt(NEW.zoom_client_secret);
      IF v_enc IS NOT NULL THEN NEW.zoom_client_secret_enc := v_enc; NEW.zoom_client_secret := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.zoom_client_secret_enc := NULL; END;
  BEGIN
    IF NEW.slack_bot_token IS NOT NULL AND NEW.slack_bot_token <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `slack_bot_token` could be ignored in favour of an older value.
      NEW.slack_bot_token_enc := NULL;
      v_enc := public._settings_encrypt(NEW.slack_bot_token);
      IF v_enc IS NOT NULL THEN NEW.slack_bot_token_enc := v_enc; NEW.slack_bot_token := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.slack_bot_token_enc := NULL; END;
  BEGIN
    IF NEW.google_api_key IS NOT NULL AND NEW.google_api_key <> '' THEN
      -- Clear the old ciphertext FIRST. If encryption then fails, the row holds
      -- plaintext and nothing else, instead of a fresh plaintext sitting beside
      -- a stale ciphertext that the reader prefers. That mismatch is how a
      -- correct key in `google_api_key` could be ignored in favour of an older value.
      NEW.google_api_key_enc := NULL;
      v_enc := public._settings_encrypt(NEW.google_api_key);
      IF v_enc IS NOT NULL THEN NEW.google_api_key_enc := v_enc; NEW.google_api_key := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.google_api_key_enc := NULL; END;
  -- 1522: the two white-label SSO secrets, same shape as the eight above.
  BEGIN
    IF NEW.sso_google_client_secret IS NOT NULL AND NEW.sso_google_client_secret <> '' THEN
      NEW.sso_google_client_secret_enc := NULL;
      v_enc := public._settings_encrypt(NEW.sso_google_client_secret);
      IF v_enc IS NOT NULL THEN NEW.sso_google_client_secret_enc := v_enc; NEW.sso_google_client_secret := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.sso_google_client_secret_enc := NULL; END;
  BEGIN
    IF NEW.sso_ms_client_secret IS NOT NULL AND NEW.sso_ms_client_secret <> '' THEN
      NEW.sso_ms_client_secret_enc := NULL;
      v_enc := public._settings_encrypt(NEW.sso_ms_client_secret);
      IF v_enc IS NOT NULL THEN NEW.sso_ms_client_secret_enc := v_enc; NEW.sso_ms_client_secret := NULL; END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN NEW.sso_ms_client_secret_enc := NULL; END;
  RETURN NEW;
END;
$enc$;

-- Runs LAST among BEFORE triggers (zzz name) so any other normalisation of
-- these columns happens before we encrypt and blank them.
REVOKE ALL ON FUNCTION public._settings_encrypt_secrets() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS zzz_tr_settings_encrypt_secrets ON public.settings;
CREATE TRIGGER zzz_tr_settings_encrypt_secrets
  BEFORE INSERT OR UPDATE ON public.settings
  FOR EACH ROW EXECUTE FUNCTION public._settings_encrypt_secrets();

-- Self-healing secret repair. Runs on EVERY execution of this file, so any
-- tenant database sitting in a bad state is corrected by re-running setup
-- rather than needing a hand-written fix per database. Covers all ELEVEN
-- encrypted columns (nine until 1844 added the two sign-in secrets); the
-- previous backfill covered five, which is how
-- smtp_oauth_refresh, zoom_client_secret, slack_bot_token and google_api_key
-- could stay in plain text indefinitely. Three states are handled:
--   plaintext + ciphertext    the two hold DIFFERENT secrets. The plaintext is
--                             the newer value (it is only left behind when the
--                             encrypt step failed on the most recent write), so
--                             re-writing it makes the trigger discard the stale
--                             ciphertext and encrypt the current value.
--   plaintext only            never encrypted; re-writing encrypts it.
--   ciphertext undecryptable  not recoverable, so it is REPORTED and the secret
--                             has to be re-entered.
-- Each column is repaired in its own block, so one failure cannot skip the
-- rest, and the outcome is reported per database rather than assumed.
DO $secret_repair$
DECLARE
  v_col   text;
  -- 1844: and the two sign-in secrets (1522), which the portal's warning
  -- names and this left as they were.
  v_cols  text[] := ARRAY['smtp_pass','smtp_oauth_refresh','stripe_secret_key',
                          'stripe_webhook_secret','ai_api_key','teams_client_secret',
                          'zoom_client_secret','slack_bot_token','google_api_key',
                          'sso_google_client_secret','sso_ms_client_secret'];
  v_n     integer;
  v_fixed integer := 0;
  v_bad   text[] := ARRAY[]::text[];
BEGIN
  FOREACH v_col IN ARRAY v_cols LOOP
    BEGIN
      EXECUTE format(
        'UPDATE public.settings SET %I = %I WHERE %I IS NOT NULL AND %I <> ''''',
        v_col, v_col, v_col, v_col);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n > 0 THEN
        v_fixed := v_fixed + v_n;
        RAISE NOTICE 'secret repair: % rewritten through the encrypt trigger (% row(s))', v_col, v_n;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'secret repair: % could not be rewritten: %', v_col, SQLERRM;
    END;
  END LOOP;

  -- Verify rather than assume. Plaintext still present after the pass means the
  -- encrypt call itself is failing on this database and that secret is at rest
  -- in the clear, which is a finding, not a warning to scroll past.
  FOREACH v_col IN ARRAY v_cols LOOP
    BEGIN
      EXECUTE format('SELECT count(*) FROM public.settings WHERE %I IS NOT NULL AND %I <> ''''',
                     v_col, v_col) INTO v_n;
      IF v_n > 0 THEN v_bad := v_bad || (v_col || ' STORED IN PLAIN TEXT (' || COALESCE(public._settings_secrets_fault(), 'the encrypt step itself failed') || ')'); END IF;
      EXECUTE format('SELECT count(*) FROM public.settings WHERE %I IS NOT NULL AND public._settings_decrypt(%I) IS NULL',
                     v_col || '_enc', v_col || '_enc') INTO v_n;
      IF v_n > 0 THEN v_bad := v_bad || (v_col || ' CIPHERTEXT WILL NOT DECRYPT, re-enter it'); END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'secret repair: could not verify %: %', v_col, SQLERRM;
    END;
  END LOOP;

  IF array_length(v_bad, 1) IS NULL THEN
    RAISE NOTICE 'secret repair: OK, every configured secret is encrypted (% row(s) rewritten)', v_fixed;
  ELSE
    RAISE WARNING 'secret repair: NEEDS ATTENTION on this database: %', array_to_string(v_bad, '; ');
  END IF;
END
$secret_repair$;

-- Read path: decrypt smtp_pass out of smtp_pass_enc. Rebuilt to prefer the
-- encrypted column, falling back to any plaintext still present (pre-backfill).
--
-- 1841: AND NEITHER SECRET, ONCE THIS PORTAL SENDS ITS OWN EMAIL. [stated]
-- Arian: once the firm's side has sent mail, Pental "cannot read the mailbox
-- password or token" and "cannot send its mail". From then on
-- (_mail_locked) this read gives no password and no refresh token, only
-- whether each is set (smtp_pass_set, smtp_oauth_refresh_set) and mail_locked,
-- and Pental's servers hand what they write to this database to send
-- (rpc_mail_hand). Nothing is decrypted for this read at all.
CREATE OR REPLACE FUNCTION public.rpc_get_smtp_config(
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_s RECORD; v_mode text; v_pass text; v_locked boolean;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_get_smtp_config', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Session required'; END IF;
  SELECT smtp_host, smtp_port, smtp_user, smtp_pass, smtp_pass_enc, smtp_from_name, smtp_from_email,
         company_name, email_enabled, email_templates, accent_color, company_email,
         -- 1363: AND THE CONNECTION. This is the FIFTH definition of this
         -- function in this file and the one Postgres keeps; the first returns
         -- the oauth fields and this one did not, so on every tenant that has
         -- re-run the setup the mailer read a row with no connection in it and
         -- fell through to a password. Every OAuth send path since 1095 was
         -- dead here even once the token was stored.
         smtp_oauth_provider, smtp_oauth_user, smtp_oauth_refresh, smtp_oauth_refresh_enc,
         smtp_oauth_verified_at, notify_reply_to_email,
         -- 1709: what the email kit draws with. The font a firm chose for
         -- email under Branding, and the logo a template's {{logo}} shows.
         logo_url, logo_url_light, email_logo_variant, email_font,
         -- 1832: the security-notice switches, which the server read the
         -- whole settings row (every secret decrypted) to find; and whether
         -- passwords are in use, which the welcome email asks this read for
         -- and which only an earlier definition of it returned.
         notify_new_sign_in, notify_new_device_sign_in, notify_session_revoked,
         notify_mfa_changed, notify_role_changed, notify_user_created,
         password_login_enabled
    INTO v_s FROM public.settings ORDER BY created_at ASC NULLS LAST, id ASC LIMIT 1;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  v_locked := public._mail_locked();
  v_pass := CASE WHEN v_locked THEN NULL ELSE COALESCE(public._settings_decrypt(v_s.smtp_pass_enc), v_s.smtp_pass) END;
  RETURN jsonb_build_object(
    'smtp_host', v_s.smtp_host, 'smtp_port', v_s.smtp_port, 'smtp_user', v_s.smtp_user,
    'smtp_pass', v_pass, 'smtp_from_name', v_s.smtp_from_name,
    'smtp_from_email', v_s.smtp_from_email, 'company_name', v_s.company_name,
    'email_enabled', v_s.email_enabled, 'email_templates', v_s.email_templates,
    'accent_color', v_s.accent_color, 'company_email', v_s.company_email,
    'smtp_oauth_provider', v_s.smtp_oauth_provider,
    'smtp_oauth_user', v_s.smtp_oauth_user,
    -- The trigger moves the token into the _enc column and blanks the
    -- plaintext, so the ciphertext is the one to read.
    'smtp_oauth_refresh', CASE WHEN v_locked THEN NULL
      ELSE COALESCE(NULLIF(v_s.smtp_oauth_refresh, ''), public._settings_decrypt(v_s.smtp_oauth_refresh_enc)) END,
    'mail_locked', v_locked,
    'smtp_pass_set', COALESCE(v_s.smtp_pass, '') <> '' OR v_s.smtp_pass_enc IS NOT NULL,
    'smtp_oauth_refresh_set', COALESCE(v_s.smtp_oauth_refresh, '') <> '' OR v_s.smtp_oauth_refresh_enc IS NOT NULL,
    -- 1402: whether a message from this mailbox was confirmed as ARRIVED.
    'smtp_oauth_verified_at', v_s.smtp_oauth_verified_at,
    'notify_reply_to_email', v_s.notify_reply_to_email,
    'logo_url', v_s.logo_url, 'logo_url_light', v_s.logo_url_light,
    'email_logo_variant', v_s.email_logo_variant, 'email_font', v_s.email_font,
    'notify_new_sign_in', v_s.notify_new_sign_in,
    'notify_new_device_sign_in', v_s.notify_new_device_sign_in,
    'notify_session_revoked', v_s.notify_session_revoked,
    'notify_mfa_changed', v_s.notify_mfa_changed,
    'notify_role_changed', v_s.notify_role_changed,
    'notify_user_created', v_s.notify_user_created,
    'password_login_enabled', COALESCE(v_s.password_login_enabled, false)
  );
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_get_smtp_config(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_get_smtp_config(text, jsonb) TO anon, authenticated, service_role;


-- ═══════════════════════════════════════════════════════════════════════════
-- 1831: THE AI RELAY'S OWN READ.
--
-- rpc_read_settings_server decrypts and returns every secret this database
-- holds, and the AI relay called it on every request to get one key. This
-- returns the AI settings and the AI key alone, so an AI request no longer
-- brings the SMTP password, the Stripe keys or any other secret into Pental's
-- servers. Signed only, like the read it narrows.
--
-- 1841: AND NEVER THE KEY. [stated] Arian: "it's fine it's only my own firm
-- now do all the recommended stuff". A firm's own key is used from this
-- database alone (rpc_ai_submit, 1833), so the relay serves only Pental's
-- own key, to a firm with none of its own. It is told whether a key is saved
-- (has_key) and whether the firm's own endpoint is (has_custom_url), and
-- turns either away; it is given neither the key, the endpoint nor its
-- headers.
-- ═══════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.rpc_read_ai_settings_server(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_row RECORD; v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_read_ai_settings_server', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Session required'; END IF;
  SELECT * INTO v_row FROM public.settings LIMIT 1;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;
  RETURN jsonb_build_object(
    'ai_provider',          v_row.ai_provider,
    'has_key',              v_row.ai_api_key_enc IS NOT NULL OR COALESCE(v_row.ai_api_key, '') <> '',
    'has_custom_url',       COALESCE(btrim(v_row.ai_custom_url), '') <> '',
    'ai_custom_model',      v_row.ai_custom_model,
    'ai_custom_format',     v_row.ai_custom_format,
    'ai_custom_max_tokens', v_row.ai_custom_max_tokens
  );
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_read_ai_settings_server(text, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_read_ai_settings_server(text, jsonb) TO anon, authenticated, service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1832: EVERY SERVER FEATURE READS ITS OWN SETTINGS, AND NOTHING ELSE.
--
-- After 1831 the AI relay read its own; everything else on Pental's servers
-- still called rpc_read_settings_server, which decrypts and returns every
-- secret the firm holds, to use one or two of them: a Teams meeting brought
-- the Stripe keys and the SMTP password with it, a Stripe webhook the AI key.
-- Each feature now has a read of its own, signed as its own operation, so an
-- envelope for one cannot read another's secrets, and each request decrypts
-- only what it uses:
--   rpc_read_teams_settings_server           the Teams app credentials (1843: retired)
--   rpc_read_google_settings_server          the review link and Places key (1843: retired)
-- and rpc_get_smtp_config carries the security-notice switches, which the one
-- remaining use read the whole row for.
-- 1841: the broad read is retired, and so are the two Stripe reads (the
-- secret key, and the webhook secret's state): this database makes every
-- Stripe call itself (1840) and checks Stripe's events itself (1839), so
-- Pental's servers are given nothing of Stripe's. So is the scan read (the
-- AI settings and the key, for a write-up Pental's servers did for a
-- collector or a scanner posting to them): scanning is the firm's own side's
-- alone, collectors and posts included, and so is its write-up.
-- ═══════════════════════════════════════════════════════════════════════════
-- (1841: rpc_read_scan_settings_server is retired, with Pental's old scan path; see the RETIRED IN 1841 section.)

-- 1843: rpc_read_teams_settings_server and rpc_read_google_settings_server are
-- retired: this database makes the Teams and Google calls itself (TEAMS LINKS
-- AND GOOGLE REVIEWS FROM THE FIRM'S OWN SIDE), so Pental's servers are given
-- neither the Teams secret nor the Google key. Dropped there.

-- ═══════════════════════════════════════════════════════════════════════════
-- 1832: IS THIS DATABASE THE FIRM'S? Asked by pental.io before it points a
-- firm's portal at a database at a new address (the dashboard's switch). The
-- switch checked only that the address and publishable key answered, and both
-- are in every portal page, so a firm could point its own portal at another
-- firm's database and have Pental's servers carry its calls there. A database
-- is the firm's when it is bound to that firm, or holds that firm's
-- provisioning secret (a move, a restore and a new address all carry it); a
-- database bound to another firm refuses the signature before this answers.
-- A "no" is raised rather than returned, so the question leaves nothing in a
-- database that is not the asking firm's (its audit row and its spent nonce
-- go back with it): another firm's probes cannot write to its record.
-- ═══════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.rpc_pental_identity(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $pid$
DECLARE v_mode text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_pental_identity', true);
  IF v_mode IS DISTINCT FROM 'signed' THEN RAISE EXCEPTION 'Session required'; END IF;
  IF public._pental_bound_tenant() IS NOT DISTINCT FROM (p_auth->>'tenant_id')::uuid
     OR public._pental_provision_secret_ok(p_secret) THEN
    RETURN jsonb_build_object('yours', true);
  END IF;
  RAISE EXCEPTION 'Not this firm''s database';
END;
$pid$;
REVOKE ALL ON FUNCTION public.rpc_pental_identity(text, jsonb) FROM PUBLIC, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_pental_identity(text, jsonb) TO anon, service_role;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1833: AI FROM THE FIRM'S OWN SIDE.
--
-- [stated] Arian, on "Taking client data off Pental's servers" (Phase 1, AI
-- off Vercel): "if pental were breached, their data shouldnt be readable.
-- pental employees shouldnt be able to read their data", with no extra steps
-- for firms.
--
-- The portal asked Pental's relay (/api/ai) for every request to a hosted
-- model: the relay read the firm's AI key from here with a signed call, and
-- the prompt (finding and report text) passed through it to the provider.
-- Now the portal hands this database the request, shaped as the relay shaped
-- it (api/_ai-kit.js, which the portal carries), and this database adds the
-- key and sends it:
--   - on Supabase (Cloud and the self-hosted kit) with pg_net, which this file
--     enables where it is available;
--   - behind a Pental gateway (a plain Postgres has no way out of its own) by
--     the gateway, from 1.4.0, which takes each request from here and puts the
--     answer back.
-- The portal asks rpc_ai_capability first, and uses Pental's relay only where
-- neither can send: a gateway older than 1.4.0 or stopped, pg_net missing or
-- not answering, or no key of the firm's own. Settings, AI says which. Only a
-- signed-in member of the firm's staff can ask, for themselves, and nothing
-- here answers Pental's signature, so what is asked this way and what comes
-- back never pass through Pental. What this does not cover, yet: the signed
-- settings reads still return the key (the relay, kept as the fallback, and
-- the scan write-ups use them), and the scan write-ups still send finding
-- text through Pental.
--
-- The address is never the asker's: it is the provider's own (Anthropic,
-- OpenAI, Groq) or the endpoint the firm saved in Settings, AI, so the key
-- goes nowhere else. pg_net runs inside Supabase's network, so there an
-- endpoint written as a loopback, private or link-local address, or as a name
-- that only resolves inside a network, is refused; behind a gateway, which
-- sits in the firm's own network, a private endpoint is what a firm may well
-- mean, and only link-local and cloud-metadata addresses are refused. Only the
-- gateway can check where a name resolves as it connects; pg_net cannot, and
-- follows a redirect.
-- ═══════════════════════════════════════════════════════════════════════════
DO $ai_net$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_net')
     AND NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    BEGIN
      IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'extensions') THEN
        CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;
      ELSE
        CREATE EXTENSION IF NOT EXISTS pg_net;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'pg_net is not enabled here (%): the portal asks its AI through Pental until it is', SQLERRM;
    END;
  END IF;
END $ai_net$;

-- One row per request, for as long as it takes and a while after: who asked,
-- how it is being sent, and (behind a gateway) the prompt until it is sent and
-- the answer until it is read. The key is never kept here: it is added as the
-- request leaves. Unlogged, so neither ever reaches the database's write-ahead
-- log, its backups or its replicas. Read and written only by the functions
-- below.
CREATE UNLOGGED TABLE IF NOT EXISTS public._ai_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asked_by uuid,
  kind text NOT NULL,
  sender text NOT NULL,
  net_id bigint,
  state text NOT NULL DEFAULT 'queued',
  after_id text,
  body jsonb,
  status_code integer,
  retry_after text,
  content text,
  error text,
  timed_out boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  polled_at timestamptz,
  claimed_by text,
  finished_at timestamptz,
  read_at timestamptz,
  CONSTRAINT _ai_requests_kind CHECK (kind IN ('chat', 'models')),
  CONSTRAINT _ai_requests_sender CHECK (sender IN ('pg_net', 'gateway')),
  CONSTRAINT _ai_requests_state CHECK (state IN ('queued', 'sending', 'done', 'failed'))
);
-- A table made before these columns were, and before it was unlogged.
ALTER TABLE public._ai_requests ADD COLUMN IF NOT EXISTS polled_at timestamptz;
ALTER TABLE public._ai_requests ADD COLUMN IF NOT EXISTS claimed_by text;
-- 1837: or asked by a collector writing up a run it holds (rpc_collector_ai),
-- which is no person.
ALTER TABLE public._ai_requests ALTER COLUMN asked_by DROP NOT NULL;
ALTER TABLE public._ai_requests ADD COLUMN IF NOT EXISTS scan_run_id uuid;
CREATE INDEX IF NOT EXISTS _ai_requests_run_idx ON public._ai_requests (scan_run_id) WHERE scan_run_id IS NOT NULL;
ALTER TABLE public._ai_requests SET UNLOGGED;
CREATE INDEX IF NOT EXISTS _ai_requests_created_idx ON public._ai_requests (created_at);
CREATE INDEX IF NOT EXISTS _ai_requests_waiting_idx ON public._ai_requests (created_at) WHERE sender = 'gateway' AND state = 'queued';
ALTER TABLE public._ai_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._ai_requests FROM PUBLIC, anon, authenticated;

-- Whether an endpoint address is not to be sent the firm's key from here.
-- The relay's rule (api/_url-guard.js and _public-net.js), for an address as
-- it is written: the sender reads a host written as a number in forms that
-- look like something else here (127.1, 0177.0.0.1, 2130706433), so a number
-- is taken only as a plain dotted quad.
CREATE OR REPLACE FUNCTION public._ai_url_refused(p_url text, p_sender text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $aiu$
DECLARE v_host text; v_ip inet; v_gw boolean := p_sender IS NOT DISTINCT FROM 'gateway';
BEGIN
  -- http or https, a host, no credentials written into the address, and no
  -- spaces or control characters anywhere in it.
  IF p_url IS NULL OR p_url !~* '^https?://[^/?#@[:space:]]+([/?#]|$)' OR p_url ~ '[[:space:][:cntrl:]]' THEN RETURN true; END IF;
  v_host := lower(substring(p_url FROM '^[A-Za-z]+://([^/?#]+)'));
  IF v_host ~ '^\[' THEN v_host := substring(v_host FROM '^\[([^]]+)\]');
  ELSE v_host := regexp_replace(v_host, ':[0-9]*$', '');
  END IF;
  v_host := regexp_replace(COALESCE(v_host, ''), '\.$', '');
  IF v_host = '' OR position('%' IN v_host) > 0 THEN RETURN true; END IF;
  -- A cloud's instance metadata, from anywhere.
  IF v_host IN ('metadata', 'metadata.google.internal', 'metadata.google.com', 'instance-data', 'instance-data.ec2.internal', 'metadata.azure.internal') THEN RETURN true; END IF;
  -- A number: only as a plain dotted quad, each part 0 to 255.
  IF v_host ~ '^(0x[0-9a-f]*|[0-9]+)(\.(0x[0-9a-f]*|[0-9]+))*$' THEN
    IF v_host !~ '^(0|[1-9][0-9]{0,2})(\.(0|[1-9][0-9]{0,2})){3}$' THEN RETURN true; END IF;
    BEGIN v_ip := v_host::inet; EXCEPTION WHEN OTHERS THEN RETURN true; END;
  ELSIF position(':' IN v_host) > 0 THEN
    BEGIN v_ip := v_host::inet; EXCEPTION WHEN OTHERS THEN RETURN true; END;
  END IF;
  IF v_ip IS NOT NULL THEN
    -- Link-local (where clouds keep instance metadata), the metadata services
    -- that live elsewhere, and "this" network, however written.
    IF family(v_ip) = 4 AND (v_ip <<= '169.254.0.0/16'::inet OR v_ip <<= '0.0.0.0/8'::inet OR v_ip = '100.100.100.200'::inet) THEN RETURN true; END IF;
    IF family(v_ip) = 6 AND (v_ip <<= 'fe80::/10'::inet OR v_ip = '::'::inet OR v_ip <<= '::a9fe:0/112'::inet OR v_ip <<= '::ffff:169.254.0.0/112'::inet
        OR v_ip <<= '::ffff:0.0.0.0/104'::inet OR v_ip <<= '64:ff9b::a9fe:0/112'::inet OR v_ip <<= '2002:a9fe::/32'::inet
        OR v_ip = 'fd00:ec2::254'::inet OR v_ip = 'fd20:ce::254'::inet OR v_ip = '::ffff:100.100.100.200'::inet) THEN RETURN true; END IF;
    IF NOT v_gw THEN
      IF family(v_ip) = 4 AND (v_ip <<= '127.0.0.0/8'::inet OR v_ip <<= '10.0.0.0/8'::inet OR v_ip <<= '172.16.0.0/12'::inet
          OR v_ip <<= '192.168.0.0/16'::inet OR v_ip <<= '100.64.0.0/10'::inet OR v_ip <<= '198.18.0.0/15'::inet
          OR v_ip <<= '192.0.0.0/24'::inet OR v_ip <<= '192.0.2.0/24'::inet OR v_ip <<= '198.51.100.0/24'::inet
          OR v_ip <<= '203.0.113.0/24'::inet OR v_ip <<= '224.0.0.0/3'::inet) THEN RETURN true; END IF;
      IF family(v_ip) = 6 AND (v_ip <<= '::/96'::inet OR v_ip <<= 'fc00::/7'::inet OR v_ip <<= '::ffff:0:0/96'::inet OR v_ip <<= 'ff00::/8'::inet
          OR v_ip <<= '64:ff9b::/96'::inet OR v_ip <<= '2002::/16'::inet OR v_ip <<= '2001:db8::/32'::inet) THEN RETURN true; END IF;
    END IF;
    RETURN false;
  END IF;
  -- A name only a network of its own answers. Behind a gateway, in the firm's
  -- own network, it is what a firm may well mean.
  IF NOT v_gw
     AND (v_host = 'localhost' OR v_host LIKE '%.localhost' OR v_host LIKE '%.local' OR v_host LIKE '%.internal'
          OR v_host LIKE '%.lan' OR v_host LIKE '%.home.arpa' OR position('.' IN v_host) = 0) THEN
    RETURN true;
  END IF;
  RETURN false;
END $aiu$;
REVOKE ALL ON FUNCTION public._ai_url_refused(text, text) FROM PUBLIC, anon, authenticated;

-- Where a chat endpoint keeps its list of models: the same API's /models
-- (modelsUrlFrom in api/_ai-kit.js).
CREATE OR REPLACE FUNCTION public._ai_models_url(p_chat text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $aim$
DECLARE v_base text; v_path text;
BEGIN
  v_base := substring(p_chat FROM '^([A-Za-z]+://[^/?#]+)');
  IF v_base IS NULL THEN RETURN NULL; END IF;
  v_path := regexp_replace(COALESCE(substring(p_chat FROM '^[A-Za-z]+://[^/?#]+([^?#]*)'), ''), '/+$', '');
  IF v_path ~* '/chat/completions$' THEN v_path := regexp_replace(v_path, '/chat/completions$', '/models', 'i');
  ELSIF v_path ~* '/messages$' THEN v_path := regexp_replace(v_path, '/messages$', '/models', 'i');
  ELSIF v_path ~* '/v[0-9]+$' THEN v_path := v_path || '/models';
  ELSE v_path := v_path || '/v1/models';
  END IF;
  RETURN v_base || v_path;
END $aim$;
REVOKE ALL ON FUNCTION public._ai_models_url(text) FROM PUBLIC, anon, authenticated;

-- Whether a gateway's AI worker (1.4.0 on) has said in the last 45 seconds
-- that it is there. Each says so every fifteen seconds under a key of its own
-- ('ai_worker:<instance>'), and takes its key away when it stops.
-- With p_worker, whether that one is.
CREATE OR REPLACE FUNCTION public._ai_gateway_alive(p_worker text DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $aiga$
DECLARE v_seen integer;
BEGIN
  IF to_regclass('pental.meta') IS NULL THEN RETURN false; END IF;
  IF p_worker IS NULL THEN
    EXECUTE $q$SELECT 1 FROM pental.meta WHERE key LIKE 'ai\_worker%' AND updated_at > now() - interval '45 seconds' LIMIT 1$q$ INTO v_seen;
  ELSE
    EXECUTE $q$SELECT 1 FROM pental.meta WHERE key = $1 AND updated_at > now() - interval '45 seconds' LIMIT 1$q$ INTO v_seen USING p_worker;
  END IF;
  RETURN v_seen IS NOT NULL;
END $aiga$;
DROP FUNCTION IF EXISTS public._ai_gateway_alive();
REVOKE ALL ON FUNCTION public._ai_gateway_alive(text) FROM PUBLIC, anon, authenticated;

-- How this database sends: 'pg_net' (installed, and its worker serving this
-- database: loaded with the server, which defines its settings, pointed at
-- this database, which Supabase's always is, and running: from pg_net 0.14 its
-- worker names itself in pg_stat_activity, which every role is shown),
-- 'gateway' (a gateway's AI worker is there), or NULL (it cannot, and the
-- portal asks through Pental). A pg_net that left a request with no answer at
-- all in the last fifteen minutes is not counted on until then (an older one
-- does not name its worker).
CREATE OR REPLACE FUNCTION public._ai_sender() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $ais$
DECLARE v_db text; v_ver text[];
BEGIN
  IF to_regprocedure('net.http_post(text,jsonb,jsonb,jsonb,integer)') IS NOT NULL
     AND to_regclass('net._http_response') IS NOT NULL THEN
    v_db := current_setting('pg_net.database_name', true);
    -- An older pg_net names no database: its worker serves postgres.
    IF COALESCE(v_db, '') = '' AND current_setting('pg_net.batch_size', true) IS NOT NULL THEN v_db := 'postgres'; END IF;
    v_ver := regexp_match((SELECT extversion FROM pg_catalog.pg_extension WHERE extname = 'pg_net'), '^(\d+)\.(\d+)');
    IF v_db = current_database()
       AND (v_ver IS NULL OR (v_ver[1]::integer = 0 AND v_ver[2]::integer < 14)
            OR EXISTS (SELECT 1 FROM pg_catalog.pg_stat_activity WHERE application_name LIKE 'pg\_net %' AND datname = current_database()))
       AND NOT EXISTS (SELECT 1 FROM public._ai_requests WHERE sender = 'pg_net' AND error = 'no answer came back' AND finished_at > now() - interval '15 minutes') THEN
      RETURN 'pg_net';
    END IF;
  END IF;
  IF public._ai_gateway_alive() THEN RETURN 'gateway'; END IF;
  RETURN NULL;
END $ais$;
REVOKE ALL ON FUNCTION public._ai_sender() FROM PUBLIC, anon, authenticated;

-- The method, address and headers (the firm's key among them) for one
-- request, as it leaves, and the model the firm chose: { provider, format,
-- method, url, headers, model }, or { code } when it cannot be made (the
-- portal says each as the relay did): ollama (asked from the browser),
-- provider (unknown), no_key, undecryptable, key (a key with a line break in
-- it), url (no custom endpoint saved), blocked (an address not sent to from
-- here). A custom header with a line break in it is left out, as one with a
-- name that is not one is.
CREATE OR REPLACE FUNCTION public._ai_endpoint(p_kind text, p_after text, p_sender text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $aie$
DECLARE v_row record; v_provider text; v_key text; v_url text; v_anth boolean; v_h jsonb; v_custom jsonb; v_kv record;
BEGIN
  SELECT ai_provider, ai_api_key, ai_api_key_enc, ai_custom_url, ai_custom_format, ai_custom_headers, ai_custom_model INTO v_row FROM public.settings LIMIT 1;
  v_provider := lower(COALESCE(NULLIF(btrim(v_row.ai_provider), ''), 'groq'));
  IF v_provider = 'ollama' THEN RETURN jsonb_build_object('code', 'ollama', 'provider', v_provider); END IF;
  IF v_provider NOT IN ('anthropic', 'openai', 'groq', 'custom') THEN RETURN jsonb_build_object('code', 'provider', 'provider', v_provider); END IF;
  v_key := btrim(COALESCE(public._settings_decrypt(v_row.ai_api_key_enc), NULLIF(v_row.ai_api_key, '')), E' \t\r\n');
  IF v_provider <> 'custom' AND COALESCE(v_key, '') = '' THEN
    RETURN jsonb_build_object('code', CASE WHEN v_row.ai_api_key_enc IS NOT NULL THEN 'undecryptable' ELSE 'no_key' END, 'provider', v_provider);
  END IF;
  -- A key with a line break in it would end its header there.
  IF v_key ~ '[[:cntrl:]]' THEN RETURN jsonb_build_object('code', 'key', 'provider', v_provider); END IF;
  v_anth := v_provider = 'anthropic' OR (v_provider = 'custom' AND v_row.ai_custom_format = 'anthropic');
  IF v_provider = 'custom' THEN
    v_url := btrim(COALESCE(v_row.ai_custom_url, ''));
    IF v_url = '' THEN RETURN jsonb_build_object('code', 'url', 'provider', v_provider); END IF;
    IF public._ai_url_refused(v_url, p_sender) THEN RETURN jsonb_build_object('code', 'blocked', 'provider', v_provider); END IF;
    IF p_kind = 'models' THEN
      v_url := public._ai_models_url(v_url);
      IF v_url IS NULL OR public._ai_url_refused(v_url, p_sender) THEN RETURN jsonb_build_object('code', 'blocked', 'provider', v_provider); END IF;
    END IF;
  ELSIF p_kind = 'models' THEN
    v_url := CASE v_provider WHEN 'anthropic' THEN 'https://api.anthropic.com/v1/models?limit=1000'
                             WHEN 'openai' THEN 'https://api.openai.com/v1/models'
                             ELSE 'https://api.groq.com/openai/v1/models' END;
  ELSE
    v_url := CASE v_provider WHEN 'anthropic' THEN 'https://api.anthropic.com/v1/messages'
                             WHEN 'openai' THEN 'https://api.openai.com/v1/chat/completions'
                             ELSE 'https://api.groq.com/openai/v1/chat/completions' END;
  END IF;
  -- Claude's list comes a page at a time; the caller checked the id's shape.
  IF p_kind = 'models' AND p_after IS NOT NULL THEN
    v_url := v_url || CASE WHEN position('?' IN v_url) > 0 THEN '&' ELSE '?' END || 'after_id=' || p_after;
  END IF;
  v_h := CASE WHEN p_kind = 'chat' THEN '{"Content-Type": "application/json"}'::jsonb ELSE '{}'::jsonb END;
  IF v_anth THEN v_h := v_h || '{"anthropic-version": "2023-06-01"}'::jsonb; END IF;
  IF v_provider = 'anthropic' THEN v_h := v_h || jsonb_build_object('x-api-key', v_key);
  ELSIF COALESCE(v_key, '') <> '' THEN v_h := v_h || jsonb_build_object('Authorization', 'Bearer ' || v_key);
  END IF;
  -- A custom endpoint's own headers (Settings, AI), as the relay sent them.
  IF v_provider = 'custom' AND COALESCE(btrim(v_row.ai_custom_headers), '') <> '' THEN
    BEGIN v_custom := v_row.ai_custom_headers::jsonb; EXCEPTION WHEN OTHERS THEN v_custom := NULL; END;
    IF v_custom IS NOT NULL AND jsonb_typeof(v_custom) = 'object' THEN
      FOR v_kv IN SELECT e.key, e.value FROM jsonb_each(v_custom) e LOOP
        IF v_kv.key ~ '^[A-Za-z0-9-]+$' AND jsonb_typeof(v_kv.value) = 'string' AND lower(v_kv.key) <> 'content-type'
           AND (v_kv.value #>> '{}') !~ '[[:cntrl:]]' THEN
          v_h := v_h || jsonb_build_object(v_kv.key, v_kv.value #>> '{}');
        END IF;
      END LOOP;
    END IF;
  END IF;
  RETURN jsonb_build_object('provider', v_provider, 'format', CASE WHEN v_anth THEN 'anthropic' ELSE 'openai' END,
                            'method', CASE WHEN p_kind = 'models' THEN 'GET' ELSE 'POST' END, 'url', v_url, 'headers', v_h,
                            'model', NULLIF(btrim(COALESCE(v_row.ai_custom_model, '')), ''));
END $aie$;
REVOKE ALL ON FUNCTION public._ai_endpoint(text, text, text) FROM PUBLIC, anon, authenticated;

-- What is kept goes after half an hour: a request's record, and pg_net's
-- copy of an answer nobody read, or of a request it never took (so it is not
-- sent late). Never waiting on pg_net's worker: what it holds is left to it.
CREATE OR REPLACE FUNCTION public._ai_purge() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $aip$
DECLARE v_ids bigint[]; v_from timestamptz; v_to timestamptz;
BEGIN
  WITH gone AS (DELETE FROM public._ai_requests WHERE created_at < now() - interval '30 minutes' RETURNING net_id, created_at)
  SELECT array_agg(net_id) FILTER (WHERE net_id IS NOT NULL), min(created_at) FILTER (WHERE net_id IS NOT NULL), max(created_at) FILTER (WHERE net_id IS NOT NULL)
    INTO v_ids, v_from, v_to FROM gone;
  IF v_ids IS NOT NULL AND to_regclass('net._http_response') IS NOT NULL AND to_regclass('net.http_request_queue') IS NOT NULL THEN
    BEGIN
      -- An answer comes within ten minutes of its request.
      EXECUTE 'DELETE FROM net._http_response WHERE ctid IN (SELECT ctid FROM net._http_response WHERE created >= $2 AND created < $3 AND id = ANY($1) FOR UPDATE SKIP LOCKED)'
        USING v_ids, v_from - interval '1 minute', v_to + interval '11 minutes';
      EXECUTE 'DELETE FROM net.http_request_queue WHERE ctid IN (SELECT ctid FROM net.http_request_queue WHERE id = ANY($1) FOR UPDATE SKIP LOCKED)' USING v_ids;
    EXCEPTION WHEN OTHERS THEN NULL;  -- pg_net's own time to live takes them
    END;
  END IF;
END $aip$;
REVOKE ALL ON FUNCTION public._ai_purge() FROM PUBLIC, anon, authenticated;

-- Whether this database sends the firm's AI requests itself: { local, sender,
-- provider, has_key }. The portal uses Pental's relay where local is false,
-- or where the provider needs a key and the firm has saved none (the relay
-- may hold one of Pental's).
CREATE OR REPLACE FUNCTION public.rpc_ai_capability() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $aic$
DECLARE v_sender text; v_row record;
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() IN ('none', 'client') THEN RETURN jsonb_build_object('local', false); END IF;
  v_sender := public._ai_sender();
  SELECT ai_provider, ai_api_key, ai_api_key_enc INTO v_row FROM public.settings LIMIT 1;
  RETURN jsonb_build_object('local', v_sender IS NOT NULL, 'sender', v_sender,
    'provider', lower(COALESCE(NULLIF(btrim(v_row.ai_provider), ''), 'groq')),
    'has_key', v_row.ai_api_key_enc IS NOT NULL OR COALESCE(v_row.ai_api_key, '') <> '');
END $aic$;
REVOKE ALL ON FUNCTION public.rpc_ai_capability() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_ai_capability() TO authenticated;

-- 1846: THE FIRM'S OWN LIMIT ON AI REQUESTS, IF IT WANTS ONE. [stated] Arian:
-- "No limit on ai requests, but it can be set in settings." Thirty a minute
-- was the relay's, kept when the requests moved here (1833); there is no
-- limit now unless the firm sets one (Settings, AI: ai_requests_per_minute).
-- How many fields Generate all asks at once is set there too
-- (ai_parallel_requests; none set, it goes by the provider).
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS ai_requests_per_minute integer;
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS ai_parallel_requests integer;
DO $ailimits$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'settings_ai_requests_per_minute_check') THEN
    ALTER TABLE public.settings ADD CONSTRAINT settings_ai_requests_per_minute_check
      CHECK (ai_requests_per_minute IS NULL OR ai_requests_per_minute BETWEEN 1 AND 100000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'settings_ai_parallel_requests_check') THEN
    ALTER TABLE public.settings ADD CONSTRAINT settings_ai_parallel_requests_check
      CHECK (ai_parallel_requests IS NULL OR ai_parallel_requests BETWEEN 1 AND 16);
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Pental setup: the AI request limits could not be checked by the table (%)', SQLERRM;
END $ailimits$;

-- Send one request: p_kind 'chat' (p_body, the provider's request body as
-- api/_ai-kit.js shapes it) or 'models' (the provider's list; p_after, the
-- id to list after). { ok: true, id, sender }, or { ok: false, code } where it
-- is not sent: unavailable (nothing here can send it now), rate (the firm's
-- own limit in a minute reached, where it has set one; retry_after),
-- too_large, body (not a request the portal makes), and _ai_endpoint's codes.
-- The model is the one the firm saved, as the relay sent it, whatever the
-- request names.
-- 1837: the work of it, for a person (rpc_ai_submit) or a collector writing
-- up a run it holds (rpc_collector_ai, p_scan_run).
CREATE OR REPLACE FUNCTION public._ai_submit_core(p_kind text, p_body jsonb, p_after text, p_asked_by uuid, p_scan_run uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $aisb$
DECLARE v_sender text; v_ep jsonb; v_id uuid; v_net bigint; v_n integer; v_oldest timestamptz; v_keys text[]; v_text bigint; v_body jsonb := p_body;
  v_limit integer;
BEGIN
  IF p_asked_by IS NULL AND p_scan_run IS NULL THEN RAISE EXCEPTION 'Nobody asked' USING ERRCODE = '42501'; END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('chat', 'models') THEN RAISE EXCEPTION 'Unknown AI request' USING ERRCODE = '22023'; END IF;
  IF p_kind = 'chat' AND (p_body IS NULL OR jsonb_typeof(p_body) <> 'object') THEN RAISE EXCEPTION 'The AI request has no body' USING ERRCODE = '22023'; END IF;
  IF p_after IS NOT NULL AND p_after !~ '^[A-Za-z0-9._:-]{1,200}$' THEN RAISE EXCEPTION 'Not a page of models' USING ERRCODE = '22023'; END IF;
  PERFORM public._ai_purge();
  v_sender := public._ai_sender();
  IF v_sender IS NULL THEN RETURN jsonb_build_object('ok', false, 'code', 'unavailable'); END IF;
  -- 1846: no limit unless the firm has set one (it was thirty a minute, as the
  -- relay allowed). Set, one at a time through the count, so a burst is
  -- counted as it comes; unset, nothing waits on anything.
  SELECT ai_requests_per_minute INTO v_limit FROM public.settings LIMIT 1;
  IF COALESCE(v_limit, 0) > 0 THEN
    PERFORM pg_advisory_xact_lock(hashtext('pental_ai_requests_rate'));
    SELECT count(*), min(created_at) INTO v_n, v_oldest FROM public._ai_requests WHERE created_at > now() - interval '60 seconds';
    IF v_n >= v_limit THEN
      RETURN jsonb_build_object('ok', false, 'code', 'rate', 'limit', v_limit,
        'retry_after', GREATEST(1, ceil(extract(epoch FROM (v_oldest + interval '60 seconds' - now())))::integer));
    END IF;
  END IF;
  -- The relay's limits: 100,000 characters of message and 50,000 of system
  -- prompt, and screenshots up to 3 MB, are well inside this.
  IF p_kind = 'chat' AND pg_column_size(p_body) > 6000000 THEN RETURN jsonb_build_object('ok', false, 'code', 'too_large'); END IF;
  v_ep := public._ai_endpoint(p_kind, p_after, v_sender);
  IF v_ep ? 'code' THEN RETURN (v_ep - 'model') || jsonb_build_object('ok', false); END IF;
  IF p_kind = 'chat' THEN
    -- What the portal sends (api/_ai-kit.js providerRequest), and nothing else:
    -- its fields for the provider's shape, a low effort where there is one,
    -- JSON mode, a temperature from 0 to 1, a reply of up to 32,768 tokens.
    v_keys := CASE WHEN v_ep->>'format' = 'anthropic'
                   THEN ARRAY['model', 'max_tokens', 'system', 'messages', 'output_config', 'temperature']
                   ELSE ARRAY['model', 'messages', 'max_completion_tokens', 'max_tokens', 'reasoning_effort', 'temperature', 'response_format'] END;
    -- (In brackets: PL/pgSQL ends an IF's condition at the first THEN outside
    -- them, and a CASE has THENs of its own.)
    IF (EXISTS (SELECT 1 FROM jsonb_object_keys(p_body) k WHERE k <> ALL (v_keys))
       OR jsonb_typeof(p_body->'model') IS DISTINCT FROM 'string'
       OR jsonb_typeof(p_body->'messages') IS DISTINCT FROM 'array'
       OR (p_body ? 'system' AND jsonb_typeof(p_body->'system') <> 'string')
       OR (p_body ? 'output_config' AND p_body->'output_config' <> '{"effort": "low"}'::jsonb)
       OR (p_body ? 'reasoning_effort' AND p_body->'reasoning_effort' <> '"low"'::jsonb)
       OR (p_body ? 'response_format' AND p_body->'response_format' <> '{"type": "json_object"}'::jsonb)
       OR CASE WHEN jsonb_typeof(p_body->'temperature') = 'number' THEN (p_body->>'temperature')::numeric NOT BETWEEN 0 AND 1 ELSE p_body ? 'temperature' END
       OR CASE WHEN jsonb_typeof(p_body->'max_tokens') = 'number' THEN (p_body->>'max_tokens')::numeric NOT BETWEEN 1 AND 32768 ELSE p_body ? 'max_tokens' END
       OR CASE WHEN jsonb_typeof(p_body->'max_completion_tokens') = 'number' THEN (p_body->>'max_completion_tokens')::numeric NOT BETWEEN 1 AND 32768 ELSE p_body ? 'max_completion_tokens' END) THEN
      RETURN jsonb_build_object('ok', false, 'code', 'body');
    END IF;
    -- The words asked about: the relay's 100,000 characters of message and
    -- 50,000 of system prompt, with room to spare.
    v_text := COALESCE((SELECT sum(length(x #>> '{}')) FROM jsonb_path_query(p_body, 'strict $.** ? (@.type() == "object").text', '{}', true) x WHERE jsonb_typeof(x) = 'string'), 0)
            + COALESCE((SELECT sum(length(x #>> '{}')) FROM jsonb_path_query(p_body, 'strict $.messages[*].content', '{}', true) x WHERE jsonb_typeof(x) = 'string'), 0)
            + CASE WHEN jsonb_typeof(p_body->'system') = 'string' THEN length(p_body->>'system') ELSE 0 END;
    IF v_text > 160000 THEN RETURN jsonb_build_object('ok', false, 'code', 'too_large'); END IF;
    IF v_ep->>'model' IS NOT NULL AND v_body->>'model' IS DISTINCT FROM v_ep->>'model' THEN v_body := jsonb_set(v_body, '{model}', to_jsonb(v_ep->>'model')); END IF;
  END IF;
  -- pg_net takes it as this commits (it wakes at commit); the record is
  -- written once, with pg_net's id for it.
  IF v_sender = 'pg_net' THEN
    IF v_ep->>'method' = 'GET' THEN
      EXECUTE 'SELECT net.http_get(url := $1, headers := $2, timeout_milliseconds := $3)' INTO v_net USING v_ep->>'url', v_ep->'headers', 30000;
    ELSE
      EXECUTE 'SELECT net.http_post(url := $1, body := $2, headers := $3, timeout_milliseconds := $4)' INTO v_net USING v_ep->>'url', v_body, v_ep->'headers', 280000;
    END IF;
    INSERT INTO public._ai_requests (asked_by, scan_run_id, kind, sender, state, after_id, net_id)
      VALUES (p_asked_by, p_scan_run, p_kind, v_sender, 'sending', p_after, v_net)
      RETURNING id INTO v_id;
  ELSE
    INSERT INTO public._ai_requests (asked_by, scan_run_id, kind, sender, state, after_id, body)
      VALUES (p_asked_by, p_scan_run, p_kind, v_sender, 'queued', p_after, v_body)
      RETURNING id INTO v_id;
    PERFORM pg_notify('pental_ai', v_id::text);
  END IF;
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'sender', v_sender);
END $aisb$;
REVOKE ALL ON FUNCTION public._ai_submit_core(text, jsonb, text, uuid, uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_ai_submit(p_kind text, p_body jsonb DEFAULT NULL, p_after text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $aisbw$
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() IN ('none', 'client') THEN
    RAISE EXCEPTION 'AI drafting is not available to this account' USING ERRCODE = '42501';
  END IF;
  RETURN public._ai_submit_core(p_kind, p_body, p_after, auth.uid(), NULL);
END $aisbw$;
REVOKE ALL ON FUNCTION public.rpc_ai_submit(text, jsonb, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_ai_submit(text, jsonb, text) TO authenticated;

-- The answer to a request, to the person who asked it, once: { state:
-- 'pending' }, { state: 'done', status, body, retry_after, timed_out, error }
-- (status and body are the provider's own; error a network failure),
-- { state: 'unsent' } (no gateway was there to take it: taken back, never to
-- be sent, and the portal asks the relay instead), { state: 'busy' } (a
-- gateway too busy to take it in five minutes: not sent), or { state: 'gone' }
-- (not theirs, or read already). The provider's answer is not kept once read.
--
-- pg_net sends what it has taken all together and makes the answers known
-- once the last of them is in, so a request can wait behind another for as
-- long as that one takes (up to 280 seconds), and then take as long itself:
-- ten minutes covers both. Nothing here waits on pg_net's worker. pg_net's
-- answers are indexed by when they came, not by id, so an answer is looked
-- for from when its request was made: a firm whose webhooks fill that table
-- does not make every look a scan of it.
-- 1837: the work of it, for whoever the caller checked asked it.
CREATE OR REPLACE FUNCTION public._ai_result_core(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $airs$
DECLARE v_r public._ai_requests%ROWTYPE; v_status integer; v_content text; v_headers jsonb; v_timed boolean; v_err text; v_found boolean := false; v_ra text;
BEGIN
  SELECT * INTO v_r FROM public._ai_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_r.read_at IS NOT NULL THEN RETURN jsonb_build_object('state', 'gone'); END IF;
  IF v_r.sender = 'pg_net' THEN
    IF v_r.net_id IS NOT NULL AND to_regclass('net._http_response') IS NOT NULL THEN
      EXECUTE 'SELECT true, status_code, content, headers, COALESCE(timed_out, false), error_msg FROM net._http_response WHERE created >= $2 AND id = $1'
        INTO v_found, v_status, v_content, v_headers, v_timed, v_err USING v_r.net_id, v_r.created_at - interval '1 minute';
    END IF;
    IF NOT COALESCE(v_found, false) THEN
      IF v_r.created_at < now() - interval '600 seconds' THEN
        -- Not left to be sent once the person who asked has been told it failed.
        BEGIN
          EXECUTE 'DELETE FROM net.http_request_queue WHERE ctid IN (SELECT ctid FROM net.http_request_queue WHERE id = $1 FOR UPDATE SKIP LOCKED)' USING v_r.net_id;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        UPDATE public._ai_requests SET state = 'failed', read_at = now(), finished_at = now(), error = 'no answer came back' WHERE id = p_id;
        RETURN jsonb_build_object('state', 'done', 'status', NULL, 'timed_out', true, 'error', 'no answer came back');
      END IF;
      RETURN jsonb_build_object('state', 'pending');
    END IF;
    SELECT h.value INTO v_ra FROM jsonb_each_text(COALESCE(v_headers, '{}'::jsonb)) h WHERE lower(h.key) = 'retry-after' LIMIT 1;
    BEGIN
      EXECUTE 'DELETE FROM net._http_response WHERE ctid IN (SELECT ctid FROM net._http_response WHERE created >= $2 AND id = $1 FOR UPDATE SKIP LOCKED)' USING v_r.net_id, v_r.created_at - interval '1 minute';
    EXCEPTION WHEN OTHERS THEN NULL;  -- pg_net's own time to live takes it
    END;
    UPDATE public._ai_requests SET state = CASE WHEN v_err IS NULL OR v_status IS NOT NULL THEN 'done' ELSE 'failed' END,
      finished_at = now(), read_at = now(), body = NULL WHERE id = p_id;
    RETURN jsonb_build_object('state', 'done', 'status', v_status, 'body', v_content, 'retry_after', v_ra,
                              'timed_out', COALESCE(v_timed, false), 'error', CASE WHEN v_status IS NULL THEN v_err END);
  END IF;
  -- Behind a gateway.
  IF v_r.state = 'queued' THEN
    -- Not taken, and no gateway is there to take it (stopped without saying
    -- so): taken back, never to be sent.
    IF v_r.created_at < now() - interval '30 seconds' AND NOT public._ai_gateway_alive() THEN
      UPDATE public._ai_requests SET state = 'failed', read_at = now(), finished_at = now(), body = NULL, error = 'not sent' WHERE id = p_id;
      RETURN jsonb_build_object('state', 'unsent');
    END IF;
    -- A gateway too busy to take it in five minutes: not sent, and said as that.
    IF v_r.created_at < now() - interval '300 seconds' THEN
      UPDATE public._ai_requests SET state = 'failed', read_at = now(), finished_at = now(), body = NULL, error = 'not sent' WHERE id = p_id;
      RETURN jsonb_build_object('state', 'busy');
    END IF;
  END IF;
  -- Being sent by a gateway that has gone (stopped without saying so, or
  -- replaced): no answer will come.
  IF v_r.state = 'sending' AND v_r.claimed_by IS NOT NULL AND NOT public._ai_gateway_alive(v_r.claimed_by) THEN
    UPDATE public._ai_requests SET state = 'failed', read_at = now(), finished_at = now(), body = NULL WHERE id = p_id;
    RETURN jsonb_build_object('state', 'done', 'status', NULL, 'timed_out', false, 'error', 'the gateway stopped while sending it');
  END IF;
  IF v_r.state IN ('queued', 'sending') THEN
    IF v_r.created_at < now() - interval '600 seconds' THEN
      UPDATE public._ai_requests SET state = 'failed', read_at = now(), finished_at = now(), body = NULL WHERE id = p_id;
      RETURN jsonb_build_object('state', 'done', 'status', NULL, 'timed_out', true, 'error', 'no answer came back');
    END IF;
    UPDATE public._ai_requests SET polled_at = now() WHERE id = p_id;
    RETURN jsonb_build_object('state', 'pending');
  END IF;
  UPDATE public._ai_requests SET read_at = now(), content = NULL, body = NULL, error = NULL WHERE id = p_id;
  RETURN jsonb_build_object('state', 'done', 'status', v_r.status_code, 'body', v_r.content, 'retry_after', v_r.retry_after,
                            'timed_out', v_r.timed_out, 'error', CASE WHEN v_r.status_code IS NULL THEN v_r.error END);
END $airs$;
REVOKE ALL ON FUNCTION public._ai_result_core(uuid) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_ai_result(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $airsw$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public._ai_requests WHERE id = p_id AND asked_by = auth.uid()) THEN
    RETURN jsonb_build_object('state', 'gone');
  END IF;
  RETURN public._ai_result_core(p_id);
END $airsw$;
REVOKE ALL ON FUNCTION public.rpc_ai_result(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_ai_result(uuid) TO authenticated;

-- The gateway's half (1.4.0 on), called on its own connection only: the
-- requests waiting for it, each with its address and headers (the key among
-- them) made as it is taken, and the answer put back. Only a request someone
-- is still waiting on is sent: asked after in the last twenty seconds (the
-- portal asks every two), and made in the last five minutes. p_worker, the
-- worker's own key in pental.meta, is kept with each, so a request that worker
-- was sending when it went is said as that.
DROP FUNCTION IF EXISTS public._ai_claim(integer);
CREATE OR REPLACE FUNCTION public._ai_claim(p_limit integer DEFAULT 4, p_worker text DEFAULT NULL)
RETURNS TABLE (r_id uuid, r_method text, r_url text, r_headers jsonb, r_body jsonb, r_timeout_ms integer)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $aicl$
DECLARE v record; v_ep jsonb;
BEGIN
  PERFORM public._ai_purge();
  FOR v IN SELECT q.id, q.kind, q.after_id, q.body FROM public._ai_requests q
            WHERE q.sender = 'gateway' AND q.state = 'queued'
              AND COALESCE(q.polled_at, q.created_at) > now() - interval '20 seconds'
              AND q.created_at > now() - interval '300 seconds'
            ORDER BY q.created_at LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 4), 16))
            FOR UPDATE SKIP LOCKED LOOP
    BEGIN
      v_ep := public._ai_endpoint(v.kind, v.after_id, 'gateway');
    EXCEPTION WHEN OTHERS THEN
      v_ep := jsonb_build_object('code', 'error');
    END;
    IF v_ep ? 'code' THEN
      UPDATE public._ai_requests SET state = 'failed', error = 'the request could not be made (' || (v_ep->>'code') || ')', finished_at = now(), body = NULL
       WHERE public._ai_requests.id = v.id;
      CONTINUE;
    END IF;
    UPDATE public._ai_requests SET state = 'sending', claimed_by = p_worker WHERE public._ai_requests.id = v.id;
    r_id := v.id; r_method := v_ep->>'method'; r_url := v_ep->>'url'; r_headers := v_ep->'headers'; r_body := v.body;
    r_timeout_ms := CASE WHEN v.kind = 'models' THEN 30000 ELSE 280000 END;
    RETURN NEXT;
  END LOOP;
END $aicl$;
REVOKE ALL ON FUNCTION public._ai_claim(integer, text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._ai_complete(p_id uuid, p_status integer, p_content text, p_retry_after text, p_error text, p_timed_out boolean)
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $aico$
  UPDATE public._ai_requests
     SET state = CASE WHEN p_status IS NULL THEN 'failed' ELSE 'done' END,
         status_code = p_status, content = p_content, retry_after = p_retry_after,
         error = p_error, timed_out = COALESCE(p_timed_out, false), finished_at = now(), body = NULL
   WHERE id = p_id AND sender = 'gateway' AND state = 'sending';
$aico$;
REVOKE ALL ON FUNCTION public._ai_complete(uuid, integer, text, text, text, boolean) FROM PUBLIC, anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- PASSWORD SIGN-IN (optional, per-tenant, OFF by default)
-- ═══════════════════════════════════════════════════════════════════════════
-- Lets a firm offer username+password sign-in alongside the default email-code
-- sign-in. MFA is unchanged and still runs AFTER this step, because password
-- sign-in mints exactly the same GoTrue session the code flow does.
--
-- WHERE THE PASSWORD LIVES
-- Hashes are stored in THIS database (the firm's own Supabase project) in
-- public.user_credentials. Nothing about a password ever reaches Pental's
-- database or Pental's servers: the browser talks straight to this project.
--
-- WHY NOT auth.users.encrypted_password
-- The existing email-code flow signs a user in by writing a random one-shot
-- "bridge" password into auth.users.encrypted_password and immediately using
-- it. If real passwords lived there too, every code sign-in would silently
-- destroy the user's password. So real hashes live in their own table and
-- auth.users.encrypted_password stays purely the ephemeral bridge slot.
--
-- HASHING
-- bcrypt via pgcrypto, cost 12, unique per-row salt (gen_salt does this).
-- bcrypt silently truncates at 72 bytes, which would mean two different long
-- passphrases sharing a prefix collide, so the password is SHA-256 pre-hashed
-- to a 64-char hex digest first and bcrypt is applied to that. This is the
-- standard pre-hash construction and keeps NCSC's "do not impose a low length
-- cap" advice compatible with bcrypt.
--
-- POLICY (NCSC guidance)
-- Minimum 12 characters. NO composition rules (no forced upper/lower/digit/
-- symbol), NO forced expiry, NO password hints, NO knowledge-based recovery:
-- NCSC advises all of those actively harm security. Instead the weak-password
-- problem is handled by blocklisting: the most common passwords, anything
-- derived from the user's own email or the company name, and long runs of a
-- repeated or sequential character.

-- ── Setting: off unless the firm turns it on ───────────────────────────────
-- New databases default to password sign-in. Deliberately DEFAULT false on
-- the ALTER as well as here: adding the column to an existing tenant must
-- not silently change how their users sign in. The CREATE TABLE default
-- below is what new installs pick up.
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS password_login_enabled boolean DEFAULT false;

-- ── Credential store ───────────────────────────────────────────────────────
-- One row per profile that has set a password. No row means that user simply
-- cannot sign in with a password, which is also how an admin revokes it.
CREATE TABLE IF NOT EXISTS public.user_credentials (
  profile_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,
  password_hash text NOT NULL,
  password_set_at timestamptz NOT NULL DEFAULT now(),
  -- Throttling state. NCSC advises throttling over hard lockout, because a
  -- hard lockout hands an attacker a denial-of-service against a known user.
  failed_attempts integer NOT NULL DEFAULT 0,
  last_failed_at timestamptz,
  locked_until timestamptz,
  last_login_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- ── Setup / reset tokens ───────────────────────────────────────────────────
-- Only the SHA-256 of the token is stored, so a database read cannot be
-- replayed into an account takeover. Single use, expiring, and re-issuable.
CREATE TABLE IF NOT EXISTS public.password_setup_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  purpose text NOT NULL DEFAULT 'set' CHECK (purpose IN ('set', 'reset')),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_pw_tokens_profile ON public.password_setup_tokens(profile_id);
CREATE INDEX IF NOT EXISTS idx_pw_tokens_expiry ON public.password_setup_tokens(expires_at);

-- ── Common-password blocklist ──────────────────────────────────────────────
-- Seeded with the passwords that dominate real-world breach corpora. These are
-- public knowledge by definition, so storing them in the clear is fine and
-- makes the lookup a plain indexed equality check.
CREATE TABLE IF NOT EXISTS public.common_passwords (
  pw text PRIMARY KEY
);

-- ── Lock the tables down ───────────────────────────────────────────────────
-- No client role may read or write ANY of these directly. Every legitimate
-- operation goes through a SECURITY DEFINER function below, so a password
-- hash, a token hash and the blocklist are all unreachable over PostgREST
-- even with a valid session.
ALTER TABLE public.user_credentials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.password_setup_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.common_passwords ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_credentials FROM anon, authenticated;
REVOKE ALL ON public.password_setup_tokens FROM anon, authenticated;
REVOKE ALL ON public.common_passwords FROM anon, authenticated;

-- ── Internal helpers ───────────────────────────────────────────────────────

-- A common password with padding on it. This is the check that earns its
-- keep: the length floor already refuses "password", so what actually reaches
-- us is "password1234", "P@ssw0rd2025", "qwerty123456!" and "iloveyouiloveyou".
-- Undo the three things people do to make a short favourite long enough, then
-- ask whether what is left is one of those favourites.
--
--   1. leet substitutions            P@ssw0rd -> password
--   2. padding on either end          password1234 / !!password!! -> password
--   3. repeating the whole thing      passwordpassword -> password
--
-- The remainder must equal a base EXACTLY, never merely contain one, so
-- "mastermind2025" and "gloveboxrepair" are not caught by "master" or "love".
CREATE OR REPLACE FUNCTION public._pw_is_padded_common(p_lower text)
RETURNS boolean LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_core text := COALESCE(p_lower, '');
  v_half text;
BEGIN
  IF v_core = '' THEN RETURN false; END IF;

  -- Order matters. Padding comes off FIRST, because the "1234" in
  -- "password1234" would otherwise be read as leet and turn into letters that
  -- can never be stripped again.
  v_core := regexp_replace(v_core, '[0-9]+$', '');        -- trailing year or run
  v_core := regexp_replace(v_core, '[^a-z0-9]+$', '');    -- trailing punctuation
  v_core := regexp_replace(v_core, '[0-9]+$', '');        -- digits behind that punctuation
  -- Leading padding, but @ and $ are kept: they are far more often a leet "a"
  -- or "s" at the start of a word (@dmin, $unshine) than decoration.
  v_core := regexp_replace(v_core, '^[^a-z@$]+', '');

  -- Now undo the character swaps on what is left.
  v_core := translate(v_core, '@$!013457', 'asioleast');
  v_core := replace(replace(v_core, '|', 'l'), '+', 't');
  v_core := regexp_replace(v_core, '[^a-z]', '', 'g');
  IF v_core = '' THEN RETURN false; END IF;

  IF EXISTS (SELECT 1 FROM public.common_password_bases WHERE base = v_core) THEN
    RETURN true;
  END IF;

  -- The whole favourite typed twice to reach the length, which is the other
  -- thing people do: "passwordpassword".
  IF length(v_core) % 2 = 0 THEN
    v_half := left(v_core, length(v_core) / 2);
    IF v_half = right(v_core, length(v_core) / 2)
       AND EXISTS (SELECT 1 FROM public.common_password_bases WHERE base = v_half) THEN
      RETURN true;
    END IF;
  END IF;

  RETURN false;
END;
$$;

-- Pre-hash so bcrypt never sees more than 64 bytes (see header note).
CREATE OR REPLACE FUNCTION public._pw_prehash(p_password text)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT encode(extensions.digest(convert_to(p_password, 'UTF8'), 'sha256'), 'hex');
$$;

CREATE OR REPLACE FUNCTION public._pw_hash(p_password text)
RETURNS text LANGUAGE sql VOLATILE AS $$
  SELECT extensions.crypt(public._pw_prehash(p_password), extensions.gen_salt('bf', 12));
$$;

CREATE OR REPLACE FUNCTION public._pw_verify(p_password text, p_hash text)
RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT p_hash IS NOT NULL
     AND p_hash <> ''
     AND extensions.crypt(public._pw_prehash(p_password), p_hash) = p_hash;
$$;

-- ── Policy check ───────────────────────────────────────────────────────────
-- Returns { ok, reasons[] }. Deliberately returns EVERY failing reason at once
-- so the UI can show a complete checklist rather than making the user discover
-- rules one rejection at a time.
CREATE OR REPLACE FUNCTION public.rpc_password_policy(p_password text, p_email text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_reasons text[] := ARRAY[]::text[];
  v_pw text := COALESCE(p_password, '');
  v_lower text := lower(COALESCE(p_password, ''));
  v_local text;
  v_company text;
BEGIN
  -- NCSC: length is the control that matters. 12 is the floor.
  IF length(v_pw) < 12 THEN
    v_reasons := array_append(v_reasons, 'Must be at least 12 characters long.');
  END IF;
  -- Upper bound exists only to bound hashing work and reject accidental
  -- paste-of-a-file. It is deliberately far above any sensible passphrase.
  IF length(v_pw) > 256 THEN
    v_reasons := array_append(v_reasons, 'Must be 256 characters or fewer.');
  END IF;
  IF v_pw <> btrim(v_pw) THEN
    v_reasons := array_append(v_reasons, 'Cannot start or end with a space.');
  END IF;

  -- Breach-corpus blocklist, checked case-insensitively.
  IF EXISTS (SELECT 1 FROM public.common_passwords WHERE pw = v_lower)
     OR public._pw_is_padded_common(v_lower) THEN
    v_reasons := array_append(v_reasons, 'This is one of the most commonly used passwords. Choose something else.');
  END IF;

  -- Derived from the account's own email address.
  IF p_email IS NOT NULL AND position('@' in p_email) > 1 THEN
    v_local := lower(split_part(p_email, '@', 1));
    IF length(v_local) >= 3 AND position(v_local in v_lower) > 0 THEN
      v_reasons := array_append(v_reasons, 'Cannot contain your email address.');
    END IF;
  END IF;

  -- Derived from the company name.
  SELECT lower(company_name) INTO v_company FROM public.settings
   WHERE company_name IS NOT NULL AND company_name <> '' ORDER BY created_at LIMIT 1;
  IF v_company IS NOT NULL AND length(v_company) >= 4 AND position(v_company in v_lower) > 0 THEN
    v_reasons := array_append(v_reasons, 'Cannot contain the company name.');
  END IF;

  -- A single character repeated, or a straight keyboard/alphabet/number run,
  -- is long but not strong, so length alone must not let it through.
  IF v_lower ~ '^(.)\1+$' THEN
    v_reasons := array_append(v_reasons, 'Cannot be the same character repeated.');
  END IF;
  IF v_lower ~ '(0123456789|abcdefghij|qwertyuiop|asdfghjkl)' THEN
    v_reasons := array_append(v_reasons, 'Cannot contain a long keyboard or number sequence.');
  END IF;

  RETURN jsonb_build_object(
    'ok', cardinality(v_reasons) = 0,
    'reasons', to_jsonb(v_reasons)
  );
END;
$$;

-- ── Issue a setup / reset token ────────────────────────────────────────────
-- Provision-secret gated because the RAW token is returned: only Pental's
-- backend calls this, and only so it can put the token in an email sent
-- through the firm's own SMTP, exactly as login codes are sent today.
--
-- Returns { ok, token, expires_at, name } or { ok: false, reason }. It does
-- NOT reveal whether an address exists to anyone but that trusted caller.
-- Accepts p_auth as well as p_secret because the portal calls this through the
-- signed-envelope pipeline (pentalAuthFields sends p_auth), like every other
-- server-to-server RPC. Without the parameter PostgREST cannot match the
-- signature at all, and the op must ALSO be listed in KNOWN_OPS on both the
-- portal and the website sign modules or no envelope is ever minted, which is
-- exactly the "unknown op" failure this replaces.
DROP FUNCTION IF EXISTS public.rpc_issue_password_token(text, text, text);
CREATE OR REPLACE FUNCTION public.rpc_issue_password_token(
  p_email text,
  p_purpose text DEFAULT 'set',
  p_secret text DEFAULT NULL,
  p_auth jsonb DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_profile RECORD;
  v_token text;
  v_ttl interval;
  v_expires timestamptz;
BEGIN
  -- 1798: signed only. The token it returns sets that account's password, and
  -- the only caller is the portal server (api/auth-code.js), which signs. A
  -- signed-in session or the provisioning secret alone no longer mints one.
  IF public._pental_authorise(p_auth, p_secret, 'rpc_issue_password_token') IS DISTINCT FROM 'signed' THEN
    RAISE EXCEPTION 'Invalid secret';
  END IF;
  -- 1839: refused once this database sends its own password links.
  IF public._signin_refuse_pental('rpc_issue_password_token') THEN RETURN jsonb_build_object('ok', false, 'reason', 'signin_local'); END IF;
  IF p_purpose NOT IN ('set', 'reset') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_purpose');
  END IF;

  SELECT id, email, name, active INTO v_profile
    FROM public.profiles WHERE lower(email) = lower(btrim(p_email)) LIMIT 1;
  IF NOT FOUND OR NOT COALESCE(v_profile.active, true) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_account');
  END IF;

  -- A first-time setup link may sit in an inbox for a while; a reset link is
  -- short-lived because it is a live path to an existing account.
  v_ttl := CASE WHEN p_purpose = 'set' THEN interval '72 hours' ELSE interval '1 hour' END;
  v_expires := now() + v_ttl;

  -- Any earlier unused token for this profile is invalidated, so only the
  -- newest link ever works and a forwarded older email is inert.
  UPDATE public.password_setup_tokens
     SET used_at = now()
   WHERE profile_id = v_profile.id AND used_at IS NULL;

  v_token := encode(extensions.gen_random_bytes(32), 'base64');
  v_token := replace(replace(replace(v_token, '+', '-'), '/', '_'), '=', '');

  INSERT INTO public.password_setup_tokens (profile_id, token_hash, purpose, expires_at)
  VALUES (v_profile.id, encode(extensions.digest(convert_to(v_token, 'UTF8'), 'sha256'), 'hex'), p_purpose, v_expires);

  RETURN jsonb_build_object(
    'ok', true, 'token', v_token, 'expires_at', v_expires,
    'name', COALESCE(v_profile.name, ''), 'email', v_profile.email, 'purpose', p_purpose
  );
END;
$$;

-- ── Redeem a token and set the password ────────────────────────────────────
-- anon-callable: the user is by definition not signed in yet. Security rests
-- on the token being 256 bits of CSPRNG output, stored only as a hash, single
-- use and time limited.
CREATE OR REPLACE FUNCTION public.rpc_set_password_with_token(p_token text, p_password text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_hash text;
  v_tok RECORD;
  v_profile RECORD;
  v_policy jsonb;
BEGIN
  IF p_token IS NULL OR length(p_token) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_token');
  END IF;
  v_hash := encode(extensions.digest(convert_to(p_token, 'UTF8'), 'sha256'), 'hex');

  SELECT * INTO v_tok FROM public.password_setup_tokens
   WHERE token_hash = v_hash LIMIT 1;
  IF NOT FOUND OR v_tok.used_at IS NOT NULL OR v_tok.expires_at < now() THEN
    -- One undifferentiated answer for unknown, used and expired, so the link
    -- cannot be used to probe which of those it was.
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_token');
  END IF;

  SELECT id, email, active INTO v_profile FROM public.profiles WHERE id = v_tok.profile_id;
  IF NOT FOUND OR NOT COALESCE(v_profile.active, true) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_token');
  END IF;

  v_policy := public.rpc_password_policy(p_password, v_profile.email);
  IF NOT (v_policy->>'ok')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'policy', 'reasons', v_policy->'reasons');
  END IF;

  INSERT INTO public.user_credentials (profile_id, password_hash, password_set_at, updated_at)
  VALUES (v_profile.id, public._pw_hash(p_password), now(), now())
  ON CONFLICT (profile_id) DO UPDATE
    SET password_hash = EXCLUDED.password_hash,
        password_set_at = now(),
        updated_at = now(),
        -- Setting a new password clears any throttle: the legitimate owner
        -- has just proven control of the mailbox.
        failed_attempts = 0, last_failed_at = NULL, locked_until = NULL;

  UPDATE public.password_setup_tokens SET used_at = now() WHERE id = v_tok.id;
  -- 1839: a link this database sent, used: its own side is proven.
  IF COALESCE(v_tok.issued_here, false) THEN
    BEGIN
      PERFORM public._signin_note_local('link');
    EXCEPTION WHEN undefined_function THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object('ok', true, 'email', v_profile.email);
END;
$$;

-- ── Password sign-in ───────────────────────────────────────────────────────
-- anon-callable. Verifies the password inside the database, and on success
-- mints a single-use bridge password in auth.users and returns it so the
-- browser can complete a normal GoTrue sign-in against THIS project. That is
-- the same mechanism the email-code flow already uses; the difference is only
-- what was proven first. The plaintext password is never stored, never
-- logged, and never leaves this database.
--
-- Throttling is per account with escalating delay rather than a hard lockout,
-- per NCSC, so an attacker cannot trivially lock a known user out.
-- ── Login throttle, keyed by EMAIL not by account ──────────────────────────
-- Deliberately not keyed on user_credentials. If only real accounts could be
-- throttled, an attacker could tell a real address from a fake one purely by
-- whether hammering it ever produced a "too many attempts" answer. Keying on a
-- hash of the submitted address means unknown addresses throttle identically,
-- and hashing means this table never becomes a readable list of the addresses
-- people have typed at the login form.
CREATE TABLE IF NOT EXISTS public.password_login_throttle (
  email_key text PRIMARY KEY,
  failed_attempts integer NOT NULL DEFAULT 0,
  last_failed_at timestamptz,
  locked_until timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_pw_throttle_recent
  ON public.password_login_throttle(last_failed_at);

-- Password setup/reset EMAIL requests, counted in this tenant's OWN database.
-- It previously used the shared master-side limiter, which is the wrong place
-- for a BYO tenant: their throttle state belongs with their data, and it must
-- keep working whether or not the master is reachable. Only a hash of the
-- address is stored, so the table is not a list of who has been asking.
CREATE TABLE IF NOT EXISTS public.password_email_requests (
  id bigserial PRIMARY KEY,
  email_key text NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_pw_email_req ON public.password_email_requests(email_key, requested_at);
ALTER TABLE public.password_email_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.password_email_requests FROM anon, authenticated;

-- Records the request AND answers whether it is over the ceiling, in one call,
-- so the count can never be read without also being written (which is exactly
-- how the previous version counted nothing at all).
CREATE OR REPLACE FUNCTION public.rpc_pw_email_throttle(
  p_email text, p_max integer DEFAULT 5, p_window_mins integer DEFAULT 15,
  p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_key text;
  v_since timestamptz;
  v_count integer;
  v_mode text;
BEGIN
  -- 1798: this called a two-argument _pental_authorise that does not exist, so
  -- every call raised, the caller fell open, and the password-email limit never
  -- applied. The portal server calls it signed with the provisioning secret
  -- beside it; either is accepted, a signed-in session is not.
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_pw_email_throttle');
  IF v_mode IS NULL OR v_mode = 'user_jwt' THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  IF public._signin_refuse_pental('rpc_pw_email_throttle') THEN RETURN jsonb_build_object('allowed', false, 'refused', 'signin_local'); END IF;  -- 1839
  v_key := encode(extensions.digest(convert_to(lower(btrim(COALESCE(p_email, ''))), 'UTF8'), 'sha256'), 'hex');
  v_since := now() - make_interval(mins => GREATEST(1, COALESCE(p_window_mins, 15)));
  DELETE FROM public.password_email_requests WHERE requested_at < now() - interval '24 hours';
  INSERT INTO public.password_email_requests (email_key) VALUES (v_key);
  SELECT count(*) INTO v_count FROM public.password_email_requests
   WHERE email_key = v_key AND requested_at >= v_since;
  RETURN jsonb_build_object('allowed', COALESCE(v_count, 0) <= GREATEST(1, COALESCE(p_max, 5)), 'hits', COALESCE(v_count, 0));
END;
$$;
DO $g$ BEGIN
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.rpc_pw_email_throttle(text, integer, integer, text, jsonb) TO anon, authenticated, service_role';
EXCEPTION WHEN undefined_function THEN NULL; END $g$;
ALTER TABLE public.password_login_throttle ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.password_login_throttle FROM anon, authenticated;

-- A real bcrypt hash of a fixed string, used as the verification target when
-- no account or no credential exists, so that a failed attempt performs the
-- SAME cost-12 bcrypt work as a real one. Without this, an unknown address
-- returns in microseconds while a real one takes a quarter of a second, which
-- is a reliable account-enumeration oracle regardless of what the response
-- body says.
CREATE TABLE IF NOT EXISTS public._pw_dummy (h text NOT NULL);
INSERT INTO public._pw_dummy (h)
  SELECT extensions.crypt('pental-constant-time-verify-target', extensions.gen_salt('bf', 12))
   WHERE NOT EXISTS (SELECT 1 FROM public._pw_dummy);
ALTER TABLE public._pw_dummy ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._pw_dummy FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_password_login(p_email text, p_password text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_enabled boolean;
  v_profile RECORD;
  v_hash text;
  v_bridge text;
  v_delay interval;
  v_key text;
  v_thr RECORD;
  v_target text;
  v_ok boolean;
  v_spray integer;
  v_email text := lower(btrim(COALESCE(p_email, '')));
BEGIN
  SELECT COALESCE(password_login_enabled, false) INTO v_enabled
    FROM public.settings ORDER BY created_at LIMIT 1;
  IF NOT COALESCE(v_enabled, false) THEN
    -- Not account-specific, so this discloses nothing about any address.
    RETURN jsonb_build_object('ok', false, 'reason', 'disabled');
  END IF;

  v_key := encode(extensions.digest(convert_to(v_email, 'UTF8'), 'sha256'), 'hex');

  -- Throttle is checked BEFORE any account lookup, so the answer is the same
  -- for a real and a fake address.
  SELECT * INTO v_thr FROM public.password_login_throttle WHERE email_key = v_key;
  IF FOUND AND v_thr.locked_until IS NOT NULL AND v_thr.locked_until > now() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'throttled',
      'retry_after_seconds', GREATEST(1, EXTRACT(EPOCH FROM (v_thr.locked_until - now()))::int));
  END IF;

  SELECT id, email, active INTO v_profile
    FROM public.profiles WHERE lower(email) = v_email LIMIT 1;
  IF FOUND AND COALESCE(v_profile.active, true) THEN
    SELECT password_hash INTO v_hash FROM public.user_credentials WHERE profile_id = v_profile.id;
  END IF;

  -- ALWAYS verify against something. A missing account, an inactive account
  -- and an account with no password all fall through to the dummy hash, so
  -- every rejected attempt costs the same time as a wrong password.
  v_target := COALESCE(v_hash, (SELECT h FROM public._pw_dummy LIMIT 1));
  v_ok := public._pw_verify(COALESCE(p_password, ''), v_target) AND v_hash IS NOT NULL;

  IF NOT v_ok THEN
    -- Escalating backoff: nothing for the first four attempts, then doubling
    -- from 30 seconds to a 15-minute cap. NCSC prefers throttling to hard
    -- lockout, which would let an attacker deny service to a known user.
    -- Spray brake, applied ONLY here, on the failure path. The per-email
    -- throttle cannot see one password tried against many accounts, because no
    -- single account reaches five attempts: 200 users is 800 free guesses at
    -- the same weak password, and that is the realistic attack on password
    -- login. This RPC is called straight from the browser so there is no IP to
    -- key on, and the pattern has to be read from the failures: a spread across
    -- DISTINCT addresses in a short window.
    --
    -- Checked AFTER verification and only when the password was WRONG, which
    -- is the whole point. Anyone typing their own password correctly signs in
    -- normally no matter what else is happening, so a spray against the tenant
    -- cannot lock out or even delay a single legitimate user. All it does is
    -- withdraw the four free attempts from people who are already guessing
    -- wrong, which costs a real user with a typo one short wait and costs a
    -- sprayer its throughput.
    SELECT count(*) INTO v_spray
      FROM public.password_login_throttle
     WHERE last_failed_at > now() - interval '15 minutes';
    v_delay := CASE
      WHEN COALESCE(v_spray, 0) >= 20 THEN interval '60 seconds'
      WHEN COALESCE(v_thr.failed_attempts, 0) + 1 < 5 THEN NULL
      ELSE LEAST(interval '15 minutes',
                 (interval '30 seconds') * power(2, LEAST(COALESCE(v_thr.failed_attempts, 0) + 1 - 5, 5)))
    END;
    INSERT INTO public.password_login_throttle (email_key, failed_attempts, last_failed_at, locked_until, updated_at)
    VALUES (v_key, 1, now(), CASE WHEN v_delay IS NULL THEN NULL ELSE now() + v_delay END, now())
    ON CONFLICT (email_key) DO UPDATE
      SET failed_attempts = public.password_login_throttle.failed_attempts + 1,
          last_failed_at = now(),
          locked_until = CASE WHEN v_delay IS NULL THEN NULL ELSE now() + v_delay END,
          updated_at = now();
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid');
  END IF;

  -- Correct password. Clear the throttle for this address and mint the bridge.
  DELETE FROM public.password_login_throttle WHERE email_key = v_key;
  UPDATE public.user_credentials
     SET failed_attempts = 0, last_failed_at = NULL, locked_until = NULL,
         last_login_at = now(), updated_at = now()
   WHERE profile_id = v_profile.id;

  v_bridge := encode(extensions.gen_random_bytes(32), 'base64');
  PERFORM set_config('pental.bypass_protect', 'true', true);
  UPDATE auth.users
     SET encrypted_password = extensions.crypt(v_bridge, extensions.gen_salt('bf')),
         email_confirmed_at = COALESCE(email_confirmed_at, now()),
         updated_at = now()
   WHERE email = lower(v_profile.email);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid');
  END IF;

  RETURN jsonb_build_object('ok', true, 'bridge', v_bridge, 'email', lower(v_profile.email));
END;
$$;

-- ── Change your own password while signed in ───────────────────────────────
-- Requires the CURRENT password as well as a fresh MFA state, so a hijacked
-- tab cannot silently change the password and lock the owner out.
CREATE OR REPLACE FUNCTION public.rpc_change_own_password(p_current text, p_new text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_profile RECORD;
  v_cred RECORD;
  v_policy jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  END IF;
  IF NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mfa_required');
  END IF;

  SELECT id, email INTO v_profile FROM public.profiles WHERE auth_user_id = auth.uid() LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_signed_in');
  END IF;

  SELECT * INTO v_cred FROM public.user_credentials WHERE profile_id = v_profile.id;
  -- If a password was never set, the user must use the emailed setup link
  -- rather than being able to create one from an existing session.
  IF NOT FOUND OR NOT public._pw_verify(p_current, v_cred.password_hash) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'wrong_current');
  END IF;

  v_policy := public.rpc_password_policy(p_new, v_profile.email);
  IF NOT (v_policy->>'ok')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'policy', 'reasons', v_policy->'reasons');
  END IF;

  UPDATE public.user_credentials
     SET password_hash = public._pw_hash(p_new), password_set_at = now(), updated_at = now(),
         failed_attempts = 0, last_failed_at = NULL, locked_until = NULL
   WHERE profile_id = v_profile.id;

  RETURN jsonb_build_object('ok', true);
END;
$$;

-- ── Admin: revoke a user's password ────────────────────────────────────────
-- Removes the credential row entirely, so that user falls back to email-code
-- sign-in. Used when someone leaves or a password is believed compromised.
CREATE OR REPLACE FUNCTION public.rpc_admin_clear_password(p_profile_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_role text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'senior') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  DELETE FROM public.user_credentials WHERE profile_id = p_profile_id;
  UPDATE public.password_setup_tokens SET used_at = now()
   WHERE profile_id = p_profile_id AND used_at IS NULL;
  RETURN jsonb_build_object('ok', true);
END;
$$;

-- ── Transition from email codes to passwords ───────────────────────────────
-- Turning the setting on does NOT strand anyone: email-code sign-in keeps
-- working for every user, forever, and a user without a password simply cannot
-- use the password field yet. These three functions drive the changeover.

-- Does the CURRENT user have a password? Used to prompt someone who just
-- signed in with a code to set one. Self-scoped only, so it cannot be used to
-- ask about anybody else.
CREATE OR REPLACE FUNCTION public.rpc_has_password()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_profile_id uuid; v_enabled boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok', false); END IF;
  SELECT COALESCE(password_login_enabled, false) INTO v_enabled
    FROM public.settings ORDER BY created_at LIMIT 1;
  SELECT id INTO v_profile_id FROM public.profiles WHERE auth_user_id = auth.uid() LIMIT 1;
  IF v_profile_id IS NULL THEN RETURN jsonb_build_object('ok', false); END IF;
  RETURN jsonb_build_object(
    'ok', true,
    'enabled', COALESCE(v_enabled, false),
    'has_password', EXISTS (SELECT 1 FROM public.user_credentials WHERE profile_id = v_profile_id)
  );
END;
$$;

-- Changeover progress for the admin: counts only, never a list of who has or
-- has not set one, so this cannot become a target list.
CREATE OR REPLACE FUNCTION public.rpc_password_adoption()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_role text; v_total integer; v_with integer; v_pending integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'senior') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  SELECT count(*) INTO v_total FROM public.profiles WHERE COALESCE(active, true);
  SELECT count(*) INTO v_with FROM public.user_credentials c
    JOIN public.profiles p ON p.id = c.profile_id WHERE COALESCE(p.active, true);
  SELECT count(*) INTO v_pending FROM public.password_setup_tokens t
    JOIN public.profiles p ON p.id = t.profile_id
   WHERE t.used_at IS NULL AND t.expires_at > now() AND COALESCE(p.active, true);
  RETURN jsonb_build_object('ok', true, 'total_users', v_total,
    'with_password', v_with, 'without_password', GREATEST(0, v_total - v_with),
    'invites_outstanding', v_pending);
END;
$$;

-- Who still needs an invite. Admin + fresh MFA only, and it returns addresses
-- that the caller can already see in the Users screen, so it grants no new
-- visibility; it exists so the backend can send the batch of setup links.
CREATE OR REPLACE FUNCTION public.rpc_admin_password_pending(p_limit integer DEFAULT 500)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_role text; v_rows jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'senior') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  -- 1839: and its id, so each link is sent through the admin route one by
  -- one with its outcome (send_password_setup), as an invitation is.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p.id, 'email', p.email, 'name', p.name, 'role', p.role)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT p.id, p.email, p.name, p.role FROM public.profiles p
       WHERE COALESCE(p.active, true)
         AND NOT EXISTS (SELECT 1 FROM public.user_credentials c WHERE c.profile_id = p.id)
       ORDER BY p.created_at
       LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 500), 2000))
    ) p;
  RETURN jsonb_build_object('ok', true, 'users', v_rows);
END;
$$;

-- ── Deleting a profile ─────────────────────────────────────────────────────
-- Deleting a profile with a plain DELETE fails whenever that person is
-- referenced anywhere, and many attribution columns (created_by, lead_id,
-- qa_assignee, sent_by and so on) reference profiles(id) with no ON DELETE
-- action, which means RESTRICT. In practice that is every client who has ever
-- commented, signed or been assigned to anything, so "delete" silently failed
-- for exactly the accounts people most want to remove.
--
-- This clears those attributions rather than destroying the history they point
-- at: nullable referencing columns are set NULL, so the assessment or comment
-- survives with an unknown author, and the profile can then be removed. Any
-- NOT NULL reference is reported by name instead of failing opaquely.
--
-- Discovery is done from the catalogue rather than a hand-written list, so a
-- table added later is handled without anyone remembering to update this.
DROP FUNCTION IF EXISTS public.rpc_admin_delete_profile(uuid);
-- WHO OWNS THIS PORTAL, answered inside the tenant database.
--
-- The subscription owner is known to the MASTER database, by the email that
-- pays for the tenant. This database has never had any idea, which is why an
-- admin could not delete a peer however senior they were: the rank rule had
-- nothing else to go on. The first account on a portal is the one that set it
-- up, so the EARLIEST active admin is that person here, derived rather than
-- stored so it cannot fall out of step with reality or be set by hand.
--
-- Deliberately narrow: it grants exactly one power, the ability to remove
-- another admin. Everything else still goes through the ordinary rank rule.
CREATE OR REPLACE FUNCTION public._pental_first_admin() RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $firstadmin$
  SELECT id FROM public.profiles
   WHERE role = 'admin' AND COALESCE(active, true) = true
   ORDER BY created_at ASC NULLS LAST, id ASC
   LIMIT 1
$firstadmin$;
REVOKE ALL ON FUNCTION public._pental_first_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._pental_first_admin() TO authenticated, service_role;

-- WHO THE OWNER IS, ONCE (570).
--
-- [stated] Arian: "the main admin user, you know the one paying the
-- subscription, to be able to change emails, edit and delete the other admin
-- users".
--
-- The power was already written. The problem was that "owner" meant two
-- different people. Billing ownership is decided in the master database, where
-- the tenant record carries the email that pays, and the portal reads it as
-- `is_owner`. Everything in USER MANAGEMENT — this schema, the API, the
-- portal's own permission helpers — instead used "the earliest created active
-- admin". When the paying admin is not the oldest admin row, and there is
-- nothing that makes them so, the subscriber is refused by all three layers at
-- once and there is no screen anywhere that explains why.
--
-- So the owner is now a STAMPED value with the old rule as the fallback:
--   settings.account_owner_id, written by the API only after the master
--   database has confirmed that caller's email owns THIS tenant.
-- The fallback keeps every portal that has never stamped one working exactly
-- as before, and a stamped id that is no longer an active admin is ignored
-- rather than locking the portal out of its own administration.
CREATE OR REPLACE FUNCTION public._pental_account_owner() RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $acctowner$
  SELECT COALESCE(
    (SELECT p.id FROM public.profiles p
      WHERE p.id = (SELECT s.account_owner_id FROM public.settings s
                     WHERE s.account_owner_id IS NOT NULL LIMIT 1)
        AND p.role = 'admin' AND COALESCE(p.active, true) = true),
    public._pental_first_admin()
  )
$acctowner$;
REVOKE ALL ON FUNCTION public._pental_account_owner() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._pental_account_owner() TO authenticated, service_role;

-- AND NOBODY IN THE PORTAL MAY WRITE IT (570).
--
-- `settings_admin_update` lets any admin or senior update settings, which is
-- right for every other column on that table and catastrophic for this one: an
-- ordinary admin could name themselves owner and then delete their colleagues.
-- The value is written only by `rpc_claim_account_owner` below, which Pental's
-- API calls after the MASTER database has confirmed the caller's email owns
-- this tenant, so the proof lives where the billing does and no portal session
-- can forge it.
--
-- 1738: THE GUARD ASKS WHO IS WRITING, SO IT RUNS AS THEM. It was SECURITY
-- DEFINER, and inside a definer function `current_user` is always the owner,
-- never `authenticated` or `anon`: the guard never fired, and any admin could
-- stamp themselves owner with one request. Run as the caller, a portal session
-- is refused and the claim function, which runs as the owner, is not.
--
-- A column-level GRANT is the other way to do this and is the wrong one here:
-- revoking one column means re-granting the other two hundred by name, and the
-- next settings column added would silently become unwritable.
CREATE OR REPLACE FUNCTION public._pental_guard_account_owner() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = public, pg_catalog, pg_temp AS $ownerguard$
BEGIN
  IF NEW.account_owner_id IS DISTINCT FROM OLD.account_owner_id
     AND current_user IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION 'account_owner_id is set from the billing record, not from the portal';
  END IF;
  RETURN NEW;
END;
$ownerguard$;
DROP TRIGGER IF EXISTS trg_pental_guard_account_owner ON public.settings;
CREATE TRIGGER trg_pental_guard_account_owner
  BEFORE UPDATE ON public.settings
  FOR EACH ROW EXECUTE FUNCTION public._pental_guard_account_owner();

-- 1738: THE PAYER CLAIMS IT, THROUGH PENTAL. [stated] Arian: "continue" (to
-- fixing the owner claim). The API wrote this column with the only key it
-- holds for a firm, the publishable one, and the write was refused, so no
-- firm's owner was ever stamped and every firm's owner was its earliest admin.
--
-- Two proofs, both required: Pental's signature (or the provisioning secret),
-- which the API adds only after the master database has confirmed the caller's
-- email holds the subscription, and the caller's own session, which says who
-- becomes the owner. A signed-in admin calling this without Pental is refused,
-- and so is Pental without a signed-in admin.
CREATE OR REPLACE FUNCTION public.rpc_claim_account_owner(p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $claimowner$
DECLARE v_mode text; v_me uuid; v_row uuid; v_current uuid;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_claim_account_owner');
  IF v_mode IS NULL OR v_mode NOT IN ('signed', 'provision_secret') THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  SELECT id INTO v_me FROM public.profiles
   WHERE auth_user_id = auth.uid() AND active = true AND role = 'admin' LIMIT 1;
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_admin');
  END IF;
  SELECT id, account_owner_id INTO v_row, v_current FROM public.settings LIMIT 1;
  IF v_row IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_settings_row');
  END IF;
  IF v_current IS NOT DISTINCT FROM v_me THEN
    RETURN jsonb_build_object('ok', true, 'owner_id', v_me, 'changed', false);
  END IF;
  UPDATE public.settings SET account_owner_id = v_me WHERE id = v_row;
  RETURN jsonb_build_object('ok', true, 'owner_id', v_me, 'changed', true);
END;
$claimowner$;
REVOKE ALL ON FUNCTION public.rpc_claim_account_owner(text, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_claim_account_owner(text, jsonb) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.rpc_admin_delete_profile(p_profile_id uuid, p_force boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE
  v_role text;
  v_target RECORD;
  v_rank jsonb := '{"admin":100,"senior":80,"standard":50,"sales":50,"marketing":50,"contractor":30,"client":10}'::jsonb;
  r RECORD;
  v_blocked text[] := ARRAY[]::text[];
  v_cleared integer := 0;
  v_removed integer := 0;
  v_n integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  SELECT role INTO v_role FROM public.profiles WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'senior') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;

  SELECT id, role, email, auth_user_id INTO v_target FROM public.profiles WHERE id = p_profile_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  -- Same hierarchy rule the API enforces: never delete a peer or a senior.
  -- EXCEPT for the account owner, who is the first admin on the portal and the
  -- only person who can remove another admin. Without this, a firm whose other
  -- administrator has left has no way to remove them from their own portal.
  -- The owner is never deletable, by anyone including themselves, or a portal
  -- could be left with nobody able to administer it.
  IF v_target.id = public._pental_account_owner() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'owner');
  END IF;
  IF COALESCE((v_rank->>v_target.role)::int, 0) >= COALESCE((v_rank->>v_role)::int, 0)
     AND NOT EXISTS (
       SELECT 1 FROM public.profiles
        WHERE auth_user_id = auth.uid() AND id = public._pental_account_owner()
     ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'rank');
  END IF;

  -- Every column in this schema that points at profiles(id).
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl,
           a.attname::text            AS col,
           a.attnotnull               AS notnull,
           c.confdeltype              AS deltype
      FROM pg_constraint c
      JOIN unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
     WHERE c.contype = 'f'
       AND c.confrelid = 'public.profiles'::regclass
       AND c.connamespace = 'public'::regnamespace
  LOOP
    -- 'a' means ON DELETE NO ACTION, 'r' RESTRICT. Anything else (cascade,
    -- set null, set default) already handles itself.
    IF r.deltype IN ('a', 'r') THEN
      IF r.notnull THEN
        -- Cannot be nulled, so the row itself has to go, but only on request.
        IF p_force THEN
          EXECUTE format('DELETE FROM %s WHERE %I = $1', r.tbl, r.col) USING p_profile_id;
          GET DIAGNOSTICS v_n = ROW_COUNT;
          v_removed := v_removed + v_n;
        ELSE
          EXECUTE format('SELECT count(*) FROM %s WHERE %I = $1', r.tbl, r.col) INTO v_n USING p_profile_id;
          IF v_n > 0 THEN
            v_blocked := v_blocked || (r.tbl || '.' || r.col || ' (' || v_n || ')');
          END IF;
        END IF;
      ELSE
        EXECUTE format('UPDATE %s SET %I = NULL WHERE %I = $1', r.tbl, r.col, r.col) USING p_profile_id;
        v_cleared := v_cleared + 1;
      END IF;
    END IF;
  END LOOP;

  IF cardinality(v_blocked) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'referenced',
      'blocked_by', to_jsonb(v_blocked));
  END IF;

  DELETE FROM public.profiles WHERE id = p_profile_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'delete_failed');
  END IF;

  RETURN jsonb_build_object('ok', true, 'cleared_references', v_cleared,
    'removed_rows', v_removed,
    'auth_user_id', v_target.auth_user_id, 'email', v_target.email);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_admin_delete_profile(uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rpc_admin_delete_profile(uuid, boolean) TO authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1816: WHO MAY ACT ON WHOM, ASKED HERE AS WELL.
--
-- [stated] Arian: "cant edit people with higher or equal roles, why is the
-- option even there?"
--
-- The rule: you act on the people below you; the account owner also acts on
-- the other administrators; nobody else acts on the owner; and nobody acts on
-- themselves through the controls meant for other people. The Users screen
-- and the API route said so, and this database said so only for removing
-- someone. With a session and nothing else, straight through the API, an
-- administrator or senior could reset anybody's MFA (rpc_admin_reset_mfa
-- never asked whose it was), and write `role`, `active`, `email` or
-- `auth_user_id` on any profile, their own included: a senior could make
-- themselves an administrator with one request.
--
-- _pental_manage_refusal(target) answers NULL when the caller may act on that
-- person, or why not: not_authorised (not an active admin or senior),
-- not_found, self, owner (the account owner, to anybody else), owner_only
-- (another administrator, to anybody but the owner) or rank (an equal or
-- higher role). The ranks are the ones rpc_create_auth_user and the route use.
CREATE OR REPLACE FUNCTION public._pental_manage_refusal(p_target uuid)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $mngref$
DECLARE
  v_h jsonb := '{"admin":5,"senior":4,"standard":3,"sales":2,"marketing":1,"contractor":0,"client":0}'::jsonb;
  v_me uuid; v_mine text; v_theirs text; v_owner uuid;
BEGIN
  SELECT id, role INTO v_me, v_mine FROM public.profiles
   WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_me IS NULL OR v_mine NOT IN ('admin', 'senior') THEN RETURN 'not_authorised'; END IF;
  SELECT role INTO v_theirs FROM public.profiles WHERE id = p_target;
  IF NOT FOUND THEN RETURN 'not_found'; END IF;
  IF p_target = v_me THEN RETURN 'self'; END IF;
  v_owner := public._pental_account_owner();
  IF p_target = v_owner THEN RETURN 'owner'; END IF;
  IF v_me = v_owner THEN RETURN NULL; END IF;
  IF v_theirs = 'admin' THEN RETURN 'owner_only'; END IF;
  IF COALESCE((v_h->>v_theirs)::int, 0) >= COALESCE((v_h->>v_mine)::int, 0) THEN RETURN 'rank'; END IF;
  RETURN NULL;
END;
$mngref$;
REVOKE ALL ON FUNCTION public._pental_manage_refusal(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public._pental_manage_refusal(uuid) TO authenticated, service_role;

-- And on the table, for a write made straight through the API with a session.
-- The functions that manage people run as the definer and ask the question
-- above themselves (or set pental.bypass_protect), so this stands aside for
-- them, as the account owner's guard does: it runs as the person writing,
-- which is how it can tell. Only the columns that decide who someone is and
-- what they may do: role, active, the sign-in binding, and the address (a
-- change of capitals alone is the same address). Your own name, picture,
-- signature and the rest stay yours to change; your own role, status and
-- sign-in binding do not. Adding someone is limited to your own rank or
-- below, as rpc_create_auth_user limits it.
CREATE OR REPLACE FUNCTION public._pental_guard_profile_rank() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER
SET search_path = public, pg_catalog, pg_temp AS $rankguard$
DECLARE
  v_h jsonb := '{"admin":5,"senior":4,"standard":3,"sales":2,"marketing":1,"contractor":0,"client":0}'::jsonb;
  v_me uuid; v_why text;
BEGIN
  IF current_user IS DISTINCT FROM 'authenticated'
     OR COALESCE(current_setting('pental.bypass_protect', true), '') = 'true' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.role IS NOT DISTINCT FROM OLD.role
     AND NEW.active IS NOT DISTINCT FROM OLD.active
     AND NEW.auth_user_id IS NOT DISTINCT FROM OLD.auth_user_id
     AND lower(COALESCE(NEW.email, '')) = lower(COALESCE(OLD.email, '')) THEN
    RETURN NEW;
  END IF;
  v_me := public.current_profile_id();
  -- No active profile of your own: the row policies refuse you already.
  IF v_me IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF COALESCE((v_h->>NEW.role)::int, 0) > COALESCE((v_h->>public.current_user_role())::int, 0) THEN
      RAISE EXCEPTION 'You cannot add someone with a higher role than your own' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.id = v_me THEN
    IF NEW.role IS DISTINCT FROM OLD.role OR NEW.active IS DISTINCT FROM OLD.active
       OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN
      RAISE EXCEPTION 'You cannot change your own role, status or sign-in' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  v_why := public._pental_manage_refusal(OLD.id);
  IF v_why IS NOT NULL THEN
    RAISE EXCEPTION '%', CASE v_why
        WHEN 'owner' THEN 'Nobody else can change or remove the account owner'
        WHEN 'owner_only' THEN 'Only the account owner can change or remove another administrator'
        WHEN 'rank' THEN 'You cannot change or remove someone with an equal or higher role'
        WHEN 'self' THEN 'You cannot remove yourself'
        ELSE 'Not authorised' END
      USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.role IS DISTINCT FROM OLD.role
     AND COALESCE((v_h->>NEW.role)::int, 0) > COALESCE((v_h->>public.current_user_role())::int, 0) THEN
    RAISE EXCEPTION 'You cannot give a role higher than your own' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$rankguard$;
REVOKE ALL ON FUNCTION public._pental_guard_profile_rank() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS tr_pental_guard_profile_rank ON public.profiles;
CREATE TRIGGER tr_pental_guard_profile_rank
  BEFORE INSERT OR UPDATE OR DELETE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public._pental_guard_profile_rank();

-- 1737: AN ADMINISTRATOR CHANGES SOMEBODY'S SIGN-IN ADDRESS HERE. [stated]
-- Arian: "continue" (to fixing it). The API asked the sign-in service's admin
-- endpoint, which wants the firm's service key; Pental holds only the
-- publishable one, so the change was refused on every firm.
--
-- One transaction moves both halves: the sign-in record (lower case, the
-- identity) and the profile (as typed, where email is sent), so the two can
-- never disagree about who this person is. The rules are the route's, asked
-- again here: an admin or senior with a fresh MFA check; a senior never
-- re-points another senior; another administrator's address is the account
-- owner's call. And it needs Pental's signature (or the provisioning secret)
-- as well as the session: the API sends a notice to both addresses on the same
-- request, and a call straight from a browser would skip it.
CREATE OR REPLACE FUNCTION public.rpc_admin_change_sign_in_email(
  p_profile_id uuid, p_email text, p_secret text DEFAULT NULL, p_auth jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_catalog, pg_temp AS $signinemail$
DECLARE
  v_mode text;
  v_me record;
  v_target record;
  v_typed text;
  v_next text;
BEGIN
  v_mode := public._pental_authorise(p_auth, p_secret, 'rpc_admin_change_sign_in_email');
  IF v_mode IS NULL OR v_mode NOT IN ('signed', 'provision_secret') THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  SELECT id, role INTO v_me FROM public.profiles
   WHERE auth_user_id = auth.uid() AND active = true LIMIT 1;
  IF v_me.id IS NULL OR v_me.role NOT IN ('admin', 'senior') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;

  v_typed := btrim(COALESCE(p_email, ''));
  v_next := lower(v_typed);
  IF v_next !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]{2,}$' OR length(v_next) > 254 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid');
  END IF;

  SELECT id, role, email, auth_user_id INTO v_target FROM public.profiles WHERE id = p_profile_id;
  IF v_target.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  IF v_target.id <> v_me.id THEN
    IF v_me.role = 'senior' AND v_target.role = 'senior' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'rank');
    END IF;
    IF v_target.role = 'admin' AND v_me.id IS DISTINCT FROM public._pental_account_owner() THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'owner_only');
    END IF;
  END IF;

  IF v_typed = COALESCE(v_target.email, '') THEN
    RETURN jsonb_build_object('ok', true, 'changed', false, 'email', v_typed);
  END IF;

  PERFORM set_config('pental.bypass_protect', 'true', true);
  -- The same address in other capitals: who can sign in does not change.
  IF lower(btrim(COALESCE(v_target.email, ''))) = v_next THEN
    UPDATE public.profiles SET email = v_typed WHERE id = v_target.id;
    PERFORM set_config('pental.bypass_protect', 'false', true);
    RETURN jsonb_build_object('ok', true, 'changed', true, 'case_only', true,
      'email', v_typed, 'old_email', v_target.email);
  END IF;

  IF EXISTS (SELECT 1 FROM public.profiles
              WHERE id <> v_target.id AND lower(btrim(email)) = v_next)
     OR (v_target.auth_user_id IS NOT NULL AND EXISTS (
           SELECT 1 FROM auth.users
            WHERE id <> v_target.auth_user_id AND lower(btrim(email)) = v_next)) THEN
    PERFORM set_config('pental.bypass_protect', 'false', true);
    RETURN jsonb_build_object('ok', false, 'reason', 'taken');
  END IF;

  IF v_target.auth_user_id IS NOT NULL THEN
    UPDATE auth.users
       SET email = v_next,
           email_confirmed_at = COALESCE(email_confirmed_at, now()),
           email_change = '', email_change_token_new = '',
           updated_at = now()
     WHERE id = v_target.auth_user_id;
    IF to_regclass('auth.identities') IS NOT NULL THEN
      UPDATE auth.identities
         SET identity_data = COALESCE(identity_data, '{}'::jsonb) || jsonb_build_object('email', v_next),
             updated_at = now()
       WHERE user_id = v_target.auth_user_id AND provider = 'email';
    END IF;
  END IF;
  UPDATE public.profiles SET email = v_typed WHERE id = v_target.id;
  PERFORM set_config('pental.bypass_protect', 'false', true);
  RETURN jsonb_build_object('ok', true, 'changed', true, 'email', v_typed, 'old_email', v_target.email);
EXCEPTION WHEN unique_violation THEN
  -- Taken between the check and the write: nothing above is kept.
  RETURN jsonb_build_object('ok', false, 'reason', 'taken');
END;
$signinemail$;
REVOKE ALL ON FUNCTION public.rpc_admin_change_sign_in_email(uuid, text, text, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_admin_change_sign_in_email(uuid, text, text, jsonb) TO authenticated, service_role;

-- ── Housekeeping ───────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.rpc_cleanup_password_tokens()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, extensions, pg_catalog, pg_temp AS $$
DECLARE v_n integer;
BEGIN
  DELETE FROM public.password_setup_tokens
   WHERE expires_at < now() - interval '7 days' OR used_at < now() - interval '7 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$$;

-- ── Grants ─────────────────────────────────────────────────────────────────
-- Only the functions are callable, never the tables.
REVOKE ALL ON FUNCTION public._pw_prehash(text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._pw_hash(text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._pw_verify(text, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.rpc_password_policy(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_issue_password_token(text, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_set_password_with_token(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_password_login(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_change_own_password(text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_has_password() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_password_adoption() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_admin_password_pending(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_admin_clear_password(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.rpc_cleanup_password_tokens() FROM PUBLIC, anon, authenticated;

-- Pre-auth surface: the sign-in form needs the policy (to give live feedback
-- on the set-password screen), the token redemption and the sign-in itself.
GRANT EXECUTE ON FUNCTION public.rpc_password_policy(text, text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_set_password_with_token(text, text) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_password_login(text, text) TO anon, authenticated;
-- Signed-in surface.
GRANT EXECUTE ON FUNCTION public.rpc_change_own_password(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_has_password() TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_password_adoption() TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_admin_password_pending(integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_admin_clear_password(uuid) TO authenticated;
-- Server-to-server only (provision secret enforced inside).
GRANT EXECUTE ON FUNCTION public.rpc_issue_password_token(text, text, text, jsonb) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.rpc_cleanup_password_tokens() TO service_role;

-- ── Seed the blocklist ─────────────────────────────────────────────────────
-- TWO tables, because they answer different questions.
--
-- common_passwords holds passwords a user could ACTUALLY TYPE and have
-- accepted. The minimum length is 12, so "password" and "qwerty" are already
-- refused by the length rule before this list is ever consulted: listing them
-- here is dead weight. Every entry is therefore 12 characters or more, taken
-- from the long tail of breach corpora that genuinely clears the floor.
--
-- common_password_bases holds the SHORT roots. They are not passwords anyone
-- can use, but they are what people PAD to reach twelve: "password" becomes
-- "password1234", "qwerty" becomes "qwerty123456", "P@ssw0rd" becomes
-- "P@ssw0rd2025". The check below strips that padding and tests what is left,
-- which catches far more than any literal list of long passwords could.

CREATE TABLE IF NOT EXISTS public.common_password_bases (
  base text PRIMARY KEY
);
ALTER TABLE public.common_password_bases ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.common_password_bases FROM anon, authenticated;

-- Anything below the minimum length can never be reached, so it is removed
-- rather than left to look like protection. Runs on every execution of this
-- file, so a database seeded by an earlier version is cleaned up.
DELETE FROM public.common_passwords WHERE length(pw) < 12;

