CREATE OR REPLACE FUNCTION public._cvss4_level(p_metric text, p_value text) RETURNS float8
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $cv4l$
  SELECT (CASE
    WHEN p_metric = 'AV' THEN CASE p_value WHEN 'N' THEN 0.0 WHEN 'A' THEN 0.1 WHEN 'L' THEN 0.2 WHEN 'P' THEN 0.3 END
    WHEN p_metric = 'PR' THEN CASE p_value WHEN 'N' THEN 0.0 WHEN 'L' THEN 0.1 WHEN 'H' THEN 0.2 END
    WHEN p_metric = 'UI' THEN CASE p_value WHEN 'N' THEN 0.0 WHEN 'P' THEN 0.1 WHEN 'A' THEN 0.2 END
    WHEN p_metric = 'AC' THEN CASE p_value WHEN 'L' THEN 0.0 WHEN 'H' THEN 0.1 END
    WHEN p_metric = 'AT' THEN CASE p_value WHEN 'N' THEN 0.0 WHEN 'P' THEN 0.1 END
    WHEN p_metric IN ('VC', 'VI', 'VA') THEN CASE p_value WHEN 'H' THEN 0.0 WHEN 'L' THEN 0.1 WHEN 'N' THEN 0.2 END
    WHEN p_metric = 'SC' THEN CASE p_value WHEN 'H' THEN 0.1 WHEN 'L' THEN 0.2 WHEN 'N' THEN 0.3 END
    WHEN p_metric IN ('SI', 'SA') THEN CASE p_value WHEN 'S' THEN 0.0 WHEN 'H' THEN 0.1 WHEN 'L' THEN 0.2 WHEN 'N' THEN 0.3 END
    WHEN p_metric IN ('CR', 'IR', 'AR') THEN CASE p_value WHEN 'H' THEN 0.0 WHEN 'M' THEN 0.1 WHEN 'L' THEN 0.2 END
    WHEN p_metric = 'E' THEN CASE p_value WHEN 'U' THEN 0.2 WHEN 'P' THEN 0.1 WHEN 'A' THEN 0.0 END
  END)::float8
$cv4l$;

CREATE OR REPLACE FUNCTION public._cvss4_score(p_vector text) RETURNS numeric
LANGUAGE plpgsql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $cv4s$
DECLARE
  v text := public._cvss_vector_norm(p_vector);
  ok jsonb := '{"AV":["N","A","L","P"],"AC":["L","H"],"AT":["N","P"],"PR":["N","L","H"],"UI":["N","P","A"],"VC":["H","L","N"],"VI":["H","L","N"],"VA":["H","L","N"],"SC":["H","L","N"],"SI":["H","L","N"],"SA":["H","L","N"],"E":["X","A","P","U"],"CR":["X","H","M","L"],"IR":["X","H","M","L"],"AR":["X","H","M","L"],"MAV":["X","N","A","L","P"],"MAC":["X","L","H"],"MAT":["X","N","P"],"MPR":["X","N","L","H"],"MUI":["X","N","P","A"],"MVC":["X","H","L","N"],"MVI":["X","H","L","N"],"MVA":["X","H","L","N"],"MSC":["X","H","L","N"],"MSI":["X","S","H","L","N"],"MSA":["X","S","H","L","N"],"S":["X","N","P"],"AU":["X","N","Y"],"R":["X","A","U","I"],"V":["X","D","C"],"RE":["X","L","M","H"],"U":["X","CLEAR","GREEN","AMBER","RED"]}';
  base text[] := ARRAY['AV','AC','AT','PR','UI','VC','VI','VA','SC','SI','SA'];
  lv text[] := ARRAY['AV','PR','UI','AC','AT','VC','VI','VA','SC','SI','SA','CR','IR','AR','E'];
  m jsonb := '{}'::jsonb; part text; kk text; vv text;
  eff jsonb := '{}'::jsonb;
  eq1 int; eq2 int; eq3 int; eq4 int; eq5 int; eq6 int; mac text;
  val float8; lo1 float8; lo2 float8; lo36 float8; lo4 float8; lo5 float8;
  c1 text[]; c2 text[]; c36 text[]; c4 text[]; c5 text[];
  a text; b text; c text; d text; e text; mx text;
  dAV float8; dPR float8; dUI float8; dAC float8; dAT float8; dVC float8; dVI float8; dVA float8;
  dSC float8; dSI float8; dSA float8; dCR float8; dIR float8; dAR float8; dE float8;
  dd float8[]; all_ok boolean; i int; found boolean := false;
  cur1 float8; cur2 float8; cur36 float8; cur4 float8;
  n int := 0; n1 float8 := 0; n2 float8 := 0; n36 float8 := 0; n4 float8 := 0; n5 float8 := 0;
  step float8 := 0.1; mean float8; x float8; t float8; r float8;
BEGIN
  IF v IS NULL OR v !~ '^CVSS:4\.0/' THEN RETURN NULL; END IF;
  FOREACH part IN ARRAY string_to_array(substr(v, 10), '/') LOOP
    IF split_part(part, ':', 3) <> '' OR position(':' in part) = 0 THEN RETURN NULL; END IF;
    kk := upper(split_part(part, ':', 1)); vv := upper(split_part(part, ':', 2));
    IF m ? kk THEN CONTINUE; END IF;
    IF NOT (ok ? kk) OR NOT ((ok -> kk) ? vv) THEN RETURN NULL; END IF;
    m := m || jsonb_build_object(kk, vv);
  END LOOP;
  FOREACH kk IN ARRAY base LOOP
    IF NOT (m ? kk) THEN RETURN NULL; END IF;
  END LOOP;
  -- Each metric as it counts: E, CR, IR and AR at their worst where not said,
  -- a modified metric over the one it modifies.
  FOREACH kk IN ARRAY lv || ARRAY['MSI','MSA'] LOOP
    vv := COALESCE(m ->> kk, 'X');
    IF vv = 'X' AND kk IN ('E', 'CR', 'IR', 'AR') THEN
      vv := CASE kk WHEN 'E' THEN 'A' ELSE 'H' END;
    ELSIF COALESCE(m ->> ('M' || kk), 'X') <> 'X' THEN
      vv := m ->> ('M' || kk);
    END IF;
    eff := eff || jsonb_build_object(kk, vv);
  END LOOP;
  IF eff ->> 'VC' = 'N' AND eff ->> 'VI' = 'N' AND eff ->> 'VA' = 'N' AND eff ->> 'SC' = 'N' AND eff ->> 'SI' = 'N' AND eff ->> 'SA' = 'N' THEN
    RETURN 0;
  END IF;
  -- The MacroVector.
  eq1 := CASE WHEN eff ->> 'AV' = 'N' AND eff ->> 'PR' = 'N' AND eff ->> 'UI' = 'N' THEN 0
              WHEN (eff ->> 'AV' = 'N' OR eff ->> 'PR' = 'N' OR eff ->> 'UI' = 'N') AND eff ->> 'AV' <> 'P' THEN 1 ELSE 2 END;
  eq2 := CASE WHEN eff ->> 'AC' = 'L' AND eff ->> 'AT' = 'N' THEN 0 ELSE 1 END;
  eq3 := CASE WHEN eff ->> 'VC' = 'H' AND eff ->> 'VI' = 'H' THEN 0
              WHEN eff ->> 'VC' = 'H' OR eff ->> 'VI' = 'H' OR eff ->> 'VA' = 'H' THEN 1 ELSE 2 END;
  eq4 := CASE WHEN eff ->> 'MSI' = 'S' OR eff ->> 'MSA' = 'S' THEN 0
              WHEN eff ->> 'SC' = 'H' OR eff ->> 'SI' = 'H' OR eff ->> 'SA' = 'H' THEN 1 ELSE 2 END;
  eq5 := CASE eff ->> 'E' WHEN 'A' THEN 0 WHEN 'P' THEN 1 ELSE 2 END;
  eq6 := CASE WHEN (eff ->> 'CR' = 'H' AND eff ->> 'VC' = 'H') OR (eff ->> 'IR' = 'H' AND eff ->> 'VI' = 'H')
                OR (eff ->> 'AR' = 'H' AND eff ->> 'VA' = 'H') THEN 0 ELSE 1 END;
  mac := eq1::text || eq2 || eq3 || eq4 || eq5 || eq6;
  val := public._cvss4_macro_score(mac);
  -- 1. The maximal scoring difference to the next lower MacroVector in each
  --    class (NULL where there is none).
  lo1 := public._cvss4_macro_score((eq1 + 1)::text || eq2 || eq3 || eq4 || eq5 || eq6);
  lo2 := public._cvss4_macro_score(eq1::text || (eq2 + 1) || eq3 || eq4 || eq5 || eq6);
  IF eq3 = 1 AND eq6 = 1 THEN lo36 := public._cvss4_macro_score(eq1::text || eq2 || (eq3 + 1) || eq4 || eq5 || eq6);
  ELSIF eq3 = 0 AND eq6 = 1 THEN lo36 := public._cvss4_macro_score(eq1::text || eq2 || (eq3 + 1) || eq4 || eq5 || eq6);
  ELSIF eq3 = 1 AND eq6 = 0 THEN lo36 := public._cvss4_macro_score(eq1::text || eq2 || eq3 || eq4 || eq5 || (eq6 + 1));
  ELSIF eq3 = 0 AND eq6 = 0 THEN
    lo36 := GREATEST(public._cvss4_macro_score(eq1::text || eq2 || eq3 || eq4 || eq5 || (eq6 + 1)),
                     public._cvss4_macro_score(eq1::text || eq2 || (eq3 + 1) || eq4 || eq5 || eq6));
  ELSE lo36 := public._cvss4_macro_score(eq1::text || eq2 || (eq3 + 1) || eq4 || eq5 || (eq6 + 1));
  END IF;
  lo4 := public._cvss4_macro_score(eq1::text || eq2 || eq3 || (eq4 + 1) || eq5 || eq6);
  lo5 := public._cvss4_macro_score(eq1::text || eq2 || eq3 || eq4 || (eq5 + 1) || eq6);
  -- 2. The distance from the highest severity vector of this MacroVector that
  --    is at least as severe in every metric (the last one tried where none is).
  c1 := CASE eq1 WHEN 0 THEN ARRAY['AV:N/PR:N/UI:N/'] WHEN 1 THEN ARRAY['AV:A/PR:N/UI:N/', 'AV:N/PR:L/UI:N/', 'AV:N/PR:N/UI:P/']
                 ELSE ARRAY['AV:P/PR:N/UI:N/', 'AV:A/PR:L/UI:P/'] END;
  c2 := CASE eq2 WHEN 0 THEN ARRAY['AC:L/AT:N/'] ELSE ARRAY['AC:H/AT:N/', 'AC:L/AT:P/'] END;
  c36 := CASE eq3::text || eq6
    WHEN '00' THEN ARRAY['VC:H/VI:H/VA:H/CR:H/IR:H/AR:H/']
    WHEN '01' THEN ARRAY['VC:H/VI:H/VA:L/CR:M/IR:M/AR:H/', 'VC:H/VI:H/VA:H/CR:M/IR:M/AR:M/']
    WHEN '10' THEN ARRAY['VC:L/VI:H/VA:H/CR:H/IR:H/AR:H/', 'VC:H/VI:L/VA:H/CR:H/IR:H/AR:H/']
    WHEN '11' THEN ARRAY['VC:L/VI:H/VA:L/CR:H/IR:M/AR:H/', 'VC:L/VI:H/VA:H/CR:H/IR:M/AR:M/', 'VC:H/VI:L/VA:H/CR:M/IR:H/AR:M/', 'VC:H/VI:L/VA:L/CR:M/IR:H/AR:H/', 'VC:L/VI:L/VA:H/CR:H/IR:H/AR:M/']
    ELSE ARRAY['VC:L/VI:L/VA:L/CR:H/IR:H/AR:H/'] END;
  c4 := CASE eq4 WHEN 0 THEN ARRAY['SC:H/SI:S/SA:S/'] WHEN 1 THEN ARRAY['SC:H/SI:H/SA:H/'] ELSE ARRAY['SC:L/SI:L/SA:L/'] END;
  c5 := CASE eq5 WHEN 0 THEN ARRAY['E:A/'] WHEN 1 THEN ARRAY['E:P/'] ELSE ARRAY['E:U/'] END;
  <<maxes>>
  FOREACH a IN ARRAY c1 LOOP FOREACH b IN ARRAY c2 LOOP FOREACH c IN ARRAY c36 LOOP FOREACH d IN ARRAY c4 LOOP FOREACH e IN ARRAY c5 LOOP
    mx := a || b || c || d || e;
    dd := ARRAY[]::float8[];
    all_ok := true;
    FOR i IN 1 .. array_length(lv, 1) LOOP
      dd := dd || (public._cvss4_level(lv[i], eff ->> lv[i])
                   - public._cvss4_level(lv[i], split_part(substr(mx, strpos(mx, lv[i]) + length(lv[i]) + 1), '/', 1)));
      IF dd[i] IS NULL OR dd[i] < 0 THEN all_ok := false; END IF;
    END LOOP;
    EXIT maxes WHEN all_ok;
  END LOOP; END LOOP; END LOOP; END LOOP; END LOOP;
  dAV := dd[1]; dPR := dd[2]; dUI := dd[3]; dAC := dd[4]; dAT := dd[5]; dVC := dd[6]; dVI := dd[7]; dVA := dd[8];
  dSC := dd[9]; dSI := dd[10]; dSA := dd[11]; dCR := dd[12]; dIR := dd[13]; dAR := dd[14]; dE := dd[15];
  cur1 := dAV + dPR + dUI;
  cur2 := dAC + dAT;
  cur36 := dVC + dVI + dVA + dCR + dIR + dAR;
  cur4 := dSC + dSI + dSA;
  IF lo1 IS NOT NULL THEN n := n + 1; n1 := (val - lo1) * (cur1 / ((CASE eq1 WHEN 0 THEN 1 WHEN 1 THEN 4 ELSE 5 END)::float8 * step)); END IF;
  IF lo2 IS NOT NULL THEN n := n + 1; n2 := (val - lo2) * (cur2 / ((CASE eq2 WHEN 0 THEN 1 ELSE 2 END)::float8 * step)); END IF;
  IF lo36 IS NOT NULL THEN
    n := n + 1;
    n36 := (val - lo36) * (cur36 / ((CASE eq3::text || eq6 WHEN '00' THEN 7 WHEN '01' THEN 6 WHEN '10' THEN 8 WHEN '11' THEN 8 ELSE 10 END)::float8 * step));
  END IF;
  IF lo4 IS NOT NULL THEN n := n + 1; n4 := (val - lo4) * (cur4 / ((CASE eq4 WHEN 0 THEN 6 WHEN 1 THEN 5 ELSE 4 END)::float8 * step)); END IF;
  IF lo5 IS NOT NULL THEN n := n + 1; n5 := (val - lo5) * 0; END IF;
  mean := CASE WHEN n = 0 THEN 0 ELSE (n1 + n2 + n36 + n4 + n5) / n END;
  -- 3. That MacroVector's score less the mean, rounded half up to one place
  --    (after adding 10^-6, as the reference does, JavaScript's Math.round).
  x := GREATEST(0::float8, LEAST(10::float8, val - mean));
  t := (x + 0.000001::float8) * 10;
  r := floor(t);
  IF t - r >= 0.5 THEN r := r + 1; END IF;
  RETURN round(r::numeric / 10, 1);
END $cv4s$;

-- A vector's score in its own version, NULL where it is not a whole vector.
CREATE OR REPLACE FUNCTION public._cvss_score(p_vector text) RETURNS numeric
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $cvsc$
  SELECT CASE WHEN public._cvss_vector_norm(p_vector) ~ '^CVSS:4\.0/' THEN public._cvss4_score(p_vector)
              ELSE public._cvss3_score(p_vector) END
$cvsc$;

CREATE OR REPLACE FUNCTION public._cvss_in_step() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_catalog, pg_temp AS $cis$
DECLARE v_norm text; v_calc numeric;
BEGIN
  v_norm := public._cvss_vector_norm(NEW.cvss_vector);
  NEW.cvss_vector := v_norm;
  v_calc := public._cvss_score(v_norm);
  IF v_calc IS NULL OR NEW.cvss IS NOT DISTINCT FROM v_calc THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.cvss IS DISTINCT FROM OLD.cvss
     AND public._cvss_vector_norm(OLD.cvss_vector) IS NOT DISTINCT FROM v_norm THEN
    -- The score was changed and the metrics were not: the score is the
    -- writer's, and metrics that no longer describe it go.
    NEW.cvss_vector := NULL;
    RETURN NEW;
  END IF;
  NEW.cvss := v_calc;
  NEW.severity := public._cvss_band(v_calc);
  RETURN NEW;
END $cis$;
REVOKE ALL ON FUNCTION public._cvss_in_step() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS zy_cvss_in_step ON public.findings;
CREATE TRIGGER zy_cvss_in_step BEFORE INSERT OR UPDATE OF cvss, cvss_vector ON public.findings
  FOR EACH ROW EXECUTE FUNCTION public._cvss_in_step();
DROP TRIGGER IF EXISTS zy_cvss_in_step ON public.kb_entries;
CREATE TRIGGER zy_cvss_in_step BEFORE INSERT OR UPDATE OF cvss, cvss_vector ON public.kb_entries
  FOR EACH ROW EXECUTE FUNCTION public._cvss_in_step();

-- ═══════════════════════════════════════════════════════════════════════════
-- 1845: A CLIENT CODE MADE FROM SYMBOLS IS MADE AGAIN. [stated]
-- Arian, asked whether the codes made before 1844's rule (a client's code is
-- four letters, "the 4 letters should only be a letter") should be made
-- again: "yes". A client whose code holds anything but letters and digits
-- (SE() for "Sample (Daniel)") is given the code the portal now makes from its
-- name (generateUniqueJobCode, the one rule, worked out by an administrator's
-- portal and checked here), and every reference made with the old code is
-- renamed with it: its engagements' and proposals' codes (SE()-001 is
-- SEDL-001), the codes kept on their findings, and its invoices still in
-- draft that no accounting system has been given. An invoice already sent
-- keeps its number (the client and the books have it), and so does a draft
-- already in Xero. Each renamed engagement's timeline says what its reference
-- was. Digits are left as they are: a random reference (1317) has them by
-- design.
-- ═══════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public._code_has_symbol(p text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $codesym$
  SELECT COALESCE(btrim(COALESCE(p, '')) ~ '[^A-Za-z0-9]', false);
$codesym$;
REVOKE ALL ON FUNCTION public._code_has_symbol(text) FROM PUBLIC, anon, authenticated;

-- A reference made with a code: the code itself, or the code and a hyphen
-- and what follows (SE()-001, SE()-INV001). Compared as text, never as a
-- pattern: an old code may hold % or _.
CREATE OR REPLACE FUNCTION public._code_ref_of(p_ref text, p_code text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $coderef$
  SELECT COALESCE(p_code <> '' AND (btrim(p_ref) = p_code OR left(btrim(p_ref), length(p_code) + 1) = p_code || '-'), false);
$coderef$;
REVOKE ALL ON FUNCTION public._code_ref_of(text, text) FROM PUBLIC, anon, authenticated;

-- The reference renamed: the new code in place of the old at its start.
CREATE OR REPLACE FUNCTION public._code_ref_renamed(p_ref text, p_old text, p_new text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $coderen$
  SELECT CASE WHEN public._code_ref_of(p_ref, p_old) THEN p_new || substr(btrim(p_ref), length(p_old) + 1) ELSE p_ref END;
$coderen$;
REVOKE ALL ON FUNCTION public._code_ref_renamed(text, text, text) FROM PUBLIC, anon, authenticated;

-- Each code a client was given in place of one made from symbols: what it
-- was and what it became (rpc_recode_clients), for a reference made from the
-- old code later (_code_ref_current). The database's own: no session reads or
-- writes it.
CREATE TABLE IF NOT EXISTS public._client_code_renames (
  client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,
  old_code text NOT NULL,
  new_code text NOT NULL,
  renamed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (client_id, old_code)
);
ALTER TABLE public._client_code_renames ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._client_code_renames FROM PUBLIC, anon, authenticated;

-- By an administrator, with a fresh second factor: p_codes is
-- [{ client, code }], each client's new code as the portal made it. Checked
-- here: the client's code still holds a symbol, the new one has none and is
-- no other client's, and no reference of another client's begins with it. { ok, recoded: [{ client, from, to, assessments, proposals, findings,
-- invoices, invoices_kept }], skipped: [{ client, why, code }] }.
CREATE OR REPLACE FUNCTION public.rpc_recode_clients(p_codes jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $recode$
DECLARE
  e jsonb; v_client uuid; v_new text; v_old text; c record; r record; v_ref text; v_rv bigint;
  v_done jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb;
  v_a integer; v_p integer; v_f integer; v_i integer; v_kept integer;
  v_me uuid := public.current_profile_id(); v_me_name text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.mfa_is_fresh() OR public.current_user_role() IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501';
  END IF;
  SELECT name INTO v_me_name FROM public.profiles WHERE id = v_me;
  IF jsonb_typeof(p_codes) IS DISTINCT FROM 'array' OR jsonb_array_length(p_codes) > 1000 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Nothing to re-code.');
  END IF;
  -- One re-coding at a time, whoever asks.
  PERFORM pg_advisory_xact_lock(hashtext('pental_recode_clients'));
  FOR e IN SELECT x FROM jsonb_array_elements(p_codes) AS x LOOP
    v_client := NULL;
    IF jsonb_typeof(e) = 'object' AND COALESCE(e ->> 'client', '') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
      v_client := (e ->> 'client')::uuid;
    END IF;
    IF v_client IS NULL THEN CONTINUE; END IF;
    v_new := upper(btrim(COALESCE(e ->> 'code', '')));
    SELECT id, job_code INTO c FROM public.clients WHERE id = v_client FOR UPDATE;
    IF NOT FOUND THEN v_skipped := v_skipped || jsonb_build_object('client', v_client, 'why', 'gone'); CONTINUE; END IF;
    v_old := btrim(COALESCE(c.job_code, ''));
    IF NOT public._code_has_symbol(v_old) THEN
      v_skipped := v_skipped || jsonb_build_object('client', v_client, 'why', 'letters'); CONTINUE;
    END IF;
    -- Letters (a code made from the name), or letters and digits (a random
    -- reference, 1317): never a symbol.
    IF v_new !~ '^[A-Z0-9]{2,8}$' THEN
      v_skipped := v_skipped || jsonb_build_object('client', v_client, 'why', 'not_letters', 'code', left(v_new, 20)); CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM public.clients WHERE id <> v_client AND upper(btrim(COALESCE(job_code, ''))) = v_new)
       OR EXISTS (SELECT 1 FROM public.assessments WHERE client_id IS DISTINCT FROM v_client AND public._code_ref_of(upper(job_code), v_new))
       OR EXISTS (SELECT 1 FROM public.proposals WHERE client_id IS DISTINCT FROM v_client AND public._code_ref_of(upper(job_code), v_new))
       OR EXISTS (SELECT 1 FROM public.invoices WHERE client_id IS DISTINCT FROM v_client AND public._code_ref_of(upper(invoice_number), v_new)) THEN
      v_skipped := v_skipped || jsonb_build_object('client', v_client, 'why', 'taken', 'code', v_new); CONTINUE;
    END IF;
    v_a := 0; v_p := 0; v_f := 0; v_i := 0; v_kept := 0;
    UPDATE public.clients SET job_code = v_new WHERE id = v_client;
    -- What it was, for a reference made from it later (_code_ref_current).
    INSERT INTO public._client_code_renames (client_id, old_code, new_code) VALUES (v_client, v_old, v_new)
      ON CONFLICT (client_id, old_code) DO UPDATE SET new_code = EXCLUDED.new_code, renamed_at = now();
    -- The engagements, each with a line on its timeline.
    FOR r IN SELECT id, job_code FROM public.assessments WHERE client_id = v_client AND public._code_ref_of(job_code, v_old) FOR UPDATE LOOP
      v_ref := public._code_ref_renamed(r.job_code, v_old, v_new);
      UPDATE public.assessments SET job_code = v_ref WHERE id = r.id;
      -- Written as the portal writes its own (the sentence is the title and
      -- the event), so every view of the log reads the whole of it.
      INSERT INTO public.timeline_events (assessment_id, type, title, event, details, user_id, user_name)
      VALUES (r.id, 'reference', 'Reference changed from ' || btrim(r.job_code) || ' to ' || v_ref, 'Reference changed from ' || btrim(r.job_code) || ' to ' || v_ref,
              'Client codes hold no symbols now, so ' || v_old || ' is ' || v_new || '.', v_me, v_me_name);
      v_a := v_a + 1;
    END LOOP;
    UPDATE public.proposals SET job_code = public._code_ref_renamed(job_code, v_old, v_new)
     WHERE client_id = v_client AND public._code_ref_of(job_code, v_old);
    GET DIAGNOSTICS v_p = ROW_COUNT;
    -- The codes kept on its findings. Their words do not change, so a QA
    -- review of one (assessments.qa_reviewed, which marks a finding by its
    -- row_version, moved by any change) stays a review of it.
    FOR r IN SELECT f.id, f.assessment_id, f.row_version AS was FROM public.findings f
              WHERE f.assessment_id IN (SELECT id FROM public.assessments WHERE client_id = v_client)
                AND public._code_ref_of(f.finding_code, v_old) FOR UPDATE OF f LOOP
      UPDATE public.findings SET finding_code = public._code_ref_renamed(finding_code, v_old, v_new)
       WHERE id = r.id RETURNING row_version INTO v_rv;
      IF r.was IS NOT NULL AND v_rv IS NOT NULL THEN
        UPDATE public.assessments
           SET qa_reviewed = jsonb_set(qa_reviewed, ARRAY[r.id::text, 'rev'], to_jsonb(v_rv))
         WHERE id = r.assessment_id AND jsonb_typeof(qa_reviewed -> r.id::text) = 'object'
           AND (qa_reviewed -> r.id::text ->> 'rev') = r.was::text;
      END IF;
      v_f := v_f + 1;
    END LOOP;
    -- Invoices: a draft no accounting system has is renamed; one sent, or
    -- in Xero, keeps the number it was given.
    FOR r IN SELECT i.id, i.invoice_number, i.status,
                    EXISTS (SELECT 1 FROM public.invoice_external_links l WHERE l.invoice_id = i.id) AS linked
               FROM public.invoices i
              WHERE i.client_id = v_client AND public._code_ref_of(i.invoice_number, v_old) FOR UPDATE OF i LOOP
      IF COALESCE(r.status, 'draft') = 'draft' AND NOT r.linked THEN
        UPDATE public.invoices SET invoice_number = public._code_ref_renamed(r.invoice_number, v_old, v_new), updated_at = now() WHERE id = r.id;
        v_i := v_i + 1;
      ELSE
        v_kept := v_kept + 1;
      END IF;
    END LOOP;
    v_done := v_done || jsonb_build_object('client', v_client, 'from', v_old, 'to', v_new, 'assessments', v_a, 'proposals', v_p,
      'findings', v_f, 'invoices', v_i, 'invoices_kept', v_kept);
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'recoded', v_done, 'skipped', v_skipped);
END $recode$;
REVOKE ALL ON FUNCTION public.rpc_recode_clients(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_recode_clients(jsonb) TO authenticated;

-- A REFERENCE MADE FROM A CODE THE CLIENT NO LONGER HAS. A portal that has
-- not heard of the re-code yet (its realtime connection down, or in the
-- moment between the re-code and the news of it) makes a new engagement's,
-- proposal's, finding's or invoice's reference from the code it still holds,
-- which would leave SE()-003 for good beside SEDL-001 and SEDL-002 (an
-- independent review of 1845 found this). Such a reference is renamed as it
-- is written, to the client's code as it is now, from the record of each code
-- the client was given in place of another (_client_code_renames). Only a
-- reference being written (made, or changed to one): what is saved beside a
-- reference that was kept leaves it as it is. An invoice is renamed as
-- rpc_recode_clients renames one: in draft, and not once it is in an
-- accounting system.
CREATE OR REPLACE FUNCTION public._code_ref_current() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $coderefnow$
DECLARE v_ref text; v_was text; v_client uuid; v_old text; v_now text;
BEGIN
  IF TG_TABLE_NAME = 'invoices' THEN
    v_ref := NEW.invoice_number;
    IF TG_OP = 'UPDATE' THEN v_was := OLD.invoice_number; END IF;
    IF COALESCE(NEW.status, 'draft') <> 'draft' THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND EXISTS (SELECT 1 FROM public.invoice_external_links l WHERE l.invoice_id = NEW.id) THEN RETURN NEW; END IF;
  ELSIF TG_TABLE_NAME = 'findings' THEN
    v_ref := NEW.finding_code;
    IF TG_OP = 'UPDATE' THEN v_was := OLD.finding_code; END IF;
  ELSE
    v_ref := NEW.job_code;
    IF TG_OP = 'UPDATE' THEN v_was := OLD.job_code; END IF;
  END IF;
  IF v_ref IS NULL OR btrim(v_ref) = '' OR (TG_OP = 'UPDATE' AND v_ref IS NOT DISTINCT FROM v_was) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'findings' THEN
    SELECT a.client_id INTO v_client FROM public.assessments a WHERE a.id = NEW.assessment_id;
    v_client := COALESCE(v_client, NEW.client_id);
  ELSE
    v_client := NEW.client_id;
  END IF;
  IF v_client IS NULL THEN RETURN NEW; END IF;
  -- The longest old code first, should one ever begin another.
  SELECT r.old_code INTO v_old FROM public._client_code_renames r
   WHERE r.client_id = v_client AND public._code_ref_of(v_ref, r.old_code)
   ORDER BY length(r.old_code) DESC LIMIT 1;
  IF v_old IS NULL THEN RETURN NEW; END IF;
  SELECT btrim(COALESCE(c.job_code, '')) INTO v_now FROM public.clients c WHERE c.id = v_client;
  IF COALESCE(v_now, '') = '' OR v_now = v_old OR public._code_has_symbol(v_now) THEN RETURN NEW; END IF;
  v_ref := public._code_ref_renamed(v_ref, v_old, v_now);
  IF TG_TABLE_NAME = 'invoices' THEN NEW.invoice_number := v_ref;
  ELSIF TG_TABLE_NAME = 'findings' THEN NEW.finding_code := v_ref;
  ELSE NEW.job_code := v_ref;
  END IF;
  RETURN NEW;
END $coderefnow$;
REVOKE ALL ON FUNCTION public._code_ref_current() FROM PUBLIC, anon, authenticated;

-- First of each table's triggers (a0_ sorts before aa_invoice_before_write,
-- which then makes a number already taken its own, as for any other).
DROP TRIGGER IF EXISTS a0_code_ref_current ON public.assessments;
CREATE TRIGGER a0_code_ref_current BEFORE INSERT OR UPDATE OF job_code ON public.assessments
  FOR EACH ROW EXECUTE FUNCTION public._code_ref_current();
DROP TRIGGER IF EXISTS a0_code_ref_current ON public.proposals;
CREATE TRIGGER a0_code_ref_current BEFORE INSERT OR UPDATE OF job_code ON public.proposals
  FOR EACH ROW EXECUTE FUNCTION public._code_ref_current();
DROP TRIGGER IF EXISTS a0_code_ref_current ON public.findings;
CREATE TRIGGER a0_code_ref_current BEFORE INSERT OR UPDATE OF finding_code ON public.findings
  FOR EACH ROW EXECUTE FUNCTION public._code_ref_current();
DROP TRIGGER IF EXISTS a0_code_ref_current ON public.invoices;
CREATE TRIGGER a0_code_ref_current BEFORE INSERT OR UPDATE OF invoice_number ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public._code_ref_current();

-- ═══════════════════════════════════════════════════════════════════════════
-- 1841: THE SECOND FACTOR FOR PEOPLE AND SETTINGS. Every other table's writes
-- ask mfa_is_fresh(); these did not. With a password alone (an
-- administrator's, never its second factor) a session could add an
-- administrator at an address of its own, whose first sign-in enrols a
-- second factor of its own choosing, or point the firm's email at another
-- server and read every sign-in link sent after. Reading stays as it was: the
-- sign-in reads a person's own row before any second factor, by design.
-- ═══════════════════════════════════════════════════════════════════════════
DROP POLICY IF EXISTS settings_admin_insert ON public.settings;
DROP POLICY IF EXISTS settings_admin_update ON public.settings;
DROP POLICY IF EXISTS settings_admin_delete ON public.settings;
CREATE POLICY settings_admin_insert ON public.settings FOR INSERT TO authenticated WITH CHECK (public.current_user_role() = 'admin' AND public.mfa_is_fresh());
CREATE POLICY settings_admin_update ON public.settings FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin','senior') AND public.mfa_is_fresh()) WITH CHECK (true);
CREATE POLICY settings_admin_delete ON public.settings FOR DELETE TO authenticated USING (public.current_user_role() = 'admin' AND public.mfa_is_fresh());
DROP POLICY IF EXISTS profiles_manage_insert ON public.profiles;
DROP POLICY IF EXISTS profiles_update ON public.profiles;
DROP POLICY IF EXISTS profiles_manage_delete ON public.profiles;
CREATE POLICY profiles_manage_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (public.can_manage() AND public.mfa_is_fresh());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (public.mfa_is_fresh() AND (public.can_manage() OR (auth_user_id = auth.uid() AND active = true))) WITH CHECK (true);
CREATE POLICY profiles_manage_delete ON public.profiles FOR DELETE TO authenticated USING (public.can_manage() AND public.mfa_is_fresh());

-- ═══════════════════════════════════════════════════════════════════════════
-- 1841: A CONTRACTOR REACHES THEIR OWN WORK, AND EVERY TABLE ASKS FOR THE
-- SECOND FACTOR. [stated] Arian: "do a full QA audit". Found by it, here:
--   - a contractor (an outside tester, who sees only the engagements they
--     lead) could change ANY finding, file, client, ticket, timeline line or
--     checklist tick by its id, read every proposal and every internal comment,
--     and change or delete the firm's own checklists and runbooks;
--   - the checklists, their ticks, a client's scan targets and cadences asked
--     for no second factor.
-- A contractor's rows are now those of the engagements they lead and the
-- clients they work with (can_access_assessment, can_access_client, the
-- helpers the read rules already use), a write is checked on the row it
-- leaves as well as the one it finds, and every rule asks mfa_is_fresh().
-- The firm's own people are unchanged.
-- ═══════════════════════════════════════════════════════════════════════════
DROP POLICY IF EXISTS findings_update ON public.findings;
-- 1970: and not Sales or Marketing (is_delivery_staff).
CREATE POLICY findings_update ON public.findings FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND (public.is_delivery_staff() OR (public.current_user_role() = 'contractor' AND public.can_access_assessment(assessment_id))))
  WITH CHECK (public.is_delivery_staff() OR (public.current_user_role() = 'contractor' AND public.can_access_assessment(assessment_id)));

DROP POLICY IF EXISTS afile_update ON public.assessment_files;
-- 1970: is_delivery_staff, as every rule on an engagement's work says now
-- (can_write already left Sales and Marketing out of both).
CREATE POLICY afile_update ON public.assessment_files FOR UPDATE TO authenticated
  USING (public.mfa_is_fresh() AND public.can_write() AND (public.is_delivery_staff() OR public.can_access_assessment(assessment_id)))
  WITH CHECK (public.is_delivery_staff() OR public.can_access_assessment(assessment_id));
