  USING (public.mfa_is_fresh() AND (
    (public.can_write() AND (public.is_delivery_staff() OR public.can_access_assessment(assessment_id)))
    OR (public.current_user_role() = 'client' AND uploaded_by_client IS TRUE AND uploaded_by = public.current_profile_id() AND public.can_access_assessment(assessment_id))));

