-- Whether a client has accepted a scan's authorisation is the firm's
-- business, asked inside rpc_client_request_scan; it was open to anybody.
REVOKE ALL ON FUNCTION public._scan_auth_on_file(uuid) FROM PUBLIC, anon, authenticated;

-- A finding removed sets its scan results' finding_id to null, which looked
-- for them one table scan per finding; and the sign-in sweep clears by time.
CREATE INDEX IF NOT EXISTS scan_results_finding_idx ON public.scan_results (finding_id) WHERE finding_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS _signin_hits_at_idx ON public._signin_hits (at);

-- pg_cron keeps a line for every run of every job, and the call clock runs
-- every ten seconds: a database's run history grew by thousands of lines a
-- day for good. The tickets', mail's and Xero's clocks cleared their own;
-- this clears every pental- job's, older than a day, in the 23rd minute of
-- each hour, from the call clock and the scan clock (_net_tick, _scan_tick),
-- 20,000 lines a call, so a database with months of history behind it
-- catches up over a few hours rather than holding one clock up for long.
-- Returns how many lines went.
CREATE OR REPLACE FUNCTION public._cron_tidy(p_any_minute boolean DEFAULT false) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $crontidy$
DECLARE v_n integer := 0;
BEGIN
  IF to_regclass('cron.job_run_details') IS NULL THEN RETURN 0; END IF;
  IF NOT COALESCE(p_any_minute, false) AND extract(minute FROM now()) <> 23 THEN RETURN 0; END IF;
  IF NOT pg_try_advisory_xact_lock(hashtext('pental_cron_tidy')) THEN RETURN 0; END IF;
  BEGIN
    EXECUTE $q$DELETE FROM cron.job_run_details WHERE runid IN (
                 SELECT d.runid FROM cron.job_run_details d
                  WHERE d.end_time < now() - interval '1 day'
                    AND d.jobid IN (SELECT j.jobid FROM cron.job j WHERE j.jobname LIKE 'pental-%')
                  LIMIT 20000)$q$;
    GET DIAGNOSTICS v_n = ROW_COUNT;
  EXCEPTION WHEN OTHERS THEN RETURN 0;
  END;
  RETURN v_n;
END $crontidy$;
REVOKE ALL ON FUNCTION public._cron_tidy(boolean) FROM PUBLIC, anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1847: SHAREPOINT AND GOOGLE DRIVE, KEPT IN STEP WITH THE PORTAL.
--
-- [stated] Arian: "i want something implemented to sync into sharepoint, and
-- be editable in settings sharepoint integration to create folders and put
-- all relevant files from the portal into the folder, and directory stuff all
-- editable, like assessment files can go into a folder or just free into the
-- job folder with names editable. modern, beautiful seamless. fully
-- customisable and editable"; "same with google workspace as well"; "there
-- may be m365/ google workspace permissions already enabled so it could just
-- be a case of enabling to do that as well right? by default it should be off
-- and enablable".
--
-- One way, the portal to SharePoint or Google Drive, through the firm's own
-- applications: Microsoft through its Teams application (Sites.ReadWrite.All,
-- or Sites.Selected for one site), Google through its Google sign-in
-- application with Drive's drive.file scope (it reaches only what it made).
-- Every call is made by this database (pg_net, or a gateway's call worker
-- from 1.13.0): the secrets and the Drive's lasting access never leave it,
-- and nothing passes through Pental. A file's bytes go through a one-file
-- upload address this database asks for (Graph's upload session, Drive's
-- resumable upload) straight to Microsoft or Google: behind a gateway, from
-- the gateway itself (1.13.0), which reads them where it keeps them; on
-- Supabase, from the browser of a signed-in member of the firm's team who
-- may read the file, while the portal is open. What arrived is checked from
-- here before it counts. Off until the firm turns it on; nothing is removed
-- there unless it says so; nothing but files (no credentials).
-- ═══════════════════════════════════════════════════════════════════════════

-- The firm's choices, in a table of their own: read and written only through
-- the functions below (administrators and seniors, with a fresh second
-- factor), so no session reads them with the rest of the settings and no
-- client sees where the firm keeps its files.
CREATE TABLE IF NOT EXISTS public._docs_config (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  cfg jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid
);
ALTER TABLE public._docs_config ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_config FROM PUBLIC, anon, authenticated;

-- The kinds of file kept in step, in Settings' order: what each is called,
-- whether it is kept until the firm says otherwise, the folder it goes in
-- within its engagement's (or, for a client's own paperwork, its client's),
-- and its name ({file}: the name it has in the portal).
CREATE OR REPLACE FUNCTION public._docs_kinds() RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dskinds$
  SELECT '[
    {"k":"report","label":"Reports","hint":"The final report, and report PDFs added to the engagement","on":true,"folder":"Reports","name":"{file}","level":"job"},
    {"k":"attestation","label":"Attestations","hint":"The final attestation, and attestation PDFs added to the engagement","on":true,"folder":"Reports","name":"{file}","level":"job"},
    {"k":"edited","label":"Edited Word report","hint":"The Word report as it was edited and delivered","on":true,"folder":"Reports","name":"{file}","level":"job"},
    {"k":"paperwork","label":"Proposal and invoice documents","hint":"Proposal and invoice PDFs added to the engagement","on":true,"folder":"Paperwork","name":"{file}","level":"job"},
    {"k":"files","label":"Engagement files","hint":"Everything else the team adds to the engagement","on":true,"folder":"Files","name":"{file}","level":"job"},
    {"k":"client","label":"Files from the client","hint":"What the client uploads to the portal","on":true,"folder":"From the client","name":"{file}","level":"job"},
    {"k":"scans","label":"Scans","hint":"Scan reports, and files attached to a scan of the engagement","on":true,"folder":"Scans","name":"{file}","level":"job"},
    {"k":"evidence","label":"Pictures in findings","hint":"Each picture pasted into a finding, as its own file","on":false,"folder":"Pictures","name":"{file}","level":"job"},
    {"k":"proposals","label":"Proposals","hint":"Each proposal''s PDF, in its client''s folder","on":false,"folder":"Proposals","name":"{file}","level":"client"},
    {"k":"invoices","label":"Invoices","hint":"Each invoice''s PDF, in its client''s folder","on":false,"folder":"Invoices","name":"{file}","level":"client"}
  ]'::jsonb;
$dskinds$;
REVOKE ALL ON FUNCTION public._docs_kinds() FROM PUBLIC, anon, authenticated;

-- ── Names ──────────────────────────────────────────────────────────────────
-- A layout as typed: the folder or name it makes, with its {tokens}, one
-- line, folders separated by "/", 200 characters at most.
CREATE OR REPLACE FUNCTION public._docs_pattern(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dspat$
  SELECT left(btrim(regexp_replace(regexp_replace(regexp_replace(COALESCE(p, ''), '[[:cntrl:]]+', ' ', 'g'),
                                                  '[ ]+', ' ', 'g'),
                                   '[ ]*/+[ ]*', '/', 'g'), ' /'), 200);
$dspat$;
REVOKE ALL ON FUNCTION public._docs_pattern(text) FROM PUBLIC, anon, authenticated;

-- One folder's or file's name as SharePoint and Drive both take it: none of
-- " * : < > ? / \ | or control characters, no space or full stop at either
-- end, not a name Windows keeps for itself (CON, AUX, COM1 and the rest),
-- not beginning ~$ (SharePoint refuses those), nothing called _vti_, at most
-- p_max characters.
CREATE OR REPLACE FUNCTION public._docs_safe(p text, p_max integer DEFAULT 120) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dssafe$
DECLARE v text := COALESCE(p, '');
BEGIN
  v := regexp_replace(v, '[[:cntrl:]"*:<>?/\\|]+', ' ', 'g');
  v := regexp_replace(v, '[[:space:]]+', ' ', 'g');
  v := btrim(v, ' .');
  WHILE left(v, 2) = '~$' LOOP v := btrim(substr(v, 3), ' .'); END LOOP;
  v := replace(v, '_vti_', 'vti');
  IF v ~* '^(con|prn|aux|nul|com[0-9]|lpt[0-9]|desktop\.ini)(\.[^.]*)?$' THEN v := v || '_'; END IF;
  IF length(v) > p_max THEN v := btrim(left(v, p_max), ' .'); END IF;
  RETURN v;
END $dssafe$;
REVOKE ALL ON FUNCTION public._docs_safe(text, integer) FROM PUBLIC, anon, authenticated;

-- A pattern with its {tokens} filled in. A value cannot make a folder of its
-- own ("/" in a client's name) or a token of its own ({file} in a name).
CREATE OR REPLACE FUNCTION public._docs_render(p_pattern text, p_vars jsonb) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsrender$
DECLARE v text := COALESCE(p_pattern, ''); k record;
BEGIN
  FOR k IN SELECT e.key, e.value FROM jsonb_each_text(CASE WHEN jsonb_typeof(p_vars) = 'object' THEN p_vars ELSE '{}'::jsonb END) AS e(key, value)
            WHERE e.key ~ '^[a-z_]{1,20}$' LOOP
    v := replace(v, '{' || k.key || '}', translate(COALESCE(k.value, ''), '/\{}', '--()'));
  END LOOP;
  RETURN v;
END $dsrender$;
REVOKE ALL ON FUNCTION public._docs_render(text, jsonb) FROM PUBLIC, anon, authenticated;

-- The folders a pattern makes, each as SharePoint and Drive take a name.
CREATE OR REPLACE FUNCTION public._docs_segments(p_pattern text, p_vars jsonb) RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $dsseg$
  SELECT COALESCE(array_agg(s.seg ORDER BY s.i) FILTER (WHERE s.seg <> ''), ARRAY[]::text[])
    FROM (SELECT x.i, public._docs_safe(x.part, 120) AS seg
            FROM unnest(string_to_array(public._docs_render(public._docs_pattern(p_pattern), p_vars), '/')) WITH ORDINALITY AS x(part, i)) s;
$dsseg$;
REVOKE ALL ON FUNCTION public._docs_segments(text, jsonb) FROM PUBLIC, anon, authenticated;

-- A file's name, with its extension whatever the name made of it.
CREATE OR REPLACE FUNCTION public._docs_file_name(p_name text, p_ext text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $dsfile$
DECLARE v_ext text := left(regexp_replace(COALESCE(p_ext, ''), '[^A-Za-z0-9]', '', 'g'), 10); v text := COALESCE(p_name, '');
BEGIN
  IF v_ext <> '' AND lower(v) LIKE '%.' || lower(v_ext) THEN v := left(v, length(v) - length(v_ext) - 1); END IF;
  v := public._docs_safe(v, 120 - CASE WHEN v_ext <> '' THEN length(v_ext) + 1 ELSE 0 END);
  IF v = '' THEN v := 'File'; END IF;
  RETURN v || CASE WHEN v_ext <> '' THEN '.' || v_ext ELSE '' END;
END $dsfile$;
REVOKE ALL ON FUNCTION public._docs_file_name(text, text) FROM PUBLIC, anon, authenticated;

-- ── The settings, as they are kept ─────────────────────────────────────────
-- { v, on, provider: 'sharepoint' | 'gdrive' | null, sharepoint: { site_url,
-- library, base_path }, gdrive: { root_name }, client_folder, job_folder,
-- kinds: { <kind>: { on, folder, name } }, remove_remote }. On only with a
-- provider. Whatever is saved is kept this way (rpc_docs_sync_save), and read
-- this way too (_docs_cfg).
CREATE OR REPLACE FUNCTION public._docs_norm(p jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $dsnorm$
DECLARE c jsonb := CASE WHEN jsonb_typeof(p) = 'object' THEN p ELSE '{}'::jsonb END;
  v_prov text := lower(btrim(COALESCE(c ->> 'provider', '')));
  sp jsonb := CASE WHEN jsonb_typeof(c -> 'sharepoint') = 'object' THEN c -> 'sharepoint' ELSE '{}'::jsonb END;
  gd jsonb := CASE WHEN jsonb_typeof(c -> 'gdrive') = 'object' THEN c -> 'gdrive' ELSE '{}'::jsonb END;
  ks jsonb := CASE WHEN jsonb_typeof(c -> 'kinds') = 'object' THEN c -> 'kinds' ELSE '{}'::jsonb END;
  k jsonb; one jsonb; v_kinds jsonb := '{}'::jsonb; v_site text; v_base text;
BEGIN
  IF v_prov NOT IN ('sharepoint', 'gdrive') THEN v_prov := NULL; END IF;
  -- A SharePoint site's address, as the browser shows it on the site:
  -- https, its host, and the site's own path; nothing after a ? or #, and no
  -- page of it (/Shared Documents/..., /SitePages/...).
  v_site := btrim(COALESCE(sp ->> 'site_url', ''));
  v_site := regexp_replace(v_site, '[?#].*$', '');
  -- A library's own page (.../Engagements/Forms/AllItems.aspx, the library
  -- with it), the site's pages, its lists and its own Documents.
  v_site := regexp_replace(v_site, '/[^/]+/Forms(/.*)?$', '', 'i');
  v_site := regexp_replace(v_site, '/(SitePages|Shared%20Documents|Shared Documents|Forms|_layouts|Lists)(/.*)?$', '', 'i');
  v_site := regexp_replace(v_site, '/[^/]*\.aspx$', '', 'i');
  v_site := rtrim(v_site, '/');
  -- On SharePoint's own hosts (Microsoft's clouds), and with no . or ..
  -- step in its path (which would reach elsewhere in Graph).
  IF length(v_site) > 300
     OR v_site !~* '^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?\.(sharepoint\.com|sharepoint\.us|sharepoint-mil\.us|sharepoint\.de|sharepoint\.cn)(:443)?(/[^[:space:][:cntrl:]"<>\\^`{|}#?]*)?$'
     OR v_site ~ '/\.\.?(/|$)' OR v_site ~* '%2e|%2f|%5c' THEN
    v_site := '';
  END IF;
  v_base := array_to_string(public._docs_segments(sp ->> 'base_path', '{}'::jsonb), '/');
  FOR k IN SELECT x FROM jsonb_array_elements(public._docs_kinds()) AS x LOOP
    one := CASE WHEN jsonb_typeof(ks -> (k ->> 'k')) = 'object' THEN ks -> (k ->> 'k') ELSE '{}'::jsonb END;
    v_kinds := v_kinds || jsonb_build_object(k ->> 'k', jsonb_build_object(
      'on', CASE WHEN jsonb_typeof(one -> 'on') = 'boolean' THEN (one ->> 'on')::boolean ELSE (k ->> 'on')::boolean END,
      'folder', public._docs_pattern(CASE WHEN jsonb_typeof(one -> 'folder') = 'string' THEN one ->> 'folder' ELSE k ->> 'folder' END),
      'name', COALESCE(NULLIF(public._docs_pattern(CASE WHEN jsonb_typeof(one -> 'name') = 'string' THEN one ->> 'name' END), ''), '{file}')));
  END LOOP;
  RETURN jsonb_build_object('v', 1,
    'on', v_prov IS NOT NULL AND COALESCE(CASE WHEN jsonb_typeof(c -> 'on') = 'boolean' THEN (c ->> 'on')::boolean END, false),
    'provider', v_prov,
    'sharepoint', jsonb_build_object('site_url', v_site,
       'library', public._docs_safe(COALESCE(sp ->> 'library', ''), 120),
       'base_path', v_base),
    'gdrive', jsonb_build_object('root_name', public._docs_safe(COALESCE(gd ->> 'root_name', ''), 120)),
    'client_folder', CASE WHEN jsonb_typeof(c -> 'client_folder') = 'string' THEN public._docs_pattern(c ->> 'client_folder') ELSE '{client}' END,
    'job_folder', CASE WHEN jsonb_typeof(c -> 'job_folder') = 'string' THEN public._docs_pattern(c ->> 'job_folder') ELSE '{job_code} {assessment}' END,
    'kinds', v_kinds,
    'remove_remote', COALESCE(CASE WHEN jsonb_typeof(c -> 'remove_remote') = 'boolean' THEN (c ->> 'remove_remote')::boolean END, false));
END $dsnorm$;
REVOKE ALL ON FUNCTION public._docs_norm(jsonb) FROM PUBLIC, anon, authenticated;

-- The settings as kept now.
CREATE OR REPLACE FUNCTION public._docs_cfg() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dscfg$
  SELECT public._docs_norm(COALESCE((SELECT x.cfg FROM public._docs_config x WHERE x.id), '{}'::jsonb));
$dscfg$;
REVOKE ALL ON FUNCTION public._docs_cfg() FROM PUBLIC, anon, authenticated;

-- ── What is kept here ──────────────────────────────────────────────────────
-- Google Drive's lasting access (its refresh token, sealed as the settings'
-- secrets are), with the account it is for and the application it was given
-- to; one row. The access for the hour, unlogged.
CREATE TABLE IF NOT EXISTS public._docs_google (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  refresh_enc bytea,
  account text,
  scope text,
  client_hash text,
  connected_at timestamptz,
  connected_by uuid,
  broken_at timestamptz,
  broken_reason text
);
ALTER TABLE public._docs_google ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_google FROM PUBLIC, anon, authenticated;

CREATE UNLOGGED TABLE IF NOT EXISTS public._docs_google_cache (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  fp text,
  token text,
  expires_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public._docs_google_cache SET UNLOGGED;
ALTER TABLE public._docs_google_cache ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_google_cache FROM PUBLIC, anon, authenticated;

-- Google's consent in flight: the state the browser carries there and back,
-- the PKCE verifier (never sent anywhere but Google's token address), the
-- address it comes back to, and who asked. Unlogged, and gone in a quarter
-- of an hour.
CREATE UNLOGGED TABLE IF NOT EXISTS public._docs_pending (
  state text PRIMARY KEY,
  verifier text NOT NULL,
  redirect_uri text NOT NULL,
  origin text NOT NULL,
  client_id text NOT NULL,
  asked_by uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  used_at timestamptz,
  job uuid
);
ALTER TABLE public._docs_pending SET UNLOGGED;
ALTER TABLE public._docs_pending ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_pending FROM PUBLIC, anon, authenticated;

-- Where the files go, as found: SharePoint's site, its library and the base
-- folder in it; or the Drive's own folder (base). One row, for the target it
-- was found for (target_key; another site, library, base folder, Drive
-- account or folder name is another target, found afresh).
CREATE TABLE IF NOT EXISTS public._docs_target (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  target_key text,
  provider text,
  site_id text,
  site_url text,
  site_name text,
  drive_id text,
  drive_name text,
  base_id text,
  base_url text,
  ready boolean NOT NULL DEFAULT false,
  checking boolean NOT NULL DEFAULT false,
  job uuid,
  checked_at timestamptz,
  error text,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public._docs_target ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_target FROM PUBLIC, anon, authenticated;

-- A folder made (or found) there, by its path below the base, for its target.
CREATE TABLE IF NOT EXISTS public._docs_folders (
  target_key text NOT NULL,
  path text NOT NULL,
  remote_id text NOT NULL,
  web_url text,
  made_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (target_key, path)
);
ALTER TABLE public._docs_folders ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_folders FROM PUBLIC, anon, authenticated;

-- Each file kept in step: where it is here (its stored name, kind, engagement
-- and client, name, size and version), where it went there, and how it is
-- getting on: pending, linking (its folders and upload address being asked
-- for), uploading (a gateway or a browser sending it), verifying (asked of
-- SharePoint or Drive), done, failed (asked again in a while), held (three
-- goes failed: waits for Sync now), gone (removed here, left there),
-- removing, removed, off (its kind is not kept). Who is sending it: a person
-- (lease_by, their browser) or a gateway's worker (lease_worker). Read only
-- through the functions below.
CREATE TABLE IF NOT EXISTS public._docs_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  target_key text NOT NULL,
  provider text NOT NULL,
  source text NOT NULL,
  kind text NOT NULL,
  assessment_id uuid,
  client_id uuid,
  file_name text NOT NULL,
  size bigint,
  version text,
  file_at timestamptz,
  state text NOT NULL DEFAULT 'pending',
  attempts integer NOT NULL DEFAULT 0,
  next_at timestamptz NOT NULL DEFAULT now(),
  last_error text,
  lease_by uuid,
  lease_worker text,
  lease_until timestamptz,
  origin text,
  taken_version text,
  folders text[],
  name text,
  parent_id text,
  job uuid,
  candidate_id text,
  candidate_size bigint,
  session_at timestamptz,
  remote_id text,
  remote_name text,
  remote_parent text,
  remote_url text,
  remote_path text,
  synced_version text,
  synced_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT _docs_items_state CHECK (state IN ('pending', 'linking', 'uploading', 'verifying', 'done', 'failed', 'held', 'gone', 'removing', 'removed', 'off')),
  CONSTRAINT _docs_items_provider CHECK (provider IN ('sharepoint', 'gdrive')),
  CONSTRAINT _docs_items_one UNIQUE (target_key, source)
);
-- What arrived and how big it was said to be, kept until it is checked; and
-- when its upload address was last asked for (a file whose sender went away
-- after sending it is looked for there before it is sent again).
ALTER TABLE public._docs_items ADD COLUMN IF NOT EXISTS candidate_size bigint;
ALTER TABLE public._docs_items ADD COLUMN IF NOT EXISTS session_at timestamptz;
CREATE INDEX IF NOT EXISTS _docs_items_due_idx ON public._docs_items (target_key, state, next_at);
CREATE INDEX IF NOT EXISTS _docs_items_lease_idx ON public._docs_items (lease_by) WHERE lease_by IS NOT NULL;
ALTER TABLE public._docs_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_items FROM PUBLIC, anon, authenticated;

-- A file's upload address, which lets whoever holds it write that one file
-- there until it lapses: for the gateway or the browser sending it, and no
-- one else. Unlogged; gone once the file has arrived or failed.
CREATE UNLOGGED TABLE IF NOT EXISTS public._docs_links (
  item_id uuid PRIMARY KEY,
  url text NOT NULL,
  provider text NOT NULL,
  for_user uuid,
  for_worker text,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT _docs_links_for CHECK (for_user IS NOT NULL OR for_worker IS NOT NULL)
);
ALTER TABLE public._docs_links SET UNLOGGED;
ALTER TABLE public._docs_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_links FROM PUBLIC, anon, authenticated;

-- When the files here were last looked through, and what was found.
CREATE TABLE IF NOT EXISTS public._docs_state (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  scanned_at timestamptz,
  scanned integer,
  scan_error text,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public._docs_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_state FROM PUBLIC, anon, authenticated;
INSERT INTO public._docs_state (id) VALUES (true) ON CONFLICT (id) DO NOTHING;

-- ── Google's access ────────────────────────────────────────────────────────
-- The Drive's lasting access as sealed here, opened only to be sent to
-- Google's token address.
CREATE OR REPLACE FUNCTION public._docs_google_refresh() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsgref$
  SELECT NULLIF(public._settings_decrypt(g.refresh_enc), '') FROM public._docs_google g WHERE g.id AND g.broken_at IS NULL;
$dsgref$;
REVOKE ALL ON FUNCTION public._docs_google_refresh() FROM PUBLIC, anon, authenticated;

-- Which lasting access and application an hour's access came from.
CREATE OR REPLACE FUNCTION public._docs_google_fp() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsgfp$
  SELECT encode(extensions.digest(COALESCE(public._docs_google_refresh(), '') || chr(31)
    || COALESCE((SELECT btrim(s.sso_google_client_id) FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1), ''), 'sha256'), 'hex');
$dsgfp$;
REVOKE ALL ON FUNCTION public._docs_google_fp() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._docs_drive_token_now() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgtok$
  SELECT c.token FROM public._docs_google_cache c
   WHERE c.id AND c.token IS NOT NULL AND c.expires_at > now() + interval '1 minute' AND c.fp = public._docs_google_fp();
$dsgtok$;
REVOKE ALL ON FUNCTION public._docs_drive_token_now() FROM PUBLIC, anon, authenticated;

-- Whether Google Drive is connected (an account, its lasting access readable
-- here, for the sign-in application saved now).
CREATE OR REPLACE FUNCTION public._docs_google_connected() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsgcon$
  SELECT EXISTS (SELECT 1 FROM public._docs_google g
                  WHERE g.id AND g.broken_at IS NULL AND g.refresh_enc IS NOT NULL AND COALESCE(g.account, '') <> ''
                    AND g.client_hash = encode(extensions.digest(COALESCE((SELECT btrim(s.sso_google_client_id) FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1), ''), 'sha256'), 'hex'));
$dsgcon$;
REVOKE ALL ON FUNCTION public._docs_google_connected() FROM PUBLIC, anon, authenticated;

-- ── The target ─────────────────────────────────────────────────────────────
-- Which target the settings name: NULL where they name none yet.
CREATE OR REPLACE FUNCTION public._docs_target_key(c jsonb) RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dstkey$
DECLARE v_acct text;
BEGIN
  IF c ->> 'provider' = 'sharepoint' THEN
    IF COALESCE(c #>> '{sharepoint,site_url}', '') = '' THEN RETURN NULL; END IF;
    RETURN encode(extensions.digest('sp' || chr(31) || lower(c #>> '{sharepoint,site_url}') || chr(31) || lower(COALESCE(c #>> '{sharepoint,library}', ''))
      || chr(31) || lower(COALESCE(c #>> '{sharepoint,base_path}', '')), 'sha256'), 'hex');
  ELSIF c ->> 'provider' = 'gdrive' THEN
    IF NOT public._docs_google_connected() THEN RETURN NULL; END IF;
    SELECT lower(g.account) INTO v_acct FROM public._docs_google g WHERE g.id;
    RETURN encode(extensions.digest('gd' || chr(31) || COALESCE(v_acct, '') || chr(31) || lower(public._docs_root_name(c)), 'sha256'), 'hex');
  END IF;
  RETURN NULL;
END $dstkey$;
REVOKE ALL ON FUNCTION public._docs_target_key(jsonb) FROM PUBLIC, anon, authenticated;

-- The Drive folder everything goes in: as the firm named it, or its name.
CREATE OR REPLACE FUNCTION public._docs_root_name(c jsonb) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsroot$
  SELECT COALESCE(NULLIF(c #>> '{gdrive,root_name}', ''),
                  NULLIF(public._docs_safe((SELECT s.company_name FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1), 120), ''),
                  'Client files');
$dsroot$;
REVOKE ALL ON FUNCTION public._docs_root_name(jsonb) FROM PUBLIC, anon, authenticated;

-- Whether the files can be kept in step from here now: NULL where they can,
-- or { code, error }: unavailable (being moved, or nothing here makes calls
-- out), off, not_set_up, no_app (the Teams application, or the Google
-- sign-in application, is not saved), not_connected (Drive), config (a
-- secret sealed with another key), gateway_old (a gateway before 1.13.0).
CREATE OR REPLACE FUNCTION public._docs_cannot(c jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dscannot$
DECLARE t jsonb; v_sender text;
BEGIN
  IF public._xero_stood_down() IS NOT NULL THEN
    RETURN jsonb_build_object('code', 'unavailable', 'error', 'Nothing is sent while this portal''s database is being moved. It carries on once the move has finished.');
  END IF;
  IF c ->> 'provider' IS NULL THEN
    RETURN jsonb_build_object('code', 'not_set_up', 'error', 'Choose SharePoint or Google Drive first.');
  END IF;
  IF c ->> 'provider' = 'sharepoint' THEN
    -- 1848: with whichever of the firm's Microsoft applications reaches it.
    t := public._docs_ms_app();
    IF t IS NULL THEN
      RETURN jsonb_build_object('code', 'no_app', 'error', 'SharePoint is reached with a Microsoft application of your firm''s own: save your Teams application (Settings, Integrations, Microsoft Teams) or your own Microsoft sign-in (Settings, Login Page, Single sign-on).');
    END IF;
    IF COALESCE((t ->> 'undecryptable')::boolean, false) THEN
      RETURN jsonb_build_object('code', 'config', 'error', CASE WHEN t ->> 'via' = 'teams'
        THEN 'The saved Teams secret cannot be read here (it was sealed with another key). Enter it again in Settings, Integrations, Microsoft Teams.'
        ELSE 'The saved Microsoft sign-in secret cannot be read here (it was sealed with another key). Enter it again in Settings, Login Page, Single sign-on.' END);
    END IF;
    IF t ->> 'tenant' IS NULL THEN
      RETURN jsonb_build_object('code', 'needs_access', 'error', 'Give your Microsoft sign-in application access to SharePoint first: an administrator of your Microsoft 365 signs in once, from here.');
    END IF;
    IF COALESCE(c #>> '{sharepoint,site_url}', '') = '' THEN
      RETURN jsonb_build_object('code', 'not_set_up', 'error', 'Enter the address of the SharePoint site the files go to.');
    END IF;
  ELSE
    IF NOT public._sso_own('google') THEN
      RETURN jsonb_build_object('code', 'no_app', 'error', 'Google Drive is reached with your Google sign-in application: save its client ID and secret in Settings, Login Page, Single sign-on.');
    END IF;
    IF NOT public._docs_google_connected() THEN
      RETURN jsonb_build_object('code', 'not_connected', 'error',
        COALESCE((SELECT 'Google no longer lets the portal reach ' || COALESCE(g.account, 'the Drive') || ': connect it again.' FROM public._docs_google g WHERE g.id AND g.broken_at IS NOT NULL),
                 'Connect Google Drive first.'));
    END IF;
  END IF;
  v_sender := public._net_sender();
  IF v_sender IS NULL THEN
    RETURN jsonb_build_object('code', 'unavailable', 'error', 'This portal''s database cannot reach ' || CASE WHEN c ->> 'provider' = 'sharepoint' THEN 'Microsoft' ELSE 'Google' END || ' just now. It tries again in a few minutes.');
  END IF;
  IF v_sender = 'gateway' AND NOT public._net_gateway_can(CASE WHEN c ->> 'provider' = 'sharepoint' THEN 'docs_graph' ELSE 'drive' END) THEN
    RETURN jsonb_build_object('code', 'gateway_old', 'error', 'Your Pental gateway needs its update to 1.13.0 before it can keep files in step: paste its deploy command again (the Database step on pental.io).');
  END IF;
  RETURN NULL;
END $dscannot$;
REVOKE ALL ON FUNCTION public._docs_cannot(jsonb) FROM PUBLIC, anon, authenticated;

-- ── Where each file goes ───────────────────────────────────────────────────
-- What a file's {tokens} are: its client, its engagement and itself.
CREATE OR REPLACE FUNCTION public._docs_vars(p_kind text, p_assessment uuid, p_client uuid, p_file text, p_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsvars$
DECLARE v_aname text; v_job text; v_type text; v_start date; v_created timestamptz; v_aclient uuid; v_cname text; v_ccode text;
  v_day date; v_file text := COALESCE(p_file, ''); v_ext text := ''; v_label text;
BEGIN
  IF p_assessment IS NOT NULL THEN
    SELECT x.name, x.job_code, x.type, x.start_date, x.created_at, x.client_id INTO v_aname, v_job, v_type, v_start, v_created, v_aclient
      FROM public.assessments x WHERE x.id = p_assessment;
  END IF;
  SELECT y.name, y.job_code INTO v_cname, v_ccode FROM public.clients y WHERE y.id = COALESCE(p_client, v_aclient);
  v_day := COALESCE(v_start, (v_created AT TIME ZONE 'UTC')::date, (p_at AT TIME ZONE 'UTC')::date, (now() AT TIME ZONE 'UTC')::date);
  IF v_file ~ '\.[A-Za-z0-9]{1,10}$' THEN
    v_ext := substring(v_file FROM '\.([A-Za-z0-9]{1,10})$');
    v_file := left(v_file, length(v_file) - length(v_ext) - 1);
  END IF;
  SELECT x ->> 'label' INTO v_label FROM jsonb_array_elements(public._docs_kinds()) AS x WHERE x ->> 'k' = p_kind;
  RETURN jsonb_build_object(
    'client', COALESCE(NULLIF(btrim(v_cname), ''), 'Client'),
    'client_code', COALESCE(NULLIF(btrim(v_ccode), ''), ''),
    'job_code', COALESCE(NULLIF(btrim(v_job), ''), ''),
    'assessment', COALESCE(NULLIF(btrim(v_aname), ''), ''),
    'type', COALESCE(NULLIF(btrim(v_type), ''), ''),
    'year', to_char(v_day, 'YYYY'),
    'month', to_char(v_day, 'MM'),
    'start', COALESCE(to_char(v_start, 'YYYY-MM-DD'), ''),
    'file', v_file,
    'ext', v_ext,
    'date', to_char(COALESCE((p_at AT TIME ZONE 'UTC')::date, (now() AT TIME ZONE 'UTC')::date), 'YYYY-MM-DD'),
    'kind', COALESCE(v_label, ''));
END $dsvars$;
REVOKE ALL ON FUNCTION public._docs_vars(text, uuid, uuid, text, timestamptz) FROM PUBLIC, anon, authenticated;

-- Where a file of a kind goes below the base: { folders, name }. A client's
-- folder (none where the firm leaves it blank), then for an engagement's
-- files its engagement's, then its kind's (loose where blank), at most
-- twelve deep; its name with its extension.
CREATE OR REPLACE FUNCTION public._docs_place(c jsonb, p_kind text, p_vars jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsplace$
DECLARE kc jsonb := c -> 'kinds' -> p_kind; v_level text; f text[] := ARRAY[]::text[]; v_name text; i integer;
BEGIN
  SELECT x ->> 'level' INTO v_level FROM jsonb_array_elements(public._docs_kinds()) AS x WHERE x ->> 'k' = p_kind;
  f := f || public._docs_segments(c ->> 'client_folder', p_vars);
  IF v_level = 'job' THEN f := f || public._docs_segments(c ->> 'job_folder', p_vars); END IF;
  f := f || public._docs_segments(kc ->> 'folder', p_vars);
  f := f[1:12];
  -- A SharePoint library keeps a folder of its own called Forms at its top.
  IF c ->> 'provider' = 'sharepoint' AND COALESCE(c #>> '{sharepoint,base_path}', '') = '' AND cardinality(f) > 0 AND lower(f[1]) = 'forms' THEN
    f[1] := f[1] || ' (files)';
  END IF;
  v_name := public._docs_file_name(public._docs_render(COALESCE(NULLIF(kc ->> 'name', ''), '{file}'), p_vars), p_vars ->> 'ext');
  -- SharePoint takes a path of at most 400 characters, the base's with it:
  -- folders are shortened before the name is.
  IF length(COALESCE(c #>> '{sharepoint,base_path}', '') || '/' || array_to_string(f, '/') || '/' || v_name) > 360 THEN
    FOR i IN 1 .. COALESCE(cardinality(f), 0) LOOP f[i] := public._docs_safe(f[i], 40); END LOOP;
  END IF;
  RETURN jsonb_build_object('folders', to_jsonb(f), 'name', v_name);
END $dsplace$;
REVOKE ALL ON FUNCTION public._docs_place(jsonb, text, jsonb) FROM PUBLIC, anon, authenticated;

-- ── What there is to keep in step ──────────────────────────────────────────
-- Every file of every kind in the portal's own storage, with its engagement
-- or client, the name it has in the portal, its size and its version. Never
-- credentials (they are not files), avatars, templates or branding.
CREATE OR REPLACE FUNCTION public._docs_sources()
RETURNS TABLE (r_source text, r_kind text, r_assessment uuid, r_client uuid, r_name text, r_size bigint, r_version text, r_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dssrc$
DECLARE v_names jsonb;
BEGIN
  IF to_regclass('storage.objects') IS NULL THEN RETURN; END IF;
  -- A final PDF's name, as the portal keeps it: { name, size } by
  -- "<type>_<id>", or a bare name from before 762 (and the whole map kept as
  -- text by a portal of that time).
  SELECT s.final_pdf_names INTO v_names FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1;
  IF jsonb_typeof(v_names) = 'string' THEN
    BEGIN v_names := (v_names #>> '{}')::jsonb; EXCEPTION WHEN OTHERS THEN v_names := NULL; END;
  END IF;
  IF jsonb_typeof(v_names) IS DISTINCT FROM 'object' THEN v_names := '{}'::jsonb; END IF;
  RETURN QUERY EXECUTE $q$
    WITH o AS MATERIALIZED (
      SELECT ob.name, COALESCE(ob.updated_at, ob.created_at) AS at,
             CASE WHEN COALESCE(ob.metadata ->> 'size', '') ~ '^[0-9]{1,15}$' THEN (ob.metadata ->> 'size')::bigint END AS size,
             COALESCE(ob.version, '') || '|' || COALESCE(ob.metadata ->> 'eTag', '') || '|' || COALESCE(ob.metadata ->> 'size', '')
               || '|' || COALESCE(extract(epoch FROM COALESCE(ob.updated_at, ob.created_at))::text, '') AS ver
        FROM storage.objects ob WHERE ob.bucket_id = 'assessment-files'
    ),
    finals AS (
      SELECT o.*, m[1] AS t, m[2]::uuid AS fid,
             COALESCE(NULLIF(btrim($1 #>> ARRAY[m[1] || '_' || lower(m[2]), 'name']), ''),
                      CASE WHEN jsonb_typeof($1 -> (m[1] || '_' || lower(m[2]))) = 'string' THEN NULLIF(btrim($1 ->> (m[1] || '_' || lower(m[2]))), '') END) AS nm
        FROM o, LATERAL regexp_match(o.name, '^[0-9A-Fa-f-]{36}/final-pdfs/(report|loa|vuln_report|proposal|invoice)_([0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12})\.pdf$') AS m
       WHERE m IS NOT NULL
    ),
    named AS (
      SELECT f.*, CASE WHEN f.nm IS NULL THEN NULL WHEN f.nm ~* '\.pdf$' THEN f.nm ELSE f.nm || '.pdf' END AS fname FROM finals f
    )
    SELECT f.name, CASE f.t WHEN 'report' THEN 'report' ELSE 'attestation' END, a.id, a.client_id,
           COALESCE(f.fname, CASE f.t WHEN 'report' THEN 'Report.pdf' ELSE 'Attestation.pdf' END),
           f.size, f.ver, f.at
      FROM named f JOIN public.assessments a ON a.id = f.fid WHERE f.t IN ('report', 'loa')
    UNION ALL
    SELECT f.name, 'scans', r.assessment_id, COALESCE(a.client_id, r.client_id), COALESCE(f.fname, 'Scan report.pdf'), f.size, f.ver, f.at
      FROM named f JOIN public.scan_runs r ON r.id = f.fid JOIN public.assessments a ON a.id = r.assessment_id WHERE f.t = 'vuln_report'
    UNION ALL
    SELECT f.name, 'proposals', NULL::uuid, p.client_id, COALESCE(f.fname, 'Proposal.pdf'), f.size, f.ver, f.at
      FROM named f JOIN public.proposals p ON p.id = f.fid WHERE f.t = 'proposal' AND p.client_id IS NOT NULL
    UNION ALL
    SELECT f.name, 'invoices', NULL::uuid, i.client_id, COALESCE(f.fname, 'Invoice.pdf'), f.size, f.ver, f.at
      FROM named f JOIN public.invoices i ON i.id = f.fid WHERE f.t = 'invoice' AND i.client_id IS NOT NULL
    UNION ALL
    SELECT af.storage_path,
           CASE WHEN af.scan_run_id IS NOT NULL THEN 'scans'
                WHEN af.doc_type = 'report' THEN 'report'
                WHEN af.doc_type = 'attestation' THEN 'attestation'
                WHEN af.doc_type IN ('proposal', 'invoice') THEN 'paperwork'
                WHEN COALESCE(af.uploaded_by_client, false) THEN 'client'
                ELSE 'files' END,
           a.id, a.client_id, COALESCE(NULLIF(btrim(af.file_name), ''), regexp_replace(af.storage_path, '^.*/', '')), COALESCE(o.size, af.file_size), o.ver, o.at
      FROM public.assessment_files af JOIN public.assessments a ON a.id = af.assessment_id JOIN o ON o.name = af.storage_path
    UNION ALL
    SELECT a.edited_docx_path, 'edited', a.id, a.client_id,
           COALESCE(NULLIF(btrim(a.edited_docx_name), ''), regexp_replace(a.edited_docx_path, '^.*/', '')), o.size, o.ver, o.at
      FROM public.assessments a JOIN o ON o.name = a.edited_docx_path
     WHERE COALESCE(a.edited_docx_path, '') <> ''
       AND NOT EXISTS (SELECT 1 FROM public.assessment_files af3 WHERE af3.storage_path = a.edited_docx_path)
    UNION ALL
    -- A picture in a finding: kept under its engagement, then the field it
    -- is in (evidence, description, a firm's own), then its finding.
    SELECT o.name, 'evidence', a.id, a.client_id, regexp_replace(o.name, '^.*/', ''), o.size, o.ver, o.at
      FROM o JOIN public.assessments a ON a.id::text = lower(split_part(o.name, '/', 1))
     WHERE split_part(o.name, '/', 3) <> '' AND split_part(o.name, '/', 2) NOT IN ('edited', 'scan', 'final-pdfs')
       AND o.name ~* '\.(png|jpe?g|gif|webp|bmp|svg)$'
       AND NOT EXISTS (SELECT 1 FROM public.assessment_files af2 WHERE af2.storage_path = o.name)
  $q$ USING v_names;
END $dssrc$;
REVOKE ALL ON FUNCTION public._docs_sources() FROM PUBLIC, anon, authenticated;

-- The files looked through, for the target named now: a new one, or one
-- with a new version, to be sent; one whose kind is not kept, left; one gone
-- from here, removed there where the firm says so, otherwise left there.
-- Every file at once, not one at a time (a firm with years of evidence
-- pictures has tens of thousands), and one look at a time. Returns how many
-- changed.
CREATE OR REPLACE FUNCTION public._docs_scan() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsscan$
DECLARE c jsonb := public._docs_cfg(); v_key text; v_prov text; v_kinds jsonb; v_rm boolean; v_n integer := 0; v_seen integer := 0;
BEGIN
  IF NOT COALESCE((c ->> 'on')::boolean, false) THEN RETURN 0; END IF;
  v_key := public._docs_target_key(c);
  IF v_key IS NULL THEN RETURN 0; END IF;
  IF NOT pg_try_advisory_xact_lock(hashtext('pental_docs_scan')) THEN RETURN 0; END IF;
  v_prov := c ->> 'provider';
  v_kinds := c -> 'kinds';
  v_rm := COALESCE((c ->> 'remove_remote')::boolean, false);
  WITH src AS MATERIALIZED (
    SELECT DISTINCT ON (x.r_source) x.r_source, x.r_kind, x.r_assessment, x.r_client, x.r_name, x.r_size, x.r_version, x.r_at,
           COALESCE((v_kinds -> x.r_kind ->> 'on')::boolean, false) AND COALESCE(x.r_size, 1) > 0 AS keep
      FROM public._docs_sources() x
     ORDER BY x.r_source, x.r_at DESC NULLS LAST
  ),
  ins AS (
    INSERT INTO public._docs_items (target_key, provider, source, kind, assessment_id, client_id, file_name, size, version, file_at, state)
    SELECT v_key, v_prov, s.r_source, s.r_kind, s.r_assessment, s.r_client, s.r_name, s.r_size, s.r_version, s.r_at,
           CASE WHEN s.keep THEN 'pending' ELSE 'off' END
      FROM src s
     WHERE NOT EXISTS (SELECT 1 FROM public._docs_items i WHERE i.target_key = v_key AND i.source = s.r_source)
    ON CONFLICT (target_key, source) DO NOTHING
    RETURNING 1
  ),
  cur AS (
    SELECT i.id, s.r_kind, s.r_assessment, s.r_client, s.r_name, s.r_size, s.r_version, s.r_at,
      CASE
        WHEN NOT s.keep THEN CASE WHEN i.state IN ('pending', 'failed', 'held') THEN 'off' ELSE i.state END
        -- Back here while it was being removed there: kept, once that call
        -- has landed (a removal under way is not called back).
        WHEN i.state = 'removing' AND public._docs_job_live(i.job) THEN 'removing'
        WHEN i.state IN ('off', 'done', 'gone', 'removed', 'removing') THEN
          CASE WHEN i.state NOT IN ('removed', 'removing') AND i.remote_id IS NOT NULL AND i.synced_version IS NOT DISTINCT FROM s.r_version
               THEN 'done' ELSE 'pending' END
        WHEN i.state IN ('failed', 'held') AND i.version IS DISTINCT FROM s.r_version THEN 'pending'
        ELSE i.state END AS new_state
      FROM src s JOIN public._docs_items i ON i.target_key = v_key AND i.source = s.r_source
  ),
  upd AS (
    UPDATE public._docs_items i
       SET state = c2.new_state, kind = c2.r_kind, assessment_id = c2.r_assessment, client_id = c2.r_client, file_name = c2.r_name,
           size = c2.r_size, version = c2.r_version, file_at = c2.r_at,
           attempts = CASE WHEN i.version IS DISTINCT FROM c2.r_version OR c2.new_state = 'pending' AND i.state IN ('off', 'done', 'gone', 'removed', 'removing') THEN 0 ELSE i.attempts END,
           next_at = CASE WHEN c2.new_state = 'pending' AND i.state IS DISTINCT FROM 'pending' THEN now() ELSE i.next_at END,
           last_error = CASE WHEN c2.new_state IN ('pending', 'done', 'off') THEN NULL ELSE i.last_error END,
           job = CASE WHEN i.state = 'removing' AND c2.new_state <> 'removing' THEN NULL ELSE i.job END,
           updated_at = now()
      FROM cur c2
     WHERE i.id = c2.id
       AND (c2.new_state IS DISTINCT FROM i.state OR i.version IS DISTINCT FROM c2.r_version OR i.file_name IS DISTINCT FROM c2.r_name
            OR i.kind IS DISTINCT FROM c2.r_kind OR i.assessment_id IS DISTINCT FROM c2.r_assessment OR i.client_id IS DISTINCT FROM c2.r_client)
    RETURNING 1
  ),
  -- Gone from here. Never sent: nothing to keep. Sent: removed there where
  -- the firm says so, otherwise left there and said.
  del AS (
    DELETE FROM public._docs_items i
     WHERE i.target_key = v_key AND i.remote_id IS NULL AND i.candidate_id IS NULL AND i.state IN ('pending', 'failed', 'held', 'off')
       AND NOT EXISTS (SELECT 1 FROM src s WHERE s.r_source = i.source)
    RETURNING 1
  ),
  -- (What arrived there and was still to be checked counts as there.)
  gone AS (
    UPDATE public._docs_items i
       SET state = CASE WHEN v_rm THEN 'removing' ELSE 'gone' END, remote_id = COALESCE(i.remote_id, i.candidate_id),
           candidate_id = NULL, candidate_size = NULL,
           job = NULL, attempts = 0, next_at = now(), last_error = NULL, updated_at = now()
     WHERE i.target_key = v_key AND (i.remote_id IS NOT NULL OR i.candidate_id IS NOT NULL) AND i.state IN ('done', 'failed', 'held', 'off')
       AND NOT EXISTS (SELECT 1 FROM src s WHERE s.r_source = i.source)
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM ins) + (SELECT count(*) FROM upd) + (SELECT count(*) FROM del) + (SELECT count(*) FROM gone),
         (SELECT count(*) FROM src)
    INTO v_n, v_seen;
  UPDATE public._docs_state SET scanned_at = now(), scanned = v_seen, scan_error = NULL, updated_at = now() WHERE id;
  -- A gateway's worker is told there may be something to send.
  IF v_n > 0 THEN PERFORM pg_notify('pental_docs', ''); END IF;
  RETURN v_n;
EXCEPTION WHEN OTHERS THEN
  UPDATE public._docs_state SET scanned_at = now(), scan_error = left(SQLERRM, 300), updated_at = now() WHERE id;
  RETURN 0;
END $dsscan$;
REVOKE ALL ON FUNCTION public._docs_scan() FROM PUBLIC, anon, authenticated;

-- ── The calls ──────────────────────────────────────────────────────────────
-- A Graph call for keeping files in step: with Microsoft's access for the
-- hour where it is held, otherwise after asking for it (teams_token, with
-- the Teams application's credentials; its answer comes back here through
-- _teams_after_token).
CREATE OR REPLACE FUNCTION public._docs_graph_plan(p jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgplan$
BEGIN
  -- 1848: with whichever of the firm's Microsoft applications reaches it.
  IF public._docs_ms_token_now() IS NULL THEN
    RETURN public._net_plan('teams_token', p || CASE WHEN public._docs_ms_app() ->> 'via' = 'signin' THEN jsonb_build_object('app', 'signin') ELSE '{}'::jsonb END);
  END IF;
  RETURN public._net_plan('docs_graph', p);
END $dsgplan$;
REVOKE ALL ON FUNCTION public._docs_graph_plan(jsonb) FROM PUBLIC, anon, authenticated;

-- A Drive call: with Google's access for the hour where it is held,
-- otherwise after asking for it with the lasting access (drive_token).
CREATE OR REPLACE FUNCTION public._docs_drive_plan(p jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsdplan$
BEGIN
  IF public._docs_drive_token_now() IS NULL THEN
    RETURN public._net_plan('drive_token', jsonb_build_object('docs', 'refresh', 'then', p) || jsonb_build_object('item', p -> 'item'));
  END IF;
  RETURN public._net_plan('drive', p);
END $dsdplan$;
REVOKE ALL ON FUNCTION public._docs_drive_plan(jsonb) FROM PUBLIC, anon, authenticated;

-- The call a file, or the finding of the target, now waits on: kept on it,
-- so a step asked again while it is out is not asked twice.
CREATE OR REPLACE FUNCTION public._docs_track(p jsonb, p_job uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstrack$
DECLARE v jsonb := CASE WHEN jsonb_typeof(p -> 'then') = 'object' THEN p -> 'then' ELSE p END;
BEGIN
  IF p_job IS NULL THEN RETURN NULL; END IF;
  IF COALESCE(v ->> 'item', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    UPDATE public._docs_items SET job = p_job, updated_at = now() WHERE id = (v ->> 'item')::uuid AND state IN ('linking', 'verifying', 'removing');
  END IF;
  IF COALESCE((v ->> 'base')::boolean, false) OR v ->> 'docs' IN ('site', 'drive', 'root') THEN
    UPDATE public._docs_target SET job = p_job, updated_at = now() WHERE id AND target_key IS NOT DISTINCT FROM v ->> 'target';
  END IF;
  RETURN p_job;
END $dstrack$;
REVOKE ALL ON FUNCTION public._docs_track(jsonb, uuid) FROM PUBLIC, anon, authenticated;

-- With Microsoft's access in hand (teams_token's answer, by way of
-- _teams_after_token), the Graph call that was waiting for it.
CREATE OR REPLACE FUNCTION public._docs_after_token(p jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsafter$
BEGIN
  RETURN public._docs_track(p, public._net_plan('docs_graph', p));
END $dsafter$;
REVOKE ALL ON FUNCTION public._docs_after_token(jsonb) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._docs_plan(c jsonb, p jsonb) RETURNS uuid
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsplan$
  SELECT CASE WHEN c ->> 'provider' = 'sharepoint' THEN public._docs_graph_plan(p) ELSE public._docs_drive_plan(p) END;
$dsplan$;
REVOKE ALL ON FUNCTION public._docs_plan(jsonb, jsonb) FROM PUBLIC, anon, authenticated;

-- Whether a call is still out.
CREATE OR REPLACE FUNCTION public._docs_job_live(p_job uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dslive$
  SELECT p_job IS NOT NULL AND EXISTS (SELECT 1 FROM public._net_jobs j WHERE j.id = p_job AND j.state IN ('planned', 'queued', 'sending'));
$dslive$;
REVOKE ALL ON FUNCTION public._docs_job_live(uuid) FROM PUBLIC, anon, authenticated;

-- A Graph path segment and a Drive query's quoted name.
CREATE OR REPLACE FUNCTION public._docs_q(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsq$
  SELECT '''' || replace(replace(COALESCE(p, ''), '\', '\\'), '''', '\''') || '''';
$dsq$;
REVOKE ALL ON FUNCTION public._docs_q(text) FROM PUBLIC, anon, authenticated;

-- What a docs call asks now (as _net_build answers): { method, url, headers,
-- body } or { error, code }. p_job.subject.docs says which step:
--   Graph (docs_graph): site, drive, root, folder (made), find (a folder by
--   its path), session (an upload address), verify, remove.
--   Drive (drive): find (a folder by name in its parent), folder (made),
--   session, verify, remove; Google's token address (drive_token): code
--   (the consent's one-time code exchanged) or refresh.
CREATE OR REPLACE FUNCTION public._docs_build(p_job public._net_jobs) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsbuild$
DECLARE s jsonb := p_job.subject; v_step text := s ->> 'docs'; v_tok text; c jsonb := public._docs_cfg(); t public._docs_target;
  v_host text; v_path text; v_url text; v_gb text := public._net_endpoint('graph'); v_db text := public._net_endpoint('drive');
  pd public._docs_pending; v_secret text; v_client text; it public._docs_items; v_rem text; h jsonb;
BEGIN
  -- 1848: the giving of SharePoint's access makes calls of its own.
  IF p_job.kind = 'sso_exchange' OR (p_job.kind = 'docs_graph' AND COALESCE(v_step, '') LIKE 'ms\_%') THEN RETURN public._docs_ms_build(p_job); END IF;
  IF p_job.kind = 'drive_token' THEN
    v_client := (SELECT btrim(st.sso_google_client_id) FROM public.settings st ORDER BY st.created_at ASC NULLS LAST, st.id LIMIT 1);
    v_secret := public._sso_client_secret('google');
    IF COALESCE(v_client, '') = '' OR v_secret IS NULL THEN
      RETURN jsonb_build_object('error', 'The Google sign-in application''s client ID and secret are not saved here.', 'code', 'config');
    END IF;
    IF v_step = 'code' THEN
      SELECT * INTO pd FROM public._docs_pending WHERE state = s ->> 'state';
      IF pd.state IS NULL OR pd.provider IS DISTINCT FROM 'google' OR COALESCE(s ->> 'code', '') = '' OR pd.created_at < now() - interval '15 minutes' THEN
        RETURN jsonb_build_object('error', 'Connecting Google Drive was not started here, or took too long. Start again.', 'code', 'gone');
      END IF;
      RETURN jsonb_build_object('method', 'POST', 'url', public._net_endpoint('google_token'),
        'headers', jsonb_build_object('Content-Type', 'application/x-www-form-urlencoded', 'Accept', 'application/json'),
        'body', public._xero_form(jsonb_build_object('grant_type', 'authorization_code', 'code', s ->> 'code', 'client_id', pd.client_id,
          'client_secret', v_secret, 'redirect_uri', pd.redirect_uri, 'code_verifier', pd.verifier)));
    END IF;
    v_tok := public._docs_google_refresh();
    IF v_tok IS NULL THEN RETURN jsonb_build_object('error', 'Google Drive is not connected.', 'code', 'config'); END IF;
    RETURN jsonb_build_object('method', 'POST', 'url', public._net_endpoint('google_token'),
      'headers', jsonb_build_object('Content-Type', 'application/x-www-form-urlencoded', 'Accept', 'application/json'),
      'body', public._xero_form(jsonb_build_object('grant_type', 'refresh_token', 'refresh_token', v_tok, 'client_id', v_client, 'client_secret', v_secret)));
  END IF;

  SELECT * INTO t FROM public._docs_target WHERE id;
  IF s ? 'item' THEN SELECT * INTO it FROM public._docs_items WHERE id = (s ->> 'item')::uuid; END IF;

  IF p_job.kind = 'docs_graph' THEN
    v_tok := public._docs_ms_token_now();
    IF v_tok IS NULL THEN RETURN jsonb_build_object('error', 'The access Microsoft gave ran out before the next step. It is asked for again.', 'code', 'config'); END IF;
    h := jsonb_build_object('Authorization', 'Bearer ' || v_tok, 'Accept', 'application/json');
    IF v_step = 'site' THEN
      v_host := substring(c #>> '{sharepoint,site_url}' FROM '^https://([^/:]+)');
      v_path := COALESCE(substring(c #>> '{sharepoint,site_url}' FROM '^https://[^/]+(/.*)$'), '');
      IF v_host IS NULL THEN RETURN jsonb_build_object('error', 'The SharePoint site''s address is not one Microsoft names.', 'code', 'gone'); END IF;
      v_url := v_gb || '/sites/' || public._tk_uri(v_host)
        || CASE WHEN v_path IN ('', '/') THEN '' ELSE ':' || (SELECT string_agg(public._tk_uri(x), '/') FROM unnest(string_to_array(v_path, '/')) AS x) END
        || '?$select=id,webUrl,displayName';
      RETURN jsonb_build_object('method', 'GET', 'url', v_url, 'headers', h);
    ELSIF v_step = 'drive' THEN
      IF COALESCE(t.site_id, '') = '' THEN RETURN jsonb_build_object('error', 'The SharePoint site was not found yet.', 'code', 'gone'); END IF;
      RETURN jsonb_build_object('method', 'GET', 'url', v_gb || '/sites/' || public._tk_uri(t.site_id)
        || CASE WHEN COALESCE(c #>> '{sharepoint,library}', '') = '' THEN '/drive?$select=id,name,webUrl' ELSE '/drives?$select=id,name,webUrl&$top=200' END,
        'headers', h);
    ELSIF v_step = 'root' THEN
      RETURN jsonb_build_object('method', 'GET', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/root?$select=id,webUrl', 'headers', h);
    ELSIF v_step = 'folder' THEN
      -- Made where it is not there yet; refused (409) where it is.
      RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/items/' || public._tk_uri(s ->> 'parent') || '/children',
        'headers', h || jsonb_build_object('Content-Type', 'application/json'),
        'body', jsonb_build_object('name', s ->> 'name', 'folder', '{}'::jsonb, '@microsoft.graph.conflictBehavior', 'fail')::text);
    ELSIF v_step = 'find' THEN
      RETURN jsonb_build_object('method', 'GET', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/items/' || public._tk_uri(s ->> 'parent')
        || ':/' || public._tk_uri(s ->> 'name') || ':?$select=id,name,webUrl,folder', 'headers', h);
    ELSIF v_step = 'session' THEN
      IF it.id IS NULL OR it.state <> 'linking' THEN RETURN jsonb_build_object('error', 'Not a file being sent.', 'code', 'gone'); END IF;
      -- A new version of a file already there goes into that file (its
      -- history kept); a new file is named as planned, renamed by
      -- SharePoint ("Report 1.pdf") where something else has the name.
      IF COALESCE(s ->> 'remote', '') <> '' THEN
        RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/items/' || public._tk_uri(s ->> 'remote') || '/createUploadSession',
          'headers', h || jsonb_build_object('Content-Type', 'application/json'),
          'body', jsonb_build_object('item', jsonb_build_object('@microsoft.graph.conflictBehavior', 'replace'))::text);
      END IF;
      RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/items/' || public._tk_uri(it.parent_id)
        || ':/' || public._tk_uri(it.name) || ':/createUploadSession',
        'headers', h || jsonb_build_object('Content-Type', 'application/json'),
        'body', jsonb_build_object('item', jsonb_build_object('@microsoft.graph.conflictBehavior', 'rename', 'name', it.name))::text);
    ELSIF v_step = 'lookup' THEN
      -- A file perhaps sent already, looked for by its name in its folder.
      IF it.id IS NULL OR it.state <> 'linking' OR COALESCE(it.parent_id, '') = '' OR COALESCE(it.name, '') = '' THEN
        RETURN jsonb_build_object('error', 'Not a file being sent.', 'code', 'gone');
      END IF;
      RETURN jsonb_build_object('method', 'GET', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/items/' || public._tk_uri(it.parent_id)
        || ':/' || public._tk_uri(it.name) || ':?$select=id,name,size,webUrl,parentReference,file', 'headers', h);
    ELSIF v_step = 'verify' THEN
      IF it.id IS NULL OR COALESCE(it.candidate_id, '') = '' THEN RETURN jsonb_build_object('error', 'Nothing to check.', 'code', 'gone'); END IF;
      RETURN jsonb_build_object('method', 'GET', 'url', v_gb || '/drives/' || public._tk_uri(t.drive_id) || '/items/' || public._tk_uri(it.candidate_id)
        || '?$select=id,name,size,webUrl,parentReference,file', 'headers', h);
    ELSIF v_step = 'remove' THEN
      v_rem := COALESCE(s ->> 'remote', it.remote_id);
      IF COALESCE(v_rem, '') = '' OR COALESCE(s ->> 'drive', t.drive_id, '') = '' THEN RETURN jsonb_build_object('error', 'Nothing to remove.', 'code', 'gone'); END IF;
      -- pg_net and a gateway's worker send GET and POST only: the DELETE goes
      -- in a POST to Graph's batch address (as a Teams meeting's change does).
      RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/$batch',
        'headers', h || jsonb_build_object('Content-Type', 'application/json'),
        'body', jsonb_build_object('requests', jsonb_build_array(jsonb_build_object('id', '1', 'method', 'DELETE',
          'url', '/drives/' || public._tk_uri(COALESCE(s ->> 'drive', t.drive_id)) || '/items/' || public._tk_uri(v_rem))))::text);
    END IF;
    RETURN jsonb_build_object('error', 'Not a step this database takes.', 'code', 'gone');
  END IF;

  IF p_job.kind = 'drive' THEN
    v_tok := public._docs_drive_token_now();
    IF v_tok IS NULL THEN RETURN jsonb_build_object('error', 'The access Google gave ran out before the next step. It is asked for again.', 'code', 'config'); END IF;
    h := jsonb_build_object('Authorization', 'Bearer ' || v_tok, 'Accept', 'application/json');
    IF v_step = 'find' THEN
      RETURN jsonb_build_object('method', 'GET', 'url', v_db || '/files?q=' || public._tk_uri(
          public._docs_q(s ->> 'parent') || ' in parents and name = ' || public._docs_q(s ->> 'name')
          || ' and mimeType = ''application/vnd.google-apps.folder'' and trashed = false')
        || '&fields=' || public._tk_uri('files(id,name,webViewLink)') || '&pageSize=10&spaces=drive', 'headers', h);
    ELSIF v_step = 'folder' THEN
      RETURN jsonb_build_object('method', 'POST', 'url', v_db || '/files?fields=' || public._tk_uri('id,name,webViewLink'),
        'headers', h || jsonb_build_object('Content-Type', 'application/json'),
        'body', jsonb_build_object('name', s ->> 'name', 'mimeType', 'application/vnd.google-apps.folder', 'parents', jsonb_build_array(s ->> 'parent'))::text);
    ELSIF v_step = 'lookup' THEN
      -- A file perhaps sent already, looked for by its name in its folder.
      IF it.id IS NULL OR it.state <> 'linking' OR COALESCE(it.parent_id, '') = '' OR COALESCE(it.name, '') = '' THEN
        RETURN jsonb_build_object('error', 'Not a file being sent.', 'code', 'gone');
      END IF;
      RETURN jsonb_build_object('method', 'GET', 'url', v_db || '/files?q=' || public._tk_uri(
          public._docs_q(it.parent_id) || ' in parents and name = ' || public._docs_q(it.name)
          || ' and mimeType != ''application/vnd.google-apps.folder'' and trashed = false')
        || '&fields=' || public._tk_uri('files(id,name,size,parents,webViewLink,trashed)') || '&pageSize=10&spaces=drive', 'headers', h);
    ELSIF v_step = 'session' THEN
      IF it.id IS NULL OR it.state <> 'linking' THEN RETURN jsonb_build_object('error', 'Not a file being sent.', 'code', 'gone'); END IF;
      -- The upload address comes back in the answer's Location header; the
      -- browser that sends the file is named as its origin, so the address
      -- answers that page (and only a page there).
      h := h || jsonb_build_object('Content-Type', 'application/json; charset=UTF-8', 'X-Upload-Content-Type', 'application/octet-stream')
             || CASE WHEN it.size IS NOT NULL THEN jsonb_build_object('X-Upload-Content-Length', it.size::text) ELSE '{}'::jsonb END
             || CASE WHEN COALESCE(it.origin, '') <> '' THEN jsonb_build_object('Origin', it.origin) ELSE '{}'::jsonb END;
      IF COALESCE(s ->> 'remote', '') <> '' THEN
        RETURN jsonb_build_object('method', 'POST', 'url', public._net_endpoint('drive_upload') || '/files/' || public._tk_uri(s ->> 'remote')
          || '?uploadType=resumable&fields=' || public._tk_uri('id,name,size,parents,webViewLink'),
          'headers', h || jsonb_build_object('X-HTTP-Method-Override', 'PATCH'), 'body', '{}');
      END IF;
      RETURN jsonb_build_object('method', 'POST', 'url', public._net_endpoint('drive_upload') || '/files?uploadType=resumable&fields=' || public._tk_uri('id,name,size,parents,webViewLink'),
        'headers', h, 'body', jsonb_build_object('name', it.name, 'parents', jsonb_build_array(it.parent_id))::text);
    ELSIF v_step = 'verify' THEN
      IF it.id IS NULL OR COALESCE(it.candidate_id, '') = '' THEN RETURN jsonb_build_object('error', 'Nothing to check.', 'code', 'gone'); END IF;
      RETURN jsonb_build_object('method', 'GET', 'url', v_db || '/files/' || public._tk_uri(it.candidate_id) || '?fields=' || public._tk_uri('id,name,size,parents,webViewLink,trashed'), 'headers', h);
    ELSIF v_step = 'remove' THEN
      v_rem := COALESCE(s ->> 'remote', it.remote_id);
      IF COALESCE(v_rem, '') = '' THEN RETURN jsonb_build_object('error', 'Nothing to remove.', 'code', 'gone'); END IF;
      -- To Drive's bin (a PATCH, sent as a POST that says so).
      RETURN jsonb_build_object('method', 'POST', 'url', v_db || '/files/' || public._tk_uri(v_rem) || '?fields=' || public._tk_uri('id,trashed'),
        'headers', h || jsonb_build_object('Content-Type', 'application/json', 'X-HTTP-Method-Override', 'PATCH'),
        'body', jsonb_build_object('trashed', true)::text);
    END IF;
    RETURN jsonb_build_object('error', 'Not a step this database takes.', 'code', 'gone');
  END IF;
  RETURN jsonb_build_object('error', 'Not a call this database makes.', 'code', 'gone');
END $dsbuild$;
REVOKE ALL ON FUNCTION public._docs_build(public._net_jobs) FROM PUBLIC, anon, authenticated;

-- What Microsoft or Google said, in words for the firm: its own message, a
-- refusal made here before the call left in its own words, or what became
-- of the call.
CREATE OR REPLACE FUNCTION public._docs_said(o jsonb, p_status integer, p_error text, p_transport text, p_who text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $dssaid$
  SELECT left(regexp_replace(COALESCE(
    NULLIF(btrim(COALESCE(o #>> '{error,message}', '')), ''),
    NULLIF(btrim(split_part(replace(COALESCE(o ->> 'error_description', ''), E'\r', E'\n'), E'\n', 1)), ''),
    CASE WHEN jsonb_typeof(o -> 'error') = 'string' THEN NULLIF(btrim(o ->> 'error'), '') END,
    CASE WHEN p_status IS NULL AND p_transport IN ('refused', 'skip') AND COALESCE(p_error, '') <> '' THEN p_error END,
    CASE WHEN p_status IS NULL THEN p_who || ' did not answer your portal''s database (' || public._mail_transport_words(p_error) || ').'
         ELSE p_who || ' answered ' || p_status || '.' END), '[[:cntrl:]]+', ' ', 'g'), 400);
$dssaid$;
REVOKE ALL ON FUNCTION public._docs_said(jsonb, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- An id Graph or Drive gives a site, drive, folder or file, as an address
-- can carry it.
CREATE OR REPLACE FUNCTION public._docs_id_ok(p text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsidok$
  -- (A pattern counts to 255 at most in PostgreSQL: the length apart.)
  SELECT COALESCE(p, '') ~ '^[A-Za-z0-9!._,:@=+-]+$' AND length(p) BETWEEN 4 AND 400;
$dsidok$;
REVOKE ALL ON FUNCTION public._docs_id_ok(text) FROM PUBLIC, anon, authenticated;

-- A file's go failed: tried again in a while (a minute, then five, then
-- twenty), held after three until Sync now.
-- p_keep: what arrived there is kept, to be checked again rather than sent
-- again (its check failed in passing, or its answer was lost); p_count:
-- whether it counts as one of its three tries (a sender that went away does
-- not: the file is let go for someone else to send).
DROP FUNCTION IF EXISTS public._docs_fail(uuid, text);
CREATE OR REPLACE FUNCTION public._docs_fail(p_item uuid, p_error text, p_keep boolean DEFAULT false, p_count boolean DEFAULT true) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsfail$
BEGIN
  UPDATE public._docs_items
     SET attempts = attempts + CASE WHEN p_count THEN 1 ELSE 0 END,
         state = CASE WHEN p_count AND attempts + 1 >= 3 THEN 'held' ELSE 'failed' END,
         next_at = now() + CASE WHEN NOT p_count OR attempts = 0 THEN interval '1 minute' WHEN attempts = 1 THEN interval '5 minutes' ELSE interval '20 minutes' END,
         last_error = left(COALESCE(NULLIF(btrim(p_error), ''), 'It could not be sent.'), 500),
         lease_by = NULL, lease_worker = NULL, lease_until = NULL, job = NULL,
         candidate_id = CASE WHEN p_keep THEN candidate_id END,
         candidate_size = CASE WHEN p_keep THEN candidate_size END,
         updated_at = now()
   WHERE id = p_item AND state IN ('linking', 'uploading', 'verifying', 'pending');
  DELETE FROM public._docs_links WHERE item_id = p_item;
END $dsfail$;
REVOKE ALL ON FUNCTION public._docs_fail(uuid, text, boolean, boolean) FROM PUBLIC, anon, authenticated;

-- Microsoft's or Google's access could not be had for a step: the file it
-- was for tried again in a while, or the finding of where the files go said
-- to have failed, with why (a wrong secret is said as Microsoft says it).
CREATE OR REPLACE FUNCTION public._docs_token_failed(p jsonb, p_error text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstokfail$
DECLARE v jsonb := CASE WHEN jsonb_typeof(p -> 'then') = 'object' THEN p -> 'then' ELSE p END; v_item uuid;
  v_err text := 'The portal could not be given access: ' || COALESCE(NULLIF(btrim(p_error), ''), 'no reason was given.');
BEGIN
  IF COALESCE(v ->> 'item', '') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_item := (v ->> 'item')::uuid;
    UPDATE public._docs_items SET job = NULL, attempts = attempts + 1, last_error = left(v_err, 500),
           next_at = now() + interval '20 minutes', updated_at = now()
     WHERE id = v_item AND state = 'removing';
    PERFORM public._docs_fail(v_item, v_err);
  END IF;
  IF COALESCE((v ->> 'base')::boolean, false) OR v ->> 'docs' IN ('site', 'drive', 'root') THEN
    PERFORM public._docs_target_fail(v ->> 'target', v_err);
  END IF;
END $dstokfail$;
REVOKE ALL ON FUNCTION public._docs_token_failed(jsonb, text) FROM PUBLIC, anon, authenticated;

-- A folder there that is no longer where it was (someone removed or moved
-- it): every folder kept for the target forgotten, and where the files go
-- found again, so the next go makes them afresh.
CREATE OR REPLACE FUNCTION public._docs_folders_lost(p_key text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dslost$
  DELETE FROM public._docs_folders WHERE target_key = p_key;
  UPDATE public._docs_target SET ready = false, checking = false, job = NULL, base_id = NULL, updated_at = now()
   WHERE id AND target_key IS NOT DISTINCT FROM p_key;
$dslost$;
REVOKE ALL ON FUNCTION public._docs_folders_lost(text) FROM PUBLIC, anon, authenticated;

-- The target found for the settings named now, or its finding begun (one
-- at a time): true where it is ready.
CREATE OR REPLACE FUNCTION public._docs_target_ready(c jsonb, p_asked_by uuid DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstready$
DECLARE v_key text := public._docs_target_key(c); t public._docs_target; v_job uuid;
BEGIN
  IF v_key IS NULL THEN RETURN false; END IF;
  -- Found already, or being found: said at once, without waiting on whoever
  -- else is moving files on (a sender asks this every go).
  SELECT * INTO t FROM public._docs_target WHERE id;
  IF FOUND AND t.target_key IS NOT DISTINCT FROM v_key AND t.ready THEN RETURN true; END IF;
  IF FOUND AND t.target_key IS NOT DISTINCT FROM v_key AND t.checking AND public._docs_job_live(t.job) THEN RETURN false; END IF;
  INSERT INTO public._docs_target (id) VALUES (true) ON CONFLICT (id) DO NOTHING;
  SELECT * INTO t FROM public._docs_target WHERE id FOR UPDATE;
  IF t.target_key IS NOT DISTINCT FROM v_key AND t.ready THEN RETURN true; END IF;
  IF t.target_key IS NOT DISTINCT FROM v_key AND t.checking AND public._docs_job_live(t.job) THEN RETURN false; END IF;
  -- A failure is not asked again more than once a minute by itself.
  IF t.target_key IS NOT DISTINCT FROM v_key AND NOT t.checking AND t.error IS NOT NULL AND t.checked_at > now() - interval '1 minute' AND p_asked_by IS NULL THEN
    RETURN false;
  END IF;
  UPDATE public._docs_target
     SET target_key = v_key, provider = c ->> 'provider', ready = false, checking = true, error = NULL, need = NULL, need_url = NULL, updated_at = now(),
         site_id = CASE WHEN target_key IS NOT DISTINCT FROM v_key THEN site_id END,
         site_url = CASE WHEN target_key IS NOT DISTINCT FROM v_key THEN site_url END,
         site_name = CASE WHEN target_key IS NOT DISTINCT FROM v_key THEN site_name END,
         drive_id = NULL, drive_name = NULL, base_id = NULL, base_url = NULL
   WHERE id;
  IF c ->> 'provider' = 'sharepoint' THEN
    v_job := public._docs_graph_plan(jsonb_build_object('docs', 'site', 'target', v_key, 'asked_by', p_asked_by));
  ELSE
    v_job := public._docs_drive_plan(jsonb_build_object('docs', 'find', 'target', v_key, 'base', true, 'path', '#base', 'parent', 'root', 'name', public._docs_root_name(c), 'asked_by', p_asked_by));
  END IF;
  UPDATE public._docs_target SET job = v_job WHERE id;
  RETURN false;
END $dstready$;
REVOKE ALL ON FUNCTION public._docs_target_ready(jsonb, uuid) FROM PUBLIC, anon, authenticated;

-- The target's own steps, as each answer lands: the site, its library, the
-- base folder's own folders (below the library's top), each made or found.
CREATE OR REPLACE FUNCTION public._docs_target_step(c jsonb, p_key text, p_asked_by uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dststep$
DECLARE t public._docs_target; v_segs text[]; i integer; v_path text; v_parent text; v_id text; v_url text; v_job uuid;
BEGIN
  SELECT * INTO t FROM public._docs_target WHERE id FOR UPDATE;
  IF t.target_key IS DISTINCT FROM p_key OR c ->> 'provider' IS DISTINCT FROM 'sharepoint' THEN RETURN; END IF;
    IF COALESCE(t.site_id, '') = '' THEN v_job := public._docs_graph_plan(jsonb_build_object('docs', 'site', 'target', p_key, 'asked_by', p_asked_by));
    ELSIF COALESCE(t.drive_id, '') = '' THEN v_job := public._docs_graph_plan(jsonb_build_object('docs', 'drive', 'target', p_key, 'asked_by', p_asked_by));
    ELSE
      v_segs := string_to_array(NULLIF(c #>> '{sharepoint,base_path}', ''), '/');
      SELECT f.remote_id, f.web_url INTO v_parent, v_url FROM public._docs_folders f WHERE f.target_key = p_key AND f.path = '#root';
      IF v_parent IS NULL THEN
        v_job := public._docs_graph_plan(jsonb_build_object('docs', 'root', 'target', p_key, 'asked_by', p_asked_by));
      ELSE
        FOR i IN 1 .. COALESCE(cardinality(v_segs), 0) LOOP
          v_path := '#base/' || array_to_string(v_segs[1:i], '/');
          SELECT f.remote_id, f.web_url INTO v_id, v_url FROM public._docs_folders f WHERE f.target_key = p_key AND f.path = v_path;
          IF v_id IS NULL THEN
            v_job := public._docs_graph_plan(jsonb_build_object('docs', 'folder', 'target', p_key, 'base', true, 'path', v_path, 'parent', v_parent, 'name', v_segs[i], 'asked_by', p_asked_by));
            EXIT;
          END IF;
          v_parent := v_id;
        END LOOP;
        IF v_job IS NULL THEN
          UPDATE public._docs_target SET base_id = v_parent, base_url = v_url, ready = true, checking = false, job = NULL, checked_at = now(), error = NULL, updated_at = now() WHERE id;
          RETURN;
        END IF;
      END IF;
    END IF;
  UPDATE public._docs_target SET job = v_job, updated_at = now() WHERE id;
END $dststep$;
REVOKE ALL ON FUNCTION public._docs_target_step(jsonb, text, uuid) FROM PUBLIC, anon, authenticated;

-- A target that could not be found, said as why.
CREATE OR REPLACE FUNCTION public._docs_target_fail(p_key text, p_error text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstfail$
  UPDATE public._docs_target SET ready = false, checking = false, job = NULL, checked_at = now(), error = left(p_error, 600), updated_at = now()
   WHERE id AND target_key IS NOT DISTINCT FROM p_key;
$dstfail$;
REVOKE ALL ON FUNCTION public._docs_target_fail(text, text) FROM PUBLIC, anon, authenticated;

-- A file's next step, once its last call has landed: the target found, its
-- folders made one at a time (a folder another file is making waits for
-- it), then its upload address. Nothing where a call is still out.
CREATE OR REPLACE FUNCTION public._docs_advance(p_item uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsadv$
DECLARE c jsonb := public._docs_cfg(); i public._docs_items; t public._docs_target; pl jsonb; v_f text[]; k integer; v_path text;
  v_parent text; v_id text; v_job uuid; v_no jsonb;
BEGIN
  -- A file another call is moving on just now is left to it.
  SELECT * INTO i FROM public._docs_items WHERE id = p_item FOR UPDATE SKIP LOCKED;
  IF NOT FOUND OR i.state <> 'linking' OR public._docs_job_live(i.job) THEN RETURN; END IF;
  IF i.target_key IS DISTINCT FROM public._docs_target_key(c) OR NOT COALESCE((c ->> 'on')::boolean, false) THEN
    UPDATE public._docs_items SET state = 'pending', lease_by = NULL, lease_worker = NULL, lease_until = NULL, job = NULL, updated_at = now() WHERE id = i.id;
    RETURN;
  END IF;
  v_no := public._docs_cannot(c);
  IF v_no IS NOT NULL THEN
    UPDATE public._docs_items SET state = 'pending', lease_by = NULL, lease_worker = NULL, lease_until = NULL, job = NULL, next_at = now() + interval '2 minutes',
           last_error = v_no ->> 'error', updated_at = now() WHERE id = i.id;
    RETURN;
  END IF;
  IF NOT public._docs_target_ready(c, NULL) THEN
    SELECT * INTO t FROM public._docs_target WHERE id;
    IF NOT t.checking AND t.error IS NOT NULL THEN PERFORM public._docs_fail(i.id, t.error); END IF;
    RETURN;
  END IF;
  SELECT * INTO t FROM public._docs_target WHERE id;
  -- What arrived for it before and could not be checked then: checked now,
  -- not sent again.
  IF COALESCE(i.candidate_id, '') <> '' AND i.parent_id IS NOT NULL THEN
    UPDATE public._docs_items SET state = 'verifying', lease_until = now() + interval '5 minutes', updated_at = now() WHERE id = i.id;
    v_job := public._docs_plan(c, jsonb_build_object('docs', 'verify', 'target', i.target_key, 'item', i.id));
    UPDATE public._docs_items SET job = v_job, updated_at = now() WHERE id = i.id;
    RETURN;
  END IF;
  -- A new version of a file already there goes into that file, where it is
  -- (its history kept there), whatever the layout says now.
  IF i.remote_id IS NOT NULL AND i.synced_version IS NOT NULL AND i.remote_parent IS NOT NULL THEN
    UPDATE public._docs_items SET parent_id = i.remote_parent, name = COALESCE(i.remote_name, i.name), updated_at = now() WHERE id = i.id;
    v_job := public._docs_plan(c, jsonb_build_object('docs', 'session', 'target', i.target_key, 'item', i.id, 'remote', i.remote_id));
    UPDATE public._docs_items SET job = v_job, updated_at = now() WHERE id = i.id;
    RETURN;
  END IF;
  -- Where it goes, worked out once a go (the layout as it is now).
  IF i.folders IS NULL OR i.name IS NULL THEN
    pl := public._docs_place(c, i.kind, public._docs_vars(i.kind, i.assessment_id, i.client_id, i.file_name, i.file_at));
    v_f := ARRAY(SELECT jsonb_array_elements_text(pl -> 'folders'));
    UPDATE public._docs_items SET folders = v_f, name = pl ->> 'name', updated_at = now() WHERE id = i.id;
    i.folders := v_f; i.name := pl ->> 'name';
  END IF;
  -- One file at a time decides which folder to ask for, so two never make
  -- the same one (Drive would keep both).
  PERFORM pg_advisory_xact_lock(hashtext('pental_docs_folders'), hashtext(i.target_key));
  v_parent := t.base_id;
  FOR k IN 1 .. COALESCE(cardinality(i.folders), 0) LOOP
    v_path := array_to_string(i.folders[1:k], '/');
    SELECT f.remote_id INTO v_id FROM public._docs_folders f WHERE f.target_key = i.target_key AND f.path = v_path;
    IF v_id IS NULL THEN
      -- Another file asking for the same folder is waited for.
      IF EXISTS (SELECT 1 FROM public._net_jobs j WHERE j.kind IN ('docs_graph', 'drive', 'drive_token', 'teams_token') AND j.state IN ('planned', 'queued', 'sending')
                    AND j.subject ->> 'target' = i.target_key AND (j.subject ->> 'path' = v_path OR j.subject #>> '{then,path}' = v_path)) THEN
        RETURN;
      END IF;
      v_job := public._docs_plan(c, jsonb_build_object('docs', CASE WHEN c ->> 'provider' = 'gdrive' THEN 'find' ELSE 'folder' END,
        'target', i.target_key, 'path', v_path, 'parent', v_parent, 'name', i.folders[k], 'item', i.id));
      UPDATE public._docs_items SET job = v_job, updated_at = now() WHERE id = i.id;
      RETURN;
    END IF;
    v_parent := v_id;
    v_id := NULL;
  END LOOP;
  UPDATE public._docs_items SET parent_id = v_parent, updated_at = now() WHERE id = i.id;
  -- Its upload address; or, where one was asked for before and its sender
  -- went away (it may have arrived though nobody said so), looked for there
  -- by its name first, so it is never sent twice.
  v_job := public._docs_plan(c, jsonb_build_object('docs', CASE WHEN i.session_at IS NOT NULL THEN 'lookup' ELSE 'session' END, 'target', i.target_key, 'item', i.id));
  UPDATE public._docs_items SET job = v_job, updated_at = now() WHERE id = i.id;
END $dsadv$;
REVOKE ALL ON FUNCTION public._docs_advance(uuid) FROM PUBLIC, anon, authenticated;

-- An upload address, as Microsoft or Google gives one: https, and on their
-- own upload hosts (Google's is www.googleapis.com, whatever address the
-- session was begun at; or, for a suite, its stand-in's).
CREATE OR REPLACE FUNCTION public._docs_link_ok(p_provider text, p_url text) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = public, pg_catalog, pg_temp AS $dslinkok$
DECLARE v_origin text := public._net_origin(p_url);
  v_host text := lower(substring(COALESCE(p_url, '') FROM '^https://([^/:?#@]+)(:443)?(/|$)'));
BEGIN
  IF v_origin IS NULL OR length(p_url) > 4000 OR p_url ~ '[[:space:][:cntrl:]"<>\\]' THEN RETURN false; END IF;
  IF p_provider = 'sharepoint' THEN
    RETURN COALESCE(v_host ~ '(^|\.)(sharepoint\.com|sharepoint\.us|sharepoint-mil\.us|sharepoint\.de|sharepoint\.cn|1drv\.com|onedrive\.com|microsoftpersonalcontent\.com)$', false)
        OR v_origin = public._net_origin(public._net_endpoint('graph'));
  END IF;
  RETURN (v_host = 'www.googleapis.com' AND p_url ~ '^https://www\.googleapis\.com(:443)?/upload/')
      OR v_origin = public._net_origin(public._net_endpoint('drive_upload'));
END $dslinkok$;
REVOKE ALL ON FUNCTION public._docs_link_ok(text, text) FROM PUBLIC, anon, authenticated;

-- ── The answers ────────────────────────────────────────────────────────────
-- A folder there, kept, and whatever was waiting for it moved on.
CREATE OR REPLACE FUNCTION public._docs_folder_kept(p_key text, p_path text, p_id text, p_url text, p_base boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsfkept$
DECLARE c jsonb := public._docs_cfg(); r record;
BEGIN
  INSERT INTO public._docs_folders (target_key, path, remote_id, web_url) VALUES (p_key, p_path, p_id, left(p_url, 2000))
  ON CONFLICT (target_key, path) DO UPDATE SET remote_id = EXCLUDED.remote_id, web_url = COALESCE(EXCLUDED.web_url, public._docs_folders.web_url), made_at = now();
  IF p_base THEN
    PERFORM public._docs_target_step(c, p_key, NULL);
  END IF;
  FOR r IN SELECT id FROM public._docs_items WHERE target_key = p_key AND state = 'linking' AND NOT public._docs_job_live(job) LIMIT 50 LOOP
    PERFORM public._docs_advance(r.id);
  END LOOP;
END $dsfkept$;
REVOKE ALL ON FUNCTION public._docs_folder_kept(text, text, text, text, boolean) FROM PUBLIC, anon, authenticated;

-- Microsoft's answer to a Graph step.
CREATE OR REPLACE FUNCTION public._docs_graph_answer(j public._net_jobs, p_status integer, p_content text, p_error text, p_transport text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgans$
DECLARE o jsonb := public._tk_parse(p_content); s jsonb := j.subject; v_step text := s ->> 'docs'; v_key text := s ->> 'target';
  c jsonb := public._docs_cfg(); v_err text; v_lib text; d jsonb; v_item uuid; it public._docs_items; r jsonb; v_in integer; t public._docs_target;
BEGIN
  -- 1848: the giving of SharePoint's access has answers of its own.
  IF COALESCE(v_step, '') LIKE 'ms\_%' THEN RETURN public._docs_ms_answer(j, p_status, p_content, p_error, p_transport); END IF;
  IF s ? 'item' THEN v_item := (s ->> 'item')::uuid; END IF;
  IF p_status = 401 THEN
    UPDATE public._teams_cache SET token = NULL, expires_at = NULL, updated_at = now() WHERE id;
    DELETE FROM public._docs_ms_cache WHERE id;
  END IF;
  v_err := public._docs_said(o, p_status, p_error, p_transport, 'Microsoft');
  -- 1848: refused for want of SharePoint's permission (403; or 401 for an
  -- access that carries no permission at all): said with what puts it right,
  -- which Settings offers to do (Give access with Microsoft), and kept with
  -- where the files go, which is looked for again every minute until found.
  IF p_status = 403 OR (p_status = 401 AND COALESCE(o #>> '{error,message}', '') ~* 'roles|scp') THEN
    v_err := v_err || ' Y' || substr(public._docs_ms_words(public._docs_ms_app() ->> 'via'), 2)
      || ' needs access to SharePoint''s sites (Sites.ReadWrite.All): give it with Microsoft in Settings, SharePoint & Drive (an administrator of your Microsoft 365 signs in once).';
    IF v_step IN ('site', 'drive', 'root') OR COALESCE((s ->> 'base')::boolean, false) THEN PERFORM public._docs_target_need(v_key, 'access', NULL); END IF;
  END IF;

  IF v_step = 'site' THEN
    IF p_status = 200 AND public._docs_id_ok(o ->> 'id') THEN
      UPDATE public._docs_target SET site_id = o ->> 'id', site_url = left(o ->> 'webUrl', 2000), site_name = left(o ->> 'displayName', 300), updated_at = now()
       WHERE id AND target_key IS NOT DISTINCT FROM v_key;
      PERFORM public._docs_target_step(c, v_key, (s ->> 'asked_by')::uuid);
      RETURN jsonb_build_object('ok', true);
    END IF;
    PERFORM public._docs_target_fail(v_key, CASE WHEN p_status = 404 THEN 'Microsoft found no SharePoint site at that address. Copy it from the site''s own page (https://…sharepoint.com/sites/…).' ELSE v_err END);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'drive' THEN
    IF p_status = 200 THEN
      v_lib := lower(COALESCE(c #>> '{sharepoint,library}', ''));
      IF v_lib = '' AND public._docs_id_ok(o ->> 'id') THEN
        d := o;
      ELSIF jsonb_typeof(o -> 'value') = 'array' THEN
        SELECT x INTO d FROM jsonb_array_elements(o -> 'value') AS x
         WHERE lower(x ->> 'name') = v_lib OR lower(regexp_replace(COALESCE(x ->> 'webUrl', ''), '^.*/', '')) = replace(v_lib, ' ', '%20') LIMIT 1;
      END IF;
      IF d IS NOT NULL AND public._docs_id_ok(d ->> 'id') THEN
        UPDATE public._docs_target SET drive_id = d ->> 'id', drive_name = left(d ->> 'name', 300), base_url = left(d ->> 'webUrl', 2000), updated_at = now()
         WHERE id AND target_key IS NOT DISTINCT FROM v_key;
        PERFORM public._docs_target_step(c, v_key, (s ->> 'asked_by')::uuid);
        RETURN jsonb_build_object('ok', true);
      END IF;
      PERFORM public._docs_target_fail(v_key, 'The site has no document library called ' || COALESCE(c #>> '{sharepoint,library}', '') || '. Leave the library blank for the site''s own Documents.');
      RETURN jsonb_build_object('ok', false, 'error', 'no such library');
    END IF;
    PERFORM public._docs_target_fail(v_key, v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'root' THEN
    IF p_status = 200 AND public._docs_id_ok(o ->> 'id') THEN
      PERFORM public._docs_folder_kept(v_key, '#root', o ->> 'id', o ->> 'webUrl', true);
      RETURN jsonb_build_object('ok', true);
    END IF;
    PERFORM public._docs_target_fail(v_key, v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step IN ('folder', 'find') THEN
    IF p_status IN (200, 201) AND public._docs_id_ok(o ->> 'id') AND (v_step = 'folder' OR jsonb_typeof(o -> 'folder') = 'object') THEN
      PERFORM public._docs_folder_kept(v_key, s ->> 'path', o ->> 'id', o ->> 'webUrl', COALESCE((s ->> 'base')::boolean, false));
      RETURN jsonb_build_object('ok', true);
    END IF;
    IF v_step = 'folder' AND p_status = 409 THEN
      -- There already: found by its name in its parent.
      PERFORM public._docs_track(s || jsonb_build_object('docs', 'find'), public._docs_graph_plan(s || jsonb_build_object('docs', 'find')));
      RETURN jsonb_build_object('ok', true, 'exists', true);
    END IF;
    IF v_step = 'find' AND p_status = 200 THEN
      v_err := 'Something called ' || COALESCE(s ->> 'name', '') || ' is there already and is not a folder.';
    END IF;
    -- The folder it was to go in is not there any more.
    IF p_status = 404 AND NOT COALESCE((s ->> 'base')::boolean, false) THEN PERFORM public._docs_folders_lost(v_key); END IF;
    IF COALESCE((s ->> 'base')::boolean, false) THEN PERFORM public._docs_target_fail(v_key, v_err);
    ELSIF v_item IS NOT NULL THEN PERFORM public._docs_fail(v_item, 'The folder ' || COALESCE(s ->> 'path', '') || ' could not be made: ' || v_err);
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'session' THEN
    SELECT * INTO it FROM public._docs_items WHERE id = v_item FOR UPDATE;
    IF NOT FOUND OR it.state <> 'linking' THEN RETURN jsonb_build_object('ok', false, 'error', 'no longer being sent'); END IF;
    IF p_status = 200 AND public._docs_link_ok('sharepoint', o ->> 'uploadUrl') AND (it.lease_by IS NOT NULL OR it.lease_worker IS NOT NULL) THEN
      INSERT INTO public._docs_links (item_id, url, provider, for_user, for_worker, expires_at)
      VALUES (it.id, o ->> 'uploadUrl', 'sharepoint', it.lease_by, it.lease_worker,
              LEAST(COALESCE(CASE WHEN COALESCE(o ->> 'expirationDateTime', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T' THEN (o ->> 'expirationDateTime')::timestamptz END, now() + interval '1 hour'), now() + interval '1 day'))
      ON CONFLICT (item_id) DO UPDATE SET url = EXCLUDED.url, for_user = EXCLUDED.for_user, for_worker = EXCLUDED.for_worker, expires_at = EXCLUDED.expires_at, created_at = now();
      UPDATE public._docs_items SET state = 'uploading', job = NULL, lease_until = now() + interval '10 minutes', session_at = now(), updated_at = now() WHERE id = it.id;
      IF it.lease_worker IS NOT NULL THEN PERFORM pg_notify('pental_docs', it.id::text); END IF;
      RETURN jsonb_build_object('ok', true);
    END IF;
    IF p_status = 404 AND COALESCE(s ->> 'remote', '') <> '' THEN
      -- The file there was removed by someone: sent afresh, where planned.
      UPDATE public._docs_items SET remote_id = NULL, remote_name = NULL, remote_parent = NULL, remote_url = NULL, remote_path = NULL,
             synced_version = NULL, job = NULL, updated_at = now() WHERE id = it.id;
      PERFORM public._docs_advance(it.id);
      RETURN jsonb_build_object('ok', true, 'gone_there', true);
    END IF;
    -- The folder it was to go in is not there any more.
    IF p_status = 404 THEN PERFORM public._docs_folders_lost(v_key); END IF;
    PERFORM public._docs_fail(it.id, v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'lookup' THEN
    SELECT * INTO it FROM public._docs_items WHERE id = v_item FOR UPDATE;
    IF NOT FOUND OR it.state <> 'linking' THEN RETURN jsonb_build_object('ok', false, 'error', 'no longer being sent'); END IF;
    -- It had arrived (its name, in its folder, at its size): taken as sent,
    -- once checked, rather than sent again.
    IF p_status = 200 AND jsonb_typeof(o -> 'file') = 'object' AND public._docs_id_ok(o ->> 'id') AND o #>> '{parentReference,id}' = it.parent_id
       AND it.size IS NOT NULL AND COALESCE(o ->> 'size', '') ~ '^[0-9]{1,15}$' AND (o ->> 'size')::bigint = it.size THEN
      UPDATE public._docs_items SET state = 'verifying', candidate_id = o ->> 'id', candidate_size = it.size, job = NULL, updated_at = now() WHERE id = it.id;
      RETURN public._docs_verified(it.id, 200, o, NULL, 'sharepoint');
    END IF;
    -- Not there (or not this one): its upload address asked for.
    IF p_status IN (200, 404) THEN
      PERFORM public._docs_track(s || jsonb_build_object('docs', 'session'), public._docs_graph_plan(s || jsonb_build_object('docs', 'session')));
      RETURN jsonb_build_object('ok', true, 'found', false);
    END IF;
    PERFORM public._docs_fail(it.id, v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'verify' THEN
    RETURN public._docs_verified(v_item, p_status, o, v_err, 'sharepoint');
  ELSIF v_step = 'remove' THEN
    IF p_status = 200 AND jsonb_typeof(o -> 'responses') = 'array' THEN
      SELECT x INTO r FROM jsonb_array_elements(o -> 'responses') AS x WHERE x ->> 'id' = '1' LIMIT 1;
      IF jsonb_typeof(r -> 'status') = 'number' THEN v_in := (r ->> 'status')::integer; END IF;
    END IF;
    IF v_in IN (200, 204, 404) THEN
      IF v_item IS NOT NULL THEN
        UPDATE public._docs_items SET state = 'removed', job = NULL, last_error = NULL, remote_id = NULL, remote_name = NULL, remote_parent = NULL,
               remote_url = NULL, remote_path = NULL, synced_version = NULL, session_at = NULL, updated_at = now() WHERE id = v_item AND state = 'removing';
      END IF;
      RETURN jsonb_build_object('ok', true);
    END IF;
    v_err := public._docs_said(CASE WHEN jsonb_typeof(r -> 'body') = 'object' THEN r -> 'body' ELSE o END, COALESCE(v_in, p_status), p_error, p_transport, 'Microsoft');
    IF v_item IS NOT NULL THEN
      UPDATE public._docs_items SET job = NULL, attempts = attempts + 1, last_error = left(v_err, 500),
             next_at = now() + interval '20 minutes', updated_at = now() WHERE id = v_item AND state = 'removing';
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  END IF;
  RETURN jsonb_build_object('ok', false, 'error', 'Not a step this database takes.');
END $dsgans$;
REVOKE ALL ON FUNCTION public._docs_graph_answer(public._net_jobs, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- What arrived there, checked: the file its sender said it made, in the
-- folder planned (a new version: wherever that file is now, as someone there
-- may have moved it), at the size sent, and not in Drive's bin. Done, or why
-- not. A check that failed in passing keeps what arrived, to be checked again
-- rather than sent again (which would leave a second copy there).
CREATE OR REPLACE FUNCTION public._docs_verified(p_item uuid, p_status integer, o jsonb, p_err text, p_provider text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsver$
DECLARE it public._docs_items; v_parent text; v_parent_ok boolean; v_size bigint; v_url text; v_name text; v_version boolean; v_expect bigint;
BEGIN
  SELECT * INTO it FROM public._docs_items WHERE id = p_item FOR UPDATE;
  IF NOT FOUND OR it.state <> 'verifying' THEN RETURN jsonb_build_object('ok', false, 'error', 'no longer being checked'); END IF;
  v_version := it.remote_id IS NOT NULL AND it.candidate_id IS NOT DISTINCT FROM it.remote_id;
  IF p_status = 200 AND o ->> 'id' = it.candidate_id THEN
    v_size := CASE WHEN COALESCE(o ->> 'size', '') ~ '^[0-9]{1,15}$' THEN (o ->> 'size')::bigint END;
    IF p_provider = 'gdrive' AND COALESCE((o ->> 'trashed')::boolean, false) THEN
      -- In Drive's bin (the file, or a folder it is in, put there by someone):
      -- as good as gone. Its folders are found or made again, and it is sent
      -- afresh (not one of its tries).
      PERFORM public._docs_folders_lost(it.target_key);
      UPDATE public._docs_items
         SET state = 'pending', next_at = now(), last_error = 'It, or a folder it was in, is in Google Drive''s bin there, so it is sent afresh.',
             remote_id = NULL, remote_name = NULL, remote_parent = NULL, remote_url = NULL, remote_path = NULL, synced_version = NULL,
             candidate_id = NULL, candidate_size = NULL, session_at = NULL, folders = NULL, name = NULL, parent_id = NULL,
             lease_by = NULL, lease_worker = NULL, lease_until = NULL, job = NULL, updated_at = now()
       WHERE id = it.id;
      DELETE FROM public._docs_links WHERE item_id = it.id;
      RETURN jsonb_build_object('ok', false, 'error', 'trashed');
    END IF;
    IF p_provider = 'sharepoint' THEN
      v_parent := o #>> '{parentReference,id}';
      v_parent_ok := v_parent IS NOT DISTINCT FROM it.parent_id;
      v_url := o ->> 'webUrl';
    ELSE
      v_parent_ok := jsonb_typeof(o -> 'parents') = 'array' AND (o -> 'parents') ? it.parent_id;
      v_parent := CASE WHEN v_parent_ok THEN it.parent_id WHEN jsonb_typeof(o -> 'parents') = 'array' THEN o -> 'parents' ->> 0 END;
      v_url := o ->> 'webViewLink';
    END IF;
    v_name := left(COALESCE(o ->> 'name', it.name), 300);
    IF NOT v_parent_ok AND NOT v_version THEN
      PERFORM public._docs_fail(it.id, 'It arrived somewhere other than the folder it was sent to.');
      RETURN jsonb_build_object('ok', false, 'error', 'parent');
    END IF;
    v_expect := COALESCE(it.candidate_size, it.size);
    IF v_expect IS NOT NULL AND v_size IS NOT NULL AND v_size <> v_expect THEN
      PERFORM public._docs_fail(it.id, 'It arrived at ' || v_size || ' bytes rather than ' || v_expect || '.');
      RETURN jsonb_build_object('ok', false, 'error', 'size');
    END IF;
    UPDATE public._docs_items
       SET state = CASE WHEN version IS DISTINCT FROM taken_version THEN 'pending' ELSE 'done' END,
           remote_id = it.candidate_id, candidate_id = NULL, candidate_size = NULL, session_at = NULL, remote_name = v_name,
           remote_parent = CASE WHEN v_parent_ok THEN it.parent_id ELSE COALESCE(v_parent, it.remote_parent) END,
           remote_url = CASE WHEN v_url ~ '^https://[^[:space:]"<>]+$' THEN left(v_url, 2000) END,
           remote_path = CASE WHEN NOT v_parent_ok OR it.folders IS NULL THEN remote_path ELSE left(array_to_string(it.folders || v_name, '/'), 2000) END,
           synced_version = it.taken_version, synced_at = now(), attempts = 0, last_error = NULL,
           lease_by = NULL, lease_worker = NULL, lease_until = NULL, job = NULL, next_at = now(), updated_at = now()
     WHERE id = it.id;
    RETURN jsonb_build_object('ok', true);
  END IF;
  IF p_status = 200 THEN
    PERFORM public._docs_fail(it.id, 'The answer named another file than the one sent.');
    RETURN jsonb_build_object('ok', false, 'error', 'another file');
  END IF;
  IF p_status = 404 THEN
    -- Not there: a new version's file was removed there meanwhile (sent
    -- afresh, where planned), or what was said to have arrived did not.
    IF v_version THEN
      UPDATE public._docs_items SET remote_id = NULL, remote_name = NULL, remote_parent = NULL, remote_url = NULL, remote_path = NULL,
             synced_version = NULL WHERE id = it.id;
    END IF;
    PERFORM public._docs_fail(it.id, 'It did not arrive.');
    RETURN jsonb_build_object('ok', false, 'error', p_err);
  END IF;
  -- The check itself failed in passing (Microsoft or Google busy, the access
  -- lapsing, no answer): what arrived is kept, and checked again next time.
  PERFORM public._docs_fail(it.id, p_err, true, true);
  RETURN jsonb_build_object('ok', false, 'error', p_err);
END $dsver$;
REVOKE ALL ON FUNCTION public._docs_verified(uuid, integer, jsonb, text, text) FROM PUBLIC, anon, authenticated;

-- Google's token address: the consent's code exchanged (the lasting access
-- sealed and kept, with the account it is for), or the hour's access from
-- the lasting one; then whatever was waiting for it.
CREATE OR REPLACE FUNCTION public._docs_drive_token_answer(j public._net_jobs, p_status integer, p_content text, p_error text, p_transport text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsdtans$
DECLARE o jsonb := public._tk_parse(p_content); s jsonb := j.subject; v_secs integer; v_err text; pd public._docs_pending; v_email text; v_scope text;
  v_next uuid; v_item uuid;
BEGIN
  IF s ? 'item' AND COALESCE(s ->> 'item', '') ~ '^[0-9a-f-]{36}$' THEN v_item := (s ->> 'item')::uuid; END IF;
  v_err := public._docs_said(o, p_status, p_error, p_transport, 'Google');
  v_secs := CASE WHEN COALESCE(o ->> 'expires_in', '') ~ '^[0-9]{1,6}$' THEN (o ->> 'expires_in')::integer ELSE 3599 END;
  v_secs := GREATEST(120, LEAST(v_secs, 86400));
  IF s ->> 'docs' = 'code' THEN
    SELECT * INTO pd FROM public._docs_pending WHERE state = s ->> 'state' FOR UPDATE;
    IF pd.state IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Connecting Google Drive took too long. Start again.');
    END IF;
    IF p_status = 200 AND COALESCE(o ->> 'refresh_token', '') ~ '^[A-Za-z0-9._~+/=-]+$' AND length(o ->> 'refresh_token') BETWEEN 10 AND 2000
       AND COALESCE(o ->> 'access_token', '') ~ '^[A-Za-z0-9._~+/=-]+$' AND length(o ->> 'access_token') BETWEEN 10 AND 4000 THEN
      v_scope := left(COALESCE(o ->> 'scope', ''), 1000);
      IF v_scope !~ '(^| )https://www\.googleapis\.com/auth/drive(\.file)?( |$)' THEN
        DELETE FROM public._docs_pending WHERE state = pd.state;
        RETURN jsonb_build_object('ok', false, 'error', 'Google did not give access to Drive. Tick "See, edit, create and delete only the specific Google Drive files that you use with this app" when you connect.');
      END IF;
      v_email := lower(left(COALESCE(public._xero_jwt_claim(o ->> 'id_token', 'email'), ''), 320));
      INSERT INTO public._docs_google (id, refresh_enc, account, scope, client_hash, connected_at, connected_by, broken_at, broken_reason)
      VALUES (true, public._settings_encrypt(o ->> 'refresh_token'), NULLIF(v_email, ''), v_scope,
              encode(extensions.digest(COALESCE(pd.client_id, ''), 'sha256'), 'hex'), now(), pd.asked_by, NULL, NULL)
      ON CONFLICT (id) DO UPDATE SET refresh_enc = EXCLUDED.refresh_enc, account = EXCLUDED.account, scope = EXCLUDED.scope,
        client_hash = EXCLUDED.client_hash, connected_at = now(), connected_by = EXCLUDED.connected_by, broken_at = NULL, broken_reason = NULL;
      INSERT INTO public._docs_google_cache AS gc (id, fp, token, expires_at, updated_at)
      VALUES (true, public._docs_google_fp(), o ->> 'access_token', now() + make_interval(secs => v_secs - 60), now())
      ON CONFLICT (id) DO UPDATE SET fp = EXCLUDED.fp, token = EXCLUDED.token, expires_at = EXCLUDED.expires_at, updated_at = now();
      UPDATE public._docs_pending SET used_at = now() WHERE state = pd.state;
      -- The Drive's own folder found or made at once, so Settings can show it.
      PERFORM public._docs_target_ready(public._docs_cfg(), pd.asked_by);
      RETURN jsonb_build_object('ok', true, 'account', v_email);
    END IF;
    IF p_status = 200 THEN
      v_err := 'Google gave no lasting access to Drive. Remove the portal''s access in your Google account (Security, Third-party apps), then connect again.';
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  END IF;
  -- The hour's access.
  IF p_status = 200 AND COALESCE(o ->> 'access_token', '') ~ '^[A-Za-z0-9._~+/=-]+$' AND length(o ->> 'access_token') BETWEEN 10 AND 4000 THEN
    INSERT INTO public._docs_google_cache AS gc (id, fp, token, expires_at, updated_at)
    VALUES (true, public._docs_google_fp(), o ->> 'access_token', now() + make_interval(secs => v_secs - 60), now())
    ON CONFLICT (id) DO UPDATE SET fp = EXCLUDED.fp, token = EXCLUDED.token, expires_at = EXCLUDED.expires_at, updated_at = now();
    IF jsonb_typeof(s -> 'then') = 'object' THEN v_next := public._docs_track(s -> 'then', public._net_plan('drive', s -> 'then')); END IF;
    RETURN jsonb_build_object('ok', true, 'next', v_next);
  END IF;
  IF p_status IN (400, 401) AND COALESCE(o ->> 'error', '') IN ('invalid_grant', 'unauthorized_client', 'invalid_client') THEN
    UPDATE public._docs_google SET broken_at = now(), broken_reason = left(v_err, 300) WHERE id;
    DELETE FROM public._docs_google_cache WHERE id;
    v_err := 'Google no longer lets the portal reach this Drive (' || v_err || '). Connect it again in Settings, SharePoint & Drive.';
  END IF;
  IF v_item IS NOT NULL THEN
    PERFORM public._docs_fail(v_item, v_err);
  END IF;
  IF COALESCE((s #>> '{then,base}')::boolean, false) THEN
    PERFORM public._docs_target_fail(s #>> '{then,target}', v_err);
  END IF;
  RETURN jsonb_build_object('ok', false, 'error', v_err);
END $dsdtans$;
REVOKE ALL ON FUNCTION public._docs_drive_token_answer(public._net_jobs, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- Google's answer to a Drive step.
CREATE OR REPLACE FUNCTION public._docs_drive_answer(j public._net_jobs, p_status integer, p_content text, p_error text, p_transport text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsdans$
DECLARE o jsonb := public._tk_parse(p_content); s jsonb := j.subject; v_step text := s ->> 'docs'; v_key text := s ->> 'target'; v_err text;
  v_item uuid; it public._docs_items; f jsonb; v_loc text; v_base boolean := COALESCE((s ->> 'base')::boolean, false);
BEGIN
  IF s ? 'item' AND COALESCE(s ->> 'item', '') ~ '^[0-9a-f-]{36}$' THEN v_item := (s ->> 'item')::uuid; END IF;
  IF p_status = 401 THEN DELETE FROM public._docs_google_cache WHERE id; END IF;
  v_err := public._docs_said(o, p_status, p_error, p_transport, 'Google');
  IF v_step = 'find' THEN
    IF p_status = 200 AND jsonb_typeof(o -> 'files') = 'array' THEN
      SELECT x INTO f FROM jsonb_array_elements(o -> 'files') AS x WHERE public._docs_id_ok(x ->> 'id') LIMIT 1;
      IF f IS NOT NULL THEN
        IF v_base THEN
          UPDATE public._docs_target SET base_id = f ->> 'id', base_url = CASE WHEN f ->> 'webViewLink' ~ '^https://' THEN left(f ->> 'webViewLink', 2000) END,
                 ready = true, checking = false, job = NULL, checked_at = now(), error = NULL, updated_at = now()
           WHERE id AND target_key IS NOT DISTINCT FROM v_key;
          PERFORM public._docs_folder_kept(v_key, '#base', f ->> 'id', f ->> 'webViewLink', false);
        ELSE
          PERFORM public._docs_folder_kept(v_key, s ->> 'path', f ->> 'id', f ->> 'webViewLink', false);
        END IF;
        RETURN jsonb_build_object('ok', true);
      END IF;
      -- Not there: made.
      PERFORM public._docs_track(s || jsonb_build_object('docs', 'folder'), public._docs_drive_plan(s || jsonb_build_object('docs', 'folder')));
      RETURN jsonb_build_object('ok', true, 'making', true);
    END IF;
  ELSIF v_step = 'folder' THEN
    IF p_status IN (200, 201) AND public._docs_id_ok(o ->> 'id') THEN
      IF v_base THEN
        UPDATE public._docs_target SET base_id = o ->> 'id', base_url = CASE WHEN o ->> 'webViewLink' ~ '^https://' THEN left(o ->> 'webViewLink', 2000) END,
               ready = true, checking = false, job = NULL, checked_at = now(), error = NULL, updated_at = now()
         WHERE id AND target_key IS NOT DISTINCT FROM v_key;
        PERFORM public._docs_folder_kept(v_key, '#base', o ->> 'id', o ->> 'webViewLink', false);
      ELSE
        PERFORM public._docs_folder_kept(v_key, s ->> 'path', o ->> 'id', o ->> 'webViewLink', false);
      END IF;
      RETURN jsonb_build_object('ok', true);
    END IF;
  ELSIF v_step = 'session' THEN
    SELECT * INTO it FROM public._docs_items WHERE id = v_item FOR UPDATE;
    IF NOT FOUND OR it.state <> 'linking' THEN RETURN jsonb_build_object('ok', false, 'error', 'no longer being sent'); END IF;
    v_loc := j.answer_headers ->> 'location';
    IF p_status = 200 AND public._docs_link_ok('gdrive', v_loc) AND (it.lease_by IS NOT NULL OR it.lease_worker IS NOT NULL) THEN
      INSERT INTO public._docs_links (item_id, url, provider, for_user, for_worker, expires_at)
      VALUES (it.id, v_loc, 'gdrive', it.lease_by, it.lease_worker, now() + interval '1 day')
      ON CONFLICT (item_id) DO UPDATE SET url = EXCLUDED.url, for_user = EXCLUDED.for_user, for_worker = EXCLUDED.for_worker, expires_at = EXCLUDED.expires_at, created_at = now();
      UPDATE public._docs_items SET state = 'uploading', job = NULL, lease_until = now() + interval '10 minutes', session_at = now(), updated_at = now() WHERE id = it.id;
      IF it.lease_worker IS NOT NULL THEN PERFORM pg_notify('pental_docs', it.id::text); END IF;
      RETURN jsonb_build_object('ok', true);
    END IF;
    IF p_status = 200 THEN
      v_err := 'Google gave no upload address (its answer had no Location).';
    ELSIF p_status = 404 AND COALESCE(s ->> 'remote', '') = '' THEN
      -- The folder it was to go in is not there any more.
      PERFORM public._docs_folders_lost(v_key);
    ELSIF p_status IN (400, 403, 404) AND COALESCE(s ->> 'remote', '') <> '' THEN
      -- The file there is gone, or Google would not take a new version of it:
      -- sent afresh, where planned.
      UPDATE public._docs_items SET remote_id = NULL, remote_name = NULL, remote_parent = NULL, remote_url = NULL, remote_path = NULL,
             synced_version = NULL, job = NULL, updated_at = now() WHERE id = it.id;
      PERFORM public._docs_advance(it.id);
      RETURN jsonb_build_object('ok', true, 'gone_there', true);
    END IF;
    PERFORM public._docs_fail(it.id, v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'lookup' THEN
    SELECT * INTO it FROM public._docs_items WHERE id = v_item FOR UPDATE;
    IF NOT FOUND OR it.state <> 'linking' THEN RETURN jsonb_build_object('ok', false, 'error', 'no longer being sent'); END IF;
    IF p_status = 200 AND jsonb_typeof(o -> 'files') = 'array' THEN
      -- It had arrived (its name, in its folder, at its size): taken as
      -- sent, once checked, rather than sent again.
      IF it.size IS NOT NULL THEN
        SELECT x INTO f FROM jsonb_array_elements(o -> 'files') AS x
         WHERE public._docs_id_ok(x ->> 'id') AND COALESCE(x ->> 'size', '') ~ '^[0-9]{1,15}$' AND (x ->> 'size')::bigint = it.size
           AND jsonb_typeof(x -> 'parents') = 'array' AND (x -> 'parents') ? it.parent_id LIMIT 1;
      END IF;
      IF f IS NOT NULL THEN
        UPDATE public._docs_items SET state = 'verifying', candidate_id = f ->> 'id', candidate_size = it.size, job = NULL, updated_at = now() WHERE id = it.id;
        RETURN public._docs_verified(it.id, 200, f, NULL, 'gdrive');
      END IF;
      -- Not there: its upload address asked for.
      PERFORM public._docs_track(s || jsonb_build_object('docs', 'session'), public._docs_drive_plan(s || jsonb_build_object('docs', 'session')));
      RETURN jsonb_build_object('ok', true, 'found', false);
    END IF;
    -- The folder it was to go in is not there any more.
    IF p_status = 404 THEN PERFORM public._docs_folders_lost(v_key); END IF;
    PERFORM public._docs_fail(it.id, v_err);
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSIF v_step = 'verify' THEN
    RETURN public._docs_verified(v_item, p_status, o, v_err, 'gdrive');
  ELSIF v_step = 'remove' THEN
    IF p_status IN (200, 204, 404) THEN
      IF v_item IS NOT NULL THEN
        UPDATE public._docs_items SET state = 'removed', job = NULL, last_error = NULL, remote_id = NULL, remote_name = NULL, remote_parent = NULL,
               remote_url = NULL, remote_path = NULL, synced_version = NULL, session_at = NULL, updated_at = now() WHERE id = v_item AND state = 'removing';
      END IF;
      RETURN jsonb_build_object('ok', true);
    END IF;
    IF v_item IS NOT NULL THEN
      UPDATE public._docs_items SET job = NULL, attempts = attempts + 1, last_error = left(v_err, 500),
             next_at = now() + interval '20 minutes', updated_at = now() WHERE id = v_item AND state = 'removing';
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', v_err);
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'Not a step this database takes.');
  END IF;
  -- A folder's step that failed.
  IF p_status = 403 THEN
    -- 1848: Google's Drive API switched off for the project: said, with the
    -- project's own page to switch it on (Settings offers it), and kept with
    -- where the files go, which is looked for again every minute until found.
    v_loc := public._docs_drive_api_url(o);
    IF v_loc IS NOT NULL THEN
      v_err := 'Google''s Drive API is switched off for your Google sign-in application''s project. Switch it on there (Settings opens the page): the files are found again within a minute or two of it.';
      PERFORM public._docs_target_need(v_key, 'drive_api', v_loc);
    ELSE
      v_err := v_err || ' The Google sign-in application needs the Google Drive API switched on in its Google Cloud project, and the Drive scope (drive.file) on its consent screen.';
    END IF;
  END IF;
  IF p_status = 404 AND NOT v_base THEN PERFORM public._docs_folders_lost(v_key); END IF;
  IF v_base THEN PERFORM public._docs_target_fail(v_key, v_err);
  ELSIF v_item IS NOT NULL THEN PERFORM public._docs_fail(v_item, 'The folder ' || COALESCE(s ->> 'path', '') || ' could not be made: ' || v_err);
  END IF;
  RETURN jsonb_build_object('ok', false, 'error', v_err);
END $dsdans$;
REVOKE ALL ON FUNCTION public._docs_drive_answer(public._net_jobs, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- ── The clock ──────────────────────────────────────────────────────────────
-- From _net_tick: a file left unfinished by a gateway or a browser that went
-- away, tried again later; one whose call landed moved on; one gone from here
-- removed there (a few at a time); the files looked through every two
-- minutes; upload addresses past their time cleared; and a gateway's worker
-- told when there is something to send.
CREATE OR REPLACE FUNCTION public._docs_tick() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstick$
DECLARE c jsonb := public._docs_cfg(); v_key text; r record; v_scan integer := 0; v_no jsonb; v_job uuid; t public._docs_target;
BEGIN
  DELETE FROM public._docs_links WHERE expires_at < now();
  DELETE FROM public._docs_pending WHERE created_at < now() - interval '1 hour';
  -- 1848: a giving of SharePoint's access that heard nothing back for ten
  -- minutes is over, its sign-in's access forgotten (as it is once it
  -- lapses), and none is kept past the hour.
  UPDATE public._docs_ms_grant SET token = NULL, token_until = NULL, job = NULL, step = 'failed', ok = false,
         error = COALESCE(error, 'No answer came back from Microsoft. Start again.'), updated_at = now()
   WHERE step NOT IN ('done', 'failed') AND updated_at < now() - interval '10 minutes';
  UPDATE public._docs_ms_grant SET token = NULL, token_until = NULL WHERE token IS NOT NULL AND (token_until IS NULL OR token_until < now());
  DELETE FROM public._docs_ms_grant WHERE created_at < now() - interval '1 hour';
  IF NOT COALESCE((c ->> 'on')::boolean, false) THEN RETURN jsonb_build_object('on', false); END IF;
  v_key := public._docs_target_key(c);
  IF v_key IS NULL THEN RETURN jsonb_build_object('on', true, 'target', false); END IF;
  -- Whoever was sending it went away: let go, for someone else to send in a
  -- minute (not one of its tries; what it may have sent is looked for there
  -- first, _docs_advance).
  FOR r IN SELECT id, state, lease_worker FROM public._docs_items
            WHERE target_key = v_key AND state IN ('linking', 'uploading') AND lease_until < now() AND NOT public._docs_job_live(job) LIMIT 50 LOOP
    PERFORM public._docs_fail(r.id, CASE WHEN r.lease_worker IS NOT NULL AND r.state = 'uploading' THEN 'The gateway sending it stopped before it had finished.'
                                         WHEN r.state = 'uploading' THEN 'The browser sending it closed before it had finished.'
                                         ELSE 'It was left part way.' END, true, false);
  END LOOP;
  -- A check whose answer will not come: what arrived is kept, and checked
  -- again next time rather than sent again.
  FOR r IN SELECT id FROM public._docs_items
            WHERE target_key = v_key AND state = 'verifying' AND NOT public._docs_job_live(job) AND updated_at < now() - interval '2 minutes' LIMIT 50 LOOP
    PERFORM public._docs_fail(r.id, 'What arrived could not be checked.', true, true);
  END LOOP;
  SELECT * INTO t FROM public._docs_target WHERE id;
  IF t.checking AND NOT public._docs_job_live(t.job) AND t.updated_at < now() - interval '2 minutes' THEN
    PERFORM public._docs_target_fail(t.target_key, 'No answer came back while finding where the files go.');
  END IF;
  v_no := public._docs_cannot(c);
  IF v_no IS NULL THEN
    FOR r IN SELECT id FROM public._docs_items WHERE target_key = v_key AND state = 'linking' AND NOT public._docs_job_live(job) LIMIT 20 LOOP
      PERFORM public._docs_advance(r.id);
    END LOOP;
    FOR r IN SELECT id, remote_id FROM public._docs_items
              WHERE target_key = v_key AND state = 'removing' AND next_at <= now() AND NOT public._docs_job_live(job) LIMIT 5 FOR UPDATE SKIP LOCKED LOOP
      IF NOT COALESCE((c ->> 'remove_remote')::boolean, false) THEN
        UPDATE public._docs_items SET state = 'gone', updated_at = now() WHERE id = r.id;
      ELSIF public._docs_target_ready(c, NULL) THEN
        v_job := public._docs_plan(c, jsonb_build_object('docs', 'remove', 'target', v_key, 'item', r.id, 'remote', r.remote_id));
        UPDATE public._docs_items SET job = v_job, updated_at = now() WHERE id = r.id;
      END IF;
    END LOOP;
  END IF;
  -- 1848: where the files go, not found for something the firm can put right
  -- (SharePoint's access, Google's Drive API), looked for again every
  -- minute, and for anything else every five, so it is found once put right.
  IF v_no IS NULL THEN
    SELECT * INTO t FROM public._docs_target WHERE id;
    IF t.target_key IS NOT DISTINCT FROM v_key AND NOT t.ready AND NOT t.checking AND t.error IS NOT NULL
       AND t.checked_at < now() - (CASE WHEN t.need IS NOT NULL THEN interval '1 minute' ELSE interval '5 minutes' END) THEN
      PERFORM public._docs_target_ready(c, NULL);
    END IF;
  END IF;
  IF (SELECT scanned_at IS NULL OR scanned_at < now() - interval '2 minutes' FROM public._docs_state WHERE id) THEN
    v_scan := public._docs_scan();
  END IF;
  -- Behind a gateway, its worker sends them: told when something waits.
  IF v_no IS NULL AND public._net_sender() = 'gateway'
     AND EXISTS (SELECT 1 FROM public._docs_items WHERE target_key = v_key AND state IN ('pending', 'failed') AND next_at <= now()
                    AND (lease_until IS NULL OR lease_until < now())) THEN
    PERFORM pg_notify('pental_docs', '');
  END IF;
  RETURN jsonb_build_object('on', true, 'changed', v_scan);
END $dstick$;
REVOKE ALL ON FUNCTION public._docs_tick() FROM PUBLIC, anon, authenticated;

-- ── For the portal ─────────────────────────────────────────────────────────
-- Who may set it up: administrators and seniors, with a fresh second factor.
CREATE OR REPLACE FUNCTION public._docs_need_admin() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsadmin$
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() NOT IN ('admin', 'senior') THEN RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501'; END IF;
  PERFORM public._need_fresh_mfa();
END $dsadmin$;
REVOKE ALL ON FUNCTION public._docs_need_admin() FROM PUBLIC, anon, authenticated;

-- Everything Settings shows: the settings, the kinds, whether it can run and
-- why not, where the files go, the Drive connected, how many files are where,
-- the latest that failed, and when the files were last looked through.
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_get() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsget$
DECLARE c jsonb; v_key text; t public._docs_target; g public._docs_google; v_counts jsonb; v_fail jsonb; v_recent jsonb; st public._docs_state; v_tm jsonb;
  v_app jsonb; v_door jsonb; acc record; gr record;
BEGIN
  PERFORM public._docs_need_admin();
  IF pg_try_advisory_xact_lock(hashtext('pental_net_tick')) THEN PERFORM public._net_settle(); END IF;
  c := public._docs_cfg();
  v_key := public._docs_target_key(c);
  SELECT * INTO t FROM public._docs_target WHERE id;
  SELECT * INTO g FROM public._docs_google WHERE id;
  SELECT * INTO st FROM public._docs_state WHERE id;
  v_tm := public._teams_creds();
  SELECT COALESCE(jsonb_object_agg(x.state, x.n), '{}'::jsonb) INTO v_counts
    FROM (SELECT state, count(*) AS n FROM public._docs_items WHERE target_key = v_key GROUP BY state) x;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', i.id, 'file', i.file_name, 'kind', i.kind, 'error', i.last_error, 'attempts', i.attempts,
           'state', i.state, 'at', i.updated_at, 'next_at', i.next_at) ORDER BY i.updated_at DESC), '[]'::jsonb) INTO v_fail
    FROM (SELECT * FROM public._docs_items WHERE target_key = v_key AND state IN ('failed', 'held') ORDER BY updated_at DESC LIMIT 20) i;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('file', i.file_name, 'kind', i.kind, 'path', i.remote_path, 'url', i.remote_url, 'at', i.synced_at) ORDER BY i.synced_at DESC), '[]'::jsonb) INTO v_recent
    FROM (SELECT * FROM public._docs_items WHERE target_key = v_key AND state = 'done' ORDER BY synced_at DESC NULLS LAST LIMIT 8) i;
  v_app := public._docs_ms_app();
  v_door := public._docs_ms_door();
  SELECT * INTO acc FROM public._docs_ms_access WHERE id;
  SELECT * INTO gr FROM public._docs_ms_grant WHERE asked_by = auth.uid() ORDER BY created_at DESC LIMIT 1;
  RETURN jsonb_build_object(
    'cfg', c,
    'kinds', public._docs_kinds(),
    'cannot', public._docs_cannot(c),
    'by', public._docs_by(),
    'teams_ready', v_tm ->> 'tenant' IS NOT NULL AND v_tm ->> 'client' IS NOT NULL AND v_tm ->> 'secret' IS NOT NULL,
    'google_app_ready', public._sso_own('google'),
    'google', jsonb_build_object('connected', public._docs_google_connected(), 'account', g.account, 'connected_at', g.connected_at,
                                 'broken', g.broken_at IS NOT NULL, 'broken_reason', g.broken_reason),
    'root_name', public._docs_root_name(c),
    'target', CASE WHEN t.target_key IS NOT DISTINCT FROM v_key AND v_key IS NOT NULL THEN jsonb_build_object(
        'ready', t.ready, 'checking', t.checking, 'error', t.error, 'checked_at', t.checked_at,
        'site_name', t.site_name, 'site_url', t.site_url, 'drive_name', t.drive_name, 'base_url', t.base_url,
        'need', CASE WHEN t.error IS NOT NULL THEN t.need END, 'need_url', CASE WHEN t.error IS NOT NULL THEN t.need_url END) END,
    -- 1848: which Microsoft application reaches SharePoint and which an
    -- administrator signs in through to give it access (their IDs, for
    -- Microsoft Entra's own pages; no secret), the access given here, and
    -- this person's giving under way.
    'ms', jsonb_build_object('app', v_app ->> 'via', 'door', v_door ->> 'via', 'app_id', v_app ->> 'client', 'door_app_id', v_door ->> 'client',
      'signin_ready', public._docs_ms_signin() IS NOT NULL,
      'access', CASE WHEN acc.app_id IS NOT NULL AND lower(acc.app_id) = lower(COALESCE(v_app ->> 'client', '')) THEN jsonb_build_object(
        'given_at', acc.given_at, 'by', acc.given_by_name, 'tidied', acc.tidied, 'tidy_error', acc.tidy_error) END,
      'grant', CASE WHEN gr.state IS NOT NULL AND gr.created_at > now() - interval '30 minutes' THEN jsonb_build_object(
        'step', gr.step, 'ok', gr.ok, 'error', gr.error, 'admin', gr.admin, 'at', gr.updated_at) END),
    'google_project', public._docs_google_project(),
    'counts', v_counts, 'failures', v_fail, 'recent', v_recent,
    'scanned_at', st.scanned_at, 'scanned', st.scanned, 'scan_error', st.scan_error,
    'last_synced_at', (SELECT max(synced_at) FROM public._docs_items WHERE target_key = v_key));
END $dsget$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_get() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_get() TO authenticated;

-- The settings saved (kept as _docs_norm keeps them), and what Settings
-- shows then. A new target is found at once.
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_save(p_cfg jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dssave$
DECLARE c jsonb;
BEGIN
  PERFORM public._docs_need_admin();
  IF jsonb_typeof(p_cfg) IS DISTINCT FROM 'object' OR octet_length(p_cfg::text) > 20000 THEN
    RAISE EXCEPTION 'Not settings this portal keeps' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public._docs_config AS x (id, cfg, updated_at, updated_by) VALUES (true, public._docs_norm(p_cfg), now(), auth.uid())
  ON CONFLICT (id) DO UPDATE SET cfg = EXCLUDED.cfg, updated_at = now(), updated_by = EXCLUDED.updated_by;
  c := public._docs_cfg();
  IF COALESCE((c ->> 'on')::boolean, false) AND public._docs_cannot(c) IS NULL THEN
    PERFORM public._docs_target_ready(c, auth.uid());
    UPDATE public._docs_state SET scanned_at = NULL WHERE id;
  END IF;
  RETURN public.rpc_docs_sync_get();
END $dssave$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_save(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_save(jsonb) TO authenticated;

-- Where SharePoint or Drive is, found afresh now (Settings' Check).
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_check() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dscheck$
DECLARE c jsonb; v_no jsonb;
BEGIN
  PERFORM public._docs_need_admin();
  c := public._docs_cfg();
  v_no := public._docs_cannot(c);
  IF v_no IS NOT NULL THEN RETURN jsonb_build_object('ok', false) || v_no; END IF;
  UPDATE public._docs_target SET ready = false, checking = false, job = NULL, error = NULL, target_key = NULL WHERE id;
  DELETE FROM public._docs_folders WHERE target_key = public._docs_target_key(c) AND path LIKE '#%';
  PERFORM public._docs_target_ready(c, auth.uid());
  RETURN jsonb_build_object('ok', true);
END $dscheck$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_check() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_check() TO authenticated;

-- Where the files would go, for the layout being edited (not saved): the
-- firm's latest engagements (or an example), each kind kept with a file of
-- its own. { provider, base, items: [{ folders, name, kind }] }.
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_preview(p_cfg jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsprev$
DECLARE c jsonb := public._docs_norm(p_cfg); a record; k jsonb; v_items jsonb := '[]'::jsonb; v_vars jsonb; v_file text; n integer := 0; v_kind text;
  v_examples jsonb := '{"report":"Final report.pdf","attestation":"Attestation.pdf","edited":"Report.docx","paperwork":"Signed proposal.pdf",
    "files":"Scope.xlsx","client":"Network diagram.pdf","scans":"External scan.pdf","evidence":"screenshot.png","proposals":"Proposal.pdf","invoices":"Invoice INV-104.pdf"}'::jsonb;
BEGIN
  PERFORM public._docs_need_admin();
  FOR a IN SELECT x.id, x.client_id FROM public.assessments x WHERE x.archived_at IS NULL ORDER BY x.created_at DESC NULLS LAST LIMIT 2 LOOP
    n := n + 1;
    FOR k IN SELECT y FROM jsonb_array_elements(public._docs_kinds()) AS y LOOP
      v_kind := k ->> 'k';
      CONTINUE WHEN NOT COALESCE((c -> 'kinds' -> v_kind ->> 'on')::boolean, false);
      CONTINUE WHEN n > 1 AND k ->> 'level' = 'client';
      v_file := v_examples ->> v_kind;
      v_vars := public._docs_vars(v_kind, CASE WHEN k ->> 'level' = 'job' THEN a.id END, a.client_id, v_file, now());
      v_items := v_items || jsonb_build_array(public._docs_place(c, v_kind, v_vars) || jsonb_build_object('kind', v_kind));
    END LOOP;
  END LOOP;
  IF n = 0 THEN
    FOR k IN SELECT y FROM jsonb_array_elements(public._docs_kinds()) AS y LOOP
      v_kind := k ->> 'k';
      CONTINUE WHEN NOT COALESCE((c -> 'kinds' -> v_kind ->> 'on')::boolean, false);
      v_vars := jsonb_build_object('client', 'Northwind Trading', 'client_code', 'NWT', 'job_code', 'NWT-001', 'assessment', 'Web application test',
        'type', 'Web Application', 'year', to_char(now(), 'YYYY'), 'month', to_char(now(), 'MM'), 'start', to_char(now(), 'YYYY-MM-DD'),
        'file', regexp_replace(v_examples ->> v_kind, '\.[^.]+$', ''), 'ext', substring(v_examples ->> v_kind FROM '\.([^.]+)$'),
        'date', to_char(now(), 'YYYY-MM-DD'), 'kind', k ->> 'label');
      v_items := v_items || jsonb_build_array(public._docs_place(c, v_kind, v_vars) || jsonb_build_object('kind', v_kind, 'example', true));
    END LOOP;
  END IF;
  RETURN jsonb_build_object('provider', c ->> 'provider',
    'base', CASE WHEN c ->> 'provider' = 'gdrive' THEN public._docs_root_name(c) ELSE NULLIF(c #>> '{sharepoint,base_path}', '') END,
    'items', v_items);
END $dsprev$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_preview(jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_preview(jsonb) TO authenticated;

-- Everything that failed asked again, and the files looked through, now.
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_now() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsnow$
DECLARE c jsonb; v_key text;
BEGIN
  PERFORM public._docs_need_admin();
  c := public._docs_cfg();
  v_key := public._docs_target_key(c);
  UPDATE public._docs_items SET state = 'pending', attempts = 0, next_at = now(), last_error = NULL, updated_at = now()
   WHERE target_key = v_key AND state IN ('failed', 'held');
  UPDATE public._docs_items SET next_at = now() WHERE target_key = v_key AND state = 'removing';
  IF public._docs_cannot(c) IS NULL THEN PERFORM public._docs_target_ready(c, auth.uid()); END IF;
  PERFORM public._docs_scan();
  RETURN public.rpc_docs_sync_get();
END $dsnow$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_now() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_now() TO authenticated;

-- One file that failed asked again.
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_retry(p_item uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsretry$
BEGIN
  PERFORM public._docs_need_admin();
  UPDATE public._docs_items SET state = 'pending', attempts = 0, next_at = now(), last_error = NULL, updated_at = now()
   WHERE id = p_item AND state IN ('failed', 'held');
  RETURN public.rpc_docs_sync_get();
END $dsretry$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_retry(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_retry(uuid) TO authenticated;

-- ── Google Drive connected ─────────────────────────────────────────────────
-- Begun: { ok, authorize_url }, Google's own consent page for the firm's
-- Google sign-in application, asking for Drive's drive.file scope (what it
-- makes, nothing else of the Drive) and lasting access, with a PKCE
-- challenge; it comes back to the portal's own /api/sso, which hands the
-- code to the portal at its own address (#docs_state).
CREATE OR REPLACE FUNCTION public.rpc_docs_google_begin(p_origin text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsgbeg$
DECLARE v_origin text := public._sso_origin(p_origin); v_client text; v_state text; v_verifier text; v_redirect text; v_wire text; v_q jsonb; v_no jsonb;
BEGIN
  PERFORM public._docs_need_admin();
  IF public._xero_stood_down() IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'unavailable', 'error', 'Nothing is sent while this portal''s database is being moved.');
  END IF;
  IF NOT public._sso_own('google') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'no_app', 'error', 'Google Drive is reached with your Google sign-in application: save its client ID and secret in Settings, Login Page, Single sign-on first.');
  END IF;
  IF v_origin IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'This page''s address could not be read. Reload it and try again.'); END IF;
  IF public._net_sender() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'unavailable', 'error', 'This portal''s database cannot reach Google just now. Try again in a few minutes.');
  END IF;
  IF public._net_sender() = 'gateway' AND NOT public._net_gateway_can('drive_token') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'gateway_old', 'error', 'Your Pental gateway needs its update to 1.13.0 before it can reach Google Drive: paste its deploy command again (the Database step on pental.io).');
  END IF;
  IF (SELECT count(*) FROM public._docs_pending WHERE created_at > now() - interval '10 minutes') > 30 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'throttled', 'error', 'Too many tries at once. Try again in a few minutes.');
  END IF;
  v_client := (SELECT btrim(s.sso_google_client_id) FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1);
  v_state := encode(extensions.gen_random_bytes(24), 'hex');
  v_verifier := public._signin_b64u(extensions.gen_random_bytes(32));
  v_redirect := v_origin || '/api/sso';
  DELETE FROM public._docs_pending WHERE created_at < now() - interval '1 hour';
  INSERT INTO public._docs_pending (state, verifier, redirect_uri, origin, client_id, asked_by) VALUES (v_state, v_verifier, v_redirect, v_origin, v_client, auth.uid());
  v_wire := 'pd2.' || public._signin_b64u(convert_to(jsonb_build_object('p', 'google', 'o', v_origin, 's', v_state, 'w', 1, 'k', 'docs')::text, 'UTF8'));
  v_q := jsonb_build_object('client_id', v_client, 'redirect_uri', v_redirect, 'response_type', 'code',
    'scope', 'openid email https://www.googleapis.com/auth/drive.file', 'state', v_wire, 'access_type', 'offline', 'prompt', 'consent',
    'include_granted_scopes', 'true',
    'code_challenge', public._signin_b64u(extensions.digest(convert_to(v_verifier, 'UTF8'), 'sha256')), 'code_challenge_method', 'S256');
  RETURN jsonb_build_object('ok', true, 'authorize_url', public._sso_authorize_url('google', NULL) || '?' || public._xero_form(v_q));
END $dsgbeg$;
REVOKE ALL ON FUNCTION public.rpc_docs_google_begin(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_google_begin(text) TO authenticated;

-- Finished: the code Google sent back exchanged here, with the firm's
-- secret and the PKCE verifier (neither leaves this database), by whoever
-- began it. { ok } or why not; Settings then shows the account.
CREATE OR REPLACE FUNCTION public.rpc_docs_google_finish(p_state text, p_code text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgfin$
DECLARE pd public._docs_pending; v_job uuid;
BEGIN
  PERFORM public._docs_need_admin();
  SELECT * INTO pd FROM public._docs_pending WHERE state = COALESCE(p_state, '') FOR UPDATE;
  IF NOT FOUND OR pd.provider IS DISTINCT FROM 'google' OR pd.asked_by IS DISTINCT FROM auth.uid() OR pd.created_at < now() - interval '15 minutes' OR pd.used_at IS NOT NULL OR pd.job IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Connecting Google Drive was not started from this session, or took too long. Start again.');
  END IF;
  IF COALESCE(p_code, '') = '' OR length(p_code) > 4000 THEN RETURN jsonb_build_object('ok', false, 'error', 'Google sent no code back.'); END IF;
  v_job := public._net_plan('drive_token', jsonb_build_object('docs', 'code', 'state', pd.state, 'code', p_code, 'asked_by', auth.uid()::text));
  UPDATE public._docs_pending SET job = v_job WHERE state = pd.state;
  RETURN jsonb_build_object('ok', true, 'job', v_job);
END $dsgfin$;
REVOKE ALL ON FUNCTION public.rpc_docs_google_finish(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_google_finish(text, text) TO authenticated;

-- How the exchange went: { state: 'pending' } or { state, ok, account, error }.
CREATE OR REPLACE FUNCTION public.rpc_docs_google_result(p_job uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgres$
DECLARE j public._net_jobs;
BEGIN
  PERFORM public._docs_need_admin();
  IF pg_try_advisory_xact_lock(hashtext('pental_net_tick')) THEN PERFORM public._net_settle(); END IF;
  SELECT * INTO j FROM public._net_jobs WHERE id = p_job AND kind = 'drive_token' AND subject ->> 'asked_by' = auth.uid()::text;
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'gone'); END IF;
  IF j.state IN ('planned', 'queued', 'sending') THEN RETURN jsonb_build_object('state', 'pending'); END IF;
  RETURN jsonb_build_object('state', j.state, 'ok', j.state = 'done' AND COALESCE((j.outcome ->> 'ok')::boolean, false),
    'account', j.outcome ->> 'account', 'error', j.outcome ->> 'error');
END $dsgres$;
REVOKE ALL ON FUNCTION public.rpc_docs_google_result(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_google_result(uuid) TO authenticated;

-- Disconnected: the lasting access forgotten here (Google's own record of
-- the consent is the account's to remove).
CREATE OR REPLACE FUNCTION public.rpc_docs_google_disconnect() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgdis$
BEGIN
  PERFORM public._docs_need_admin();
  DELETE FROM public._docs_google WHERE id;
  DELETE FROM public._docs_google_cache WHERE id;
  UPDATE public._docs_target SET ready = false, checking = false, job = NULL WHERE id AND provider = 'gdrive';
  RETURN public.rpc_docs_sync_get();
END $dsgdis$;
REVOKE ALL ON FUNCTION public.rpc_docs_google_disconnect() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_google_disconnect() TO authenticated;

-- ── Sending the files ──────────────────────────────────────────────────────
-- Who sends them: behind a gateway, the gateway itself (from 1.13.0; it
-- reads each file where it keeps it); on Supabase, the browser of a member
-- of the firm's team whose portal is open. Never both: 'gateway' or
-- 'browser', or NULL where nothing here can reach Microsoft or Google.
CREATE OR REPLACE FUNCTION public._docs_by() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsby$
  SELECT CASE public._net_sender() WHEN 'gateway' THEN 'gateway' WHEN 'pg_net' THEN 'browser' END;
$dsby$;
REVOKE ALL ON FUNCTION public._docs_by() FROM PUBLIC, anon, authenticated;

-- Whether this person (their browser) or this gateway's worker holds a file.
CREATE OR REPLACE FUNCTION public._docs_holds(i public._docs_items, p_user uuid, p_worker text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $dsholds$
  SELECT (p_user IS NOT NULL AND i.lease_worker IS NULL AND i.lease_by IS NOT DISTINCT FROM p_user)
      OR (p_worker IS NOT NULL AND i.lease_worker IS NOT DISTINCT FROM p_worker);
$dsholds$;
REVOKE ALL ON FUNCTION public._docs_holds(public._docs_items, uuid, text) FROM PUBLIC, anon, authenticated;

-- A few files taken to send (not already being sent; for a person, only
-- those they may read), each held for ten minutes and its upload address
-- asked for at once. p_origin is the portal's address in that browser, which
-- Drive's upload address answers. { on, ready, by, cannot, items: [{ id,
-- source, kind, file, size, provider }] }.
CREATE OR REPLACE FUNCTION public._docs_take(p_limit integer, p_user uuid, p_worker text, p_origin text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstake$
DECLARE c jsonb := public._docs_cfg(); v_key text; v_no jsonb; r record; v_items jsonb := '[]'::jsonb; v_origin text; v_by text;
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 2), 4)); v_n integer := 0;
BEGIN
  IF NOT COALESCE((c ->> 'on')::boolean, false) THEN RETURN jsonb_build_object('on', false); END IF;
  v_no := public._docs_cannot(c);
  IF v_no IS NOT NULL THEN RETURN jsonb_build_object('on', true, 'ready', false, 'cannot', v_no); END IF;
  v_by := public._docs_by();
  IF v_by IS DISTINCT FROM (CASE WHEN p_worker IS NOT NULL THEN 'gateway' ELSE 'browser' END) THEN
    RETURN jsonb_build_object('on', true, 'ready', true, 'by', v_by, 'items', '[]'::jsonb);
  END IF;
  v_key := public._docs_target_key(c);
  IF pg_try_advisory_xact_lock(hashtext('pental_net_tick')) THEN PERFORM public._net_settle(); END IF;
  -- What was added since is found within a quarter of a minute of a sender
  -- asking (the clock looks every two minutes besides).
  IF (SELECT scanned_at IS NULL OR scanned_at < now() - interval '15 seconds' FROM public._docs_state WHERE id) THEN
    PERFORM public._docs_scan();
  END IF;
  IF NOT public._docs_target_ready(c, NULL) THEN RETURN jsonb_build_object('on', true, 'ready', false, 'by', v_by, 'items', '[]'::jsonb); END IF;
  IF p_user IS NOT NULL THEN
    v_origin := CASE WHEN lower(rtrim(btrim(COALESCE(p_origin, '')), '/')) ~ '^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:[0-9]{2,5})?$'
                     THEN lower(rtrim(btrim(p_origin), '/')) END;
  END IF;
  -- The next few due, oldest first; for a person, only those they may read
  -- (asked of the few looked at, never of every file waiting).
  FOR r IN SELECT i.id, i.source FROM public._docs_items i
            WHERE i.target_key = v_key AND i.state IN ('pending', 'failed') AND i.next_at <= now()
              AND (i.lease_until IS NULL OR i.lease_until < now())
            ORDER BY i.state = 'failed', i.next_at, i.file_at NULLS LAST
            LIMIT v_limit * 5 FOR UPDATE SKIP LOCKED LOOP
    EXIT WHEN v_n >= v_limit;
    CONTINUE WHEN p_worker IS NULL AND NOT public.can_access_assessment_file(r.source);
    -- What arrived for it before and is still to be checked keeps its place
    -- (and the version it was), to be checked rather than sent again.
    UPDATE public._docs_items
       SET state = 'linking', lease_by = p_user, lease_worker = p_worker, lease_until = now() + interval '10 minutes', origin = v_origin,
           taken_version = CASE WHEN candidate_id IS NULL THEN version ELSE taken_version END,
           folders = CASE WHEN candidate_id IS NULL THEN NULL ELSE folders END,
           name = CASE WHEN candidate_id IS NULL THEN NULL ELSE name END,
           parent_id = CASE WHEN candidate_id IS NULL THEN NULL ELSE parent_id END,
           job = NULL, updated_at = now()
     WHERE id = r.id;
    v_n := v_n + 1;
    PERFORM public._docs_advance(r.id);
    v_items := v_items || (SELECT jsonb_build_array(jsonb_build_object('id', i.id, 'source', i.source, 'kind', i.kind, 'file', i.file_name,
                                                                       'size', i.size, 'provider', i.provider))
                             FROM public._docs_items i WHERE i.id = r.id);
  END LOOP;
  RETURN jsonb_build_object('on', true, 'ready', true, 'by', v_by, 'items', v_items);
END $dstake$;
REVOKE ALL ON FUNCTION public._docs_take(integer, uuid, text, text) FROM PUBLIC, anon, authenticated;

-- A browser's: a member of the firm's team (not a client, not a contractor)
-- with their second factor fresh.
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_take(p_limit integer DEFAULT 2, p_origin text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsrtake$
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() NOT IN ('admin', 'senior', 'standard') OR NOT public.mfa_is_fresh() THEN
    RETURN jsonb_build_object('on', false);
  END IF;
  RETURN public._docs_take(p_limit, auth.uid(), NULL, p_origin);
END $dsrtake$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_take(integer, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_take(integer, text) TO authenticated;

-- A gateway's (1.13.0), on its own connection only: what it is to send, and
-- where it keeps each file's bytes (its storage object).
CREATE OR REPLACE FUNCTION public._docs_gw_take(p_limit integer, p_worker text)
RETURNS TABLE (r_item uuid, r_object text, r_size bigint, r_provider text, r_file text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgwtake$
DECLARE v jsonb; x jsonb; v_obj text;
BEGIN
  IF COALESCE(btrim(p_worker), '') = '' THEN RETURN; END IF;
  v := public._docs_take(p_limit, NULL, p_worker, NULL);
  FOR x IN SELECT y FROM jsonb_array_elements(COALESCE(v -> 'items', '[]'::jsonb)) AS y LOOP
    v_obj := NULL;
    IF to_regclass('storage.objects') IS NOT NULL THEN
      EXECUTE $q$SELECT id::text FROM storage.objects WHERE bucket_id = 'assessment-files' AND name = $1$q$ INTO v_obj USING x ->> 'source';
    END IF;
    IF v_obj IS NULL THEN
      PERFORM public._docs_fail((x ->> 'id')::uuid, 'It is no longer in the portal''s storage.');
      CONTINUE;
    END IF;
    r_item := (x ->> 'id')::uuid; r_object := v_obj; r_size := (x ->> 'size')::bigint; r_provider := x ->> 'provider'; r_file := x ->> 'file';
    RETURN NEXT;
  END LOOP;
END $dsgwtake$;
REVOKE ALL ON FUNCTION public._docs_gw_take(integer, text) FROM PUBLIC, anon, authenticated;

-- Where a file taken is (its sender asks every second or so): linking,
-- uploading with its upload address (for whoever took it and no one else),
-- verifying, done, failed. pg_net's answers are applied here as they land.
CREATE OR REPLACE FUNCTION public._docs_step(p_item uuid, p_user uuid, p_worker text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsstep$
DECLARE i public._docs_items; l public._docs_links;
BEGIN
  IF pg_try_advisory_xact_lock(hashtext('pental_net_tick')) THEN PERFORM public._net_settle(); END IF;
  SELECT * INTO i FROM public._docs_items WHERE id = p_item;
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'gone'); END IF;
  IF i.state IN ('linking', 'uploading', 'verifying') AND NOT public._docs_holds(i, p_user, p_worker) THEN RETURN jsonb_build_object('state', 'elsewhere'); END IF;
  IF i.state = 'linking' THEN
    UPDATE public._docs_items SET lease_until = GREATEST(lease_until, now() + interval '5 minutes') WHERE id = i.id;
    PERFORM public._docs_advance(i.id);
    SELECT * INTO i FROM public._docs_items WHERE id = p_item;
  END IF;
  IF i.state = 'uploading' THEN
    SELECT * INTO l FROM public._docs_links
     WHERE item_id = i.id AND expires_at > now()
       AND ((p_user IS NOT NULL AND for_worker IS NULL AND for_user = p_user) OR (p_worker IS NOT NULL AND for_worker = p_worker));
    IF l.item_id IS NULL THEN
      PERFORM public._docs_fail(i.id, 'Its upload address lapsed before it was used.');
      RETURN jsonb_build_object('state', 'failed', 'error', 'Its upload address lapsed before it was used.');
    END IF;
    -- Its sender asks between pieces, so a file being sent stays its own; one
    -- whose sender went away is let go ten minutes after it was last heard of.
    UPDATE public._docs_items SET lease_until = GREATEST(lease_until, now() + interval '10 minutes') WHERE id = i.id;
    -- SharePoint keeps an upload session open while its pieces keep arriving
    -- (each moves its expiry on), so its address is kept here as long.
    IF l.provider = 'sharepoint' THEN
      UPDATE public._docs_links SET expires_at = GREATEST(expires_at, now() + interval '15 minutes') WHERE item_id = i.id;
    END IF;
    -- In pieces of 5 MiB: a multiple of both 320 KiB (SharePoint) and 256
    -- KiB (Drive), as each asks of every piece but the last.
    RETURN jsonb_build_object('state', 'uploading', 'provider', l.provider, 'url', l.url, 'size', i.size, 'chunk', 5242880, 'name', i.name);
  END IF;
  RETURN jsonb_build_object('state', i.state, 'error', CASE WHEN i.state IN ('failed', 'held', 'pending') THEN i.last_error END,
    'url', CASE WHEN i.state = 'done' THEN i.remote_url END, 'path', CASE WHEN i.state = 'done' THEN i.remote_path END);
END $dsstep$;
REVOKE ALL ON FUNCTION public._docs_step(uuid, uuid, text) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_docs_sync_step(p_item uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsrstep$
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() NOT IN ('admin', 'senior', 'standard') THEN RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501'; END IF;
  RETURN public._docs_step(p_item, auth.uid(), NULL);
END $dsrstep$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_step(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_step(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public._docs_gw_step(p_item uuid, p_worker text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgwstep$
BEGIN
  IF COALESCE(btrim(p_worker), '') = '' THEN RETURN jsonb_build_object('state', 'elsewhere'); END IF;
  RETURN public._docs_step(p_item, NULL, p_worker);
END $dsgwstep$;
REVOKE ALL ON FUNCTION public._docs_gw_step(uuid, text) FROM PUBLIC, anon, authenticated;

-- Sent: the file SharePoint or Drive says it made, checked from here before
-- it is taken as done (its folder, and the size its sender sent: a file
-- replaced here while it was being sent is sent again as a new version).
DROP FUNCTION IF EXISTS public._docs_uploaded(uuid, text, uuid, text);
CREATE OR REPLACE FUNCTION public._docs_uploaded(p_item uuid, p_remote_id text, p_user uuid, p_worker text, p_size bigint DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsup$
DECLARE i public._docs_items; c jsonb := public._docs_cfg(); v_job uuid;
BEGIN
  SELECT * INTO i FROM public._docs_items WHERE id = p_item FOR UPDATE;
  IF NOT FOUND OR i.state <> 'uploading' OR NOT public._docs_holds(i, p_user, p_worker) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a file this sender is sending.');
  END IF;
  IF NOT public._docs_id_ok(p_remote_id) THEN
    PERFORM public._docs_fail(i.id, 'The answer to its upload named no file.');
    RETURN jsonb_build_object('ok', false, 'error', 'no file named');
  END IF;
  DELETE FROM public._docs_links WHERE item_id = i.id;
  UPDATE public._docs_items SET state = 'verifying', candidate_id = p_remote_id, candidate_size = CASE WHEN p_size > 0 THEN p_size ELSE size END,
         lease_until = now() + interval '5 minutes', updated_at = now() WHERE id = i.id;
  v_job := public._docs_plan(c, jsonb_build_object('docs', 'verify', 'target', i.target_key, 'item', i.id));
  UPDATE public._docs_items SET job = v_job WHERE id = i.id;
  RETURN jsonb_build_object('ok', true);
END $dsup$;
REVOKE ALL ON FUNCTION public._docs_uploaded(uuid, text, uuid, text, bigint) FROM PUBLIC, anon, authenticated;

DROP FUNCTION IF EXISTS public.rpc_docs_sync_uploaded(uuid, text);
CREATE OR REPLACE FUNCTION public.rpc_docs_sync_uploaded(p_item uuid, p_remote_id text, p_size bigint DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsrup$
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() NOT IN ('admin', 'senior', 'standard') THEN RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501'; END IF;
  RETURN public._docs_uploaded(p_item, p_remote_id, auth.uid(), NULL, p_size);
END $dsrup$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_uploaded(uuid, text, bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_uploaded(uuid, text, bigint) TO authenticated;

DROP FUNCTION IF EXISTS public._docs_gw_uploaded(uuid, text, text);
CREATE OR REPLACE FUNCTION public._docs_gw_uploaded(p_item uuid, p_remote_id text, p_worker text, p_size bigint DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgwup$
BEGIN
  IF COALESCE(btrim(p_worker), '') = '' THEN RETURN jsonb_build_object('ok', false); END IF;
  RETURN public._docs_uploaded(p_item, p_remote_id, NULL, p_worker, p_size);
END $dsgwup$;
REVOKE ALL ON FUNCTION public._docs_gw_uploaded(uuid, text, text, bigint) FROM PUBLIC, anon, authenticated;

-- Not sent, as its sender found (the file could not be read, or the upload
-- was refused there): tried again in a while.
-- (p_count false: its sender is stopping, which is not one of its tries.)
DROP FUNCTION IF EXISTS public._docs_failed(uuid, text, uuid, text);
CREATE OR REPLACE FUNCTION public._docs_failed(p_item uuid, p_error text, p_user uuid, p_worker text, p_count boolean DEFAULT true) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsfailed$
DECLARE i public._docs_items;
BEGIN
  SELECT * INTO i FROM public._docs_items WHERE id = p_item;
  IF NOT FOUND OR i.state NOT IN ('linking', 'uploading') OR NOT public._docs_holds(i, p_user, p_worker) THEN
    RETURN jsonb_build_object('ok', false);
  END IF;
  PERFORM public._docs_fail(p_item, left(regexp_replace(COALESCE(p_error, ''), '[[:cntrl:]]+', ' ', 'g'), 300), false, COALESCE(p_count, true));
  RETURN jsonb_build_object('ok', true);
END $dsfailed$;
REVOKE ALL ON FUNCTION public._docs_failed(uuid, text, uuid, text, boolean) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.rpc_docs_sync_failed(p_item uuid, p_error text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsrfailed$
BEGIN
  IF auth.uid() IS NULL OR public.current_user_role() NOT IN ('admin', 'senior', 'standard') THEN RAISE EXCEPTION 'Not authorised' USING ERRCODE = '42501'; END IF;
  RETURN public._docs_failed(p_item, p_error, auth.uid(), NULL);
END $dsrfailed$;
REVOKE ALL ON FUNCTION public.rpc_docs_sync_failed(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_sync_failed(uuid, text) TO authenticated;

DROP FUNCTION IF EXISTS public._docs_gw_failed(uuid, text, text);
CREATE OR REPLACE FUNCTION public._docs_gw_failed(p_item uuid, p_error text, p_worker text, p_count boolean DEFAULT true) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgwfailed$
BEGIN
  IF COALESCE(btrim(p_worker), '') = '' THEN RETURN jsonb_build_object('ok', false); END IF;
  RETURN public._docs_failed(p_item, p_error, NULL, p_worker, p_count);
END $dsgwfailed$;
REVOKE ALL ON FUNCTION public._docs_gw_failed(uuid, text, text, boolean) FROM PUBLIC, anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1848: SHAREPOINT'S ACCESS GIVEN FROM SETTINGS, AND GOOGLE'S LAST STEP ONE
-- CLICK AWAY.
--
-- [stated] Arian: "is it possible to add the extra sign in as autoamted
-- oauth step in the settings for sharepoint/google i dont want them to have
-- to do anything complicated when it can be seamless".
--
-- SharePoint is reached with an application of the firm's own that may read
-- and write its sites (Microsoft Graph's Sites.ReadWrite.All). Rather than
-- the firm adding that permission in Microsoft Entra, an administrator of its
-- Microsoft 365 signs in once from Settings, SharePoint & Drive, through the
-- firm's own Microsoft application that knows the portal's address (its
-- Microsoft sign-in application, whose address is the one sign-in uses; or
-- its Teams application, once the address is added to it), and allows it,
-- for that sign-in, to read the directory's applications and give one of
-- them a permission. The code Microsoft sends back is exchanged here, with
-- the firm's own secret and the PKCE verifier, neither of which leaves this
-- database; with the access it gives, for the minutes it lasts, this
-- database gives the firm's application SharePoint's permission (Graph's
-- appRoleAssignedTo), then takes back what the sign-in itself was allowed
-- (oauth2PermissionGrants), so nothing of it is left standing. The sign-in's
-- access is held only in an unlogged table while it is used, and forgotten
-- once it has been. Nothing passes through Pental. A firm whose only
-- Microsoft application of its own is its sign-in application reaches
-- SharePoint with that, given the permission the same way.
--
-- Google: Connect Google Drive stays the one sign-in. Where Google says its
-- Drive API is switched off for the project of the firm's Google sign-in
-- application, Settings offers that project's own page to switch it on, and
-- where the files go is looked for again by itself, every minute, until it
-- is found (as it is after SharePoint's access is given).
-- ═══════════════════════════════════════════════════════════════════════════

-- Who gave which application SharePoint's access, and when: no secret and no
-- access, only what Settings says. One row; it moves with a database.
CREATE TABLE IF NOT EXISTS public._docs_ms_access (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  via text,
  app_id text,
  tenant text,
  role text,
  given_at timestamptz,
  given_by uuid,
  given_by_name text,
  tidied boolean,
  tidy_error text,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public._docs_ms_access ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_ms_access FROM PUBLIC, anon, authenticated;

-- A giving of the access under way: which application the administrator
-- signed in through (door) and which is given the access (target), the
-- sign-in's access while it is used (forgotten once it has been), what was
-- found in the directory, and how it is going: signing_in, finding, giving,
-- tidying, done or failed. Unlogged, and gone within the hour.
CREATE UNLOGGED TABLE IF NOT EXISTS public._docs_ms_grant (
  state text PRIMARY KEY,
  asked_by uuid NOT NULL,
  door text NOT NULL,
  door_app text NOT NULL,
  target_via text NOT NULL,
  target_app text NOT NULL,
  token text,
  token_until timestamptz,
  admin text,
  tenant text,
  door_sp text,
  target_sp text,
  graph_sp text,
  role_id text,
  given boolean,
  step text NOT NULL DEFAULT 'signing_in',
  ok boolean,
  error text,
  tidy_error text,
  job uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT _docs_ms_grant_step CHECK (step IN ('signing_in', 'finding', 'giving', 'tidying', 'done', 'failed'))
);
ALTER TABLE public._docs_ms_grant SET UNLOGGED;
ALTER TABLE public._docs_ms_grant ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_ms_grant FROM PUBLIC, anon, authenticated;

-- The sign-in application's own access for the hour, where SharePoint is
-- reached with it. Unlogged: asked for again as it lapses.
CREATE UNLOGGED TABLE IF NOT EXISTS public._docs_ms_cache (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  fp text,
  token text,
  expires_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public._docs_ms_cache SET UNLOGGED;
ALTER TABLE public._docs_ms_cache ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._docs_ms_cache FROM PUBLIC, anon, authenticated;

-- A consent in flight is Google's or Microsoft's, and Microsoft's is for a
-- directory.
ALTER TABLE public._docs_pending ADD COLUMN IF NOT EXISTS provider text NOT NULL DEFAULT 'google';
ALTER TABLE public._docs_pending ADD COLUMN IF NOT EXISTS tenant text;

-- What stood in the way when where the files go was last looked for, where
-- the firm can put it right with a click: 'access' (SharePoint refused the
-- application) or 'drive_api' (Google's Drive API is switched off for the
-- project), with the page that puts it right.
ALTER TABLE public._docs_target ADD COLUMN IF NOT EXISTS need text;
ALTER TABLE public._docs_target ADD COLUMN IF NOT EXISTS need_url text;

-- ── Which application ──────────────────────────────────────────────────────
-- A Microsoft directory as an address may name it: its ID, or one of its
-- domains (contoso.onmicrosoft.com); 'organizations' (any work directory)
-- otherwise. Never 'consumers'.
CREATE OR REPLACE FUNCTION public._docs_ms_dir(p text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsmsdir$
  SELECT CASE WHEN lower(btrim(COALESCE(p, ''))) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR (length(btrim(COALESCE(p, ''))) <= 200 AND lower(btrim(COALESCE(p, ''))) ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$')
              THEN lower(btrim(p)) ELSE 'organizations' END;
$dsmsdir$;
REVOKE ALL ON FUNCTION public._docs_ms_dir(text) FROM PUBLIC, anon, authenticated;

-- The firm's own Microsoft sign-in application as saved: { client, secret,
-- tenant (as Settings names it), undecryptable }, NULL where none is saved.
CREATE OR REPLACE FUNCTION public._docs_ms_signin() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsmssign$
DECLARE r record; v_plain text;
BEGIN
  SELECT btrim(s.sso_ms_client_id) AS client, s.sso_ms_tenant AS tenant, s.sso_ms_client_secret AS plain, s.sso_ms_client_secret_enc AS enc INTO r
    FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1;
  IF NOT FOUND OR COALESCE(r.client, '') = '' OR (COALESCE(r.plain, '') = '' AND r.enc IS NULL) THEN RETURN NULL; END IF;
  v_plain := public._settings_decrypt(r.enc);
  RETURN jsonb_build_object('via', 'signin', 'client', r.client,
    'secret', COALESCE(NULLIF(v_plain, ''), NULLIF(r.plain, '')),
    'tenant', NULLIF(btrim(COALESCE(r.tenant, '')), ''),
    'undecryptable', r.enc IS NOT NULL AND v_plain IS NULL AND COALESCE(r.plain, '') = '');
END $dsmssign$;
REVOKE ALL ON FUNCTION public._docs_ms_signin() FROM PUBLIC, anon, authenticated;

-- The application SharePoint is reached with: { via ('teams' | 'signin'),
-- tenant, client, secret, undecryptable }, NULL where the firm has neither.
-- The one given the access from here while it is still saved; otherwise the
-- Teams application (as 1847 had it); otherwise the Microsoft sign-in
-- application, in the directory its access was given in (or the one Settings
-- names for it, where that is a directory's ID or domain).
CREATE OR REPLACE FUNCTION public._docs_ms_app() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsapp$
DECLARE t jsonb := public._teams_creds(); si jsonb := public._docs_ms_signin(); a public._docs_ms_access; v_teams boolean; v_tenant text;
BEGIN
  SELECT * INTO a FROM public._docs_ms_access WHERE id;
  v_teams := t ->> 'tenant' IS NOT NULL AND t ->> 'client' IS NOT NULL AND (t ->> 'secret' IS NOT NULL OR COALESCE((t ->> 'undecryptable')::boolean, false));
  IF si IS NOT NULL AND (NOT v_teams OR (a.via = 'signin' AND lower(COALESCE(a.app_id, '')) = lower(si ->> 'client'))) THEN
    v_tenant := CASE WHEN a.via = 'signin' AND lower(COALESCE(a.app_id, '')) = lower(si ->> 'client') AND public._docs_ms_dir(a.tenant) <> 'organizations' THEN public._docs_ms_dir(a.tenant)
                     WHEN public._docs_ms_dir(si ->> 'tenant') <> 'organizations' THEN public._docs_ms_dir(si ->> 'tenant') END;
    RETURN jsonb_build_object('via', 'signin', 'client', si ->> 'client', 'secret', si ->> 'secret', 'tenant', v_tenant,
                              'undecryptable', COALESCE((si ->> 'undecryptable')::boolean, false));
  END IF;
  IF v_teams THEN
    RETURN jsonb_build_object('via', 'teams', 'client', t ->> 'client', 'secret', t ->> 'secret', 'tenant', t ->> 'tenant',
                              'undecryptable', COALESCE((t ->> 'undecryptable')::boolean, false));
  END IF;
  RETURN NULL;
END $dsmsapp$;
REVOKE ALL ON FUNCTION public._docs_ms_app() FROM PUBLIC, anon, authenticated;

-- The application an administrator signs in through to give the access: the
-- Microsoft sign-in application where it is saved (Microsoft sends people
-- back to the portal's address, which is registered with it for sign-in);
-- otherwise the Teams application, whose registration must list the portal's
-- address too (Settings says so, with the address).
CREATE OR REPLACE FUNCTION public._docs_ms_door() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsdoor$
DECLARE si jsonb := public._docs_ms_signin(); t jsonb;
BEGIN
  IF si IS NOT NULL THEN RETURN si; END IF;
  t := public._teams_creds();
  IF t ->> 'client' IS NULL OR t ->> 'tenant' IS NULL OR (t ->> 'secret' IS NULL AND NOT COALESCE((t ->> 'undecryptable')::boolean, false)) THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('via', 'teams', 'client', t ->> 'client', 'secret', t ->> 'secret', 'tenant', t ->> 'tenant',
                            'undecryptable', COALESCE((t ->> 'undecryptable')::boolean, false));
END $dsmsdoor$;
REVOKE ALL ON FUNCTION public._docs_ms_door() FROM PUBLIC, anon, authenticated;

-- The application's name, as Settings calls it.
CREATE OR REPLACE FUNCTION public._docs_ms_words(p_via text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsmswords$
  SELECT CASE p_via WHEN 'teams' THEN 'your Teams application' WHEN 'signin' THEN 'your Microsoft sign-in application' ELSE 'your Microsoft application' END;
$dsmswords$;
REVOKE ALL ON FUNCTION public._docs_ms_words(text) FROM PUBLIC, anon, authenticated;

-- ── SharePoint reached with the sign-in application ─────────────────────────
-- Which credentials an hour's access came from.
CREATE OR REPLACE FUNCTION public._docs_ms_fp(a jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = public, extensions, pg_catalog, pg_temp AS $dsmsfp$
  SELECT encode(extensions.digest(COALESCE(a ->> 'via', '') || chr(31) || COALESCE(a ->> 'tenant', '') || chr(31) || COALESCE(a ->> 'client', '')
    || chr(31) || COALESCE(a ->> 'secret', ''), 'sha256'), 'hex');
$dsmsfp$;
REVOKE ALL ON FUNCTION public._docs_ms_fp(jsonb) FROM PUBLIC, anon, authenticated;

-- The access SharePoint's calls are made with, while it lasts: the Teams
-- application's (kept as Teams links keep it), or the sign-in application's.
CREATE OR REPLACE FUNCTION public._docs_ms_token_now() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmstok$
DECLARE a jsonb := public._docs_ms_app();
BEGIN
  IF a ->> 'via' = 'signin' THEN
    RETURN (SELECT c.token FROM public._docs_ms_cache c
             WHERE c.id AND c.token IS NOT NULL AND c.expires_at > now() + interval '1 minute' AND c.fp = public._docs_ms_fp(a));
  END IF;
  RETURN public._teams_token_now();
END $dsmstok$;
REVOKE ALL ON FUNCTION public._docs_ms_token_now() FROM PUBLIC, anon, authenticated;

-- The sign-in application's access for the hour, asked for with its secret
-- (a teams_token call, to Microsoft's token address, as Teams links ask).
CREATE OR REPLACE FUNCTION public._docs_ms_token_build(p_job public._net_jobs) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmstb$
DECLARE a jsonb := public._docs_ms_app();
BEGIN
  IF a ->> 'via' IS DISTINCT FROM 'signin' THEN
    RETURN jsonb_build_object('error', 'SharePoint is not reached with the Microsoft sign-in application here.', 'code', 'gone');
  END IF;
  IF a ->> 'secret' IS NULL THEN RETURN jsonb_build_object('error', 'The Microsoft sign-in application has no secret saved here.', 'code', 'config'); END IF;
  IF a ->> 'tenant' IS NULL OR public._docs_ms_dir(a ->> 'tenant') = 'organizations' THEN
    RETURN jsonb_build_object('error', 'Which Microsoft 365 the sign-in application reaches SharePoint in is not known yet: give it access to SharePoint first.', 'code', 'config');
  END IF;
  RETURN jsonb_build_object('method', 'POST', 'url', public._net_endpoint('microsoft') || '/' || public._docs_ms_dir(a ->> 'tenant') || '/oauth2/v2.0/token',
    'headers', jsonb_build_object('Content-Type', 'application/x-www-form-urlencoded', 'Accept', 'application/json'),
    'body', public._xero_form(jsonb_build_object('grant_type', 'client_credentials', 'client_id', a ->> 'client', 'client_secret', a ->> 'secret',
      'scope', 'https://graph.microsoft.com/.default')));
END $dsmstb$;
REVOKE ALL ON FUNCTION public._docs_ms_token_build(public._net_jobs) FROM PUBLIC, anon, authenticated;

-- Its answer: kept, then the call that waited for it.
CREATE OR REPLACE FUNCTION public._docs_ms_token_answer(j public._net_jobs, p_status integer, p_content text, p_error text, p_transport text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsta$
DECLARE o jsonb := public._tk_parse(p_content); v_secs integer; v_err text;
BEGIN
  IF p_status = 200 AND jsonb_typeof(o) = 'object' AND COALESCE(o ->> 'access_token', '') ~ '^[A-Za-z0-9._~+/=-]+$'
     AND length(o ->> 'access_token') BETWEEN 20 AND 16000 AND lower(COALESCE(o ->> 'token_type', 'bearer')) = 'bearer' THEN
    v_secs := CASE WHEN COALESCE(o ->> 'expires_in', '') ~ '^[0-9]{1,6}$' THEN (o ->> 'expires_in')::integer ELSE 3599 END;
    v_secs := GREATEST(120, LEAST(v_secs, 86400));
    INSERT INTO public._docs_ms_cache AS c (id, fp, token, expires_at, updated_at)
    VALUES (true, public._docs_ms_fp(public._docs_ms_app()), o ->> 'access_token', now() + make_interval(secs => v_secs - 60), now())
    ON CONFLICT (id) DO UPDATE SET fp = EXCLUDED.fp, token = EXCLUDED.token, expires_at = EXCLUDED.expires_at, updated_at = now();
    RETURN jsonb_build_object('ok', true, 'next', public._docs_after_token(j.subject - 'app'));
  END IF;
  v_err := public._teams_said(o, p_status, p_error, p_transport);
  PERFORM public._docs_token_failed(j.subject, v_err);
  RETURN jsonb_build_object('ok', false, 'step', 'access', 'error', v_err);
END $dsmsta$;
REVOKE ALL ON FUNCTION public._docs_ms_token_answer(public._net_jobs, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- ── Giving the access ──────────────────────────────────────────────────────
-- What the administrator's sign-in asks Microsoft to allow, for that sign-in
-- only: to read the directory's applications, to give one of them a
-- permission, and to take back what the sign-in itself was allowed.
CREATE OR REPLACE FUNCTION public._docs_ms_scopes() RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsmsscopes$
  SELECT 'openid profile https://graph.microsoft.com/Application.Read.All https://graph.microsoft.com/AppRoleAssignment.ReadWrite.All https://graph.microsoft.com/DelegatedPermissionGrant.ReadWrite.All';
$dsmsscopes$;
REVOKE ALL ON FUNCTION public._docs_ms_scopes() FROM PUBLIC, anon, authenticated;

-- SharePoint's permission as Microsoft Graph names it, and its well-known ID
-- (read from the directory's own Graph application where it says).
CREATE OR REPLACE FUNCTION public._docs_ms_role() RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsmsrole$
  SELECT 'Sites.ReadWrite.All';
$dsmsrole$;
REVOKE ALL ON FUNCTION public._docs_ms_role() FROM PUBLIC, anon, authenticated;

-- Begun: { ok, authorize_url, door, app, address } — Microsoft's own sign-in
-- page, for the firm's application that knows the portal's address, in the
-- firm's directory, asking for what the giving needs (and no lasting
-- access), with a PKCE challenge; it comes back to the portal's own
-- /api/sso, which hands the code to the portal at its own address
-- (#docs_state), as Google Drive's connecting does.
CREATE OR REPLACE FUNCTION public.rpc_docs_ms_begin(p_origin text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $dsmsbeg$
DECLARE v_origin text := public._sso_origin(p_origin); a jsonb; d jsonb; v_state text; v_verifier text; v_redirect text; v_wire text; v_q jsonb; v_tenant text;
BEGIN
  PERFORM public._docs_need_admin();
  IF public._xero_stood_down() IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'unavailable', 'error', 'Nothing is asked of Microsoft while this portal''s database is being moved.');
  END IF;
  a := public._docs_ms_app();
  d := public._docs_ms_door();
  IF a IS NULL OR d IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'no_app', 'error', 'SharePoint is reached with a Microsoft application of your firm''s own: save your Teams application (Settings, Integrations, Microsoft Teams) or your own Microsoft sign-in (Settings, Login Page, Single sign-on) first.');
  END IF;
  IF COALESCE((d ->> 'undecryptable')::boolean, false) OR d ->> 'secret' IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'config', 'error', 'The saved secret of ' || public._docs_ms_words(d ->> 'via') || ' cannot be read here (it was sealed with another key). Enter it again in Settings, '
      || CASE WHEN d ->> 'via' = 'teams' THEN 'Integrations, Microsoft Teams.' ELSE 'Login Page, Single sign-on.' END);
  END IF;
  IF NOT public._teams_is_object_id(a ->> 'client') OR NOT public._teams_is_object_id(d ->> 'client') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'config', 'error', 'The saved application ID is not one Microsoft gives (it looks like 00000000-0000-0000-0000-000000000000).');
  END IF;
  IF v_origin IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'This page''s address could not be read. Reload it and try again.'); END IF;
  IF public._net_sender() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'unavailable', 'error', 'This portal''s database cannot reach Microsoft just now. Try again in a few minutes.');
  END IF;
  IF public._net_sender() = 'gateway' AND NOT public._net_gateway_can('docs_graph') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'gateway_old', 'error', 'Your Pental gateway needs its update to 1.13.0 first: paste its deploy command again (the Database step on pental.io).');
  END IF;
  IF (SELECT count(*) FROM public._docs_pending WHERE created_at > now() - interval '10 minutes') > 30 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'throttled', 'error', 'Too many tries at once. Try again in a few minutes.');
  END IF;
  -- In the directory of the application to be given the access.
  v_tenant := public._docs_ms_dir(CASE WHEN a ->> 'via' = 'teams' THEN a ->> 'tenant' ELSE COALESCE(a ->> 'tenant', d ->> 'tenant') END);
  v_state := encode(extensions.gen_random_bytes(24), 'hex');
  v_verifier := public._signin_b64u(extensions.gen_random_bytes(32));
  v_redirect := v_origin || '/api/sso';
  DELETE FROM public._docs_pending WHERE created_at < now() - interval '1 hour';
  INSERT INTO public._docs_pending (state, verifier, redirect_uri, origin, client_id, asked_by, provider, tenant)
  VALUES (v_state, v_verifier, v_redirect, v_origin, d ->> 'client', auth.uid(), 'microsoft', v_tenant);
  v_wire := 'pd2.' || public._signin_b64u(convert_to(jsonb_build_object('p', 'microsoft', 'o', v_origin, 's', v_state, 'w', 1, 'k', 'docs')::text, 'UTF8'));
  v_q := jsonb_build_object('client_id', d ->> 'client', 'redirect_uri', v_redirect, 'response_type', 'code', 'response_mode', 'query',
    'scope', public._docs_ms_scopes(), 'state', v_wire, 'prompt', 'select_account',
    'code_challenge', public._signin_b64u(extensions.digest(convert_to(v_verifier, 'UTF8'), 'sha256')), 'code_challenge_method', 'S256');
  -- Microsoft's sign-in page is at its token address's own host (a suite may
  -- name the page apart, as 'microsoft_auth').
  RETURN jsonb_build_object('ok', true, 'door', d ->> 'via', 'app', a ->> 'via', 'address', v_redirect,
    'authorize_url', COALESCE(public._net_endpoint('microsoft_auth'), public._net_endpoint('microsoft')) || '/' || v_tenant || '/oauth2/v2.0/authorize?' || public._xero_form(v_q));
END $dsmsbeg$;
REVOKE ALL ON FUNCTION public.rpc_docs_ms_begin(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_ms_begin(text) TO authenticated;

-- Back from Microsoft: the code exchanged here (with the firm's secret and
-- the PKCE verifier), by whoever began it, within a quarter of an hour, once.
-- { ok, job }; rpc_docs_ms_result says how the giving went.
CREATE OR REPLACE FUNCTION public.rpc_docs_ms_finish(p_state text, p_code text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsfin$
DECLARE pd public._docs_pending; a jsonb; d jsonb; v_job uuid;
BEGIN
  PERFORM public._docs_need_admin();
  SELECT * INTO pd FROM public._docs_pending WHERE state = COALESCE(p_state, '') FOR UPDATE;
  IF NOT FOUND OR pd.provider IS DISTINCT FROM 'microsoft' OR pd.asked_by IS DISTINCT FROM auth.uid() OR pd.created_at < now() - interval '15 minutes'
     OR pd.used_at IS NOT NULL OR pd.job IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Giving SharePoint access was not started from this session, or took too long. Start again.');
  END IF;
  IF COALESCE(p_code, '') = '' OR length(p_code) > 4000 THEN RETURN jsonb_build_object('ok', false, 'error', 'Microsoft sent no code back.'); END IF;
  a := public._docs_ms_app();
  d := public._docs_ms_door();
  IF a IS NULL OR d IS NULL OR lower(d ->> 'client') IS DISTINCT FROM lower(pd.client_id) OR NOT public._teams_is_object_id(a ->> 'client') THEN
    DELETE FROM public._docs_pending WHERE state = pd.state;
    RETURN jsonb_build_object('ok', false, 'error', 'Your Microsoft application was changed in Settings while you were signing in. Start again.');
  END IF;
  INSERT INTO public._docs_ms_grant (state, asked_by, door, door_app, target_via, target_app)
  VALUES (pd.state, auth.uid(), d ->> 'via', lower(d ->> 'client'), a ->> 'via', lower(a ->> 'client'))
  ON CONFLICT (state) DO NOTHING;
  v_job := public._net_plan('sso_exchange', jsonb_build_object('docs', 'ms_code', 'state', pd.state, 'code', p_code, 'asked_by', auth.uid()::text));
  UPDATE public._docs_pending SET job = v_job, used_at = now() WHERE state = pd.state;
  UPDATE public._docs_ms_grant SET job = v_job, updated_at = now() WHERE state = pd.state;
  RETURN jsonb_build_object('ok', true, 'job', v_job);
END $dsmsfin$;
REVOKE ALL ON FUNCTION public.rpc_docs_ms_finish(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_ms_finish(text, text) TO authenticated;

-- How the giving went: { state: 'pending', step } while it goes on, then
-- { state: 'done', ok, error, admin, app, tidied, tidy_error }.
CREATE OR REPLACE FUNCTION public.rpc_docs_ms_result(p_job uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsres$
DECLARE g public._docs_ms_grant;
BEGIN
  PERFORM public._docs_need_admin();
  IF pg_try_advisory_xact_lock(hashtext('pental_net_tick')) THEN PERFORM public._net_settle(); END IF;
  SELECT x.* INTO g FROM public._net_jobs j JOIN public._docs_ms_grant x ON x.state = j.subject ->> 'state'
   WHERE j.id = p_job AND j.kind = 'sso_exchange' AND j.subject ->> 'docs' = 'ms_code' AND j.subject ->> 'asked_by' = auth.uid()::text AND x.asked_by = auth.uid();
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'gone'); END IF;
  IF g.step NOT IN ('done', 'failed') THEN RETURN jsonb_build_object('state', 'pending', 'step', g.step); END IF;
  RETURN jsonb_build_object('state', 'done', 'ok', g.step = 'done' AND COALESCE(g.ok, false), 'error', g.error, 'admin', g.admin,
    'app', g.target_via, 'tidied', g.tidy_error IS NULL, 'tidy_error', g.tidy_error);
END $dsmsres$;
REVOKE ALL ON FUNCTION public.rpc_docs_ms_result(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_docs_ms_result(uuid) TO authenticated;

-- A Graph object's ID as Microsoft gives a service principal, an app role
-- or a delegated grant (letters, digits, - and _).
CREATE OR REPLACE FUNCTION public._docs_ms_id_ok(p text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $dsmsid$
  SELECT COALESCE(p ~ '^[A-Za-z0-9_-]{8,200}$', false);
$dsmsid$;
REVOKE ALL ON FUNCTION public._docs_ms_id_ok(text) FROM PUBLIC, anon, authenticated;

-- The calls of the giving, as _net_build answers: the code exchanged
-- (sso_exchange, ms_code), then with the administrator's access, Graph:
--   ms_find (one $batch: the application to be given the access, the
--     permissions it has already, Microsoft Graph's own application with its
--     permissions' IDs, the application signed in through, and what that
--     sign-in was allowed);
--   ms_give (the permission given: appRoleAssignedTo);
--   ms_tidy (one $batch: what the sign-in itself was allowed, taken back).
CREATE OR REPLACE FUNCTION public._docs_ms_build(p_job public._net_jobs) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsbuild$
DECLARE s jsonb := p_job.subject; v_step text := s ->> 'docs'; pd public._docs_pending; g public._docs_ms_grant; d jsonb; h jsonb; v_reqs jsonb := '[]'::jsonb; x jsonb;
  v_gb text := public._net_endpoint('graph'); v_graph_app constant text := '00000003-0000-0000-c000-000000000000';
BEGIN
  IF p_job.kind = 'sso_exchange' THEN
    IF v_step IS DISTINCT FROM 'ms_code' THEN RETURN jsonb_build_object('error', 'Not a call this database makes.', 'code', 'gone'); END IF;
    SELECT * INTO pd FROM public._docs_pending WHERE state = s ->> 'state';
    IF pd.state IS NULL OR pd.provider IS DISTINCT FROM 'microsoft' OR COALESCE(s ->> 'code', '') = '' OR pd.created_at < now() - interval '15 minutes' THEN
      RETURN jsonb_build_object('error', 'Giving SharePoint access was not started here, or took too long. Start again.', 'code', 'gone');
    END IF;
    d := public._docs_ms_door();
    IF d IS NULL OR lower(d ->> 'client') IS DISTINCT FROM lower(pd.client_id) OR d ->> 'secret' IS NULL THEN
      RETURN jsonb_build_object('error', 'The Microsoft application signed in through is not saved here as it was.', 'code', 'config');
    END IF;
    RETURN jsonb_build_object('method', 'POST', 'url', public._net_endpoint('microsoft') || '/' || public._docs_ms_dir(pd.tenant) || '/oauth2/v2.0/token',
      'headers', jsonb_build_object('Content-Type', 'application/x-www-form-urlencoded', 'Accept', 'application/json'),
      'body', public._xero_form(jsonb_build_object('grant_type', 'authorization_code', 'code', s ->> 'code', 'client_id', pd.client_id,
        'client_secret', d ->> 'secret', 'redirect_uri', pd.redirect_uri, 'code_verifier', pd.verifier)));
  END IF;
  SELECT * INTO g FROM public._docs_ms_grant WHERE state = s ->> 'state';
  IF g.state IS NULL OR g.token IS NULL OR g.token_until IS NULL OR g.token_until < now() THEN
    RETURN jsonb_build_object('error', 'The administrator''s sign-in has lapsed. Start again.', 'code', 'gone');
  END IF;
  IF NOT public._teams_is_object_id(g.target_app) OR NOT public._teams_is_object_id(g.door_app) THEN
    RETURN jsonb_build_object('error', 'Not an application ID Microsoft gives.', 'code', 'gone');
  END IF;
  h := jsonb_build_object('Authorization', 'Bearer ' || g.token, 'Accept', 'application/json');
  IF v_step = 'ms_find' THEN
    v_reqs := jsonb_build_array(
      jsonb_build_object('id', 'target', 'method', 'GET', 'url', '/servicePrincipals(appId=''' || g.target_app || ''')?$select=id,appId,displayName'),
      jsonb_build_object('id', 'roles', 'method', 'GET', 'url', '/servicePrincipals(appId=''' || g.target_app || ''')/appRoleAssignments?$select=id,resourceId,appRoleId'),
      jsonb_build_object('id', 'graph', 'method', 'GET', 'url', '/servicePrincipals(appId=''' || v_graph_app || ''')?$select=id,appId,appRoles'),
      jsonb_build_object('id', 'grants', 'method', 'GET', 'url', '/servicePrincipals(appId=''' || g.door_app || ''')/oauth2PermissionGrants'));
    IF g.door_app <> g.target_app THEN
      v_reqs := v_reqs || jsonb_build_array(jsonb_build_object('id', 'door', 'method', 'GET', 'url', '/servicePrincipals(appId=''' || g.door_app || ''')?$select=id,appId'));
    END IF;
    RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/$batch', 'headers', h || jsonb_build_object('Content-Type', 'application/json'),
      'body', jsonb_build_object('requests', v_reqs)::text);
  ELSIF v_step = 'ms_give' THEN
    IF NOT (public._docs_ms_id_ok(g.graph_sp) AND public._docs_ms_id_ok(g.target_sp) AND public._docs_ms_id_ok(g.role_id)) THEN
      RETURN jsonb_build_object('error', 'What the directory said could not be used.', 'code', 'gone');
    END IF;
    RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/servicePrincipals/' || g.graph_sp || '/appRoleAssignedTo',
      'headers', h || jsonb_build_object('Content-Type', 'application/json'),
      'body', jsonb_build_object('principalId', g.target_sp, 'resourceId', g.graph_sp, 'appRoleId', g.role_id)::text);
  ELSIF v_step = 'ms_tidy' THEN
    FOR x IN SELECT y FROM jsonb_array_elements(CASE WHEN jsonb_typeof(s -> 'ops') = 'array' THEN s -> 'ops' ELSE '[]'::jsonb END) AS y LOOP
      CONTINUE WHEN NOT public._docs_ms_id_ok(x ->> 'id') OR jsonb_array_length(v_reqs) >= 20;
      IF COALESCE((x ->> 'delete')::boolean, false) THEN
        v_reqs := v_reqs || jsonb_build_array(jsonb_build_object('id', 'd' || jsonb_array_length(v_reqs), 'method', 'DELETE', 'url', '/oauth2PermissionGrants/' || (x ->> 'id')));
      ELSIF COALESCE(x ->> 'scope', '') ~ '^[A-Za-z0-9._:/ -]+$' AND length(x ->> 'scope') <= 3000 THEN
        v_reqs := v_reqs || jsonb_build_array(jsonb_build_object('id', 'p' || jsonb_array_length(v_reqs), 'method', 'PATCH', 'url', '/oauth2PermissionGrants/' || (x ->> 'id'),
          'headers', jsonb_build_object('Content-Type', 'application/json'), 'body', jsonb_build_object('scope', x ->> 'scope')));
      END IF;
    END LOOP;
    IF jsonb_array_length(v_reqs) = 0 THEN RETURN jsonb_build_object('error', 'Nothing to take back.', 'code', 'gone'); END IF;
    RETURN jsonb_build_object('method', 'POST', 'url', v_gb || '/$batch', 'headers', h || jsonb_build_object('Content-Type', 'application/json'),
      'body', jsonb_build_object('requests', v_reqs)::text);
  END IF;
  RETURN jsonb_build_object('error', 'Not a step this database takes.', 'code', 'gone');
END $dsmsbuild$;
REVOKE ALL ON FUNCTION public._docs_ms_build(public._net_jobs) FROM PUBLIC, anon, authenticated;

-- The giving finished, however it went: the sign-in's access forgotten, the
-- access recorded where it was given, the application's own access for the
-- hour asked for afresh (so it carries the new permission), and where the
-- files go looked for again.
CREATE OR REPLACE FUNCTION public._docs_ms_done(p_state text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsdone$
DECLARE g public._docs_ms_grant; c jsonb;
BEGIN
  UPDATE public._docs_ms_grant
     SET token = NULL, token_until = NULL, job = NULL, step = CASE WHEN COALESCE(given, false) THEN 'done' ELSE 'failed' END,
         ok = COALESCE(given, false), updated_at = now()
   WHERE state = p_state RETURNING * INTO g;
  IF g.state IS NULL THEN RETURN; END IF;
  IF COALESCE(g.given, false) THEN
    INSERT INTO public._docs_ms_access AS x (id, via, app_id, tenant, role, given_at, given_by, given_by_name, tidied, tidy_error, updated_at)
    VALUES (true, g.target_via, g.target_app, g.tenant, public._docs_ms_role(), now(), g.asked_by, g.admin, g.tidy_error IS NULL, g.tidy_error, now())
    ON CONFLICT (id) DO UPDATE SET via = EXCLUDED.via, app_id = EXCLUDED.app_id, tenant = EXCLUDED.tenant, role = EXCLUDED.role, given_at = now(),
      given_by = EXCLUDED.given_by, given_by_name = EXCLUDED.given_by_name, tidied = EXCLUDED.tidied, tidy_error = EXCLUDED.tidy_error, updated_at = now();
    UPDATE public._teams_cache SET token = NULL, expires_at = NULL, updated_at = now() WHERE id;
    DELETE FROM public._docs_ms_cache WHERE id;
    c := public._docs_cfg();
    IF COALESCE((c ->> 'on')::boolean, false) AND c ->> 'provider' = 'sharepoint' AND public._docs_cannot(c) IS NULL THEN
      UPDATE public._docs_target SET ready = false, checking = false, job = NULL, error = NULL, need = NULL, need_url = NULL, target_key = NULL WHERE id;
      PERFORM public._docs_target_ready(c, g.asked_by);
    END IF;
  ELSIF g.tidy_error IS NOT NULL THEN
    UPDATE public._docs_ms_grant SET error = COALESCE(error, '') || CASE WHEN COALESCE(error, '') = '' THEN '' ELSE ' ' END || tidy_error WHERE state = p_state;
  END IF;
END $dsmsdone$;
REVOKE ALL ON FUNCTION public._docs_ms_done(text) FROM PUBLIC, anon, authenticated;

-- A step of the giving that could not be made: said, and what the sign-in
-- itself was allowed still taken back where it was found.
CREATE OR REPLACE FUNCTION public._docs_ms_stop(p_state text, p_error text, p_ops jsonb DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsstop$
DECLARE v_job uuid;
BEGIN
  UPDATE public._docs_ms_grant SET error = left(COALESCE(error, p_error), 800), given = COALESCE(given, false), updated_at = now() WHERE state = p_state;
  IF jsonb_typeof(p_ops) = 'array' AND jsonb_array_length(p_ops) > 0 THEN
    UPDATE public._docs_ms_grant SET step = 'tidying', updated_at = now() WHERE state = p_state;
    v_job := public._net_plan('docs_graph', jsonb_build_object('docs', 'ms_tidy', 'state', p_state, 'ops', p_ops));
    UPDATE public._docs_ms_grant SET job = v_job WHERE state = p_state;
  ELSE
    PERFORM public._docs_ms_done(p_state);
  END IF;
  RETURN jsonb_build_object('ok', false, 'error', p_error);
END $dsmsstop$;
REVOKE ALL ON FUNCTION public._docs_ms_stop(text, text, jsonb) FROM PUBLIC, anon, authenticated;

-- Microsoft's answer to the code: the administrator's access kept for the
-- minutes it lasts (in the unlogged table only, never in the call's own
-- record), who they are and in which directory, then the finding.
CREATE OR REPLACE FUNCTION public._docs_ms_code_answer(j public._net_jobs, p_status integer, p_content text, p_error text, p_transport text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmscode$
DECLARE o jsonb := public._tk_parse(p_content); s jsonb := j.subject; g public._docs_ms_grant; v_secs integer; v_scope text; v_err text; v_who text; v_tid text; v_job uuid;
BEGIN
  SELECT * INTO g FROM public._docs_ms_grant WHERE state = s ->> 'state' FOR UPDATE;
  DELETE FROM public._docs_pending WHERE state = s ->> 'state';
  IF g.state IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Giving SharePoint access took too long. Start again.'); END IF;
  IF p_status = 200 AND jsonb_typeof(o) = 'object' AND COALESCE(o ->> 'access_token', '') ~ '^[A-Za-z0-9._~+/=-]+$' AND length(o ->> 'access_token') BETWEEN 20 AND 16000 THEN
    v_scope := ' ' || lower(regexp_replace(COALESCE(o ->> 'scope', ''), '\s+', ' ', 'g')) || ' ';
    v_who := left(COALESCE(NULLIF(public._xero_jwt_claim(o ->> 'id_token', 'preferred_username'), ''), NULLIF(public._xero_jwt_claim(o ->> 'id_token', 'email'), ''),
                           NULLIF(public._xero_jwt_claim(o ->> 'id_token', 'upn'), ''), NULLIF(public._xero_jwt_claim(o ->> 'id_token', 'name'), ''), 'the administrator'), 320);
    v_tid := COALESCE(NULLIF(public._xero_jwt_claim(o ->> 'id_token', 'tid'), ''), NULLIF(public._xero_jwt_claim(o ->> 'access_token', 'tid'), ''));
    UPDATE public._docs_ms_grant SET admin = v_who, tenant = CASE WHEN public._teams_is_object_id(v_tid) THEN lower(v_tid) END, updated_at = now() WHERE state = g.state;
    -- What Microsoft says it allowed, where it says (a box left unticked, or a
    -- directory's rule, can leave a permission out).
    IF o ? 'scope' AND (v_scope !~ '[ /]approleassignment\.readwrite\.all ' OR v_scope !~ '[ /](application\.read\.all|application\.readwrite\.all|directory\.read\.all) ') THEN
      RETURN public._docs_ms_stop(g.state, 'Microsoft did not allow what giving the access needs (to read your directory''s applications and give one a permission). '
        || 'Sign in with a Global Administrator or a Privileged Role Administrator of your Microsoft 365, and accept what Microsoft asks.');
    END IF;
    v_secs := CASE WHEN COALESCE(o ->> 'expires_in', '') ~ '^[0-9]{1,6}$' THEN (o ->> 'expires_in')::integer ELSE 3599 END;
    UPDATE public._docs_ms_grant SET token = o ->> 'access_token', token_until = now() + make_interval(secs => GREATEST(60, LEAST(v_secs, 7200)) - 30),
           step = 'finding', updated_at = now() WHERE state = g.state;
    v_job := public._net_plan('docs_graph', jsonb_build_object('docs', 'ms_find', 'state', g.state));
    UPDATE public._docs_ms_grant SET job = v_job WHERE state = g.state;
    RETURN jsonb_build_object('ok', true);
  END IF;
  v_err := public._docs_said(o, p_status, p_error, p_transport, 'Microsoft');
  IF v_err ~ 'AADSTS50011' THEN
    v_err := 'Microsoft would not send the sign-in back to the portal: ' || public._docs_ms_words(g.door) || ' does not list the portal''s address. Add it (Settings shows it), then try again. (' || v_err || ')';
  ELSIF v_err ~ 'AADSTS7000215|AADSTS7000222|invalid_client' THEN
    v_err := 'Microsoft refused the secret saved for ' || public._docs_ms_words(g.door) || ' (' || v_err || ').';
  ELSE
    v_err := 'Microsoft did not give the sign-in''s access: ' || v_err;
  END IF;
  -- What the administrator accepted on Microsoft's page stays allowed for the
  -- application until a giving goes through (which takes it back): said.
  RETURN public._docs_ms_stop(g.state, v_err
    || ' What the sign-in asked for stays allowed for ' || public._docs_ms_words(g.door) || ' until a giving goes through, which takes it back, or until it is removed in Microsoft Entra (Enterprise applications, the application, Permissions).');
END $dsmscode$;
REVOKE ALL ON FUNCTION public._docs_ms_code_answer(public._net_jobs, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- Graph's answers to the giving's own calls.
CREATE OR REPLACE FUNCTION public._docs_ms_answer(j public._net_jobs, p_status integer, p_content text, p_error text, p_transport text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsmsans$
DECLARE o jsonb := public._tk_parse(p_content); s jsonb := j.subject; v_step text := s ->> 'docs'; g public._docs_ms_grant;
  rt jsonb; rr jsonb; rg jsonb; rd jsonb; rp jsonb; x jsonb; v_graph text; v_role text; v_target text; v_door text; v_have boolean;
  v_ops jsonb := '[]'::jsonb; v_new text; v_err text; v_job uuid; v_bad text := '';
  v_mine text[] := ARRAY['application.read.all', 'approleassignment.readwrite.all', 'delegatedpermissiongrant.readwrite.all'];
BEGIN
  SELECT * INTO g FROM public._docs_ms_grant WHERE state = s ->> 'state' FOR UPDATE;
  IF g.state IS NULL OR g.step IN ('done', 'failed') THEN RETURN jsonb_build_object('ok', false, 'error', 'no longer under way'); END IF;
  IF v_step = 'ms_find' THEN
    IF p_status = 200 AND jsonb_typeof(o -> 'responses') = 'array' THEN
      SELECT y INTO rt FROM jsonb_array_elements(o -> 'responses') AS y WHERE y ->> 'id' = 'target' LIMIT 1;
      SELECT y INTO rr FROM jsonb_array_elements(o -> 'responses') AS y WHERE y ->> 'id' = 'roles' LIMIT 1;
      SELECT y INTO rg FROM jsonb_array_elements(o -> 'responses') AS y WHERE y ->> 'id' = 'graph' LIMIT 1;
      SELECT y INTO rp FROM jsonb_array_elements(o -> 'responses') AS y WHERE y ->> 'id' = 'grants' LIMIT 1;
      SELECT y INTO rd FROM jsonb_array_elements(o -> 'responses') AS y WHERE y ->> 'id' = 'door' LIMIT 1;
    ELSE
      RETURN public._docs_ms_stop(g.state, 'Microsoft could not be asked about your applications: ' || public._docs_said(o, p_status, p_error, p_transport, 'Microsoft'));
    END IF;
    -- Microsoft Graph's own application in this directory, and the ID of
    -- SharePoint's permission among its own (its well-known ID otherwise).
    IF rg ->> 'status' = '200' AND public._docs_ms_id_ok(rg #>> '{body,id}') THEN
      v_graph := rg #>> '{body,id}';
      SELECT y ->> 'id' INTO v_role FROM jsonb_array_elements(CASE WHEN jsonb_typeof(rg #> '{body,appRoles}') = 'array' THEN rg #> '{body,appRoles}' ELSE '[]'::jsonb END) AS y
       WHERE y ->> 'value' = public._docs_ms_role() AND public._docs_ms_id_ok(y ->> 'id') LIMIT 1;
      v_role := COALESCE(v_role, '9492366f-7969-46a4-8d15-ed1a20078fff');
    END IF;
    IF rt ->> 'status' = '200' AND public._docs_ms_id_ok(rt #>> '{body,id}') THEN v_target := rt #>> '{body,id}'; END IF;
    v_door := CASE WHEN g.door_app = g.target_app THEN v_target WHEN rd ->> 'status' = '200' AND public._docs_ms_id_ok(rd #>> '{body,id}') THEN rd #>> '{body,id}' END;
    -- What the sign-in itself was allowed on Graph, to be taken back once
    -- the access is given: each of its three taken out of whatever grant
    -- holds it (this administrator's own, or the directory's), the grant
    -- removed where nothing else is left in it.
    IF rp ->> 'status' = '200' AND jsonb_typeof(rp #> '{body,value}') = 'array' THEN
      FOR x IN SELECT y FROM jsonb_array_elements(rp #> '{body,value}') AS y
                WHERE (v_graph IS NULL OR y ->> 'resourceId' = v_graph) AND public._docs_ms_id_ok(y ->> 'id') LOOP
        v_new := array_to_string(ARRAY(SELECT w FROM regexp_split_to_table(btrim(COALESCE(x ->> 'scope', '')), '\s+') AS w WHERE w <> '' AND lower(w) <> ALL (v_mine)), ' ');
        IF v_new IS DISTINCT FROM btrim(regexp_replace(COALESCE(x ->> 'scope', ''), '\s+', ' ', 'g')) THEN
          v_ops := v_ops || jsonb_build_array(CASE WHEN v_new = '' THEN jsonb_build_object('id', x ->> 'id', 'delete', true) ELSE jsonb_build_object('id', x ->> 'id', 'scope', v_new) END);
        END IF;
      END LOOP;
    END IF;
    UPDATE public._docs_ms_grant SET graph_sp = v_graph, target_sp = v_target, door_sp = v_door, role_id = v_role, updated_at = now() WHERE state = g.state;
    -- What the sign-in was allowed could not be read, so it cannot be taken
    -- back from here: said, with where to remove it.
    IF NOT (rp ->> 'status' = '200') THEN
      UPDATE public._docs_ms_grant SET tidy_error = 'What the sign-in itself was allowed could not be read, so it was not taken back. Remove it in Microsoft Entra: Enterprise applications, '
        || replace(public._docs_ms_words(g.door), 'your ', 'your firm''s ') || ', Permissions.' WHERE state = g.state;
    END IF;
    IF v_graph IS NULL OR v_target IS NULL THEN
      v_err := CASE
        WHEN rt ->> 'status' = '404' THEN 'Microsoft found no ' || replace(public._docs_ms_words(g.target_via), 'your ', '') || ' (' || g.target_app || ') in the Microsoft 365 that '
          || COALESCE(g.admin, 'the administrator') || ' signed in to. Sign in with an administrator of the Microsoft 365 it was made in.'
        WHEN rt ->> 'status' = '403' OR rg ->> 'status' = '403' THEN 'Microsoft did not let ' || COALESCE(g.admin, 'the administrator') || ' read your directory''s applications ('
          || public._docs_said(COALESCE(rt -> 'body', rg -> 'body'), 403, NULL, 'answered', 'Microsoft') || ').'
        ELSE 'Microsoft could not be asked about your applications: ' || public._docs_said(COALESCE(rt -> 'body', rg -> 'body', o), COALESCE((rt ->> 'status')::integer, p_status), p_error, p_transport, 'Microsoft') END;
      RETURN public._docs_ms_stop(g.state, v_err, v_ops);
    END IF;
    v_have := rr ->> 'status' = '200' AND jsonb_typeof(rr #> '{body,value}') = 'array'
      AND EXISTS (SELECT 1 FROM jsonb_array_elements(rr #> '{body,value}') AS y WHERE y ->> 'resourceId' = v_graph AND lower(y ->> 'appRoleId') = lower(v_role));
    IF v_have THEN
      -- It had the permission already: nothing to give.
      UPDATE public._docs_ms_grant SET given = true, updated_at = now() WHERE state = g.state;
      IF jsonb_array_length(v_ops) > 0 THEN
        UPDATE public._docs_ms_grant SET step = 'tidying' WHERE state = g.state;
        v_job := public._net_plan('docs_graph', jsonb_build_object('docs', 'ms_tidy', 'state', g.state, 'ops', v_ops));
        UPDATE public._docs_ms_grant SET job = v_job WHERE state = g.state;
      ELSE
        PERFORM public._docs_ms_done(g.state);
      END IF;
      RETURN jsonb_build_object('ok', true, 'had', true);
    END IF;
    UPDATE public._docs_ms_grant SET step = 'giving', updated_at = now() WHERE state = g.state;
    v_job := public._net_plan('docs_graph', jsonb_build_object('docs', 'ms_give', 'state', g.state, 'ops', v_ops));
    UPDATE public._docs_ms_grant SET job = v_job WHERE state = g.state;
    RETURN jsonb_build_object('ok', true);
  ELSIF v_step = 'ms_give' THEN
    v_err := public._docs_said(o, p_status, p_error, p_transport, 'Microsoft');
    IF p_status IN (200, 201) OR (p_status IN (400, 409) AND v_err ~* 'already exists') THEN
      UPDATE public._docs_ms_grant SET given = true, updated_at = now() WHERE state = g.state;
    ELSE
      UPDATE public._docs_ms_grant SET given = false, error = left(CASE WHEN p_status = 403
          THEN 'Microsoft would not let ' || COALESCE(g.admin, 'the administrator') || ' give ' || public._docs_ms_words(g.target_via) || ' this permission: only a Global Administrator or a Privileged Role Administrator of your Microsoft 365 can ('
               || v_err || ').'
          ELSE 'Microsoft did not give ' || public._docs_ms_words(g.target_via) || ' the permission: ' || v_err END, 800), updated_at = now() WHERE state = g.state;
    END IF;
    IF jsonb_typeof(s -> 'ops') = 'array' AND jsonb_array_length(s -> 'ops') > 0 THEN
      UPDATE public._docs_ms_grant SET step = 'tidying', updated_at = now() WHERE state = g.state;
      v_job := public._net_plan('docs_graph', jsonb_build_object('docs', 'ms_tidy', 'state', g.state, 'ops', s -> 'ops'));
      UPDATE public._docs_ms_grant SET job = v_job WHERE state = g.state;
    ELSE
      PERFORM public._docs_ms_done(g.state);
    END IF;
    RETURN jsonb_build_object('ok', COALESCE((SELECT given FROM public._docs_ms_grant WHERE state = g.state), false));
  ELSIF v_step = 'ms_tidy' THEN
    IF p_status = 200 AND jsonb_typeof(o -> 'responses') = 'array' THEN
      FOR x IN SELECT y FROM jsonb_array_elements(o -> 'responses') AS y LOOP
        IF COALESCE((x ->> 'status')::integer, 0) NOT IN (200, 204, 404) THEN
          v_bad := public._docs_said(CASE WHEN jsonb_typeof(x -> 'body') = 'object' THEN x -> 'body' ELSE '{}'::jsonb END, (x ->> 'status')::integer, NULL, 'answered', 'Microsoft');
        END IF;
      END LOOP;
    ELSE
      v_bad := public._docs_said(o, p_status, p_error, p_transport, 'Microsoft');
    END IF;
    IF v_bad <> '' THEN
      UPDATE public._docs_ms_grant SET tidy_error = left('What the sign-in itself was allowed could not all be taken back (' || v_bad || '). Remove it in Microsoft Entra: Enterprise applications, '
        || replace(public._docs_ms_words(g.door), 'your ', 'your firm''s ') || ', Permissions.', 600), updated_at = now() WHERE state = g.state;
    END IF;
    PERFORM public._docs_ms_done(g.state);
    RETURN jsonb_build_object('ok', v_bad = '');
  END IF;
  RETURN jsonb_build_object('ok', false, 'error', 'Not a step this database takes.');
END $dsmsans$;
REVOKE ALL ON FUNCTION public._docs_ms_answer(public._net_jobs, integer, text, text, text) FROM PUBLIC, anon, authenticated;

-- ── Google's Drive API switched off ────────────────────────────────────────
-- The project of the firm's Google sign-in application, as its client ID
-- begins (Google's own numbering), NULL where it does not.
CREATE OR REPLACE FUNCTION public._docs_google_project() RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgproj$
  SELECT substring(btrim(COALESCE(s.sso_google_client_id, '')) FROM '^([0-9]{4,30})-[A-Za-z0-9_]+\.apps\.googleusercontent\.com$')
    FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1;
$dsgproj$;
REVOKE ALL ON FUNCTION public._docs_google_project() FROM PUBLIC, anon, authenticated;

-- Where Google says its Drive API is switched off for the project (or not
-- yet used there): the project's own page for the API, with its Enable, as
-- Google's console names it; NULL for any other refusal. The page is made
-- here from the project's number, never taken from the answer as it came.
CREATE OR REPLACE FUNCTION public._docs_drive_api_url(o jsonb) RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dsgapi$
DECLARE v_said text := COALESCE(o::text, ''); v_msg text := COALESCE(o #>> '{error,message}', ''); v_proj text;
BEGIN
  IF NOT (v_said ~ '"SERVICE_DISABLED"' OR v_said ~ '"accessNotConfigured"' OR v_msg ~* 'API has not been used in project|API (is|has been) disabled|it is disabled') THEN RETURN NULL; END IF;
  v_proj := COALESCE(substring(v_said FROM '"consumer"\s*:\s*"projects/([0-9]{4,30})"'), substring(v_msg FROM 'in project ([0-9]{4,30})'),
                     substring(v_said FROM '[?&]project=([0-9]{4,30})'), public._docs_google_project());
  RETURN 'https://console.cloud.google.com/apis/library/drive.googleapis.com' || CASE WHEN v_proj IS NOT NULL THEN '?project=' || v_proj ELSE '' END;
END $dsgapi$;
REVOKE ALL ON FUNCTION public._docs_drive_api_url(jsonb) FROM PUBLIC, anon, authenticated;

-- What stood in the way, kept with where the files go, for Settings.
CREATE OR REPLACE FUNCTION public._docs_target_need(p_key text, p_need text, p_url text) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $dstneed$
  UPDATE public._docs_target SET need = p_need, need_url = left(p_url, 1000), updated_at = now() WHERE id AND target_key IS NOT DISTINCT FROM p_key;
$dstneed$;
REVOKE ALL ON FUNCTION public._docs_target_need(text, text, text) FROM PUBLIC, anon, authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1851: THE PASSWORD MANAGERS A TESTER MAY SEND A CLIENT'S CREDENTIALS TO.
--
-- [stated] Arian: "i want to have password managers as options in
-- integrations. how this would work is, once credentials are viewed, there
-- will be a send to <password manager> option which would send it there
-- securely from their pc (as some will be whitelisted to their ip> or any
-- other secure way, tailorable in the settings. Support all the major ones,
-- 1password, passbolt, etc".
--
-- What an administrator chose in Settings, Integrations, Password managers:
-- which password managers a tester is offered while the one-time view of a
-- client's credentials is open, how each is sent to (handed to 1Password's
-- own browser extension; written to a HashiCorp Vault or OpenBao, or to the
-- manager's own API, from the tester's browser with the tester's own token;
-- or saved as a file the manager imports, encrypted unless the firm allows
-- otherwise), and how an item and its folder are named. It holds no secret.
-- A tester's token stays in that tester's browser, and the credentials go
-- from the browser to the manager and nowhere else: not through this
-- database, and not through Pental.
--
-- Read by the firm's own people who may open a client's credentials (an
-- administrator, a senior, a standard tester, a contractor) through
-- rpc_password_managers(), and by nobody else: not a client's users, since it
-- can name addresses inside the firm (and an API's headers may carry a fixed
-- credential an administrator wrote there), so the signed-in grant withholds
-- the column (_settings_secret_columns), and not the sign-in page. Written by
-- an administrator or a senior with a fresh second factor, as the rest of the
-- row is. The rule is the database's own check of what is kept:
-- each destination is a kind the portal sends to (its name a string), there
-- are at most twelve, one sent to by its address has one (a string), and
-- every address is https (or this
-- computer's own, for a manager run on it) with nobody's name before its
-- host, so a change to the settings cannot point a tester's browser, and the
-- credentials it carries, at a plain http address.
-- ═══════════════════════════════════════════════════════════════════════════
ALTER TABLE public.settings ADD COLUMN IF NOT EXISTS password_managers jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.settings DROP CONSTRAINT IF EXISTS settings_password_managers_ck;
ALTER TABLE public.settings ADD CONSTRAINT settings_password_managers_ck CHECK (
  jsonb_typeof(password_managers) = 'object'
  AND pg_column_size(password_managers) <= 65536
  AND (NOT (password_managers ? 'destinations')
       OR (jsonb_typeof(password_managers -> 'destinations') = 'array'
           AND jsonb_array_length(password_managers -> 'destinations') <= 12))
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*] ? (@.type() != "object")')
  -- 1852: and the ones connected once and sent to from the firm's gateway
  -- (op_sa: 1Password through a service account; bitwarden; passbolt;
  -- keeper), and a tester's own KeePass file written in place (kdbx_local).
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*] ? (!exists(@.kind) || !(@.kind == "onepassword" || @.kind == "vault" || @.kind == "api" || @.kind == "kdbx" || @.kind == "file" || @.kind == "op_sa" || @.kind == "bitwarden" || @.kind == "passbolt" || @.kind == "keeper" || @.kind == "kdbx_local"))')
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*] ? ((@.kind == "vault" || @.kind == "api" || @.kind == "passbolt") && !exists(@.url))')
  -- Bitwarden's server: its cloud in the US or the EU, or an address held to
  -- the rule every address is (below).
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*] ? (exists(@.server) && @.server.type() != "string")')
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*].server ? (!(@ == "us" || @ == "eu" || @ like_regex "^(https://[^/?#@\\\\[:space:]]+|http://(localhost|127\\.0\\.0\\.1|\\[::1\\]))(:[0-9]{1,5})?([/?#][^[:space:]]*)?$"))')
  -- A kind and an address are each a string: a path in lax mode reads a list
  -- for its members, so ["vault"] or [] would pass the rules above and below
  -- (and the portal would take [] for an address of its own).
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*] ? (exists(@.kind) && @.kind.type() != "string")')
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*] ? (exists(@.url) && @.url.type() != "string")')
  AND NOT jsonb_path_exists(password_managers, '$.destinations[*].url ? (@.type() != "string" || !(@ like_regex "^(https://[^/?#@\\\\[:space:]]+|http://(localhost|127\\.0\\.0\\.1|\\[::1\\]))(:[0-9]{1,5})?([/?#][^[:space:]]*)?$"))')
);
-- With a fresh second factor, as a client's credentials are read (1841): an
-- API's headers may hold a fixed credential.
CREATE OR REPLACE FUNCTION public.rpc_password_managers() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmget$
BEGIN
  IF public.current_user_role() NOT IN ('admin', 'senior', 'standard', 'contractor') THEN RETURN '{}'::jsonb; END IF;
  PERFORM public._need_fresh_mfa();
  RETURN COALESCE((SELECT s.password_managers FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1), '{}'::jsonb);
END $pmget$;
REVOKE ALL ON FUNCTION public.rpc_password_managers() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_password_managers() TO authenticated;
COMMENT ON COLUMN public.settings.password_managers IS
  'Settings, Integrations, Password managers (1851): the password managers a tester may send a client''s revealed credentials to, how each is sent to, and how items and folders are named. No secret: a tester''s token stays in their own browser, and the credentials go from it straight to the manager.';

-- ═══════════════════════════════════════════════════════════════════════════
-- 1852: A PASSWORD MANAGER CONNECTED ONCE, AND SENT TO IN ONE CLICK.
--
-- [stated] Arian: "i was hoping for a more seamless send to password manager
-- solution", for "all of the main ones", and "something more seamless" than
-- a tester's own browser.
--
-- 1Password (through a service account), Bitwarden, Passbolt and Keeper
-- encrypt on the client and take nothing from a browser of another site, so
-- an administrator connects each once, in Settings, Integrations, Password
-- managers, giving Pental an account of its own there (a service account's
-- token; a member's API key and master password; a user's recovery kit and
-- passphrase; a Secrets Manager application's one-time access token). That
-- secret is kept here, encrypted with the firm's own key (_settings_encrypt),
-- in a table no session can read (_pm_secrets), and is handed only to the
-- firm's own gateway (1.14.0 on) as a send starts (_pm_claim), which writes
-- through that manager's own software (gateway/lib/pm). A tester's Send to
-- <manager> hands what they revealed to this database (rpc_pm_send), which
-- reads the files from the client's credentials itself, keeps it all
-- encrypted until the gateway has sent it, then deletes it, and says how each
-- item went (rpc_pm_job). Nothing of it passes through Pental. Testers type
-- nothing: no token, no file, no passphrase.
--
-- A destination's address and what was chosen (a vault, a collection, a
-- group and folder, a shared folder) are in Settings with the rest
-- (settings.password_managers, 1851's rule above); nothing secret is there.
-- ═══════════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public._pm_secrets (
  dest_id text PRIMARY KEY,
  kind text NOT NULL,
  secret bytea NOT NULL,
  account jsonb NOT NULL DEFAULT '{}'::jsonb,
  saved boolean NOT NULL DEFAULT false,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT _pm_secrets_dest CHECK (dest_id ~ '^[A-Za-z0-9_-]{1,40}$'),
  CONSTRAINT _pm_secrets_kind CHECK (kind IN ('op_sa', 'bitwarden', 'passbolt', 'keeper'))
);
ALTER TABLE public._pm_secrets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._pm_secrets FROM PUBLIC, anon, authenticated;
COMMENT ON TABLE public._pm_secrets IS
  'Settings, Integrations, Password managers (1852): the account each connected password manager gives Pental, encrypted with the firm''s own key, read only by the firm''s gateway as it sends (_pm_claim). No session can read it.';

-- What waits to be sent, and how it went. Unlogged: nothing in it is kept
-- past a day, and what a tester sent is deleted once the gateway has it out.
CREATE UNLOGGED TABLE IF NOT EXISTS public._pm_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind text NOT NULL,
  dest_id text NOT NULL,
  dest_kind text NOT NULL,
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  payload bytea,
  n integer NOT NULL DEFAULT 0,
  state text NOT NULL DEFAULT 'queued',
  results jsonb NOT NULL DEFAULT '[]'::jsonb,
  outcome jsonb,
  created_by uuid,
  assessment_id uuid,
  claimed_by text,
  claimed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  CONSTRAINT _pm_jobs_kind CHECK (kind IN ('connect', 'send')),
  CONSTRAINT _pm_jobs_state CHECK (state IN ('queued', 'sending', 'done', 'failed', 'expired'))
);
ALTER TABLE public._pm_jobs SET UNLOGGED;
CREATE INDEX IF NOT EXISTS _pm_jobs_live_idx ON public._pm_jobs (state, created_at) WHERE state IN ('queued', 'sending');
ALTER TABLE public._pm_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._pm_jobs FROM PUBLIC, anon, authenticated;

-- The kinds a gateway sends to.
CREATE OR REPLACE FUNCTION public._pm_gateway_kinds() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $pmkinds$
  SELECT ARRAY['op_sa', 'bitwarden', 'passbolt', 'keeper']::text[];
$pmkinds$;
REVOKE ALL ON FUNCTION public._pm_gateway_kinds() FROM PUBLIC, anon, authenticated;

-- One destination as Settings keeps it, or NULL.
CREATE OR REPLACE FUNCTION public._pm_dest(p_id text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmdest$
  SELECT d FROM jsonb_array_elements(COALESCE((
      SELECT CASE WHEN jsonb_typeof(s.password_managers -> 'destinations') = 'array' THEN s.password_managers -> 'destinations' END
        FROM public.settings s ORDER BY s.created_at ASC NULLS LAST, s.id LIMIT 1), '[]'::jsonb)) d
   WHERE jsonb_typeof(d) = 'object' AND d ->> 'id' = p_id
   LIMIT 1;
$pmdest$;
REVOKE ALL ON FUNCTION public._pm_dest(text) FROM PUBLIC, anon, authenticated;

-- Whether a gateway's worker for these (1.14.0 on) said in the last 45
-- seconds that it is there.
CREATE OR REPLACE FUNCTION public._pm_worker_alive() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmalive$
DECLARE v integer;
BEGIN
  IF to_regclass('pental.meta') IS NULL THEN RETURN false; END IF;
  EXECUTE $q$SELECT 1 FROM pental.meta WHERE key LIKE 'pm\_worker%' AND updated_at > now() - interval '45 seconds' LIMIT 1$q$ INTO v;
  RETURN v IS NOT NULL;
END $pmalive$;
REVOKE ALL ON FUNCTION public._pm_worker_alive() FROM PUBLIC, anon, authenticated;

-- What a manager or the gateway said, kept as plain short text.
CREATE OR REPLACE FUNCTION public._pm_text(p jsonb, p_max integer DEFAULT 300) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $pmtext$
  SELECT CASE WHEN jsonb_typeof(p) = 'string' THEN left(regexp_replace(p #>> '{}', '[[:cntrl:]]+', ' ', 'g'), p_max)
              WHEN jsonb_typeof(p) IN ('number', 'boolean') THEN left(p #>> '{}', p_max) END;
$pmtext$;
REVOKE ALL ON FUNCTION public._pm_text(jsonb, integer) FROM PUBLIC, anon, authenticated;

-- How each item went, as a person may read it: its key, whether it went,
-- the words for it, and which of its files went with it. Nothing else.
CREATE OR REPLACE FUNCTION public._pm_clean_results(p jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $pmclean$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'key', public._pm_text(r -> 'key', 80),
      'ok', COALESCE(r -> 'ok' = 'true'::jsonb, false),
      'msg', public._pm_text(r -> 'msg', 400),
      'files', COALESCE((SELECT jsonb_agg(jsonb_build_object('ci', (f ->> 'ci')::integer, 'fi', (f ->> 'fi')::integer))
                           FROM jsonb_array_elements(CASE WHEN jsonb_typeof(r -> 'files') = 'array' THEN r -> 'files' ELSE '[]'::jsonb END) f
                          WHERE jsonb_typeof(f) = 'object' AND (f ->> 'ci') ~ '^[0-9]{1,4}$' AND (f ->> 'fi') ~ '^[0-9]{1,4}$'), '[]'::jsonb))), '[]'::jsonb)
    FROM (SELECT r FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p) = 'array' THEN p ELSE '[]'::jsonb END) r WHERE jsonb_typeof(r) = 'object' LIMIT 200) x;
$pmclean$;
REVOKE ALL ON FUNCTION public._pm_clean_results(jsonb) FROM PUBLIC, anon, authenticated;

-- What a connection found (who Pental is there, and the places it can put
-- things), kept to what Settings shows: no field that could hold a secret,
-- and only so much of it.
CREATE OR REPLACE FUNCTION public._pm_clean_outcome(p jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = public, pg_catalog, pg_temp AS $pmout$
DECLARE v jsonb;
BEGIN
  IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('ok', false, 'error', 'The gateway gave no answer.'); END IF;
  v := p - ARRAY['config', 'secret', 'token', 'private_key', 'passphrase', 'password', 'client_secret', 'results'];
  IF pg_column_size(v) > 524288 THEN RETURN jsonb_build_object('ok', COALESCE(p -> 'ok' = 'true'::jsonb, false), 'error', 'What the manager listed was too long to keep.'); END IF;
  RETURN v || jsonb_build_object('ok', COALESCE(p -> 'ok' = 'true'::jsonb, false))
           || CASE WHEN p ? 'error' THEN jsonb_build_object('error', public._pm_text(p -> 'error', 600)) ELSE '{}'::jsonb END;
END $pmout$;
REVOKE ALL ON FUNCTION public._pm_clean_outcome(jsonb) FROM PUBLIC, anon, authenticated;

-- What is connected, and whether the gateway that sends is there: for the
-- firm's people who may open a client's credentials (Settings, and Send to).
-- The account each found is for an administrator alone.
CREATE OR REPLACE FUNCTION public.rpc_pm_status() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmstatus$
DECLARE v_role text := public.current_user_role(); v_gw text; v_conn jsonb;
BEGIN
  IF v_role NOT IN ('admin', 'senior', 'standard', 'contractor') THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  PERFORM public._need_fresh_mfa();
  IF to_regclass('pental.meta') IS NOT NULL THEN
    EXECUTE $q$SELECT value FROM pental.meta WHERE key = 'gateway_version'$q$ INTO v_gw;
  END IF;
  SELECT COALESCE(jsonb_object_agg(s.dest_id, jsonb_build_object('kind', s.kind, 'at', s.updated_at)
           || CASE WHEN v_role = 'admin' THEN jsonb_build_object('account', s.account) ELSE '{}'::jsonb END), '{}'::jsonb)
    INTO v_conn FROM public._pm_secrets s;
  RETURN jsonb_build_object('gateway', CASE WHEN v_gw IS NULL THEN NULL ELSE left(v_gw, 40) END,
    'worker', public._pm_worker_alive(), 'connected', v_conn);
END $pmstatus$;
REVOKE ALL ON FUNCTION public.rpc_pm_status() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_pm_status() TO authenticated;

-- Connect a password manager, or look at it again: an administrator, with
-- their second factor fresh. Its secret (given, or the one kept) is kept
-- encrypted, and the gateway is asked to sign in with it and say who Pental
-- is there and where it can put things (rpc_pm_job reads the answer).
CREATE OR REPLACE FUNCTION public.rpc_pm_connect(p_dest text, p_kind text, p_config jsonb DEFAULT '{}'::jsonb, p_secret jsonb DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $pmconnect$
DECLARE
  v_url_re constant text := '^(https://[^/?#@\\[:space:]]+|http://(localhost|127\.0\.0\.1|\[::1\]))(:[0-9]{1,5})?([/?#][^[:space:]]*)?$';
  v_cfg jsonb := '{}'::jsonb; v_sec jsonb; v_old public._pm_secrets; v_job uuid; v_dest jsonb; v_s text;
BEGIN
  IF public.current_user_role() <> 'admin' THEN RETURN jsonb_build_object('error', 'Only an administrator connects a password manager.'); END IF;
  PERFORM public._need_fresh_mfa();
  IF p_dest IS NULL OR p_dest !~ '^[A-Za-z0-9_-]{1,40}$' THEN RETURN jsonb_build_object('error', 'That is not a password manager of Settings.'); END IF;
  IF p_kind IS NULL OR NOT (p_kind = ANY (public._pm_gateway_kinds())) THEN RETURN jsonb_build_object('error', 'That password manager is not connected this way.'); END IF;
  -- Where it is: the firm's own Passbolt, held to the rule every address is;
  -- Bitwarden's cloud in the US or the EU, or the firm's own server.
  IF p_kind = 'passbolt' THEN
    v_s := COALESCE(p_config ->> 'url', '');
    IF v_s !~ v_url_re THEN RETURN jsonb_build_object('error', 'Passbolt''s address has to start with https://, with no name and @ before the host.'); END IF;
    v_cfg := jsonb_build_object('url', v_s);
  ELSIF p_kind = 'bitwarden' THEN
    v_s := COALESCE(p_config ->> 'server', 'us');
    IF NOT (v_s IN ('us', 'eu') OR v_s ~ v_url_re) THEN RETURN jsonb_build_object('error', 'Bitwarden''s server is bitwarden.com, bitwarden.eu, or your own server''s https:// address.'); END IF;
    v_cfg := jsonb_build_object('server', v_s);
  END IF;
  SELECT * INTO v_old FROM public._pm_secrets WHERE dest_id = p_dest;
  IF p_secret IS NULL THEN
    IF v_old.dest_id IS NULL OR v_old.kind <> p_kind THEN RETURN jsonb_build_object('error', 'Give its details first.'); END IF;
  ELSE
    IF jsonb_typeof(p_secret) <> 'object' THEN RETURN jsonb_build_object('error', 'Those details do not read.'); END IF;
    IF p_kind = 'op_sa' THEN
      -- (A repetition count in a pattern goes to 255 at most here: the length
      -- is held on its own.)
      IF COALESCE(p_secret ->> 'token', '') !~ '^ops_[A-Za-z0-9_=+/.-]+$' OR length(p_secret ->> 'token') NOT BETWEEN 24 AND 8004 THEN RETURN jsonb_build_object('error', 'A 1Password service account token begins ops_.'); END IF;
      v_sec := jsonb_build_object('token', p_secret ->> 'token');
    ELSIF p_kind = 'bitwarden' THEN
      IF COALESCE(p_secret ->> 'client_id', '') !~* '^user\.[0-9a-f-]{36}$' THEN RETURN jsonb_build_object('error', 'The client_id of a member''s API key begins user. and an ID (an organisation''s API key cannot write into vaults).'); END IF;
      IF length(COALESCE(p_secret ->> 'client_secret', '')) NOT BETWEEN 10 AND 500 THEN RETURN jsonb_build_object('error', 'Give the API key''s client_secret.'); END IF;
      IF length(COALESCE(p_secret ->> 'password', '')) NOT BETWEEN 1 AND 1000 THEN RETURN jsonb_build_object('error', 'Give the member''s master password.'); END IF;
      v_sec := jsonb_build_object('client_id', p_secret ->> 'client_id', 'client_secret', p_secret ->> 'client_secret', 'password', p_secret ->> 'password');
    ELSIF p_kind = 'passbolt' THEN
      IF position('PRIVATE KEY BLOCK' in COALESCE(p_secret ->> 'private_key', '')) = 0 OR length(p_secret ->> 'private_key') > 40000 THEN RETURN jsonb_build_object('error', 'Give the recovery kit: the OpenPGP private key Passbolt gives its user.'); END IF;
      IF length(COALESCE(p_secret ->> 'passphrase', '')) > 1000 THEN RETURN jsonb_build_object('error', 'That passphrase is too long.'); END IF;
      v_sec := jsonb_build_object('private_key', p_secret ->> 'private_key', 'passphrase', COALESCE(p_secret ->> 'passphrase', ''));
    ELSE
      IF COALESCE(p_secret ->> 'token', '') !~ '^[A-Za-z0-9]{2,8}:[A-Za-z0-9_-]{20,200}$' THEN RETURN jsonb_build_object('error', 'A Keeper one-time access token begins with its region, such as US:.'); END IF;
      v_sec := jsonb_build_object('token', p_secret ->> 'token');
    END IF;
    v_dest := public._pm_dest(p_dest);
    INSERT INTO public._pm_secrets (dest_id, kind, secret, account, saved, created_by)
      VALUES (p_dest, p_kind, public._settings_encrypt(v_sec::text), '{}'::jsonb, v_dest IS NOT NULL AND v_dest ->> 'kind' = p_kind, public.current_profile_id())
      ON CONFLICT (dest_id) DO UPDATE SET kind = EXCLUDED.kind, secret = EXCLUDED.secret, account = '{}'::jsonb, saved = EXCLUDED.saved,
        created_by = EXCLUDED.created_by, updated_at = now();
  END IF;
  -- An earlier look still waiting is let go.
  UPDATE public._pm_jobs SET state = 'expired', payload = NULL, finished_at = now(), outcome = jsonb_build_object('ok', false, 'error', 'Asked again.')
   WHERE dest_id = p_dest AND kind = 'connect' AND state = 'queued';
  INSERT INTO public._pm_jobs (kind, dest_id, dest_kind, config, created_by)
    VALUES ('connect', p_dest, p_kind, v_cfg, public.current_profile_id()) RETURNING id INTO v_job;
  PERFORM pg_notify('pental_pm', v_job::text);
  RETURN jsonb_build_object('job', v_job, 'worker', public._pm_worker_alive());
END $pmconnect$;
REVOKE ALL ON FUNCTION public.rpc_pm_connect(text, text, jsonb, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_pm_connect(text, text, jsonb, jsonb) TO authenticated;

-- Disconnect: its secret deleted, and nothing waiting is sent.
CREATE OR REPLACE FUNCTION public.rpc_pm_forget(p_dest text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmforget$
BEGIN
  IF public.current_user_role() <> 'admin' THEN RETURN jsonb_build_object('error', 'Only an administrator disconnects a password manager.'); END IF;
  PERFORM public._need_fresh_mfa();
  DELETE FROM public._pm_secrets WHERE dest_id = p_dest;
  UPDATE public._pm_jobs SET state = 'expired', payload = NULL, finished_at = now(), outcome = jsonb_build_object('ok', false, 'error', 'It was disconnected before it was sent.')
   WHERE dest_id = p_dest AND state = 'queued';
  RETURN jsonb_build_object('success', true);
END $pmforget$;
REVOKE ALL ON FUNCTION public.rpc_pm_forget(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_pm_forget(text) TO authenticated;

-- Send what a tester revealed to a connected manager: whoever may open the
-- client's credentials (a contractor, only on the engagement they lead), with
-- their second factor fresh. Each item is plain text the portal laid out
-- (its name, username, password, address, one-time code, notes and other
-- values), kept to a size; its files are named by where they are in the
-- client's credentials and read here, from the credentials themselves.
-- Encrypted until the gateway has sent it, then deleted.
CREATE OR REPLACE FUNCTION public.rpc_pm_send(p_dest text, p_assessment uuid, p_items jsonb, p_ctx jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $pmsend$
DECLARE
  v_role text := public.current_user_role(); v_pid uuid := public.current_profile_id();
  v_ass record; v_dest jsonb; v_kind text; v_list jsonb; v_items jsonb := '[]'::jsonb; it jsonb; f jsonb; v_f jsonb;
  v_files jsonb; v_size bigint := 0; v_job uuid; v_key text; v_dec text; v_recent integer; v_ctx jsonb;
BEGIN
  IF v_role NOT IN ('admin', 'senior', 'standard', 'contractor') THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  PERFORM public._need_fresh_mfa();
  SELECT * INTO v_ass FROM public.assessments WHERE id = p_assessment;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Assessment not found'); END IF;
  IF v_role = 'contractor' AND NOT public.can_access_assessment(p_assessment) THEN RETURN jsonb_build_object('error', 'Not the assigned tester'); END IF;   -- 1943: or their team's
  v_dest := public._pm_dest(p_dest);
  IF v_dest IS NULL THEN RETURN jsonb_build_object('error', 'That password manager is no longer set up in Settings.'); END IF;
  v_kind := v_dest ->> 'kind';
  IF NOT (v_kind = ANY (public._pm_gateway_kinds())) THEN RETURN jsonb_build_object('error', 'That password manager is not sent to this way.'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public._pm_secrets WHERE dest_id = p_dest AND kind = v_kind) THEN
    RETURN jsonb_build_object('error', 'It is not connected yet. An administrator connects it in Settings, Integrations, Password managers.');
  END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 100 THEN
    RETURN jsonb_build_object('error', 'Send between one and a hundred items at a time.');
  END IF;
  SELECT count(*) INTO v_recent FROM public._pm_jobs WHERE created_by = v_pid AND kind = 'send' AND created_at > now() - interval '10 minutes';
  IF v_recent >= 30 THEN RETURN jsonb_build_object('error', 'That is a lot of sends in ten minutes. Wait a few minutes, then send again.'); END IF;
  FOR it IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    IF jsonb_typeof(it) <> 'object' THEN RETURN jsonb_build_object('error', 'An item does not read.'); END IF;
    v_files := '[]'::jsonb;
    IF jsonb_typeof(it -> 'files') = 'array' AND jsonb_array_length(it -> 'files') > 0 THEN
      IF v_list IS NULL THEN
        IF v_ass.credentials_data IS NULL OR (v_ass.credentials_data::jsonb) ->> 'enc' IS NULL THEN
          RETURN jsonb_build_object('error', 'The client''s credentials are no longer here, so their files cannot be sent.');
        END IF;
        v_key := public._get_cred_key();
        BEGIN v_dec := extensions.pgp_sym_decrypt(decode((v_ass.credentials_data::jsonb) ->> 'enc', 'base64'), v_key);
        EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error', 'Could not decrypt'); END;
        v_list := v_dec::jsonb;
        IF jsonb_typeof(v_list) <> 'array' THEN v_list := jsonb_build_array(v_list); END IF;
      END IF;
      FOR f IN SELECT * FROM jsonb_array_elements(it -> 'files') LIMIT 40 LOOP
        IF jsonb_typeof(f) = 'object' AND (f ->> 'ci') ~ '^[0-9]{1,4}$' AND (f ->> 'fi') ~ '^[0-9]{1,4}$' THEN
          v_f := v_list -> ((f ->> 'ci')::integer) -> 'files' -> ((f ->> 'fi')::integer);
          IF jsonb_typeof(v_f) = 'object' AND jsonb_typeof(v_f -> 'b64') = 'string' THEN
            v_size := v_size + length(v_f ->> 'b64');
            v_files := v_files || jsonb_build_array(jsonb_build_object('ci', (f ->> 'ci')::integer, 'fi', (f ->> 'fi')::integer,
              'name', left(COALESCE(v_f ->> 'name', 'file'), 255), 'type', left(COALESCE(v_f ->> 'type', ''), 120), 'b64', v_f ->> 'b64'));
          END IF;
        END IF;
      END LOOP;
    END IF;
    v_size := v_size + length(it::text);
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key', left(COALESCE(it ->> 'key', ''), 80), 'title', left(COALESCE(it ->> 'title', ''), 300),
      'username', left(COALESCE(it ->> 'username', ''), 2000), 'password', left(COALESCE(it ->> 'password', ''), 20000),
      'url', left(COALESCE(it ->> 'url', ''), 4000), 'otp', left(COALESCE(it ->> 'otp', ''), 2000),
      'notes', left(COALESCE(it ->> 'notes', ''), 200000), 'type', left(COALESCE(it ->> 'type', ''), 80),
      'fields', COALESCE((SELECT jsonb_agg(jsonb_build_object('label', left(COALESCE(x ->> 'label', ''), 120), 'value', left(COALESCE(x ->> 'value', ''), 200000), 'secret', COALESCE(x -> 'secret' = 'true'::jsonb, false)))
                            FROM (SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(it -> 'fields') = 'array' THEN it -> 'fields' ELSE '[]'::jsonb END) x
                                   WHERE jsonb_typeof(x) = 'object' LIMIT 40) q), '[]'::jsonb),
      'files', v_files));
  END LOOP;
  IF v_size > 30000000 THEN RETURN jsonb_build_object('error', 'Those are too large to send at once (their files come to more than 20 MB). Send fewer at a time.'); END IF;
  v_ctx := jsonb_build_object('client', left(COALESCE(p_ctx ->> 'client', ''), 200), 'assessment', left(COALESCE(p_ctx ->> 'assessment', ''), 200),
    'folder', COALESCE((SELECT jsonb_agg(left(x #>> '{}', 200)) FROM (SELECT x FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_ctx -> 'folder') = 'array' THEN p_ctx -> 'folder' ELSE '[]'::jsonb END) x
                         WHERE jsonb_typeof(x) = 'string' AND btrim(x #>> '{}') <> '' LIMIT 8) q), '[]'::jsonb));
  INSERT INTO public._pm_jobs (kind, dest_id, dest_kind, payload, n, created_by, assessment_id)
    VALUES ('send', p_dest, v_kind, public._settings_encrypt(jsonb_build_object('items', v_items, 'ctx', v_ctx)::text), jsonb_array_length(v_items), v_pid, p_assessment)
    RETURNING id INTO v_job;
  PERFORM pg_notify('pental_pm', v_job::text);
  RETURN jsonb_build_object('job', v_job, 'worker', public._pm_worker_alive());
END $pmsend$;
REVOKE ALL ON FUNCTION public.rpc_pm_send(text, uuid, jsonb, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_pm_send(text, uuid, jsonb, jsonb) TO authenticated;

-- How a send or a connection went, for whoever asked for it (and any
-- administrator). What a connection found is for an administrator alone.
CREATE OR REPLACE FUNCTION public.rpc_pm_job(p_job uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmjob$
DECLARE v public._pm_jobs; v_role text := public.current_user_role();
BEGIN
  IF v_role NOT IN ('admin', 'senior', 'standard', 'contractor') THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  SELECT * INTO v FROM public._pm_jobs WHERE id = p_job;
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'gone'); END IF;
  IF v.created_by IS DISTINCT FROM public.current_profile_id() AND v_role <> 'admin' THEN RETURN jsonb_build_object('error', 'Access denied'); END IF;
  -- Waited longer than a gateway takes to pick one up: let go, never sent late.
  IF v.state = 'queued' AND v.created_at < now() - interval '10 minutes' THEN
    UPDATE public._pm_jobs SET state = 'expired', payload = NULL, finished_at = now(),
      outcome = jsonb_build_object('ok', false, 'error', 'No gateway picked it up within ten minutes, so it was not sent.')
     WHERE id = v.id RETURNING * INTO v;
  END IF;
  RETURN jsonb_build_object('state', v.state, 'kind', v.kind, 'dest', v.dest_id, 'n', v.n, 'results', v.results,
    'outcome', CASE WHEN v.kind = 'connect' AND v_role <> 'admin' THEN NULL ELSE v.outcome END,
    'worker', public._pm_worker_alive(), 'created_at', v.created_at, 'finished_at', v.finished_at);
END $pmjob$;
REVOKE ALL ON FUNCTION public.rpc_pm_job(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.rpc_pm_job(uuid) TO authenticated;

-- The gateway's (1.14.0 on): the next to send, each with its secret and what
-- is sent decrypted as it is handed over, one at a time for a destination
-- (two sends to one Passbolt making one folder twice would make two).
DO $pmclaim_kind$ BEGIN
  IF to_regprocedure('public._pm_claim(integer,text)') IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM pg_proc WHERE oid = to_regprocedure('public._pm_claim(integer,text)') AND 'r_payload' = ANY (COALESCE(proargnames, ARRAY[]::text[]))) THEN
    DROP FUNCTION public._pm_claim(integer, text);
  END IF;
END $pmclaim_kind$;
CREATE OR REPLACE FUNCTION public._pm_claim(p_limit integer DEFAULT 2, p_worker text DEFAULT NULL)
RETURNS TABLE (r_id uuid, r_job text, r_kind text, r_dest_id text, r_config jsonb, r_secret text, r_payload text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $pmclaim$
DECLARE v public._pm_jobs; v_sec public._pm_secrets; v_dest jsonb; v_taken text[] := ARRAY[]::text[];
BEGIN
  FOR v IN SELECT * FROM public._pm_jobs q WHERE q.state = 'queued'
              AND NOT EXISTS (SELECT 1 FROM public._pm_jobs o WHERE o.dest_id = q.dest_id AND o.state = 'sending')
            ORDER BY q.created_at LIMIT 20 FOR UPDATE SKIP LOCKED LOOP
    EXIT WHEN cardinality(v_taken) >= GREATEST(1, LEAST(COALESCE(p_limit, 2), 4));
    CONTINUE WHEN v.dest_id = ANY (v_taken);
    IF v.created_at < now() - interval '10 minutes' THEN
      UPDATE public._pm_jobs SET state = 'expired', payload = NULL, finished_at = now(),
        outcome = jsonb_build_object('ok', false, 'error', 'No gateway picked it up within ten minutes, so it was not sent.') WHERE id = v.id;
      CONTINUE;
    END IF;
    SELECT * INTO v_sec FROM public._pm_secrets WHERE dest_id = v.dest_id;
    IF v_sec.dest_id IS NULL OR v_sec.kind <> v.dest_kind THEN
      UPDATE public._pm_jobs SET state = 'failed', payload = NULL, finished_at = now(),
        outcome = jsonb_build_object('ok', false, 'error', 'It is not connected any more. An administrator connects it again in Settings.') WHERE id = v.id;
      CONTINUE;
    END IF;
    IF v.kind = 'send' THEN
      v_dest := public._pm_dest(v.dest_id);
      IF v_dest IS NULL OR v_dest ->> 'kind' IS DISTINCT FROM v.dest_kind THEN
        UPDATE public._pm_jobs SET state = 'failed', payload = NULL, finished_at = now(),
          outcome = jsonb_build_object('ok', false, 'error', 'That password manager is no longer set up in Settings.') WHERE id = v.id;
        CONTINUE;
      END IF;
    ELSE
      v_dest := v.config;
    END IF;
    UPDATE public._pm_jobs SET state = 'sending', claimed_by = p_worker, claimed_at = now() WHERE id = v.id;
    v_taken := v_taken || v.dest_id;
    r_id := v.id; r_job := v.kind; r_kind := v.dest_kind; r_dest_id := v.dest_id; r_config := v_dest;
    r_secret := public._settings_decrypt(v_sec.secret);
    r_payload := CASE WHEN v.payload IS NULL THEN NULL ELSE public._settings_decrypt(v.payload) END;
    RETURN NEXT;
  END LOOP;
END $pmclaim$;
REVOKE ALL ON FUNCTION public._pm_claim(integer, text) FROM PUBLIC, anon, authenticated;

-- How each item went, as it goes, so a tester sees them land.
CREATE OR REPLACE FUNCTION public._pm_progress(p_id uuid, p_item jsonb, p_worker text DEFAULT NULL) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmprogress$
  UPDATE public._pm_jobs SET results = results || public._pm_clean_results(jsonb_build_array(p_item))
   WHERE id = p_id AND state = 'sending' AND (p_worker IS NULL OR claimed_by IS NOT DISTINCT FROM p_worker) AND jsonb_array_length(results) < 200;
$pmprogress$;
REVOKE ALL ON FUNCTION public._pm_progress(uuid, jsonb, text) FROM PUBLIC, anon, authenticated;

-- Done: how it went kept, and what was sent deleted. A connection keeps who
-- Pental is there, for Settings to show.
CREATE OR REPLACE FUNCTION public._pm_complete(p_id uuid, p_outcome jsonb, p_worker text DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmdone$
DECLARE v public._pm_jobs; v_out jsonb := public._pm_clean_outcome(p_outcome);
BEGIN
  SELECT * INTO v FROM public._pm_jobs WHERE id = p_id AND state = 'sending' AND (p_worker IS NULL OR claimed_by IS NOT DISTINCT FROM p_worker) FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  UPDATE public._pm_jobs SET state = CASE WHEN v_out -> 'ok' = 'true'::jsonb THEN 'done' ELSE 'failed' END,
      results = CASE WHEN jsonb_typeof(p_outcome -> 'results') = 'array' THEN public._pm_clean_results(p_outcome -> 'results') ELSE results END,
      outcome = v_out, payload = NULL, finished_at = now()
   WHERE id = p_id;
  IF v.kind = 'connect' AND v_out -> 'ok' = 'true'::jsonb AND jsonb_typeof(v_out -> 'account') = 'object' THEN
    UPDATE public._pm_secrets SET account = (v_out -> 'account') || jsonb_strip_nulls(jsonb_build_object('server_fp', public._pm_text(v_out -> 'server_fp', 60))), updated_at = now()
     WHERE dest_id = v.dest_id AND kind = v.dest_kind;
  END IF;
END $pmdone$;
REVOKE ALL ON FUNCTION public._pm_complete(uuid, jsonb, text) FROM PUBLIC, anon, authenticated;

-- Keeper: its one-time access token, once bound, is replaced by the
-- application's configuration (its own key and Keeper's) that its SDK
-- writes; only for a connection this gateway is making.
CREATE OR REPLACE FUNCTION public._pm_secret_bind(p_id uuid, p_secret text, p_worker text DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions, pg_catalog, pg_temp AS $pmbind$
DECLARE v jsonb;
BEGIN
  BEGIN v := p_secret::jsonb; EXCEPTION WHEN OTHERS THEN RETURN false; END;
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR jsonb_typeof(v -> 'config') IS DISTINCT FROM 'object' OR length(p_secret) > 40000 THEN RETURN false; END IF;
  UPDATE public._pm_secrets s SET secret = public._settings_encrypt(jsonb_build_object('config', v -> 'config')::text), updated_at = now()
    FROM public._pm_jobs j
   WHERE j.id = p_id AND j.kind = 'connect' AND j.state = 'sending' AND j.dest_kind = 'keeper'
     AND (p_worker IS NULL OR j.claimed_by IS NOT DISTINCT FROM p_worker)
     AND s.dest_id = j.dest_id AND s.kind = 'keeper';
  RETURN FOUND;
END $pmbind$;
REVOKE ALL ON FUNCTION public._pm_secret_bind(uuid, text, text) FROM PUBLIC, anon, authenticated;

-- Kept tidy, every half minute from the gateway: what no gateway picked up in
-- ten minutes let go; what a gateway that stopped was sending, said failed;
-- what is finished, kept a day; a connection never saved in Settings, a day.
CREATE OR REPLACE FUNCTION public._pm_tick() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmtick$
DECLARE v_live text[];
BEGIN
  UPDATE public._pm_jobs SET state = 'expired', payload = NULL, finished_at = now(),
    outcome = jsonb_build_object('ok', false, 'error', 'No gateway picked it up within ten minutes, so it was not sent.')
   WHERE state = 'queued' AND created_at < now() - interval '10 minutes';
  IF to_regclass('pental.meta') IS NOT NULL THEN
    EXECUTE $q$SELECT array_agg(key) FROM pental.meta WHERE key LIKE 'pm\_worker%' AND updated_at > now() - interval '90 seconds'$q$ INTO v_live;
  END IF;
  UPDATE public._pm_jobs SET state = 'failed', payload = NULL, finished_at = now(),
    outcome = jsonb_build_object('ok', false, 'error', 'The gateway stopped while it was sending. Look in the password manager for what arrived before sending again.')
   WHERE state = 'sending' AND (claimed_at < now() - interval '20 minutes'
     OR (claimed_at < now() - interval '2 minutes' AND NOT (claimed_by = ANY (COALESCE(v_live, ARRAY[]::text[])))));
  DELETE FROM public._pm_jobs WHERE finished_at < now() - interval '1 day' OR created_at < now() - interval '2 days';
  DELETE FROM public._pm_secrets WHERE NOT saved AND updated_at < now() - interval '1 day';
END $pmtick$;
REVOKE ALL ON FUNCTION public._pm_tick() FROM PUBLIC, anon, authenticated;

-- Settings saved: a connection whose destination is now there is kept; one
-- whose destination was removed (or is now another kind) is deleted, with
-- anything still waiting to be sent to it.
CREATE OR REPLACE FUNCTION public._pm_settings_changed() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog, pg_temp AS $pmsettings$
DECLARE v_new jsonb := CASE WHEN jsonb_typeof(NEW.password_managers -> 'destinations') = 'array' THEN NEW.password_managers -> 'destinations' ELSE '[]'::jsonb END;
BEGIN
  IF NEW.password_managers IS NOT DISTINCT FROM OLD.password_managers THEN RETURN NEW; END IF;
  UPDATE public._pm_secrets s SET saved = true
   WHERE NOT s.saved AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_new) d WHERE jsonb_typeof(d) = 'object' AND d ->> 'id' = s.dest_id AND d ->> 'kind' = s.kind);
  DELETE FROM public._pm_secrets s
   WHERE s.saved AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_new) d WHERE jsonb_typeof(d) = 'object' AND d ->> 'id' = s.dest_id AND d ->> 'kind' = s.kind);
  UPDATE public._pm_jobs j SET state = 'expired', payload = NULL, finished_at = now(),
    outcome = jsonb_build_object('ok', false, 'error', 'That password manager was removed from Settings before it was sent.')
   WHERE j.state = 'queued' AND j.kind = 'send'
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_new) d WHERE jsonb_typeof(d) = 'object' AND d ->> 'id' = j.dest_id);
  RETURN NEW;
END $pmsettings$;
REVOKE ALL ON FUNCTION public._pm_settings_changed() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS _pm_settings_changed ON public.settings;
CREATE TRIGGER _pm_settings_changed AFTER UPDATE OF password_managers ON public.settings
  FOR EACH ROW EXECUTE FUNCTION public._pm_settings_changed();

